/** Настройки игры (сохраняются в localStorage). */
import { makeAutoObservable, reaction } from "mobx";
import { setLang, type Lang } from "../core/i18n";
import type { QualityLevel } from "../engine/renderer";

const KEY = "kotoverse.settings.v1";

export class SettingsStore {
  lang: Lang = "ru";
  quality: QualityLevel = "medium";
  sfx = 0.8;
  music = 0.45;
  muted = false;
  showFps = false;
  autoAim = true;
  damageNumbers = true;
  cameraShake = true;
  hudScale = 1;
  leftHanded = false;
  dayLength = 20;
  difficulty: "easy" | "normal" | "hard" = "normal";
  /** Кооператив: использовать публичные STUN-серверы для обхода NAT (иначе — только локальная сеть). */
  useStun = true;

  constructor() {
    this.load();
    makeAutoObservable(this);
    setLang(this.lang);
    reaction(
      () => JSON.stringify(this.snapshot()),
      () => this.save(),
    );
    reaction(
      () => this.lang,
      (l) => setLang(l),
    );
  }

  snapshot() {
    return {
      lang: this.lang,
      quality: this.quality,
      sfx: this.sfx,
      music: this.music,
      muted: this.muted,
      showFps: this.showFps,
      autoAim: this.autoAim,
      damageNumbers: this.damageNumbers,
      cameraShake: this.cameraShake,
      hudScale: this.hudScale,
      leftHanded: this.leftHanded,
      dayLength: this.dayLength,
      difficulty: this.difficulty,
      useStun: this.useStun,
    };
  }

  private load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) Object.assign(this, JSON.parse(raw));
      else {
        // Первый запуск: подбираем качество по устройству
        const mobile = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
        this.quality = mobile ? "low" : "medium";
        const nav = navigator.language || "ru";
        this.lang = nav.startsWith("ru") || nav.startsWith("uk") || nav.startsWith("be") || nav.startsWith("kk") ? "ru" : "en";
      }
    } catch {
      /* приватный режим и т.п. */
    }
  }

  private save() {
    try {
      localStorage.setItem(KEY, JSON.stringify(this.snapshot()));
    } catch {
      /* ignore */
    }
  }

  set<K extends keyof ReturnType<SettingsStore["snapshot"]>>(k: K, v: SettingsStore[K]) {
    (this as unknown as Record<string, unknown>)[k] = v;
  }

  get difficultyMul(): number {
    return this.difficulty === "easy" ? 0.6 : this.difficulty === "hard" ? 1.5 : 1;
  }
}
