/**
 * Процедурный мир.
 *
 * - Материк (кампания): огромный остров радиусом ~7.6 км, 100 уровней сложности от юга к северу.
 * - Бесконечный мир: сложность растёт с расстоянием от старта без ограничений.
 *
 * Мир делится на регионы 512×512: у каждого региона есть уровень, биом, имя, город (с NPC),
 * дороги к соседям и точки интереса (подземелья, лагеря, святилища, сундуки...).
 * Всё вычисляется детерминированно из seed, поэтому не требует хранения и одинаково у всех игроков.
 */
import { clamp, clamp01, lerp, smoothstep, dist, distToSegment } from "../../core/math";
import { fbm2, noise2, ridged2 } from "../../core/noise";
import { hash2, hashInts, Rng, toUnit } from "../../core/rng";
import type { Txt } from "../../core/i18n";
import type { ModeConfig } from "../types";
import { BIOMES, type BiomeId, PropKind, PROP_COLLIDER, type Biome } from "./biomes";
import { bossName, catName, dungeonName, regionName, townName } from "./names";

export const CHUNK = 32;
export const REGION = 512;
export const WATER_LEVEL = 0;
export const CONTINENT_RADIUS = 7600;
const BIOME_CELL = 300;
const CAMPAIGN_START = { x: 0, z: 4200 };

export type BuildingKind =
  | "house"
  | "houseBig"
  | "stall"
  | "well"
  | "shrine"
  | "tower"
  | "lamp"
  | "fence"
  | "tent"
  | "campfire"
  | "chest"
  | "obelisk"
  | "statue"
  | "pillar"
  | "bench"
  | "barrel"
  | "crate"
  | "waystone"
  | "fountain"
  | "clocktower"
  | "fishrack"
  | "laundry"
  | "flowerbed"
  | "dungeon_box"
  | "dungeon_cave"
  | "dungeon_crypt"
  | "dungeon_pyramid"
  | "dungeon_ice"
  | "dungeon_forge"
  | "dungeon_crystal"
  | "dungeon_factory"
  | "dungeon_rift";

export interface Building {
  kind: BuildingKind;
  x: number;
  z: number;
  y: number;
  rot: number;
  scale: number;
  color: number;
  collider: number;
}

export type NpcRole = "questgiver" | "merchant" | "smith" | "innkeeper" | "trainer" | "villager" | "guard" | "elder";

export interface NpcSpawn {
  id: string;
  role: NpcRole;
  x: number;
  z: number;
  rot: number;
  name: Txt;
  seed: number;
  townId: string;
}

export interface Town {
  id: string;
  rx: number;
  rz: number;
  x: number;
  z: number;
  h: number;
  radius: number;
  size: 0 | 1 | 2;
  name: Txt;
  buildings: Building[];
  npcs: NpcSpawn[];
}

export type PoiKind = "dungeon" | "camp" | "shrine" | "obelisk" | "treasure" | "nest" | "waystone";

export type DungeonTheme = "box" | "cave" | "crypt" | "pyramid" | "ice" | "forge" | "crystal" | "factory" | "rift";

export interface Poi {
  id: string;
  kind: PoiKind;
  x: number;
  z: number;
  h: number;
  level: number;
  seed: number;
  name: Txt;
  theme?: DungeonTheme;
  floors?: number;
  bossName?: Txt;
  buildings: Building[];
}

export interface Flatten {
  x: number;
  z: number;
  r: number;
  blend: number;
  h: number;
  kind: "town" | "poi";
  /** Тропинки от площади к домам: x0,z0,x1,z1,... */
  paths?: number[];
}

export interface Road {
  id: string;
  a: string;
  b: string;
  pts: number[]; // x0,z0,x1,z1,...
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
}

export interface Region {
  rx: number;
  rz: number;
  id: string;
  seed: number;
  level: number;
  biome: BiomeId;
  name: Txt;
  town: Town | null;
  pois: Poi[];
  flatten: Flatten[];
  /** Дороги вычисляются лениво (нужны соседи). */
  _roads: Road[] | null;
}

export interface TerrainSample {
  h: number;
  biomeA: BiomeId;
  biomeB: BiomeId;
  w: number; // вес biomeB
  road: number; // 0..1 близость к дороге
  town: number; // 0..1 внутри города (выравнивание)
  poi: number; // 0..1 внутри площадки POI
  plaza: number; // 0..1 мощёная площадь в центре города
}

export interface PropInstance {
  kind: PropKind;
  x: number;
  y: number;
  z: number;
  rot: number;
  scale: number;
  tint: number;
}

export interface Collider {
  x: number;
  z: number;
  r: number;
}

export interface SpawnPoint {
  id: number;
  x: number;
  z: number;
  size: number;
  kind: "pack" | "camp" | "elite";
  poiId?: string;
}

export interface ChunkContent {
  cx: number;
  cz: number;
  props: PropInstance[];
  buildings: Building[];
  colliders: Collider[];
  spawns: SpawnPoint[];
}

const DUNGEON_BY_BIOME: Record<BiomeId, DungeonTheme[]> = {
  meadow: ["box", "cave", "box"],
  forest: ["cave", "box", "crypt"],
  birch: ["box", "cave"],
  sakura: ["cave", "box", "crypt"],
  autumn: ["crypt", "cave", "box"],
  jungle: ["pyramid", "cave"],
  savanna: ["cave", "pyramid", "box"],
  desert: ["pyramid", "pyramid", "box", "factory"],
  swamp: ["crypt", "cave"],
  taiga: ["cave", "ice"],
  snow: ["ice", "ice", "cave"],
  mountain: ["cave", "ice", "factory", "forge"],
  beach: ["cave", "box"],
  volcanic: ["forge", "forge", "cave"],
  crystal: ["crystal", "crystal", "factory"],
  shadow: ["crypt", "crypt", "rift"],
  void: ["rift", "rift", "crystal"],
  candy: ["box", "box", "cave"],
};

export class WorldGen {
  readonly seed: number;
  readonly mode: ModeConfig;
  readonly infinite: boolean;
  readonly start: { x: number; z: number };
  private regions = new Map<number, Region>();
  private cellBiomes = new Map<number, BiomeId>();
  private sH: number;
  private sM: number;
  private sR: number;
  private sD: number;
  private sL: number;
  private sT: number;
  private sW: number;
  private sC: number;

  constructor(seed: number, mode: ModeConfig) {
    this.seed = seed >>> 0;
    this.mode = mode;
    this.infinite = mode.world === "infinite";
    const r = new Rng(this.seed);
    this.sH = r.id();
    this.sM = r.id();
    this.sR = r.id();
    this.sD = r.id();
    this.sL = r.id();
    this.sT = r.id();
    this.sW = r.id();
    this.sC = r.id();
    this.start = this.findStart();
  }

  // ───────────────────────── поля ─────────────────────────

  /** 1 — суша материка, 0 — открытый океан. */
  continentMask(x: number, z: number): number {
    if (this.infinite) return 1;
    const r0 = Math.sqrt(x * x + z * z);
    if (r0 < CONTINENT_RADIUS * 0.72 - 700) return 1;
    if (r0 > CONTINENT_RADIUS * 0.98 + 700) return 0;
    const wx = x + fbm2(x / 2200, z / 2200, this.sC, 3) * 900;
    const wz = z + fbm2(x / 2200 + 17.3, z / 2200 - 9.1, this.sC + 1, 3) * 900;
    const r = Math.sqrt(wx * wx + wz * wz);
    return 1 - smoothstep(CONTINENT_RADIUS * 0.72, CONTINENT_RADIUS * 0.98, r);
  }

  /** Непрерывный уровень сложности в точке. */
  levelAt(x: number, z: number): number {
    const warp = fbm2(x / 1800, z / 1800, this.sL, 2) * 350;
    if (!this.infinite) {
      const d = dist(x, z, this.start.x, this.start.z) + warp;
      const t = clamp((d - 220) / 8600, 0, 1);
      return 1 + 99 * Math.pow(t, 1.05);
    }
    const d = Math.max(0, dist(x, z, this.start.x, this.start.z) + warp - 220);
    const lvl = 1 + d / 150;
    return this.mode.levels === "capped" ? Math.min(100, lvl) : lvl;
  }

  climate(x: number, z: number): { t: number; m: number } {
    let t = 0.55 + fbm2(x / 3200, z / 3200, this.sT, 3) * 0.55;
    if (!this.infinite) {
      const north = clamp01((this.start.z - z) / 11000);
      t -= north * 0.3;
    }
    const m = 0.5 + fbm2(x / 2600 + 91.7, z / 2600 - 33.1, this.sT + 7, 3) * 0.6;
    return { t: clamp01(t), m: clamp01(m) };
  }

  private mountainMask(x: number, z: number): number {
    return smoothstep(0.12, 0.5, fbm2(x / 2600, z / 2600, this.sM, 3));
  }

  /** Биом ячейки Вороного (ячейка ~300 ед.). */
  private cellBiome(ix: number, iz: number): BiomeId {
    const key = (ix + 40000) * 80000 + (iz + 40000);
    const cached = this.cellBiomes.get(key);
    if (cached) return cached;
    const h = hash2(ix, iz, this.sW);
    const cx = (ix + toUnit(h) * 0.8 + 0.1) * BIOME_CELL;
    const cz = (iz + toUnit(hash2(iz, ix, this.sW + 3)) * 0.8 + 0.1) * BIOME_CELL;
    const b = this.pickBiome(cx, cz, toUnit(hash2(ix, iz, this.sW + 11)));
    if (this.cellBiomes.size > 20000) this.cellBiomes.clear();
    this.cellBiomes.set(key, b);
    return b;
  }

  private pickBiome(x: number, z: number, roll: number): BiomeId {
    const dStart = dist(x, z, this.start.x, this.start.z);
    if (dStart < 700) return roll < 0.7 ? "meadow" : "birch";
    const lvl = this.levelAt(x, z);
    const { t, m } = this.climate(x, z);
    const mask = this.continentMask(x, z);
    // Экзотические биомы появляются с ростом сложности.
    const exotic = this.infinite ? smoothstep(35, 160, lvl) * 0.65 : smoothstep(55, 92, lvl) * 0.85;
    const roll2 = toUnit(hashInts(Math.floor(x), Math.floor(z), this.sW));
    if (roll < exotic) {
      if (lvl > (this.infinite ? 120 : 88) && roll2 < 0.45) return "void";
      if (t > 0.6) return "volcanic";
      if (m > 0.55) return "shadow";
      return roll2 < 0.5 ? "crystal" : "shadow";
    }
    if (roll > 0.975 && lvl > 12) return "candy";
    if (this.mountainMask(x, z) > 0.75 && roll2 < 0.8) return t < 0.3 ? "snow" : "mountain";
    if (!this.infinite && mask < 0.55 && t > 0.45) return "beach";
    if (t < 0.22) return "snow";
    if (t < 0.36) return m > 0.45 ? "taiga" : "snow";
    if (t < 0.62) {
      if (m > 0.74) return "swamp";
      if (m > 0.55) return roll2 < 0.6 ? "forest" : "autumn";
      if (m > 0.4) return roll2 < 0.5 ? "birch" : roll2 < 0.8 ? "autumn" : "forest";
      return roll2 < 0.8 ? "meadow" : "sakura";
    }
    if (t < 0.8) {
      if (m > 0.68) return "jungle";
      if (m > 0.5) return roll2 < 0.55 ? "sakura" : "meadow";
      if (m > 0.32) return "savanna";
      return "desert";
    }
    if (m > 0.62) return "jungle";
    if (m > 0.36) return "savanna";
    return "desert";
  }

  /** Два ближайших биома и вес смешивания. */
  biomeAt(x: number, z: number, out: { a: BiomeId; b: BiomeId; w: number }): void {
    const wx = x + noise2(x / 190, z / 190, this.sW + 5) * 70;
    const wz = z + noise2(x / 190 + 5.2, z / 190 + 1.3, this.sW + 6) * 70;
    const gx = wx / BIOME_CELL;
    const gz = wz / BIOME_CELL;
    const ix = Math.floor(gx);
    const iz = Math.floor(gz);
    let d1 = 1e9,
      d2 = 1e9,
      c1x = 0,
      c1z = 0,
      c2x = 0,
      c2z = 0;
    for (let j = -1; j <= 1; j++) {
      for (let i = -1; i <= 1; i++) {
        const cx = ix + i;
        const cz = iz + j;
        const px = cx + toUnit(hash2(cx, cz, this.sW)) * 0.8 + 0.1;
        const pz = cz + toUnit(hash2(cz, cx, this.sW + 3)) * 0.8 + 0.1;
        const d = (px - gx) * (px - gx) + (pz - gz) * (pz - gz);
        if (d < d1) {
          d2 = d1;
          c2x = c1x;
          c2z = c1z;
          d1 = d;
          c1x = cx;
          c1z = cz;
        } else if (d < d2) {
          d2 = d;
          c2x = cx;
          c2z = cz;
        }
      }
    }
    const a = this.cellBiome(c1x, c1z);
    const b = this.cellBiome(c2x, c2z);
    out.a = a;
    out.b = b;
    if (a === b) {
      out.w = 0;
      return;
    }
    const edge = (Math.sqrt(d2) - Math.sqrt(d1)) * BIOME_CELL;
    out.w = 0.5 * (1 - smoothstep(0, 60, edge));
  }

  private tmpBiome = { a: "meadow" as BiomeId, b: "meadow" as BiomeId, w: 0 };

  /** «Сырая» высота без выравнивания под города и дороги. */
  rawHeight(x: number, z: number, bio?: { a: BiomeId; b: BiomeId; w: number }): number {
    if (!bio) {
      bio = this.tmpBiome;
      this.biomeAt(x, z, bio);
    }
    const A = BIOMES[bio.a];
    const B = BIOMES[bio.b];
    const relief = lerp(A.relief, B.relief, bio.w);
    const lift = lerp(A.lift, B.lift, bio.w);
    const hills = fbm2(x / 520, z / 520, this.sH, 4) * 13;
    const detail = fbm2(x / 45, z / 45, this.sD, 2) * 1.3;
    const mm = this.mountainMask(x, z);
    let mountains = 0;
    if (mm > 0.001) {
      const rg = ridged2(x / 420, z / 420, this.sR, 4);
      mountains = mm * rg * rg * 95 * (0.55 + 0.45 * Math.min(1.6, relief));
    }
    let h = 5 + lift + relief * (hills + detail) + mountains;
    // Озёра
    const lake = fbm2(x / 900 + 3.3, z / 900 - 7.7, this.sL + 9, 3);
    const lk = smoothstep(-0.32, -0.55, lake);
    if (lk > 0) h = lerp(h, -7 + detail, lk);
    // Океан вокруг материка
    if (!this.infinite) {
      const cm = this.continentMask(x, z);
      h = lerp(-28 + detail * 2, h, cm);
    }
    // Старт всегда на суше и пологий
    const ds = dist(x, z, this.start ? this.start.x : 0, this.start ? this.start.z : 0);
    if (this.start && ds < 420) {
      const k = 1 - smoothstep(180, 420, ds);
      h = lerp(h, Math.max(h, 4) * 0.6 + 2.5, k);
    }
    return h;
  }

  private findStart(): { x: number; z: number } {
    // Временное значение, чтобы rawHeight() не обращался к undefined.
    (this as { start: { x: number; z: number } }).start = this.infinite ? { x: 0, z: 0 } : { ...CAMPAIGN_START };
    const base = this.start;
    const rng = new Rng(hashInts(this.seed, 777));
    let best = { x: base.x, z: base.z };
    let bestScore = -1e9;
    for (let i = 0; i < 40; i++) {
      const ang = rng.next() * Math.PI * 2;
      const r = i === 0 ? 0 : rng.range(0, 250);
      const x = base.x + Math.cos(ang) * r;
      const z = base.z + Math.sin(ang) * r;
      const h = this.rawHeight(x, z);
      const s = h > 2 ? 10 - Math.abs(h - 6) - r / 100 : -100;
      if (s > bestScore) {
        bestScore = s;
        best = { x, z };
      }
    }
    return best;
  }

  // ───────────────────────── регионы ─────────────────────────

  private regionKey(rx: number, rz: number): number {
    return (rx + 32768) * 65536 + (rz + 32768);
  }

  regionAt(x: number, z: number): Region {
    return this.region(Math.floor(x / REGION), Math.floor(z / REGION));
  }

  region(rx: number, rz: number): Region {
    const key = this.regionKey(rx, rz);
    let r = this.regions.get(key);
    if (r) return r;
    r = this.buildRegion(rx, rz);
    if (this.regions.size > 600) {
      // Простейшая очистка кэша: удаляем самые старые записи.
      let n = 0;
      for (const k of this.regions.keys()) {
        this.regions.delete(k);
        if (++n > 200) break;
      }
    }
    this.regions.set(key, r);
    return r;
  }

  /** Находит город/POI по id (например, для квестов). */
  regionById(id: string): Region | null {
    const m = /^r(-?\d+)_(-?\d+)$/.exec(id);
    if (!m) return null;
    return this.region(parseInt(m[1]), parseInt(m[2]));
  }

  private buildRegion(rx: number, rz: number): Region {
    const seed = hashInts(this.seed, rx, rz, 0x5e61);
    const rng = new Rng(seed);
    const id = `r${rx}_${rz}`;
    const x0 = rx * REGION;
    const z0 = rz * REGION;
    const cx = x0 + REGION / 2;
    const cz = z0 + REGION / 2;
    const bio = { a: "meadow" as BiomeId, b: "meadow" as BiomeId, w: 0 };

    // Ищем место для города.
    let town: Town | null = null;
    let best: { x: number; z: number; h: number; score: number } | null = null;
    const containsStart =
      this.start.x >= x0 && this.start.x < x0 + REGION && this.start.z >= z0 && this.start.z < z0 + REGION;
    for (let i = 0; i < 14; i++) {
      let x: number, z: number;
      if (containsStart && i === 0) {
        x = clamp(this.start.x, x0 + 110, x0 + REGION - 110);
        z = clamp(this.start.z, z0 + 110, z0 + REGION - 110);
      } else {
        x = x0 + 120 + rng.next() * (REGION - 240);
        z = z0 + 120 + rng.next() * (REGION - 240);
      }
      const h = this.rawHeight(x, z);
      if (h < 2.2) continue;
      const hs = [this.rawHeight(x + 20, z), this.rawHeight(x - 20, z), this.rawHeight(x, z + 20), this.rawHeight(x, z - 20)];
      let rough = 0;
      let wet = 0;
      for (const v of hs) {
        rough += Math.abs(v - h);
        if (v < 1) wet++;
      }
      if (wet > 1) continue;
      const score = -rough - dist(x, z, cx, cz) / 60 - Math.max(0, h - 30) * 0.5 + (containsStart && i === 0 ? 100 : 0);
      if (!best || score > best.score) best = { x, z, h, score };
    }

    const level = Math.max(1, Math.round(this.levelAt(best ? best.x : cx, best ? best.z : cz)));
    this.biomeAt(best ? best.x : cx, best ? best.z : cz, bio);
    const biome = bio.w > 0.5 ? bio.b : bio.a;
    const dark = BIOMES[biome].mood === "dark";
    const name = regionName(rng.fork("name"), biome, dark);
    const flatten: Flatten[] = [];
    const pois: Poi[] = [];

    if (best) {
      const size: 0 | 1 | 2 = containsStart ? 1 : rng.chance(0.12) ? 2 : rng.chance(0.45) ? 1 : 0;
      const radius = [24, 34, 44][size];
      const th = Math.max(2.5, best.h);
      town = this.buildTown(id, rx, rz, best.x, best.z, th, radius, size, rng.fork("town"), biome);
      const paths: number[] = [];
      for (const b of town.buildings) {
        if (b.kind !== "house" && b.kind !== "houseBig") continue;
        const fx = Math.sin(b.rot),
          fz = Math.cos(b.rot);
        const off = b.kind === "houseBig" ? 3.4 : 2.6;
        paths.push(best.x + (b.x - best.x) * 0.25, best.z + (b.z - best.z) * 0.25, b.x + fx * off, b.z + fz * off);
      }
      flatten.push({ x: best.x, z: best.z, r: radius, blend: 34, h: th, kind: "town", paths });
    }

    // Точки интереса
    const poiRng = rng.fork("poi");
    const landish = best != null;
    if (landish || this.infinite) {
      const plan: PoiKind[] = [];
      const nDungeons = poiRng.int(1, 3);
      for (let i = 0; i < nDungeons; i++) plan.push("dungeon");
      const nCamps = poiRng.int(2, 4);
      for (let i = 0; i < nCamps; i++) plan.push("camp");
      if (poiRng.chance(0.7)) plan.push("shrine");
      const nObel = poiRng.int(0, 2);
      for (let i = 0; i < nObel; i++) plan.push("obelisk");
      const nTreasure = poiRng.int(1, 3);
      for (let i = 0; i < nTreasure; i++) plan.push("treasure");
      if (poiRng.chance(0.65)) plan.push("nest");
      if (poiRng.chance(0.5)) plan.push("waystone");
      let idx = 0;
      for (const kind of plan) {
        for (let attempt = 0; attempt < 10; attempt++) {
          const x = x0 + 60 + poiRng.next() * (REGION - 120);
          const z = z0 + 60 + poiRng.next() * (REGION - 120);
          if (town && dist(x, z, town.x, town.z) < town.radius + 70) continue;
          let clash = false;
          for (const p of pois) if (dist(x, z, p.x, p.z) < 70) clash = true;
          if (clash) continue;
          this.biomeAt(x, z, bio);
          const h = this.rawHeight(x, z, bio);
          if (h < 1.5) continue;
          const hx = this.rawHeight(x + 8, z, bio);
          const hz = this.rawHeight(x, z + 8, bio);
          if (Math.abs(hx - h) + Math.abs(hz - h) > 7) continue;
          const pb = bio.w > 0.5 ? bio.b : bio.a;
          const lv = Math.max(1, Math.round(this.levelAt(x, z)));
          const poi = this.buildPoi(`${id}:p${idx++}`, kind, x, z, h, lv, pb, poiRng.fork(idx));
          pois.push(poi);
          const fr = kind === "dungeon" ? 11 : kind === "camp" ? 12 : 6;
          flatten.push({ x, z, r: fr, blend: 12, h, kind: "poi" });
          break;
        }
      }
    }

    return { rx, rz, id, seed, level, biome, name, town, pois, flatten, _roads: null };
  }

  private buildTown(
    regionId: string,
    rx: number,
    rz: number,
    x: number,
    z: number,
    h: number,
    radius: number,
    size: 0 | 1 | 2,
    rng: Rng,
    biome: BiomeId,
  ): Town {
    const id = `${regionId}:t`;
    const buildings: Building[] = [];
    const npcs: NpcSpawn[] = [];
    const wall = [0xe8d8b8, 0xd8c09a, 0xf0e6d0, 0xc9a27a, 0xe0c8a8, 0xbfd0e0][rng.int(0, 5)];
    const roofs = [0xc0503a, 0x8a4a3a, 0x3a6aa0, 0x4a8a4a, 0x9a5ab0, 0xd08a3a];
    const add = (kind: BuildingKind, bx: number, bz: number, rot: number, scale = 1, color = 0xffffff, collider = 0) =>
      buildings.push({ kind, x: bx, z: bz, y: h, rot, scale, color, collider });

    // Центральная площадь: путевой камень-портал и колодец
    add("waystone", x, z, 0, 1, 0x8fd0ff, 1.4);
    add("well", x + 7, z - 5, rng.next() * 6, 1, wall, 1.6);
    const nHouses = [5, 8, 12][size];
    const special: NpcRole[] = ["merchant", "innkeeper", "elder"];
    if (size >= 1) special.push("smith", "trainer");
    let placed = 0;
    for (let ring = 0; ring < 2 && placed < nHouses; ring++) {
      const rr = ring === 0 ? radius * 0.55 : radius * 0.88;
      const count = ring === 0 ? Math.min(nHouses, 5 + size) : nHouses - placed;
      const off = rng.next() * Math.PI * 2;
      for (let i = 0; i < count; i++) {
        const a = off + (i / count) * Math.PI * 2 + rng.range(-0.15, 0.15);
        const bx = x + Math.cos(a) * rr;
        const bz = z + Math.sin(a) * rr;
        const rot = Math.atan2(x - bx, z - bz);
        const big = rng.chance(0.25 + size * 0.1);
        add(big ? "houseBig" : "house", bx, bz, rot, rng.range(0.9, 1.15), wall | 0, big ? 4.2 : 3.2);
        buildings[buildings.length - 1].color = roofs[rng.int(0, roofs.length - 1)];
        placed++;
      }
    }
    // Лавки, фонари, лавочки, кошачьи башни
    const nStalls = 1 + size;
    for (let i = 0; i < nStalls; i++) {
      const a = rng.next() * Math.PI * 2;
      const r = radius * 0.32;
      add("stall", x + Math.cos(a) * r, z + Math.sin(a) * r, Math.atan2(-Math.cos(a), -Math.sin(a)), 1, roofs[rng.int(0, 5)], 1.6);
    }
    const nLamps = 4 + size * 3;
    for (let i = 0; i < nLamps; i++) {
      const a = (i / nLamps) * Math.PI * 2;
      const r = radius * 0.72;
      add("lamp", x + Math.cos(a) * r, z + Math.sin(a) * r, 0, 1, 0xffd27a, 0.25);
    }
    for (let i = 0; i < 1 + size; i++) {
      const a = rng.next() * Math.PI * 2;
      const r = rng.range(radius * 0.4, radius * 0.8);
      add("tower", x + Math.cos(a) * r, z + Math.sin(a) * r, rng.next() * 6, rng.range(0.9, 1.3), 0xc8a070, 0.9);
    }
    for (let i = 0; i < 2 + size * 2; i++) {
      const a = rng.next() * Math.PI * 2;
      const r = rng.range(radius * 0.2, radius * 0.5);
      add(rng.chance(0.5) ? "bench" : rng.chance(0.5) ? "barrel" : "crate", x + Math.cos(a) * r, z + Math.sin(a) * r, rng.next() * 6, 1, 0x9a6a3a, 0.5);
    }
    if (size >= 1) add("statue", x - 6, z + 6, rng.next() * 6, 1 + size * 0.2, 0xd8d8d0, 1.2);

    // NPC
    const npcRng = rng.fork("npc");
    let n = 0;
    const mkNpc = (role: NpcRole, nx: number, nz: number) => {
      npcs.push({
        id: `${id}:n${n++}`,
        role,
        x: nx,
        z: nz,
        rot: Math.atan2(x - nx, z - nz),
        name: catName(npcRng),
        seed: npcRng.id(),
        townId: id,
      });
    };
    const nQuest = [2, 3, 4][size];
    for (let i = 0; i < nQuest; i++) {
      const a = (i / nQuest) * Math.PI * 2 + 0.4;
      mkNpc("questgiver", x + Math.cos(a) * 9, z + Math.sin(a) * 9);
    }
    for (const role of special) {
      const a = npcRng.next() * Math.PI * 2;
      mkNpc(role, x + Math.cos(a) * radius * 0.4, z + Math.sin(a) * radius * 0.4);
    }
    const nGuards = 1 + size;
    for (let i = 0; i < nGuards; i++) {
      const a = npcRng.next() * Math.PI * 2;
      mkNpc("guard", x + Math.cos(a) * radius * 0.95, z + Math.sin(a) * radius * 0.95);
    }
    const nVill = [3, 5, 8][size];
    for (let i = 0; i < nVill; i++) {
      const a = npcRng.next() * Math.PI * 2;
      const r = npcRng.range(4, radius * 0.8);
      mkNpc("villager", x + Math.cos(a) * r, z + Math.sin(a) * r);
    }
    const name = townName(rng.fork("tn"));
    this.decorateTown(x, z, radius, size, buildings, npcs, rng.fork("deco"), add);
    return { id, rx, rz, x, z, h, radius, size, name, buildings, npcs };
  }

  /**
   * Уют города: фонтан с рыбой, часовая башня, сушилки рыбы, клумбы у домов, бельё между домами.
   * Отдельный поток случайных чисел, чтобы не сдвигать раскладку домов и жителей.
   */
  private decorateTown(
    x: number,
    z: number,
    radius: number,
    size: 0 | 1 | 2,
    buildings: Building[],
    npcs: NpcSpawn[],
    rng: Rng,
    add: (kind: BuildingKind, bx: number, bz: number, rot: number, scale?: number, color?: number, collider?: number) => void,
  ) {
    const houses = buildings.filter((b) => b.kind === "house" || b.kind === "houseBig");
    // Точка появления игрока в городе (см. GameSession) должна оставаться свободной
    const spawnX = x + 3,
      spawnZ = z + 6;
    const free = (px: number, pz: number, r: number) =>
      buildings.every((b) => Math.hypot(px - b.x, pz - b.z) > b.collider * b.scale + r + 0.8) &&
      npcs.every((n) => Math.hypot(px - n.x, pz - n.z) > r + 1.2) &&
      Math.hypot(px - spawnX, pz - spawnZ) > r + 2.5;
    const place = (kind: BuildingKind, r0: number, r1: number, col: number, tries = 12, color = 0xffffff) => {
      for (let k = 0; k < tries; k++) {
        const a = rng.next() * Math.PI * 2;
        const rr = rng.range(r0, r1);
        const px = x + Math.cos(a) * rr,
          pz = z + Math.sin(a) * rr;
        if (!free(px, pz, col)) continue;
        add(kind, px, pz, Math.atan2(x - px, z - pz), 1, color, col);
        return true;
      }
      return false;
    };
    if (size >= 1) place("fountain", radius * 0.2, radius * 0.3, 2.4);
    if (size >= 2) place("clocktower", radius * 0.38, radius * 0.5, 2.3);
    for (let i = 0; i < 1 + size; i++) place("fishrack", radius * 0.3, radius * 0.55, 1.2);
    // Клумбы по бокам от входа
    for (const hb of houses) {
      if (!rng.chance(0.6)) continue;
      const big = hb.kind === "houseBig";
      const side = rng.chance(0.5) ? 1 : -1;
      const lx = side * (big ? 3.6 : 3.1),
        lz = big ? 3.2 : 2.6;
      const c = Math.cos(hb.rot),
        sn = Math.sin(hb.rot);
      const px = hb.x + c * lx + sn * lz,
        pz = hb.z - sn * lx + c * lz;
      if (buildings.every((b) => b === hb || Math.hypot(px - b.x, pz - b.z) > b.collider * b.scale + 1.4)) add("flowerbed", px, pz, hb.rot, 1, 0xffffff, 0.6);
    }
    // Бельё на верёвке между соседними домами внешнего кольца
    const ring = houses.filter((b) => Math.hypot(b.x - x, b.z - z) > radius * 0.7).sort((a, b) => Math.atan2(a.z - z, a.x - x) - Math.atan2(b.z - z, b.x - x));
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i],
        b = ring[(i + 1) % ring.length];
      const d = Math.hypot(a.x - b.x, a.z - b.z);
      if (d < 9 || d > 17 || !rng.chance(0.55)) continue;
      const mx = (a.x + b.x) / 2,
        mz = (a.z + b.z) / 2;
      // Чуть наружу от центра, чтобы не перегораживать проход
      const ox = mx - x,
        oz = mz - z;
      const ol = Math.hypot(ox, oz) || 1;
      const px = mx + (ox / ol) * 2.5,
        pz = mz + (oz / ol) * 2.5;
      // Верёвка идёт вдоль локальной оси X меша: поворот, при котором X смотрит от дома a к дому b
      add("laundry", px, pz, Math.atan2(a.z - b.z, b.x - a.x), 1, 0xffffff, 0);
    }
  }

  private buildPoi(id: string, kind: PoiKind, x: number, z: number, h: number, level: number, biome: BiomeId, rng: Rng): Poi {
    const buildings: Building[] = [];
    const add = (k: BuildingKind, bx: number, bz: number, rot: number, scale = 1, color = 0xffffff, collider = 0) =>
      buildings.push({ kind: k, x: bx, z: bz, y: h, rot, scale, color, collider });
    const seed = rng.id();
    let name: Txt = { ru: "", en: "" };
    let theme: DungeonTheme | undefined;
    let floors: number | undefined;
    let boss: Txt | undefined;
    switch (kind) {
      case "dungeon": {
        theme = rng.pick(DUNGEON_BY_BIOME[biome]);
        name = dungeonName(rng, theme);
        floors = clamp(1 + Math.floor(level / 25) + rng.int(0, 2), 1, 6);
        boss = bossName(rng);
        const rot = rng.next() * Math.PI * 2;
        add(`dungeon_${theme}` as BuildingKind, x, z, rot, 1, 0xffffff, 0);
        break;
      }
      case "camp": {
        name = { ru: "Лагерь", en: "Camp" };
        add("campfire", x, z, 0, 1, 0xff8a3a, 0.8);
        const n = rng.int(2, 4);
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2 + rng.next();
          add("tent", x + Math.cos(a) * 7, z + Math.sin(a) * 7, Math.atan2(-Math.cos(a), -Math.sin(a)), rng.range(0.9, 1.2), [0x8a5a3a, 0x6a7a4a, 0x9a4a4a][rng.int(0, 2)], 2.0);
        }
        add("chest", x + 3, z + 2, rng.next() * 6, 1, 0xb8863a, 0.6);
        break;
      }
      case "shrine":
        name = { ru: "Святилище", en: "Shrine" };
        add("shrine", x, z, rng.next() * 6, 1, [0x8fd0ff, 0xffd27a, 0xd08fff, 0x8fffb0][rng.int(0, 3)], 1.5);
        break;
      case "obelisk":
        name = { ru: "Камень памяти", en: "Memory stone" };
        add("obelisk", x, z, rng.next() * 6, rng.range(0.9, 1.3), 0xb8c0d0, 1.0);
        break;
      case "treasure":
        name = { ru: "Тайник", en: "Stash" };
        add("chest", x, z, rng.next() * 6, 1, 0xd8a03a, 0.6);
        for (let i = 0; i < 3; i++) {
          const a = rng.next() * Math.PI * 2;
          add("pillar", x + Math.cos(a) * 4, z + Math.sin(a) * 4, rng.next() * 6, rng.range(0.6, 1.1), 0xa8a8a0, 0.7);
        }
        break;
      case "nest":
        name = { ru: "Логово", en: "Lair" };
        boss = bossName(rng);
        for (let i = 0; i < 5; i++) {
          const a = (i / 5) * Math.PI * 2;
          add("pillar", x + Math.cos(a) * 8, z + Math.sin(a) * 8, rng.next() * 6, rng.range(0.8, 1.4), 0x8a8078, 0.8);
        }
        break;
      case "waystone":
        name = { ru: "Путевой камень", en: "Waystone" };
        add("waystone", x, z, 0, 1, 0x8fd0ff, 1.4);
        break;
    }
    return { id, kind, x, z, h, level, seed, name, theme, floors, bossName: boss, buildings };
  }

  /** Дороги региона (к соседям на востоке и юге + приходящие с запада и севера). */
  roadsOf(r: Region): Road[] {
    if (r._roads) return r._roads;
    const roads: Road[] = [];
    const tryRoad = (a: Region, b: Region) => {
      if (!a.town || !b.town) return;
      const road = this.makeRoad(a.town, b.town);
      if (road) roads.push(road);
    };
    tryRoad(r, this.region(r.rx + 1, r.rz));
    tryRoad(r, this.region(r.rx, r.rz + 1));
    tryRoad(this.region(r.rx - 1, r.rz), r);
    tryRoad(this.region(r.rx, r.rz - 1), r);
    r._roads = roads;
    return roads;
  }

  private makeRoad(a: Town, b: Town): Road | null {
    const d = dist(a.x, a.z, b.x, b.z);
    if (d > REGION * 1.6) return null;
    const rng = new Rng(hashInts(this.seed, a.rx, a.rz, b.rx, b.rz, 0x70ad));
    const nx = -(b.z - a.z) / d;
    const nz = (b.x - a.x) / d;
    const bend = rng.range(-50, 50);
    const wob = rng.range(10, 22);
    const ph = rng.next() * 6;
    const pts: number[] = [];
    const N = 14;
    let minX = 1e18,
      maxX = -1e18,
      minZ = 1e18,
      maxZ = -1e18;
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const off = Math.sin(Math.PI * t) * bend + Math.sin(t * 9 + ph) * wob * Math.sin(Math.PI * t);
      const px = lerp(a.x, b.x, t) + nx * off;
      const pz = lerp(a.z, b.z, t) + nz * off;
      pts.push(px, pz);
      minX = Math.min(minX, px);
      maxX = Math.max(maxX, px);
      minZ = Math.min(minZ, pz);
      maxZ = Math.max(maxZ, pz);
    }
    return { id: `${a.id}>${b.id}`, a: a.id, b: b.id, pts, minX, maxX, minZ, maxZ };
  }

  /** Расстояние до ближайшей дороги (по дорогам региона точки). */
  roadDistance(x: number, z: number, r?: Region): number {
    r = r ?? this.regionAt(x, z);
    const roads = this.roadsOf(r);
    let best = 1e9;
    for (const road of roads) {
      if (x < road.minX - 12 || x > road.maxX + 12 || z < road.minZ - 12 || z > road.maxZ + 12) continue;
      const p = road.pts;
      for (let i = 0; i + 3 < p.length; i += 2) {
        const d = distToSegment(x, z, p[i], p[i + 1], p[i + 2], p[i + 3]);
        if (d < best) best = d;
      }
    }
    return best;
  }

  // ───────────────────────── итоговая высота ─────────────────────────

  private tmpSample: TerrainSample = { h: 0, biomeA: "meadow", biomeB: "meadow", w: 0, road: 0, town: 0, poi: 0, plaza: 0 };

  /** Полная выборка: высота + биом + дороги (для генерации чанков). */
  sample(x: number, z: number, out: TerrainSample = this.tmpSample): TerrainSample {
    const bio = this.tmpBiome;
    this.biomeAt(x, z, bio);
    let h = this.rawHeight(x, z, bio);
    const r = this.regionAt(x, z);
    let town = 0;
    let poi = 0;
    let plaza = 0;
    let road = 0;
    for (const f of r.flatten) {
      const dx = x - f.x;
      const dz = z - f.z;
      const d2 = dx * dx + dz * dz;
      const outer = f.r + f.blend;
      if (d2 > outer * outer) continue;
      const d = Math.sqrt(d2);
      const k = 1 - smoothstep(f.r, outer, d);
      h = lerp(h, f.h, k);
      if (f.kind === "town") {
        if (k > town) town = k;
        const pz = 1 - smoothstep(f.r * 0.3, f.r * 0.42, d + noise2(x * 0.15, z * 0.15, 77) * 2.5);
        if (pz > plaza) plaza = pz;
        if (f.paths && d < f.r + 4) {
          const p = f.paths;
          for (let i = 0; i < p.length; i += 4) {
            const pd = distToSegment(x, z, p[i], p[i + 1], p[i + 2], p[i + 3]);
            const pr = 1 - smoothstep(0.6, 1.5, pd);
            if (pr > road) road = pr;
          }
        }
      } else if (k > poi) poi = k;
    }
    const rd = this.roadDistance(x, z, r);
    if (rd < 6) {
      road = Math.max(road, 1 - smoothstep(1.6, 4.2, rd));
      if (h < 0.7) h = lerp(h, 0.7, 1 - smoothstep(3, 6, rd));
    }
    out.h = h;
    out.biomeA = bio.a;
    out.biomeB = bio.b;
    out.w = bio.w;
    out.road = road;
    out.town = town;
    out.poi = poi;
    out.plaza = plaza;
    return out;
  }

  height(x: number, z: number): number {
    return this.sample(x, z).h;
  }

  biomeIdAt(x: number, z: number): BiomeId {
    const b = this.tmpBiome;
    this.biomeAt(x, z, b);
    return b.w > 0.5 ? b.b : b.a;
  }

  // ───────────────────────── содержимое чанка ─────────────────────────

  chunkContent(cx: number, cz: number): ChunkContent {
    const x0 = cx * CHUNK;
    const z0 = cz * CHUNK;
    const props: PropInstance[] = [];
    const colliders: Collider[] = [];
    const buildings: Building[] = [];
    const spawns: SpawnPoint[] = [];
    const region = this.regionAt(x0 + CHUNK / 2, z0 + CHUNK / 2);
    const s: TerrainSample = { h: 0, biomeA: "meadow", biomeB: "meadow", w: 0, road: 0, town: 0, poi: 0, plaza: 0 };

    // Постройки (города и POI), попадающие в этот чанк.
    const inChunk = (b: Building) => b.x >= x0 && b.x < x0 + CHUNK && b.z >= z0 && b.z < z0 + CHUNK;
    const collectFrom = (reg: Region) => {
      if (reg.town) for (const b of reg.town.buildings) if (inChunk(b)) buildings.push(b);
      for (const p of reg.pois) for (const b of p.buildings) if (inChunk(b)) buildings.push(b);
    };
    collectFrom(region);
    for (const b of buildings) if (b.collider > 0) colliders.push({ x: b.x, z: b.z, r: b.collider * b.scale });

    // Пропы на джиттер-сетке.
    const CELL = 3.2;
    const n = Math.round(CHUNK / CELL);
    const seed = hashInts(this.seed, cx, cz, 0x9a0b);
    for (let j = 0; j < n; j++) {
      for (let i = 0; i < n; i++) {
        const hh = hashInts(seed, i, j);
        const r0 = toUnit(hh);
        const px = x0 + (i + 0.15 + toUnit(hashInts(hh, 1)) * 0.7) * CELL;
        const pz = z0 + (j + 0.15 + toUnit(hashInts(hh, 2)) * 0.7) * CELL;
        this.sample(px, pz, s);
        const biome: Biome = BIOMES[toUnit(hashInts(hh, 3)) < s.w ? s.biomeB : s.biomeA];
        if (r0 > biome.density) continue;
        if (s.h < 0.4 || s.town > 0.05 || s.poi > 0.3 || s.road > 0.02) continue;
        const rule = pickRule(biome, toUnit(hashInts(hh, 4)));
        if (!rule) continue;
        const scale = lerp(rule.scale[0], rule.scale[1], toUnit(hashInts(hh, 5)));
        const tint = rule.tints ? rule.tints[hashInts(hh, 6) % rule.tints.length] : 0xffffff;
        const rot = toUnit(hashInts(hh, 7)) * Math.PI * 2;
        props.push({ kind: rule.kind, x: px, y: s.h, z: pz, rot, scale, tint });
        const cr = PROP_COLLIDER[rule.kind];
        if (cr > 0) colliders.push({ x: px, z: pz, r: cr * scale });
      }
    }

    // Точки появления врагов.
    const sh = hashInts(this.seed, cx, cz, 0x5fa0);
    const packs = toUnit(sh) < 0.55 ? 1 : toUnit(sh) < 0.8 ? 0 : 2;
    for (let i = 0; i < packs; i++) {
      const hx = hashInts(sh, i, 1);
      const x = x0 + 4 + toUnit(hx) * (CHUNK - 8);
      const z = z0 + 4 + toUnit(hashInts(hx, 2)) * (CHUNK - 8);
      this.sample(x, z, s);
      if (s.h < 0.5 || s.town > 0 || s.road > 0.3) continue;
      if (region.town && dist(x, z, region.town.x, region.town.z) < region.town.radius + 45) continue;
      if (dist(x, z, this.start.x, this.start.z) < 70) continue;
      spawns.push({ id: hashInts(sh, i, 3) & 0x7fffffff, x, z, size: 1 + (hashInts(hx, 4) % 3), kind: "pack" });
    }
    for (const p of region.pois) {
      if (p.x < x0 || p.x >= x0 + CHUNK || p.z < z0 || p.z >= z0 + CHUNK) continue;
      if (p.kind === "camp")
        spawns.push({ id: hashInts(p.seed, 1) & 0x7fffffff, x: p.x, z: p.z, size: 4 + (p.seed % 3), kind: "camp", poiId: p.id });
      if (p.kind === "nest")
        spawns.push({ id: hashInts(p.seed, 2) & 0x7fffffff, x: p.x, z: p.z, size: 1, kind: "elite", poiId: p.id });
    }

    return { cx, cz, props, buildings, colliders, spawns };
  }
}

function pickRule(b: Biome, r: number) {
  let total = 0;
  for (const p of b.props) total += p.weight;
  let x = r * total;
  for (const p of b.props) {
    x -= p.weight;
    if (x <= 0) return p;
  }
  return b.props[b.props.length - 1];
}
