/**
 * Атмосфера вокруг камеры: лепестки сакуры, листопад, светлячки, снег, пыль, угли, искры, конфетти —
 * по биому и времени суток. Плюс дым из труб-хвостов домов рядом с игроком.
 */
import type { ParticleSystem } from "../../engine/particles";
import type { Environment } from "../../engine/environment";
import { CHIMNEY_TIPS } from "../../engine/prop-meshes";
import type { BiomeId } from "../world/biomes";
import type { Building } from "../world/worldgen";

const R = () => Math.random();
const RS = () => Math.random() * 2 - 1;

type Emitter = (ps: ParticleSystem, x: number, y: number, z: number, env: Environment) => void;

interface AmbientDef {
  /** Частиц в секунду при полном качестве. */
  rate: number;
  day?: Emitter;
  night?: Emitter;
}

const petals: Emitter = (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 22,
    y: y + 5 + R() * 6,
    z: z + RS() * 22,
    vx: env.windX * 0.8 + RS() * 0.3,
    vy: -0.55 - R() * 0.3,
    vz: env.windZ * 0.8 + RS() * 0.3,
    life: 9,
    size: 0.09 + R() * 0.05,
    color: R() < 0.5 ? 0xffc2d8 : 0xffe0ec,
    shape: "heart",
    spin: RS() * 3,
    alpha: 0.95,
    additive: false,
    drag: 0.2,
  });

const leaves = (cols: number[]): Emitter => (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 22,
    y: y + 5 + R() * 5,
    z: z + RS() * 22,
    vx: env.windX * 0.9 + RS() * 0.4,
    vy: -0.8 - R() * 0.4,
    vz: env.windZ * 0.9 + RS() * 0.4,
    life: 8,
    size: 0.13 + R() * 0.06,
    color: cols[(R() * cols.length) | 0],
    shape: "leaf",
    spin: RS() * 4,
    additive: false,
    drag: 0.3,
  });

const pollen: Emitter = (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 18,
    y: y + 0.4 + R() * 3,
    z: z + RS() * 18,
    vx: env.windX * 0.3 + RS() * 0.15,
    vy: RS() * 0.1,
    vz: env.windZ * 0.3 + RS() * 0.15,
    life: 6,
    size: 0.05 + R() * 0.03,
    color: 0xfff2b0,
    alpha: 0.5,
    shape: "circle",
  });

const fireflies: Emitter = (ps, x, y, z) => {
  const fx = x + RS() * 18,
    fz = z + RS() * 18,
    fy = y + 0.4 + R() * 1.8;
  ps.emit({ x: fx, y: fy, z: fz, vx: RS() * 0.4, vy: RS() * 0.2, vz: RS() * 0.4, life: 2.2 + R() * 2, size: 0.09, size1: 0.02, color: 0xd8ff6a, color1: 0x9aff4a, shape: "circle", drag: 0.1 });
  ps.emit({ x: fx, y: fy, z: fz, vx: 0, vy: 0, vz: 0, life: 1.2, size: 0.4, size1: 0.1, color: 0x9aff4a, alpha: 0.25, shape: "circle" });
};

const snow: Emitter = (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 20,
    y: y + 7 + R() * 5,
    z: z + RS() * 20,
    vx: env.windX * 0.6 + RS() * 0.3,
    vy: -1.1 - R() * 0.5,
    vz: env.windZ * 0.6 + RS() * 0.3,
    life: 9,
    size: 0.07 + R() * 0.06,
    color: 0xffffff,
    shape: R() < 0.3 ? "snow" : "circle",
    spin: RS(),
    alpha: 0.9,
    additive: false,
  });

const dust: Emitter = (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 20,
    y: y + 0.3 + R() * 1.2,
    z: z + RS() * 20,
    vx: env.windX * 2.2 + RS() * 0.5,
    vy: 0.05,
    vz: env.windZ * 2.2 + RS() * 0.5,
    life: 4,
    size: 0.8 + R() * 0.8,
    size1: 1.8,
    color: 0xe8d0a0,
    alpha: 0.12,
    shape: "smoke",
    additive: false,
  });

const embers: Emitter = (ps, x, y, z) => {
  ps.emit({ x: x + RS() * 18, y: y + R() * 1.5, z: z + RS() * 18, vx: RS() * 0.4, vy: 0.9 + R() * 1.2, vz: RS() * 0.4, life: 3, size: 0.07, size1: 0.02, color: 0xffb04a, color1: 0xff3a0a, shape: "spark", stretch: 1 });
  if (R() < 0.5) ps.emit({ x: x + RS() * 20, y: y + 6 + R() * 4, z: z + RS() * 20, vx: RS() * 0.3, vy: -0.5, vz: RS() * 0.3, life: 8, size: 0.08, color: 0x6a6260, shape: "circle", alpha: 0.7, additive: false });
};

const sparkles = (c1: number, c2: number): Emitter => (ps, x, y, z) =>
  ps.emit({ x: x + RS() * 16, y: y + 0.3 + R() * 2.5, z: z + RS() * 16, vx: 0, vy: 0.15, vz: 0, life: 1.4 + R(), size: 0.12, size1: 0.0, color: R() < 0.5 ? c1 : c2, shape: "star", spin: RS() * 2 });

const wisps = (c: number): Emitter => (ps, x, y, z) =>
  ps.emit({ x: x + RS() * 18, y: y + 0.2 + R() * 1.2, z: z + RS() * 18, vx: RS() * 0.3, vy: 0.2, vz: RS() * 0.3, life: 4, size: 0.5, size1: 1.2, color: c, alpha: 0.18, shape: "smoke" });

const swampGas: Emitter = (ps, x, y, z) =>
  ps.emit({ x: x + RS() * 16, y: y + R() * 0.3, z: z + RS() * 16, vx: 0, vy: 0.35 + R() * 0.3, vz: 0, life: 3, size: 0.12, size1: 0.2, color: 0xb8ff9a, alpha: 0.5, shape: "bubble", additive: false });

const confetti: Emitter = (ps, x, y, z, env) =>
  ps.emit({
    x: x + RS() * 20,
    y: y + 6 + R() * 5,
    z: z + RS() * 20,
    vx: env.windX * 0.6 + RS() * 0.4,
    vy: -0.9 - R() * 0.4,
    vz: env.windZ * 0.6 + RS() * 0.4,
    life: 8,
    size: 0.08 + R() * 0.04,
    color: [0xff6b9b, 0x6bd0ff, 0xffe066, 0x9bff8a, 0xd8a0ff][(R() * 5) | 0],
    shape: "diamond",
    spin: RS() * 6,
    additive: false,
  });

const AMBIENT: Partial<Record<BiomeId, AmbientDef>> = {
  meadow: { rate: 10, day: pollen, night: fireflies },
  birch: { rate: 8, day: leaves([0xe8e070, 0xd8c858, 0xb8d060]), night: fireflies },
  sakura: { rate: 22, day: petals, night: petals },
  forest: { rate: 8, day: leaves([0x7aa84a, 0xa8b04a, 0xc8a040]), night: fireflies },
  autumn: { rate: 20, day: leaves([0xe07a2a, 0xd8402a, 0xf0b030, 0xa05a2a]), night: leaves([0xe07a2a, 0xd8402a, 0xf0b030]) },
  jungle: { rate: 12, day: pollen, night: fireflies },
  savanna: { rate: 6, day: dust, night: fireflies },
  desert: { rate: 8, day: dust, night: dust },
  beach: { rate: 5, day: dust },
  swamp: { rate: 12, day: swampGas, night: fireflies },
  taiga: { rate: 14, day: snow, night: snow },
  snow: { rate: 40, day: snow, night: snow },
  mountain: { rate: 6, day: wisps(0xe8eef4), night: wisps(0xc8d0e8) },
  volcanic: { rate: 24, day: embers, night: embers },
  crystal: { rate: 14, day: sparkles(0xb8f0ff, 0xe0b0ff), night: sparkles(0xb8f0ff, 0xe0b0ff) },
  shadow: { rate: 10, day: wisps(0x8a6aff), night: wisps(0xa07aff) },
  void: { rate: 12, day: sparkles(0xd08aff, 0x7a5aff), night: sparkles(0xd08aff, 0x7a5aff) },
  candy: { rate: 14, day: confetti, night: confetti },
};

export class AmbientFx {
  private acc = 0;
  private smokeAcc = 0;
  quality = 1;

  constructor(private ps: ParticleSystem) {}

  update(dt: number, biome: BiomeId, x: number, y: number, z: number, env: Environment) {
    const def = AMBIENT[biome];
    if (def) {
      const em = env.night > 0.5 ? def.night : def.day;
      if (em) {
        this.acc += dt * def.rate * this.quality;
        let n = 0;
        while (this.acc >= 1 && n < 12) {
          this.acc -= 1;
          n++;
          em(this.ps, x, y, z, env);
        }
      }
    }
  }

  /** Дым из труб-хвостов ближних домов (колечками вверх по ветру). */
  chimneys(dt: number, buildings: Building[], px: number, pz: number, env: Environment) {
    this.smokeAcc += dt;
    if (this.smokeAcc < 0.22) return;
    this.smokeAcc = 0;
    for (const b of buildings) {
      const tip = CHIMNEY_TIPS[b.kind];
      if (!tip) continue;
      if (Math.abs(b.x - px) > 45 || Math.abs(b.z - pz) > 45) continue;
      if (R() > 0.55 * this.quality + 0.2) continue;
      const c = Math.cos(b.rot),
        s = Math.sin(b.rot);
      const lx = tip[0] * b.scale,
        ly = tip[1] * b.scale,
        lz = tip[2] * b.scale;
      const wx = b.x + c * lx + s * lz,
        wz = b.z - s * lx + c * lz;
      const warm = env.night > 0.5 ? 0x8a8a9a : 0xd8d4d0;
      this.ps.emit({
        x: wx + RS() * 0.1,
        y: b.y + ly + 0.1,
        z: wz + RS() * 0.1,
        vx: env.windX * 0.6 + RS() * 0.15,
        vy: 0.9 + R() * 0.3,
        vz: env.windZ * 0.6 + RS() * 0.15,
        life: 3.2,
        size: 0.25,
        size1: 1.1,
        color: warm,
        alpha: 0.35,
        shape: "smoke",
        additive: false,
        drag: 0.4,
      });
    }
  }
}
