/** Инстансированный рендер пропов (деревья, камни...) и построек. */
import { hexToRgb } from "../core/math";
import { PropKind } from "../game/world/biomes";
import { CHUNK, type BuildingKind } from "../game/world/worldgen";
import type { TerrainCache } from "../game/world/terrain-cache";
import type { Camera } from "./camera";
import { ATTR, DynamicBuffer, GpuMesh, type GL, type Program } from "./gl";
import { BUILDING_KINDS, buildBuildingMesh, buildPropMesh } from "./prop-meshes";

const INST_FLOATS = 8;

/** Мелкий декор рисуем только вблизи. */
const DECOR = new Set<number>([PropKind.Grass, PropKind.Flowers, PropKind.Mushroom, PropKind.Reeds, PropKind.FishBones]);

/**
 * Партия инстансов одного меша. В буфере подряд лежат два набора: видимые камерой
 * и попадающие в карту теней (атрибуты инстансов переуказываются на нужное смещение).
 */
interface Batch {
  mesh: GpuMesh;
  buf: DynamicBuffer;
  data: Float32Array;
  count: number;
  sdata: Float32Array;
  scount: number;
}

interface ChunkInstances {
  cx: number;
  cz: number;
  minY: number;
  maxY: number;
  /** kind → [x,y,z,rot,scale,r,g,b]* (x,z относительно угла чанка) */
  props: Map<number, Float32Array>;
  buildings: Map<string, Float32Array>;
}

const ckey = (cx: number, cz: number) => (cx + 1048576) * 2097152 + (cz + 1048576);

export class PropRenderer {
  private propBatches: Batch[] = [];
  private buildingBatches = new Map<string, Batch>();
  private chunkData = new Map<number, ChunkInstances>();
  propRadius = 5; // в чанках
  decorRadius = 2;
  buildingRadius = 8;
  drawn = 0;

  constructor(
    readonly gl: GL,
    readonly cache: TerrainCache,
  ) {
    for (let k = 0; k < PropKind.COUNT; k++) this.propBatches.push(this.makeBatch(buildPropMesh(k as PropKind)));
    for (const bk of BUILDING_KINDS) this.buildingBatches.set(bk, this.makeBatch(buildBuildingMesh(bk)));
  }

  private makeBatch(geo: ReturnType<typeof buildPropMesh>): Batch {
    const gl = this.gl;
    const buf = new DynamicBuffer(gl);
    const mesh = new GpuMesh(gl, geo, (gl) => {
      gl.bindBuffer(gl.ARRAY_BUFFER, buf.buffer);
      gl.bufferData(gl.ARRAY_BUFFER, 64, gl.DYNAMIC_DRAW);
      const stride = INST_FLOATS * 4;
      gl.enableVertexAttribArray(ATTR.i0);
      gl.vertexAttribPointer(ATTR.i0, 4, gl.FLOAT, false, stride, 0);
      gl.vertexAttribDivisor(ATTR.i0, 1);
      gl.enableVertexAttribArray(ATTR.i1);
      gl.vertexAttribPointer(ATTR.i1, 4, gl.FLOAT, false, stride, 16);
      gl.vertexAttribDivisor(ATTR.i1, 1);
    });
    return { mesh, buf, data: new Float32Array(256 * INST_FLOATS), count: 0, sdata: new Float32Array(64 * INST_FLOATS), scount: 0 };
  }

  private prepareChunk(cx: number, cz: number): ChunkInstances {
    const k = ckey(cx, cz);
    let ci = this.chunkData.get(k);
    if (ci) return ci;
    const content = this.cache.content(cx, cz);
    const x0 = cx * CHUNK,
      z0 = cz * CHUNK;
    const byKind = new Map<number, number[]>();
    let minY = Infinity,
      maxY = -Infinity;
    for (const p of content.props) {
      let arr = byKind.get(p.kind);
      if (!arr) byKind.set(p.kind, (arr = []));
      const [r, g, b] = hexToRgb(p.tint);
      arr.push(p.x - x0, p.y, p.z - z0, p.rot, p.scale, r, g, b);
      minY = Math.min(minY, p.y);
      maxY = Math.max(maxY, p.y + 8 * p.scale);
    }
    const byB = new Map<string, number[]>();
    for (const bd of content.buildings) {
      let arr = byB.get(bd.kind);
      if (!arr) byB.set(bd.kind, (arr = []));
      const [r, g, b] = hexToRgb(bd.color);
      arr.push(bd.x - x0, bd.y, bd.z - z0, bd.rot, bd.scale, r, g, b);
      minY = Math.min(minY, bd.y);
      maxY = Math.max(maxY, bd.y + 10 * bd.scale);
    }
    const props = new Map<number, Float32Array>();
    for (const [kind, arr] of byKind) props.set(kind, new Float32Array(arr));
    const buildings = new Map<string, Float32Array>();
    for (const [kind, arr] of byB) buildings.set(kind, new Float32Array(arr));
    ci = { cx, cz, minY: isFinite(minY) ? minY : 0, maxY: isFinite(maxY) ? maxY : 1, props, buildings };
    this.chunkData.set(k, ci);
    if (this.chunkData.size > 700) {
      const first = this.chunkData.keys().next().value;
      if (first !== undefined) this.chunkData.delete(first);
    }
    return ci;
  }

  private push(batch: Batch, src: Float32Array, ox: number, oz: number, shadow = false) {
    const n = src.length / INST_FLOATS;
    const cnt = shadow ? batch.scount : batch.count;
    let d = shadow ? batch.sdata : batch.data;
    const need = (cnt + n) * INST_FLOATS;
    if (need > d.length) {
      const nd = new Float32Array(Math.max(need, d.length * 2));
      nd.set(d.subarray(0, cnt * INST_FLOATS));
      d = nd;
      if (shadow) batch.sdata = nd;
      else batch.data = nd;
    }
    let o = cnt * INST_FLOATS;
    for (let i = 0; i < src.length; i += INST_FLOATS) {
      d[o] = src[i] + ox;
      d[o + 1] = src[i + 1];
      d[o + 2] = src[i + 2] + oz;
      d[o + 3] = src[i + 3];
      d[o + 4] = src[i + 4];
      d[o + 5] = src[i + 5];
      d[o + 6] = src[i + 6];
      d[o + 7] = src[i + 7];
      o += INST_FLOATS;
    }
    if (shadow) batch.scount += n;
    else batch.count += n;
  }

  /** Сколько чанков с содержимым можно подготовить за кадр (генерация занимает время). */
  prepareBudget = 6;

  /**
   * Собрать инстансы кадра: видимые камерой и (если sr > 0) попадающие в квадрат карты теней.
   * Загружает всё в буферы; рисовать можно затем draw() и drawShadow().
   */
  collect(cam: Camera, sx = 0, sz = 0, sr = 0) {
    for (const b of this.propBatches) b.count = b.scount = 0;
    for (const b of this.buildingBatches.values()) b.count = b.scount = 0;
    const ccx = Math.floor(cam.tx / CHUNK),
      ccz = Math.floor(cam.tz / CHUNK);
    const R = Math.max(this.propRadius, this.buildingRadius);
    let prepared = 0;
    for (let dz = -R; dz <= R; dz++) {
      for (let dx = -R; dx <= R; dx++) {
        const d2 = dx * dx + dz * dz;
        if (d2 > (R + 0.5) * (R + 0.5)) continue;
        const cx = ccx + dx,
          cz = ccz + dz;
        const k = ckey(cx, cz);
        let ci = this.chunkData.get(k);
        if (!ci) {
          if (prepared >= this.prepareBudget && d2 > 2) continue;
          ci = this.prepareChunk(cx, cz);
          prepared++;
        }
        const x0 = cx * CHUNK - cam.ox,
          z0 = cz * CHUNK - cam.oz;
        const inView = cam.boxVisible(x0 - 4, ci.minY - 1, z0 - 4, x0 + CHUNK + 4, ci.maxY, z0 + CHUNK + 4);
        // Квадрат теней с запасом на высоту объектов
        const wx0 = cx * CHUNK,
          wz0 = cz * CHUNK;
        const inShadow = sr > 0 && wx0 - 6 < sx + sr && wx0 + CHUNK + 6 > sx - sr && wz0 - 6 < sz + sr && wz0 + CHUNK + 6 > sz - sr;
        if (!inView && !inShadow) continue;
        const inProps = d2 <= (this.propRadius + 0.5) ** 2;
        const inDecor = d2 <= (this.decorRadius + 0.5) ** 2;
        if (inProps)
          for (const [kind, arr] of ci.props) {
            const decor = DECOR.has(kind);
            if (decor && !inDecor) continue;
            const b = this.propBatches[kind];
            if (inView) this.push(b, arr, x0, z0);
            if (inShadow && !decor) this.push(b, arr, x0, z0, true);
          }
        if (d2 <= (this.buildingRadius + 0.5) ** 2)
          for (const [kind, arr] of ci.buildings) {
            const batch = this.buildingBatches.get(kind);
            if (!batch) continue;
            if (inView) this.push(batch, arr, x0, z0);
            if (inShadow) this.push(batch, arr, x0, z0, true);
          }
      }
    }
    const up = (b: Batch) => {
      const n = b.count + b.scount;
      if (n === 0) return;
      if (b.scount) {
        // Оба набора одним буфером: сначала видимые, затем теневые
        const need = n * INST_FLOATS;
        if (b.data.length < need) {
          const nd = new Float32Array(need);
          nd.set(b.data.subarray(0, b.count * INST_FLOATS));
          b.data = nd;
        }
        b.data.set(b.sdata.subarray(0, b.scount * INST_FLOATS), b.count * INST_FLOATS);
      }
      b.buf.upload(b.data, n * INST_FLOATS);
    };
    for (const b of this.propBatches) up(b);
    for (const b of this.buildingBatches.values()) up(b);
  }

  private pointInstances(b: Batch, first: number) {
    const gl = this.gl;
    const stride = INST_FLOATS * 4;
    gl.bindBuffer(gl.ARRAY_BUFFER, b.buf.buffer);
    gl.vertexAttribPointer(ATTR.i0, 4, gl.FLOAT, false, stride, first * stride);
    gl.vertexAttribPointer(ATTR.i1, 4, gl.FLOAT, false, stride, first * stride + 16);
  }

  /** Нарисовать видимые инстансы (после collect). */
  draw(prog: Program) {
    const gl = this.gl;
    prog.use();
    let drawn = 0;
    const flush = (b: Batch) => {
      if (b.count === 0) return;
      gl.bindVertexArray(b.mesh.vao);
      if (b.scount) this.pointInstances(b, 0);
      b.mesh.drawInstanced(b.count);
      drawn += b.count;
    };
    for (const b of this.propBatches) flush(b);
    for (const b of this.buildingBatches.values()) flush(b);
    gl.bindVertexArray(null);
    this.drawn = drawn;
  }

  /** Нарисовать отбрасывающие тень инстансы в карту теней. */
  drawShadow(prog: Program) {
    const gl = this.gl;
    prog.use();
    const flush = (b: Batch) => {
      if (b.scount === 0) return;
      gl.bindVertexArray(b.mesh.vao);
      this.pointInstances(b, b.count);
      b.mesh.drawInstanced(b.scount);
    };
    for (const b of this.propBatches) flush(b);
    for (const b of this.buildingBatches.values()) flush(b);
    gl.bindVertexArray(null);
  }

  /** Сбросить подготовленные данные (например, при смене мира). */
  clear() {
    this.chunkData.clear();
  }
}

export type { BuildingKind };
