/**
 * Лазание по деревьям. Кот цепляется за ствол, лезет вверх и вниз (и вбок, обходя ствол),
 * наверху запрыгивает на крону и лежит там, свесив хвост. Спрыгивает в сторону движения.
 * Стволы и «насесты» повторяют модели из engine/prop-meshes (локальные координаты до поворота и масштаба).
 */
import { PropKind } from "../world/biomes";
import type { BuildingKind } from "../world/worldgen";

export interface ClimbSpec {
  /** Ось ствола от земли вверх (локально): кот ползёт по ней. */
  path: [number, number, number][];
  /** Радиус ствола у земли и наверху. */
  r0: number;
  r1: number;
  /** Прыжки после ствола (площадки когтеточки), затем — насест. */
  hops: [number, number, number][];
  /** Где кот устраивается наверху. */
  perch: [number, number, number];
}

// Ствол пальмы — та же цепочка сегментов, что в модели
const palmPath = (): [number, number, number][] => {
  const pts: [number, number, number][] = [[0, 0, 0]];
  let x = 0,
    y = 0;
  for (let i = 0; i < 6; i++) {
    const lean = 0.07 * i;
    x += Math.sin(lean);
    y += Math.cos(lean) * 0.98;
    pts.push([x, y, 0]);
  }
  return pts;
};
const PALM = palmPath();
const PALM_TOP = PALM[PALM.length - 1];

