/** Опора: дерево или когтеточка в мире. */
export interface ClimbAnchor {
  x: number;
  y: number;
  z: number;
  rot: number;
  scale: number;
  spec: ClimbSpec;
  building: boolean;
  /** Радиус коллайдера в мире (куда приземляться, откуда начинать лезть). */
  col: number;
  /** Цвет кроны (для листьев, которые сыплются при прыжке). */
  tint: number;
}

export type ClimbPhase = "climb" | "hop" | "perch" | "leap";

export interface ClimbState extends ClimbAnchor {
  /** Длина ствола (м) и пройденное расстояние. */
  len: number;
  d: number;
  /** С какой стороны ствола кот (мировой угол, как yaw: направление (sin, cos)). */
  ang: number;
  /**
   * Направление ввода «вверх по стволу» (мир). Запоминается при старте и не зависит от того,
   * с какой стороны ствола кот: иначе, обходя ствол, кот начинал считать тот же ввод «вниз» и слезал.
   */
  upX: number;
  upZ: number;
  phase: ClimbPhase;
  t: number;
  /** Текущий прыжок: откуда, куда, длительность, высота дуги. */
  from: [number, number, number];
  to: [number, number, number];
  dur: number;
  arc: number;
  /** Номер следующего прыжка по площадкам (для когтеточки). */
  hop: number;
  /** Здоровье в начале — удар сбивает с дерева. */
  hp: number;
  /** Сколько держат ввод «прочь» на насесте (чтобы не спрыгнуть случайно). */
  away: number;
}

export const CLIMB_SPEED = 2.2;

/** Локальная точка опоры → мир (как в шейдере пропов). */
export function anchorPoint(a: ClimbAnchor, p: readonly number[], out: number[] = [0, 0, 0]): number[] {
  const c = Math.cos(a.rot),
    s = Math.sin(a.rot);
  out[0] = a.x + (c * p[0] + s * p[2]) * a.scale;
  out[1] = a.y + p[1] * a.scale;
  out[2] = a.z + (-s * p[0] + c * p[2]) * a.scale;
  return out;
}

/** Длина ствола в метрах. */
export function pathLength(a: ClimbAnchor): number {
  let len = 0;
  const p = a.spec.path;
  for (let i = 1; i < p.length; i++) len += Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1], p[i][2] - p[i - 1][2]);
  return len * a.scale;
}

/** Точка на оси ствола на расстоянии d от земли и радиус ствола там. */
export function trunkAt(a: ClimbAnchor, d: number, out: number[] = [0, 0, 0, 0]): number[] {
  const p = a.spec.path;
  const total = pathLength(a);
  let left = Math.max(0, Math.min(d, total)) / a.scale;
  let lx = p[0][0],
    ly = p[0][1],
    lz = p[0][2];
  for (let i = 1; i < p.length; i++) {
    const sl = Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1], p[i][2] - p[i - 1][2]);
    if (left <= sl || i === p.length - 1) {
      const k = sl > 0 ? Math.min(1, left / sl) : 0;
      lx = p[i - 1][0] + (p[i][0] - p[i - 1][0]) * k;
      ly = p[i - 1][1] + (p[i][1] - p[i - 1][1]) * k;
      lz = p[i - 1][2] + (p[i][2] - p[i - 1][2]) * k;
      break;
    }
    left -= sl;
  }
  anchorPoint(a, [lx, ly, lz], out);
  const u = total > 0 ? Math.min(1, d / total) : 0;
  out[3] = (a.spec.r0 + (a.spec.r1 - a.spec.r0) * u) * a.scale;
  return out;
}

/**
 * Поза кота на стволе: точка у поверхности ствола со стороны ang, мордой к стволу.
 * Возвращает [x, y, z, yaw].
 */
export function climbPose(a: ClimbAnchor, d: number, ang: number, out: number[] = [0, 0, 0, 0]): number[] {
  const t = trunkAt(a, d);
  const r = t[3] + 0.02;
  out[0] = t[0] + Math.sin(ang) * r;
  out[1] = t[1];
  out[2] = t[2] + Math.cos(ang) * r;
  out[3] = ang + Math.PI;
  return out;
}

/** Высота дуги прыжка: чем дальше, тем выше. */
export function hopArc(from: readonly number[], to: readonly number[]): number {
  return 0.35 + Math.hypot(to[0] - from[0], to[2] - from[2]) * 0.12 + Math.max(0, to[1] - from[1]) * 0.15;
}
