/** Боевая математика: урон, крит, броня, щиты, эффекты при попадании, лечение, смерть. */
import { levelScale } from "../progression";
import type { Element } from "../types";
import type { OnHit, SkillDef } from "../skills/types";
import type { DamageSource, Entity, Status } from "./types";
import type { GameWorld } from "./world";
import { ELEMENTS } from "../types";

export function isHostile(a: { faction: number }, b: { faction: number }): boolean {
  return a.faction !== b.faction && a.faction !== 2 && b.faction !== 2;
}

export function statusValue(e: Entity, kind: Status["kind"]): number {
  let v = 0;
  for (const s of e.statuses) if (s.kind === kind) v = Math.max(v, s.value);
  return v;
}

export function sumStatus(e: Entity, kind: Status["kind"]): number {
  let v = 0;
  for (const s of e.statuses) if (s.kind === kind) v += s.value;
  return v;
}

export function hasStatus(e: Entity, kind: Status["kind"]): boolean {
  for (const s of e.statuses) if (s.kind === kind) return true;
  return false;
}

export function isDisabled(e: Entity): boolean {
  return hasStatus(e, "stun") || hasStatus(e, "freeze");
}

export function buffPct(e: Entity, stat: string): number {
  let v = 0;
  for (const s of e.statuses) if (s.kind === "buff" && s.stat === stat) v += s.value;
  return v;
}

export function addStatus(e: Entity, st: Status) {
  if (!e.alive) return;
  const key = st.key ?? st.kind + (st.el ?? "") + (st.stat ?? "");
  st.key = key;
  for (const s of e.statuses) {
    if (s.key === key) {
      s.t = Math.max(s.t, st.t);
      s.dur = Math.max(s.dur, st.dur);
      if (st.kind === "dot") {
        // стакаем урон доты (до 3x)
        s.value = Math.min(s.value + st.value, st.value * 3);
        s.src = st.src;
      } else s.value = Math.max(s.value, st.value);
      return;
    }
  }
  e.statuses.push(st);
}

/** Снимок параметров атакующего для навыка. */
export function makeSource(w: GameWorld, caster: Entity, skill: SkillDef | null): DamageSource {
  const st = caster.stats;
  let power: number, crit: number, critDmg: number, lifesteal: number;
  let mul = 1 - sumStatus(caster, "weaken");
  let deliveryPct = 0;
  let elementPct: Record<Element, number> | null = null;
  if (st) {
    power = st.power * (1 + buffPct(caster, "power"));
    crit = st.crit + buffPct(caster, "crit") + (skill?.params.crit ?? 0);
    critDmg = st.critDmg;
    lifesteal = st.lifesteal;
    elementPct = st.elementPct;
    deliveryPct = skill ? st.deliveryPct[skill.delivery] ?? 0 : 0;
    mul *= st.damageMul;
    const ks = st.keystones;
    if (ks.has("bloodPact")) mul *= 1.3;
    if (ks.has("chaos")) mul *= 1.25;
    if (ks.has("berserker")) mul *= 1 + 0.5 * (1 - caster.hp / Math.max(1, caster.maxHp));
    if (ks.has("loneHunter")) {
      let alone = true;
      for (const o of w.entities.values()) {
        if (o === caster || !o.alive || o.faction !== caster.faction || o.kind === "npc") continue;
        if ((o.x - caster.x) ** 2 + (o.z - caster.z) ** 2 < 144) {
          alone = false;
          break;
        }
      }
      if (alone) mul *= 1.4;
    }
    if (caster.kind === "minion" && caster.minion) {
      const owner = w.entities.get(caster.minion.ownerId);
      if (owner?.stats?.keystones.has("packLeader")) mul *= 1.4;
    }
  } else {
    power = caster.dmg;
    crit = 0.05;
    critDmg = 1.5;
    lifesteal = 0;
  }
  return {
    attackerId: caster.id,
    faction: caster.faction,
    level: caster.level,
    power,
    crit,
    critDmg,
    elementPct,
    deliveryPct,
    mul: Math.max(0.1, mul),
    lifesteal,
    onHit: skill ? skill.onHit : [],
    skill,
    isPlayer: caster.kind === "player",
    castX: caster.x,
    castZ: caster.z,
  };
}

export interface HitOpts {
  dot?: boolean;
  noOnHit?: boolean;
  knock?: number;
  fromX?: number;
  fromZ?: number;
  noThorns?: boolean;
  delivery?: string;
}

export function dealDamage(w: GameWorld, src: DamageSource, target: Entity, coef: number, el: Element, opts: HitOpts = {}): number {
  if (!target.alive || target.faction === src.faction || target.faction === 2) return 0;
  if (target.invuln > 0) return 0;
  if (!w.authority) {
    // Гость кооператива: урон считает хост, здесь только визуальная реакция.
    if (target.kind !== "player") target.flash = Math.max(target.flash, opts.dot ? 0.25 : 0.8);
    return 0;
  }
  const rng = w.rng;
  const tStats = target.stats;
  if (!opts.dot) {
    const dodge = tStats ? tStats.dodge : target.enemy?.role === "skirmisher" ? 0.06 : 0.02;
    const blind = src.isPlayer ? 0 : 0;
    if (rng.next() < dodge + blind) {
      w.emit({ t: "dodge", id: target.id, x: target.x, y: target.y + 1.6 * target.look.size, z: target.z });
      return 0;
    }
  }
  const elPct = src.elementPct ? src.elementPct[el] : 0;
  let dmg = src.power * coef * src.mul * (1 + elPct + src.deliveryPct);
  let crit = false;
  if (!opts.dot && rng.next() < src.crit) {
    dmg *= src.critDmg;
    crit = true;
  }
  // Снайпер: бонус на дистанции
  if (src.isPlayer && src.skill?.delivery === "projectile") {
    const att = w.entities.get(src.attackerId);
    if (att?.stats?.keystones.has("sniper")) {
      const d = Math.sqrt((target.x - src.castX) ** 2 + (target.z - src.castZ) ** 2);
      dmg *= 1 + Math.min(0.6, Math.max(0, (d - 6) / 14) * 0.6);
    }
  }
  dmg *= 1 + sumStatus(target, "vulnerable") + sumStatus(target, "mark");
  // Защита
  const armor = tStats ? tStats.armor * (1 + buffPct(target, "armor")) : target.armor;
  const resist = tStats ? tStats.resist : target.resist;
  if (el === "physical") {
    const K = 30 * levelScale(src.level);
    dmg *= K / (K + Math.max(0, armor));
  } else dmg *= 1 - Math.min(0.75, resist);
  if (target.kind === "player" && !src.isPlayer) dmg *= w.difficulty;
  if (dmg <= 0) return 0;
  // Щит (щит удалённого игрока учитывает он сам)
  if (target.shield > 0 && target.peer !== "remote") {
    const a = Math.min(target.shield, dmg);
    target.shield -= a;
    dmg -= a;
  }
  target.hp -= dmg;
  // Здоровьем удалённого игрока распоряжается он сам: хост лишь пересылает удары.
  if (target.peer === "remote" && target.hp < 1) target.hp = 1;
  target.flash = Math.max(target.flash, opts.dot ? 0.25 : 0.8);
  target.lastCombat = w.time;
  const attacker = w.entities.get(src.attackerId);
  if (attacker) attacker.lastCombat = w.time;
  if (target.ai && attacker && attacker.alive) {
    target.ai.lastHitBy = attacker.id;
    if (target.ai.mode !== "flee" && target.ai.mode !== "chase" && target.ai.mode !== "attack") {
      target.ai.target = attacker.id;
      target.ai.mode = "chase";
    }
  }
  w.emit({
    t: "damage",
    id: target.id,
    by: src.attackerId,
    x: target.x,
    y: target.y + (1.4 + 0.3 * rng.next()) * target.look.size,
    z: target.z,
    amount: dmg,
    crit,
    el,
    toPlayer: target.kind === "player",
    dot: !!opts.dot,
  });
  if (!opts.dot && target.kind !== "player" && !target.cast && target.action === null) {
    target.action = "hit";
    target.actionT = 0;
    target.actionDur = 0.3;
  }
  // Вампиризм
  if (attacker && attacker.alive) {
    let ls = src.lifesteal;
    if (!opts.noOnHit) for (const h of src.onHit) if (h.k === "lifesteal") ls += h.pct;
    if (ls > 0) healEntity(w, attacker, dmg * ls, true);
    if (!opts.noOnHit)
      for (const h of src.onHit)
        if (h.k === "manaLeech") attacker.mp = Math.min(attacker.maxMp, attacker.mp + dmg * h.pct * 0.2);
    // Бешенство
    if (attacker.stats?.keystones.has("frenzy") && !opts.dot) {
      attacker.frenzy = Math.min(10, attacker.frenzy + 1);
      attacker.frenzyT = 4;
    }
  }
  // Шипы
  if (!opts.noThorns && !opts.dot && tStats && tStats.thorns > 0 && attacker && attacker.alive) {
    const back = makeSource(w, target, null);
    dealDamage(w, back, attacker, (dmg / Math.max(1, back.power)) * tStats.thorns, "physical", { noOnHit: true, noThorns: true });
  }
  if (!opts.dot && tStats?.keystones.has("frozenHeart") && attacker) addStatus(attacker, { kind: "slow", t: 2, dur: 2, value: 0.3 });
  // Эффекты при попадании
  if (!opts.noOnHit && target.alive) applyOnHits(w, src, target, src.onHit, opts);
  if (opts.knock && target.alive && !target.enemy?.boss) knock(target, opts.fromX ?? src.castX, opts.fromZ ?? src.castZ, opts.knock);
  // Смерть
  if (target.hp <= 0) killEntity(w, target, src.attackerId);
  else {
    // Казнь
    if (!opts.noOnHit)
      for (const h of src.onHit)
        if (h.k === "execute" && !target.enemy?.boss && target.kind !== "player" && target.hp / target.maxHp < h.pct) {
          target.hp = 0;
          w.emit({ t: "text", text: { ru: "Казнь!", en: "Execute!" }, x: target.x, y: target.y + 2, z: target.z, color: 0xff5a5a });
          killEntity(w, target, src.attackerId);
          break;
        }
  }
  // Когти бури
  if (src.isPlayer && !opts.dot && src.skill?.melee && attacker?.stats?.keystones.has("stormClaws") && rng.chance(0.35)) {
    w.runtime.chainFrom(src, target, 2, 7, 0.5, "lightning");
  }
  return dmg;
}

function knock(t: Entity, fx: number, fz: number, force: number) {
  let dx = t.x - fx,
    dz = t.z - fz;
  const l = Math.hypot(dx, dz) || 1;
  dx /= l;
  dz /= l;
  const k = force * (t.kind === "player" ? 0.6 : 1) / Math.max(0.6, t.look.size);
  t.vx += dx * k * 2.2;
  t.vz += dz * k * 2.2;
}

export function applyOnHits(w: GameWorld, src: DamageSource, target: Entity, hits: OnHit[], opts: HitOpts) {
  const durMul = 1 + (w.entities.get(src.attackerId)?.stats?.durationPct ?? 0);
  const boss = !!target.enemy?.boss;
  const ccMul = boss ? 0.35 : target.kind === "player" ? 0.6 : 1;
  for (const h of hits) {
    switch (h.k) {
      case "dot":
        addStatus(target, { kind: "dot", t: h.dur * durMul, dur: h.dur * durMul, value: h.dps, el: h.el, src, tick: 0 });
        break;
      case "slow":
        addStatus(target, { kind: "slow", t: h.dur * durMul, dur: h.dur, value: h.pct * (boss ? 0.5 : 1) });
        break;
      case "stun":
        if (target.invuln <= 0) addStatus(target, { kind: "stun", t: h.dur * ccMul, dur: h.dur * ccMul, value: 1 });
        break;
      case "freeze":
        addStatus(target, { kind: "freeze", t: h.dur * ccMul, dur: h.dur * ccMul, value: 1 });
        break;
      case "knockback":
        if (!boss) knock(target, opts.fromX ?? src.castX, opts.fromZ ?? src.castZ, h.force);
        break;
      case "pull": {
        if (boss) break;
        const a = w.entities.get(src.attackerId);
        const px = opts.fromX ?? a?.x ?? src.castX;
        const pz = opts.fromZ ?? a?.z ?? src.castZ;
        knock(target, px, pz, -h.force);
        break;
      }
      case "weaken":
        addStatus(target, { kind: "weaken", t: h.dur * durMul, dur: h.dur, value: Math.min(0.6, h.pct) });
        break;
      case "vulnerable":
        addStatus(target, { kind: "vulnerable", t: h.dur * durMul, dur: h.dur, value: Math.min(0.8, h.pct) });
        break;
      case "explode":
        w.runtime.explosion(src, target.x, target.z, h.radius, h.power, src.skill?.element ?? "fire", target.id);
        break;
      case "split":
        if (src.skill && src.skill.delivery === "projectile") w.runtime.splitFrom(src, target, h.count);
        break;
      case "chain":
        w.runtime.chainFrom(src, target, h.count, 7, 0.6, src.skill?.element ?? "lightning");
        break;
      case "fear":
        if (!boss && target.kind !== "player") addStatus(target, { kind: "fear", t: h.dur * ccMul, dur: h.dur, value: 1 });
        break;
      case "charm":
        if (!boss && target.kind === "enemy" && target.faction === 1) {
          addStatus(target, { kind: "charm", t: h.dur, dur: h.dur, value: src.faction });
          target.faction = src.faction;
          if (target.ai) target.ai.target = -1;
        }
        break;
      case "blind":
        addStatus(target, { kind: "blind", t: h.dur, dur: h.dur, value: h.pct });
        break;
      default:
        break;
    }
  }
}

export function healEntity(w: GameWorld, target: Entity, amount: number, silent = false, healer?: Entity) {
  if (!target.alive || amount <= 0) return;
  // Гость кооператива: лечение от чужих (зеркальных) сущностей присылает хост
  if (!w.authority && target.peer === "local" && healer && healer.peer !== "local") return;
  const before = target.hp;
  target.hp = Math.min(target.maxHp, target.hp + amount);
  const real = target.hp - before;
  if (healer?.stats?.keystones.has("holyMantle")) {
    target.shield = Math.min(target.maxHp, target.shield + amount * 0.5);
    target.shieldT = Math.max(target.shieldT, 6);
  }
  // Для удалённого игрока событие нужно всегда: хост пересылает ему лечение от других
  if (real > 0.5 && (!silent || target.peer === "remote")) w.emit({ t: "heal", id: target.id, x: target.x, y: target.y + 1.6 * target.look.size, z: target.z, amount: real, by: healer?.id ?? -1, silent });
}

export function killEntity(w: GameWorld, target: Entity, killerId: number) {
  if (!target.alive) return;
  // У гостя кооператива смерти чужих сущностей приходят от хоста (иначе опыт засчитается дважды)
  if (!w.authority && target.peer !== "local") return;
  // Ключевые таланты игрока: девять жизней и феникс
  if (target.kind === "player" && target.stats) {
    const ks = target.stats.keystones;
    if (ks.has("nineLives") && target.nineLivesCd <= 0) {
      target.hp = target.maxHp * 0.5;
      target.nineLivesCd = 180;
      target.invuln = 1.5;
      w.emit({ t: "text", text: { ru: "Девять жизней!", en: "Nine Lives!" }, x: target.x, y: target.y + 2.2, z: target.z, color: 0xffd24a });
      w.emit({ t: "fx", fx: { k: "levelup", x: target.x, y: target.y, z: target.z, color: 0xffd24a } });
      return;
    }
    if (ks.has("phoenix") && target.phoenixCd <= 0) {
      target.hp = target.maxHp * 0.4;
      target.phoenixCd = 240;
      target.invuln = 1.5;
      w.runtime.explosion(makeSource(w, target, null), target.x, target.z, 6, 3, "fire", -1);
      w.emit({ t: "text", text: { ru: "Хвост феникса!", en: "Phoenix Tail!" }, x: target.x, y: target.y + 2.2, z: target.z, color: 0xff8a3a });
      return;
    }
  }
  target.alive = false;
  target.hp = 0;
  target.shield = 0;
  target.cast = null;
  target.motion = null;
  target.state = "dead";
  target.stateT = 0;
  target.action = null;
  target.statuses.length = 0;
  target.deadT = 0;
  w.emit({
    t: "death",
    id: target.id,
    x: target.x,
    z: target.z,
    kind: target.kind,
    killerId,
    level: target.level,
    family: target.enemy?.family,
    role: target.enemy?.role,
    boss: target.enemy?.boss,
    elite: target.enemy?.elite,
    poiId: target.enemy?.poiId,
  });
  w.emit({ t: "sound", s: target.kind === "player" ? "playerDeath" : target.enemy?.boss ? "bossDeath" : "death", x: target.x, z: target.z, pitch: 1.5 / Math.max(0.6, target.look.size) });
  if (target.kind === "player") w.emit({ t: "playerDeath", id: target.id });
  // Пассивки убийцы
  const killer = w.entities.get(killerId);
  const owner = killer?.kind === "minion" && killer.minion ? w.entities.get(killer.minion.ownerId) : killer;
  if (owner && owner.alive && owner.stats && target.kind === "enemy") {
    const ok = owner.stats.onKill;
    if (ok.heal > 0) healEntity(w, owner, owner.maxHp * ok.heal, true);
    if (ok.mana > 0) owner.mp = Math.min(owner.maxMp, owner.mp + owner.maxMp * ok.mana);
    if (ok.haste > 0) addStatus(owner, { kind: "buff", stat: "haste", t: 3, dur: 3, value: ok.haste * 5, key: "onKillHaste" });
    if (ok.explode > 0) w.runtime.explosion(makeSource(w, owner, null), target.x, target.z, 3, ok.explode, "fire", target.id);
  }
  // Питомцы умершего исчезают
  for (const e of w.entities.values()) if (e.minion && e.minion.ownerId === target.id && e.alive) e.minion.expires = 0;
}

export function randomElement(w: GameWorld): Element {
  return w.rng.pick(ELEMENTS);
}
