/** Визуальные эффекты: из событий и состояния симуляции → частицы, декали и вспышки света. */
import type { ParticleSystem } from "../../engine/particles";
import type { Decal, PointLight } from "../../engine/renderer";
import { ELEMENT_INFO } from "../skills/palette";
import type { ParticleShape, SkillVisual } from "../skills/types";
import type { Element } from "../types";
import type { Area, Entity, Fx, Projectile } from "../sim/types";

interface Telegraph {
  x: number;
  y: number;
  z: number;
  r: number;
  color: number;
  t: number;
  dur: number;
}
interface Flash {
  x: number;
  y: number;
  z: number;
  r: number;
  color: number;
  i: number;
  t: number;
  dur: number;
}

const R = () => Math.random();
const RS = () => Math.random() * 2 - 1;

const DEFAULT_V: SkillVisual = { color: 0xffffff, color2: 0xffe0a0, shape: "circle", size: 1, trail: false, glow: 1, style: 0 };

export class FxSystem {
  private telegraphs: Telegraph[] = [];
  private flashes: Flash[] = [];
  private acc = 0;
  quality = 1;

  constructor(private ps: ParticleSystem) {}

  private n(k: number) {
    return Math.max(1, Math.round(k * this.quality));
  }

  clear() {
    this.telegraphs.length = 0;
    this.flashes.length = 0;
    this.ps.clear();
  }

  light(x: number, y: number, z: number, r: number, color: number, i: number, dur: number) {
    if (this.flashes.length > 24) this.flashes.shift();
    this.flashes.push({ x, y, z, r, color, i, t: 0, dur });
  }

  handle(fx: Fx) {
    const v = fx.v ?? DEFAULT_V;
    const ps = this.ps;
    const { x, y, z } = fx;
    switch (fx.k) {
      case "slash": {
        const yaw = fx.yaw ?? 0,
          r = fx.radius ?? 2,
          sp = Math.min(fx.spread ?? 2, Math.PI * 2);
        const n = this.n(10 + sp * 4);
        for (let i = 0; i < n; i++) {
          const a = yaw - sp / 2 + (sp * i) / Math.max(1, n - 1);
          const rr = r * (0.55 + R() * 0.45);
          const px = x + Math.sin(a) * rr * 0.5,
            pz = z + Math.cos(a) * rr * 0.5;
          const tx = Math.cos(a),
            tz = -Math.sin(a);
          ps.emit({ x: px, y: y + RS() * 0.2, z: pz, vx: tx * 6 + Math.sin(a) * 2, vy: R() * 1.5, vz: tz * 6 + Math.cos(a) * 2, life: 0.22 + R() * 0.12, size: 0.28 * v.size, size1: 0.05, color: v.color2, color1: v.color, shape: "spark", stretch: 1.5, drag: 4 });
        }
        ps.emit({ x: x, y, z, life: 0.18, size: r * 0.55, size1: r * 0.75, color: v.color, shape: "claw", rot: yaw + Math.PI / 2, alpha: 0.9 });
        this.light(x, y, z, r * 2, v.color, 0.6, 0.15);
        break;
      }
      case "burst": {
        const r = Math.max(0.6, fx.radius ?? 1.5);
        ps.emit({ x, y, z, life: 0.2, size: r * 1.1, size1: r * 1.6, color: v.color2, alpha: 0.9 });
        const n = this.n(10 + r * 5);
        for (let i = 0; i < n; i++) {
          const a = R() * Math.PI * 2;
          const up = R() * 0.8 + 0.2;
          const s = r * (2 + R() * 3);
          ps.emit({ x, y, z, vx: Math.cos(a) * s, vy: up * s * 0.8, vz: Math.sin(a) * s, life: 0.35 + R() * 0.45, size: (0.22 + R() * 0.3) * v.size, size1: 0.05, color: v.color, color1: v.color2, shape: v.shape, gravity: 6, drag: 2.5, spin: RS() * 6 });
        }
        ps.emit({ x, y: y - 0.1, z, life: 0.35, size: 0.3, size1: r, color: v.color, shape: "ring", ground: true, alpha: 0.8 });
        for (let i = 0; i < this.n(3 + r); i++)
          ps.emit({ x: x + RS() * r * 0.5, y: y + 0.2, z: z + RS() * r * 0.5, vy: 1 + R(), life: 0.8 + R() * 0.6, size: 0.5 + r * 0.25, size1: 1 + r * 0.4, color: 0x5a5058, alpha: 0.35, shape: "smoke", additive: false, drag: 1 });
        this.light(x, y + 0.5, z, r * 3.2, v.color, 1.6, 0.3);
        break;
      }
      case "nova": {
        const r = fx.radius ?? 5;
        ps.emit({ x, y: y + 0.05, z, life: 0.4, size: 0.5, size1: r * 1.05, color: v.color, shape: "ring", ground: true, alpha: 1 });
        ps.emit({ x, y: y + 0.08, z, life: 0.3, size: r * 0.3, size1: r * 0.95, color: v.color2, ground: true, alpha: 0.35 });
        const n = this.n(18 + r * 3);
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.6, y: y + 0.3 + R() * 0.5, z: z + Math.sin(a) * 0.6, vx: Math.cos(a) * r * 2.6, vy: R() * 2, vz: Math.sin(a) * r * 2.6, life: 0.35 + R() * 0.2, size: 0.35 * v.size, size1: 0.1, color: v.color, color1: v.color2, shape: v.shape, drag: 3, spin: RS() * 5 });
        }
        this.light(x, y + 0.5, z, r * 2, v.color, 1.4, 0.35);
        break;
      }
      case "cone": {
        const yaw = fx.yaw ?? 0,
          r = fx.radius ?? 6,
          sp = fx.spread ?? 1;
        const n = this.n(22 + r * 2);
        for (let i = 0; i < n; i++) {
          const a = yaw + RS() * sp * 0.5;
          const s = r * (2 + R() * 1.6);
          ps.emit({ x, y: y + RS() * 0.2, z, vx: Math.sin(a) * s, vy: RS() * 0.8, vz: Math.cos(a) * s, life: 0.35 + R() * 0.2, size: 0.25 * v.size, size1: 0.8 * v.size, color: v.color2, color1: v.color, shape: v.shape, drag: 3, spin: RS() * 4 });
        }
        this.light(x, y, z, r * 1.5, v.color, 1, 0.3);
        break;
      }
      case "chain": {
        const p = fx.pts ?? [];
        for (let s = 0; s + 5 < p.length; s += 3) {
          const ax = p[s],
            ay = p[s + 1],
            az = p[s + 2],
            bx = p[s + 3],
            by = p[s + 4],
            bz = p[s + 5];
          const len = Math.hypot(bx - ax, by - ay, bz - az);
          const n = Math.max(3, Math.round(len * 2.5 * this.quality));
          for (let i = 0; i <= n; i++) {
            const t = i / n;
            const j = Math.sin(t * Math.PI) * 0.35;
            ps.emit({ x: ax + (bx - ax) * t + RS() * j, y: ay + (by - ay) * t + RS() * j, z: az + (bz - az) * t + RS() * j, life: 0.18 + R() * 0.08, size: 0.32 * v.size, size1: 0.1, color: v.color2, color1: v.color });
          }
          ps.emit({ x: bx, y: by, z: bz, life: 0.25, size: 0.9, size1: 0.3, color: v.color, shape: v.shape === "bolt" ? "bolt" : "star", rot: RS() });
          this.light(bx, by, bz, 4, v.color, 1, 0.2);
        }
        break;
      }
      case "heal": {
        const sh: ParticleShape = v.shape === "leaf" ? "leaf" : v.shape === "cross" ? "cross" : "heart";
        for (let i = 0; i < this.n(10); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.6, y: y + R() * 1.2, z: z + Math.sin(a) * 0.6, vy: 1.5 + R(), life: 0.9 + R() * 0.4, size: 0.22, size1: 0.1, color: 0x7aff8a, color1: 0xeaffb0, shape: sh });
        }
        ps.emit({ x, y: y + 0.05, z, life: 0.5, size: 0.4, size1: 1.8, color: 0x7aff8a, shape: "ring", ground: true, alpha: 0.7 });
        this.light(x, y + 1, z, 5, 0x7aff8a, 1, 0.4);
        break;
      }
      case "buff":
        for (let i = 0; i < this.n(12); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.7, y: y + 0.2, z: z + Math.sin(a) * 0.7, vy: 2 + R() * 2, life: 0.8, size: 0.2, size1: 0.05, color: v.color, color1: 0xffffff, shape: "star", spin: 4 });
        }
        ps.emit({ x, y: y + 0.05, z, life: 0.5, size: 0.5, size1: 2.2, color: v.color, shape: "ring", ground: true });
        break;
      case "shield":
        ps.emit({ x, y: y + 0.7 * (fx.radius ?? 1), z, life: 0.6, size: 1.5 * (fx.radius ?? 1), size1: 1.2 * (fx.radius ?? 1), color: v.color, shape: "bubble", alpha: 0.7 });
        for (let i = 0; i < this.n(8); i++) ps.emit({ x: x + RS() * 0.8, y: y + R() * 1.4, z: z + RS() * 0.8, vy: 1, life: 0.6, size: 0.15, color: v.color2, shape: "diamond" });
        break;
      case "summon":
        ps.emit({ x, y: y + 0.05, z, life: 0.6, size: 0.3, size1: (fx.radius ?? 1.5) * 1.4, color: fx.color ?? v.color, shape: "ring", ground: true });
        for (let i = 0; i < this.n(12); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.8, y: y + 0.1, z: z + Math.sin(a) * 0.8, vy: 1.5 + R() * 2, life: 0.8, size: 0.25, size1: 0.05, color: fx.color ?? v.color, shape: "paw", spin: RS() * 3 });
        }
        break;
      case "blink":
        for (let i = 0; i < this.n(16); i++) {
          const a = R() * Math.PI * 2;
          const d = 1.5 + R();
          ps.emit({ x: x + Math.cos(a) * d, y: y + 0.3 + R() * 1.2, z: z + Math.sin(a) * d, vx: -Math.cos(a) * d * 4, vz: -Math.sin(a) * d * 4, life: 0.25, size: 0.25, size1: 0.05, color: v.color, shape: v.shape });
        }
        ps.emit({ x, y: y + 0.8, z, life: 0.2, size: 1.8, size1: 0.2, color: v.color2 });
        break;
      case "leaves":
        // Листья из кроны, когда кот в неё прыгает
        for (let i = 0; i < this.n(10); i++) {
          const a = R() * Math.PI * 2;
          const r = (fx.radius ?? 1) * R();
          ps.emit({
            x: x + Math.cos(a) * r,
            y: y + R() * 0.6,
            z: z + Math.sin(a) * r,
            vx: Math.cos(a) * 1.2,
            vy: 0.6 + R() * 1.2,
            vz: Math.sin(a) * 1.2,
            life: 1.6 + R() * 1.2,
            size: 0.14 + R() * 0.08,
            color: fx.color ?? 0x6aa84a,
            shape: "leaf",
            spin: RS() * 5,
            gravity: 2.2,
            drag: 1.4,
            additive: false,
          });
        }
        break;
      case "dust":
        for (let i = 0; i < this.n(8); i++) {
          const a = R() * Math.PI * 2;
          const r = fx.radius ?? 1;
          ps.emit({ x: x + Math.cos(a) * r * 0.5, y: y + 0.15, z: z + Math.sin(a) * r * 0.5, vx: Math.cos(a) * 2, vy: 0.6, vz: Math.sin(a) * 2, life: 0.7 + R() * 0.4, size: 0.4, size1: 1.0, color: 0x9a8a78, alpha: 0.45, shape: "smoke", additive: false, drag: 2 });
        }
        break;
      case "levelup":
        for (let i = 0; i < this.n(36); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.9, y: y + R() * 0.5, z: z + Math.sin(a) * 0.9, vy: 3 + R() * 4, life: 1.1 + R() * 0.5, size: 0.3, size1: 0.05, color: fx.color ?? 0xffd24a, color1: 0xffffff, shape: "star", spin: 5, drag: 0.8 });
        }
        ps.emit({ x, y: y + 0.05, z, life: 0.8, size: 0.5, size1: 4, color: fx.color ?? 0xffd24a, shape: "ring", ground: true });
        this.light(x, y + 1.5, z, 10, fx.color ?? 0xffd24a, 2, 0.8);
        break;
      case "death":
        for (let i = 0; i < this.n(6); i++) ps.emit({ x: x + RS() * 0.5, y: y + 0.5 + R() * 0.5, z: z + RS() * 0.5, vy: 0.8 + R(), life: 1 + R() * 0.5, size: 0.5, size1: 1.2, color: fx.color ?? 0x8a8090, alpha: 0.35, shape: "smoke", additive: false, drag: 1 });
        for (let i = 0; i < this.n(5); i++) {
          const a = (i / 5) * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.4, y: y + 1.0, z: z + Math.sin(a) * 0.4, vx: Math.cos(a + 1.5) * 1.5, vy: 0.8, vz: Math.sin(a + 1.5) * 1.5, life: 1.2, size: 0.22, size1: 0.05, color: 0xffe066, shape: "star", spin: 6, drag: 1 });
        }
        break;
      case "loot":
        for (let i = 0; i < this.n(8); i++) ps.emit({ x: x + RS() * 0.4, y: y + 0.3, z: z + RS() * 0.4, vy: 2 + R() * 2, life: 0.7, size: 0.2, size1: 0.05, color: fx.color ?? 0xffd24a, shape: "star", gravity: 3 });
        break;
      case "telegraph":
        this.telegraphs.push({ x, y, z, r: fx.radius ?? 2, color: fx.color ?? 0xff4a3a, t: 0, dur: fx.dur ?? 1 });
        break;
      case "hitspark":
        for (let i = 0; i < this.n(5); i++) ps.emit({ x, y, z, vx: RS() * 5, vy: R() * 4, vz: RS() * 5, life: 0.15 + R() * 0.1, size: 0.18, size1: 0.02, color: v.color2, shape: "spark", stretch: 1, gravity: 8 });
        break;
      case "cast":
        for (let i = 0; i < this.n(8); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 0.5, y: y + 0.2, z: z + Math.sin(a) * 0.5, vx: -Math.sin(a) * 1.5, vy: 1.2 + R(), vz: Math.cos(a) * 1.5, life: 0.5, size: 0.2 * v.size, size1: 0.05, color: v.color, shape: v.shape, spin: 4 });
        }
        break;
      case "trail": {
        const p = fx.pts ?? [];
        if (p.length >= 6) {
          const n = this.n(14);
          for (let i = 0; i < n; i++) {
            const t = i / n;
            ps.emit({ x: p[0] + (p[3] - p[0]) * t, y: p[1] + RS() * 0.3, z: p[2] + (p[5] - p[2]) * t, life: 0.35 + R() * 0.2, size: 0.4 * v.size, size1: 0.05, color: v.color, shape: v.shape, alpha: 0.8 });
          }
        }
        break;
      }
      case "portal":
        for (let i = 0; i < this.n(20); i++) {
          const a = R() * Math.PI * 2;
          ps.emit({ x: x + Math.cos(a) * 1.5, y: y + R() * 2.5, z: z + Math.sin(a) * 1.5, vx: -Math.sin(a) * 3, vy: 0.5, vz: Math.cos(a) * 3, life: 0.8, size: 0.25, size1: 0.05, color: fx.color ?? 0x8fd0ff, shape: "star", drag: 1 });
        }
        break;
    }
  }

  /** Непрерывные эффекты: снаряды, области, статусы. */
  frame(dt: number, projectiles: Projectile[], areas: Area[], entities: Iterable<Entity>, time: number, decals: Decal[], lights: PointLight[]) {
    const ps = this.ps;
    this.acc += dt;
    const tick = this.acc > 0.05;
    if (tick) this.acc = 0;
    for (const p of projectiles) {
      const v = p.visual;
      ps.immediateOne({ x: p.x, y: p.y, z: p.z, life: 1, size: 0.55 * v.size, color: v.color2, shape: "circle", alpha: 0.95 });
      ps.immediateOne({ x: p.x, y: p.y, z: p.z, life: 1, size: 0.42 * v.size, color: v.color, shape: v.shape, rot: time * 8 + p.id, alpha: 1 });
      if (v.trail || tick) ps.emit({ x: p.x + RS() * 0.1, y: p.y + RS() * 0.1, z: p.z + RS() * 0.1, life: 0.25 + R() * 0.15, size: 0.3 * v.size, size1: 0.02, color: v.color, color1: v.color2, shape: v.trail ? "circle" : v.shape, alpha: 0.8 });
      if (lights.length < 12) lights.push({ x: p.x, y: p.y, z: p.z, radius: 4.5, color: v.color, intensity: 0.9 });
    }
    for (const a of areas) {
      const v = a.visual;
      const el = a.el;
      switch (a.kind) {
        case "ground":
          decals.push({ x: a.x, y: a.y, z: a.z, r: a.radius, color: v.color, mode: 1, progress: 1, alpha: Math.min(1, a.t * 2) });
          if (tick) this.elementPuff(el, a.x + RS() * a.radius * 0.7, a.y, a.z + RS() * a.radius * 0.7, v);
          break;
        case "aura":
          decals.push({ x: a.x, y: a.y, z: a.z, r: a.radius, color: v.color, mode: 0, progress: 1, alpha: Math.min(1, a.t * 2) });
          if (tick)
            for (let i = 0; i < 2; i++) {
              const ang = R() * Math.PI * 2;
              ps.emit({ x: a.x + Math.cos(ang) * a.radius, y: a.y + 0.2, z: a.z + Math.sin(ang) * a.radius, vy: 1.5, vx: -Math.sin(ang) * 1.5, vz: Math.cos(ang) * 1.5, life: 0.6, size: 0.25, size1: 0.05, color: v.color, shape: v.shape });
            }
          break;
        case "totem": {
          for (let i = 0; i < 3; i++) ps.immediateOne({ x: a.x, y: a.y + 0.4 + i * 0.55 + Math.sin(time * 3 + i) * 0.05, z: a.z, life: 1, size: 0.45 - i * 0.08, color: i === 2 ? v.color2 : v.color, shape: i === 2 ? "star" : "ring", rot: time * (i + 1), alpha: 0.9 });
          decals.push({ x: a.x, y: a.y, z: a.z, r: 1.2, color: v.color, mode: 0, progress: 1, alpha: 0.8 });
          if (tick) ps.emit({ x: a.x, y: a.y + 1.6, z: a.z, vy: 0.8, life: 0.5, size: 0.2, size1: 0.02, color: v.color, shape: v.shape });
          if (lights.length < 12) lights.push({ x: a.x, y: a.y + 1.5, z: a.z, radius: 5, color: v.color, intensity: 0.8 });
          break;
        }
        case "trap":
          decals.push({ x: a.x, y: a.y, z: a.z, r: a.radius * 0.5, color: a.armed > 0 ? 0x888888 : v.color, mode: 0, progress: 1, alpha: 0.9 });
          ps.immediateOne({ x: a.x, y: a.y + 0.08, z: a.z, life: 1, size: 0.55, color: v.color, shape: "claw", ground: true, rot: time, alpha: 0.9 });
          break;
        case "wall": {
          const n = Math.max(3, Math.round(a.length * 1.2));
          const hx = Math.sin(a.angle) * a.length * 0.5,
            hz = Math.cos(a.angle) * a.length * 0.5;
          if (tick)
            for (let i = 0; i < n; i++) {
              const t = i / (n - 1) - 0.5;
              const wx = a.x + hx * 2 * t,
                wz = a.z + hz * 2 * t;
              this.elementPuff(el, wx + RS() * 0.2, a.y, wz + RS() * 0.2, v, 1.4);
            }
          break;
        }
        case "vortex":
          decals.push({ x: a.x, y: a.y, z: a.z, r: a.radius, color: v.color, mode: 0, progress: 1, alpha: 0.9 });
          if (tick)
            for (let i = 0; i < 4; i++) {
              const ang = R() * Math.PI * 2;
              const d = a.radius * (0.4 + R() * 0.6);
              ps.emit({ x: a.x + Math.cos(ang) * d, y: a.y + 0.3 + R() * 1.5, z: a.z + Math.sin(ang) * d, vx: -Math.sin(ang) * 6 - Math.cos(ang) * 2, vz: Math.cos(ang) * 6 - Math.sin(ang) * 2, vy: 0.5, life: 0.6, size: 0.3, size1: 0.05, color: v.color, shape: v.shape, drag: 1 });
            }
          break;
        case "rain":
          decals.push({ x: a.x, y: a.y, z: a.z, r: a.radius, color: v.color, mode: 0, progress: 1, alpha: 0.5 });
          if (tick)
            for (let i = 0; i < 3; i++) {
              const ang = R() * Math.PI * 2;
              const d = Math.sqrt(R()) * a.radius;
              ps.emit({ x: a.x + Math.cos(ang) * d, y: a.y + 8, z: a.z + Math.sin(ang) * d, vy: -18, life: 0.45, size: 0.3 * v.size, color: v.color, shape: el === "frost" ? "snow" : v.shape, stretch: el === "lightning" ? 0 : 1 });
            }
          break;
        case "orbit": {
          const n = a.count;
          for (let i = 0; i < n; i++) {
            const ang = time * 3 + (i / n) * Math.PI * 2;
            const ox = a.x + Math.sin(ang) * a.radius,
              oz = a.z + Math.cos(ang) * a.radius;
            ps.immediateOne({ x: ox, y: a.y + 1, z: oz, life: 1, size: 0.6 * v.size, color: v.color2, alpha: 0.9 });
            ps.immediateOne({ x: ox, y: a.y + 1, z: oz, life: 1, size: 0.45 * v.size, color: v.color, shape: v.shape, rot: time * 6 });
            if (tick) ps.emit({ x: ox, y: a.y + 1, z: oz, life: 0.3, size: 0.3, size1: 0.02, color: v.color });
          }
          break;
        }
        case "beam": {
          const ex = Math.sin(a.angle),
            ez = Math.cos(a.angle);
          const n = Math.round(a.length * 2.2);
          for (let i = 1; i <= n; i++) {
            const t = i / n;
            const bx = a.x + ex * a.length * t,
              bz = a.z + ez * a.length * t;
            ps.immediateOne({ x: bx, y: a.y + 0.9, z: bz, life: 1, size: 0.55 + Math.sin(time * 30 + i) * 0.08, color: i % 2 ? v.color : v.color2, alpha: 0.85 });
          }
          if (tick) ps.emit({ x: a.x + ex * a.length, y: a.y + 0.9, z: a.z + ez * a.length, vx: RS() * 3, vy: R() * 3, vz: RS() * 3, life: 0.3, size: 0.3, size1: 0.02, color: v.color2, shape: v.shape });
          if (lights.length < 12) lights.push({ x: a.x + ex * a.length * 0.5, y: a.y + 1, z: a.z + ez * a.length * 0.5, radius: a.length * 0.8, color: v.color, intensity: 1 });
          break;
        }
      }
    }
    // Статусы на сущностях
    for (const e of entities) {
      if (!e.alive || !e.statuses.length) continue;
      const top = e.y + (1.35 + 0.2 * e.look.headSize) * e.look.size;
      for (const s of e.statuses) {
        switch (s.kind) {
          case "dot":
            if (tick && R() < 0.5) this.elementPuff(s.el ?? "fire", e.x + RS() * 0.4, e.y + 0.4 * e.look.size, e.z + RS() * 0.4, undefined, 0.8);
            break;
          case "stun":
          case "freeze":
            if (s.kind === "stun")
              for (let i = 0; i < 3; i++) {
                const ang = time * 5 + (i / 3) * Math.PI * 2;
                ps.immediateOne({ x: e.x + Math.cos(ang) * 0.4, y: top + 0.15, z: e.z + Math.sin(ang) * 0.4, life: 1, size: 0.18, color: 0xffe066, shape: "star", rot: time * 4 });
              }
            else if (tick && R() < 0.3) ps.emit({ x: e.x + RS() * 0.4, y: e.y + R() * e.look.size, z: e.z + RS() * 0.4, life: 0.6, size: 0.2, color: 0xbff4ff, shape: "snow" });
            break;
          case "charm":
            ps.immediateOne({ x: e.x, y: top + 0.3 + Math.sin(time * 4) * 0.08, z: e.z, life: 1, size: 0.3, color: 0xff7ab8, shape: "heart" });
            break;
          case "fear":
            ps.immediateOne({ x: e.x, y: top + 0.3, z: e.z, life: 1, size: 0.3, color: 0xb07aff, shape: "skull" });
            break;
          case "mark":
            decals.push({ x: e.x, y: e.y, z: e.z, r: 0.9 * e.look.size, color: 0xff5a3a, mode: 3, progress: 1, alpha: 0.9 });
            break;
          case "buff":
            if (tick && R() < 0.15) ps.emit({ x: e.x + RS() * 0.5, y: e.y + R() * e.look.size, z: e.z + RS() * 0.5, vy: 1.2, life: 0.6, size: 0.15, color: 0xffe68a, shape: "star" });
            break;
        }
      }
      if (e.shield > 0) ps.immediateOne({ x: e.x, y: e.y + 0.6 * e.look.size, z: e.z, life: 1, size: 1.1 * e.look.size, color: 0x8fd0ff, shape: "bubble", alpha: 0.35 });
    }
    // Телеграфы
    for (let i = this.telegraphs.length - 1; i >= 0; i--) {
      const t = this.telegraphs[i];
      t.t += dt;
      if (t.t >= t.dur) {
        this.telegraphs.splice(i, 1);
        continue;
      }
      decals.push({ x: t.x, y: t.y, z: t.z, r: t.r, color: t.color, mode: 2, progress: t.t / t.dur, alpha: 1 });
    }
    // Вспышки
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i];
      f.t += dt;
      if (f.t >= f.dur) {
        this.flashes.splice(i, 1);
        continue;
      }
      const k = 1 - f.t / f.dur;
      lights.push({ x: f.x, y: f.y, z: f.z, radius: f.r, color: f.color, intensity: f.i * k });
    }
    this.ps.update(dt);
  }

  elementPuff(el: Element, x: number, y: number, z: number, v?: SkillVisual, scale = 1) {
    const ps = this.ps;
    const info = ELEMENT_INFO[el];
    switch (el) {
      case "fire":
        ps.emit({ x, y: y + 0.1, z, vy: 2 + R() * 1.5, vx: RS() * 0.3, vz: RS() * 0.3, life: 0.5 + R() * 0.3, size: 0.45 * scale, size1: 0.1, color: 0xffd24a, color1: 0xff4a1a, shape: "flame" });
        break;
      case "poison":
        ps.emit({ x, y: y + 0.1, z, vy: 1 + R(), life: 0.8, size: 0.2 * scale, size1: 0.35 * scale, color: 0x8aff5a, shape: "bubble", alpha: 0.8 });
        break;
      case "frost":
        ps.emit({ x, y: y + 0.2, z, vy: 0.6, life: 0.8, size: 0.3 * scale, size1: 0.05, color: 0xbff4ff, shape: "snow", spin: 2 });
        break;
      case "lightning":
        ps.emit({ x, y: y + 0.3 + R() * 0.8, z, life: 0.12, size: 0.5 * scale, color: 0xffffa8, shape: "bolt", rot: RS() });
        break;
      case "holy":
        ps.emit({ x, y: y + 0.1, z, vy: 1.5, life: 0.8, size: 0.22 * scale, size1: 0.05, color: 0xfff0a0, shape: "cross" });
        break;
      case "shadow":
        ps.emit({ x, y: y + 0.2, z, vy: 0.8, life: 1, size: 0.4 * scale, size1: 0.9 * scale, color: 0x5a2a8a, alpha: 0.5, shape: "smoke", additive: false });
        break;
      case "nature":
        ps.emit({ x, y: y + 0.2, z, vy: 1, vx: RS(), vz: RS(), life: 0.9, size: 0.25 * scale, color: 0x6ae05a, shape: "leaf", spin: 3 });
        break;
      case "blood":
        ps.emit({ x, y: y + 0.3, z, vy: 1.5, life: 0.6, size: 0.18 * scale, color: 0xff3a4a, shape: "circle", gravity: 6 });
        break;
      case "arcane":
        ps.emit({ x, y: y + 0.2, z, vy: 1, life: 0.8, size: 0.28 * scale, size1: 0.05, color: 0xff7aff, shape: "rune", spin: 2 });
        break;
      default:
        ps.emit({ x, y: y + 0.1, z, vy: 0.5, life: 0.6, size: 0.3 * scale, size1: 0.6 * scale, color: v?.color ?? info.color, alpha: 0.4, shape: "smoke", additive: false });
    }
  }
}
