/**
 * Основной сюжет: «Девять колокольчиков».
 * Давным-давно Великий Кот повесил на небо девять колокольчиков, и их звон держал Тьму за горизонтом.
 * Бездонный Мурлык украл их и раздал своим стражам. Собери колокольчики — и одолей его.
 * В бесконечном режиме после девятого колокольчика начинаются новые «эпохи» — без конца.
 */
import type { Txt } from "../../core/i18n";
import { dist } from "../../core/math";
import { priceScale, questXp } from "../progression";
import type { Poi, Region, Town, WorldGen } from "../world/worldgen";
import { REGION } from "../world/worldgen";
import type { QuestDef } from "./types";
import { roman } from "../skills/vocab";

export interface StoryChapter {
  index: number;
  level: number;
  region: Region;
  town: Town;
  elderId: string;
  poi: Poi;
  bell: Txt;
  final: boolean;
}

const BELLS: Txt[] = [
  { ru: "Колокольчик Рассвета", en: "Bell of Dawn" },
  { ru: "Колокольчик Листвы", en: "Bell of Leaves" },
  { ru: "Колокольчик Ветра", en: "Bell of Wind" },
  { ru: "Колокольчик Песков", en: "Bell of Sands" },
  { ru: "Колокольчик Приливов", en: "Bell of Tides" },
  { ru: "Колокольчик Инея", en: "Bell of Frost" },
  { ru: "Колокольчик Пламени", en: "Bell of Flame" },
  { ru: "Колокольчик Кристаллов", en: "Bell of Crystals" },
  { ru: "Колокольчик Тени", en: "Bell of Shadow" },
];

const chapterCache = new Map<string, StoryChapter | null>();

export function chapterLevel(k: number, infinite: boolean): number {
  if (!infinite && k >= 9) return 97;
  return 4 + k * 10;
}

export function isFinalChapter(k: number, infinite: boolean): boolean {
  return !infinite && k === 9;
}

export function storyChapter(gen: WorldGen, k: number): StoryChapter | null {
  const key = `${gen.seed}|${gen.infinite}|${k}`;
  if (chapterCache.has(key)) return chapterCache.get(key)!;
  const L = chapterLevel(k, gen.infinite);
  const srx = Math.floor(gen.start.x / REGION),
    srz = Math.floor(gen.start.z / REGION);
  let best: { r: Region; score: number } | null = null;
  if (k === 0) {
    const r = gen.region(srx, srz);
    if (r.town) {
      const d = r.pois.find((p) => p.kind === "dungeon") ?? null;
      if (d) best = { r, score: 0 };
    }
  }
  // Ожидаемое расстояние (в регионах) до нужного уровня
  const expected = gen.infinite ? ((L - 1) * 150 + 220) / REGION : (Math.pow((L - 1) / 99, 1 / 1.05) * 8600 + 220) / REGION;
  const rMin = Math.max(0, Math.floor(expected - 4)),
    rMax = Math.ceil(expected + 6);
  for (let rad = rMin; rad <= rMax && !best; rad++) {
    const steps = Math.max(8, rad * 8);
    for (let i = 0; i < steps; i++) {
      // для кампании идём в основном на север (где растёт сложность)
      const a = gen.infinite ? (i / steps) * Math.PI * 2 + k * 0.7 : -Math.PI / 2 + ((i / steps) - 0.5) * Math.PI * 1.6;
      const rx = srx + Math.round(Math.cos(a) * rad);
      const rz = srz + Math.round(Math.sin(a) * rad);
      const r = gen.region(rx, rz);
      if (!r.town || Math.abs(r.level - L) > 4) continue;
      const d = r.pois.find((p) => p.kind === "dungeon");
      if (!d) continue;
      const score = Math.abs(r.level - L) + dist(rx, rz, srx, srz) * 0.01;
      if (!best || score < best.score) best = { r, score };
    }
    if (best) break;
  }
  if (!best) {
    chapterCache.set(key, null);
    return null;
  }
  const r = best.r;
  const town = r.town!;
  const elder = town.npcs.find((n) => n.role === "elder") ?? town.npcs[0];
  const poi = r.pois.find((p) => p.kind === "dungeon")!;
  const final = isFinalChapter(k, gen.infinite);
  const era = Math.floor(k / 9);
  const bellBase = BELLS[k % 9];
  const bell: Txt = final
    ? { ru: "Бездонный Мурлык", en: "The Bottomless Purr" }
    : era === 0
      ? bellBase
      : { ru: `${bellBase.ru} (Эпоха ${roman(era + 1)})`, en: `${bellBase.en} (Era ${roman(era + 1)})` };
  const ch: StoryChapter = { index: k, level: L, region: r, town, elderId: elder.id, poi, bell, final };
  chapterCache.set(key, ch);
  return ch;
}

export function storyQuest(gen: WorldGen, k: number, step: number): QuestDef | null {
  const ch = storyChapter(gen, k);
  if (!ch) return null;
  const id = `story:${k}:${step}`;
  const lvl = ch.level;
  const title: Txt = ch.final
    ? { ru: "Финал: Бездонный Мурлык", en: "Finale: The Bottomless Purr" }
    : { ru: `Глава ${k + 1}: ${ch.bell.ru}`, en: `Chapter ${k + 1}: ${ch.bell.en}` };
  const townName = ch.town.name;
  const boss = ch.final ? { ru: "Бездонный Мурлык", en: "the Bottomless Purr" } : ch.poi.bossName!;
  let intro: Txt, done: Txt;
  let objectives: QuestDef["objectives"];
  if (step === 0) {
    intro =
      k === 0
        ? {
            ru: "Давным-давно Великий Кот повесил на небо девять колокольчиков, и их звон держал Тьму за горизонтом. Но Бездонный Мурлык украл их и раздал своим стражам. Без их звона мир остывает, а коты забывают, как мурлыкать. Поговори со старейшиной — он знает, где искать первый колокольчик.",
            en: "Long ago the Great Cat hung nine bells in the sky, and their chime kept the Darkness beyond the horizon. But the Bottomless Purr stole them and gave them to its guardians. Without their chime the world grows cold and cats forget how to purr. Speak to the elder — they know where to find the first bell.",
          }
        : { ru: `След колокольчика ведёт в ${townName.ru}. Найди там старейшину.`, en: `The bell's trail leads to ${townName.en}. Find the elder there.` };
    objectives = [{ k: "talk", npcId: ch.elderId, townId: ch.town.id, at: { x: ch.town.x, z: ch.town.z, r: ch.town.radius }, label: { ru: `Поговорить со старейшиной (${townName.ru})`, en: `Talk to the elder (${townName.en})` } }];
    done = { ru: "Мр-р… Я ждал тебя, путник.", en: "Mrrr… I've been waiting for you, traveler." };
  } else if (step === 1) {
    intro = ch.final
      ? { ru: `Все колокольчики собраны, но Тьма ещё здесь. В «${ch.poi.name.ru}» ждёт сам Бездонный Мурлык. Иди — и пусть твой хвост не дрогнет.`, en: `All the bells are gathered, yet the Darkness remains. In "${ch.poi.name.en}" the Bottomless Purr itself awaits. Go — and may your tail not tremble.` }
      : { ru: `${ch.bell.ru} охраняет ${boss.ru} в подземелье «${ch.poi.name.ru}». Верни его!`, en: `${ch.bell.en} is guarded by ${boss.en} in the dungeon "${ch.poi.name.en}". Bring it back!` };
    objectives = [{ k: "dungeon", poiId: ch.poi.id, at: { x: ch.poi.x, z: ch.poi.z, r: 8 }, label: { ru: `Одолеть: ${boss.ru}`, en: `Defeat ${boss.en}` } }];
    done = { ru: "Звон! Ты слышишь? Колокольчик снова поёт!", en: "A chime! Do you hear it? The bell sings again!" };
  } else {
    intro = { ru: `Верни ${ch.bell.ru.toLowerCase()} старейшине в ${townName.ru}.`, en: `Return the ${ch.bell.en.toLowerCase()} to the elder in ${townName.en}.` };
    objectives = [{ k: "talk", npcId: ch.elderId, townId: ch.town.id, at: { x: ch.town.x, z: ch.town.z, r: ch.town.radius }, label: { ru: `Вернуться к старейшине (${townName.ru})`, en: `Return to the elder (${townName.en})` } }];
    done = ch.final
      ? { ru: "Тьма отступила! Мир снова мурлычет. Ты — легенда всех кошачьих земель.", en: "The Darkness recedes! The world purrs again. You are a legend of all cat lands." }
      : { ru: "Спасибо, герой! Мир стал чуточку теплее. Но колокольчиков ещё много…", en: "Thank you, hero! The world is a little warmer now. But many bells remain…" };
  }
  return {
    id,
    kind: "story",
    giverNpcId: ch.elderId,
    townId: ch.town.id,
    title,
    intro,
    done,
    level: lvl,
    objectives,
    reward:
      step === 2
        ? { xp: questXp(lvl, 5), fish: Math.round(60 * priceScale(lvl)), item: { rarity: ch.final ? 5 : 4 }, skillPoints: 2, tome: true }
        : { xp: questXp(lvl, step === 1 ? 2 : 0.5), fish: Math.round(10 * priceScale(lvl)), item: null, skillPoints: 0, tome: false },
    requires: null,
    chain: { step: step + 1, total: 3 },
    turnInNpcId: null,
  };
}
