/**
 * Кэш высот и содержимого чанков для физики, ИИ и рендера.
 * Сетка 33×33 на чанк (шаг 1 ед.), билинейная интерполяция высоты.
 */
import { CHUNK, type ChunkContent, type TerrainSample, WorldGen } from "./worldgen";
import type { BiomeId } from "./biomes";

export const GRID = CHUNK + 1;

export interface ChunkSamples {
  cx: number;
  cz: number;
  h: Float32Array;
  biomeA: BiomeId[];
  biomeB: BiomeId[];
  w: Float32Array;
  road: Float32Array;
  town: Float32Array;
  poi: Float32Array;
  plaza: Float32Array;
  minH: number;
  maxH: number;
}

const key = (cx: number, cz: number) => (cx + 1048576) * 2097152 + (cz + 1048576);

export class TerrainCache {
  private samples = new Map<number, ChunkSamples>();
  private contents = new Map<number, ChunkContent>();
  private tmp: TerrainSample = { h: 0, biomeA: "meadow", biomeB: "meadow", w: 0, road: 0, town: 0, poi: 0, plaza: 0 };

  constructor(readonly gen: WorldGen) {}

  chunkSamples(cx: number, cz: number): ChunkSamples {
    const k = key(cx, cz);
    let s = this.samples.get(k);
    if (s) {
      // LRU: переставляем в конец
      this.samples.delete(k);
      this.samples.set(k, s);
      return s;
    }
    const n = GRID * GRID;
    s = {
      cx,
      cz,
      h: new Float32Array(n),
      biomeA: new Array(n),
      biomeB: new Array(n),
      w: new Float32Array(n),
      road: new Float32Array(n),
      town: new Float32Array(n),
      poi: new Float32Array(n),
      plaza: new Float32Array(n),
      minH: Infinity,
      maxH: -Infinity,
    };
    const x0 = cx * CHUNK;
    const z0 = cz * CHUNK;
    const t = this.tmp;
    for (let j = 0; j < GRID; j++) {
      for (let i = 0; i < GRID; i++) {
        this.gen.sample(x0 + i, z0 + j, t);
        const idx = j * GRID + i;
        s.h[idx] = t.h;
        s.biomeA[idx] = t.biomeA;
        s.biomeB[idx] = t.biomeB;
        s.w[idx] = t.w;
        s.road[idx] = t.road;
        s.town[idx] = t.town;
        s.poi[idx] = t.poi;
        s.plaza[idx] = t.plaza;
        if (t.h < s.minH) s.minH = t.h;
        if (t.h > s.maxH) s.maxH = t.h;
      }
    }
    this.samples.set(k, s);
    if (this.samples.size > 500) {
      const first = this.samples.keys().next().value;
      if (first !== undefined) this.samples.delete(first);
    }
    return s;
  }

  hasSamples(cx: number, cz: number) {
    return this.samples.has(key(cx, cz));
  }

  content(cx: number, cz: number): ChunkContent {
    const k = key(cx, cz);
    let c = this.contents.get(k);
    if (c) return c;
    c = this.gen.chunkContent(cx, cz);
    this.contents.set(k, c);
    if (this.contents.size > 900) {
      const first = this.contents.keys().next().value;
      if (first !== undefined) this.contents.delete(first);
    }
    return c;
  }

  hasContent(cx: number, cz: number) {
    return this.contents.has(key(cx, cz));
  }

  /** Высота рельефа в точке (билинейно по кэшу). */
  heightAt(x: number, z: number): number {
    const cx = Math.floor(x / CHUNK);
    const cz = Math.floor(z / CHUNK);
    const s = this.chunkSamples(cx, cz);
    const lx = x - cx * CHUNK;
    const lz = z - cz * CHUNK;
    const i = Math.min(CHUNK - 1, Math.floor(lx));
    const j = Math.min(CHUNK - 1, Math.floor(lz));
    const fx = lx - i;
    const fz = lz - j;
    const h = s.h;
    const a = h[j * GRID + i];
    const b = h[j * GRID + i + 1];
    const c = h[(j + 1) * GRID + i];
    const d = h[(j + 1) * GRID + i + 1];
    return (a * (1 - fx) + b * fx) * (1 - fz) + (c * (1 - fx) + d * fx) * fz;
  }

  /** Нормаль рельефа (через конечные разности). */
  normalAt(x: number, z: number): [number, number, number] {
    const e = 0.75;
    const hx = this.heightAt(x + e, z) - this.heightAt(x - e, z);
    const hz = this.heightAt(x, z + e) - this.heightAt(x, z - e);
    const nx = -hx,
      ny = 2 * e,
      nz = -hz;
    const l = Math.hypot(nx, ny, nz);
    return [nx / l, ny / l, nz / l];
  }

  /** Все коллайдеры вокруг точки (3×3 чанка). */
  collidersNear(x: number, z: number, out: { x: number; z: number; r: number }[]): void {
    out.length = 0;
    const cx = Math.floor(x / CHUNK);
    const cz = Math.floor(z / CHUNK);
    for (let j = -1; j <= 1; j++)
      for (let i = -1; i <= 1; i++) {
        const c = this.content(cx + i, cz + j);
        for (const col of c.colliders) out.push(col);
      }
  }
}
