/** Карта, по которой ходят сущности (открытый мир или подземелье). */
export interface WorldMap {
  kind: "overworld" | "dungeon";
  groundAt(x: number, z: number): number;
  blocked(x: number, z: number): boolean;
  resolve(e: Entity): void;
  /** Направление движения к цели с обходом препятствий. */
  pathDir?(e: Entity, tx: number, tz: number): [number, number];
  update?(w: GameWorld, dt: number): void;
}

export type CastResult = "ok" | "cooldown" | "mana" | "disabled" | "busy";

/** Описание сущности хоста, передаваемое гостю при первом появлении. */
export interface MirrorInfo {
  id: number;
  kind: Entity["kind"];
  name: Txt;
  look: CatLook;
  x: number;
  z: number;
  yaw: number;
  level: number;
  hp: number;
  maxHp: number;
  alive: boolean;
  radius: number;
  faction: number;
  classId?: string | null;
  enemy?: { family: string; role: string; elite: boolean; boss: boolean; poiId?: string; named?: Txt };
  npc?: { role: string; npcId: string; townId: string };
  minionOwner?: number;
}

export interface TimedAction {
  t: number;
  fn: () => void;
}

class OverworldMap implements WorldMap {
  kind = "overworld" as const;
  private cols: { x: number; z: number; r: number }[] = [];
  constructor(
    readonly terrain: TerrainCache,
    readonly gen: WorldGen,
  ) {}
  groundAt(x: number, z: number) {
    return this.terrain.heightAt(x, z);
  }
  blocked() {
    return false;
  }
  resolve(e: Entity) {
    this.terrain.collidersNear(e.x, e.z, this.cols);
    for (const c of this.cols) {
      const dx = e.x - c.x,
        dz = e.z - c.z;
      const rr = c.r + e.radius * 0.8;
      const d2 = dx * dx + dz * dz;
      if (d2 < rr * rr && d2 > 1e-6) {
        const d = Math.sqrt(d2);
        e.x = c.x + (dx / d) * rr;
        e.z = c.z + (dz / d) * rr;
      }
    }
    // Граница материка: дальше — открытый океан
    if (!this.gen.infinite) {
      const r = Math.hypot(e.x, e.z);
      const lim = 7900;
      if (r > lim) {
        e.x *= lim / r;
        e.z *= lim / r;
      }
    }
  }
}

export class GameWorld {
  readonly rng = new Rng((Math.random() * 2 ** 31) | 0);
  readonly runtime: SkillRuntime;
  readonly overworld: OverworldMap;
  map: WorldMap;
  time = 0;
  nextId = 1;
  entities = new Map<number, Entity>();
  projectiles: Projectile[] = [];
  areas: Area[] = [];
  timeline: TimedAction[] = [];
  events: GameEvent[] = [];
  /** true — мы хост/одиночная игра: ИИ, урон, спавн. */
  authority = true;
  /** Множитель входящего урона по игрокам (сложность). */
  difficulty = 1;
  /** Уровни в «материк + бесконечные уровни»: враги подтягиваются к игроку. */
  levelFloor = 0;
  private spawnActive = new Map<string, number[]>();
  private spawnDead = new Map<string, number>();
  private npcActive = new Map<string, number>();
  private spawnTimer = 0;
  private sep: Entity[] = [];

  constructor(
    readonly gen: WorldGen,
    readonly terrain: TerrainCache,
    readonly mode: ModeConfig,
  ) {
    this.runtime = new SkillRuntime(this);
    this.overworld = new OverworldMap(terrain, gen);
    this.map = this.overworld;
  }

  // ───────────────────────── утилиты ─────────────────────────

  emit(ev: GameEvent) {
    this.events.push(ev);
  }
  fx(fx: Fx) {
    this.events.push({ t: "fx", fx });
  }
  after(t: number, fn: () => void) {
    this.timeline.push({ t, fn });
  }
  groundAt(x: number, z: number) {
    return this.map.groundAt(x, z);
  }
  blocked(x: number, z: number) {
    return this.map.blocked(x, z);
  }
  kill(e: Entity, killerId: number) {
    killEntity(this, e, killerId);
  }

  /** Обрезает перемещение по стенам (для рывков/телепортов). */
  clampMove(x0: number, z0: number, x1: number, z1: number): [number, number] {
    const steps = Math.ceil(dist(x0, z0, x1, z1) / 0.5);
    let lx = x0,
      lz = z0;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const x = lerp(x0, x1, t),
        z = lerp(z0, z1, t);
      if (this.map.blocked(x, z)) break;
      lx = x;
      lz = z;
    }
    return [lx, lz];
  }

  pathDir(e: Entity, tx: number, tz: number): [number, number] {
    if (this.map.pathDir) return this.map.pathDir(e, tx, tz);
    return [tx - e.x, tz - e.z];
  }

  startMotion(e: Entity, x1: number, z1: number, dur: number, arc: number, onEnd?: () => void) {
    e.motion = { t: 0, dur, x0: e.x, z0: e.z, x1, z1, arc, onEnd };
    e.yaw = Math.atan2(x1 - e.x, z1 - e.z);
  }

  nearestHostile(e: Entity, r: number): Entity | null {
    return this.nearestHostileTo(e.x, e.z, e.faction, r);
  }

  nearestHostileTo(x: number, z: number, faction: number, r: number): Entity | null {
    let best: Entity | null = null;
    let bd = r * r;
    for (const o of this.entities.values()) {
      if (!o.alive || o.faction === faction || o.faction === 2) continue;
      if (o.kind === "player" && o.invuln > 5) continue;
      const d = (o.x - x) ** 2 + (o.z - z) ** 2;
      if (d < bd) {
        bd = d;
        best = o;
      }
    }
    return best;
  }

  nearestPlayer(x: number, z: number, r: number): Entity | null {
    let best: Entity | null = null;
    let bd = r * r;
    for (const o of this.entities.values()) {
      if (o.kind !== "player" || !o.alive) continue;
      const d = (o.x - x) ** 2 + (o.z - z) ** 2;
      if (d < bd) {
        bd = d;
        best = o;
      }
    }
    return best;
  }

  players(): Entity[] {
    const out: Entity[] = [];
    for (const e of this.entities.values()) if (e.kind === "player") out.push(e);
    return out;
  }

  // ───────────────────────── создание сущностей ─────────────────────────

  private baseEntity(kind: Entity["kind"], look: CatLook, name: Txt, x: number, z: number): Entity {
    const id = this.nextId++;
    return {
      id,
      kind,
      faction: kind === "enemy" ? 1 : kind === "npc" ? 2 : 0,
      name,
      x,
      y: this.groundAt(x, z),
      z,
      yaw: this.rng.next() * Math.PI * 2,
      vx: 0,
      vz: 0,
      moveX: 0,
      moveZ: 0,
      speed: 0,
      radius: 0.55 * look.size,
      level: 1,
      hp: 100,
      maxHp: 100,
      mp: 0,
      maxMp: 0,
      shield: 0,
      shieldT: 0,
      alive: true,
      deadT: 0,
      look,
      action: null,
      actionT: 0,
      actionDur: 0,
      flash: 0,
      state: "alive",
      stateT: 0,
      statuses: [],
      cds: new Map(),
      cast: null,
      stats: null,
      baseSpeed: 5,
      dmg: 5,
      armor: 5,
      resist: 0.05,
      ai: null,
      enemy: null,
      npc: null,
      minion: null,
      classId: null,
      peer: null,
      motion: null,
      invuln: 0,
      frenzy: 0,
      frenzyT: 0,
      lastCombat: -100,
      nineLivesCd: 0,
      phoenixCd: 0,
      purrT: 8,
      swimming: false,
      climb: null,
      climbPush: 0,
      idleFar: 0,
    };
  }

  addPlayer(o: { classId: ClassId; name: Txt; look: CatLook; level: number; stats: Stats; peer: "local" | "remote"; x: number; z: number; hpFrac?: number; id?: number }): Entity {
    const e = this.baseEntity("player", o.look, o.name, o.x, o.z);
    if (o.id !== undefined) {
      this.nextId = Math.max(this.nextId, o.id + 1);
      e.id = o.id;
    }
    e.classId = o.classId;
    e.peer = o.peer;
    e.level = o.level;
    e.faction = 0;
    this.applyStats(e, o.stats, o.hpFrac ?? 1);
    e.mp = e.maxMp;
    this.entities.set(e.id, e);
    return e;
  }

  applyStats(e: Entity, st: Stats, hpFrac = e.maxHp > 0 ? e.hp / e.maxHp : 1) {
    const mpFrac = e.maxMp > 0 ? e.mp / e.maxMp : 1;
    e.stats = st;
    e.level = st.level;
    e.maxHp = st.maxHp;
    e.maxMp = st.maxMp;
    e.hp = clamp(hpFrac, 0, 1) * e.maxHp;
    e.mp = clamp(mpFrac, 0, 1) * e.maxMp;
    e.baseSpeed = st.moveSpeed;
    e.armor = st.armor;
    e.resist = st.resist;
  }

  spawnEnemy(o: { family: string; role: Role; level: number; x: number; z: number; elite?: boolean; boss?: boolean; spawnKey: string; poiId?: string; named?: Txt; seed?: number; room?: number }): Entity {
    const fam = familyFor(o.family);
    const rng = new Rng(o.seed ?? this.rng.id());
    const elite = !!o.elite,
      boss = !!o.boss;
    const look = enemyLook(rng, fam, o.role, elite, boss);
    const name = o.named ?? enemyName(fam, o.role, elite);
    const e = this.baseEntity("enemy", look, name, o.x, o.z);
    const R = ROLES[o.role];
    const L = Math.max(1, Math.round(o.level));
    const ls = levelScale(L);
    const nPlayers = Math.max(1, this.players().length);
    const coopHp = 1 + (nPlayers - 1) * 0.6;
    e.level = L;
    e.maxHp = 42 * ls * R.hp * (elite ? 4 : 1) * (boss ? 24 : 1) * coopHp;
    e.hp = e.maxHp;
    e.dmg = 6.5 * ls * R.dmg * (elite ? 1.45 : 1) * (boss ? 1.7 : 1);
    e.armor = 12 * ls * (o.role === "tank" ? 2 : 1) * (boss ? 1.5 : 1);
    e.resist = 0.05 + (o.role === "caster" ? 0.1 : 0) + (boss ? 0.1 : 0);
    e.baseSpeed = R.speed * (elite ? 1.08 : 1);
    e.radius = 0.55 * look.size;
    e.enemy = { family: fam.id, role: o.role, elite, boss, xpMul: (elite ? 4 : 1) * (boss ? 25 : 1), spawnKey: o.spawnKey, poiId: o.poiId, named: o.named, dungeonRoom: o.room };
    e.ai = {
      mode: "idle",
      homeX: o.x,
      homeZ: o.z,
      leash: boss ? 60 : 42,
      target: -1,
      t: rng.next() * 3,
      wx: o.x,
      wz: o.z,
      aggro: boss ? 20 : o.role === "kitten" ? 14 : 12.5,
      skills: boss ? bossSkills(fam, rng) : roleSkills(o.role, fam, elite, rng),
      keepDist: R.keepDist,
      phase: 0,
      lastHitBy: -1,
    };
    this.entities.set(e.id, e);
    return e;
  }

  spawnNpc(n: NpcSpawn): Entity {
    const rng = new Rng(n.seed);
    const look = villagerLook(rng);
    if (n.role === "guard") {
      look.hat = "helmet";
      look.hatColor = 0xb8c0c8;
      look.weapon = "sword";
      look.weaponColor = 0xd8e0e8;
      look.bulk = 1.2;
    } else if (n.role === "merchant") {
      look.hat = "straw";
      look.hatColor = 0xd23a3a;
    } else if (n.role === "smith") {
      look.hat = "bandana";
      look.hatColor = 0x3a3a3a;
      look.weapon = "mace";
      look.weaponColor = 0x9a9aa0;
    } else if (n.role === "innkeeper") {
      look.hat = "chef";
    } else if (n.role === "trainer") {
      look.hat = "wizard";
      look.hatColor = 0x3a6aa0;
      look.weapon = "tome";
    } else if (n.role === "elder") {
      look.hat = "crown";
      look.fur = 0xd8d8d0;
      look.fur2 = 0xb8b8b0;
      look.pattern = "solid";
      look.size = 1.05;
    }
    const e = this.baseEntity("npc", look, n.name, n.x, n.z);
    e.faction = 2;
    e.yaw = n.rot;
    e.maxHp = e.hp = 1000;
    e.baseSpeed = 2.5;
    e.npc = { role: n.role, npcId: n.id, townId: n.townId, mood: rng.next() };
    e.ai = { mode: "idle", homeX: n.x, homeZ: n.z, leash: 30, target: -1, t: rng.next() * 4, wx: n.x, wz: n.z, aggro: 0, skills: [], keepDist: 0, phase: 0, lastHitBy: -1 };
    this.entities.set(e.id, e);
    return e;
  }

  summon(owner: Entity, skill: SkillDef, n: number, dur: number, coef: number) {
    // У гостя питомцы создаются хостом и приходят как зеркала
    if (!this.authority) {
      this.fx({ k: "summon", x: owner.x, y: owner.y, z: owner.z, radius: 1.5, v: skill.visual });
      return;
    }
    // Ограничиваем количество — удаляем старых той же способности
    const existing = [...this.entities.values()].filter((m) => m.minion && m.minion.ownerId === owner.id && m.alive && m.name.en === skill.id);
    const extra = existing.length + n - Math.max(n, Math.round(skill.params.count) + (owner.stats?.keystones.has("packLeader") ? 1 : 0));
    for (let i = 0; i < extra && i < existing.length; i++) existing[i].minion!.expires = 0;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + this.rng.next();
      const x = owner.x + Math.cos(a) * 1.8;
      const z = owner.z + Math.sin(a) * 1.8;
      if (owner.kind === "enemy") {
        const k = this.spawnEnemy({ family: owner.enemy!.family, role: "kitten", level: owner.level, x, z, spawnKey: owner.enemy!.spawnKey + ":k" });
        k.ai!.target = owner.ai?.target ?? -1;
        k.ai!.mode = "chase";
        k.minion = { ownerId: owner.id, expires: this.time + dur, skill: k.ai!.skills[0], ranged: false };
        k.kind = "enemy";
        k.enemy!.xpMul = 0.3;
        this.fx({ k: "summon", x, y: k.y, z, radius: 1, v: skill.visual });
        continue;
      }
      const kind = skill.summon?.kind ?? "kitten";
      const look = this.minionLook(owner, kind, skill.element);
      const e = this.baseEntity("minion", look, { ru: "Питомец", en: skill.id }, x, z);
      e.name = { ru: "Питомец", en: skill.id };
      e.faction = owner.faction;
      e.level = owner.level;
      const sp = owner.stats?.summonPct ?? 0;
      e.maxHp = e.hp = owner.maxHp * 0.3 * (1 + sp);
      e.baseSpeed = 6.5;
      e.armor = (owner.stats?.armor ?? 10) * 0.6;
      e.resist = owner.stats?.resist ?? 0.1;
      const ranged = !!skill.summon?.ranged;
      const atk = ranged
        ? enemySkill(`m:${skill.id}`, "projectile", skill.element, "point", { power: coef * 0.9 * (1 + sp), cooldown: 1.3, speed: 18, range: 13, castTime: 0.3 }, skill.onHit, { visual: skill.visual })
        : enemySkill(`m:${skill.id}`, "strike", skill.element, "swipe", { power: coef * (1 + sp), cooldown: 1.0, radius: 1.9, castTime: 0.25 }, skill.onHit, { visual: skill.visual });
      e.stats = null;
      e.dmg = owner.stats ? owner.stats.power : owner.dmg;
      e.minion = { ownerId: owner.id, expires: this.time + dur, skill: atk, ranged };
      e.ai = { mode: "follow", homeX: x, homeZ: z, leash: 99, target: -1, t: 0, wx: x, wz: z, aggro: 13, skills: [atk], keepDist: 0, phase: 0, lastHitBy: -1 };
      this.entities.set(e.id, e);
      this.fx({ k: "summon", x, y: e.y, z, radius: 1, v: skill.visual });
    }
  }

  private minionLook(owner: Entity, kind: string, el: Element): CatLook {
    const base: CatLook = { ...BASE_LOOK, collar: undefined, bell: false, size: 0.6, headSize: 1.2 };
    const c = ELEMENT_INFO[el].color;
    switch (kind) {
      case "ghost":
        return { ...base, fur: 0xcfe8ff, fur2: 0x8ab8ff, pattern: "ghost", alpha: 0.7, glow: 0x9affc0 };
      case "spirit":
        return { ...base, fur: c, fur2: 0xffffff, pattern: "crystal", glow: c, size: 0.65 };
      case "golem":
        return { ...base, fur: 0x8a8a84, fur2: 0x5a5a54, pattern: "mecha", glow: 0xffa03a, size: 0.9, bulk: 1.4 };
      case "beast":
        return { ...base, fur: 0xc8a070, fur2: 0x5a4030, pattern: "spots", tufts: true, tailLen: 0.35, size: 0.9, legLen: 1.15 };
      case "skeleton":
        return { ...base, fur: 0xe8e0d0, fur2: 0x2a2a2a, pattern: "skeleton", glow: 0x7aff9a, size: 0.75 };
      case "treant":
        return { ...base, fur: 0x6a5a3a, fur2: 0x4a9a3a, pattern: "tortie", hat: "leaves", hatColor: 0x4a9a3a, size: 0.85, bulk: 1.3 };
      case "elemental":
        return { ...base, fur: 0x2a2220, fur2: c, pattern: "lava", glow: c, size: 0.75 };
      case "shadow":
        return { ...owner.look, fur: 0x16121e, fur2: 0x9a5aff, pattern: "void", alpha: 0.65, glow: 0xc08aff, size: owner.look.size * 0.9 };
      default:
        return { ...base, fur: owner.look.fur, fur2: owner.look.fur2, pattern: owner.look.pattern, eyes: owner.look.eyes };
    }
  }

  /** Гость: создать зеркало сущности хоста по описанию из сети. */
  addMirror(m: MirrorInfo): Entity {
    const e = this.baseEntity(m.kind, m.look, m.name, m.x, m.z);
    e.faction = m.faction as Entity["faction"];
    e.level = m.level;
    e.maxHp = m.maxHp;
    e.hp = m.hp;
    e.alive = m.alive;
    e.state = m.alive ? "alive" : "dead";
    e.yaw = m.yaw;
    e.radius = m.radius;
    e.baseSpeed = 5;
    e.classId = (m.classId ?? null) as Entity["classId"];
    e.peer = m.kind === "player" ? "remote" : null;
    if (m.enemy) e.enemy = { family: m.enemy.family, role: m.enemy.role as Role, elite: m.enemy.elite, boss: m.enemy.boss, xpMul: 1, spawnKey: "net", poiId: m.enemy.poiId, named: m.enemy.named };
    if (m.npc) e.npc = { role: m.npc.role as NpcSpawn["role"], npcId: m.npc.npcId, townId: m.npc.townId, mood: 0.5 };
    if (m.minionOwner !== undefined) e.minion = { ownerId: m.minionOwner, expires: Infinity, skill: null as unknown as SkillDef, ranged: false };
    e.net = { tx: m.x, tz: m.z, tyaw: m.yaw };
    this.entities.set(e.id, e);
    return e;
  }

  // ───────────────────────── применение навыков ─────────────────────────

  /**
   * Попытка применить навык. force — без проверок отката/маны/контроля: каст, уже
   * состоявшийся у другого участника кооператива (удалённый игрок или зеркало у гостя).
   */
  tryCast(e: Entity, skill: SkillDef, aimX: number, aimZ: number, targetId = -1, force = false): CastResult {
    if (!e.alive) return "disabled";
    if (e.climb) {
      // С дерева колдовать можно только устроившись на насесте, и без рывков и прыжков
      const moving = skill.delivery === "dash" || skill.delivery === "leap" || skill.delivery === "blink";
      if (e.climb.phase !== "perch" || moving) return "disabled";
    }
    if (!force) {
      if (isDisabled(e) || e.motion) return "disabled";
      if (e.cast && (!e.cast.released || e.cast.skill.delivery === "beam")) return "busy";
      if ((e.cds.get(skill.id) ?? 0) > 0) return "cooldown";
    } else if (e.cast && !e.cast.released) {
      // Незавершённый каст прерывается новым
      e.cast = null;
    }
    const st = e.stats;
    const haste = (st ? st.haste : 0) + buffPct(e, "haste") + e.frenzy * 0.03;
    if (e.kind === "player" && st && !force) {
      const cost = skill.params.cost * manaScale(e.level);
      if (st.keystones.has("bloodPact")) {
        const hpCost = (cost / Math.max(1, e.maxMp)) * e.maxHp * 0.4;
        if (e.hp <= hpCost + 1) return "mana";
        e.hp -= hpCost;
      } else {
        if (e.mp < cost) return "mana";
        e.mp -= cost;
      }
    }
    let cd = skill.params.cooldown / (1 + haste);
    if (st?.keystones.has("sprinter") && (skill.delivery === "dash" || skill.delivery === "leap" || skill.delivery === "blink")) cd *= 0.5;
    e.cds.set(skill.id, cd);
    const castT = skill.params.castTime / (1 + haste * 0.5);
    e.cast = { skill, t: castT, total: castT, aimX, aimZ, targetId, released: false };
    e.action = skill.anim;
    e.actionT = 0;
    e.actionDur = Math.max(0.3, castT * 2 + 0.15);
    // Удалённый игрок на дереве приходит без climb, только с состоянием
    e.state = e.climb || e.state === "perch" ? "perch" : e.swimming ? "swim" : "alive";
    e.yaw = Math.atan2(aimX - e.x, aimZ - e.z) || e.yaw;
    this.emit({ t: "cast", casterId: e.id, skill, aimX, aimZ, targetId });
    if (e.kind === "enemy" && skill.params.castTime >= 0.6 && (skill.delivery === "nova" || skill.delivery === "cone" || skill.delivery === "leap")) {
      // Телеграф опасной атаки
      const r = skill.delivery === "nova" ? skill.params.radius : skill.delivery === "leap" ? skill.params.radius : skill.params.radius * 0.6;
      const tx = skill.delivery === "leap" ? aimX : skill.delivery === "cone" ? e.x + Math.sin(e.yaw) * r : e.x;
      const tz = skill.delivery === "leap" ? aimZ : skill.delivery === "cone" ? e.z + Math.cos(e.yaw) * r : e.z;
      this.fx({ k: "telegraph", x: tx, y: this.groundAt(tx, tz), z: tz, radius: r, dur: castT, color: 0xff3a3a });
    }
    return "ok";
  }

  // ───────────────────────── главный цикл ─────────────────────────

  update(dt: number) {
    this.time += dt;
    // Отложенные действия
    if (this.timeline.length) {
      const now = this.timeline;
      this.timeline = [];
      for (const a of now) {
        a.t -= dt;
        if (a.t <= 0) a.fn();
        else this.timeline.push(a);
      }
    }
    this.map.update?.(this, dt);
    const toRemove: number[] = [];
    for (const e of this.entities.values()) {
      this.updateEntity(e, dt);
      if (!e.alive) {
        if (e.climb) this.fallDead(e, dt);
        else if (e.net && (e.net.h ?? 0) > 0) {
          // Удалённый кот погиб на дереве: тело падает вслед за сетевыми данными
          const n = e.net,
            k = Math.min(1, dt * 12);
          e.x = lerp(e.x, n.tx, k);
          e.z = lerp(e.z, n.tz, k);
          n.h = Math.max(0, lerp(n.h ?? 0, n.th ?? 0, k) - dt * 3);
          e.y = this.groundAt(e.x, e.z) + n.h;
        }
        e.deadT += dt;
        e.stateT += dt;
        if (e.kind !== "player" && e.deadT > 4) toRemove.push(e.id);
      }
      if (e.minion && this.time > e.minion.expires && e.alive) {
        e.alive = false;
        e.state = "dead";
        e.deadT = 3;
        this.fx({ k: "summon", x: e.x, y: e.y, z: e.z, radius: 0.8, color: 0xffffff });
      }
    }
    for (const id of toRemove) this.entities.delete(id);
    this.separate();
    // Снаряды и области обновляются и у гостя кооператива: урон там только визуальный
    // (dealDamage ничего не отнимает), зато снаряды попадают, взрываются и отскакивают как у хоста.
    this.runtime.updateProjectiles(dt);
    this.runtime.updateAreas(dt);
    if (this.authority && this.map.kind === "overworld") {
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0) {
        this.spawnTimer = 0.5;
        this.updateSpawns();
      }
    }
  }

  private updateEntity(e: Entity, dt: number) {
    e.flash = Math.max(0, e.flash - dt * 4);
    e.invuln = Math.max(0, e.invuln - dt);
    if (e.action) {
      e.actionT += dt / Math.max(0.05, e.actionDur);
      if (e.actionT >= 1) {
        e.action = null;
        e.actionT = 0;
      }
    }
    if (!e.alive) return;
    e.stateT += dt;
    // Эффекты
    for (let i = e.statuses.length - 1; i >= 0; i--) {
      const s = e.statuses[i];
      s.t -= dt;
      if (s.kind === "dot" && s.src && this.authority) {
        s.tick = (s.tick ?? 0) + dt;
        while (s.tick >= 0.5 && e.alive) {
          s.tick -= 0.5;
          dealDamage(this, s.src, e, s.value * 0.5, s.el ?? "fire", { dot: true, noOnHit: true });
        }
        // Добил яд: смерть уже очистила статусы, дальше обходить нечего
        if (!e.alive) return;
      } else if (s.kind === "regen") {
        healEntity(this, e, s.value * dt, true);
      }
      if (s.t <= 0) {
        e.statuses.splice(i, 1);
        if (s.kind === "charm" && e.enemy) {
          e.faction = 1;
          if (e.ai) e.ai.target = -1;
        }
      }
    }
    if (!e.alive) return;
    if (e.shieldT > 0) {
      e.shieldT -= dt;
      if (e.shieldT <= 0) e.shield = 0;
    }
    if (e.frenzyT > 0) {
      e.frenzyT -= dt;
      if (e.frenzyT <= 0) e.frenzy = 0;
    }
    // Регенерация игроков
    if (e.kind === "player" && e.stats) {
      // Зелий нет: в бою понемногу, без боя кот мурлычет и быстро приходит в себя
      const r = regenPerSec(e.stats, e.maxHp, e.maxMp, restFactor(this.time - e.lastCombat), e.hp / Math.max(1, e.maxHp));
      e.hp = Math.min(e.maxHp, e.hp + r.hp * dt);
      e.mp = Math.min(e.maxMp, e.mp + r.mp * dt);
      e.nineLivesCd = Math.max(0, e.nineLivesCd - dt);
      e.phoenixCd = Math.max(0, e.phoenixCd - dt);
      if (e.stats.keystones.has("purrShield")) {
        e.purrT -= dt;
        if (e.purrT <= 0) {
          e.purrT = 8;
          e.shield = Math.max(e.shield, e.maxHp * 0.1);
          e.shieldT = Math.max(e.shieldT, 8);
        }
      }
    }
    // Откаты
    for (const [k, v] of e.cds) {
      if (v > 0) e.cds.set(k, v - dt);
    }
    // Каст
    if (e.cast) {
      e.cast.t -= dt;
      if (!e.cast.released && e.cast.t <= 0) {
        e.cast.released = true;
        const c = e.cast;
        // У гостя навыки чужих сущностей исполняются только ради визуала (урон решает хост).
        this.runtime.execute(e, c.skill, c.aimX, c.aimZ, c.targetId);
        if (e.cast === c) e.cast = null;
      } else if (e.cast && e.cast.released && e.cast.t <= 0) e.cast = null;
    }
    if (this.authority && e.ai) updateAI(this, e, dt);
    this.move(e, dt);
  }

  private move(e: Entity, dt: number) {
    const px = e.x,
      pz = e.z;
    if (e.climb) {
      if (e.motion || this.map.kind !== "overworld") e.climb = null;
      else {
        this.updateClimb(e, dt);
        return;
      }
    }
    if (e.motion) {
      const m = e.motion;
      m.t += dt;
      const t = Math.min(1, m.t / m.dur);
      e.x = lerp(m.x0, m.x1, t);
      e.z = lerp(m.z0, m.z1, t);
      const g = this.groundAt(e.x, e.z);
      e.y = g + Math.sin(t * Math.PI) * m.arc;
      if (t >= 1) {
        e.motion = null;
        m.onEnd?.();
      }
      e.speed = dist(px, pz, e.x, e.z) / Math.max(dt, 1e-4);
      return;
    }
    if (e.net && e.peer !== "local" && (!this.authority || e.peer === "remote")) {
      // Интерполяция удалённых сущностей у гостя
      const k = 1 - Math.exp(-dt * 12);
      e.x = lerp(e.x, e.net.tx, k);
      e.z = lerp(e.z, e.net.tz, k);
      e.yaw += wrapAngle(e.net.tyaw - e.yaw) * k;
      // Высота над землёй (кот на дереве) приходит по сети
      const th = e.net.th ?? 0;
      e.net.h = e.net.h === undefined ? th : lerp(e.net.h, th, k);
      e.y = this.groundAt(e.x, e.z) + e.net.h;
      e.speed = dist(px, pz, e.x, e.z) / Math.max(dt, 1e-4);
      if (e.state === "climb") e.speed = Math.max(e.speed, Math.abs(th - e.net.h) * 12);
      if (e.swimming) e.y = Math.max(e.y, -0.45);
      return;
    }
    let sp = e.baseSpeed * (1 + buffPct(e, "moveSpeed"));
    let slow = 0;
    for (const s of e.statuses) if (s.kind === "slow") slow = Math.max(slow, s.value);
    sp *= 1 - slow;
    if (isDisabled(e)) sp = 0;
    if (e.cast && !e.cast.released) sp *= e.cast.skill.basic ? 0.75 : 0.4;
    if (e.cast && e.cast.released && e.cast.skill.delivery === "beam") sp *= 0.3;
    if (e.swimming) sp *= 0.62;
    const mx = e.moveX,
      mz = e.moveZ;
    e.x += (mx * sp + e.vx) * dt;
    e.z += (mz * sp + e.vz) * dt;
    const damp = Math.exp(-dt * 7);
    e.vx *= damp;
    e.vz *= damp;
    if (Math.abs(e.vx) < 0.01) e.vx = 0;
    if (Math.abs(e.vz) < 0.01) e.vz = 0;
    this.map.resolve(e);
    const g = this.groundAt(e.x, e.z);
    if (this.map.kind === "overworld" && g < -0.75) {
      e.swimming = true;
      e.y = -0.42;
      if (e.state !== "dead") e.state = "swim";
    } else {
      if (e.swimming && e.state === "swim") e.state = "alive";
      e.swimming = false;
      e.y = g;
    }
    const moved = dist(px, pz, e.x, e.z);
    e.speed = moved / Math.max(dt, 1e-4);
    if (e.kind === "player" && e.peer === "local") this.autoClimb(e, mx, mz, dt);
    if ((mx !== 0 || mz !== 0) && (!e.cast || e.cast.released) && e.kind !== "player") {
      const want = Math.atan2(mx, mz);
      e.yaw += wrapAngle(want - e.yaw) * Math.min(1, dt * 10);
    }
    if (e.speed > 0.3 && (e.state === "sit" || e.state === "loaf" || e.state === "sleep")) e.state = "alive";
  }

  // ───────────────────────── лазание по деревьям ─────────────────────────

  /** Ближайшее дерево или когтеточка, до ствола которых не дальше reach (открытый мир). */
  findClimbable(x: number, z: number, reach: number): ClimbAnchor | null {
    if (this.map.kind !== "overworld") return null;
    const ccx = Math.floor(x / CHUNK),
      ccz = Math.floor(z / CHUNK);
    let best: ClimbAnchor | null = null;
    let bd = reach;
    for (let dz = -1; dz <= 1; dz++)
      for (let dx = -1; dx <= 1; dx++) {
        // Как и коллайдеры: содержимое чанка строится по требованию и кэшируется
        const c = this.terrain.content(ccx + dx, ccz + dz);
        for (const p of c.props) {
          const spec = CLIMB_PROPS[p.kind];
          if (!spec) continue;
          const d = Math.hypot(p.x - x, p.z - z) - spec.r0 * p.scale;
          if (d < bd) {
            bd = d;
            best = { x: p.x, y: p.y, z: p.z, rot: p.rot, scale: p.scale, spec, building: false, col: (PROP_COLLIDER[p.kind] ?? 0.5) * p.scale, tint: p.tint };
          }
        }
        for (const b of c.buildings) {
          const spec = CLIMB_BUILDINGS[b.kind];
          if (!spec) continue;
          const base = anchorPoint({ x: b.x, y: b.y, z: b.z, rot: b.rot, scale: b.scale, spec, building: true, col: 0, tint: 0 }, spec.path[0]);
          const d = Math.hypot(base[0] - x, base[2] - z) - spec.r0 * b.scale;
          if (d < bd) {
            bd = d;
            best = { x: b.x, y: b.y, z: b.z, rot: b.rot, scale: b.scale, spec, building: true, col: b.collider * b.scale, tint: 0xd8c090 };
          }
        }
      }
    return best;
  }

  /**
   * Начать лезть: кот цепляется за ствол со своей стороны.
   * (upX, upZ) — какой ввод считать «вверх» (по умолчанию — к стволу).
   */
  startClimb(e: Entity, a: ClimbAnchor, upX = 0, upZ = 0) {
    const base = anchorPoint(a, a.spec.path[0]);
    const ang = Math.atan2(e.x - base[0], e.z - base[2]);
    let ul = Math.hypot(upX, upZ);
    if (ul < 1e-3) {
      upX = -Math.sin(ang);
      upZ = -Math.cos(ang);
      ul = 1;
    }
    const c: ClimbState = {
      ...a,
      len: pathLength(a),
      d: 0.25,
      ang,
      upX: upX / ul,
      upZ: upZ / ul,
      phase: "climb",
      t: 0,
      from: [e.x, e.y, e.z],
      to: [e.x, e.y, e.z],
      dur: 0,
      arc: 0,
      hop: 0,
      hp: e.hp,
      away: 0,
    };
    e.climb = c;
    e.motion = null;
    e.cast = null;
    e.state = "climb";
    e.stateT = 0;
    e.vx = e.vz = 0;
    e.climbPush = 0;
    this.emit({ t: "sound", s: "land", x: e.x, z: e.z, vol: 0.35, pitch: 2.2 });
  }

  /** Спрыгнуть с дерева в сторону (dx, dz); без направления — от ствола. */
  leapFromTree(e: Entity, dx = 0, dz = 0) {
    const c = e.climb;
    if (!c || c.phase === "leap") return;
    let l = Math.hypot(dx, dz);
    if (l < 0.1) {
      dx = Math.sin(c.ang);
      dz = Math.cos(c.ang);
      l = 1;
    }
    dx /= l;
    dz /= l;
    const trunk = anchorPoint(c, c.spec.path[0]);
    // Приземляемся за пределами коллайдера дерева
    const out = c.col + e.radius + 1.6;
    let tx = e.x + dx * 2.6,
      tz = e.z + dz * 2.6;
    const ox = tx - trunk[0],
      oz = tz - trunk[2];
    const od = Math.hypot(ox, oz);
    if (od < out) {
      const k = od > 1e-3 ? out / od : 1;
      tx = trunk[0] + (od > 1e-3 ? ox * k : dx * out);
      tz = trunk[2] + (od > 1e-3 ? oz * k : dz * out);
    }
    const ty = this.groundAt(tx, tz);
    c.phase = "leap";
    c.t = 0;
    c.from = [e.x, e.y, e.z];
    c.to = [tx, ty, tz];
    c.dur = 0.35 + Math.min(0.35, (e.y - ty) * 0.06);
    c.arc = 0.5;
    e.state = "alive";
    e.yaw = Math.atan2(dx, dz);
  }

  /** Слезть без анимации: телепорт, подземелье, воскрешение. */
  dropClimb(e: Entity) {
    e.climb = null;
    e.climbPush = 0;
    if (e.state === "climb" || e.state === "perch") e.state = "alive";
  }

  /** Кот погиб на дереве — тело падает на землю в стороне от ствола. */
  private fallDead(e: Entity, dt: number) {
    const c = e.climb!;
    if (c.phase !== "leap") {
      const trunk = anchorPoint(c, c.spec.path[0]);
      let dx = e.x - trunk[0],
        dz = e.z - trunk[2];
      const l = Math.hypot(dx, dz);
      if (l < 1e-3) {
        dx = Math.sin(c.ang);
        dz = Math.cos(c.ang);
      } else {
        dx /= l;
        dz /= l;
      }
      const out = c.col + e.radius + 0.6;
      const tx = trunk[0] + dx * out,
        tz = trunk[2] + dz * out;
      c.phase = "leap";
      c.t = 0;
      c.from = [e.x, e.y, e.z];
      c.to = [tx, this.groundAt(tx, tz), tz];
      c.dur = 0.3 + Math.min(0.45, (e.y - c.to[1]) * 0.07);
      c.arc = 0.15;
    }
    c.t += dt;
    const k = Math.min(1, c.t / c.dur);
    const f = c.from,
      to = c.to;
    e.x = f[0] + (to[0] - f[0]) * k;
    e.z = f[2] + (to[2] - f[2]) * k;
    e.y = f[1] + (to[1] - f[1]) * k * k + Math.sin(k * Math.PI) * c.arc;
    if (k >= 1) {
      e.climb = null;
      e.y = this.groundAt(e.x, e.z);
    }
  }

  private updateClimb(e: Entity, dt: number) {
    const c = e.climb!;
    // Удар сбивает с дерева (но не с насеста)
    if (e.hp < c.hp - 0.5 && c.phase === "climb") {
      c.hp = e.hp;
      e.action = "hit";
      e.actionT = 0;
      e.actionDur = 0.4;
      this.leapFromTree(e);
    }
    c.hp = e.hp;
    c.t += dt;
    const mx = e.moveX,
      mz = e.moveZ;
    const disabled = isDisabled(e);
    switch (c.phase) {
      case "climb": {
        // Ввод «вверх» (как при старте) — вверх, обратный — вниз, вбок — вокруг ствола
        const ix = c.upX,
          iz = c.upZ;
        const along = disabled ? 0 : mx * ix + mz * iz;
        const side = disabled ? 0 : mx * -iz + mz * ix;
        const sp = CLIMB_SPEED * (1 + buffPct(e, "moveSpeed") * 0.5);
        c.d += along * sp * dt;
        c.ang += (side * sp * dt) / Math.max(0.4, c.spec.r0 * c.scale + 0.35);
        if (c.d <= 0) {
          // Слез на землю
          const base = anchorPoint(c, c.spec.path[0]);
          const r = c.col + e.radius * 0.8 + 0.05;
          e.x = base[0] + Math.sin(c.ang) * r;
          e.z = base[2] + Math.cos(c.ang) * r;
          e.y = this.groundAt(e.x, e.z);
          e.yaw = c.ang;
          e.climb = null;
          e.state = "alive";
          e.climbPush = -0.6;
          return;
        }
        if (c.d >= c.len) {
          c.d = c.len;
          this.nextHop(e, c);
          break;
        }
        const pose = climbPose(c, c.d, c.ang);
        e.x = pose[0];
        e.y = pose[1];
        e.z = pose[2];
        e.yaw = pose[3];
        e.speed = Math.abs(along) * sp;
        e.state = "climb";
        return;
      }
      case "hop":
      case "leap": {
        const k = Math.min(1, c.t / c.dur);
        const f = c.from,
          to = c.to;
        e.x = f[0] + (to[0] - f[0]) * k;
        e.z = f[2] + (to[2] - f[2]) * k;
        e.y = f[1] + (to[1] - f[1]) * k + Math.sin(k * Math.PI) * c.arc;
        if (Math.hypot(to[0] - f[0], to[2] - f[2]) > 0.05) e.yaw = Math.atan2(to[0] - f[0], to[2] - f[2]);
        e.speed = 0;
        if (k >= 1) {
          if (c.phase === "leap") {
            e.climb = null;
            e.state = "alive";
            e.y = this.groundAt(e.x, e.z);
            e.climbPush = -0.8;
            this.emit({ t: "sound", s: "land", x: e.x, z: e.z, vol: 0.6 });
            this.fx({ k: "dust", x: e.x, y: e.y, z: e.z, radius: 0.6, color: 0xd8c8a8 });
            return;
          }
          this.nextHop(e, c);
        }
        break;
      }
      case "perch": {
        // Ввод держат полсекунды — спрыгиваем в ту сторону
        const l = Math.hypot(mx, mz);
        if (!disabled && l > 0.35) {
          c.away += dt;
          e.yaw = Math.atan2(mx, mz);
          if (c.away > 0.28) this.leapFromTree(e, mx, mz);
        } else c.away = 0;
        const p = anchorPoint(c, c.spec.perch);
        e.x = p[0];
        e.y = p[1];
        e.z = p[2];
        e.speed = 0;
        if (e.state !== "perch" && !e.action) e.state = "perch";
        break;
      }
    }
  }

  /** Следующий прыжок наверх: по площадкам когтеточки, затем на насест. c.hop — номер следующей цели. */
  private nextHop(e: Entity, c: ClimbState) {
    const hops = c.spec.hops;
    if (c.hop > hops.length) {
      // Последний прыжок был на насест — устраиваемся
      c.phase = "perch";
      c.t = 0;
      c.away = 0;
      e.state = "perch";
      e.stateT = 0;
      const p = anchorPoint(c, c.spec.perch);
      e.x = p[0];
      e.y = p[1];
      e.z = p[2];
      this.emit({ t: "sound", s: "meow", x: e.x, z: e.z, vol: 0.5, pitch: 1.3 });
      if (!c.building) this.fx({ k: "leaves", x: e.x, y: e.y, z: e.z, radius: 0.9, color: c.tint });
      return;
    }
    const target = c.hop < hops.length ? hops[c.hop] : c.spec.perch;
    c.hop++;
    const to = anchorPoint(c, target);
    c.phase = "hop";
    c.t = 0;
    c.from = [e.x, e.y, e.z];
    c.to = [to[0], to[1], to[2]];
    c.dur = 0.42;
    c.arc = hopArc(c.from, c.to);
    if (!c.building) this.fx({ k: "leaves", x: e.x, y: e.y + 0.3, z: e.z, radius: 0.6, color: c.tint });
  }

  /** Игрок упирается в ствол вне боя — кот сам начинает лезть. */
  private autoClimb(e: Entity, mx: number, mz: number, dt: number) {
    if (e.climbPush < 0) {
      e.climbPush = Math.min(0, e.climbPush + dt);
      return;
    }
    const l = Math.hypot(mx, mz);
    if (l < 0.5 || e.swimming || e.cast || this.time - e.lastCombat < 4 || this.map.kind !== "overworld") {
      e.climbPush = 0;
      return;
    }
    const a = this.findClimbable(e.x, e.z, e.radius + 0.9);
    if (!a) {
      e.climbPush = 0;
      return;
    }
    const base = anchorPoint(a, a.spec.path[0]);
    const tx = base[0] - e.x,
      tz = base[2] - e.z;
    const td = Math.hypot(tx, tz) || 1;
    const facing = (mx * tx + mz * tz) / (l * td);
    // Упёршийся наискось кот съезжает по коллайдеру вбок, и направление на ствол быстро уходит:
    // порог мягкий, а короткий выход из него не сбрасывает накопленное сразу
    if (facing < 0.35) {
      e.climbPush = Math.max(0, e.climbPush - dt * 2);
      return;
    }
    e.climbPush += dt;
    if (e.climbPush > 0.15) this.startClimb(e, a, mx, mz);
  }

  /** Мягкое расталкивание сущностей. */
  private separate() {
    const list = this.sep;
    list.length = 0;
    for (const e of this.entities.values()) if (e.alive && !e.motion && !e.climb) list.push(e);
    const n = list.length;
    for (let i = 0; i < n; i++) {
      const a = list[i];
      for (let j = i + 1; j < n; j++) {
        const b = list[j];
        const dx = b.x - a.x,
          dz = b.z - a.z;
        const rr = (a.radius + b.radius) * 0.85;
        const d2 = dx * dx + dz * dz;
        if (d2 >= rr * rr || d2 < 1e-8) continue;
        const d = Math.sqrt(d2);
        const push = (rr - d) * 0.5;
        const nx = dx / d,
          nz = dz / d;
        const wa = a.kind === "player" ? 0.3 : a.enemy?.boss ? 0.1 : 1;
        const wb = b.kind === "player" ? 0.3 : b.enemy?.boss ? 0.1 : 1;
        const s = wa + wb;
        a.x -= nx * push * (wa / s) * 2;
        a.z -= nz * push * (wa / s) * 2;
        b.x += nx * push * (wb / s) * 2;
        b.z += nz * push * (wb / s) * 2;
      }
    }
  }

  // ───────────────────────── появление врагов и жителей ─────────────────────────

  /** Уровень врага в точке с учётом режима. */
  enemyLevelAt(x: number, z: number): number {
    let lvl = Math.round(this.gen.levelAt(x, z));
    if (this.mode.world === "continent" && this.mode.levels === "infinite" && this.levelFloor > 100) lvl = Math.max(lvl, this.levelFloor - 1);
    return Math.max(1, lvl + (this.rng.chance(0.3) ? this.rng.int(-1, 1) : 0));
  }

  private updateSpawns() {
    const players = this.players().filter((p) => p.alive || true);
    if (!players.length) return;
    const R = 3;
    const wanted = new Set<string>();
    for (const p of players) {
      const pcx = Math.floor(p.x / CHUNK),
        pcz = Math.floor(p.z / CHUNK);
      for (let dz = -R; dz <= R; dz++)
        for (let dx = -R; dx <= R; dx++) {
          const cx = pcx + dx,
            cz = pcz + dz;
          const c = this.terrain.content(cx, cz);
          for (const sp of c.spawns) {
            const key = `${cx},${cz},${sp.id}`;
            const d = dist(p.x, p.z, sp.x, sp.z);
            if (d > 72) continue;
            wanted.add(key);
            if (this.spawnActive.has(key)) continue;
            const deadAt = this.spawnDead.get(key);
            if (deadAt !== undefined && this.time - deadAt < 150) continue;
            if (d < 22) continue; // не спавним прямо перед носом
            this.spawnPack(key, sp.x, sp.z, sp.size, sp.kind, sp.poiId, sp.id);
          }
        }
      // Жители городов
      const region = this.gen.regionAt(p.x, p.z);
      for (const rr of [region]) {
        const town = rr.town;
        if (!town) continue;
        if (dist(p.x, p.z, town.x, town.z) > 140) continue;
        for (const n of town.npcs) {
          if (this.npcActive.has(n.id)) continue;
          const e = this.spawnNpc(n);
          this.npcActive.set(n.id, e.id);
        }
      }
    }
    // Деспавн далёких
    for (const [key, ids] of this.spawnActive) {
      let anyAlive = false,
        anyNear = false,
        inCombat = false;
      for (const id of ids) {
        const e = this.entities.get(id);
        if (!e || !e.alive) continue;
        anyAlive = true;
        if (this.nearestPlayer(e.x, e.z, 110)) anyNear = true;
        if (e.ai && e.ai.target >= 0) inCombat = true;
      }
      if (!anyAlive) {
        this.spawnActive.delete(key);
        this.spawnDead.set(key, this.time);
        continue;
      }
      if (!anyNear && !inCombat && !wanted.has(key)) {
        for (const id of ids) this.entities.delete(id);
        this.spawnActive.delete(key);
      }
    }
    for (const [nid, eid] of this.npcActive) {
      const e = this.entities.get(eid);
      if (!e) {
        this.npcActive.delete(nid);
        continue;
      }
      if (!this.nearestPlayer(e.x, e.z, 200)) {
        this.entities.delete(eid);
        this.npcActive.delete(nid);
      }
    }
  }

  private spawnPack(key: string, x: number, z: number, size: number, kind: "pack" | "camp" | "elite", poiId: string | undefined, seed: number) {
    const rng = new Rng(hashInts(seed, Math.floor(this.time / 150)));
    const biome = BIOMES[this.gen.biomeIdAt(x, z)];
    const famId = rng.pick(biome.families);
    const fam = familyFor(famId);
    const roles = Object.entries(fam.roles) as [Role, number][];
    const ids: number[] = [];
    const level = this.enemyLevelAt(x, z);
    const n = kind === "elite" ? 1 : size;
    for (let i = 0; i < n; i++) {
      const role = rng.weighted(
        roles.map((r) => r[0]),
        roles.map((r) => r[1]),
      );
      const a = (i / n) * Math.PI * 2 + rng.next();
      const r = n > 1 ? rng.range(1.5, 4) : 0;
      const ex = x + Math.cos(a) * r,
        ez = z + Math.sin(a) * r;
      const elite = kind === "elite" || (kind === "camp" && i === 0 && rng.chance(0.6)) || rng.chance(0.04);
      let named: Txt | undefined;
      if (kind === "elite" && poiId) {
        const reg = this.gen.regionById(poiId.split(":")[0]);
        const poi = reg?.pois.find((p) => p.id === poiId);
        named = poi?.bossName;
      }
      const e = this.spawnEnemy({ family: famId, role, level: level + (elite ? 1 : 0), x: ex, z: ez, elite, spawnKey: key, poiId, named, seed: rng.id() });
      if (kind === "elite") {
        e.maxHp *= 2;
        e.hp = e.maxHp;
        e.look.size *= 1.2;
        e.radius *= 1.2;
      }
      ids.push(e.id);
    }
    this.spawnActive.set(key, ids);
  }

  /** Сброс всех врагов/жителей (например, при входе в подземелье). */
  clearNonPlayers() {
    for (const [id, e] of this.entities) if (e.kind !== "player") this.entities.delete(id);
    this.spawnActive.clear();
    this.npcActive.clear();
    this.projectiles.length = 0;
    this.areas.length = 0;
    this.timeline.length = 0;
  }

  /** Поставить отметку, что точка появления зачищена (для персистентности в сессии). */
  markSpawnDead(key: string) {
    this.spawnDead.set(key, this.time);
  }

  hasStatus = hasStatus;
  isHostile = isHostile;
  addStatus = addStatus;
  smoothstep = smoothstep;
}
