import { observer } from "mobx-react-lite";
import { useMemo, useState } from "react";
import { tr } from "../../core/i18n";
import { fmtNum } from "../../core/format";
import { Rng, hashStr } from "../../core/rng";
import { useStore } from "../stores";
import { Btn, ItemCard, ItemIcon, Panel } from "../common";
import { Glyph } from "../icons";
import { QuestView } from "./Quests";
import { makeGear, type Item } from "../../game/items";
import { priceScale } from "../../game/progression";
import { audio } from "../../audio/audio";
import { NPC_ROLE_NAMES } from "../../game/session";

export const DialogPanel = observer(() => {
  const s = useStore();
  const dlg = s.ui.dialog;
  const sess = s.session!;
  const c = s.char!;
  void c.rev;
  const [shop, setShop] = useState(false);
  if (!dlg) return null;
  const f = sess.quests.forNpc(dlg.npcId, dlg.townId);
  const role = dlg.role;
  const roleName = NPC_ROLE_NAMES[role];
  const turnIn = (qid: string) => {
    const r = sess.quests.turnIn(qid, dlg.npcId);
    if (r) {
      audio.play("quest");
      const q = sess.quests.get(qid);
      s.hud.toast({ ru: `Награда: ${fmtNum(r.xp)} XP, ${fmtNum(r.fish)} 🐟${r.items.length ? ", " + r.items.join(", ") : ""}${r.skillPoints ? `, +${r.skillPoints} очк.` : ""}`, en: `Reward: ${fmtNum(r.xp)} XP, ${fmtNum(r.fish)} 🐟${r.skillPoints ? `, +${r.skillPoints} pts` : ""}` }, 0xffd24a, "🎁");
      if (q) s.hud.toast(q.done, 0xffffff, "💬");
      sess.world.applyStats(sess.player, c.stats);
    }
  };
  const respecCost = Math.round(20 * priceScale(c.data.level) * (1 + c.data.learned.length * 0.02));
  if (shop) return <ShopPanel onBack={() => setShop(false)} townId={dlg.townId} role={role} />;
  return (
    <Panel title={{ ru: `${dlg.name.ru}${roleName ? " · " + roleName.ru : ""}`, en: `${dlg.name.en}${roleName ? " · " + roleName.en : ""}` }} onClose={() => s.ui.close()}>
      <div className="dialog-npc">
        <div style={{ width: 48, height: 48, borderRadius: "50%", background: "#4a3a6e", display: "grid", placeItems: "center", flexShrink: 0 }}>
          <Glyph name="cat" size={32} />
        </div>
        <div className="dialog-bubble">{tr(dlg.greeting)}</div>
      </div>
      {f.turnIn.map((q) => {
        const complete = sess.quests.isComplete(q.id) || q.kind === "story";
        return (
          <div key={q.id} className="quest tracked">
            <h4>
              {q.kind === "story" ? "👑 " : "✅ "}
              {tr(q.title)}
            </h4>
            <QuestView q={q} showIntro={q.kind === "story"} />
            <div className="row" style={{ marginTop: 8 }}>
              <Btn kind="primary" small disabled={!complete} onClick={() => turnIn(q.id)}>
                {q.kind === "story" ? tr({ ru: "Продолжить историю", en: "Continue the story" }) : tr({ ru: "Сдать задание", en: "Complete quest" })}
              </Btn>
            </div>
          </div>
        );
      })}
      {f.offer.map((q) => (
        <div key={q.id} className="quest">
          <h4>
            ❗ {tr(q.title)} <span className="muted">· {q.level}</span>
            {q.chain ? <span className="muted"> · {q.chain.step}/{q.chain.total}</span> : null}
          </h4>
          <QuestView q={q} />
          <div className="row" style={{ marginTop: 8 }}>
            <Btn kind="primary" small onClick={() => sess.quests.accept(q.id)}>
              {tr({ ru: "Принять", en: "Accept" })}
            </Btn>
          </div>
        </div>
      ))}
      {f.inProgress.map((q) => (
        <div key={q.id} className="quest">
          <h4>
            ⏳ {tr(q.title)}
          </h4>
          <QuestView q={q} showIntro={false} />
        </div>
      ))}
      <div className="row" style={{ marginTop: 10 }}>
        {(role === "merchant" || role === "smith") && (
          <Btn onClick={() => setShop(true)}>🛒 {tr({ ru: "Торговать", en: "Trade" })}</Btn>
        )}
        {role === "trainer" && (
          <Btn
            onClick={() =>
              s.ui.ask({
                text: { ru: `Сбросить все навыки за ${fmtNum(respecCost)} 🐟?`, en: `Reset all skills for ${fmtNum(respecCost)} 🐟?` },
                ok: () => {
                  if (c.data.fish < respecCost) {
                    s.hud.toast({ ru: "Не хватает рыбок", en: "Not enough fish" }, 0xff8a8a);
                    return;
                  }
                  c.addFish(-respecCost);
                  c.unlearnAll();
                  s.hud.toast({ ru: "Навыки сброшены", en: "Skills reset" }, 0x9ad0ff);
                },
              })
            }
          >
            🔄 {tr({ ru: "Сбросить навыки", en: "Reset skills" })}
          </Btn>
        )}
        {role === "innkeeper" && (
          <Btn
            onClick={() => {
              const p = sess.player;
              p.hp = p.maxHp;
              p.mp = p.maxMp;
              sess.saveNow();
              audio.purr(1.5, 0.3);
              s.hud.toast({ ru: "Вы вздремнули у камина. Игра сохранена.", en: "You napped by the fireplace. Game saved." }, 0xffd27a, "😴");
            }}
          >
            😴 {tr({ ru: "Вздремнуть", en: "Take a nap" })}
          </Btn>
        )}
        <div className="spacer" />
        <Btn kind="ghost" onClick={() => s.ui.close()}>
          {tr({ ru: "Пока!", en: "Bye!" })}
        </Btn>
      </div>
    </Panel>
  );
});

export const ShopPanel = observer(({ onBack, townId, role }: { onBack: () => void; townId: string; role: string }) => {
  const s = useStore();
  const c = s.char!;
  void c.rev;
  const lvl = c.data.level;
  const day = Math.floor(Date.now() / (1000 * 60 * 30));
  const stock = useMemo(() => {
    const rng = new Rng(hashStr(`${townId}:${day}:${role}`));
    const items: Item[] = [];
    const n = role === "smith" ? 6 : 4;
    for (let i = 0; i < n; i++) items.push(makeGear(rng, lvl, rng.weighted([1, 2, 3], [60, 32, 8]) as 1, c.data.classId, role === "smith" ? rng.pick(["weapon", "head", "body", "paws"] as const) : undefined));
    return items;
  }, [townId, day, role, lvl, c.data.classId]);
  const [bought, setBought] = useState<Set<string>>(new Set());
  const [sel, setSel] = useState<Item | null>(null);
  const price = (it: Item) => Math.max(2, Math.round(it.value * 1.4));
  const buy = (it: Item) => {
    const p = price(it);
    if (c.data.fish < p) {
      s.hud.toast({ ru: "Не хватает рыбок", en: "Not enough fish" }, 0xff8a8a);
      return;
    }
    if (!c.addItem(it)) {
      s.hud.toast({ ru: "Инвентарь полон", en: "Inventory full" }, 0xff8a8a);
      return;
    }
    c.addFish(-p);
    setBought(new Set([...bought, it.id]));
    audio.play("fish");
  };
  return (
    <Panel title={{ ru: `Лавка · 🐟 ${fmtNum(c.data.fish)}`, en: `Shop · 🐟 ${fmtNum(c.data.fish)}` }} onClose={() => s.ui.close()}>
      <div className="inv-grid" style={{ marginBottom: 10 }}>
        {stock
          .filter((it) => !bought.has(it.id))
          .map((it) => (
            <div key={it.id} className="col" style={{ alignItems: "center", gap: 2 }}>
              <ItemIcon item={it} size={52} selected={sel?.id === it.id} onClick={() => setSel(it)} />
              <span style={{ fontSize: 11 }}>🐟{fmtNum(price(it))}</span>
            </div>
          ))}
      </div>
      {sel && !bought.has(sel.id) && (
        <ItemCard item={sel} compare={sel.gear ? c.data.equipment[sel.gear.slot] : null}>
          <div className="row" style={{ marginTop: 8 }}>
            <Btn kind="primary" small onClick={() => buy(sel)}>
              {tr({ ru: "Купить", en: "Buy" })} · 🐟 {fmtNum(price(sel))}
            </Btn>
          </div>
        </ItemCard>
      )}
      <div className="muted" style={{ fontSize: 13, marginTop: 8 }}>
        {tr({ ru: "Продавать предметы можно в инвентаре, пока открыта лавка.", en: "Sell items from your inventory while the shop is open." })}
      </div>
      <div className="row" style={{ marginTop: 10 }}>
        <Btn onClick={onBack}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
        <Btn onClick={() => s.ui.open("inventory")}>🎒 {tr({ ru: "Инвентарь", en: "Inventory" })}</Btn>
      </div>
    </Panel>
  );
});

export const TravelPanel = observer(() => {
  const s = useStore();
  const sess = s.session!;
  const c = s.char!;
  void c.rev;
  const p = sess.player;
  const list = c.data.discovered
    .map((id) => {
      const reg = sess.gen.regionById(id.split(":")[0]);
      if (!reg) return null;
      if (reg.town?.id === id) return { id, name: reg.town.name, level: reg.level, x: reg.town.x, z: reg.town.z, region: reg.name };
      const poi = reg.pois.find((pp) => pp.id === id);
      return poi ? { id, name: poi.name, level: poi.level, x: poi.x, z: poi.z, region: reg.name } : null;
    })
    .filter(Boolean) as { id: string; name: { ru: string; en: string }; level: number; x: number; z: number; region: { ru: string; en: string } }[];
  list.sort((a, b) => Math.hypot(a.x - p.x, a.z - p.z) - Math.hypot(b.x - p.x, b.z - p.z));
  const inCombat = sess.combatT > 0;
  return (
    <Panel title={{ ru: "Путевые камни", en: "Waystones" }} onClose={() => s.ui.close()}>
      {inCombat && <div className="bad" style={{ marginBottom: 8 }}>{tr({ ru: "Нельзя путешествовать во время боя!", en: "Can't travel during combat!" })}</div>}
      {list.map((t) => (
        <div key={t.id} className="save-row">
          <div style={{ flex: 1 }}>
            <b>{tr(t.name)}</b> <span className="muted">· {tr(t.region)} · {tr({ ru: "ур.", en: "lv" })} {t.level}</span>
            <div className="muted" style={{ fontSize: 12 }}>
              {Math.round(Math.hypot(t.x - p.x, t.z - p.z))} {tr({ ru: "м", en: "m" })}
            </div>
          </div>
          <Btn small kind="primary" disabled={inCombat} onClick={() => sess.travelTo(t.id)}>
            ✨ {tr({ ru: "Перенестись", en: "Travel" })}
          </Btn>
        </div>
      ))}
      {list.length === 0 && <div className="muted">{tr({ ru: "Вы ещё не открыли ни одного путевого камня.", en: "You haven't discovered any waystones yet." })}</div>}
    </Panel>
  );
});
