/** Гость кооператива: зеркалит мир хоста, сам управляет своим котом и отправляет касты. */
import { reaction } from "mobx";
import { dist } from "../core/math";
import { audio } from "../audio/audio";
import type { GameSession, NetBridge } from "../game/session";
import type { Entity, GameEvent } from "../game/sim/types";
import type { SkillDef } from "../game/skills/types";
import { addStatus, healEntity, killEntity } from "../game/sim/combat";
import type { Peer } from "./peer";
import type { BridgeHooks } from "./host";
import { packStats, r2, SNAP_STRIDE, STATES, type GuestMsg, type HostMsg, type WelcomeMsg } from "./protocol";
import { fin, sanitizeEvents, sanitizeMirror, sanitizeSkill, txt } from "./sanitize";

const CC_KINDS = new Set(["stun", "freeze", "slow", "blind", "weaken", "vulnerable"]);
/** Сообщения, которые можно выбросить, если вкладка долго была свёрнута. */
const DROPPABLE = new Set(["cast", "ev", "emote", "toast", "status"]);

export class GuestBridge implements NetBridge {
  readonly role = "guest" as const;
  private inbox: HostMsg[] = [];
  private snap: Extract<HostMsg, { t: "snap" }> | null = null;
  /** id хоста → локальный id */
  private toLocal = new Map<number, number>();
  private toHost = new Map<number, number>();
  private session: GameSession | null = null;
  private stT = 0;
  private disposers: (() => void)[] = [];
  private closed = false;
  /** Номер перехода между картами (от хоста). */
  private epoch: number;
  hostEntity: Entity | null = null;
  readonly partnerName: string;

  constructor(
    private peer: Peer,
    readonly welcome: WelcomeMsg,
    private hooks: BridgeHooks,
  ) {
    this.partnerName = welcome.hostName;
    this.epoch = welcome.ep;
    peer.onMessage = (m) => {
      const msg = m as HostMsg;
      if (!msg || typeof msg !== "object" || typeof msg.t !== "string") return;
      if (msg.t === "snap") {
        this.snap = msg;
        return;
      }
      // Свёрнутая вкладка не обрабатывает кадры — не даём очереди расти бесконечно
      if (this.inbox.length > 3000) this.inbox = this.inbox.filter((x) => !DROPPABLE.has(x.t));
      if (this.inbox.length < 6000) this.inbox.push(msg);
    };
    peer.onClose = (reason) => this.handleClose(reason);
  }

  get connected() {
    return this.peer.isOpen;
  }

  partner(): Entity | null {
    return this.hostEntity;
  }

  private send(m: GuestMsg, reliable = true) {
    this.peer.send(m, reliable);
  }

  /** Подключить к уже созданной игровой сессии (мир хоста, authority=false). */
  attach(s: GameSession) {
    this.session = s;
    s.net = this;
    s.world.authority = false;
    const w = this.welcome;
    const me = s.player;
    this.map(w.you, me.id);
    const hm = sanitizeMirror(w.host);
    if (hm) {
      const h = s.world.addMirror(hm);
      this.hostEntity = h;
      this.map(hm.id, h.id);
    }
    s.renderer.env.timeOfDay = fin(w.tod, 0, 1, 0.3);
    // Характеристики и внешность — хосту при каждом изменении
    this.disposers.push(
      reaction(
        () => [s.char.stats, s.char.gearLook, s.char.data.level] as const,
        ([st, look, level]) => this.send({ t: "stats", stats: packStats(st), look, level }),
      ),
    );
  }

  private map(hostId: number, localId: number) {
    this.toLocal.set(hostId, localId);
    this.toHost.set(localId, hostId);
  }

  private unmapLocal(localId: number) {
    const h = this.toHost.get(localId);
    if (h !== undefined) this.toLocal.delete(h);
    this.toHost.delete(localId);
  }

  private local(hostId: number): Entity | null {
    const id = this.toLocal.get(hostId);
    if (id === undefined) return null;
    return this.session?.world.entities.get(id) ?? null;
  }

  /** Убрать сопоставления для сущностей, которых больше нет. */
  private prune() {
    const w = this.session!.world;
    for (const [lid] of this.toHost) if (!w.entities.has(lid)) this.unmapLocal(lid);
  }

  onFrame(s: GameSession, dt: number) {
    if (this.inbox.length) {
      const msgs = this.inbox;
      this.inbox = [];
      for (const m of msgs) {
        try {
          this.handle(s, m);
        } catch (e) {
          console.warn("co-op message", m.t, e);
        }
      }
    }
    if (this.snap) {
      this.applySnap(s, this.snap);
      this.snap = null;
    }
    this.stT -= dt;
    if (this.stT <= 0) {
      this.stT = 1 / 15;
      const p = s.player;
      const h = p.climb ? r2(Math.max(0, p.y - s.world.groundAt(p.x, p.z))) : 0;
      this.send({ t: "st", x: r2(p.x), z: r2(p.z), yaw: r2(p.yaw), hp: Math.round(p.hp), mp: Math.round(p.mp), sh: Math.round(p.shield), alive: p.alive ? 1 : 0, s: Math.max(0, STATES.indexOf(p.alive ? p.state : "dead")), h, ep: this.epoch }, false);
    }
  }

  private applySnap(s: GameSession, m: Extract<HostMsg, { t: "snap" }>) {
    const env = s.renderer.env;
    const tod = fin(m.tod, 0, 1, env.timeOfDay);
    if (Math.abs(env.timeOfDay - tod) > 0.01) env.timeOfDay = tod;
    const a = Array.isArray(m.e) ? m.e : [];
    for (let i = 0; i + SNAP_STRIDE <= a.length && i < 20000; i += SNAP_STRIDE) {
      const e = this.local(a[i]);
      if (!e || e === s.player) continue;
      const x = a[i + 1],
        z = a[i + 2],
        yaw = a[i + 3];
      if (!Number.isFinite(x) || !Number.isFinite(z) || !Number.isFinite(yaw)) continue;
      if (dist(e.x, e.z, x, z) > 25) {
        e.x = x;
        e.z = z;
        e.motion = null;
      }
      e.net = { tx: x, tz: z, tyaw: yaw, th: fin(a[i + 7], 0, 15, 0), h: e.net?.h };
      e.hp = fin(a[i + 4], 0, 1e15, e.hp);
      e.maxHp = fin(a[i + 5], 1, 1e15, e.maxHp);
      const flags = fin(a[i + 6], 0, 255, 1);
      const alive = (flags & 1) === 1;
      const state = STATES[(flags >> 1) & 7] ?? "alive";
      if (!alive && e.alive) {
        e.alive = false;
        e.state = "dead";
        e.stateT = 0;
        e.deadT = 0;
        e.cast = null;
      } else if (alive && !e.alive) {
        e.alive = true;
        e.state = "alive";
        e.deadT = 0;
      }
      if (e.alive && state !== "dead") e.state = state;
      e.swimming = state === "swim";
    }
  }

  private handle(s: GameSession, m: HostMsg) {
    const w = s.world;
    switch (m.t) {
      case "spawn":
        if (!Array.isArray(m.e)) break;
        for (const raw of m.e.slice(0, 500)) {
          const mi = sanitizeMirror(raw);
          if (!mi) continue;
          const ex = this.local(mi.id);
          if (ex) {
            ex.look = mi.look;
            ex.level = mi.level;
            continue;
          }
          if (mi.minionOwner !== undefined) mi.minionOwner = this.toLocal.get(mi.minionOwner) ?? -1;
          const e = w.addMirror(mi);
          this.map(mi.id, e.id);
        }
        break;
      case "gone":
        if (!Array.isArray(m.ids)) break;
        for (const hid of m.ids) {
          const lid = this.toLocal.get(hid);
          if (lid === undefined) continue;
          const e = w.entities.get(lid);
          if (e === s.player || e === this.hostEntity) continue;
          if (e) w.entities.delete(lid);
          this.unmapLocal(lid);
        }
        break;
      case "cast": {
        const c = this.local(m.c);
        if (!c || c === s.player) break;
        const skill = sanitizeSkill(m.s);
        if (!skill) break;
        const t = typeof m.tid === "number" ? this.local(m.tid) : null;
        w.tryCast(c, skill, fin(m.ax, -1e7, 1e7, c.x), fin(m.az, -1e7, 1e7, c.z), t ? t.id : -1, true);
        break;
      }
      case "ev":
        this.events(s, sanitizeEvents(m.e));
        break;
      case "status": {
        const st = m.s;
        const p = s.player;
        if (!st || !CC_KINDS.has(st.kind) || !p.alive || p.invuln > 0) break;
        addStatus(p, { kind: st.kind, t: fin(st.t, 0, 10, 1), dur: fin(st.dur, 0, 10, 1), value: fin(st.value, 0, 1, 0.3) });
        break;
      }
      case "dungeon": {
        if (typeof m.poiId !== "string") break;
        const poi = s.findPoi(m.poiId);
        if (!poi || poi.kind !== "dungeon") break;
        this.epoch = fin(m.ep, 0, 1e9, this.epoch);
        const ret = m.ret && Number.isFinite(m.ret.x) && Number.isFinite(m.ret.z) ? m.ret : null;
        if (ret) s.dungeonReturn = { x: ret.x + 1.5, z: ret.z };
        s.enterDungeon(poi, Math.round(fin(m.floor, 0, 99, 0)));
        this.prune();
        break;
      }
      case "exitDungeon":
        this.epoch = fin(m.ep, 0, 1e9, this.epoch);
        if (s.dungeon && Number.isFinite(m.x) && Number.isFinite(m.z)) {
          s.dungeonReturn = { x: m.x, z: m.z };
          s.exitDungeon(false);
          this.prune();
        }
        break;
      case "emote": {
        const e = this.local(m.id);
        if (!e) break;
        e.action = "meow";
        e.actionT = 0;
        e.actionDur = 0.7;
        audio.play("meow", e.x, e.z, 1, 1 / e.look.size);
        s.fx.handle({ k: "cast", x: e.x, y: e.y + 1.2, z: e.z, v: { color: 0xffd24a, color2: 0xffffff, shape: "note", size: 1, trail: false, glow: 1, style: 0 } });
        break;
      }
      case "toast":
        s.hud.toast(txt(m.text, 200), Math.round(fin(m.color, 0, 0xffffff, 0xffffff)), typeof m.icon === "string" ? m.icon.slice(0, 8) : undefined);
        break;
      case "bye":
        this.handleClose("bye");
        break;
      case "welcome":
      case "snap":
        break;
    }
  }

  /** События хоста: удары, лечение, смерти, уклонения — с переводом id в локальные. */
  private events(s: GameSession, evs: GameEvent[]) {
    const p = s.player;
    const out: GameEvent[] = [];
    const lid = (hid: number) => this.toLocal.get(hid) ?? -1;
    for (const ev of evs) {
      switch (ev.t) {
        case "damage": {
          const id = lid(ev.id),
            by = lid(ev.by);
          if (id === p.id) {
            // Удар по мне: здоровьем гостя распоряжается сам гость
            if (!p.alive || p.invuln > 0) break;
            let dmg = ev.amount;
            if (p.shield > 0) {
              const a = Math.min(p.shield, dmg);
              p.shield -= a;
              dmg -= a;
            }
            p.hp -= dmg;
            p.flash = Math.max(p.flash, ev.dot ? 0.25 : 0.8);
            p.lastCombat = s.world.time;
            out.push({ ...ev, id, by, amount: dmg });
            if (p.hp <= 0) {
              p.hp = 0;
              killEntity(s.world, p, by);
            }
            break;
          }
          const e = s.world.entities.get(id);
          if (e) {
            e.flash = Math.max(e.flash, ev.dot ? 0.25 : 0.8);
            if (!ev.dot && e.kind !== "player" && !e.cast && e.action === null) {
              e.action = "hit";
              e.actionT = 0;
              e.actionDur = 0.3;
            }
          }
          out.push({ ...ev, id, by });
          break;
        }
        case "heal":
          // Лечение от хоста, его тотемов и похищение жизни (посчитано у хоста)
          if (lid(ev.id) === p.id) {
            healEntity(s.world, p, ev.amount, true);
            out.push({ ...ev, id: p.id });
          }
          break;
        case "dodge":
          out.push({ ...ev, id: lid(ev.id) });
          break;
        case "text":
          out.push(ev);
          break;
        case "death": {
          const e = this.local(ev.id);
          if (e && e.alive) {
            e.alive = false;
            e.hp = 0;
            e.state = "dead";
            e.stateT = 0;
            e.deadT = 0;
            e.cast = null;
          }
          out.push({ ...ev, id: e ? e.id : -1, killerId: lid(ev.killerId) });
          break;
        }
        default:
          break;
      }
    }
    if (out.length) s.processEvents(out);
  }

  onEvents() {
    /* Локальные события гостя — только визуал. */
  }

  onLocalCast(_s: GameSession, skill: SkillDef, aimX: number, aimZ: number, targetId: number) {
    this.send({ t: "cast", s: skill, ax: r2(aimX), az: r2(aimZ), tid: this.toHost.get(targetId) ?? -1 });
  }

  onMeow() {
    this.send({ t: "emote", k: "meow" });
  }

  request(k: "dungeon" | "exit" | "stairs", poiId?: string) {
    this.send({ t: "req", k, poiId });
  }

  private handleClose(reason: string) {
    if (this.closed) return;
    this.closed = true;
    for (const d of this.disposers) d();
    const s = this.session;
    if (s) {
      // Продолжаем в одиночку в этом же мире
      const w = s.world;
      for (const [id, e] of w.entities) if (e !== s.player) w.entities.delete(id);
      w.authority = true;
      if (s.net === this) s.net = null;
      this.hostEntity = null;
      if (s.dungeon) s.exitDungeon(true);
      s.hud.toast({ ru: "Связь с хостом потеряна — игра продолжается в одиночку", en: "Lost connection to the host — continuing solo" }, 0xffb454, "🔌");
    }
    this.hooks.onClosed(reason);
  }

  close() {
    if (this.closed) return;
    this.send({ t: "bye" });
    const peer = this.peer;
    setTimeout(() => peer.close(), 150);
    this.handleClose("local");
  }
}
