import { observer } from "mobx-react-lite";
import { useEffect, useMemo, useState } from "react";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn } from "../common";
import { CLASSES } from "../../game/classes";
import { CLASS_IDS, MODE_PRESETS, type ClassId, type ModeConfig } from "../../game/types";
import { classLook, EYE_COLORS, FUR_COLORS, type CatLook, type FurPattern } from "../../game/cats/look";
import { CharacterStore, newCharacter } from "../../game/character";
import { catName } from "../../game/world/names";
import { Rng } from "../../core/rng";
import { hex } from "../icons";
import type { MenuBackdrop } from "../menu-backdrop";

const PATTERNS: { id: FurPattern; name: { ru: string; en: string } }[] = [
  { id: "solid", name: { ru: "Однотонный", en: "Solid" } },
  { id: "tabby", name: { ru: "Полосатый", en: "Tabby" } },
  { id: "spots", name: { ru: "Пятнистый", en: "Spotted" } },
  { id: "tuxedo", name: { ru: "Смокинг", en: "Tuxedo" } },
  { id: "calico", name: { ru: "Трёхцветный", en: "Calico" } },
  { id: "siamese", name: { ru: "Сиамский", en: "Siamese" } },
  { id: "tortie", name: { ru: "Черепаховый", en: "Tortie" } },
  { id: "bicolor", name: { ru: "Двухцветный", en: "Bicolor" } },
  { id: "tiger", name: { ru: "Тигровый", en: "Tiger" } },
];

export const NewGame = observer(({ backdrop }: { backdrop: MenuBackdrop | null }) => {
  const s = useStore();
  const [preset, setPreset] = useState<"campaign" | "endless" | "custom">("campaign");
  const [mode, setMode] = useState<ModeConfig>({ ...MODE_PRESETS.campaign });
  const [cls, setCls] = useState<ClassId>("warrior");
  const [name, setName] = useState(() => tr(catName(new Rng(Date.now()), 0)));
  const [look, setLook] = useState<Partial<CatLook>>({});
  const [seed, setSeed] = useState(() => String(Math.floor(Math.random() * 1e9)));
  const fullLook = useMemo(() => classLook(cls, look), [cls, look]);
  useEffect(() => {
    backdrop?.setPreview(fullLook);
    return () => backdrop?.setPreview(null);
  }, [backdrop, fullLook]);
  const setP = (p: "campaign" | "endless" | "custom") => {
    setPreset(p);
    if (p !== "custom") setMode({ ...MODE_PRESETS[p] });
  };
  const start = () => {
    const seedNum = parseInt(seed.replace(/\D/g, "").slice(0, 9)) || 12345;
    const data = newCharacter({ name: name.trim() || "Мурзик", classId: cls, look, mode, seed: seedNum });
    s.saves.save(data);
    s.play(new CharacterStore(data));
  };
  const c = CLASSES[cls];
  return (
    <div className="menu-screen" style={{ justifyContent: "flex-start" }}>
      <div className="menu-card">
        <h2>{tr({ ru: "Новый котик", en: "New cat" })}</h2>
        <div className="label">{tr({ ru: "Режим", en: "Mode" })}</div>
        <div className="mode-grid">
          <div className={`mode-card${preset === "campaign" ? " sel" : ""}`} onClick={() => setP("campaign")}>
            <b>🗺️ {tr({ ru: "Кампания", en: "Campaign" })}</b>
            <p>{tr({ ru: "Огромный материк: сотни городов, тысячи заданий и подземелий. 100 уровней, ~300 навыков у класса. Сюжет «Девять колокольчиков».", en: "A huge continent: hundreds of towns, thousands of quests and dungeons. 100 levels, ~300 skills per class. The “Nine Bells” story." })}</p>
          </div>
          <div className={`mode-card${preset === "endless" ? " sel" : ""}`} onClick={() => setP("endless")}>
            <b>♾️ {tr({ ru: "Бесконечность", en: "Endless" })}</b>
            <p>{tr({ ru: "Мир генерируется без конца, уровни без предела, дерево навыков растёт бесконечно. Новые эпохи сюжета.", en: "The world generates forever, levels are unlimited and the skill tree grows endlessly. New story eras." })}</p>
          </div>
          <div className={`mode-card${preset === "custom" ? " sel" : ""}`} onClick={() => setP("custom")}>
            <b>🎛️ {tr({ ru: "Свой режим", en: "Custom" })}</b>
            <p>{tr({ ru: "Выберите отдельно: мир, навыки и уровни.", en: "Pick world, skills and levels separately." })}</p>
          </div>
        </div>
        {preset === "custom" && (
          <div className="col" style={{ marginTop: 10 }}>
            <div className="seg">
              <button className={mode.world === "continent" ? "on" : ""} onClick={() => setMode({ ...mode, world: "continent" })}>
                {tr({ ru: "Материк", en: "Continent" })}
              </button>
              <button className={mode.world === "infinite" ? "on" : ""} onClick={() => setMode({ ...mode, world: "infinite" })}>
                {tr({ ru: "∞ мир", en: "∞ world" })}
              </button>
            </div>
            <div className="seg">
              <button className={mode.skills === "classic" ? "on" : ""} onClick={() => setMode({ ...mode, skills: "classic" })}>
                {tr({ ru: "300 навыков", en: "300 skills" })}
              </button>
              <button className={mode.skills === "infinite" ? "on" : ""} onClick={() => setMode({ ...mode, skills: "infinite" })}>
                {tr({ ru: "∞ навыки", en: "∞ skills" })}
              </button>
            </div>
            <div className="seg">
              <button className={mode.levels === "capped" ? "on" : ""} onClick={() => setMode({ ...mode, levels: "capped" })}>
                {tr({ ru: "100 уровней", en: "100 levels" })}
              </button>
              <button className={mode.levels === "infinite" ? "on" : ""} onClick={() => setMode({ ...mode, levels: "infinite" })}>
                {tr({ ru: "∞ уровни", en: "∞ levels" })}
              </button>
            </div>
          </div>
        )}
        <div className="label" style={{ marginTop: 14 }}>
          {tr({ ru: "Класс", en: "Class" })}
        </div>
        <div className="class-grid">
          {CLASS_IDS.map((id) => {
            const cd = CLASSES[id];
            return (
              <div key={id} className={`class-card${cls === id ? " sel" : ""}`} onClick={() => setCls(id)} style={{ borderColor: cls === id ? hex(cd.color) : undefined }}>
                <div style={{ fontSize: 26 }}>{["⚔️", "🔮", "🏹", "🗡️", "✨", "💀", "🌿"][CLASS_IDS.indexOf(id)]}</div>
                <div className="cname">{tr(cd.name)}</div>
                <div className="cbreed">{tr(cd.breed)}</div>
              </div>
            );
          })}
        </div>
        <div style={{ margin: "10px 0", fontSize: 14 }} className="muted">
          <b style={{ color: hex(c.color) }}>{tr(c.name)}</b> — {tr(c.desc)} {tr({ ru: "Школы:", en: "Schools:" })} {c.schools.map((sc) => tr(sc.name)).join(", ")}.
        </div>
        <div className="row" style={{ alignItems: "flex-end" }}>
          <div style={{ flex: "1 1 200px" }}>
            <div className="label">{tr({ ru: "Имя", en: "Name" })}</div>
            <div className="row" style={{ flexWrap: "nowrap" }}>
              <input type="text" value={name} maxLength={20} onChange={(e) => setName(e.target.value)} />
              <Btn small onClick={() => setName(tr(catName(new Rng(Math.random() * 1e9), 0)))}>
                🎲
              </Btn>
            </div>
          </div>
          <div style={{ flex: "1 1 160px" }}>
            <div className="label">{tr({ ru: "Seed мира", en: "World seed" })}</div>
            <div className="row" style={{ flexWrap: "nowrap" }}>
              <input type="text" value={seed} maxLength={12} onChange={(e) => setSeed(e.target.value)} />
              <Btn small onClick={() => setSeed(String(Math.floor(Math.random() * 1e9)))}>
                🎲
              </Btn>
            </div>
          </div>
        </div>
        <div className="label" style={{ marginTop: 12 }}>
          {tr({ ru: "Окрас", en: "Fur" })}
        </div>
        <div className="swatches">
          {FUR_COLORS.map((f) => (
            <div key={f} className={`swatch${fullLook.fur === f ? " sel" : ""}`} style={{ background: hex(f) }} onClick={() => setLook({ ...look, fur: f })} />
          ))}
        </div>
        <div className="swatches" style={{ marginTop: 8 }}>
          {PATTERNS.map((p) => (
            <Btn key={p.id} small kind={fullLook.pattern === p.id ? "primary" : "ghost"} onClick={() => setLook({ ...look, pattern: p.id, fur2: p.id === "tuxedo" || p.id === "bicolor" ? 0xf8f4ee : p.id === "calico" ? 0xe08a3a : p.id === "tiger" ? 0x1a1a1a : p.id === "siamese" ? 0x4a3428 : look.fur2 ?? fullLook.fur2 })}>
              {tr(p.name)}
            </Btn>
          ))}
        </div>
        <div className="label" style={{ marginTop: 8 }}>
          {tr({ ru: "Глаза", en: "Eyes" })}
        </div>
        <div className="swatches">
          {EYE_COLORS.map((e) => (
            <div key={e} className={`swatch${fullLook.eyes === e ? " sel" : ""}`} style={{ background: hex(e) }} onClick={() => setLook({ ...look, eyes: e })} />
          ))}
        </div>
        <div className="row" style={{ marginTop: 16 }}>
          <Btn onClick={() => s.ui.go("menu")}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
          <div className="spacer" />
          <Btn kind="primary" onClick={start}>
            🐾 {tr({ ru: "Начать приключение", en: "Start adventure" })}
          </Btn>
        </div>
      </div>
    </div>
  );
});
