export interface Affix {
  kind: "stat" | "element" | "delivery" | "xp" | "fish";
  stat?: StatKey;
  el?: Element;
  delivery?: Delivery;
  value: number;
  pct?: boolean;
}

export interface LegendaryEffect {
  name: Txt;
  desc: Txt;
  /** Модификаторы для всех навыков определённого типа доставки. */
  delivery?: Delivery;
  mods?: SkillMod[];
}

export interface GearData {
  slot: ItemSlot;
  power?: number;
  armor?: number;
  hp?: number;
  mp?: number;
  affixes: Affix[];
  legendary?: LegendaryEffect;
  look?: { hat?: HatKind; hatColor?: number; weapon?: WeaponKind; weaponColor?: number; collar?: number };
}

export type ItemKind = "gear" | "tome" | "quest" | "key";

export interface Item {
  id: string;
  kind: ItemKind;
  name: Txt;
  level: number;
  rarity: Rarity;
  icon: string;
  value: number;
  stack?: number;
  gear?: GearData;
  questId?: string;
}

let idCounter = 0;
export function newItemId(rng?: Rng): string {
  idCounter++;
  return `i${Date.now().toString(36)}${(rng ? rng.id() : Math.floor(Math.random() * 1e9)).toString(36)}${idCounter}`;
}

