function statAffix(rng: Rng, level: number, rarity: number): Affix {
  const ls = levelScale(level);
  const r = RARITY_MUL[rarity];
  const pool: [StatKey, number, boolean][] = [
    ["power", 2.2 * ls * r, false],
    ["armor", 3 * ls * r, false],
    ["maxHp", 14 * ls * r, false],
    ["maxMp", 12 * r, false],
    ["crit", 0.02 * r, false],
    ["critDmg", 0.1 * r, false],
    ["haste", 0.035 * r, false],
    ["moveSpeed", 0.03 * r, false],
    ["lifesteal", 0.012 * r, false],
    ["dodge", 0.015 * r, false],
    ["resist", 0.025 * r, false],
    ["hpRegen", 0.8 * r, false],
    ["mpRegen", 0.6 * r, false],
    ["thorns", 0.08 * r, false],
    ["summonPct", 0.08 * r, false],
    ["healPct", 0.08 * r, false],
    ["areaPct", 0.05 * r, false],
    ["durationPct", 0.08 * r, false],
  ];
  const [stat, v] = rng.pick(pool);
  return { kind: "stat", stat, value: v * rng.range(0.8, 1.2) };
}

function randomAffix(rng: Rng, level: number, rarity: number): Affix {
  const roll = rng.next();
  if (roll < 0.14) return { kind: "element", el: rng.pick(ELEMENTS), value: (0.06 + 0.02 * rarity) * rng.range(0.8, 1.2) };
  if (roll < 0.22) {
    const ds: Delivery[] = ["strike", "projectile", "nova", "blast", "cone", "beam", "chain", "summon", "aura", "trap", "totem", "rain", "leap"];
    return { kind: "delivery", delivery: rng.pick(ds), value: (0.08 + 0.025 * rarity) * rng.range(0.8, 1.2) };
  }
  if (roll < 0.25) return { kind: "xp", value: 0.04 + 0.015 * rarity };
  if (roll < 0.28) return { kind: "fish", value: 0.08 + 0.03 * rarity };
  return statAffix(rng, level, rarity);
}

export function rollRarity(rng: Rng, luck = 0, level = 1): Rarity {
  const w = [55, 28, 12 + luck * 4, 4 + luck * 3, 0.9 + luck * 1.2, level >= 30 ? 0.12 + luck * 0.3 : 0];
  return rng.weighted([0, 1, 2, 3, 4, 5] as Rarity[], w);
}

export function makeGear(rng: Rng, level: number, rarity: Rarity, classId: ClassId, slot?: ItemSlot): Item {
  slot = slot ?? rng.pick(SLOTS);
  const ls = levelScale(level);
  const rm = RARITY_MUL[rarity];
  const gear: GearData = { slot, affixes: [] };
  let baseNoun: Noun;
  let icon = "🎁";
  switch (slot) {
    case "weapon": {
      const wk = rng.pick(WEAPON_BY_CLASS[classId]);
      baseNoun = rng.pick(WEAPON_NOUNS[wk]);
      gear.power = 3.2 * ls * rm * rng.range(0.9, 1.1);
      gear.look = { weapon: wk, weaponColor: rng.pick([0xd8e0e8, 0xf2d27a, 0x7ad8ff, 0xff7a5a, 0x9aff8a, 0xd08aff, 0xffffff]) };
      icon = { sword: "🗡️", mace: "🔨", staff: "🪄", tome: "📕", bow: "🏹", daggers: "🔪", scythe: "🌙", totem: "🗿" }[wk as string] ?? "⚔️";
      break;
    }
    case "head": {
      const hk = rng.pick(HEAD_BY_CLASS[classId]);
      baseNoun = HAT_NOUNS[hk];
      gear.armor = 2.2 * ls * rm;
      gear.hp = 8 * ls * rm;
      gear.look = { hat: hk, hatColor: rng.pick([0x4a3ab0, 0xb8c0c8, 0x3a7a3a, 0x8a2a3a, 0xf2d27a, 0x2a2038, 0xd87a3a, 0x3a8ad8]) };
      icon = "🎩";
      break;
    }
    case "body":
      baseNoun = rng.pick(BODY_NOUNS);
      gear.armor = 4.5 * ls * rm;
      gear.hp = 16 * ls * rm;
      icon = "🧥";
      break;
    case "paws":
      baseNoun = rng.pick(PAW_NOUNS);
      gear.armor = 1.6 * ls * rm;
      gear.affixes.push({ kind: "stat", stat: "moveSpeed", value: 0.03 + 0.01 * rarity });
      icon = "🧦";
      break;
    case "collar":
      baseNoun = rng.pick(COLLAR_NOUNS);
      gear.hp = 10 * ls * rm;
      gear.mp = 8 * rm;
      gear.look = { collar: rng.pick([0xd23a3a, 0x3a7ad2, 0x3ad27a, 0xd2a03a, 0xa03ad2, 0xf2f2f2, 0x2a2a2a]) };
      icon = "📿";
      break;
    default:
      baseNoun = rng.pick(CHARM_NOUNS);
      gear.affixes.push({ kind: "stat", stat: "crit", value: 0.01 + 0.006 * rarity });
      icon = "🔔";
      break;
  }
  const nAff = [rng.int(0, 1), rng.int(1, 2), rng.int(2, 3), rng.int(3, 4), 4, 5][rarity];
  for (let i = 0; i < nAff; i++) gear.affixes.push(randomAffix(rng, level, rarity));
  let name: Txt;
  if (rarity >= 4) {
    const cands = LEGENDARIES.filter((l) => !l.slot || l.slot === slot);
    const lg = rng.pick(cands.length ? cands : LEGENDARIES);
    gear.legendary = { name: lg.name, desc: lg.desc, delivery: lg.delivery, mods: lg.mods };
    if (lg.affix) gear.affixes.push({ ...lg.affix });
    name = rarity === 5 ? { ru: `${lg.name.ru} ✦`, en: `${lg.name.en} ✦` } : lg.name;
  } else {
    const q = rng.pick(QUALITY_ADJ[rarity]);
    const main = gear.affixes.find((a) => a.kind === "stat") ?? gear.affixes[0];
    const suf = main ? SUFFIX[main.kind === "stat" ? main.stat! : main.kind] : null;
    const bn = { ru: `${q[baseNoun.g]} ${baseNoun.ru.charAt(0).toLowerCase()}${baseNoun.ru.slice(1)}`, en: `${q.en} ${baseNoun.en}` };
    name = suf && rarity >= 1 ? { ru: `${bn.ru} ${suf.ru}`, en: `${bn.en} ${suf.en}` } : bn;
  }
  const value = Math.max(1, Math.round(6 * priceScale(level) * rm * (1 + rarity * 0.6)));
  return { id: newItemId(rng), kind: "gear", name, level, rarity, icon, value, gear };
}

export function makeTome(level: number): Item {
  return {
    id: newItemId(),
    kind: "tome",
    name: { ru: "Книга усов", en: "Tome of Whiskers" },
    level,
    rarity: 3,
    icon: "📖",
    value: Math.round(40 * priceScale(level)),
    stack: 1,
  };
}

export function makeQuestItem(questId: string, name: Txt, icon: string): Item {
  return { id: newItemId(), kind: "quest", name, level: 1, rarity: 1, icon, value: 0, stack: 1, questId };
}

export function affixText(a: Affix): Txt {
  const pctS = (v: number) => `${Math.round(v * 100)}%`;
  const fmt = (v: number) => (v >= 100 ? Math.round(v).toLocaleString("ru") : v >= 10 ? v.toFixed(0) : v.toFixed(1));
  switch (a.kind) {
    case "stat": {
      const n = STAT_NAMES[a.stat!].name;
      const isPct = ["crit", "critDmg", "haste", "moveSpeed", "lifesteal", "dodge", "resist", "thorns", "summonPct", "healPct", "areaPct", "durationPct"].includes(a.stat!);
      const v = isPct ? pctS(a.value) : fmt(a.value);
      return { ru: `+${v} ${n.ru.toLowerCase()}`, en: `+${v} ${n.en.toLowerCase()}` };
    }
    case "element":
      return { ru: `+${pctS(a.value)} к урону: ${ELEMENT_NAMES[a.el!].ru.toLowerCase()}`, en: `+${pctS(a.value)} ${ELEMENT_NAMES[a.el!].en.toLowerCase()} damage` };
    case "delivery":
      return { ru: `+${pctS(a.value)} к урону: ${DELIVERY_NAMES[a.delivery!].ru.toLowerCase()}`, en: `+${pctS(a.value)} ${DELIVERY_NAMES[a.delivery!].en.toLowerCase()} damage` };
    case "xp":
      return { ru: `+${pctS(a.value)} опыта`, en: `+${pctS(a.value)} XP` };
    case "fish":
      return { ru: `+${pctS(a.value)} рыбок`, en: `+${pctS(a.value)} fish` };
  }
}

/** Оценка «силы» предмета для сравнения. */
export function gearScore(it: Item): number {
  if (!it.gear) return 0;
  const g = it.gear;
  const ls = levelScale(it.level);
  let s = (g.power ?? 0) * 3 + (g.armor ?? 0) * 1.2 + (g.hp ?? 0) * 0.25 + (g.mp ?? 0) * 0.1;
  s += g.affixes.length * 4 * ls;
  if (g.legendary) s += 25 * ls;
  return s;
}
