/** Живой 3D-фон для меню: город, коты-жители и превью выбранного класса. */
import { Renderer } from "../engine/renderer";
import { CatRenderer } from "../engine/cats";
import { ParticleSystem } from "../engine/particles";
import { makeCatInstance, type CatAction, type CatInstance } from "../engine/cat-types";
import { WorldGen } from "../game/world/worldgen";
import { TerrainCache } from "../game/world/terrain-cache";
import { MODE_PRESETS } from "../game/types";
import { villagerLook, type CatLook } from "../game/cats/look";
import { Rng } from "../core/rng";
import type { QualityLevel } from "../engine/renderer";

export class MenuBackdrop {
  private r: Renderer;
  private cats: CatRenderer;
  private ps: ParticleSystem;
  private cache: TerrainCache;
  private villagers: CatInstance[] = [];
  private preview: CatInstance | null = null;
  private raf = 0;
  private last = 0;
  private t = 0;
  private cx = 0;
  private cz = 0;
  private running = false;
  private actions: CatAction[] = ["meow", "swipe", "raise", "pounce", "spin", "wave", "summon", "roar"];

  constructor(canvas: HTMLCanvasElement, quality: QualityLevel) {
    this.r = new Renderer(canvas);
    const gen = new WorldGen(424242, MODE_PRESETS.campaign);
    this.cache = new TerrainCache(gen);
    this.r.setWorld(this.cache);
    this.r.setQuality(quality === "high" ? "medium" : quality);
    this.r.env.timeOfDay = 0.72;
    this.r.env.dayLength = 600;
    this.cats = new CatRenderer(this.r.gl);
    this.ps = new ParticleSystem(this.r.gl, 400);
    this.r.passes.push(this.cats, this.ps);
    const town = gen.regionAt(gen.start.x, gen.start.z).town;
    this.cx = town ? town.x : gen.start.x;
    this.cz = town ? town.z : gen.start.z;
    const rng = new Rng(9);
    for (let i = 0; i < 9; i++) {
      const c = makeCatInstance(i + 1, villagerLook(rng));
      const a = (i / 9) * Math.PI * 2;
      c.x = this.cx + Math.cos(a) * rng.range(4, 12);
      c.z = this.cz + Math.sin(a) * rng.range(4, 12);
      c.yaw = rng.next() * 6;
      c.state = rng.chance(0.4) ? "sit" : rng.chance(0.3) ? "loaf" : "alive";
      this.villagers.push(c);
    }
    const cam = this.r.camera;
    cam.tx = this.cx;
    cam.tz = this.cz;
    cam.distance = 24;
    cam.pitch = 0.42;
  }

  setPreview(look: CatLook | null) {
    if (!look) {
      this.preview = null;
      return;
    }
    if (!this.preview) this.preview = makeCatInstance(999, look);
    this.preview.look = look;
  }

  start() {
    this.running = true;
    this.last = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      this.raf = requestAnimationFrame(loop);
      const dt = Math.min(0.05, (now - this.last) / 1000);
      this.last = now;
      this.frame(dt);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  destroy() {
    this.stop();
    this.r.dispose();
  }

  private frame(dt: number) {
    this.t += dt;
    const r = this.r;
    const cam = r.camera;
    const ground = (x: number, z: number) => this.cache.heightAt(x, z);
    if (this.preview) {
      const p = this.preview;
      p.x = this.cx + 3;
      p.z = this.cz + 16;
      p.y = ground(p.x, p.z);
      p.yaw = Math.sin(this.t * 0.5) * 0.6 + 0.3;
      const cycle = (this.t / 2.4) % this.actions.length;
      const ai = Math.floor(cycle);
      const frac = cycle - ai;
      p.action = frac < 0.55 ? this.actions[ai] : null;
      p.actionT = frac / 0.55;
      cam.tx += (p.x + 1.2 - cam.tx) * Math.min(1, dt * 3);
      cam.tz += (p.z - cam.tz) * Math.min(1, dt * 3);
      cam.ty = p.y + 0.9;
      cam.distance += (4.6 - cam.distance) * Math.min(1, dt * 3);
      cam.pitch += (0.25 - cam.pitch) * Math.min(1, dt * 3);
      cam.yaw = 0.35 + Math.sin(this.t * 0.2) * 0.15;
      if (Math.random() < dt * 6) this.ps.emit({ x: p.x + (Math.random() - 0.5) * 2, y: p.y + Math.random() * 1.5, z: p.z + (Math.random() - 0.5) * 2, vy: 0.6, life: 1.2, size: 0.08, color: 0xffd27a, shape: "star" });
    } else {
      cam.tx += (this.cx - cam.tx) * Math.min(1, dt * 2);
      cam.tz += (this.cz - cam.tz) * Math.min(1, dt * 2);
      cam.ty = ground(cam.tx, cam.tz) + 2;
      cam.distance += (26 - cam.distance) * Math.min(1, dt * 2);
      cam.pitch += (0.42 - cam.pitch) * Math.min(1, dt * 2);
      cam.yaw = this.t * 0.04;
    }
    r.updateWorld(6);
    this.cats.begin(cam.ox, cam.oz, dt);
    r.shadows.length = 0;
    for (const c of this.villagers) {
      c.y = ground(c.x, c.z);
      if (Math.random() < dt * 0.1) {
        c.action = "meow";
        c.actionT = 0;
      }
      if (c.action) {
        c.actionT += dt / 0.8;
        if (c.actionT >= 1) c.action = null;
      }
      this.cats.add(c, dt, Math.hypot(c.x - cam.ex, c.z - cam.ez));
      r.shadows.push({ x: c.x, y: c.y, z: c.z, r: 0.7 });
    }
    if (this.preview) {
      this.cats.add(this.preview, dt, 4);
      r.shadows.push({ x: this.preview.x, y: this.preview.y, z: this.preview.z, r: 0.8 * this.preview.look.size });
    }
    this.ps.setOrigin(cam.ox, cam.oz);
    this.ps.update(dt);
    r.render(dt, ground);
  }
}
