import { observer } from "mobx-react-lite";
import { useEffect, useMemo, useRef, useState } from "react";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn, Panel } from "../common";
import { Glyph, hex } from "../icons";
import { describeNode } from "../../game/skills/describe";
import { CLASSES } from "../../game/classes";
import type { SkillNode } from "../../game/skills/types";
import { audio } from "../../audio/audio";

interface LNode {
  n: SkillNode;
  x: number;
  y: number;
  r: number;
}

const RING = 70;

function layout(nodes: Map<string, SkillNode>, root: SkillNode, visible: (n: SkillNode) => boolean): LNode[] {
  const leaves = new Map<string, number>();
  const kids = (n: SkillNode) => (n.children ?? []).map((c) => nodes.get(c)!).filter((c) => c && visible(c));
  const count = (n: SkillNode): number => {
    const ks = kids(n);
    const v = ks.length === 0 ? 1 : ks.reduce((a, k) => a + count(k), 0);
    leaves.set(n.id, v);
    return v;
  };
  count(root);
  const out: LNode[] = [];
  const place = (n: SkillNode, a0: number, a1: number, depth: number) => {
    const a = (a0 + a1) / 2;
    const rad = depth * RING;
    const r = n.kind === "root" ? 30 : n.kind === "keystone" ? 24 : n.kind === "active" ? 22 : 16;
    out.push({ n, x: Math.cos(a) * rad, y: Math.sin(a) * rad, r });
    const ks = kids(n);
    if (!ks.length) return;
    const total = ks.reduce((s, k) => s + (leaves.get(k.id) ?? 1), 0);
    let cur = a0;
    for (const k of ks) {
      const span = ((a1 - a0) * (leaves.get(k.id) ?? 1)) / total;
      place(k, cur, cur + span, depth + 1);
      cur += span;
    }
  };
  place(root, -Math.PI / 2 - Math.PI, -Math.PI / 2 + Math.PI, 0);
  return out;
}

export const SkillTreePanel = observer(() => {
  const s = useStore();
  const c = s.char!;
  const tree = c.tree;
  const d = c.data;
  void c.rev;
  const learned = c.learnedSet;
  const infinite = d.mode.skills === "infinite";
  // В бесконечном режиме раскрываем детей изученных узлов (предпросмотр следующего шага)
  if (infinite) for (const id of learned) tree.expand(id);
  const nodesCount = tree.nodes.size;
  const visible = (n: SkillNode) => !infinite || n.kind === "root" || learned.has(n.id) || (n.parent !== null && learned.has(n.parent));
  const lay = useMemo(() => layout(tree.nodes, tree.root, visible), [nodesCount, learned.size, infinite]);
  const byId = useMemo(() => new Map(lay.map((l) => [l.n.id, l])), [lay]);
  const [sel, setSel] = useState<string | null>(null);
  const [view, setView] = useState({ x: 0, y: 0, k: 1 });
  const svgRef = useRef<SVGSVGElement>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  // 1 единица SVG = 1 CSS-пиксель: узлы одинакового размера на телефоне и ПК
  const [box, setBox] = useState({ w: 800, h: 500 });
  useEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    const upd = () => setBox({ w: Math.max(100, el.clientWidth), h: Math.max(100, el.clientHeight) });
    upd();
    const ro = new ResizeObserver(upd);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  const ptrs = useRef(new Map<number, { x: number; y: number }>());
  const moved = useRef(0);
  const pinch = useRef<number | null>(null);
  const node = sel ? tree.get(sel) : null;
  const canLearn = node ? c.canLearn(node.id) : false;
  const pick = (id: string) => {
    if (moved.current > 8) return;
    setSel(id);
    audio.play("click");
  };
  const onDown = (e: React.PointerEvent) => {
    ptrs.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    moved.current = 0;
  };
  const onMove = (e: React.PointerEvent) => {
    const p = ptrs.current.get(e.pointerId);
    if (!p) return;
    if (ptrs.current.size >= 2) {
      const pts = [...ptrs.current.entries()].map(([id, v]) => (id === e.pointerId ? { x: e.clientX, y: e.clientY } : v));
      const dd = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      if (pinch.current) setView((v) => ({ ...v, k: Math.min(2.5, Math.max(0.15, (v.k * dd) / pinch.current!)) }));
      pinch.current = dd;
      moved.current += 10;
    } else {
      const dx = e.clientX - p.x,
        dy = e.clientY - p.y;
      moved.current += Math.abs(dx) + Math.abs(dy);
      // Захватываем указатель, только когда начали тащить: захват сразу при нажатии уводит
      // pointerup (и click) с узла на контейнер, и узел мышью не выбирался
      const el = e.currentTarget as Element;
      if (moved.current > 8 && !el.hasPointerCapture?.(e.pointerId)) el.setPointerCapture?.(e.pointerId);
      setView((v) => ({ ...v, x: v.x + dx, y: v.y + dy }));
    }
    p.x = e.clientX;
    p.y = e.clientY;
  };
  const onUp = (e: React.PointerEvent) => {
    const wasDown = ptrs.current.delete(e.pointerId);
    if (ptrs.current.size < 2) pinch.current = null;
    if (!wasDown || e.type !== "pointerup") return;
    // Узел — по точке отпускания, а не по цели события (она может быть контейнером)
    const hit = document.elementFromPoint(e.clientX, e.clientY)?.closest("[data-node]");
    const id = hit?.getAttribute("data-node");
    if (id) pick(id);
  };
  const onWheel = (e: React.WheelEvent) => {
    const k = Math.exp(-e.deltaY * 0.0015);
    setView((v) => ({ ...v, k: Math.min(2.5, Math.max(0.15, v.k * k)) }));
  };
  const learn = () => {
    if (node && c.learn(node.id)) {
      audio.play("cast_buff");
      s.session && s.session.world.applyStats(s.session.player, c.stats);
    }
  };
  const center = () => {
    // центрируем на «фронтире» изученного
    let far: LNode | null = null;
    for (const l of lay) if (learned.has(l.n.id) && (!far || Math.hypot(l.x, l.y) > Math.hypot(far.x, far.y))) far = l;
    setView({ x: far ? -far.x * 0.9 : 0, y: far ? -far.y * 0.9 : 0, k: 0.9 });
  };
  const status = (n: SkillNode) => (learned.has(n.id) ? "learned" : tree.canLearn(n.id, learned, d.level) ? "avail" : n.parent && learned.has(n.parent) ? "level" : "locked");
  const cls = CLASSES[d.classId];
  return (
    <Panel title={{ ru: `Навыки · очков: ${d.skillPoints}`, en: `Skills · points: ${d.skillPoints}` }} onClose={() => s.ui.close()} wide className="panel-skills">
      <div className="skill-layout">
        <div className="row" style={{ gap: 6 }}>
          <div className="skill-slots">
            {d.slots.map((id, i) => {
              const sk = id ? c.skills.get(id) : null;
              const n = id ? tree.get(id) : null;
              return (
                <div
                  key={i}
                  className="skill-slot"
                  style={{ borderStyle: sk ? "solid" : "dashed", borderColor: sk ? hex(sk.visual.color) : undefined, background: sk ? hex(sk.visual.color, 0.25) : undefined }}
                  onClick={() => {
                    if (node?.kind === "active" && learned.has(node.id)) c.setSlot(i, node.id);
                    else if (id) setSel(id);
                  }}
                  title={sk ? tr(sk.name) : ""}
                >
                  <span className="n">{i + 1}</span>
                  {n && <Glyph name={n.glyph} size={26} color={hex(sk!.visual.color)} />}
                </div>
              );
            })}
          </div>
        </div>
        <div ref={boxRef} className="skilltree" onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onWheel={onWheel}>
          {/* Масштаб — поверх дерева, чтобы не занимать отдельный ряд на телефоне */}
          <div className="skilltree-zoom" onPointerDown={(e) => e.stopPropagation()} onPointerUp={(e) => e.stopPropagation()}>
          <Btn small kind="ghost" onClick={() => setView((v) => ({ ...v, k: Math.min(2.5, v.k * 1.25) }))}>
            ＋
          </Btn>
          <Btn small kind="ghost" onClick={() => setView((v) => ({ ...v, k: Math.max(0.15, v.k / 1.25) }))}>
            －
          </Btn>
          <Btn small kind="ghost" onClick={center}>
            ◎
          </Btn>
          </div>
          <svg ref={svgRef} viewBox={`${-box.w / 2} ${-box.h / 2} ${box.w} ${box.h}`} preserveAspectRatio="xMidYMid meet">
            <defs>
              <radialGradient id="glow">
                <stop offset="0%" stopColor="#fff" stopOpacity="0.6" />
                <stop offset="100%" stopColor="#fff" stopOpacity="0" />
              </radialGradient>
            </defs>
            <g transform={`translate(${view.x} ${view.y}) scale(${view.k})`}>
              {cls.schools.map((sc, i) => {
                const a = -Math.PI / 2 - Math.PI + ((i + 0.5) / 3) * Math.PI * 2;
                return (
                  <text key={i} x={Math.cos(a) * 120} y={Math.sin(a) * 120} fill={hex(sc.color)} fontSize={26} fontWeight={900} textAnchor="middle" opacity={0.55}>
                    {tr(sc.name)}
                  </text>
                );
              })}
              {lay.map((l) => {
                if (!l.n.parent) return null;
                const p = byId.get(l.n.parent);
                if (!p) return null;
                const lit = learned.has(l.n.id);
                return <line key={"e" + l.n.id} x1={p.x} y1={p.y} x2={l.x} y2={l.y} stroke={lit ? "#ffd24a" : "rgba(255,255,255,0.18)"} strokeWidth={lit ? 5 : 3} />;
              })}
              {lay.map((l) => {
                const n = l.n;
                const st = status(n);
                const col = hex(n.color);
                const isSel = sel === n.id;
                return (
                  <g key={n.id} transform={`translate(${l.x} ${l.y})`} data-node={n.id} style={{ cursor: "pointer" }}>
                    {st === "avail" && <circle r={l.r + 10} fill="url(#glow)" />}
                    {n.kind === "keystone" ? (
                      <path d={starPath(l.r)} fill={st === "learned" ? "#ffd24a" : "#2a2040"} stroke={st === "locked" ? "#555" : "#ffd24a"} strokeWidth={3} />
                    ) : (
                      <circle r={l.r} fill={st === "learned" ? col : "#231a36"} stroke={st === "learned" ? "#ffd24a" : st === "avail" ? col : st === "level" ? "#8a7aa0" : "#443a56"} strokeWidth={st === "avail" ? 4 : 3} />
                    )}
                    <g transform={`translate(${-l.r * 0.6} ${-l.r * 0.6})`} opacity={st === "locked" ? 0.35 : 1}>
                      <Glyph name={n.glyph} size={l.r * 1.2} color={st === "learned" ? "#1a1024" : col} stroke={2.4} />
                    </g>
                    {isSel && <circle r={l.r + 6} fill="none" stroke="#fff" strokeWidth={3} strokeDasharray="6 5" />}
                    {st !== "learned" && view.k > 0.5 && n.reqLevel > 1 && (
                      <text y={l.r + 13} fontSize={11} fill={d.level >= n.reqLevel ? "#9ad0ff" : "#ff8a8a"} textAnchor="middle" fontWeight={800}>
                        {n.reqLevel}
                      </text>
                    )}
                  </g>
                );
              })}
            </g>
          </svg>
        </div>
        {node ? (
          <div className="skill-info">
            {/* Кнопка «Изучить» — в первой строке: на телефоне описание ниже может не поместиться */}
            <div className="skill-info-head">
              <h3 style={{ color: hex(node.color) }}>{tr(node.name)}</h3>
              <div className="row" style={{ gap: 8 }}>
              {learned.has(node.id) ? (
                <span className="good">✓ {tr({ ru: "Изучено", en: "Learned" })}</span>
              ) : (
                <Btn small kind="primary" disabled={!canLearn} onClick={learn}>
                  {tr({ ru: "Изучить (1 очко)", en: "Learn (1 point)" })}
                </Btn>
              )}
              {!learned.has(node.id) && !canLearn && (
                <span className="muted" style={{ fontSize: 13 }}>
                  {d.skillPoints <= 0
                    ? tr({ ru: "Нет очков навыков", en: "No skill points" })
                    : node.parent && !learned.has(node.parent)
                      ? tr({ ru: "Сначала изучите предыдущий узел", en: "Learn the previous node first" })
                      : tr({ ru: `Нужен ${node.reqLevel} уровень`, en: `Requires level ${node.reqLevel}` })}
                </span>
              )}
              {node.kind === "active" && learned.has(node.id) && (
                <span className="muted" style={{ fontSize: 13 }}>
                  {tr({ ru: "Нажмите на слот вверху, чтобы назначить", en: "Tap a slot above to assign" })}
                </span>
              )}
              </div>
            </div>
            <div className="row">
              <span className="muted" style={{ fontSize: 13 }}>
                {tr(
                  node.kind === "active"
                    ? { ru: "Активный навык", en: "Active skill" }
                    : node.kind === "upgrade"
                      ? { ru: "Улучшение", en: "Upgrade" }
                      : node.kind === "keystone"
                        ? { ru: "Ключевой талант", en: "Keystone" }
                        : node.kind === "root"
                          ? { ru: "Корень", en: "Root" }
                          : { ru: "Пассивный навык", en: "Passive" },
                )}{" "}
                · {tr({ ru: "треб. ур.", en: "req. lv" })} {node.reqLevel}
              </span>
            </div>
            <ul>
              {describeNode(node).map((t, i) => (
                <li key={i}>{tr(t)}</li>
              ))}
            </ul>
          </div>
        ) : (
          <div className="skill-info muted" style={{ fontSize: 14 }}>
            {tr({
              ru: `Ветви ${cls.schools.map((x) => tr(x.name)).join(", ")}. Каждые 2–4 навыка ветка разделяется. ${infinite ? "Дерево бесконечно — изучайте, и появятся новые ветви." : `Всего узлов: ${tree.nodes.size}.`}`,
              en: `Schools: ${cls.schools.map((x) => tr(x.name)).join(", ")}. Every 2–4 nodes a branch splits. ${infinite ? "The tree is infinite — learn to reveal new branches." : `Total nodes: ${tree.nodes.size}.`}`,
            })}
          </div>
        )}
      </div>
    </Panel>
  );
});

function starPath(r: number): string {
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 === 0 ? r * 1.15 : r * 0.55;
    pts.push(`${Math.cos(a) * rr},${Math.sin(a) * rr}`);
  }
  return `M${pts.join("L")}Z`;
}
