/**
 * Ввод: клавиатура и мышь на компьютере, виртуальный стик и кнопки на телефоне.
 * Игра читает состояние каждый кадр; одноразовые действия копятся в очереди.
 */
export type InputAction =
  | "skill0"
  | "skill1"
  | "skill2"
  | "skill3"
  | "skill4"
  | "skill5"
  | "interact"
  | "inventory"
  | "skills"
  | "map"
  | "quests"
  | "character"
  | "menu"
  | "meow";

export interface AimedCast {
  slot: number;
  /** Смещение прицела от игрока в мире (для drag-aim на телефоне); null — автоприцел. */
  dx: number | null;
  dz: number | null;
}

const KEYMAP: Record<string, InputAction> = {
  Digit1: "skill0",
  Digit2: "skill1",
  Digit3: "skill2",
  Digit4: "skill3",
  Digit5: "skill4",
  Digit6: "skill5",
  KeyE: "interact",
  KeyF: "interact",
  KeyI: "inventory",
  KeyB: "inventory",
  KeyK: "skills",
  KeyT: "skills",
  KeyM: "map",
  KeyJ: "quests",
  KeyL: "quests",
  KeyC: "character",
  Escape: "menu",
  KeyV: "meow",
};

export class Input {
  keys = new Set<string>();
  joyX = 0;
  joyY = 0;
  mouseX = 0.5;
  mouseY = 0.5;
  mouseInside = false;
  lmb = false;
  rmb = false;
  mmb = false;
  camYawDelta = 0;
  camPitchDelta = 0;
  zoomDelta = 0;
  attackHeld = false;
  touchAttack = false;
  isTouch = false;
  /** Если открыт UI-панель — клавиши движения игнорируются. */
  blocked = false;
  private actions: InputAction[] = [];
  private casts: AimedCast[] = [];
  private el: HTMLElement | null = null;
  private lastMX = 0;
  private lastMY = 0;
  private cleanups: (() => void)[] = [];

  attach(el: HTMLElement) {
    this.detach();
    this.el = el;
    const on = <K extends keyof WindowEventMap>(t: EventTarget, type: K | string, fn: (e: never) => void, opts?: AddEventListenerOptions) => {
      t.addEventListener(type, fn as EventListener, opts);
      this.cleanups.push(() => t.removeEventListener(type, fn as EventListener, opts));
    };
    on(window, "keydown", (e: KeyboardEvent) => {
      if (isTextInput(e.target)) return;
      this.keys.add(e.code);
      const a = KEYMAP[e.code];
      if (a && !e.repeat) this.actions.push(a);
      if (e.code === "Space") this.attackHeld = true;
      if (e.code === "Tab") e.preventDefault();
    });
    on(window, "keyup", (e: KeyboardEvent) => {
      this.keys.delete(e.code);
      if (e.code === "Space") this.attackHeld = false;
    });
    on(window, "blur", () => {
      this.keys.clear();
      this.lmb = this.rmb = this.mmb = false;
      this.attackHeld = false;
    });
    on(el, "mousemove", (e: MouseEvent) => {
      const r = el.getBoundingClientRect();
      this.mouseX = (e.clientX - r.left) / r.width;
      this.mouseY = (e.clientY - r.top) / r.height;
      this.mouseInside = true;
      if (this.rmb || this.mmb) {
        this.camYawDelta -= (e.clientX - this.lastMX) * 0.006;
        this.camPitchDelta += (e.clientY - this.lastMY) * 0.004;
      }
      this.lastMX = e.clientX;
      this.lastMY = e.clientY;
    });
    on(el, "mouseleave", () => {
      this.mouseInside = false;
    });
    on(el, "mousedown", (e: MouseEvent) => {
      this.lastMX = e.clientX;
      this.lastMY = e.clientY;
      if (e.button === 0) this.lmb = true;
      if (e.button === 1) this.mmb = true;
      if (e.button === 2) this.rmb = true;
    });
    on(window, "mouseup", (e: MouseEvent) => {
      if (e.button === 0) this.lmb = false;
      if (e.button === 1) this.mmb = false;
      if (e.button === 2) this.rmb = false;
    });
    on(el, "contextmenu", (e: Event) => e.preventDefault());
    on(
      el,
      "wheel",
      (e: WheelEvent) => {
        e.preventDefault();
        this.zoomDelta += Math.sign(e.deltaY) * 1.5;
      },
      { passive: false },
    );
    on(window, "touchstart", () => {
      this.isTouch = true;
    }, { passive: true });
  }

  detach() {
    for (const c of this.cleanups) c();
    this.cleanups = [];
    this.el = null;
  }

  /** Вектор движения в экранных осях: x — вправо, y — вверх (от камеры). */
  moveVector(): { x: number; y: number } {
    if (this.blocked) return { x: 0, y: 0 };
    let x = this.joyX,
      y = this.joyY;
    const k = this.keys;
    if (k.has("KeyW") || k.has("ArrowUp")) y += 1;
    if (k.has("KeyS") || k.has("ArrowDown")) y -= 1;
    if (k.has("KeyD") || k.has("ArrowRight")) x += 1;
    if (k.has("KeyA") || k.has("ArrowLeft")) x -= 1;
    const l = Math.hypot(x, y);
    if (l > 1) {
      x /= l;
      y /= l;
    }
    return { x, y };
  }

  cameraKeys(dt: number) {
    if (this.keys.has("KeyQ")) this.camYawDelta += dt * 2;
    if (this.keys.has("KeyR")) this.camYawDelta -= dt * 2;
  }

  pushAction(a: InputAction) {
    this.actions.push(a);
  }

  castSkill(slot: number, dx: number | null = null, dz: number | null = null) {
    this.casts.push({ slot, dx, dz });
  }

  takeActions(): InputAction[] {
    const a = this.actions;
    this.actions = [];
    return a;
  }

  takeCasts(): AimedCast[] {
    const c = this.casts;
    this.casts = [];
    return c;
  }

  takeCamera(): { yaw: number; pitch: number; zoom: number } {
    const r = { yaw: this.camYawDelta, pitch: this.camPitchDelta, zoom: this.zoomDelta };
    this.camYawDelta = this.camPitchDelta = this.zoomDelta = 0;
    return r;
  }
}

function isTextInput(t: EventTarget | null): boolean {
  if (!t || !(t instanceof HTMLElement)) return false;
  return t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable;
}
