/**
 * Коты на деревьях — только картинка, в симуляции их нет. У некоторых деревьев рядом с игроком
 * живёт кот со своим расписанием: посидеть у ствола, залезть, подремать на кроне, слезть.
 * На когтеточках в городах коты перепрыгивают с площадки на площадку.
 * Расписание считается от мирового времени, поэтому поведение не зависит от частоты кадров.
 */
import { makeCatInstance, type CatInstance } from "../../engine/cat-types";
import { hash2, Rng, toUnit } from "../../core/rng";
import { villagerLook } from "../cats/look";
import { PROP_COLLIDER } from "../world/biomes";
import { CHUNK } from "../world/worldgen";
import type { TerrainCache } from "../world/terrain-cache";
import { anchorPoint, CLIMB_BUILDINGS, CLIMB_PROPS, climbPose, hopArc, pathLength, type ClimbAnchor } from "../sim/climb";

interface TreeCat {
  ci: CatInstance;
  a: ClimbAnchor;
  len: number;
  ang: number;
  period: number;
  offset: number;
  sleepy: boolean;
  seen: number;
}

/** Доля деревьев, на которых живёт кот. */
const TREE_SHARE = 0.08;
const MAX_CATS = 8;
const HOP = 0.45;

const unit = (x: number, z: number, seed: number) => toUnit(hash2(Math.round(x * 10), Math.round(z * 10), seed));

export class TreeCats {
  private cats = new Map<string, TreeCat>();
  private scanT = 0;
  private frame = 0;
  private list: TreeCat[] = [];
  private tmp = [0, 0, 0, 0];

  /** Найти деревья с котами вокруг (x, z). Раз в полсекунды — деревья не двигаются. */
  private scan(cache: TerrainCache, x: number, z: number) {
    const ccx = Math.floor(x / CHUNK),
      ccz = Math.floor(z / CHUNK);
    const found: TreeCat[] = [];
    for (let dz = -2; dz <= 2; dz++)
      for (let dx = -2; dx <= 2; dx++) {
        if (!cache.hasContent(ccx + dx, ccz + dz)) continue;
        const c = cache.content(ccx + dx, ccz + dz);
        for (const p of c.props) {
          const spec = CLIMB_PROPS[p.kind];
          if (!spec || unit(p.x, p.z, 71) > TREE_SHARE) continue;
          found.push(this.get(`t${Math.round(p.x * 10)}:${Math.round(p.z * 10)}`, { x: p.x, y: p.y, z: p.z, rot: p.rot, scale: p.scale, spec, building: false, col: (PROP_COLLIDER[p.kind] ?? 0.5) * p.scale, tint: p.tint }));
        }
        for (const b of c.buildings) {
          const spec = CLIMB_BUILDINGS[b.kind];
          if (!spec) continue;
          found.push(this.get(`b${Math.round(b.x * 10)}:${Math.round(b.z * 10)}`, { x: b.x, y: b.y, z: b.z, rot: b.rot, scale: b.scale, spec, building: true, col: b.collider * b.scale, tint: 0 }));
        }
      }
    found.sort((a, b) => Math.hypot(a.a.x - x, a.a.z - z) - Math.hypot(b.a.x - x, b.a.z - z));
    this.list = found.slice(0, MAX_CATS);
    for (const t of this.list) t.seen = this.frame;
    // Забываем давно не виденных
    if (this.cats.size > 64) for (const [k, t] of this.cats) if (this.frame - t.seen > 600) this.cats.delete(k);
  }

  private get(key: string, a: ClimbAnchor): TreeCat {
    let t = this.cats.get(key);
    if (!t) {
      const h = unit(a.x, a.z, 5);
      const look = villagerLook(new Rng(Math.floor(h * 1e9)));
      look.size *= 0.85 + h * 0.2;
      const ci = makeCatInstance(800000 + Math.floor(unit(a.x, a.z, 9) * 99999), look);
      t = {
        ci,
        a,
        len: pathLength(a),
        ang: unit(a.x, a.z, 13) * Math.PI * 2,
        period: 44 + unit(a.x, a.z, 17) * 26,
        offset: unit(a.x, a.z, 23) * 100,
        sleepy: unit(a.x, a.z, 29) > 0.55,
        seen: this.frame,
      };
      this.cats.set(key, t);
    }
    return t;
  }

  /** Обновить позы и сложить в out котов, которых надо нарисовать. */
  update(dt: number, time: number, cache: TerrainCache, x: number, z: number, out: TreeCat["ci"][]) {
    this.frame++;
    this.scanT -= dt;
    if (this.scanT <= 0) {
      this.scanT = 0.5;
      this.scan(cache, x, z);
    }
    for (const t of this.list) {
      if (t.a.building) this.poseTower(t, time);
      else this.poseTree(t, time);
      out.push(t.ci);
    }
  }

  private setPose(ci: CatInstance, x: number, y: number, z: number, yaw: number, state: CatInstance["state"], speed: number, dt = 0) {
    ci.x = x;
    ci.y = y;
    ci.z = z;
    ci.yaw = yaw;
    if (ci.state !== state) {
      ci.state = state;
      ci.stateT = 0;
    } else ci.stateT += dt;
    ci.speed = speed;
  }

  /** Дерево: сидит у ствола → лезет → прыгает на крону → дремлет → спускается → сидит. */
  private poseTree(t: TreeCat, time: number) {
    const a = t.a;
    const up = t.len / 1.5,
      down = t.len / 1.3,
      sit = 7,
      rest = 6;
    const perch = Math.max(8, t.period - sit - up - HOP - HOP - down - rest);
    let u = (time + t.offset) % t.period;
    const ci = t.ci;
    const top = climbPose(a, t.len, t.ang, this.tmp);
    const topP = [top[0], top[1], top[2]];
    const perchP = anchorPoint(a, a.spec.perch);
    const base = anchorPoint(a, a.spec.path[0]);
    const r = a.col + 0.45;
    const sitX = base[0] + Math.sin(t.ang) * r,
      sitZ = base[2] + Math.cos(t.ang) * r;
    if (u < sit) return this.setPose(ci, sitX, a.y, sitZ, t.ang, "sit", 0);
    u -= sit;
    if (u < up) {
      const p = climbPose(a, (u / up) * t.len, t.ang, this.tmp);
      return this.setPose(ci, p[0], p[1], p[2], p[3], "climb", t.len / up);
    }
    u -= up;
    if (u < HOP) return this.hop(ci, topP, perchP, u / HOP, "climb");
    u -= HOP;
    if (u < perch) {
      const yaw = t.ang + Math.sin(time * 0.3 + t.offset) * 0.6;
      return this.setPose(ci, perchP[0], perchP[1], perchP[2], yaw, t.sleepy && u > perch * 0.3 ? "sleep" : "perch", 0);
    }
    u -= perch;
    if (u < HOP) return this.hop(ci, perchP, topP, u / HOP, "climb");
    u -= HOP;
    if (u < down) {
      const p = climbPose(a, (1 - u / down) * t.len, t.ang, this.tmp);
      return this.setPose(ci, p[0], p[1], p[2], p[3], "climb", t.len / down);
    }
    return this.setPose(ci, sitX, a.y, sitZ, t.ang + 0.4, "loaf", 0);
  }

  /** Когтеточка: площадка → площадка → домик наверху → обратно, с остановками. */
  private poseTower(t: TreeCat, time: number) {
    const a = t.a;
    const spots = [...a.spec.hops, a.spec.perch].map((p) => anchorPoint(a, p));
    const order = [0, 1, 2, 1];
    const stay = t.period / order.length - HOP;
    const cycle = t.period;
    let u = (time + t.offset) % cycle;
    const leg = Math.floor(u / (stay + HOP));
    u -= leg * (stay + HOP);
    const from = spots[order[leg % order.length]],
      to = spots[order[(leg + 1) % order.length]];
    const ci = t.ci;
    if (u < stay) {
      const yaw = t.ang + Math.sin(time * 0.25 + t.offset) * 0.8;
      return this.setPose(ci, from[0], from[1], from[2], yaw, t.sleepy && u > stay * 0.4 ? "sleep" : "loaf", 0);
    }
    this.hop(ci, from, to, (u - stay) / HOP, "alive");
  }

  private hop(ci: CatInstance, from: readonly number[], to: readonly number[], k: number, state: CatInstance["state"]) {
    const arc = hopArc(from, to);
    const x = from[0] + (to[0] - from[0]) * k,
      z = from[2] + (to[2] - from[2]) * k;
    const y = from[1] + (to[1] - from[1]) * k + Math.sin(k * Math.PI) * arc;
    const yaw = Math.hypot(to[0] - from[0], to[2] - from[2]) > 0.05 ? Math.atan2(to[0] - from[0], to[2] - from[2]) : ci.yaw;
    this.setPose(ci, x, y, z, yaw, state, 0);
  }
}
