/** Форматирование больших чисел для бесконечного режима: 1.2K, 3.4M, 5.6B, 7.8T, 1.2aa... */
const SUFFIXES = ["", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No", "Dc"];

function letterSuffix(i: number): string {
  // после Dc: aa, ab, ... zz, aaa ...
  let n = i - SUFFIXES.length;
  let s = "";
  do {
    s = String.fromCharCode(97 + (n % 26)) + s;
    n = Math.floor(n / 26) - 1;
  } while (n >= 0);
  return s.length === 1 ? "a" + s : s;
}

export function fmtNum(v: number, digits = 1): string {
  if (!isFinite(v)) return v > 0 ? "∞" : "-∞";
  const neg = v < 0;
  let a = Math.abs(v);
  if (a < 1000) {
    const s = a < 10 && a % 1 !== 0 ? a.toFixed(1).replace(/\.0$/, "") : Math.round(a).toString();
    return (neg ? "-" : "") + s;
  }
  let i = 0;
  while (a >= 1000) {
    a /= 1000;
    i++;
  }
  const suf = i < SUFFIXES.length ? SUFFIXES[i] : letterSuffix(i);
  const s = a >= 100 ? a.toFixed(0) : a.toFixed(digits).replace(/\.0+$/, "");
  return (neg ? "-" : "") + s + suf;
}

export function fmtPct(v: number, digits = 0): string {
  return `${(v * 100).toFixed(digits)}%`;
}

export function fmtTime(sec: number): string {
  sec = Math.max(0, Math.floor(sec));
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = sec % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function fmtCooldown(sec: number): string {
  if (sec >= 60) return `${Math.ceil(sec / 60)}m`;
  if (sec >= 10) return `${Math.ceil(sec)}`;
  return sec.toFixed(1);
}
