/**
 * Орбитальная камера третьего лица.
 * Все GPU-координаты считаются относительно «точки отсчёта» (render origin), которая
 * перескакивает сеткой по 256 ед. — это убирает дрожание float32 в бесконечном мире.
 */
import { clamp } from "../core/math";
import { invert, lookAt, mat4, multiply, perspective, type Mat4 } from "../core/mat4";

const ORIGIN_SNAP = 256;

export class Camera {
  // Цель (мировые координаты, double)
  tx = 0;
  ty = 0;
  tz = 0;
  yaw = 0;
  pitch = 0.85;
  distance = 14;
  fov = (52 * Math.PI) / 180;
  near = 0.3;
  far = 900;
  aspect = 1;

  // Точка отсчёта
  ox = 0;
  oz = 0;

  // Позиция камеры (мировая)
  ex = 0;
  ey = 0;
  ez = 0;

  readonly view: Mat4 = mat4();
  readonly proj: Mat4 = mat4();
  readonly viewProj: Mat4 = mat4();
  readonly invViewProj: Mat4 = mat4();
  private planes = new Float32Array(24);
  originChanged = false;

  update(aspect: number, groundAt?: (x: number, z: number) => number) {
    this.aspect = aspect;
    this.originChanged = false;
    if (Math.abs(this.tx - this.ox) > ORIGIN_SNAP * 0.75 || Math.abs(this.tz - this.oz) > ORIGIN_SNAP * 0.75) {
      this.ox = Math.round(this.tx / ORIGIN_SNAP) * ORIGIN_SNAP;
      this.oz = Math.round(this.tz / ORIGIN_SNAP) * ORIGIN_SNAP;
      this.originChanged = true;
    }
    const cp = Math.cos(this.pitch);
    this.ex = this.tx + Math.sin(this.yaw) * cp * this.distance;
    this.ey = this.ty + Math.sin(this.pitch) * this.distance;
    this.ez = this.tz + Math.cos(this.yaw) * cp * this.distance;
    if (groundAt) {
      const g = groundAt(this.ex, this.ez) + 1.2;
      if (this.ey < g) this.ey = g;
    }
    lookAt(this.view, this.ex - this.ox, this.ey, this.ez - this.oz, this.tx - this.ox, this.ty, this.tz - this.oz);
    perspective(this.proj, this.fov, aspect, this.near, this.far);
    multiply(this.viewProj, this.proj, this.view);
    invert(this.invViewProj, this.viewProj);
    this.extractPlanes();
  }

  /** Направление «вперёд» камеры на плоскости XZ (куда смотрит). */
  forwardXZ(): [number, number] {
    return [-Math.sin(this.yaw), -Math.cos(this.yaw)];
  }

  private extractPlanes() {
    const m = this.viewProj;
    const p = this.planes;
    const set = (i: number, a: number, b: number, c: number, d: number) => {
      const l = Math.hypot(a, b, c) || 1;
      p[i * 4] = a / l;
      p[i * 4 + 1] = b / l;
      p[i * 4 + 2] = c / l;
      p[i * 4 + 3] = d / l;
    };
    set(0, m[3] + m[0], m[7] + m[4], m[11] + m[8], m[15] + m[12]);
    set(1, m[3] - m[0], m[7] - m[4], m[11] - m[8], m[15] - m[12]);
    set(2, m[3] + m[1], m[7] + m[5], m[11] + m[9], m[15] + m[13]);
    set(3, m[3] - m[1], m[7] - m[5], m[11] - m[9], m[15] - m[13]);
    set(4, m[3] + m[2], m[7] + m[6], m[11] + m[10], m[15] + m[14]);
    set(5, m[3] - m[2], m[7] - m[6], m[11] - m[10], m[15] - m[14]);
  }

  /** Видимость AABB (в координатах относительно origin). */
  boxVisible(minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number): boolean {
    const p = this.planes;
    for (let i = 0; i < 6; i++) {
      const a = p[i * 4],
        b = p[i * 4 + 1],
        c = p[i * 4 + 2],
        d = p[i * 4 + 3];
      const x = a > 0 ? maxX : minX;
      const y = b > 0 ? maxY : minY;
      const z = c > 0 ? maxZ : minZ;
      if (a * x + b * y + c * z + d < 0) return false;
    }
    return true;
  }

  /** Видимость сферы в мировых координатах. */
  sphereVisible(x: number, y: number, z: number, r: number): boolean {
    x -= this.ox;
    z -= this.oz;
    const p = this.planes;
    for (let i = 0; i < 6; i++) {
      if (p[i * 4] * x + p[i * 4 + 1] * y + p[i * 4 + 2] * z + p[i * 4 + 3] < -r) return false;
    }
    return true;
  }

  /** Мировая точка → экранные координаты [0..1]. */
  project(x: number, y: number, z: number, out: { x: number; y: number; visible: boolean; depth: number }) {
    const m = this.viewProj;
    x -= this.ox;
    z -= this.oz;
    const cx = m[0] * x + m[4] * y + m[8] * z + m[12];
    const cy = m[1] * x + m[5] * y + m[9] * z + m[13];
    const cw = m[3] * x + m[7] * y + m[11] * z + m[15];
    if (cw <= 0.01) {
      out.visible = false;
      return out;
    }
    out.x = (cx / cw) * 0.5 + 0.5;
    out.y = 1 - ((cy / cw) * 0.5 + 0.5);
    out.depth = cw;
    out.visible = out.x > -0.1 && out.x < 1.1 && out.y > -0.1 && out.y < 1.1;
    return out;
  }

  /** Луч из экранной точки (0..1) в мировых координатах. */
  ray(sx: number, sy: number): { ox: number; oy: number; oz: number; dx: number; dy: number; dz: number } {
    const nx = sx * 2 - 1;
    const ny = 1 - sy * 2;
    const m = this.invViewProj;
    const tr = (x: number, y: number, z: number) => {
      const w = m[3] * x + m[7] * y + m[11] * z + m[15];
      return [(m[0] * x + m[4] * y + m[8] * z + m[12]) / w, (m[1] * x + m[5] * y + m[9] * z + m[13]) / w, (m[2] * x + m[6] * y + m[10] * z + m[14]) / w];
    };
    const a = tr(nx, ny, -1);
    const b = tr(nx, ny, 1);
    let dx = b[0] - a[0],
      dy = b[1] - a[1],
      dz = b[2] - a[2];
    const l = Math.hypot(dx, dy, dz) || 1;
    dx /= l;
    dy /= l;
    dz /= l;
    return { ox: a[0] + this.ox, oy: a[1], oz: a[2] + this.oz, dx, dy, dz };
  }

  /** Пересечение луча с рельефом (маршинг + уточнение). */
  pickGround(sx: number, sy: number, heightAt: (x: number, z: number) => number): { x: number; z: number; y: number } | null {
    const r = this.ray(sx, sy);
    let t = 0;
    let prevT = 0;
    const step = 0.8;
    for (let i = 0; i < 400; i++) {
      const x = r.ox + r.dx * t,
        y = r.oy + r.dy * t,
        z = r.oz + r.dz * t;
      const h = heightAt(x, z);
      if (y <= h) {
        // бинарный поиск
        let lo = prevT,
          hi = t;
        for (let k = 0; k < 8; k++) {
          const mid = (lo + hi) / 2;
          const mx = r.ox + r.dx * mid,
            my = r.oy + r.dy * mid,
            mz = r.oz + r.dz * mid;
          if (my <= heightAt(mx, mz)) hi = mid;
          else lo = mid;
        }
        const x2 = r.ox + r.dx * hi,
          z2 = r.oz + r.dz * hi;
        return { x: x2, z: z2, y: heightAt(x2, z2) };
      }
      prevT = t;
      t += step * (1 + t * 0.02);
      if (t > this.far) break;
    }
    return null;
  }

  clampPitch(min = 0.25, max = 1.45) {
    this.pitch = clamp(this.pitch, min, max);
  }
}
