/** Исполнение навыков: каждая «доставка» реализована здесь. Работает и для игроков, и для врагов. */
import { distToSegment } from "../../core/math";
import type { Element } from "../types";
import { ELEMENTS } from "../types";
import { ELEMENT_INFO } from "../skills/palette";
import type { OnHit, SkillDef, SkillVisual } from "../skills/types";
import { addStatus, dealDamage, healEntity, isHostile, makeSource } from "./combat";
import type { Area, AreaKind, DamageSource, Entity, Projectile } from "./types";
import type { GameWorld } from "./world";

const NO_CHAIN = (hits: OnHit[]) => hits.filter((h) => h.k !== "explode" && h.k !== "split" && h.k !== "chain");

export class SkillRuntime {
  constructor(private w: GameWorld) {}

  private hostilesIn(x: number, z: number, r: number, faction: number, out: Entity[] = []): Entity[] {
    out.length = 0;
    for (const e of this.w.entities.values()) {
      if (!e.alive || e.faction === faction || e.faction === 2) continue;
      const rr = r + e.radius;
      const dx = e.x - x,
        dz = e.z - z;
      if (dx * dx + dz * dz <= rr * rr) out.push(e);
    }
    return out;
  }

  private alliesIn(x: number, z: number, r: number, faction: number): Entity[] {
    const out: Entity[] = [];
    for (const e of this.w.entities.values()) {
      if (!e.alive || e.faction !== faction || e.kind === "npc") continue;
      if ((e.x - x) ** 2 + (e.z - z) ** 2 <= r * r) out.push(e);
    }
    return out;
  }

  private nearestHostile(x: number, z: number, r: number, faction: number, exclude?: Set<number>): Entity | null {
    let best: Entity | null = null;
    let bd = r * r;
    for (const e of this.w.entities.values()) {
      if (!e.alive || e.faction === faction || e.faction === 2) continue;
      if (exclude && exclude.has(e.id)) continue;
      const d = (e.x - x) ** 2 + (e.z - z) ** 2;
      if (d < bd) {
        bd = d;
        best = e;
      }
    }
    return best;
  }

  private fx(k: Parameters<GameWorld["fx"]>[0]["k"], x: number, y: number, z: number, extra: Partial<Parameters<GameWorld["fx"]>[0]> = {}) {
    this.w.fx({ k, x, y, z, ...extra });
  }

  /** Главная точка входа: выполнить навык. */
  execute(caster: Entity, skillIn: SkillDef, aimX: number, aimZ: number, targetId: number, coefMul = 1, isEcho = false) {
    const w = this.w;
    let skill = skillIn;
    const st = caster.stats;
    // Стихийный хаос
    if (st?.keystones.has("chaos") && !skill.basic) {
      const el = w.rng.pick(ELEMENTS.filter((e) => e !== "physical"));
      skill = { ...skill, element: el, visual: { ...skill.visual, color: ELEMENT_INFO[el].color, color2: ELEMENT_INFO[el].color2, shape: ELEMENT_INFO[el].shapes[0] } };
    }
    const src = makeSource(w, caster, skill);
    const p = skill.params;
    let dx = aimX - caster.x,
      dz = aimZ - caster.z;
    let dl = Math.hypot(dx, dz);
    if (dl < 0.01) {
      dx = Math.sin(caster.yaw);
      dz = Math.cos(caster.yaw);
      dl = 1;
    } else {
      dx /= dl;
      dz /= dl;
    }
    const yaw = Math.atan2(dx, dz);
    caster.yaw = yaw;
    const area = 1 + (st?.areaPct ?? 0);
    const durM = 1 + (st?.durationPct ?? 0);
    const coef = p.power * coefMul;
    const v = skill.visual;
    const y0 = caster.y + 0.8 * caster.look.size;
    const clampAim = (range: number) => {
      const d = Math.min(dl, range);
      return [caster.x + dx * d, caster.z + dz * d] as const;
    };
    w.emit({ t: "sound", s: `cast_${skill.delivery}`, x: caster.x, z: caster.z, pitch: skill.basic ? 1.1 : 1 });
    switch (skill.delivery) {
      case "strike": {
        const r = p.radius * (skill.basic ? 1 : Math.sqrt(area));
        const half = p.spread / 2;
        const full = p.spread >= Math.PI * 1.9;
        for (const e of this.hostilesIn(caster.x, caster.z, r, caster.faction)) {
          if (!full) {
            const a = Math.atan2(e.x - caster.x, e.z - caster.z);
            let d = Math.abs(((a - yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
            if (d > half + 0.25) continue;
          }
          dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: caster.x, fromZ: caster.z });
        }
        this.fx("slash", caster.x + dx * r * 0.45, y0, caster.z + dz * r * 0.45, { yaw, radius: r, spread: p.spread, v });
        break;
      }
      case "projectile":
      case "boomerang": {
        const n = Math.max(1, Math.round(p.count));
        const spread = n > 1 ? p.spread : 0;
        for (let i = 0; i < n; i++) {
          const a = yaw + (n > 1 ? -spread / 2 + (spread * i) / (n - 1) : 0);
          this.spawnProjectile(src, skill, caster.x + Math.sin(a) * 0.6, y0, caster.z + Math.cos(a) * 0.6, a, coef, caster.id, {
            returning: skill.returning || skill.delivery === "boomerang",
            pierce: skill.delivery === "boomerang" ? 99 : p.pierce,
          });
        }
        break;
      }
      case "nova": {
        const r = p.radius * area;
        for (const e of this.hostilesIn(caster.x, caster.z, r, caster.faction)) dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: caster.x, fromZ: caster.z });
        this.fx("nova", caster.x, caster.y + 0.3, caster.z, { radius: r, v });
        if (skill.ground) this.ground(src, skill, caster.x, caster.z, skill.ground.radius * area, skill.ground.dps, skill.ground.dur * durM);
        if (caster.enemy?.role === "bomber" && w.authority) {
          caster.hp = 0;
          w.kill(caster, caster.id);
        }
        break;
      }
      case "blast": {
        const [tx, tz] = clampAim(p.range);
        const r = p.radius * area;
        const delay = Math.max(0.35, p.duration || 0.6);
        const pts: [number, number][] = [[tx, tz]];
        for (let i = 1; i < Math.max(1, Math.round(p.count)); i++) {
          const a = w.rng.next() * Math.PI * 2;
          const d = r * (1.2 + w.rng.next() * 1.6);
          pts.push([tx + Math.cos(a) * d, tz + Math.sin(a) * d]);
        }
        for (const [bx, bz] of pts) {
          const by = w.groundAt(bx, bz);
          this.fx("telegraph", bx, by, bz, { radius: r, dur: delay, color: v.color });
          w.after(delay, () => {
            for (const e of this.hostilesIn(bx, bz, r, src.faction)) dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: bx, fromZ: bz });
            this.fx("burst", bx, by + 0.2, bz, { radius: r, v });
            w.emit({ t: "sound", s: "boom", x: bx, z: bz, vol: 0.8 });
            if (skill.ground) this.ground(src, skill, bx, bz, skill.ground.radius * area, skill.ground.dps, skill.ground.dur * durM);
          });
        }
        break;
      }
      case "cone": {
        const r = p.radius * Math.sqrt(area);
        const half = p.spread / 2;
        for (const e of this.hostilesIn(caster.x, caster.z, r, caster.faction)) {
          const a = Math.atan2(e.x - caster.x, e.z - caster.z);
          const d = Math.abs(((a - yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI);
          if (d > half + 0.15) continue;
          dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: caster.x, fromZ: caster.z });
        }
        this.fx("cone", caster.x, y0, caster.z, { yaw, radius: r, spread: p.spread, v });
        break;
      }
      case "beam": {
        const a = this.area("beam", src, skill, caster.x, caster.z, 0.6, p.duration * durM, p.tick, caster.id, coef);
        a.follow = true;
        a.angle = yaw;
        a.length = p.radius;
        caster.cast = { skill, t: p.duration * durM, total: p.duration * durM, aimX, aimZ, targetId, released: true };
        break;
      }
      case "chain": {
        let first = targetId >= 0 ? w.entities.get(targetId) ?? null : null;
        if (!first || !first.alive || !isHostile(first, caster) || (first.x - caster.x) ** 2 + (first.z - caster.z) ** 2 > p.range * p.range) {
          first = this.nearestHostile(aimX, aimZ, 6, caster.faction) ?? this.nearestHostile(caster.x, caster.z, p.range, caster.faction);
        }
        if (!first) {
          this.fx("chain", caster.x, y0, caster.z, { pts: [caster.x, y0, caster.z, caster.x + dx * p.range * 0.6, y0, caster.z + dz * p.range * 0.6], v });
          break;
        }
        const pts = [caster.x, y0, caster.z];
        const hit = new Set<number>();
        let cur: Entity | null = first;
        let c = coef;
        for (let i = 0; i <= Math.round(p.count) && cur; i++) {
          hit.add(cur.id);
          pts.push(cur.x, cur.y + 0.8 * cur.look.size, cur.z);
          dealDamage(w, src, cur, c, skill.element);
          c *= 0.88;
          cur = this.nearestHostile(cur.x, cur.z, p.radius, caster.faction, hit);
        }
        this.fx("chain", caster.x, y0, caster.z, { pts, v });
        break;
      }
      case "dash": {
        const [tx, tz] = w.clampMove(caster.x, caster.z, ...clampAim(p.range));
        const x0 = caster.x,
          z0 = caster.z;
        const r = p.radius;
        caster.invuln = Math.max(caster.invuln, 0.3);
        w.startMotion(caster, tx, tz, 0.22, 0, () => {
          for (const e of this.hostilesIn((x0 + tx) / 2, (z0 + tz) / 2, Math.hypot(tx - x0, tz - z0) / 2 + r, caster.faction)) {
            if (distToSegment(e.x, e.z, x0, z0, tx, tz) <= r + e.radius) dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: x0, fromZ: z0 });
          }
          if (skill.ground) for (let i = 0; i < 3; i++) this.ground(src, skill, x0 + ((tx - x0) * (i + 0.5)) / 3, z0 + ((tz - z0) * (i + 0.5)) / 3, skill.ground.radius, skill.ground.dps, skill.ground.dur * durM);
        });
        this.fx("dust", x0, caster.y, z0, { radius: 1.2, v });
        this.fx("trail", x0, y0, z0, { pts: [x0, y0, z0, tx, y0, tz], v });
        break;
      }
      case "leap": {
        const [tx, tz] = w.clampMove(caster.x, caster.z, ...clampAim(p.range));
        caster.invuln = Math.max(caster.invuln, 0.5);
        const r = p.radius * area;
        w.startMotion(caster, tx, tz, 0.45, 2.2, () => {
          for (const e of this.hostilesIn(tx, tz, r, caster.faction)) dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: tx, fromZ: tz });
          const gy = w.groundAt(tx, tz);
          this.fx("burst", tx, gy + 0.2, tz, { radius: r, v });
          this.fx("dust", tx, gy, tz, { radius: r });
          w.emit({ t: "sound", s: "land", x: tx, z: tz });
          if (skill.ground) this.ground(src, skill, tx, tz, skill.ground.radius * area, skill.ground.dps, skill.ground.dur * durM);
        });
        break;
      }
      case "summon": {
        let n = Math.max(1, Math.round(p.count));
        if (st?.keystones.has("packLeader")) n += 1;
        w.summon(caster, skill, n, p.duration * durM, coef);
        this.fx("summon", caster.x, caster.y, caster.z, { radius: 2, v });
        break;
      }
      case "aura": {
        const a = this.area("aura", src, skill, caster.x, caster.z, p.radius * area, p.duration * durM, p.tick, caster.id, coef);
        a.follow = true;
        a.heal = skill.element === "holy" || skill.element === "nature";
        break;
      }
      case "buff": {
        for (const al of this.alliesIn(caster.x, caster.z, p.radius, caster.faction)) {
          for (const b of skill.buff ?? []) addStatus(al, { kind: "buff", stat: b.stat, t: p.duration * durM, dur: p.duration * durM, value: b.pct, key: `buff:${skill.id}:${b.stat}` });
          this.fx("buff", al.x, al.y, al.z, { v });
        }
        break;
      }
      case "heal": {
        const amount = src.power * coef * (1 + (st?.healPct ?? 0));
        const allies = this.alliesIn(caster.x, caster.z, p.radius * area, caster.faction);
        for (const al of allies) {
          healEntity(w, al, al === caster || al.kind === "player" ? amount : amount * 0.6, false, caster);
          this.fx("heal", al.x, al.y, al.z, { v });
        }
        if (p.duration > 0)
          for (const al of allies) addStatus(al, { kind: "regen", t: p.duration * durM, dur: p.duration * durM, value: (amount * 0.3) / Math.max(1, p.duration), key: `regen:${skill.id}` });
        break;
      }
      case "barrier": {
        const amount = src.power * coef * 3 * (1 + (st?.healPct ?? 0) * 0.5);
        for (const al of this.alliesIn(caster.x, caster.z, p.radius || 0.1, caster.faction)) {
          const amt = al === caster ? amount : amount * 0.5;
          al.shield = Math.max(al.shield, amt);
          al.shieldT = Math.max(al.shieldT, p.duration * durM);
          this.fx("shield", al.x, al.y, al.z, { v, radius: al.look.size });
        }
        if (skill.onHit.length) {
          for (const e of this.hostilesIn(caster.x, caster.z, 3, caster.faction)) dealDamage(w, src, e, coef * 0.3, skill.element);
        }
        break;
      }
      case "trap": {
        const [tx, tz] = clampAim(p.range);
        let n = Math.max(1, Math.round(p.count));
        let c = coef;
        if (st?.keystones.has("trapMaster")) {
          n += 2;
          c *= 1.3;
        }
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2;
          const d = n > 1 ? 1.6 + n * 0.2 : 0;
          const t = this.area("trap", src, skill, tx + Math.cos(a) * d, tz + Math.sin(a) * d, p.radius * area, p.duration * durM, 0.1, caster.id, c);
          t.armed = 0.6;
        }
        break;
      }
      case "totem": {
        const [tx, tz] = clampAim(Math.min(p.range, 6));
        let n = Math.max(1, Math.round(p.count));
        let c = coef;
        if (st?.keystones.has("trapMaster")) {
          n += 2;
          c *= 1.3;
        }
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2;
          const d = n > 1 ? 2 : 0;
          const t = this.area("totem", src, skill, tx + Math.cos(a) * d, tz + Math.sin(a) * d, p.range, p.duration * durM, p.tick, caster.id, c);
          t.heal = skill.element === "holy" || skill.element === "nature";
        }
        this.fx("summon", tx, w.groundAt(tx, tz), tz, { radius: 1.2, v });
        break;
      }
      case "orbit": {
        const a = this.area("orbit", src, skill, caster.x, caster.z, p.radius * Math.sqrt(area), p.duration * durM, 0.5, caster.id, coef);
        a.follow = true;
        a.count = Math.max(1, Math.round(p.count));
        a.hitCd = new Map();
        break;
      }
      case "rain": {
        const [tx, tz] = clampAim(p.range);
        const a = this.area("rain", src, skill, tx, tz, p.radius * area, p.duration * durM, (p.duration * durM) / Math.max(1, p.count), caster.id, coef);
        a.count = Math.round(p.count);
        break;
      }
      case "wall": {
        const [tx, tz] = clampAim(p.range);
        const a = this.area("wall", src, skill, tx, tz, 1.1, p.duration * durM, p.tick, caster.id, coef);
        a.angle = yaw + Math.PI / 2;
        a.length = p.radius * area;
        break;
      }
      case "blink": {
        const [tx0, tz0] = clampAim(p.range);
        const [tx, tz] = w.clampMove(caster.x, caster.z, tx0, tz0);
        this.fx("blink", caster.x, caster.y, caster.z, { v });
        caster.x = tx;
        caster.z = tz;
        caster.y = w.groundAt(tx, tz);
        caster.invuln = Math.max(caster.invuln, 0.35);
        this.fx("blink", tx, caster.y, tz, { v });
        if (p.power > 0) {
          for (const e of this.hostilesIn(tx, tz, p.radius * area, caster.faction)) dealDamage(w, src, e, coef, skill.element);
          this.fx("burst", tx, caster.y + 0.3, tz, { radius: p.radius * area, v });
        }
        break;
      }
      case "eruption": {
        const n = Math.max(1, Math.round(p.count));
        const step = 1.5 + p.radius * 0.35;
        for (let i = 0; i < n; i++) {
          const ex = caster.x + dx * (1.4 + i * step);
          const ez = caster.z + dz * (1.4 + i * step);
          w.after(0.06 + i * 0.075, () => {
            if (w.blocked(ex, ez)) return;
            const gy = w.groundAt(ex, ez);
            for (const e of this.hostilesIn(ex, ez, p.radius * Math.sqrt(area), src.faction)) dealDamage(w, src, e, coef, skill.element, { knock: p.knock, fromX: ex - dx, fromZ: ez - dz });
            this.fx("burst", ex, gy + 0.1, ez, { radius: p.radius, v });
            if (skill.ground && i === n - 1) this.ground(src, skill, ex, ez, skill.ground.radius, skill.ground.dps, skill.ground.dur * durM);
          });
        }
        w.emit({ t: "sound", s: "rumble", x: caster.x, z: caster.z });
        break;
      }
      case "vortex": {
        const [tx, tz] = clampAim(p.range);
        this.area("vortex", src, skill, tx, tz, p.radius * area, p.duration * durM, p.tick, caster.id, coef);
        break;
      }
      case "mark": {
        const [tx, tz] = clampAim(p.range);
        const r = p.radius * area;
        for (const e of this.hostilesIn(tx, tz, r, caster.faction)) {
          addStatus(e, { kind: "mark", t: p.duration * durM, dur: p.duration * durM, value: 0.15 + p.power * 0.5, key: "mark" });
          dealDamage(w, src, e, coef * 0.5, skill.element);
        }
        this.fx("telegraph", tx, w.groundAt(tx, tz), tz, { radius: r, dur: 0.6, color: v.color });
        this.fx("burst", tx, w.groundAt(tx, tz) + 0.2, tz, { radius: r * 0.7, v });
        break;
      }
    }
    // Эхо навыка и «Эхо лап»
    if (!isEcho) {
      if (skill.echo) {
        const e = skill.echo;
        w.after(e.delay, () => {
          if (caster.alive) this.execute(caster, skill, aimX, aimZ, targetId, coefMul * e.pct, true);
        });
      }
      if (st?.keystones.has("pawEcho") && !skill.basic && w.rng.chance(0.2) && skill.delivery !== "summon" && skill.delivery !== "dash" && skill.delivery !== "leap" && skill.delivery !== "blink") {
        w.after(0.3, () => {
          if (caster.alive) this.execute(caster, skill, aimX, aimZ, targetId, coefMul, true);
        });
      }
    }
  }

  spawnProjectile(src: DamageSource, skill: SkillDef, x: number, y: number, z: number, yaw: number, coef: number, ownerId: number, o: { returning?: boolean; pierce?: number; range?: number; split?: boolean; speed?: number } = {}): Projectile {
    const p = skill.params;
    const speed = o.speed ?? p.speed;
    const pr: Projectile = {
      id: this.w.nextId++,
      src,
      skill,
      x,
      y,
      z,
      vx: Math.sin(yaw) * speed,
      vz: Math.cos(yaw) * speed,
      speed,
      dist: 0,
      range: o.range ?? p.range,
      pierce: o.pierce ?? p.pierce,
      bounce: p.bounce,
      hit: new Set(),
      homing: skill.homing,
      returning: !!o.returning,
      back: false,
      radius: 0.45 * skill.visual.size,
      coef,
      ownerId,
      visual: skill.visual,
      dead: false,
      split: !!o.split,
      age: 0,
    };
    this.w.projectiles.push(pr);
    return pr;
  }

  private area(kind: AreaKind, src: DamageSource, skill: SkillDef, x: number, z: number, radius: number, dur: number, tick: number, ownerId: number, coef: number): Area {
    const a: Area = {
      id: this.w.nextId++,
      kind,
      src,
      skill,
      x,
      y: this.w.groundAt(x, z),
      z,
      radius,
      t: dur,
      dur,
      tick: Math.max(0.05, tick),
      tickT: 0,
      ownerId,
      follow: false,
      angle: 0,
      length: 0,
      count: 0,
      coef,
      hitCd: null,
      armed: 0,
      heal: false,
      visual: skill.visual,
      dead: false,
      el: skill.element,
    };
    this.w.areas.push(a);
    return a;
  }

  ground(src: DamageSource, skill: SkillDef, x: number, z: number, radius: number, dps: number, dur: number) {
    const s2: DamageSource = { ...src, onHit: NO_CHAIN(src.onHit).filter((h) => h.k !== "knockback" && h.k !== "pull") };
    this.area("ground", s2, skill, x, z, radius, dur, 0.5, src.attackerId, dps * 0.5);
  }

  explosion(src: DamageSource, x: number, z: number, radius: number, coef: number, el: Element, excludeId: number) {
    const s2: DamageSource = { ...src, onHit: NO_CHAIN(src.onHit) };
    for (const e of this.hostilesIn(x, z, radius, src.faction)) {
      if (e.id === excludeId) continue;
      dealDamage(this.w, s2, e, coef, el, { fromX: x, fromZ: z });
    }
    const v: SkillVisual = src.skill?.visual ?? { color: ELEMENT_INFO[el].color, color2: ELEMENT_INFO[el].color2, shape: ELEMENT_INFO[el].shapes[0], size: 1, trail: false, glow: 1, style: 0 };
    this.fx("burst", x, this.w.groundAt(x, z) + 0.5, z, { radius, v });
    this.w.emit({ t: "sound", s: "boom", x, z, vol: 0.6 });
  }

  chainFrom(src: DamageSource, from: Entity, count: number, range: number, coef: number, el: Element) {
    const s2: DamageSource = { ...src, onHit: NO_CHAIN(src.onHit) };
    const hit = new Set<number>([from.id]);
    const pts = [from.x, from.y + 0.8, from.z];
    let cur: Entity | null = from;
    for (let i = 0; i < count && cur; i++) {
      const next: Entity | null = this.nearestHostile(cur.x, cur.z, range, src.faction, hit);
      if (!next) break;
      hit.add(next.id);
      pts.push(next.x, next.y + 0.8 * next.look.size, next.z);
      dealDamage(this.w, s2, next, coef, el);
      cur = next;
    }
    if (pts.length > 3) {
      const v: SkillVisual = { color: ELEMENT_INFO[el].color, color2: ELEMENT_INFO[el].color2, shape: "bolt", size: 0.8, trail: false, glow: 1, style: 0 };
      this.fx("chain", from.x, from.y, from.z, { pts, v });
    }
  }

  splitFrom(src: DamageSource, target: Entity, count: number) {
    if (!src.skill) return;
    const s2: DamageSource = { ...src, onHit: NO_CHAIN(src.onHit) };
    for (let i = 0; i < count; i++) {
      const a = this.w.rng.next() * Math.PI * 2;
      const pr = this.spawnProjectile(s2, src.skill, target.x, target.y + 0.8, target.z, a, (src.skill.params.power || 1) * 0.5, src.attackerId, { range: 8, pierce: 0, split: true });
      pr.hit.add(target.id);
      pr.visual = { ...pr.visual, size: pr.visual.size * 0.6 };
    }
  }

  // ─────────────────────── обновление снарядов и областей ───────────────────────

  updateProjectiles(dt: number) {
    const w = this.w;
    for (const pr of w.projectiles) {
      if (pr.dead) continue;
      pr.age += dt;
      if (pr.homing && !pr.back) {
        const t = this.nearestHostile(pr.x + pr.vx * 0.3, pr.z + pr.vz * 0.3, 11, pr.src.faction, pr.hit);
        if (t) {
          const want = Math.atan2(t.x - pr.x, t.z - pr.z);
          const cur = Math.atan2(pr.vx, pr.vz);
          let d = ((want - cur + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
          const turn = Math.max(-5 * dt, Math.min(5 * dt, d));
          const na = cur + turn;
          pr.vx = Math.sin(na) * pr.speed;
          pr.vz = Math.cos(na) * pr.speed;
        }
      }
      if (pr.back) {
        const o = w.entities.get(pr.ownerId);
        if (!o || !o.alive) {
          pr.dead = true;
          continue;
        }
        const dx = o.x - pr.x,
          dz = o.z - pr.z;
        const l = Math.hypot(dx, dz);
        if (l < 1) {
          pr.dead = true;
          continue;
        }
        pr.vx = (dx / l) * pr.speed;
        pr.vz = (dz / l) * pr.speed;
      }
      const step = pr.speed * dt;
      pr.x += pr.vx * dt;
      pr.z += pr.vz * dt;
      pr.dist += step;
      const gy = w.groundAt(pr.x, pr.z);
      pr.y += (gy + 0.9 - pr.y) * Math.min(1, dt * 6);
      if (w.blocked(pr.x, pr.z)) {
        this.impact(pr);
        continue;
      }
      // Попадания
      for (const e of w.entities.values()) {
        if (!e.alive || e.faction === pr.src.faction || e.faction === 2 || pr.hit.has(e.id)) continue;
        const rr = pr.radius + e.radius;
        const dx = e.x - pr.x,
          dz = e.z - pr.z;
        if (dx * dx + dz * dz > rr * rr) continue;
        pr.hit.add(e.id);
        dealDamage(w, pr.src, e, pr.coef, pr.skill.element, { knock: pr.skill.params.knock, fromX: pr.x - pr.vx * 0.1, fromZ: pr.z - pr.vz * 0.1 });
        this.fx("hitspark", pr.x, pr.y, pr.z, { v: pr.visual });
        if (pr.pierce > 0) {
          pr.pierce--;
          continue;
        }
        if (pr.bounce > 0) {
          pr.bounce--;
          const t = this.nearestHostile(pr.x, pr.z, 10, pr.src.faction, pr.hit);
          if (t) {
            const a = Math.atan2(t.x - pr.x, t.z - pr.z);
            pr.vx = Math.sin(a) * pr.speed;
            pr.vz = Math.cos(a) * pr.speed;
            pr.dist = Math.max(0, pr.dist - 6);
            continue;
          }
        }
        this.impact(pr);
        break;
      }
      if (pr.dead) continue;
      if (pr.dist >= pr.range) {
        if (pr.returning && !pr.back) {
          pr.back = true;
          pr.hit.clear();
        } else if (!pr.back) this.impact(pr);
        else pr.dead = true;
      }
      if (pr.age > 8) pr.dead = true;
    }
    w.projectiles = w.projectiles.filter((p) => !p.dead);
  }

  private impact(pr: Projectile) {
    pr.dead = true;
    this.fx("burst", pr.x, pr.y, pr.z, { radius: 0.9 * pr.visual.size, v: pr.visual });
    if (pr.skill.ground && !pr.split) {
      const durM = 1 + (this.w.entities.get(pr.ownerId)?.stats?.durationPct ?? 0);
      this.ground(pr.src, pr.skill, pr.x, pr.z, pr.skill.ground.radius, pr.skill.ground.dps, pr.skill.ground.dur * durM);
    }
  }

  updateAreas(dt: number) {
    const w = this.w;
    for (const a of w.areas) {
      if (a.dead) continue;
      a.t -= dt;
      if (a.t <= 0) {
        a.dead = true;
        continue;
      }
      const owner = w.entities.get(a.ownerId);
      if (a.follow) {
        if (!owner || !owner.alive) {
          a.dead = true;
          continue;
        }
        a.x = owner.x;
        a.z = owner.z;
        a.y = owner.y;
        if (a.kind === "beam") a.angle = owner.yaw;
      }
      a.tickT -= dt;
      switch (a.kind) {
        case "ground":
        case "aura":
        case "vortex":
          if (a.kind === "vortex") {
            for (const e of this.hostilesIn(a.x, a.z, a.radius, a.src.faction)) {
              if (e.enemy?.boss) continue;
              const dx = a.x - e.x,
                dz = a.z - e.z;
              const l = Math.hypot(dx, dz) || 1;
              e.vx += (dx / l) * 9 * dt;
              e.vz += (dz / l) * 9 * dt;
            }
          }
          if (a.tickT <= 0) {
            a.tickT += a.tick;
            for (const e of this.hostilesIn(a.x, a.z, a.radius, a.src.faction)) dealDamage(w, a.src, e, a.coef, a.el, { dot: a.kind === "ground", noOnHit: a.kind === "ground" && w.rng.next() > 0.3 });
            if (a.heal && owner) for (const al of this.alliesIn(a.x, a.z, a.radius, a.src.faction)) healEntity(w, al, a.src.power * a.coef * 0.6, true, owner);
          }
          break;
        case "beam": {
          if (!owner || !owner.cast) {
            a.dead = true;
            break;
          }
          if (a.tickT <= 0) {
            a.tickT += a.tick;
            const ex = a.x + Math.sin(a.angle) * a.length;
            const ez = a.z + Math.cos(a.angle) * a.length;
            for (const e of this.hostilesIn((a.x + ex) / 2, (a.z + ez) / 2, a.length / 2 + 1, a.src.faction)) {
              if (distToSegment(e.x, e.z, a.x, a.z, ex, ez) <= 0.9 + e.radius) dealDamage(w, a.src, e, a.coef, a.el, { noOnHit: w.rng.next() > 0.35 });
            }
          }
          break;
        }
        case "trap": {
          if (a.armed > 0) {
            a.armed -= dt;
            break;
          }
          const trig = this.hostilesIn(a.x, a.z, a.radius * 0.45, a.src.faction);
          if (trig.length) {
            for (const e of this.hostilesIn(a.x, a.z, a.radius, a.src.faction)) dealDamage(w, a.src, e, a.coef, a.el, { knock: 2, fromX: a.x, fromZ: a.z });
            this.fx("burst", a.x, a.y + 0.3, a.z, { radius: a.radius, v: a.visual });
            w.emit({ t: "sound", s: "trap", x: a.x, z: a.z });
            if (a.skill.ground) this.ground(a.src, a.skill, a.x, a.z, a.skill.ground.radius, a.skill.ground.dps, a.skill.ground.dur);
            a.dead = true;
          }
          break;
        }
        case "totem": {
          if (a.tickT <= 0) {
            a.tickT += a.tick;
            const t = this.nearestHostile(a.x, a.z, a.radius, a.src.faction);
            if (t) {
              const yaw = Math.atan2(t.x - a.x, t.z - a.z);
              this.spawnProjectile(a.src, a.skill, a.x, a.y + 1.6, a.z, yaw, a.coef, a.ownerId, { speed: 18, range: a.radius + 2, pierce: 0 });
            }
            if (a.heal && owner) for (const al of this.alliesIn(a.x, a.z, 6, a.src.faction)) healEntity(w, al, a.src.power * a.coef * 0.4, true, owner);
          }
          break;
        }
        case "orbit": {
          const n = a.count;
          const t = w.time * 3;
          for (let i = 0; i < n; i++) {
            const ang = t + (i / n) * Math.PI * 2;
            const ox = a.x + Math.sin(ang) * a.radius;
            const oz = a.z + Math.cos(ang) * a.radius;
            for (const e of this.hostilesIn(ox, oz, 0.75, a.src.faction)) {
              const cd = a.hitCd!.get(e.id) ?? 0;
              if (w.time < cd) continue;
              a.hitCd!.set(e.id, w.time + 0.5);
              dealDamage(w, a.src, e, a.coef, a.el, { knock: 1.5, fromX: a.x, fromZ: a.z });
              this.fx("hitspark", ox, a.y + 1, oz, { v: a.visual });
            }
          }
          break;
        }
        case "rain": {
          while (a.tickT <= 0 && a.count > 0) {
            a.tickT += a.tick;
            a.count--;
            const ang = w.rng.next() * Math.PI * 2;
            const d = Math.sqrt(w.rng.next()) * a.radius;
            const ix = a.x + Math.cos(ang) * d,
              iz = a.z + Math.sin(ang) * d;
            const gy = w.groundAt(ix, iz);
            w.after(0.35, () => {
              for (const e of this.hostilesIn(ix, iz, 1.6, a.src.faction)) dealDamage(w, a.src, e, a.coef, a.el, { noOnHit: w.rng.next() > 0.5 });
              this.fx("burst", ix, gy + 0.1, iz, { radius: 1.6, v: a.visual });
            });
            this.fx("telegraph", ix, gy, iz, { radius: 1.6, dur: 0.35, color: a.visual.color });
          }
          if (a.count <= 0) a.dead = true;
          break;
        }
        case "wall": {
          if (a.tickT <= 0) {
            a.tickT += a.tick;
            const hx = Math.sin(a.angle) * a.length * 0.5,
              hz = Math.cos(a.angle) * a.length * 0.5;
            for (const e of this.hostilesIn(a.x, a.z, a.length / 2 + 1.2, a.src.faction)) {
              if (distToSegment(e.x, e.z, a.x - hx, a.z - hz, a.x + hx, a.z + hz) <= 1.1 + e.radius) dealDamage(w, a.src, e, a.coef, a.el, { noOnHit: w.rng.next() > 0.4 });
            }
          }
          break;
        }
        case "mark":
          break;
      }
    }
    w.areas = w.areas.filter((a) => !a.dead);
  }
}
