/** Текстовые описания навыков, улучшений и пассивок (RU/EN). */
import type { Txt } from "../../core/i18n";
import { pluralRu } from "../../core/i18n";
import { ELEMENT_NAMES, DELIVERY_NAMES, STAT_NAMES, KEYSTONES } from "./vocab";
import type { OnHit, Passive, SkillDef, SkillMod, SkillNode } from "./types";

const pct = (v: number) => `${Math.round(v * 100)}%`;
const num = (v: number, d = 1) => (Math.abs(v - Math.round(v)) < 0.05 ? String(Math.round(v)) : v.toFixed(d));

function both(ru: string, en: string): Txt {
  return { ru, en };
}

export function describeHit(h: OnHit): Txt {
  switch (h.k) {
    case "dot":
      return both(`${ELEMENT_NAMES[h.el].ru}: ${pct(h.dps)} силы/с в течение ${num(h.dur)} с`, `${ELEMENT_NAMES[h.el].en}: ${pct(h.dps)} power/s for ${num(h.dur)}s`);
    case "slow":
      return both(`Замедляет на ${pct(h.pct)} (${num(h.dur)} с)`, `Slows by ${pct(h.pct)} (${num(h.dur)}s)`);
    case "stun":
      return both(`Оглушает на ${num(h.dur)} с`, `Stuns for ${num(h.dur)}s`);
    case "freeze":
      return both(`Замораживает на ${num(h.dur)} с`, `Freezes for ${num(h.dur)}s`);
    case "knockback":
      return both(`Отбрасывает`, `Knocks back`);
    case "pull":
      return both(`Притягивает врагов`, `Pulls enemies in`);
    case "lifesteal":
      return both(`Возвращает ${pct(h.pct)} урона здоровьем`, `Heals for ${pct(h.pct)} of damage`);
    case "weaken":
      return both(`Цель наносит на ${pct(h.pct)} меньше урона`, `Target deals ${pct(h.pct)} less damage`);
    case "vulnerable":
      return both(`Цель получает на ${pct(h.pct)} больше урона`, `Target takes ${pct(h.pct)} more damage`);
    case "explode":
      return both(`Взрывается: ${pct(h.power)} силы в радиусе ${num(h.radius)} м`, `Explodes: ${pct(h.power)} power in ${num(h.radius)}m`);
    case "split":
      return both(`Раскалывается на ${h.count} ${pluralRu(h.count, "осколок", "осколка", "осколков")}`, `Splits into ${h.count} shards`);
    case "chain":
      return both(`Перескакивает ещё на ${h.count} ${pluralRu(h.count, "цель", "цели", "целей")}`, `Chains to ${h.count} more targets`);
    case "manaLeech":
      return both(`Похищает ${pct(h.pct)} урона маной`, `Leeches ${pct(h.pct)} of damage as mana`);
    case "execute":
      return both(`Добивает врагов с запасом здоровья ниже ${pct(h.pct)}`, `Executes enemies below ${pct(h.pct)} health`);
    case "fear":
      return both(`Пугает на ${num(h.dur)} с`, `Fears for ${num(h.dur)}s`);
    case "charm":
      return both(`Очаровывает: враг сражается за вас ${num(h.dur)} с`, `Charms: enemy fights for you ${num(h.dur)}s`);
    case "blind":
      return both(`Ослепляет: ${pct(h.pct)} промахов`, `Blinds: ${pct(h.pct)} miss chance`);
  }
}

export function describeSkill(s: SkillDef): Txt[] {
  const p = s.params;
  const el = ELEMENT_NAMES[s.element];
  const lines: Txt[] = [];
  const pw = pct(p.power);
  switch (s.delivery) {
    case "strike":
      lines.push(
        p.spread >= 6
          ? both(`Круговой удар: ${pw} силы всем врагам в радиусе ${num(p.radius)} м.`, `Spinning strike: ${pw} power to all enemies within ${num(p.radius)}m.`)
          : both(`Удар перед собой: ${pw} силы (досягаемость ${num(p.radius)} м).`, `Strike in front: ${pw} power (reach ${num(p.radius)}m).`),
      );
      break;
    case "projectile":
      lines.push(
        p.count > 1
          ? both(`Выпускает ${p.count} ${pluralRu(p.count, "снаряд", "снаряда", "снарядов")} по ${pw} силы.`, `Fires ${p.count} projectiles for ${pw} power each.`)
          : both(`Выпускает снаряд: ${pw} силы.`, `Fires a projectile: ${pw} power.`),
      );
      if (p.pierce > 0) lines.push(both(`Пронзает ${p.pierce >= 99 ? "всех" : p.pierce} ${p.pierce >= 99 ? "" : pluralRu(p.pierce, "врага", "врагов", "врагов")}.`.replace("  ", " "), `Pierces ${p.pierce >= 99 ? "all" : p.pierce} enemies.`));
      if (p.bounce > 0) lines.push(both(`Отскакивает ${p.bounce} раз.`, `Bounces ${p.bounce} times.`));
      break;
    case "nova":
      lines.push(both(`Волна вокруг вас: ${pw} силы в радиусе ${num(p.radius)} м.`, `Nova around you: ${pw} power within ${num(p.radius)}m.`));
      break;
    case "blast":
      lines.push(both(`Удар по области через ${num(p.duration)} с: ${pw} силы в радиусе ${num(p.radius)} м.`, `Area strike after ${num(p.duration)}s: ${pw} power in ${num(p.radius)}m.`));
      break;
    case "cone":
      lines.push(both(`Конус перед собой (${num(p.radius)} м): ${pw} силы.`, `Cone in front (${num(p.radius)}m): ${pw} power.`));
      break;
    case "beam":
      lines.push(both(`Луч длиной ${num(p.radius)} м: ${pw} силы каждые ${num(p.tick, 2)} с, ${num(p.duration)} с.`, `Beam of ${num(p.radius)}m: ${pw} power every ${num(p.tick, 2)}s for ${num(p.duration)}s.`));
      break;
    case "chain":
      lines.push(both(`Цепь: ${pw} силы, перескакивает на ${p.count} ${pluralRu(p.count, "цель", "цели", "целей")}.`, `Chain: ${pw} power, jumps to ${p.count} targets.`));
      break;
    case "dash":
      lines.push(both(`Рывок на ${num(p.range)} м, ${pw} силы всем на пути.`, `Dash ${num(p.range)}m, ${pw} power to everything in the way.`));
      break;
    case "leap":
      lines.push(both(`Прыжок до ${num(p.range)} м, при приземлении ${pw} силы в радиусе ${num(p.radius)} м.`, `Leap up to ${num(p.range)}m, landing deals ${pw} power in ${num(p.radius)}m.`));
      break;
    case "summon":
      lines.push(both(`Призывает ${p.count} ${pluralRu(p.count, "союзника", "союзников", "союзников")} на ${num(p.duration)} с (урон ${pw} силы).`, `Summons ${p.count} allies for ${num(p.duration)}s (${pw} power damage).`));
      break;
    case "aura":
      lines.push(both(`Аура ${num(p.radius)} м на ${num(p.duration)} с: ${pw} силы каждые ${num(p.tick, 2)} с.`, `Aura of ${num(p.radius)}m for ${num(p.duration)}s: ${pw} power every ${num(p.tick, 2)}s.`));
      break;
    case "buff":
      lines.push(
        both(
          `На ${num(p.duration)} с: ${(s.buff ?? []).map((b) => `+${pct(b.pct)} ${STAT_NAMES[b.stat].name.ru.toLowerCase()}`).join(", ")} вам и союзникам рядом.`,
          `For ${num(p.duration)}s: ${(s.buff ?? []).map((b) => `+${pct(b.pct)} ${STAT_NAMES[b.stat].name.en.toLowerCase()}`).join(", ")} to you and nearby allies.`,
        ),
      );
      break;
    case "heal":
      lines.push(both(`Исцеляет вас и союзников в радиусе ${num(p.radius)} м на ${pw} силы.`, `Heals you and allies within ${num(p.radius)}m for ${pw} power.`));
      break;
    case "barrier":
      lines.push(both(`Щит, поглощающий ${pct(p.power * 3)} силы урона, на ${num(p.duration)} с.`, `Shield absorbing ${pct(p.power * 3)} power damage for ${num(p.duration)}s.`));
      break;
    case "trap":
      lines.push(both(`Ставит ${p.count > 1 ? p.count + " " : ""}${pluralRu(p.count, "ловушку", "ловушки", "ловушек")}: ${pw} силы в радиусе ${num(p.radius)} м.`, `Places ${p.count > 1 ? p.count + " " : "a "}trap${p.count > 1 ? "s" : ""}: ${pw} power in ${num(p.radius)}m.`));
      break;
    case "totem":
      lines.push(both(`Тотем на ${num(p.duration)} с атакует врагов: ${pw} силы.`, `A totem for ${num(p.duration)}s attacks enemies: ${pw} power.`));
      break;
    case "orbit":
      lines.push(both(`${p.count} ${pluralRu(p.count, "сфера кружит", "сферы кружат", "сфер кружат")} вокруг вас ${num(p.duration)} с: ${pw} силы при касании.`, `${p.count} orbs circle you for ${num(p.duration)}s: ${pw} power on touch.`));
      break;
    case "rain":
      lines.push(both(`${p.count} ударов в области ${num(p.radius)} м за ${num(p.duration)} с, по ${pw} силы.`, `${p.count} impacts over ${num(p.radius)}m in ${num(p.duration)}s, ${pw} power each.`));
      break;
    case "wall":
      lines.push(both(`Стена длиной ${num(p.radius)} м на ${num(p.duration)} с: ${pw} силы каждые ${num(p.tick, 2)} с.`, `A ${num(p.radius)}m wall for ${num(p.duration)}s: ${pw} power every ${num(p.tick, 2)}s.`));
      break;
    case "blink":
      lines.push(both(`Мгновенно переносит вас на ${num(p.range)} м${p.power > 0 ? `, ${pw} силы врагам рядом` : ""}.`, `Instantly teleports you ${num(p.range)}m${p.power > 0 ? `, ${pw} power to nearby enemies` : ""}.`));
      break;
    case "boomerang":
      lines.push(both(`Бумеранг летит на ${num(p.range)} м и возвращается: ${pw} силы.`, `Flies ${num(p.range)}m and returns: ${pw} power.`));
      break;
    case "eruption":
      lines.push(both(`${p.count} извержений вдоль линии, по ${pw} силы.`, `${p.count} eruptions along a line, ${pw} power each.`));
      break;
    case "vortex":
      lines.push(both(`Воронка ${num(p.radius)} м на ${num(p.duration)} с затягивает врагов: ${pw} силы.`, `A ${num(p.radius)}m vortex for ${num(p.duration)}s pulls enemies: ${pw} power.`));
      break;
    case "mark":
      lines.push(both(`Метит врагов в радиусе ${num(p.radius)} м на ${num(p.duration)} с.`, `Marks enemies within ${num(p.radius)}m for ${num(p.duration)}s.`));
      break;
  }
  for (const h of s.onHit) lines.push(describeHit(h));
  if (s.homing) lines.push(both("Самонаводится.", "Homing."));
  if (s.returning && s.delivery !== "boomerang") lines.push(both("Возвращается к вам.", "Returns to you."));
  if (s.echo) lines.push(both(`Эхо: повторяется через ${num(s.echo.delay)} с с силой ${pct(s.echo.pct)}.`, `Echo: repeats after ${num(s.echo.delay)}s at ${pct(s.echo.pct)} power.`));
  if (s.ground) lines.push(both(`Оставляет опасную землю: ${pct(s.ground.dps)} силы/с, ${num(s.ground.dur)} с.`, `Leaves hazardous ground: ${pct(s.ground.dps)} power/s, ${num(s.ground.dur)}s.`));
  if (p.crit > 0) lines.push(both(`+${pct(p.crit)} к шансу крита.`, `+${pct(p.crit)} crit chance.`));
  const meta: string[] = [];
  const metaEn: string[] = [];
  if (!s.basic) {
    meta.push(`${ELEMENT_NAMES[s.element].ru} · ${DELIVERY_NAMES[s.delivery].ru}`);
    metaEn.push(`${el.en} · ${DELIVERY_NAMES[s.delivery].en}`);
    meta.push(`Перезарядка ${num(p.cooldown)} с · Мана ${Math.round(p.cost)}`);
    metaEn.push(`Cooldown ${num(p.cooldown)}s · Mana ${Math.round(p.cost)}`);
  }
  if (meta.length) lines.push({ ru: meta.join(" · "), en: metaEn.join(" · ") });
  return lines;
}

export function describeMod(m: SkillMod): Txt {
  switch (m.m) {
    case "power":
      return both(`+${pct(m.pct)} к урону`, `+${pct(m.pct)} damage`);
    case "radius":
      return both(`+${pct(m.pct)} к радиусу`, `+${pct(m.pct)} radius`);
    case "count":
      return both(`+${m.add} к количеству`, `+${m.add} count`);
    case "pierce":
      return both(`+${m.add} к пронзанию`, `+${m.add} pierce`);
    case "bounce":
      return both(`+${m.add} к рикошетам`, `+${m.add} bounces`);
    case "cooldown":
      return both(`${pct(m.pct)} к перезарядке`, `${pct(m.pct)} cooldown`);
    case "cost":
      return both(`${pct(m.pct)} к стоимости`, `${pct(m.pct)} cost`);
    case "duration":
      return both(`+${pct(m.pct)} к длительности`, `+${pct(m.pct)} duration`);
    case "speed":
      return both(`+${pct(m.pct)} к скорости`, `+${pct(m.pct)} speed`);
    case "range":
      return both(`+${pct(m.pct)} к дальности`, `+${pct(m.pct)} range`);
    case "crit":
      return both(`+${pct(m.pct)} к шансу крита`, `+${pct(m.pct)} crit chance`);
    case "onHit":
      return describeHit(m.hit);
    case "homing":
      return both("Снаряды самонаводятся", "Projectiles home in");
    case "returning":
      return both("Снаряды возвращаются", "Projectiles return");
    case "echo":
      return both(`Эхо через ${num(m.delay)} с (${pct(m.pct)} силы)`, `Echo after ${num(m.delay)}s (${pct(m.pct)} power)`);
    case "element":
      return both(`Стихия меняется на: ${ELEMENT_NAMES[m.el].ru}`, `Element becomes ${ELEMENT_NAMES[m.el].en}`);
    case "ground":
      return both(`Оставляет опасную землю (${pct(m.dps)} силы/с, ${num(m.dur)} с)`, `Leaves hazardous ground (${pct(m.dps)} power/s, ${num(m.dur)}s)`);
    case "knock":
      return both("Сильнее отбрасывает", "Stronger knockback");
    case "spread":
      return both(`+${pct(m.pct)} к ширине веера`, `+${pct(m.pct)} spread`);
  }
}

export function describePassive(p: Passive): Txt {
  switch (p.p) {
    case "stat": {
      const n = STAT_NAMES[p.stat].name;
      if (p.pct !== undefined) return both(`+${pct(p.pct)} ${n.ru.toLowerCase()}`, `+${pct(p.pct)} ${n.en.toLowerCase()}`);
      const isPct = ["crit", "critDmg", "haste", "moveSpeed", "lifesteal", "dodge", "thorns", "summonPct", "healPct", "areaPct", "durationPct", "resist"].includes(p.stat);
      return both(`+${isPct ? pct(p.add ?? 0) : num(p.add ?? 0)} ${n.ru.toLowerCase()}`, `+${isPct ? pct(p.add ?? 0) : num(p.add ?? 0)} ${n.en.toLowerCase()}`);
    }
    case "element":
      return both(`+${pct(p.pct)} к урону: ${ELEMENT_NAMES[p.el].ru.toLowerCase()}`, `+${pct(p.pct)} ${ELEMENT_NAMES[p.el].en.toLowerCase()} damage`);
    case "delivery":
      return both(`+${pct(p.pct)} к урону навыков типа «${DELIVERY_NAMES[p.d].ru.toLowerCase()}»`, `+${pct(p.pct)} damage with ${DELIVERY_NAMES[p.d].en.toLowerCase()} skills`);
    case "onKill":
      switch (p.what) {
        case "heal":
          return both(`Убийство восстанавливает ${pct(p.amount)} здоровья`, `Kills restore ${pct(p.amount)} health`);
        case "mana":
          return both(`Убийство восстанавливает ${pct(p.amount)} маны`, `Kills restore ${pct(p.amount)} mana`);
        case "haste":
          return both(`Убийство ускоряет на ${pct(p.amount * 5)} на 3 с`, `Kills grant ${pct(p.amount * 5)} haste for 3s`);
        case "explode":
          return both(`Враги взрываются при гибели (${pct(p.amount)} силы)`, `Enemies explode on death (${pct(p.amount)} power)`);
      }
  }
}

export function describeNode(n: SkillNode): Txt[] {
  switch (n.kind) {
    case "active":
      return describeSkill(n.skill!);
    case "upgrade":
      return (n.mods ?? []).map(describeMod);
    case "passive":
    case "root":
      return (n.passives ?? []).map(describePassive);
    case "keystone": {
      const k = KEYSTONES[n.keystone!];
      return [k.desc, both("Повторное изучение даёт +10% ко всему урону.", "Learning it again grants +10% damage.")];
    }
  }
}
