/** Сообщения кооператива. Хост — авторитетная симуляция; гость управляет своим котом сам. */
import type { Txt } from "../core/i18n";
import type { CatLook } from "../game/cats/look";
import type { MirrorInfo } from "../game/sim/world";
import type { Entity, GameEvent } from "../game/sim/types";
import type { SkillDef } from "../game/skills/types";
import type { Stats } from "../game/stats";
import type { ClassId, ModeConfig } from "../game/types";
import type { CatState } from "../engine/cat-types";

export type WireStats = Omit<Stats, "keystones"> & { keystones: [string, number][] };

export const packStats = (s: Stats): WireStats => ({ ...s, keystones: [...s.keystones.entries()] });
export const unpackStats = (w: WireStats): Stats => ({ ...w, keystones: new Map(w.keystones) as Stats["keystones"] });

export interface WelcomeMsg {
  t: "welcome";
  v: number;
  seed: number;
  mode: ModeConfig;
  /** id сущности гостя в мире хоста. */
  you: number;
  host: MirrorInfo;
  hostName: string;
  pos: { x: number; z: number };
  dungeon: { poiId: string; floor: number } | null;
  dungeonReturn: { x: number; z: number } | null;
  tod: number;
  /** Номер перехода (подземелье/выход): гость повторяет его в своих снимках. */
  ep: number;
}

/** Эффект контроля, наложенный на гостя у хоста. */
export interface WireStatus {
  kind: "stun" | "freeze" | "slow" | "blind" | "weaken" | "vulnerable";
  t: number;
  dur: number;
  value: number;
}

export type GuestMsg =
  | { t: "hello"; v: number; name: string; classId: ClassId; look: CatLook; level: number; stats: WireStats }
  /** h — высота над землёй (кот на дереве). */
  | { t: "st"; x: number; z: number; yaw: number; hp: number; mp: number; sh: number; alive: number; s: number; h: number; ep: number }
  | { t: "stats"; stats: WireStats; look: CatLook; level: number }
  | { t: "cast"; s: SkillDef; ax: number; az: number; tid: number }
  | { t: "req"; k: "dungeon" | "exit" | "stairs"; poiId?: string }
  | { t: "emote"; k: "meow" }
  | { t: "bye" };

export type HostMsg =
  | WelcomeMsg
  | { t: "spawn"; e: MirrorInfo[] }
  | { t: "gone"; ids: number[] }
  /** Плоский массив по SNAP_STRIDE чисел на сущность. */
  | { t: "snap"; tod: number; e: number[] }
  | { t: "cast"; c: number; s: SkillDef; ax: number; az: number; tid: number }
  | { t: "ev"; e: GameEvent[] }
  | { t: "dungeon"; poiId: string; floor: number; ret: { x: number; z: number } | null; ep: number }
  | { t: "exitDungeon"; x: number; z: number; ep: number }
  | { t: "status"; s: WireStatus }
  | { t: "emote"; id: number; k: "meow" }
  | { t: "toast"; text: Txt; color?: number; icon?: string }
  | { t: "bye" };

/** id, x, z, yaw, hp, maxHp, флаги (жив | состояние << 1), высота над землёй. */
export const SNAP_STRIDE = 8;
/** Порядок важен: индекс уходит в 3 бита флагов снимка. */
export const STATES: CatState[] = ["alive", "dead", "sit", "loaf", "sleep", "swim", "climb", "perch"];

export const r2 = (v: number) => Math.round(v * 100) / 100;

export function mirrorOf(e: Entity): MirrorInfo {
  return {
    id: e.id,
    kind: e.kind,
    name: e.name,
    look: e.look,
    x: r2(e.x),
    z: r2(e.z),
    yaw: r2(e.yaw),
    level: e.level,
    hp: Math.round(e.hp),
    maxHp: Math.round(e.maxHp),
    alive: e.alive,
    radius: e.radius,
    faction: e.faction,
    classId: e.classId,
    enemy: e.enemy ? { family: e.enemy.family, role: e.enemy.role, elite: e.enemy.elite, boss: e.enemy.boss, poiId: e.enemy.poiId, named: e.enemy.named } : undefined,
    npc: e.npc ? { role: e.npc.role, npcId: e.npc.npcId, townId: e.npc.townId } : undefined,
    minionOwner: e.minion ? e.minion.ownerId : undefined,
  };
}
