import { observer } from "mobx-react-lite";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn } from "../common";
import type { QualityLevel } from "../../engine/renderer";

export const SettingsForm = observer(() => {
  const s = useStore();
  const st = s.settings;
  const Toggle = ({ k, label }: { k: "showFps" | "autoAim" | "damageNumbers" | "cameraShake" | "leftHanded" | "muted" | "useStun"; label: { ru: string; en: string } }) => (
    <label className="row" style={{ justifyContent: "space-between", marginBottom: 10, cursor: "pointer", flexWrap: "nowrap" }}>
      <span style={{ flex: 1 }}>{tr(label)}</span>
      <input type="checkbox" checked={st[k]} onChange={(e) => st.set(k, e.target.checked)} style={{ width: 22, height: 22, flex: "none" }} />
    </label>
  );
  return (
    <div>
      <div className="setting">
        <div className="label">{tr({ ru: "Язык", en: "Language" })}</div>
        <div className="seg">
          <button className={st.lang === "ru" ? "on" : ""} onClick={() => st.set("lang", "ru")}>
            Русский
          </button>
          <button className={st.lang === "en" ? "on" : ""} onClick={() => st.set("lang", "en")}>
            English
          </button>
        </div>
      </div>
      <div className="setting">
        <div className="label">{tr({ ru: "Графика", en: "Graphics" })}</div>
        <div className="seg">
          {(["low", "medium", "high"] as QualityLevel[]).map((q) => (
            <button key={q} className={st.quality === q ? "on" : ""} onClick={() => st.set("quality", q)}>
              {tr(q === "low" ? { ru: "Низкая", en: "Low" } : q === "medium" ? { ru: "Средняя", en: "Medium" } : { ru: "Высокая", en: "High" })}
            </button>
          ))}
        </div>
      </div>
      <div className="setting">
        <div className="label">{tr({ ru: "Сложность", en: "Difficulty" })}</div>
        <div className="seg">
          {(["easy", "normal", "hard"] as const).map((d) => (
            <button key={d} className={st.difficulty === d ? "on" : ""} onClick={() => st.set("difficulty", d)}>
              {tr(d === "easy" ? { ru: "Котёнок", en: "Kitten" } : d === "normal" ? { ru: "Кот", en: "Cat" } : { ru: "Тигр", en: "Tiger" })}
            </button>
          ))}
        </div>
      </div>
      <div className="setting">
        <div className="label">
          {tr({ ru: "Звуки", en: "Sound" })}: {Math.round(st.sfx * 100)}%
        </div>
        <input type="range" min={0} max={1} step={0.05} value={st.sfx} onChange={(e) => st.set("sfx", parseFloat(e.target.value))} />
      </div>
      <div className="setting">
        <div className="label">
          {tr({ ru: "Музыка", en: "Music" })}: {Math.round(st.music * 100)}%
        </div>
        <input type="range" min={0} max={1} step={0.05} value={st.music} onChange={(e) => st.set("music", parseFloat(e.target.value))} />
      </div>
      <div className="setting">
        <div className="label">
          {tr({ ru: "Размер интерфейса", en: "UI scale" })}: {Math.round(st.hudScale * 100)}%
        </div>
        <input type="range" min={0.75} max={1.4} step={0.05} value={st.hudScale} onChange={(e) => st.set("hudScale", parseFloat(e.target.value))} />
      </div>
      <div className="setting">
        <div className="label">
          {tr({ ru: "Длина суток", en: "Day length" })}: {st.dayLength} {tr({ ru: "мин", en: "min" })}
        </div>
        <input type="range" min={5} max={60} step={5} value={st.dayLength} onChange={(e) => st.set("dayLength", parseInt(e.target.value))} />
      </div>
      <Toggle k="autoAim" label={{ ru: "Автоприцел навыков", en: "Skill auto-aim" }} />
      <Toggle k="damageNumbers" label={{ ru: "Числа урона", en: "Damage numbers" }} />
      <Toggle k="cameraShake" label={{ ru: "Тряска камеры", en: "Camera shake" }} />
      <Toggle k="leftHanded" label={{ ru: "Кнопки слева (для левшей)", en: "Buttons on the left (left-handed)" }} />
      <Toggle k="showFps" label={{ ru: "Показывать FPS", en: "Show FPS" }} />
      <Toggle k="muted" label={{ ru: "Выключить звук", en: "Mute" }} />
      <Toggle k="useStun" label={{ ru: "Кооператив через интернет (публичный STUN)", en: "Co-op over the internet (public STUN)" }} />
    </div>
  );
});

export const SettingsScreen = observer(() => {
  const s = useStore();
  return (
    <div className="menu-screen" style={{ justifyContent: "flex-start" }}>
      <div className="menu-card" style={{ maxWidth: 560 }}>
        <div className="row" style={{ flexWrap: "nowrap", marginBottom: 8 }}>
          <h2 style={{ margin: 0 }}>{tr({ ru: "Настройки", en: "Settings" })}</h2>
          <div className="spacer" />
          <Btn small kind="ghost" onClick={() => s.ui.go("menu")}>
            ✕
          </Btn>
        </div>
        <SettingsForm />
        <Btn onClick={() => s.ui.go("menu")}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
      </div>
    </div>
  );
});
