import { FRAME_GLSL, HEADER, LIGHTING_GLSL, FOCUS_GLSL, SKY_GLSL, UTIL_GLSL } from "./common";
import { MATERIAL_GLSL } from "../materials";

/**
 * Шейдер ландшафта и пола подземелий. Цвет вершины — палитра биома, веса в color.a, misc.zw, normal.w —
 * доли четырёх материалов палитры чанка (uMats); крутые склоны покрываются материалом uSlopeMat (трипланарно).
 */
export const TERRAIN_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
layout(location=0) in vec3 aPos;
layout(location=1) in vec4 aNormal;
layout(location=2) in vec4 aColor;
layout(location=3) in vec4 aMisc;
uniform vec3 uOffset;
out vec3 vWorld;
out vec3 vNormal;
out vec3 vColor;
out vec2 vMisc;
out vec4 vWeights;
void main() {
  vec3 wp = aPos + uOffset;
  vWorld = wp;
  vNormal = normalize(aNormal.xyz);
  vColor = toLinear(aColor.rgb);
  vMisc = aMisc.xy;
  vWeights = vec4(aColor.a, aMisc.z, aMisc.w, max(aNormal.w, 0.0));
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

/** Каустики: сетка светлых линий по границам ячеек, точки ячеек плавают во времени. */
const CAUSTICS_GLSL = /* glsl */ `
float caustics(vec2 p, float t) {
  vec2 n = floor(p);
  vec2 f = fract(p);
  float d1 = 8.0, d2 = 8.0;
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 h = hash22(n + g);
      vec2 o = 0.5 + 0.42 * sin(t * (0.6 + h * 0.5) + 6.2831 * h);
      vec2 r = g + o - f;
      float d = dot(r, r);
      if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
    }
  float e = sqrt(d2) - sqrt(d1);
  return 1.0 - smoothstep(0.0, 0.16, e);
}
`;

export const TERRAIN_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
${LIGHTING_GLSL}
${MATERIAL_GLSL}
${CAUSTICS_GLSL}
in vec3 vWorld;
in vec3 vNormal;
in vec3 vColor;
in vec2 vMisc;
in vec4 vWeights;
uniform float uDetail;
uniform vec4 uMats;
uniform float uSlopeMat;
out vec4 outColor;

void main() {
  vec3 N = normalize(vNormal);
  vec3 albedo = vColor;
  vec2 p = vWorld.xz + uOriginMod.xy;
  float spec = 0.0, gloss = 30.0, cav = 1.0;
  // Производные вне ветвлений (иначе выбор мипа не определён)
  vec2 dpx = dFdx(p), dpy = dFdy(p);
  vec2 uvx = vec2(vWorld.z + uOriginMod.y, vWorld.y);
  vec2 uvz = vec2(vWorld.x + uOriginMod.x, vWorld.y);
  vec2 dxx = dFdx(uvx), dyx = dFdy(uvx), dxz = dFdx(uvz), dyz = dFdy(uvz);
  if (uDetail > 0.5) {
    bool low = uOriginMod.w < 0.5;
    vec4 w = vWeights;
    if (low) { w.zw = vec2(0.0); }
    w /= max(w.x + w.y + w.z + w.w, 1e-3);
    MatS s[4];
    vec4 hv = vec4(-4.0);
    for (int i = 0; i < 4; i++) {
      s[i].alb = vec3(1.0); s[i].h = 0.0; s[i].n = vec2(0.0); s[i].ao = 1.0; s[i].spec = 0.0;
      if (w[i] > 0.004) {
        float L = uMats[i];
        float sc = MAT_INFO[int(L)].x;
        s[i] = matFetch(L, p * sc, dpx * sc, dpy * sc);
        hv[i] = s[i].h + w[i] * 1.2;
      }
    }
    // Смешивание по высоте: песок забивается между камнями, трава растёт из трещин
    float ma = max(max(hv.x, hv.y), max(hv.z, hv.w)) - 0.3;
    vec4 b = max(hv - ma, 0.0);
    b /= max(b.x + b.y + b.z + b.w, 1e-4);
    vec3 alb = vec3(0.0);
    vec2 nrm = vec2(0.0);
    float gh = 0.0;
    for (int i = 0; i < 4; i++) {
      vec4 info = MAT_INFO[int(uMats[i])];
      alb += s[i].alb * b[i];
      nrm += s[i].n * info.y * b[i];
      cav += (s[i].ao - 1.0) * b[i];
      spec += s[i].spec * info.z * b[i];
      gloss += (info.w - 30.0) * b[i];
      gh += s[i].h * b[i];
    }
    vec3 Nt = normalize(N + vec3(nrm.x, 0.0, nrm.y) * 0.9);
    // Склоны: скала трипланарно (на слабом качестве — сверху)
    float rw = smoothstep(0.8, 0.56, N.y);
    if (rw > 0.01) {
      float L = uSlopeMat;
      vec4 info = MAT_INFO[int(L)];
      float sc = info.x;
      vec2 tw = pow(abs(N.xz) + 1e-3, vec2(4.0));
      tw /= tw.x + tw.y;
      MatS r;
      vec3 rn;
      if (low) {
        r = matFetch(L, p * sc, dpx * sc, dpy * sc);
        rn = N + vec3(r.n.x, 0.0, r.n.y) * info.y;
      } else {
        MatS rx = matFetch(L, uvx * sc, dxx * sc, dyx * sc);
        MatS rz = matFetch(L, uvz * sc, dxz * sc, dyz * sc);
        r.alb = rx.alb * tw.x + rz.alb * tw.y;
        r.h = rx.h * tw.x + rz.h * tw.y;
        r.ao = rx.ao * tw.x + rz.ao * tw.y;
        r.spec = rx.spec * tw.x + rz.spec * tw.y;
        rn = N + (vec3(0.0, rx.n.y, rx.n.x) * tw.x + vec3(rz.n.x, rz.n.y, 0.0) * tw.y) * info.y;
      }
      float k = smoothstep(0.35, 0.65, rw + (r.h - gh) * 0.5);
      alb = mix(alb, r.alb, k);
      cav = mix(cav, r.ao, k);
      spec = mix(spec, r.spec * info.z, k);
      gloss = mix(gloss, info.w, k);
      Nt = normalize(mix(Nt, normalize(rn), k));
    }
    albedo *= alb * mix(1.0, cav, 0.6);
    N = Nt;
  } else {
    float n1 = vnoise(p * 0.35);
    float n2 = hash12(floor(p * 3.0));
    float flatness = smoothstep(0.75, 0.95, N.y);
    albedo *= 0.88 + 0.16 * n1 + 0.08 * (n2 - 0.5) * flatness;
  }
  float water = uMisc.x;
  float wet = 0.0;
  if (uSkyColor.w < 0.5) {
    // Мокрая полоса у кромки воды и роса утром
    wet = smoothstep(0.9, 0.0, vWorld.y - water) * step(water - 0.4, vWorld.y);
    wet = max(wet, uFogParams.w * 0.5 * smoothstep(0.7, 1.0, N.y));
    albedo *= 1.0 - wet * 0.3;
    spec = max(spec, wet * 0.8);
    gloss = mix(gloss, 80.0, wet);
  }
  float sh = blobShadows(vWorld);
  float ao = sh * (0.45 + 0.55 * vMisc.x) * cav;
  vec3 V = normalize(uCamPos.xyz - vWorld);
  float shadow = sunShadow(vWorld, N);
  vec3 col = shadeFull(albedo, N, V, vWorld, vMisc.y, ao, spec, gloss, shadow);
  // Каустики на дне
  if (vWorld.y < water && uSkyColor.w < 0.5) {
    float depth = water - vWorld.y;
    float t = uCamPos.w;
    float c = caustics(p * 0.45, t * 1.1) * 0.6 + caustics(p * 0.8 + 3.7, t * 1.4) * 0.4;
    float k = exp(-depth * 0.35) * smoothstep(0.0, 0.4, depth);
    col += albedo * uSunColor.rgb * uSunDir.w * c * k * 1.6 * shadow;
  }
  col = applyDecals(col, vWorld);
  col = fog(col, vWorld);
  outColor = vec4(col, 1.0);
}
`;

/**
 * Инстансированные пропы и постройки: позиция+поворот, масштаб+тон.
 * Материал вершины (misc.w) проецируется на плоскость грани в координатах объекта:
 * так текстура «приклеена» к дому, а на скатах крыши чешуя смотрит вниз по скату.
 */
export const PROP_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${MATERIAL_GLSL}
layout(location=0) in vec3 aPos;
layout(location=1) in vec4 aNormal;
layout(location=2) in vec4 aColor;
layout(location=3) in vec4 aMisc;
layout(location=4) in vec4 iPosRot;
layout(location=5) in vec4 iScaleTint;
out vec3 vWorld;
out vec3 vNormal;
out vec3 vColor;
out float vEmissive;
out vec2 vUv;
out vec3 vTan;
out vec3 vBit;
flat out float vMat;
void main() {
  float s = iScaleTint.x;
  float c = cos(iPosRot.w), sn = sin(iPosRot.w);
  vec3 p = aPos * s;
  vec3 n = aNormal.xyz;
  // Проекция текстуры по доминирующей оси нормали (до покачивания)
  float mat = floor(aMisc.w * 255.0 + 0.5) - 1.0;
  vMat = mat;
  vec3 an = abs(n);
  vec2 uv;
  vec3 T, B;
  if (an.y >= an.x && an.y >= an.z) {
    if (an.x > an.z) { float sx = n.x >= 0.0 ? 1.0 : -1.0; uv = vec2(p.z, p.x * sx); T = vec3(0.0, 0.0, 1.0); B = vec3(sx, 0.0, 0.0); }
    else { float sz = n.z >= 0.0 ? 1.0 : -1.0; uv = vec2(p.x, p.z * sz); T = vec3(1.0, 0.0, 0.0); B = vec3(0.0, 0.0, sz); }
  } else if (an.x >= an.z) {
    uv = vec2(p.z, -p.y); T = vec3(0.0, 0.0, 1.0); B = vec3(0.0, -1.0, 0.0);
  } else {
    uv = vec2(p.x, -p.y); T = vec3(1.0, 0.0, 0.0); B = vec3(0.0, -1.0, 0.0);
  }
  vUv = mat >= 0.0 ? uv * MAT_INFO[int(mat)].x : vec2(0.0);
  float t = uCamPos.w;
  float sway = aMisc.x * max(p.y, 0.0);
  float ph = iPosRot.x * 0.21 + iPosRot.z * 0.17;
  float gust = 0.6 + 0.4 * sin(t * 0.7 + ph * 0.3) * uWind.z;
  p.x += (sin(t * 1.6 + ph) * 0.045 + uWind.x * 0.03 * gust) * sway;
  p.z += (cos(t * 1.25 + ph * 1.3) * 0.03 + uWind.y * 0.03 * gust) * sway;
  vec3 wp = vec3(c * p.x + sn * p.z, p.y, -sn * p.x + c * p.z) + iPosRot.xyz;
  vNormal = normalize(vec3(c * n.x + sn * n.z, n.y, -sn * n.x + c * n.z));
  vTan = vec3(c * T.x + sn * T.z, T.y, -sn * T.x + c * T.z);
  vBit = vec3(c * B.x + sn * B.z, B.y, -sn * B.x + c * B.z);
  vWorld = wp;
  vColor = toLinear(mix(aColor.rgb, aColor.rgb * iScaleTint.yzw, aMisc.z));
  vEmissive = aMisc.y;
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

export const PROP_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
${LIGHTING_GLSL}
${FOCUS_GLSL}
${MATERIAL_GLSL}
in vec3 vWorld;
in vec3 vNormal;
in vec3 vColor;
in float vEmissive;
in vec2 vUv;
in vec3 vTan;
in vec3 vBit;
flat in float vMat;
out vec4 outColor;
void main() {
  if (focusCutout(vWorld)) discard;
  vec3 N = normalize(vNormal);
  if (!gl_FrontFacing) N = -N;
  vec2 dx = dFdx(vUv), dy = dFdy(vUv);
  vec3 albedo = vColor;
  float spec = 0.0, gloss = 16.0, cav = 1.0;
  if (vMat >= 0.0) {
    MatS m = matFetch(vMat, vUv, dx, dy);
    vec4 info = MAT_INFO[int(vMat)];
    albedo *= m.alb * mix(1.0, m.ao, 0.6);
    N = normalize(N + (normalize(vTan) * m.n.x + normalize(vBit) * m.n.y) * info.y);
    spec = m.spec * info.z;
    gloss = info.w;
    cav = m.ao;
  }
  float em = vEmissive * (0.55 + 0.45 * uOriginMod.z + 0.3 * uSkyColor.w);
  vec3 V = normalize(uCamPos.xyz - vWorld);
  vec3 col = shadeFull(albedo, N, V, vWorld, em, cav, spec, gloss, sunShadow(vWorld, N));
  col = fog(col, vWorld);
  outColor = vec4(col, 1.0);
}
`;

/** Небо: градиент с зорями, солнце, луна-кошка, звёзды, созвездия, млечный путь, сияние, облака. */
export const SKY_VS = /* glsl */ `${HEADER}
out vec2 vNdc;
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2)) * 2.0 - 1.0;
  vNdc = p;
  gl_Position = vec4(p, 0.9999, 1.0);
}
`;

export const SKY_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
in vec2 vNdc;
uniform mat4 uInvViewProj;
uniform float uQuality;
out vec4 outColor;

// Созвездия в «куполе» (стереографическая проекция от надира): кошачья голова и рыбка
const int CAT_N = 8;
const vec2 CAT_PTS[8] = vec2[8](vec2(-0.6, 0.9), vec2(-0.9, 0.1), vec2(0.0, -0.75), vec2(0.9, 0.1), vec2(0.6, 0.9), vec2(0.25, 0.45), vec2(-0.25, 0.45), vec2(-0.6, 0.9));
const int FISH_N = 9;
const vec2 FISH_PTS[9] = vec2[9](vec2(-1.0, 0.0), vec2(-0.1, 0.45), vec2(0.6, 0.0), vec2(-0.1, -0.45), vec2(-1.0, 0.0), vec2(0.6, 0.0), vec2(1.05, 0.42), vec2(1.05, -0.42), vec2(0.6, 0.0));

float segDist(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

vec3 constellations(vec2 dome, float pxs) {
  vec3 acc = vec3(0.0);
  // Кошка
  vec2 c1 = vec2(0.28, -0.22);
  float s1 = 0.16;
  vec2 q = (dome - c1) / s1;
  if (dot(q, q) < 2.5) {
    float line = 1e3;
    float star = 0.0;
    for (int i = 0; i < CAT_N - 1; i++) {
      line = min(line, segDist(q, CAT_PTS[i], CAT_PTS[i + 1]));
      star += smoothstep(0.09, 0.0, length(q - CAT_PTS[i]));
    }
    star += smoothstep(0.08, 0.0, length(q - vec2(-0.33, 0.12))) + smoothstep(0.08, 0.0, length(q - vec2(0.33, 0.12)));
    acc += vec3(0.55, 0.7, 1.0) * smoothstep(pxs * 1.5 / s1, 0.0, line) * 0.22 + vec3(1.0, 0.95, 0.85) * star * 2.2;
  }
  // Рыбка
  vec2 c2 = vec2(-0.42, 0.3);
  float s2 = 0.13;
  q = (dome - c2) / s2;
  if (dot(q, q) < 2.5) {
    float line = 1e3;
    float star = 0.0;
    for (int i = 0; i < FISH_N - 1; i++) {
      line = min(line, segDist(q, FISH_PTS[i], FISH_PTS[i + 1]));
      star += smoothstep(0.09, 0.0, length(q - FISH_PTS[i]));
    }
    acc += vec3(0.55, 0.8, 1.0) * smoothstep(pxs * 1.5 / s2, 0.0, line) * 0.2 + vec3(0.85, 0.95, 1.0) * star * 1.8;
  }
  return acc;
}

vec3 stars(vec3 dir) {
  vec3 acc = vec3(0.0);
  for (int layer = 0; layer < 2; layer++) {
    float R = layer == 0 ? 130.0 : 260.0;
    vec3 p = dir * R;
    vec3 id = floor(p);
    float h = hash13(id + float(layer) * 71.0);
    float th = layer == 0 ? 0.972 : 0.955;
    if (h > th) {
      vec3 o = 0.25 + 0.5 * hash33(id + 13.0);
      float d = length(fract(p) - o);
      float b = (h - th) / (1.0 - th);
      float tw = 0.65 + 0.35 * sin(uCamPos.w * (1.5 + 3.0 * fract(h * 17.0)) + h * 90.0);
      vec3 c = mix(vec3(0.65, 0.78, 1.0), vec3(1.0, 0.82, 0.62), fract(h * 37.0));
      acc += c * smoothstep(0.22, 0.0, d) * (0.4 + b * 2.6) * tw * (layer == 0 ? 1.4 : 0.8);
    }
  }
  return acc;
}

float triArea(vec2 a, vec2 b, vec2 c) { return (b.x - a.x) * (c.y - a.y) - (c.x - a.x) * (b.y - a.y); }
bool inTri(vec2 p, vec2 a, vec2 b, vec2 c) {
  float d1 = triArea(p, a, b), d2 = triArea(p, b, c), d3 = triArea(p, c, a);
  bool neg = d1 < 0.0 || d2 < 0.0 || d3 < 0.0;
  bool pos = d1 > 0.0 || d2 > 0.0 || d3 > 0.0;
  return !(neg && pos);
}

// Луна с кошачьими ушками и мордочкой из «морей»
vec4 catMoon(vec3 dir, vec3 md) {
  vec3 right = normalize(cross(md, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, md);
  float R = 0.045;
  vec2 p = vec2(dot(dir, right), dot(dir, up)) / R;
  if (dot(dir, md) < 0.0) return vec4(0.0);
  float r = length(p);
  bool ear = inTri(p, vec2(-0.95, 0.35), vec2(-0.72, 1.38), vec2(-0.2, 0.9)) || inTri(p, vec2(0.95, 0.35), vec2(0.72, 1.38), vec2(0.2, 0.9));
  float disk = smoothstep(1.0, 0.96, r);
  float body = max(disk, ear ? 1.0 : 0.0);
  if (body <= 0.0) {
    float halo = exp(-max(r - 1.0, 0.0) * 1.3) * 0.25 + exp(-max(r - 1.0, 0.0) * 5.0) * 0.35;
    return vec4(vec3(0.75, 0.82, 1.0) * halo, 0.0);
  }
  vec3 c = vec3(1.0, 0.96, 0.86);
  // Моря и кратеры
  float n = vnoise(p * 3.0 + 7.0) * 0.6 + vnoise(p * 7.0) * 0.4;
  c *= 0.86 + 0.14 * n;
  // Мордочка: сомкнутые глазки «^ ^», носик и рот «w»
  float eyes = min(segDist(vec2(abs(p.x), p.y), vec2(0.22, 0.18), vec2(0.36, 0.3)), segDist(vec2(abs(p.x), p.y), vec2(0.36, 0.3), vec2(0.5, 0.18)));
  float mouth = min(segDist(vec2(abs(p.x), p.y), vec2(0.0, -0.22), vec2(0.1, -0.32)), segDist(vec2(abs(p.x), p.y), vec2(0.1, -0.32), vec2(0.2, -0.22)));
  float nose = length((p - vec2(0.0, -0.08)) * vec2(1.0, 1.5)) - 0.07;
  float mark = smoothstep(0.05, 0.02, min(min(eyes, mouth), nose));
  c = mix(c, c * vec3(0.7, 0.66, 0.7), mark * 0.8);
  // Внутренность ушек розоватая
  if (ear && r > 0.97) c = mix(c, vec3(1.0, 0.78, 0.8), 0.5);
  float limb = 0.75 + 0.25 * sqrt(max(1.0 - r * r, 0.0));
  return vec4(c * limb * 2.2, 1.0);
}

vec3 aurora(vec3 dir) {
  if (dir.y < 0.03) return vec3(0.0);
  vec3 acc = vec3(0.0);
  float t = uCamPos.w * 0.04;
  for (int i = 0; i < 9; i++) {
    float fi = float(i) / 8.0;
    float h = 1.0 + fi * 0.9;
    vec2 p = dir.xz / dir.y * h * 0.35;
    // Две ленты: на севере и на юге неба
    float center = sin(p.x * 0.7 + t * 2.0) * 0.8 + (vnoise(vec2(p.x * 0.45 + t * 3.0, fi)) - 0.5) * 1.8 + 1.1;
    float d = abs(abs(p.y) - center);
    float band = exp(-d * d * 3.0);
    float rays = 0.55 + 0.45 * vnoise(vec2(p.x * 9.0 + t * 12.0, 0.0));
    vec3 c = mix(vec3(0.1, 1.0, 0.45), vec3(0.75, 0.2, 1.0), fi * fi);
    acc += c * band * rays * (1.0 - fi * 0.6);
  }
  return acc * 0.34 * smoothstep(0.03, 0.2, dir.y);
}

float cloudShape(vec2 p, float cover) {
  vec2 w = vec2(vnoise(p * 0.5 + 3.1), vnoise(p * 0.5 + 8.7));
  float n = fbm3(p + w * 1.4);
  n = n * 0.75 + vnoise(p * 5.3 + w) * 0.25;
  return smoothstep(1.0 - cover * 0.95, 1.0 - cover * 0.95 + 0.32, n);
}

void main() {
  vec4 a = uInvViewProj * vec4(vNdc, -1.0, 1.0);
  vec4 b = uInvViewProj * vec4(vNdc, 1.0, 1.0);
  vec3 dir = normalize(b.xyz / b.w - a.xyz / a.w);
  float pxs = length(dFdx(dir)) + length(dFdy(dir));
  float h = dir.y;
  vec3 col = skyGradient(dir);
  float night = uOriginMod.z;
  vec3 sd = normalize(uSunTrue.xyz);
  // Ночное небо: звёзды, млечный путь, созвездия
  if (night > 0.02 && h > -0.02) {
    float fade = night * smoothstep(-0.02, 0.2, h);
    vec3 nd = normalize(vec3(0.35, 0.3, 0.88));
    float bandD = dot(dir, nd);
    float band = exp(-bandD * bandD * 14.0);
    float mw = fbm3(dir.xz / (h + 1.2) * 5.0 + 11.0);
    col += vec3(0.32, 0.26, 0.55) * band * mw * mw * 0.18 * fade;
    col += stars(dir) * fade * (1.0 + band * 0.8);
    vec2 dome = dir.xz / (1.0 + max(h, 0.0));
    col += constellations(dome, pxs) * fade;
    if (uMoonDir.w > 0.01) col += aurora(dir) * uMoonDir.w * fade;
  }
  // Луна
  if (uSunTrue.w > 0.01) {
    vec4 m = catMoon(dir, normalize(uMoonDir.xyz));
    col = mix(col + m.rgb * uSunTrue.w, m.rgb * uSunTrue.w + col * 0.1, m.a * uSunTrue.w);
  }
  // Солнце: яркий диск (блум даёт ореол), у горизонта краснеет
  float sdot = dot(dir, sd);
  float sunUp = smoothstep(-0.05, 0.03, sd.y);
  vec3 sunTint = mix(vec3(1.0, 0.45, 0.18), vec3(1.0, 0.93, 0.82), smoothstep(0.0, 0.35, sd.y));
  float disk = smoothstep(0.99965, 0.99985, sdot);
  col += sunTint * disk * 40.0 * sunUp;
  // Облака
  float cover = uWind.w;
  if (h > 0.0 && cover > 0.02) {
    vec2 cp = dir.xz / (h + 0.1) * 0.9 + uWind.xy * uCamPos.w * 0.006;
    float d = cloudShape(cp, cover);
    if (d > 0.001) {
      vec2 toSun = normalize(sd.xz + 1e-4) * 0.18;
      float d2 = cloudShape(cp + toSun, cover);
      float lit = clamp(0.55 + (d - d2) * 1.6, 0.0, 1.0);
      vec3 sunC = uSunColor.rgb * uSunDir.w;
      vec3 amb = mix(uHorizon.rgb, uSkyColor.rgb, 0.4) * (0.55 + uSunColor.w * 0.5);
      vec3 cc = amb * (0.7 - d * 0.25) + sunC * lit * 0.75;
      // Серебристая кайма у солнца
      float edge = (1.0 - d) * pow(max(sdot, 0.0), 12.0) * sunUp;
      cc += sunTint * edge * 2.5;
      // Зори окрашивают облака снизу
      float low = 1.0 - clamp(abs(sd.y) * 3.0, 0.0, 1.0);
      cc = mix(cc, cc * vec3(1.25, 0.8, 0.65) + vec3(0.25, 0.08, 0.04) * lit, low * 0.6 * sunUp);
      float fadeH = smoothstep(0.0, 0.12, h);
      col = mix(col, cc, d * fadeH * 0.92);
      // Высокие перистые облака (тонкие штрихи)
    }
    if (uQuality > 0.5) {
      vec2 hp = dir.xz / (h + 0.05) * vec2(0.35, 1.4) + uWind.xy * uCamPos.w * 0.01 + 40.0;
      float ci = smoothstep(0.62, 0.95, fbm3(hp * 1.3)) * smoothstep(0.0, 0.3, h) * cover;
      col += (uSunColor.rgb * uSunDir.w * 0.5 + uHorizon.rgb * 0.4) * ci * 0.35;
    }
  }
  outColor = vec4(col, 1.0);
}
`;

/** Вода: глубина по карте высот, мелководье и пена у берега, френель с отражением неба, блики. */
export const WATER_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
layout(location=0) in vec3 aPos;
uniform vec3 uOffset;
out vec3 vWorld;
void main() {
  vec3 wp = aPos + uOffset;
  vec2 p = wp.xz + uOriginMod.xy;
  float t = uCamPos.w;
  wp.y += uMisc.x + sin(p.x * 0.35 + t * 1.3) * 0.04 + cos(p.y * 0.3 + t * 1.1) * 0.04;
  vWorld = wp;
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

export const WATER_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
${LIGHTING_GLSL}
in vec3 vWorld;
uniform vec3 uWaterColor;
uniform float uLava;
uniform sampler2D uHeightField;
out vec4 outColor;

// Наклон поверхности: сумма направленных волн + мелкая рябь
vec2 waveSlope(vec2 p, float t) {
  vec2 g = vec2(0.0);
  vec2 d1 = normalize(vec2(1.0, 0.35)), d2 = normalize(vec2(-0.45, 1.0)), d3 = normalize(vec2(0.8, -0.7)), d4 = normalize(vec2(-1.0, -0.2));
  g += d1 * cos(dot(d1, p) * 0.55 + t * 1.2) * 0.55 * 0.12;
  g += d2 * cos(dot(d2, p) * 0.9 + t * 1.6) * 0.9 * 0.07;
  g += d3 * cos(dot(d3, p) * 1.7 + t * 2.3) * 1.7 * 0.035;
  g += d4 * cos(dot(d4, p) * 2.9 + t * 3.1) * 2.9 * 0.018;
  vec2 q = p * 1.6 + vec2(t * 0.35, t * 0.22);
  float e = 0.08;
  float n0 = vnoise(q), nx = vnoise(q + vec2(e, 0.0)), nz = vnoise(q + vec2(0.0, e));
  g += vec2(nx - n0, nz - n0) / e * 0.06;
  vec2 q2 = p * 3.7 - vec2(t * 0.5, t * 0.3);
  n0 = vnoise(q2); nx = vnoise(q2 + vec2(e, 0.0)); nz = vnoise(q2 + vec2(0.0, e));
  g += vec2(nx - n0, nz - n0) / e * 0.03;
  return g;
}

void main() {
  vec2 p = vWorld.xz + uOriginMod.xy;
  float t = uCamPos.w;
  vec3 V = normalize(uCamPos.xyz - vWorld);
  float dist = length(uCamPos.xyz - vWorld);
  // Глубина под водой
  float depth = 8.0;
  float hfR = uMisc.z;
  if (hfR > 0.0 && length(vWorld.xz - uCamPos.xz) < hfR) {
    float th = texture(uHeightField, p * uMisc.w).r;
    depth = max(vWorld.y - th, 0.0);
  }
  if (uLava > 0.5) {
    // Лава: корка трескается, в трещинах светится
    vec3 v = voronoi(p * 0.35 + vec2(t * 0.03, t * 0.02));
    float crack = 1.0 - smoothstep(0.02, 0.14, v.y - v.x);
    float glow = vnoise(p * 0.6 + t * 0.2) * 0.6 + vnoise(p * 2.0 - t * 0.3) * 0.4;
    vec3 crust = vec3(0.06, 0.03, 0.025) * (0.6 + 0.8 * v.z);
    vec3 hot = mix(vec3(1.0, 0.22, 0.03), vec3(1.0, 0.7, 0.2), glow) * (3.0 + 2.0 * glow);
    float heat = max(crack, smoothstep(0.55, 0.9, glow) * 0.8);
    vec3 col = mix(crust, hot, heat);
    col += hot * 0.15;
    col = fog(col, vWorld);
    outColor = vec4(col, 1.0);
    return;
  }
  vec2 g = waveSlope(p, t);
  // Вдали рябь гасим — меньше мерцания
  g *= 1.0 / (1.0 + dist * 0.012);
  vec3 N = normalize(vec3(-g.x, 1.0, -g.y));
  float ndv = max(dot(N, V), 0.0);
  float fres = 0.02 + 0.98 * pow(1.0 - ndv, 5.0);
  // Цвет толщи: мелко — бирюза, глубоко — насыщенный тёмный
  vec3 base = toLinear(uWaterColor);
  vec3 shallowC = mix(base, vec3(0.1, 0.75, 0.7), 0.35) * 1.25;
  vec3 deepC = base * vec3(0.25, 0.4, 0.6);
  float absorb = 1.0 - exp(-depth * 0.45);
  vec3 body = mix(shallowC, deepC, absorb);
  vec3 lightAmt = uSunColor.rgb * uSunDir.w * max(uSunDir.y, 0.0) * 0.6 + ambientLight(vec3(0.0, 1.0, 0.0)) * 0.8;
  float shadow = sunShadow(vWorld, vec3(0.0, 1.0, 0.0));
  vec3 col = body * lightAmt * (0.6 + 0.4 * shadow);
  col += pointLights(N, vWorld) * body * 0.8;
  // Отражение неба
  vec3 R = reflect(-V, N);
  R.y = abs(R.y);
  vec3 refl = skyGradient(R);
  col = mix(col, refl, fres);
  // Солнечная дорожка
  vec3 H = normalize(uSunDir.xyz + V);
  float spec = pow(max(dot(N, H), 0.0), 380.0) * 60.0 + pow(max(dot(N, H), 0.0), 40.0) * 0.6;
  col += uSunColor.rgb * uSunDir.w * spec * shadow;
  // Пена у берега: полосы бегут к кромке
  float foamLine = smoothstep(0.9, 0.0, depth);
  float waves = sin(depth * 9.0 - t * 2.2 + vnoise(p * 0.8) * 4.0) * 0.5 + 0.5;
  float foamN = vnoise(p * 3.0 + vec2(t * 0.4, -t * 0.3));
  float foam = foamLine * smoothstep(0.35, 0.8, waves * 0.6 + foamN * 0.6);
  foam = max(foam, smoothstep(0.25, 0.0, depth) * 0.85);
  vec3 foamC = (uSunColor.rgb * uSunDir.w * shadow + ambientLight(vec3(0.0, 1.0, 0.0))) * 0.9;
  col = mix(col, foamC, foam * 0.85);
  float alpha = clamp(0.35 + absorb * 0.75 + fres * 0.5, 0.0, 1.0);
  alpha = max(alpha, foam);
  alpha *= smoothstep(0.0, 0.08, depth);
  col = fog(col, vWorld);
  outColor = vec4(col, alpha);
}
`;
