import { observer } from "mobx-react-lite";
import { useEffect, useRef, useState } from "react";
import { tr } from "../../core/i18n";
import { fmtCooldown } from "../../core/format";
import { audio } from "../../audio/audio";
import { useStore } from "../stores";
import { Glyph, hex } from "../icons";
import type { SkillDef } from "../../game/skills/types";

/** Сенсорный слой: стик слева, камера справа (свайп/щипок). */
export const TouchLayer = observer(() => {
  const s = useStore();
  const [joy, setJoy] = useState<{ ox: number; oy: number; kx: number; ky: number } | null>(null);
  const ptrs = useRef(new Map<number, { x: number; y: number; kind: "joy" | "cam" }>());
  const pinch = useRef<number | null>(null);
  const left = s.settings.leftHanded;
  useEffect(() => {
    return () => {
      const inp = s.session?.input;
      if (inp) {
        inp.joyX = inp.joyY = 0;
      }
    };
  }, [s]);
  const onDown = (e: React.PointerEvent) => {
    audio.unlock();
    const inp = s.session?.input;
    if (!inp) return;
    inp.isTouch = true;
    const w = window.innerWidth;
    const isJoySide = left ? e.clientX > w * 0.55 : e.clientX < w * 0.45;
    const hasJoy = [...ptrs.current.values()].some((p) => p.kind === "joy");
    const kind = isJoySide && !hasJoy ? "joy" : "cam";
    ptrs.current.set(e.pointerId, { x: e.clientX, y: e.clientY, kind });
    (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
    if (kind === "joy") setJoy({ ox: e.clientX, oy: e.clientY, kx: e.clientX, ky: e.clientY });
  };
  const onMove = (e: React.PointerEvent) => {
    const p = ptrs.current.get(e.pointerId);
    const inp = s.session?.input;
    if (!p || !inp) return;
    if (p.kind === "joy") {
      setJoy((j) => {
        if (!j) return j;
        let dx = e.clientX - j.ox,
          dy = e.clientY - j.oy;
        const l = Math.hypot(dx, dy);
        const R = 56;
        if (l > R) {
          dx *= R / l;
          dy *= R / l;
        }
        inp.joyX = dx / R;
        inp.joyY = -dy / R;
        return { ...j, kx: j.ox + dx, ky: j.oy + dy };
      });
    } else {
      const cams = [...ptrs.current.entries()].filter(([, v]) => v.kind === "cam");
      if (cams.length >= 2) {
        const [a, b] = cams.map(([id, v]) => (id === e.pointerId ? { x: e.clientX, y: e.clientY } : v));
        const d = Math.hypot(a.x - b.x, a.y - b.y);
        if (pinch.current !== null) inp.zoomDelta += (pinch.current - d) * 0.04;
        pinch.current = d;
      } else {
        inp.camYawDelta -= (e.clientX - p.x) * 0.009;
        inp.camPitchDelta += (e.clientY - p.y) * 0.005;
      }
      p.x = e.clientX;
      p.y = e.clientY;
    }
  };
  const onUp = (e: React.PointerEvent) => {
    const p = ptrs.current.get(e.pointerId);
    ptrs.current.delete(e.pointerId);
    pinch.current = null;
    const inp = s.session?.input;
    if (p?.kind === "joy" && inp) {
      inp.joyX = inp.joyY = 0;
      setJoy(null);
    }
  };
  return (
    <div className="touch-layer" onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
      {joy && (
        <>
          <div className="joystick-base" style={{ left: joy.ox, top: joy.oy }} />
          <div className="joystick-knob" style={{ left: joy.kx, top: joy.ky }} />
        </>
      )}
    </div>
  );
});

function aimRadius(sk: SkillDef): number {
  const p = sk.params;
  switch (sk.delivery) {
    case "blast":
    case "rain":
    case "vortex":
    case "mark":
    case "trap":
      return p.radius;
    case "leap":
      return p.radius;
    default:
      return 1;
  }
}

function aimRange(sk: SkillDef): number {
  const p = sk.params;
  switch (sk.delivery) {
    case "strike":
    case "cone":
      return Math.max(3, p.radius);
    case "beam":
      return p.radius;
    case "nova":
    case "aura":
    case "orbit":
    case "heal":
    case "buff":
    case "barrier":
    case "summon":
      return 4;
    default:
      return Math.max(4, p.range);
  }
}

const SkillButton = observer(({ slot, x, y, size }: { slot: number; x: number; y: number; size: number }) => {
  const s = useStore();
  const h = s.hud;
  const v = h.slots[slot];
  const start = useRef<{ x: number; y: number; aiming: boolean } | null>(null);
  const [pressed, setPressed] = useState(false);
  const skill = v?.id ? s.char?.skills.get(v.id) : undefined;
  const toWorld = (dx: number, dy: number, range: number): [number, number] => {
    const sess = s.session!;
    const l = Math.hypot(dx, dy);
    const k = (Math.min(1, l / 100) * range) / Math.max(l, 1e-4);
    const yaw = sess.camYaw;
    const rx = Math.cos(yaw),
      rz = -Math.sin(yaw);
    const fx = -Math.sin(yaw),
      fz = -Math.cos(yaw);
    const sx = dx * k,
      sy = -dy * k;
    return [rx * sx + fx * sy, rz * sx + fz * sy];
  };
  const down = (e: React.PointerEvent) => {
    e.stopPropagation();
    audio.unlock();
    (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
    start.current = { x: e.clientX, y: e.clientY, aiming: false };
    setPressed(true);
  };
  const move = (e: React.PointerEvent) => {
    const st = start.current;
    if (!st || !skill || !s.session) return;
    const dx = e.clientX - st.x,
      dy = e.clientY - st.y;
    if (Math.hypot(dx, dy) > 16) st.aiming = true;
    if (st.aiming) {
      const [wx, wz] = toWorld(dx, dy, aimRange(skill));
      s.session.dragAim = { dx: wx, dz: wz, r: aimRadius(skill) };
    }
  };
  const up = (e: React.PointerEvent) => {
    const st = start.current;
    start.current = null;
    setPressed(false);
    const sess = s.session;
    if (!sess) return;
    sess.dragAim = null;
    if (!st) return;
    // Пустой слот — подсказка: открыть дерево навыков
    if (!v?.id) {
      s.ui.open("skills");
      return;
    }
    if (st.aiming && skill) {
      const [wx, wz] = toWorld(e.clientX - st.x, e.clientY - st.y, aimRange(skill));
      sess.input.castSkill(slot, wx, wz);
    } else sess.input.castSkill(slot);
  };
  const cdPct = v && v.cd > 0 ? (v.cd / Math.max(0.01, v.cdTotal)) * 100 : 0;
  return (
    <div
      className={`abtn${pressed ? " pressed" : ""}${v?.noMana ? " nomana" : ""}`}
      style={{ left: x - size / 2, top: y - size / 2, width: size, height: size, background: v?.id ? `radial-gradient(circle at 35% 30%, ${hex(v.color, 0.95)}, ${hex(v.color, 0.35)} 70%, rgba(20,14,34,0.9))` : undefined, opacity: v?.id ? 1 : 0.35 }}
      onPointerDown={down}
      onPointerMove={move}
      onPointerUp={up}
      onPointerCancel={up}
    >
      {v?.id ? <Glyph name={v.glyph} size={size * 0.5} color="#fff" /> : <span style={{ fontSize: 11, opacity: 0.8 }}>+</span>}
      {cdPct > 0 && (
        <div className="cd" style={{ ["--cd" as string]: `${cdPct}%` }}>
          {fmtCooldown(v!.cd)}
        </div>
      )}
    </div>
  );
});

export const ActionCluster = observer(() => {
  const s = useStore();
  const h = s.hud;
  const left = s.settings.leftHanded;
  const [attack, setAttack] = useState(false);
  // Компактно: атака в самом углу, над ней одна дуга из четырёх навыков — остальной экран свободен для камеры
  const W = 160;
  const A = 68;
  const ax = left ? A / 2 + 4 : W - A / 2 - 4,
    ay = W - A / 2 - 4;
  const sign = left ? 1 : -1;
  const ring = (r: number, deg: number) => {
    const a = (deg * Math.PI) / 180;
    return { x: ax + sign * Math.cos(a) * r, y: ay - Math.sin(a) * r };
  };
  const layout = [ring(96, 0), ring(96, 30), ring(96, 60), ring(96, 90)];
  const setAtk = (v: boolean) => {
    setAttack(v);
    if (s.session) s.session.input.touchAttack = v;
  };
  const basicCd = h.basicCd;
  return (
    <div className={`action-cluster${left ? " left" : ""}`}>
      <div
        className={`abtn${attack ? " pressed" : ""}`}
        style={{ left: ax - A / 2, top: ay - A / 2, width: A, height: A, background: "radial-gradient(circle at 35% 30%, #ffd27a, #c8702a 70%)" }}
        onPointerDown={(e) => {
          e.stopPropagation();
          audio.unlock();
          (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
          setAtk(true);
        }}
        onPointerUp={() => setAtk(false)}
        onPointerCancel={() => setAtk(false)}
      >
        <Glyph name="claw" size={A / 2} color="#2a1a0a" stroke={2.6} />
        {basicCd > 0.05 && <div className="cd" style={{ ["--cd" as string]: `${Math.min(100, basicCd * 150)}%`, background: "none" }} />}
      </div>
      {layout.map((p, i) => (
        <SkillButton key={i} slot={i} x={p.x} y={p.y} size={44} />
      ))}
    </div>
  );
});

export const SkillBar = observer(() => {
  const s = useStore();
  const h = s.hud;
  const btn = (i: number) => {
    const v = h.slots[i];
    const cdPct = v && v.cd > 0 ? (v.cd / Math.max(0.01, v.cdTotal)) * 100 : 0;
    return (
      <div
        key={i}
        className={`abtn${v?.noMana ? " nomana" : ""}`}
        style={{ background: v?.id ? `radial-gradient(circle at 35% 30%, ${hex(v.color, 0.95)}, ${hex(v.color, 0.35)} 70%, rgba(20,14,34,0.9))` : undefined, opacity: v?.id ? 1 : 0.4 }}
        title={v?.name ? tr(v.name) : ""}
        onClick={() => s.session?.castSlot(i, null, null)}
      >
        {v?.id ? <Glyph name={v.glyph} size={28} color="#fff" /> : null}
        {cdPct > 0 && (
          <div className="cd" style={{ ["--cd" as string]: `${cdPct}%` }}>
            {fmtCooldown(v!.cd)}
          </div>
        )}
        <span className="key">{i + 1}</span>
      </div>
    );
  };
  return (
    <div className="skillbar">{[0, 1, 2, 3, 4, 5].map(btn)}</div>
  );
});

export const InteractButton = observer(() => {
  const s = useStore();
  const it = s.hud.interact;
  if (!it || s.ui.modalOpen || s.hud.dead) return null;
  const touch = s.session?.input.isTouch;
  return (
    <div className="interact-btn" onClick={() => s.session?.doInteract()}>
      {touch ? "👆 " : "[E] "}
      {tr(it.label)}
    </div>
  );
});

export const DeadOverlay = observer(() => {
  const s = useStore();
  if (!s.hud.dead) return null;
  return (
    <div className="dead-overlay">
      <div>
        <h1>💫 {tr({ ru: "Вы без сознания", en: "You fainted" })}</h1>
        <div>{tr({ ru: "Очнётесь в ближайшем городе через", en: "You'll wake up in the nearest town in" })} {Math.ceil(s.hud.respawnIn)}…</div>
      </div>
    </div>
  );
});

export const LoadingOverlay = observer(() => {
  const s = useStore();
  if (s.hud.loading >= 1) return null;
  return (
    <div className="loading">
      <div>
        <div className="paw">🐾</div>
        <div style={{ fontWeight: 900, fontSize: 20, marginTop: 8 }}>{tr({ ru: "Мир просыпается…", en: "The world is waking up…" })}</div>
        <div style={{ width: 220, margin: "12px auto 0" }}>
          <div className="bar" style={{ height: 10 }}>
            <div className="bar-fill" style={{ width: `${s.hud.loading * 100}%`, background: "var(--accent)" }} />
          </div>
        </div>
      </div>
    </div>
  );
});
