/**
 * Детерминированные хеши и генераторы случайных чисел.
 * Всё процедурное содержимое мира строится из seed-а через эти функции,
 * поэтому оба игрока в кооперативе видят одинаковый мир без передачи данных.
 */

/** Финальное перемешивание (murmur3 fmix32). */
export function fmix32(h: number): number {
  h ^= h >>> 16;
  h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13;
  h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

/** Хеш произвольного количества целых чисел → uint32. */
export function hashInts(...v: number[]): number {
  let h = 0x9e3779b9 ^ v.length;
  for (let i = 0; i < v.length; i++) {
    let k = Math.imul(v[i] | 0, 0xcc9e2d51);
    k = (k << 15) | (k >>> 17);
    k = Math.imul(k, 0x1b873593);
    h ^= k;
    h = (h << 13) | (h >>> 19);
    h = (Math.imul(h, 5) + 0xe6546b64) | 0;
  }
  return fmix32(h);
}

/** Быстрый хеш 2D-координаты с seed-ом → uint32. */
export function hash2(x: number, y: number, seed: number): number {
  let h = Math.imul(x | 0, 0x27d4eb2d) ^ Math.imul(y | 0, 0x165667b1) ^ Math.imul(seed | 0, 0x9e3779b1);
  return fmix32(h);
}

export function hash3(x: number, y: number, z: number, seed: number): number {
  let h = Math.imul(x | 0, 0x27d4eb2d) ^ Math.imul(y | 0, 0x165667b1) ^ Math.imul(z | 0, 0x3c6ef372) ^ Math.imul(seed | 0, 0x9e3779b1);
  return fmix32(h);
}

/** uint32 → [0,1) */
export const toUnit = (h: number) => (h >>> 0) / 4294967296;

export function hashStr(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return fmix32(h);
}

/** Случайное число [0,1) из 2D координаты. */
export const rand2 = (x: number, y: number, seed: number) => toUnit(hash2(x, y, seed));

/** Генератор sfc32 — быстрый, с хорошим качеством и 128-битным состоянием. */
export class Rng {
  private a: number;
  private b: number;
  private c: number;
  private d: number;

  constructor(seed: number | string = 1) {
    const s = typeof seed === "string" ? hashStr(seed) : seed >>> 0;
    this.a = fmix32(s ^ 0xdeadbeef);
    this.b = fmix32(s + 0x9e3779b9);
    this.c = fmix32(s ^ 0x85ebca6b);
    this.d = 1;
    for (let i = 0; i < 12; i++) this.nextU32();
  }

  nextU32(): number {
    const t = (((this.a + this.b) | 0) + this.d) | 0;
    this.d = (this.d + 1) | 0;
    this.a = this.b ^ (this.b >>> 9);
    this.b = (this.c + (this.c << 3)) | 0;
    this.c = (this.c << 21) | (this.c >>> 11);
    this.c = (this.c + t) | 0;
    return t >>> 0;
  }

  /** [0,1) */
  next(): number {
    return this.nextU32() / 4294967296;
  }

  /** [a,b) */
  range(a: number, b: number): number {
    return a + (b - a) * this.next();
  }

  /** Целое в [a,b] включительно. */
  int(a: number, b: number): number {
    return a + Math.floor(this.next() * (b - a + 1));
  }

  chance(p: number): boolean {
    return this.next() < p;
  }

  pick<T>(arr: readonly T[]): T {
    return arr[Math.floor(this.next() * arr.length)];
  }

  /** Выбор по весам. */
  weighted<T>(items: readonly T[], weights: readonly number[]): T {
    let total = 0;
    for (const w of weights) total += w;
    let r = this.next() * total;
    for (let i = 0; i < items.length; i++) {
      r -= weights[i];
      if (r <= 0) return items[i];
    }
    return items[items.length - 1];
  }

  /** Выбор по весам из объектов с полем weight. */
  pickWeighted<T extends { weight: number }>(items: readonly T[]): T {
    return this.weighted(
      items,
      items.map((i) => i.weight),
    );
  }

  shuffle<T>(arr: T[]): T[] {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  /** Нормальное распределение (Бокс–Мюллер). */
  gauss(mean = 0, sd = 1): number {
    const u = 1 - this.next();
    const v = this.next();
    return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  /** Независимый дочерний генератор (стабилен относительно соли). */
  fork(salt: number | string): Rng {
    const s = typeof salt === "string" ? hashStr(salt) : salt;
    return new Rng(hashInts(this.nextU32(), s));
  }

  /** Уникальный 31-битный идентификатор. */
  id(): number {
    return this.nextU32() & 0x7fffffff;
  }
}

/** Генератор, привязанный к набору целых чисел (например, мир+регион+индекс). */
export function rngFor(...parts: number[]): Rng {
  return new Rng(hashInts(...parts));
}
