/**
 * Карта теней от солнца (или луны): ортогональная проекция вокруг точки перед камерой.
 * Центр привязан к сетке текселей в мировых координатах — тени не «плавают» при движении.
 */
import { type GL } from "./gl";

export class ShadowMap {
  readonly tex: WebGLTexture;
  readonly fbo: WebGLFramebuffer;
  /** Матрица мир (относительно начала рендера) → клип-пространство источника. */
  readonly viewProj = new Float32Array(16);
  /** Матрица мир → [0..1] (координаты карты и глубина). */
  readonly shadowMat = new Float32Array(16);
  /** Размер текселя в метрах. */
  texelWorld = 0.1;
  /** Центр и радиус покрытия в мировых координатах. */
  cx = 0;
  cz = 0;
  radius = 40;

  constructor(
    readonly gl: GL,
    readonly size: number,
  ) {
    this.tex = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, this.tex);
    gl.texStorage2D(gl.TEXTURE_2D, 1, gl.DEPTH_COMPONENT24, size, size);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_MODE, gl.COMPARE_REF_TO_TEXTURE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_FUNC, gl.LEQUAL);
    this.fbo = gl.createFramebuffer()!;
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.TEXTURE_2D, this.tex, 0);
    gl.drawBuffers([gl.NONE]);
    gl.readBuffer(gl.NONE);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  get ok(): boolean {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.fbo);
    const s = gl.checkFramebufferStatus(gl.FRAMEBUFFER);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    return s === gl.FRAMEBUFFER_COMPLETE;
  }

  /**
   * Пересчитать матрицы. (wx, wy, wz) — центр в мировых координатах, (ox, oz) — начало рендера,
   * L — направление НА источник (нормализованное).
   */
  update(wx: number, wy: number, wz: number, ox: number, oz: number, L: readonly number[], radius: number, depth: number) {
    this.radius = radius;
    // Базис источника: f смотрит от источника на сцену
    const fx = -L[0],
      fy = -L[1],
      fz = -L[2];
    let ux = 0,
      uy = 1,
      uz = 0;
    if (Math.abs(fy) > 0.99) {
      uy = 0;
      uz = 1;
    }
    // r = normalize(cross(f, up))
    let rx = fy * uz - fz * uy,
      ry = fz * ux - fx * uz,
      rz = fx * uy - fy * ux;
    const rl = Math.hypot(rx, ry, rz) || 1;
    rx /= rl;
    ry /= rl;
    rz /= rl;
    // u = cross(r, f)
    const vx = ry * fz - rz * fy,
      vy = rz * fx - rx * fz,
      vz = rx * fy - ry * fx;
    const texel = (radius * 2) / this.size;
    this.texelWorld = texel;
    // Привязка центра к сетке текселей в мировых координатах
    let cr = wx * rx + wy * ry + wz * rz;
    let cu = wx * vx + wy * vy + wz * vz;
    const cf = wx * fx + wy * fy + wz * fz;
    cr = Math.floor(cr / texel) * texel;
    cu = Math.floor(cu / texel) * texel;
    this.cx = wx;
    this.cz = wz;
    // Смещение начала рендера в базисе источника
    const or = ox * rx + oz * rz,
      ou = ox * vx + oz * vz,
      of = ox * fx + oz * fz;
    // Пространство источника: x = (dot(p, r) + or - cr) / R, y = (dot(p, u) + ou - cu) / R,
    // z = (dot(p, f) + of - cf) / depth (−1..1)
    const m = this.viewProj;
    const sx = 1 / radius,
      sz = 1 / depth;
    // Столбцы (column-major)
    m[0] = rx * sx;
    m[1] = vx * sx;
    m[2] = fx * sz;
    m[3] = 0;
    m[4] = ry * sx;
    m[5] = vy * sx;
    m[6] = fy * sz;
    m[7] = 0;
    m[8] = rz * sx;
    m[9] = vz * sx;
    m[10] = fz * sz;
    m[11] = 0;
    m[12] = (or - cr) * sx;
    m[13] = (ou - cu) * sx;
    m[14] = (of - cf) * sz;
    m[15] = 1;
    // В [0..1]: 0.5 * m + 0.5
    const s = this.shadowMat;
    for (let c = 0; c < 4; c++) {
      const w = m[c * 4 + 3];
      s[c * 4] = m[c * 4] * 0.5 + w * 0.5;
      s[c * 4 + 1] = m[c * 4 + 1] * 0.5 + w * 0.5;
      s[c * 4 + 2] = m[c * 4 + 2] * 0.5 + w * 0.5;
      s[c * 4 + 3] = w;
    }
  }

  begin() {
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.fbo);
    gl.viewport(0, 0, this.size, this.size);
    gl.depthMask(true);
    gl.clear(gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.disable(gl.BLEND);
    gl.enable(gl.POLYGON_OFFSET_FILL);
    gl.polygonOffset(1.6, 3.0);
  }

  end() {
    const gl = this.gl;
    gl.disable(gl.POLYGON_OFFSET_FILL);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  }

  dispose() {
    this.gl.deleteFramebuffer(this.fbo);
    this.gl.deleteTexture(this.tex);
  }
}
