/** Общие компоненты интерфейса. */
import { observer } from "mobx-react-lite";
import type { ReactNode } from "react";
import { tr, type Txt } from "../core/i18n";
import { fmtNum } from "../core/format";
import { audio } from "../audio/audio";
import { affixText, RARITY_COLORS, RARITY_NAMES, SLOT_NAMES, type Item } from "../game/items";
import { Glyph, hex } from "./icons";

export function click(fn: () => void) {
  return () => {
    audio.unlock();
    audio.play("click");
    fn();
  };
}

export const Btn = ({ children, onClick, kind = "normal", disabled, title, small, wide }: { children: ReactNode; onClick?: () => void; kind?: "normal" | "primary" | "danger" | "ghost"; disabled?: boolean; title?: string; small?: boolean; wide?: boolean }) => (
  <button className={`btn btn-${kind}${small ? " btn-small" : ""}${wide ? " btn-wide" : ""}`} disabled={disabled} title={title} onClick={onClick ? click(onClick) : undefined}>
    {children}
  </button>
);

export const Panel = observer(({ title, onClose, children, wide, className }: { title: Txt | string; onClose: () => void; children: ReactNode; wide?: boolean; className?: string }) => (
  <div className="panel-backdrop" onPointerDown={(e) => e.target === e.currentTarget && onClose()}>
    <div className={`panel${wide ? " panel-wide" : ""} ${className ?? ""}`}>
      <div className="panel-head">
        <div className="panel-title">{typeof title === "string" ? title : tr(title)}</div>
        <button className="icon-btn" onClick={click(onClose)} aria-label="close">
          <Glyph name="close" size={22} />
        </button>
      </div>
      <div className="panel-body">{children}</div>
    </div>
  </div>
));

export const Bar = ({ value, max, color, label, height = 14, secondary, secondaryColor, glow }: { value: number; max: number; color: string; label?: string; height?: number; secondary?: number; secondaryColor?: string; glow?: boolean }) => {
  const f = max > 0 ? Math.max(0, Math.min(1, value / max)) : 0;
  const s = secondary && max > 0 ? Math.max(0, Math.min(1, secondary / max)) : 0;
  return (
    <div className={`bar${glow && f < 1 ? " regen" : ""}`} style={{ height }}>
      <div className="bar-fill" style={{ width: `${f * 100}%`, background: color }} />
      {s > 0 && <div className="bar-fill bar-secondary" style={{ width: `${s * 100}%`, background: secondaryColor ?? "#9ad0ff" }} />}
      {label && <div className="bar-label">{label}</div>}
    </div>
  );
};

export const ItemIcon = ({ item, size = 44, onClick, selected }: { item: Item | null | undefined; size?: number; onClick?: () => void; selected?: boolean }) => (
  <div
    className={`item-icon${selected ? " selected" : ""}${item ? "" : " empty"}`}
    style={{ width: size, height: size, borderColor: item ? hex(RARITY_COLORS[item.rarity]) : undefined, boxShadow: item && item.rarity >= 3 ? `0 0 10px ${hex(RARITY_COLORS[item.rarity], 0.6)} inset` : undefined }}
    onClick={onClick}
  >
    {item && <span style={{ fontSize: size * 0.55 }}>{item.icon}</span>}
    {item?.stack && item.stack > 1 ? <span className="item-stack">{item.stack}</span> : null}
  </div>
);

export const ItemCard = observer(({ item, compare, children }: { item: Item; compare?: Item | null; children?: ReactNode }) => {
  const g = item.gear;
  const color = hex(RARITY_COLORS[item.rarity]);
  const diff = (a?: number, b?: number) => {
    if (a === undefined) return null;
    const d = a - (b ?? 0);
    if (!compare || Math.abs(d) < 0.01) return null;
    return <span className={d > 0 ? "good" : "bad"}> ({d > 0 ? "+" : ""}{fmtNum(d)})</span>;
  };
  return (
    <div className="item-card">
      <div className="item-name" style={{ color }}>
        {item.icon} {tr(item.name)}
      </div>
      <div className="item-sub">
        {tr(RARITY_NAMES[item.rarity])}
        {g ? ` · ${tr(SLOT_NAMES[g.slot])}` : ""} · {tr({ ru: "ур.", en: "lv" })} {item.level}
      </div>
      {g && (
        <div className="item-stats">
          {g.power ? <div>⚔️ {tr({ ru: "Сила", en: "Power" })}: {fmtNum(g.power)}{diff(g.power, compare?.gear?.power)}</div> : null}
          {g.armor ? <div>🛡️ {tr({ ru: "Броня", en: "Armor" })}: {fmtNum(g.armor)}{diff(g.armor, compare?.gear?.armor)}</div> : null}
          {g.hp ? <div>❤️ {tr({ ru: "Здоровье", en: "Health" })}: {fmtNum(g.hp)}{diff(g.hp, compare?.gear?.hp)}</div> : null}
          {g.mp ? <div>💧 {tr({ ru: "Мана", en: "Mana" })}: {fmtNum(g.mp)}</div> : null}
          {g.affixes.map((a, i) => (
            <div key={i} className="affix">
              {tr(affixText(a))}
            </div>
          ))}
          {g.legendary && (
            <div className="legendary">
              ✦ {tr(g.legendary.name)}: {tr(g.legendary.desc)}
            </div>
          )}
        </div>
      )}
      {item.kind === "tome" && <div className="item-stats">{tr({ ru: "Прочитайте, чтобы получить +1 очко навыков.", en: "Read to gain +1 skill point." })}</div>}
      {item.kind === "quest" && <div className="item-stats">{tr({ ru: "Предмет задания.", en: "Quest item." })}</div>}
      <div className="item-value">
        🐟 {fmtNum(Math.max(1, Math.round(item.value / 3)))} {tr({ ru: "(продажа)", en: "(sell)" })}
      </div>
      {children}
    </div>
  );
});

export const T = observer(({ t }: { t: Txt }) => <>{tr(t)}</>);
