/**
 * Процедурные кошки: скелет, IK-лапы, хвост-цепочка, голова с ушами/усами/глазами,
 * шапки и парящее оружие. Всё рисуется инстансами 6 примитивов (≈6 draw calls на всех кошек).
 */
import { clamp, clamp01, damp, dampAngle, lerp, smoothstep, wrapAngle } from "../core/math";
import { fromTYS, mat4, multiply, rotateX, rotateY, rotateZ, scale, translate, type Mat4 } from "../core/mat4";
import { hashInts, toUnit } from "../core/rng";
import { PATTERN_ID, type CatLook } from "../game/cats/look";
import type { CatInstance } from "./cat-types";
import { boxGeo, coneGeo, cylinderGeo, MeshBuilder, sphereGeo, torusGeo, xf } from "./geometry";
import { ATTR, DynamicBuffer, GpuMesh, type GL, Program } from "./gl";
import type { Renderer, RenderPass } from "./renderer";
import { CAT_FS, CAT_VS } from "./shaders/cat";
import { DEPTH_FS } from "./shaders/common";

const enum Prim {
  SphereHi = 0,
  SphereLo,
  Cyl,
  Cone,
  Box,
  Torus,
  COUNT,
}

const enum Part {
  Body = 0,
  Head = 1,
  Upper = 2,
  Lower = 3,
  Paw = 4,
  Tail = 5,
  Ear = 6,
  Eye = 7,
  Nose = 8,
  Muzzle = 9,
  Whisker = 10,
  Acc = 11,
  Metal = 12,
  Glow = 13,
  Mane = 14,
  Chest = 16,
  Wood = 17,
}

const INST = 24;

interface Batch {
  mesh: GpuMesh;
  buf: DynamicBuffer;
  data: Float32Array;
  count: number;
  /** Данные кадра уже загружены в буфер. */
  uploaded: boolean;
}

interface Mem {
  phase: number;
  blink: number;
  nextBlink: number;
  ear: number;
  nextEar: number;
  earSide: number;
  headYaw: number;
  headPitch: number;
  tilt: number;
  lookTimer: number;
  lookYaw: number;
  lookPitch: number;
  lookTilt: number;
  speed: number;
  seen: number;
  seed: number;
}

// Временные матрицы
const ROOT = mat4();
const BODY = mat4();
const HEAD = mat4();
const WEAP = mat4();
const T0 = mat4();
const T1 = mat4();
const T2 = mat4();
const P3 = [0, 0, 0];

function rgb(hex: number): [number, number, number] {
  return [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
}

const bell = (u: number, a: number, b: number) => {
  if (u <= a || u >= b) return 0;
  const t = (u - a) / (b - a);
  return Math.sin(t * Math.PI);
};
const seg = (u: number, a: number, b: number) => clamp01((u - a) / (b - a));

/** Матрица цилиндра от точки A до B радиуса r (в локальной системе). */
function segMatrix(out: Mat4, ax: number, ay: number, az: number, bx: number, by: number, bz: number, r: number): Mat4 {
  let yx = bx - ax,
    yy = by - ay,
    yz = bz - az;
  const len = Math.hypot(yx, yy, yz) || 1e-4;
  yx /= len;
  yy /= len;
  yz /= len;
  // x = normalize(cross(y, ref))
  let rx = 1,
    ry = 0,
    rz = 0;
  if (Math.abs(yx) > 0.9) {
    rx = 0;
    rz = 1;
  }
  let xx = yy * rz - yz * ry,
    xy = yz * rx - yx * rz,
    xz = yx * ry - yy * rx;
  const xl = Math.hypot(xx, xy, xz) || 1;
  xx /= xl;
  xy /= xl;
  xz /= xl;
  const zx = xy * yz - xz * yy,
    zy = xz * yx - xx * yz,
    zz = xx * yy - xy * yx;
  out[0] = xx * r;
  out[1] = xy * r;
  out[2] = xz * r;
  out[3] = 0;
  out[4] = yx * len;
  out[5] = yy * len;
  out[6] = yz * len;
  out[7] = 0;
  out[8] = zx * r;
  out[9] = zy * r;
  out[10] = zz * r;
  out[11] = 0;
  out[12] = ax;
  out[13] = ay;
  out[14] = az;
  out[15] = 1;
  return out;
}

function xformPoint(m: Mat4, x: number, y: number, z: number, out: number[]) {
  out[0] = m[0] * x + m[4] * y + m[8] * z + m[12];
  out[1] = m[1] * x + m[5] * y + m[9] * z + m[13];
  out[2] = m[2] * x + m[6] * y + m[10] * z + m[14];
  return out;
}

/** 2-звенная IK в плоскости (y,z): от плеча P к цели F; bendSign: +1 колено вперёд, -1 назад. */
function ik2(py: number, pz: number, fy: number, fz: number, a: number, b: number, bendSign: number, out: number[]) {
  let dy = fy - py,
    dz = fz - pz;
  let d = Math.hypot(dy, dz);
  const maxD = (a + b) * 0.999;
  if (d > maxD) {
    dy *= maxD / d;
    dz *= maxD / d;
    d = maxD;
  }
  if (d < 1e-4) d = 1e-4;
  const cosA = clamp((a * a + d * d - b * b) / (2 * a * d), -1, 1);
  const ang = Math.acos(cosA);
  const base = Math.atan2(dz, dy);
  const t = base + ang * bendSign;
  out[0] = py + Math.cos(t) * a; // колено y
  out[1] = pz + Math.sin(t) * a; // колено z
  out[2] = py + dy;
  out[3] = pz + dz;
}

export class CatRenderer implements RenderPass {
  readonly prog: Program;
  readonly progDepth: Program;
  private opaqueB: Batch[] = [];
  private transB: Batch[] = [];
  private mem = new Map<number, Mem>();
  private frame = 0;
  private cur!: Batch[];
  // Текущие параметры кошки
  private cA = 1;
  private cFlash = 0;
  private tintRGB: [number, number, number] = [1, 1, 1];
  private tintAmt = 0;
  private ox = 0;
  private oz = 0;
  count = 0;
  time = 0;

  constructor(readonly gl: GL) {
    this.prog = new Program(gl, CAT_VS, CAT_FS, "cat");
    this.progDepth = new Program(gl, CAT_VS, DEPTH_FS, "cat-depth");
    const geos = [sphereGeo(16, 12), sphereGeo(8, 6), cylinderGeo(8, 1, 1), coneGeo(8), boxGeo(), torusGeo(1, 0.18, 16, 6)];
    for (const g of geos) {
      const b = new MeshBuilder().add(g, xf(), 0xffffff).pack();
      this.opaqueB.push(this.makeBatch(b));
      this.transB.push(this.makeBatch(b));
    }
  }

  private makeBatch(geo: ReturnType<MeshBuilder["pack"]>): Batch {
    const gl = this.gl;
    const buf = new DynamicBuffer(gl);
    const mesh = new GpuMesh(gl, geo, (gl) => {
      gl.bindBuffer(gl.ARRAY_BUFFER, buf.buffer);
      gl.bufferData(gl.ARRAY_BUFFER, 96, gl.DYNAMIC_DRAW);
      const stride = INST * 4;
      for (let i = 0; i < 6; i++) {
        gl.enableVertexAttribArray(ATTR.i0 + i);
        gl.vertexAttribPointer(ATTR.i0 + i, 4, gl.FLOAT, false, stride, i * 16);
        gl.vertexAttribDivisor(ATTR.i0 + i, 1);
      }
    });
    return { mesh, buf, data: new Float32Array(512 * INST), count: 0, uploaded: false };
  }

  begin(ox: number, oz: number, dt: number) {
    this.ox = ox;
    this.oz = oz;
    this.frame++;
    this.time += dt;
    for (const b of this.opaqueB) {
      b.count = 0;
      b.uploaded = false;
    }
    for (const b of this.transB) {
      b.count = 0;
      b.uploaded = false;
    }
    this.count = 0;
    if (this.frame % 120 === 0) {
      for (const [id, m] of this.mem) if (this.frame - m.seen > 600) this.mem.delete(id);
    }
  }

  private put(prim: Prim, m: Mat4, colA: [number, number, number], part: number, colB: [number, number, number], pat: number, seed: number, em: number) {
    const batch = this.cur[prim];
    if ((batch.count + 1) * INST > batch.data.length) {
      const nd = new Float32Array(batch.data.length * 2);
      nd.set(batch.data);
      batch.data = nd;
    }
    const d = batch.data;
    const o = batch.count * INST;
    d[o] = m[0];
    d[o + 1] = m[4];
    d[o + 2] = m[8];
    d[o + 3] = m[12];
    d[o + 4] = m[1];
    d[o + 5] = m[5];
    d[o + 6] = m[9];
    d[o + 7] = m[13];
    d[o + 8] = m[2];
    d[o + 9] = m[6];
    d[o + 10] = m[10];
    d[o + 11] = m[14];
    const ta = this.tintAmt,
      t = this.tintRGB;
    d[o + 12] = lerp(colA[0], t[0], ta);
    d[o + 13] = lerp(colA[1], t[1], ta);
    d[o + 14] = lerp(colA[2], t[2], ta);
    d[o + 15] = part;
    d[o + 16] = lerp(colB[0], t[0], ta);
    d[o + 17] = lerp(colB[1], t[1], ta);
    d[o + 18] = lerp(colB[2], t[2], ta);
    d[o + 19] = pat;
    d[o + 20] = seed;
    d[o + 21] = em + ta * 0.3;
    d[o + 22] = this.cA;
    d[o + 23] = this.cFlash;
    batch.count++;
    this.count++;
  }

  private getMem(id: number): Mem {
    let m = this.mem.get(id);
    if (!m) {
      const s = toUnit(hashInts(id, 99));
      m = {
        phase: s * 6,
        blink: 0,
        nextBlink: 1 + s * 4,
        ear: 0,
        nextEar: 2 + s * 5,
        earSide: 1,
        headYaw: 0,
        headPitch: 0,
        tilt: 0,
        lookTimer: s * 3,
        lookYaw: 0,
        lookPitch: 0,
        lookTilt: 0,
        speed: 0,
        seen: this.frame,
        seed: s,
      };
      this.mem.set(id, m);
    }
    m.seen = this.frame;
    return m;
  }

  /** Добавить кошку в кадр. camDist — расстояние до камеры (для LOD). */
  add(ci: CatInstance, dt: number, camDist: number) {
    const L: CatLook = ci.look;
    const m = this.getMem(ci.id);
    const time = this.time;
    const far = camDist > 32;
    const veryFar = camDist > 70;
    const SPH = far ? Prim.SphereLo : Prim.SphereHi;
    this.cA = clamp01(ci.alpha * (L.alpha ?? 1));
    this.cur = this.cA < 0.99 ? this.transB : this.opaqueB;
    this.cFlash = ci.flash;
    this.tintRGB = rgb(ci.tint);
    this.tintAmt = ci.tintAmt;

    const S = L.size * ci.scale;
    const bulk = L.bulk;
    const legH = 0.3 * L.legLen;
    const rxB = 0.235 * bulk,
      ryB = 0.215 * bulk,
      rzB = 0.41;
    const hr = 0.235 * L.headSize;
    const bodyY0 = legH + 0.17 * bulk;
    const seed = m.seed;

    // ── Локомоция ──
    m.speed = damp(m.speed, ci.speed, 10, dt);
    const sp = m.speed;
    const alive = ci.state === "alive" || ci.state === "swim" || ci.state === "climb";
    const walk = alive ? smoothstep(0.05, 1.2, sp) : 0;
    const run = alive ? smoothstep(4.0, 6.5, sp) : 0;
    m.phase += (dt * sp) / (0.55 * L.legLen * S);
    const ph = m.phase;
    let bob = 0,
      pitch = 0,
      roll = 0,
      lower = 0,
      sitK = 0,
      stretch = 1,
      squash = 1,
      yawOff = 0,
      lift = 0,
      pivotZ = 0,
      climbK = 0;
    let headYawT = 0,
      headPitchT = 0,
      headRollT = 0,
      neckExt = 0;
    let tailUp = lerp(0.3, 0.55, walk),
      tailCurl = 0.1,
      tailWave = lerp(0.3, 0.15, walk),
      tailFreq = 1.4,
      tailSide = 0,
      tailPuff = 1;
    let earBack = 0,
      blink = 0;
    const stride = 0.14 * walk + 0.1 * run;
    const offs = [0, Math.PI, Math.PI, 0];
    const offsRun = [0, 0.55, Math.PI, Math.PI + 0.55];
    const feet: { dy: number; dz: number; free: boolean; fx: number; fy: number; fz: number }[] = [];
    for (let i = 0; i < 4; i++) {
      const o = lerp(offs[i], offsRun[i], run);
      const a = ph + o;
      feet.push({
        dy: Math.max(0, Math.cos(a)) * (0.07 + 0.07 * run) * walk,
        dz: Math.sin(a) * stride,
        free: false,
        fx: 0,
        fy: 0,
        fz: 0,
      });
    }
    bob = Math.abs(Math.sin(ph)) * 0.02 * walk * (1 - run) + Math.sin(ph * 2) * 0.035 * run;
    pitch += Math.sin(ph + 1.2) * 0.08 * run;
    tailUp = lerp(tailUp, 0.1, run);
    squash = 1 + Math.sin(time * 2.3 + seed * 9) * 0.012 * (1 - walk);

    // ── Взгляд, моргание, уши ──
    m.lookTimer -= dt;
    if (m.lookTimer <= 0) {
      m.lookTimer = 1.8 + toUnit(hashInts(ci.id, Math.floor(time * 3))) * 3.5;
      const r1 = toUnit(hashInts(ci.id, Math.floor(time * 7), 1));
      const r2 = toUnit(hashInts(ci.id, Math.floor(time * 7), 2));
      m.lookYaw = (r1 - 0.5) * 1.1;
      m.lookPitch = (r2 - 0.4) * 0.4;
      m.lookTilt = r1 > 0.75 ? (r2 - 0.5) * 0.6 : 0;
    }
    if (ci.lookX !== undefined && ci.lookZ !== undefined) {
      const want = Math.atan2(ci.lookX - ci.x, ci.lookZ - ci.z);
      headYawT = clamp(wrapAngle(want - ci.yaw), -0.9, 0.9);
    } else if (walk < 0.5) {
      headYawT = m.lookYaw;
      headPitchT = m.lookPitch;
      headRollT = m.lookTilt;
    }
    m.nextBlink -= dt;
    if (m.nextBlink <= 0) {
      m.blink = 0.14;
      m.nextBlink = 2 + toUnit(hashInts(ci.id, Math.floor(time))) * 4;
    }
    if (m.blink > 0) {
      m.blink -= dt;
      blink = 1;
    }
    m.nextEar -= dt;
    if (m.nextEar <= 0) {
      m.ear = 0.25;
      m.earSide = toUnit(hashInts(ci.id, Math.floor(time * 5))) > 0.5 ? 1 : -1;
      m.nextEar = 3 + toUnit(hashInts(ci.id, Math.floor(time * 2), 5)) * 6;
    }
    let earTwitch = 0;
    if (m.ear > 0) {
      m.ear -= dt;
      earTwitch = Math.sin((m.ear / 0.25) * Math.PI) * 0.7;
    }

    // ── Состояния ──
    const st = ci.stateT;
    switch (ci.state) {
      case "sit":
        sitK = 1;
        tailUp = -0.35;
        tailSide = 0.9;
        tailWave = 0.1;
        break;
      case "loaf":
      case "sleep":
        lower = legH * 0.95;
        tailUp = -0.25;
        tailSide = 1.4;
        tailCurl = 0.3;
        tailWave = 0.05;
        if (ci.state === "sleep") {
          blink = 1;
          headPitchT = -0.35;
          headRollT = 0.3;
          squash = 1 + Math.sin(time * 1.5) * 0.03;
        } else blink = Math.max(blink, 0.5);
        for (const f of feet) f.dy = 0;
        break;
      case "climb":
        // На стволе: весь кот повёрнут мордой вверх, походка превращается в лазание
        climbK = 1;
        // Тело прижато к коре, лапы обхватывают ствол
        lower = legH * 0.55;
        tailUp = -0.2;
        tailWave = 0.35;
        tailFreq = 1.8;
        tailSide = 0;
        headPitchT = 0.3;
        earBack = 0.15;
        for (const f of feet) f.dz *= 1.4;
        break;
      case "perch":
        // Лежит «буханкой» на кроне, хвост свисает
        lower = legH * 0.95;
        tailUp = -1.35;
        tailSide = 0.25;
        tailCurl = -0.04;
        tailWave = 0.16;
        tailFreq = 0.8;
        blink = Math.max(blink, 0.35);
        headPitchT = -0.12;
        for (const f of feet) f.dy = 0;
        break;
      case "swim":
        lower = legH + 0.05;
        tailUp = 0.05;
        tailWave = 0.5;
        tailFreq = 3;
        headPitchT = 0.35;
        for (let i = 0; i < 4; i++) {
          feet[i].dz = Math.sin(time * 9 + offs[i]) * 0.15;
          feet[i].dy = legH * 0.7 + Math.cos(time * 9 + offs[i]) * 0.06;
        }
        break;
      case "dead": {
        const k = clamp01(st / 0.45);
        roll = k * k * 1.45;
        lower = legH * 0.55 * k;
        tailUp = -0.1;
        tailWave = 0;
        blink = 1;
        earBack = 0.6;
        for (let i = 0; i < 4; i++) {
          feet[i].dz = (i < 2 ? 0.25 : -0.25) * k;
          feet[i].dy = 0.1 * k;
        }
        headPitchT = -0.2;
        break;
      }
    }

    // ── Действия ──
    const u = ci.actionT;
    const B = bodyY0; // для свободных целей в системе тела
    let wX = 0.55,
      wY = bodyY0 + 0.38 + Math.sin(time * 2.2 + seed * 7) * 0.05,
      wZ = 0.0,
      wRx = 0,
      wRy = 0,
      wRz = 0.3;
    if (alive && ci.action) {
      switch (ci.action) {
        case "swipe": {
          const wind = seg(u, 0, 0.35),
            strike = seg(u, 0.35, 0.55),
            rec = seg(u, 0.55, 1);
          const f = feet[1];
          f.free = true;
          f.fx = lerp(lerp(0.12, 0.14, wind), lerp(0.14, -0.02, strike), strike > 0 ? 1 : 0);
          f.fy = lerp(lerp(-B + 0.05, 0.12, wind), -B * 0.55, strike) * (1 - rec) + (-B + 0.02) * rec;
          f.fz = lerp(lerp(0.3, 0.32, wind), 0.72, strike) * (1 - rec) + 0.28 * rec;
          pitch -= bell(u, 0.3, 0.7) * 0.15;
          roll += bell(u, 0.2, 0.7) * 0.1;
          headPitchT = -0.2;
          earBack = 0.6;
          wZ = lerp(0.2, 0.55, strike);
          wX = lerp(0.6, -0.4, strike);
          wRy = lerp(-1.0, 1.4, strike);
          wRx = 1.2 * bell(u, 0.2, 0.8);
          break;
        }
        case "doubleSwipe": {
          const first = u < 0.5;
          const uu = first ? u * 2 : (u - 0.5) * 2;
          const f = feet[first ? 1 : 0];
          f.free = true;
          f.fx = (first ? 1 : -1) * lerp(0.14, 0.0, seg(uu, 0.3, 0.6));
          f.fy = lerp(0.1, -B * 0.55, seg(uu, 0.3, 0.6));
          f.fz = lerp(0.3, 0.7, seg(uu, 0.3, 0.6));
          pitch -= 0.1;
          earBack = 0.7;
          wZ = 0.4;
          wX = first ? lerp(0.5, -0.4, uu) : lerp(-0.4, 0.5, uu);
          wRy = first ? lerp(-1, 1.4, uu) : lerp(1.4, -1, uu);
          wRx = 1.1;
          break;
        }
        case "pounce": {
          const crouch = bell(u, 0, 0.4),
            jump = seg(u, 0.3, 0.75),
            land = bell(u, 0.7, 1);
          lower += crouch * 0.14;
          pitch += -crouch * 0.12 + (jump > 0 && jump < 1 ? lerp(0.35, -0.35, jump) : 0);
          lift = Math.sin(jump * Math.PI) * 0.9;
          squash *= 1 - land * 0.15;
          if (jump > 0 && jump < 1) {
            feet[0].dz = feet[1].dz = 0.3;
            feet[0].dy = feet[1].dy = 0.2;
            feet[2].dz = feet[3].dz = -0.3;
            feet[2].dy = feet[3].dy = 0.15;
          }
          tailUp = 0.3;
          earBack = 0.5;
          wZ = lerp(0, 0.6, jump);
          wRx = 1.3 * jump;
          break;
        }
        case "bite":
          neckExt = bell(u, 0.2, 0.7);
          headPitchT = -0.35 * bell(u, 0.1, 0.8);
          pitch -= bell(u, 0.2, 0.7) * 0.12;
          earBack = 0.8;
          break;
        case "spin":
          yawOff = smoothstep(0.05, 0.85, u) * Math.PI * 2;
          tailUp = 0.05;
          tailWave = 0;
          for (let i = 0; i < 4; i++) feet[i].dz += (i < 2 ? 0.1 : -0.1) * bell(u, 0, 1);
          lift = bell(u, 0.1, 0.9) * 0.12;
          wX = 0.75;
          wRz = 1.5;
          break;
        case "slam": {
          const up = seg(u, 0, 0.45),
            down = seg(u, 0.45, 0.58);
          pivotZ = -0.28;
          pitch += up * 0.95 * (1 - down) - down * 0.12 * (1 - seg(u, 0.7, 1));
          for (const i of [0, 1]) {
            const f = feet[i];
            if (u < 0.5) {
              f.free = true;
              f.fx = i === 0 ? -0.13 : 0.13;
              f.fy = lerp(-B + 0.05, 0.15, up);
              f.fz = lerp(0.3, 0.42, up);
            } else f.dz = 0.18 * (1 - seg(u, 0.6, 1));
          }
          squash *= 1 - bell(u, 0.5, 0.75) * 0.15;
          earBack = 0.8;
          tailPuff = 1.3;
          wY += up * 0.6 * (1 - down);
          wZ = 0.5 * down;
          wRx = lerp(-0.8, 1.6, down) * (1 - seg(u, 0.7, 1));
          break;
        }
        case "raise": {
          const k = bell(u, 0, 1) > 0 ? Math.min(1, bell(u, 0, 1) * 1.6) : 0;
          sitK = Math.max(sitK, k * 0.85);
          for (const i of [0, 1]) {
            const f = feet[i];
            f.free = true;
            f.fx = i === 0 ? -0.12 : 0.12;
            f.fy = lerp(-B + 0.05, 0.42, k);
            f.fz = lerp(0.3, 0.3, k);
          }
          headPitchT = 0.35 * k;
          wY += 0.5 * k;
          wX = lerp(0.55, 0.25, k);
          wZ = 0.25 * k;
          wRz = lerp(0.3, 0, k);
          break;
        }
        case "channel": {
          sitK = Math.max(sitK, 0.7);
          const sway = Math.sin(time * 5) * 0.03;
          for (const i of [0, 1]) {
            const f = feet[i];
            f.free = true;
            f.fx = i === 0 ? -0.1 : 0.1;
            f.fy = 0.2 + sway;
            f.fz = 0.5;
          }
          headPitchT = 0.15;
          wX = 0;
          wZ = 0.75;
          wY = bodyY0 + 0.45;
          wRx = 1.4;
          break;
        }
        case "point": {
          const k = Math.min(1, bell(u, 0, 1) * 1.8);
          const f = feet[1];
          f.free = true;
          f.fx = 0.1;
          f.fy = lerp(-B + 0.05, 0.1, k);
          f.fz = lerp(0.3, 0.75, k);
          wZ = 0.55 * k;
          wX = lerp(0.55, 0.2, k);
          wRx = 1.4 * k;
          break;
        }
        case "throw": {
          const wind = seg(u, 0, 0.4),
            rel = seg(u, 0.4, 0.6);
          yawOff = -0.45 * wind * (1 - rel) + 0.3 * rel * (1 - seg(u, 0.6, 1));
          const f = feet[1];
          f.free = true;
          f.fx = 0.14;
          f.fy = lerp(lerp(-B + 0.05, 0.25, wind), 0.1, rel);
          f.fz = lerp(lerp(0.3, 0.0, wind), 0.75, rel);
          wZ = lerp(-0.3, 0.8, rel);
          wRx = 1.2 * rel;
          break;
        }
        case "roar":
        case "meow": {
          const k = bell(u, 0, 1);
          headPitchT = 0.45 * k;
          neckExt = 0.4 * k;
          pitch += (ci.action === "roar" ? -0.12 : 0.05) * k;
          earBack = ci.action === "roar" ? 0.9 * k : 0;
          squash *= 1 + 0.06 * k;
          tailPuff = ci.action === "roar" ? 1 + 0.5 * k : 1;
          break;
        }
        case "tailWhip":
          yawOff = Math.sin(u * Math.PI) * 2.6;
          tailSide = Math.sin(u * Math.PI * 2) * 1.4;
          tailUp = 0.1;
          tailWave = 0;
          break;
        case "backflip":
          pitch += u * Math.PI * 2;
          lift = Math.sin(u * Math.PI) * 1.2;
          for (const f of feet) {
            f.dy = 0.25 * bell(u, 0, 1);
          }
          break;
        case "stomp": {
          const a = Math.abs(Math.sin(u * Math.PI * 2));
          feet[0].dy = feet[1].dy = a * 0.28;
          pitch += a * 0.25;
          pivotZ = -0.28;
          squash *= 1 - (1 - a) * bell(u, 0.2, 1) * 0.08;
          earBack = 0.5;
          break;
        }
        case "dash":
          stretch = 1 + 0.25 * bell(u, 0, 1);
          lower += 0.08 * bell(u, 0, 1);
          feet[0].dz = feet[1].dz = 0.28;
          feet[2].dz = feet[3].dz = -0.28;
          feet[0].dy = feet[1].dy = 0.12;
          tailUp = 0.05;
          tailWave = 0;
          earBack = 1;
          wZ = 0.5;
          wRx = 1.4;
          break;
        case "summon": {
          const k = Math.min(1, bell(u, 0, 1) * 2);
          sitK = Math.max(sitK, 0.85 * k);
          for (const i of [0, 1]) {
            const f = feet[i];
            f.free = true;
            f.fx = i === 0 ? -0.05 : 0.05;
            f.fy = lerp(-B + 0.05, 0.45, k);
            f.fz = 0.35;
          }
          yawOff = Math.sin(u * Math.PI) * 0.5;
          headPitchT = 0.4 * k;
          wY += 0.7 * k;
          wX = 0;
          wZ = 0.3;
          break;
        }
        case "pray": {
          const k = Math.min(1, bell(u, 0, 1) * 2);
          sitK = Math.max(sitK, k);
          for (const i of [0, 1]) {
            const f = feet[i];
            f.free = true;
            f.fx = i === 0 ? -0.03 : 0.03;
            f.fy = lerp(-B + 0.05, 0.15, k);
            f.fz = 0.42;
          }
          headPitchT = -0.4 * k;
          wY += 0.4 * k;
          wX = 0;
          wZ = 0.45;
          break;
        }
        case "hiss": {
          const k = Math.min(1, bell(u, 0, 1) * 2.5);
          lower -= 0.09 * k;
          earBack = k;
          tailPuff = 1 + 0.7 * k;
          tailUp = lerp(tailUp, 1.4, k);
          headPitchT = -0.15 * k;
          yawOff = 0.35 * k;
          break;
        }
        case "hit": {
          const k = bell(u, 0, 1);
          pitch += 0.25 * k;
          squash *= 1 - 0.1 * k;
          earBack = 0.9 * k;
          yawOff = Math.sin(u * 30) * 0.05 * k;
          break;
        }
        case "jump":
          lift = Math.sin(u * Math.PI) * 0.8;
          for (const f of feet) f.dy = 0.18 * bell(u, 0, 1);
          break;
        case "wave": {
          const f = feet[1];
          f.free = true;
          f.fx = 0.18;
          f.fy = 0.45;
          f.fz = 0.35 + Math.sin(u * Math.PI * 6) * 0.1;
          sitK = Math.max(sitK, 0.6);
          break;
        }
        case "shoot": {
          const k = Math.min(1, bell(u, 0, 1) * 2);
          sitK = Math.max(sitK, 0.35 * k);
          wX = lerp(0.55, 0.05, k);
          wZ = lerp(0, 0.6, k);
          wY = bodyY0 + 0.3;
          wRy = (Math.PI / 2) * k;
          wRz = 0;
          const f = feet[1];
          f.free = true;
          f.fx = 0.1;
          f.fy = 0.1;
          f.fz = lerp(0.6, 0.2, seg(u, 0.2, 0.6));
          break;
        }
        case "stab": {
          const k = bell(u, 0.2, 0.7);
          pitch -= 0.15 * k;
          stretch = 1 + 0.1 * k;
          wZ = lerp(0.1, 0.9, k);
          wX = lerp(0.5, 0.1, k);
          wRx = 1.5;
          earBack = 0.7;
          break;
        }
      }
    }

    // Сидячая поза: таз опущен, тело поднято
    if (sitK > 0) {
      pivotZ = lerp(pivotZ, -0.28, sitK);
      lower += legH * 0.55 * sitK;
      pitch += 0.72 * sitK;
      feet[2].dz = lerp(feet[2].dz, 0.28, sitK);
      feet[3].dz = lerp(feet[3].dz, 0.28, sitK);
      feet[2].dy = feet[3].dy = feet[2].dy * (1 - sitK);
      if (!feet[0].free) feet[0].dz = lerp(feet[0].dz, 0.02, sitK);
      if (!feet[1].free) feet[1].dz = lerp(feet[1].dz, 0.02, sitK);
      headPitchT -= 0.55 * sitK;
    }

    m.headYaw = dampAngle(m.headYaw, headYawT, 5, dt);
    m.headPitch = damp(m.headPitch, headPitchT, 6, dt);
    m.tilt = damp(m.tilt, headRollT, 4, dt);

    // ── Матрицы ──
    fromTYS(ROOT, ci.x - this.ox, ci.y + lift * S, ci.z - this.oz, ci.yaw + yawOff, S);
    if (climbK > 0) rotateX(ROOT, ROOT, (-Math.PI / 2) * climbK);
    // Тело
    const bodyY = bodyY0 - lower + bob;
    T0.fill(0);
    T0[0] = T0[5] = T0[10] = T0[15] = 1;
    translate(T0, T0, 0, bodyY, pivotZ);
    rotateX(T0, T0, -pitch);
    rotateZ(T0, T0, roll);
    translate(T0, T0, 0, 0, -pivotZ);
    multiply(BODY, ROOT, T0);

    const fur = rgb(L.fur),
      fur2 = rgb(L.fur2);
    const pat = PATTERN_ID[L.pattern];
    const bodyPart = (prim: Prim, mm: Mat4, part: Part, s2: number) => this.put(prim, mm, fur, part, fur2, pat, seed + s2, 0);

    // Туловище: эллипсоид + грудь + таз
    scale(T1, BODY, rxB, ryB * squash, rzB * stretch);
    bodyPart(SPH, T1, Part.Body, 0);
    translate(T1, BODY, 0, 0.025 * bulk, 0.22 * stretch);
    scale(T1, T1, 0.245 * bulk, 0.235 * bulk * squash, 0.24);
    bodyPart(SPH, T1, Part.Chest, 0.1);
    translate(T1, BODY, 0, 0.015, -0.23 * stretch);
    scale(T1, T1, 0.245 * bulk, 0.225 * bulk * squash, 0.24);
    bodyPart(SPH, T1, Part.Chest, 0.2);

    // Лапы (IK)
    const upperLen = legH * 0.56,
      lowerLen = legH * 0.54;
    const rUp = 0.075 * Math.sqrt(bulk),
      rLo = 0.062 * Math.sqrt(bulk);
    const legAttach: [number, number, number][] = [
      [-0.12 * bulk, -0.09, 0.24 * stretch],
      [0.12 * bulk, -0.09, 0.24 * stretch],
      [-0.13 * bulk, -0.08, -0.25 * stretch],
      [0.13 * bulk, -0.08, -0.25 * stretch],
    ];
    const kneeOut = [0, 0, 0, 0];
    const legScale = ci.state === "loaf" || ci.state === "sleep" || ci.state === "perch" ? 0.35 : 1;
    if (!veryFar || true) {
      for (let i = 0; i < 4; i++) {
        const a = legAttach[i];
        // Плечо в пространстве кошки (T0 = тело без корня)
        xformPoint(T0, a[0], a[1], a[2], P3);
        const px = P3[0],
          py = P3[1],
          pz = P3[2];
        const f = feet[i];
        let fx: number, fy: number, fz: number;
        if (f.free) {
          xformPoint(T0, f.fx, f.fy, f.fz, P3);
          fx = P3[0];
          fy = P3[1];
          fz = P3[2];
        } else {
          fx = a[0] * (1.05 + 0.8 * climbK);
          fy = f.dy - 0.05 * climbK;
          fz = a[2] + f.dz;
          if (roll > 0.2) {
            // Падение на бок — лапы вытягиваются в сторону
            xformPoint(T0, a[0] + 0.25 * Math.sign(a[0] || 1), a[1] - 0.2, a[2] + f.dz, P3);
            fx = P3[0];
            fy = P3[1];
            fz = P3[2];
          }
        }
        ik2(py, pz, fy, fz, upperLen * legScale, lowerLen * legScale, i < 2 ? -1 : 1, kneeOut);
        const kx = (px + fx) * 0.5;
        const [ky, kz, ey, ez] = kneeOut;
        segMatrix(T1, px, py, pz, kx, ky, kz, rUp);
        multiply(T2, ROOT, T1);
        bodyPart(Prim.Cyl, T2, Part.Upper, 1 + i);
        // сустав
        translate(T1, ROOT, kx, ky, kz);
        scale(T1, T1, rLo * 1.1, rLo * 1.1, rLo * 1.1);
        bodyPart(SPH, T1, Part.Lower, 1 + i);
        segMatrix(T1, kx, ky, kz, fx, ey, ez, rLo);
        multiply(T2, ROOT, T1);
        bodyPart(Prim.Cyl, T2, Part.Lower, 5 + i);
        // Лапка
        translate(T1, ROOT, fx, ey + 0.03, ez + 0.025);
        scale(T1, T1, 0.078 * Math.sqrt(bulk), 0.052, 0.1);
        bodyPart(SPH, T1, Part.Paw, 9 + i);
      }
    }

    // Хвост
    {
      const nSeg = far ? 5 : 8;
      const segLen = (0.6 * L.tailLen) / nSeg;
      let x = 0,
        y = ryB * 0.35,
        z = -rzB * 0.95 * stretch;
      const fluff = (L.hairless ? 0.55 : 1) * L.tailFluff * tailPuff;
      for (let i = 0; i < nSeg; i++) {
        const k = i / nSeg;
        const ang = tailUp + tailCurl * i + (ci.state === "dead" ? -0.2 : 0);
        const sway = Math.sin(time * tailFreq * 2 - i * 0.55 + seed * 10) * tailWave * k + tailSide * k;
        const dx = Math.sin(sway) * Math.cos(ang);
        const dy = Math.sin(ang);
        const dz = -Math.cos(sway) * Math.cos(ang);
        x += dx * segLen;
        y += dy * segLen;
        z += dz * segLen;
        const r = (0.088 - k * 0.028) * fluff;
        translate(T1, BODY, x, y, z);
        scale(T1, T1, r, r, r * 1.25);
        this.put(SPH, T1, fur, Part.Tail, fur2, pat, seed + 20 + i * 0.37 + (i % 2) * 0.5, 0);
      }
    }

    // Шея и голова
    xformPoint(T0, 0, ryB * 0.55, rzB * 0.78 * stretch, P3);
    T1.fill(0);
    T1[0] = T1[5] = T1[10] = T1[15] = 1;
    translate(T1, T1, P3[0], P3[1], P3[2]);
    rotateZ(T1, T1, roll);
    rotateY(T1, T1, m.headYaw);
    rotateX(T1, T1, -(m.headPitch + pitch * 0.35));
    rotateZ(T1, T1, m.tilt);
    translate(T1, T1, 0, hr * 0.5 + neckExt * 0.04, hr * 0.3 + neckExt * 0.28);
    multiply(HEAD, ROOT, T1);

    // Грива (львы)
    if (L.mane !== undefined) {
      const mc = rgb(L.mane);
      translate(T2, HEAD, 0, -hr * 0.15, -hr * 0.35);
      scale(T2, T2, hr * 1.55, hr * 1.5, hr * 1.1);
      this.put(SPH, T2, mc, Part.Mane, mc, 0, seed, 0);
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI * 2;
        translate(T2, HEAD, Math.cos(a) * hr * 1.1, Math.sin(a) * hr * 1.05 - hr * 0.1, -hr * 0.2);
        scale(T2, T2, hr * 0.55, hr * 0.55, hr * 0.5);
        this.put(SPH, T2, mc, Part.Mane, mc, 0, seed + i, 0);
      }
    }
    // Голова
    scale(T2, HEAD, hr * 1.06, hr * 0.93, hr * 0.96);
    bodyPart(SPH, T2, Part.Head, 30);
    // Щёчки/морда
    for (const s of [-1, 1]) {
      translate(T2, HEAD, s * hr * 0.2, -hr * 0.33, hr * 0.74);
      scale(T2, T2, hr * 0.28, hr * 0.22, hr * 0.24);
      bodyPart(SPH, T2, Part.Muzzle, 31);
    }
    translate(T2, HEAD, 0, -hr * 0.48, hr * 0.66);
    scale(T2, T2, hr * 0.2, hr * 0.14, hr * 0.18);
    bodyPart(SPH, T2, Part.Muzzle, 32);
    // Нос
    const dark = (L.fur & 0xff) + ((L.fur >> 8) & 0xff) + ((L.fur >> 16) & 0xff) < 200;
    const noseCol = rgb(L.hairless ? 0xc87a7a : dark ? 0x4a3a3a : 0xf08a9a);
    if (!far) {
      translate(T2, HEAD, 0, -hr * 0.18, hr * 0.96);
      scale(T2, T2, hr * 0.12, hr * 0.08, hr * 0.07);
      this.put(Prim.SphereLo, T2, noseCol, Part.Nose, noseCol, 0, 0, 0);
    }
    // Глаза
    const eyeCol = rgb(L.glow ?? L.eyes);
    const eyeEm = L.glow !== undefined ? 1.2 : 0.25;
    for (const s of [-1, 1]) {
      translate(T2, HEAD, s * hr * 0.4, hr * 0.1, hr * 0.8);
      rotateY(T2, T2, s * 0.35);
      scale(T2, T2, hr * 0.21, hr * 0.23 * (1 - blink * 0.88), hr * 0.13);
      this.put(SPH, T2, eyeCol, Part.Eye, eyeCol, 0, 0, eyeEm);
    }
    // Уши
    const es = L.earSize * (L.hairless ? 1.2 : 1);
    for (const s of [-1, 1]) {
      const tw = s === m.earSide ? earTwitch : 0;
      translate(T2, HEAD, s * hr * 0.52, hr * 0.62, hr * 0.02);
      rotateZ(T2, T2, -s * (0.32 + earBack * 0.7));
      rotateX(T2, T2, -0.12 - earBack * 0.5 - tw);
      scale(T2, T2, hr * 0.4 * es, hr * 0.78 * es, hr * 0.22 * es);
      bodyPart(Prim.Cone, T2, Part.Ear, 40);
      if (L.tufts && !far) {
        translate(T2, T2, 0, 1.0, 0);
        scale(T2, T2, 0.25, 0.5, 0.4);
        this.put(Prim.Cone, T2, rgb(0x222222), Part.Acc, fur2, 0, 0, 0);
      }
    }
    // Усы
    if (!far && !L.hairless) {
      const wc = rgb(0xf6f4f0);
      for (const s of [-1, 1])
        for (let k = 0; k < 3; k++) {
          segMatrix(T1, s * hr * 0.3, -hr * 0.32 + k * hr * 0.06, hr * 0.84, s * hr * 1.45, -hr * 0.22 + k * hr * 0.14 - 0.02, hr * 0.8 - k * hr * 0.1, 0.004);
          multiply(T2, HEAD, T1);
          this.put(Prim.Cyl, T2, wc, Part.Whisker, wc, 0, 0, 0);
        }
    }
    // Ошейник с колокольчиком
    if (L.collar !== undefined) {
      const cc = rgb(L.collar);
      xformPoint(T0, 0, ryB * 0.62, rzB * 0.8 * stretch, P3);
      translate(T2, ROOT, P3[0], P3[1] + 0.03, P3[2]);
      rotateZ(T2, T2, roll);
      rotateX(T2, T2, 0.95 - pitch * 0.6);
      scale(T2, T2, hr * 0.78, hr * 0.78, hr * 0.78);
      this.put(Prim.Torus, T2, cc, Part.Acc, cc, 0, 0, 0);
      if (L.bell && !far) {
        translate(T2, T2, 0, 0, 1.05);
        scale(T2, T2, 0.28, 0.28, 0.28);
        const gold = rgb(0xf2c84a);
        this.put(Prim.SphereLo, T2, gold, Part.Metal, gold, 0, 0, 0.1);
      }
    }
    // Шапки
    this.hat(L, hr, SPH);
    // Оружие
    if (L.weapon !== "none" && ci.state !== "dead" && ci.state !== "sleep") {
      T1.fill(0);
      T1[0] = T1[5] = T1[10] = T1[15] = 1;
      translate(T1, T1, wX, wY, wZ);
      rotateY(T1, T1, wRy);
      rotateX(T1, T1, wRx);
      rotateZ(T1, T1, wRz);
      multiply(WEAP, ROOT, T1);
      this.weapon(L.weapon, rgb(L.weaponColor), false);
      if (L.offhand) {
        T1.fill(0);
        T1[0] = T1[5] = T1[10] = T1[15] = 1;
        translate(T1, T1, -0.55, bodyY0 + 0.3 + Math.sin(time * 2.1 + 1) * 0.04, 0.05);
        rotateZ(T1, T1, -0.2);
        multiply(WEAP, ROOT, T1);
        this.weapon(L.offhand, rgb(L.weaponColor), true);
      }
    }
  }

  private hat(L: CatLook, hr: number, SPH: Prim) {
    if (L.hat === "none") return;
    const hc = rgb(L.hatColor);
    const gold = rgb(0xf2c84a);
    switch (L.hat) {
      case "wizard":
        translate(T2, HEAD, 0, hr * 0.7, -hr * 0.05);
        scale(T2, T2, hr * 1.25, hr * 0.06, hr * 1.25);
        this.put(Prim.Cyl, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.74, -hr * 0.05);
        rotateX(T2, T2, -0.25);
        scale(T2, T2, hr * 0.62, hr * 2.2, hr * 0.62);
        this.put(Prim.Cone, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.85, -hr * 0.05);
        scale(T2, T2, hr * 0.64, hr * 0.64, hr * 0.64);
        this.put(Prim.Torus, T2, gold, Part.Metal, gold, 0, 0, 0.2);
        break;
      case "helmet":
        translate(T2, HEAD, 0, hr * 0.28, -hr * 0.02);
        scale(T2, T2, hr * 1.12, hr * 0.8, hr * 1.08);
        this.put(SPH, T2, hc, Part.Metal, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.1, hr * 1.02);
        scale(T2, T2, hr * 0.12, hr * 0.5, hr * 0.08);
        this.put(Prim.Box, T2, hc, Part.Metal, hc, 0, 0, 0);
        for (const s of [-1, 1]) {
          translate(T2, HEAD, s * hr * 0.9, hr * 0.5, 0);
          rotateZ(T2, T2, -s * 1.0);
          scale(T2, T2, hr * 0.16, hr * 0.6, hr * 0.16);
          this.put(Prim.Cone, T2, rgb(0xf0e6d0), Part.Acc, hc, 0, 0, 0);
        }
        break;
      case "hood":
        translate(T2, HEAD, 0, hr * 0.15, -hr * 0.28);
        scale(T2, T2, hr * 1.25, hr * 1.2, hr * 1.2);
        this.put(SPH, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, -hr * 0.55, -hr * 0.5);
        scale(T2, T2, hr * 1.4, hr * 1.1, hr * 1.0);
        this.put(Prim.Cone, T2, hc, Part.Acc, hc, 0, 0, 0);
        break;
      case "crown":
        translate(T2, HEAD, 0, hr * 0.75, 0);
        scale(T2, T2, hr * 0.55, hr * 0.25, hr * 0.55);
        this.put(Prim.Cyl, T2, gold, Part.Metal, gold, 0, 0, 0.2);
        for (let i = 0; i < 5; i++) {
          const a = (i / 5) * Math.PI * 2;
          translate(T2, HEAD, Math.sin(a) * hr * 0.5, hr * 0.98, Math.cos(a) * hr * 0.5);
          scale(T2, T2, hr * 0.12, hr * 0.28, hr * 0.12);
          this.put(Prim.Cone, T2, gold, Part.Metal, gold, 0, 0, 0.2);
        }
        translate(T2, HEAD, 0, hr * 0.88, hr * 0.55);
        scale(T2, T2, hr * 0.12, hr * 0.12, hr * 0.08);
        this.put(Prim.SphereLo, T2, rgb(0xff3a5a), Part.Glow, gold, 0, 0, 0.5);
        break;
      case "bandana":
        translate(T2, HEAD, 0, hr * 0.35, 0);
        rotateX(T2, T2, 0.25);
        scale(T2, T2, hr * 1.02, hr * 1.4, hr * 1.02);
        this.put(Prim.Torus, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.3, -hr * 1.0);
        scale(T2, T2, hr * 0.2, hr * 0.2, hr * 0.2);
        this.put(Prim.SphereLo, T2, hc, Part.Acc, hc, 0, 0, 0);
        break;
      case "leaves":
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          translate(T2, HEAD, Math.sin(a) * hr * 0.55, hr * 0.68, Math.cos(a) * hr * 0.55);
          rotateY(T2, T2, a);
          rotateX(T2, T2, 0.7);
          scale(T2, T2, hr * 0.22, hr * 0.55, hr * 0.06);
          this.put(Prim.SphereLo, T2, hc, Part.Acc, hc, 0, 0, 0);
        }
        translate(T2, HEAD, hr * 0.4, hr * 0.8, hr * 0.4);
        scale(T2, T2, hr * 0.13, hr * 0.13, hr * 0.13);
        this.put(Prim.SphereLo, T2, rgb(0xff6a8a), Part.Acc, hc, 0, 0, 0.2);
        break;
      case "halo":
        translate(T2, HEAD, 0, hr * 1.35 + Math.sin(this.time * 2) * hr * 0.06, 0);
        scale(T2, T2, hr * 0.7, hr * 0.7, hr * 0.7);
        this.put(Prim.Torus, T2, hc, Part.Glow, hc, 0, 0, 0.8);
        break;
      case "horns":
        for (const s of [-1, 1]) {
          translate(T2, HEAD, s * hr * 0.35, hr * 0.7, -hr * 0.1);
          rotateZ(T2, T2, -s * 0.5);
          rotateX(T2, T2, -0.5);
          scale(T2, T2, hr * 0.14, hr * 0.7, hr * 0.14);
          this.put(Prim.Cone, T2, hc, Part.Acc, hc, 0, 0, 0);
        }
        break;
      case "feather":
        translate(T2, HEAD, 0, hr * 0.62, -hr * 0.05);
        scale(T2, T2, hr * 0.75, hr * 0.28, hr * 0.8);
        this.put(Prim.Cyl, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, hr * 0.4, hr * 0.85, -hr * 0.3);
        rotateX(T2, T2, -0.9);
        rotateZ(T2, T2, -0.3);
        scale(T2, T2, hr * 0.12, hr * 1.1, hr * 0.03);
        this.put(Prim.SphereLo, T2, rgb(0xd83a3a), Part.Acc, hc, 0, 0, 0);
        break;
      case "pirate":
        translate(T2, HEAD, 0, hr * 0.62, 0);
        scale(T2, T2, hr * 1.3, hr * 0.06, hr * 1.1);
        this.put(Prim.Cyl, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.62, 0);
        scale(T2, T2, hr * 0.7, hr * 0.4, hr * 0.7);
        this.put(Prim.Cyl, T2, hc, Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.85, hr * 0.7);
        scale(T2, T2, hr * 0.14, hr * 0.14, hr * 0.05);
        this.put(Prim.SphereLo, T2, rgb(0xf4f4f4), Part.Acc, hc, 0, 0, 0);
        break;
      case "chef":
        translate(T2, HEAD, 0, hr * 0.6, -hr * 0.05);
        scale(T2, T2, hr * 0.55, hr * 0.6, hr * 0.55);
        this.put(Prim.Cyl, T2, rgb(0xfafafa), Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 1.3, -hr * 0.05);
        scale(T2, T2, hr * 0.75, hr * 0.5, hr * 0.75);
        this.put(Prim.SphereLo, T2, rgb(0xfafafa), Part.Acc, hc, 0, 0, 0);
        break;
      case "straw":
        translate(T2, HEAD, 0, hr * 0.62, 0);
        scale(T2, T2, hr * 1.7, hr * 0.05, hr * 1.7);
        this.put(Prim.Cyl, T2, rgb(0xe8cf7a), Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.62, 0);
        scale(T2, T2, hr * 0.62, hr * 0.38, hr * 0.62);
        this.put(Prim.Cyl, T2, rgb(0xe8cf7a), Part.Acc, hc, 0, 0, 0);
        translate(T2, HEAD, 0, hr * 0.7, 0);
        scale(T2, T2, hr * 0.64, hr * 0.64, hr * 0.64);
        this.put(Prim.Torus, T2, hc, Part.Acc, hc, 0, 0, 0);
        break;
      case "tiara":
        translate(T2, HEAD, 0, hr * 0.62, hr * 0.1);
        rotateX(T2, T2, 0.3);
        scale(T2, T2, hr * 0.8, hr * 0.8, hr * 0.8);
        this.put(Prim.Torus, T2, gold, Part.Metal, gold, 0, 0, 0.2);
        translate(T2, HEAD, 0, hr * 0.8, hr * 0.78);
        scale(T2, T2, hr * 0.13, hr * 0.13, hr * 0.13);
        this.put(Prim.SphereLo, T2, hc, Part.Glow, hc, 0, 0, 0.8);
        break;
    }
  }

  private weapon(kind: string, wc: [number, number, number], off: boolean) {
    const gold = rgb(0xf2c84a),
      wood = rgb(0x7a5236),
      steel = rgb(0xd8e0e8),
      dark = rgb(0x2a2430);
    const W = WEAP;
    const box = (x: number, y: number, z: number, sx: number, sy: number, sz: number, c: [number, number, number], part: Part, em = 0) => {
      translate(T2, W, x, y, z);
      scale(T2, T2, sx, sy, sz);
      this.put(Prim.Box, T2, c, part, c, 0, 0, em);
    };
    const cyl = (x: number, y: number, z: number, r: number, h: number, c: [number, number, number], part: Part, em = 0) => {
      translate(T2, W, x, y, z);
      scale(T2, T2, r, h, r);
      this.put(Prim.Cyl, T2, c, part, c, 0, 0, em);
    };
    const sph = (x: number, y: number, z: number, r: number, c: [number, number, number], part: Part, em = 0) => {
      translate(T2, W, x, y, z);
      scale(T2, T2, r, r, r);
      this.put(Prim.SphereLo, T2, c, part, c, 0, 0, em);
    };
    switch (kind) {
      case "sword":
        box(0, 0.3, 0, 0.07, 0.62, 0.018, wc, Part.Metal);
        translate(T2, W, 0, 0.61, 0);
        scale(T2, T2, 0.05, 0.1, 0.012);
        this.put(Prim.Cone, T2, wc, Part.Metal, wc, 0, 0, 0);
        box(0, -0.02, 0, 0.26, 0.045, 0.06, gold, Part.Metal);
        cyl(0, -0.2, 0, 0.022, 0.18, wood, Part.Wood);
        sph(0, -0.22, 0, 0.04, gold, Part.Metal);
        break;
      case "staff":
        cyl(0, -0.55, 0, 0.028, 1.25, wood, Part.Wood);
        sph(0, 0.78, 0, 0.1, wc, Part.Glow, 1.2);
        translate(T2, W, 0, 0.72, 0);
        scale(T2, T2, 0.1, 0.1, 0.1);
        this.put(Prim.Torus, T2, gold, Part.Metal, gold, 0, 0, 0.2);
        break;
      case "bow": {
        for (let i = 0; i < 7; i++) {
          const a0 = -1.1 + (i / 7) * 2.2,
            a1 = -1.1 + ((i + 1) / 7) * 2.2;
          segMatrix(T1, 0, Math.sin(a0) * 0.45, Math.cos(a0) * 0.18 - 0.18, 0, Math.sin(a1) * 0.45, Math.cos(a1) * 0.18 - 0.18, 0.025);
          multiply(T2, W, T1);
          this.put(Prim.Cyl, T2, wc, Part.Wood, wc, 0, 0, 0);
        }
        segMatrix(T1, 0, Math.sin(-1.1) * 0.45, Math.cos(-1.1) * 0.18 - 0.18, 0, Math.sin(1.1) * 0.45, Math.cos(1.1) * 0.18 - 0.18, 0.004);
        multiply(T2, W, T1);
        this.put(Prim.Cyl, T2, rgb(0xf0f0e8), Part.Acc, wc, 0, 0, 0.2);
        break;
      }
      case "daggers":
        for (const s of [-1, 1]) {
          box(s * 0.12, 0.12, 0, 0.045, 0.28, 0.012, wc, Part.Metal);
          box(s * 0.12, -0.03, 0, 0.12, 0.03, 0.04, dark, Part.Acc);
          cyl(s * 0.12, -0.14, 0, 0.018, 0.11, dark, Part.Acc);
        }
        break;
      case "mace":
        cyl(0, -0.3, 0, 0.025, 0.65, wood, Part.Wood);
        sph(0, 0.4, 0, 0.12, wc, Part.Metal, 0.1);
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          translate(T2, W, Math.cos(a) * 0.11, 0.4, Math.sin(a) * 0.11);
          rotateY(T2, T2, -a);
          rotateZ(T2, T2, -Math.PI / 2);
          scale(T2, T2, 0.035, 0.09, 0.035);
          this.put(Prim.Cone, T2, wc, Part.Metal, wc, 0, 0, 0);
        }
        break;
      case "scythe":
        cyl(0, -0.6, 0, 0.024, 1.35, dark, Part.Wood);
        for (let i = 0; i < 5; i++) {
          const a = i * 0.28;
          translate(T2, W, 0, 0.72 - Math.sin(a) * 0.1, 0.05 + i * 0.1);
          rotateX(T2, T2, 0.3 + a);
          scale(T2, T2, 0.012, 0.06, 0.12);
          this.put(Prim.Box, T2, wc, Part.Glow, wc, 0, 0, 0.7);
        }
        break;
      case "tome":
        box(0, 0, 0, 0.3, 0.05, 0.38, rgb(0x6a2a3a), Part.Acc);
        box(0, 0.035, 0, 0.27, 0.03, 0.35, rgb(0xf4ecd8), Part.Acc, 0.2);
        sph(0, 0.06, 0, 0.05, wc, Part.Glow, 1);
        break;
      case "totem":
        cyl(0, -0.45, 0, 0.05, 1.0, wood, Part.Wood);
        sph(0, 0.62, 0, 0.12, wood, Part.Wood);
        for (const s of [-1, 1]) {
          translate(T2, W, s * 0.12, 0.72, 0);
          rotateZ(T2, T2, -s * 0.3);
          scale(T2, T2, 0.07, 0.14, 0.05);
          this.put(Prim.Cone, T2, wood, Part.Wood, wood, 0, 0, 0);
          sph(s * 0.05, 0.64, 0.1, 0.022, rgb(0x7affc0), Part.Glow, 1.2);
        }
        for (let i = 0; i < 3; i++) {
          translate(T2, W, 0, 0.45 - i * 0.08, 0.06);
          rotateZ(T2, T2, i - 1);
          scale(T2, T2, 0.1, 0.03, 0.02);
          this.put(Prim.SphereLo, T2, rgb(0x4a9a3a), Part.Acc, wood, 0, 0, 0);
        }
        break;
      case "shield":
        translate(T2, W, 0, 0, 0);
        rotateZ(T2, T2, Math.PI / 2);
        scale(T2, T2, 0.3, 0.04, 0.3);
        this.put(Prim.Cyl, T2, off ? rgb(0x3a5aa0) : wc, Part.Metal, wc, 0, 0, 0);
        translate(T2, W, -0.04, 0, 0);
        scale(T2, T2, 0.08, 0.08, 0.08);
        this.put(Prim.SphereLo, T2, gold, Part.Metal, gold, 0, 0, 0.1);
        translate(T2, W, -0.045, 0, 0);
        rotateZ(T2, T2, Math.PI / 2);
        scale(T2, T2, 0.31, 0.3, 0.31);
        this.put(Prim.Torus, T2, gold, Part.Metal, gold, 0, 0, 0);
        break;
      case "lute":
        sph(0, 0, 0, 0.16, rgb(0xb8763a), Part.Wood);
        cyl(0, 0.1, 0, 0.03, 0.4, wood, Part.Wood);
        break;
    }
  }

  private flush(batches: Batch[]) {
    for (const b of batches) {
      if (b.count === 0) continue;
      if (!b.uploaded) {
        b.buf.upload(b.data, b.count * INST);
        b.uploaded = true;
      }
      b.mesh.drawInstanced(b.count);
    }
  }

  shadow(r: Renderer) {
    const gl = this.gl;
    gl.disable(gl.CULL_FACE);
    this.progDepth.use();
    this.progDepth.f1("uShell", 0);
    this.flush(this.opaqueB);
    gl.bindVertexArray(null);
    void r;
  }

  opaque(r: Renderer) {
    const gl = this.gl;
    gl.enable(gl.CULL_FACE);
    this.prog.use();
    this.prog.f1("uShell", 0);
    this.flush(this.opaqueB);
    // Пушистая кромка ближних котов: 1–2 оболочки с alpha-to-coverage (нужен MSAA)
    const shells = r.post.msaaSamples > 0 ? (r.qualityLevel === "high" ? 2 : r.qualityLevel === "medium" ? 1 : 0) : 0;
    if (shells > 0) {
      gl.enable(gl.SAMPLE_ALPHA_TO_COVERAGE);
      for (let i = 1; i <= shells; i++) {
        this.prog.f1("uShell", 0.018 * i);
        this.prog.f1("uShellK", 0.42 + 0.14 * i);
        this.flush(this.opaqueB);
      }
      gl.disable(gl.SAMPLE_ALPHA_TO_COVERAGE);
      this.prog.f1("uShell", 0);
    }
    gl.bindVertexArray(null);
  }

  transparent(r: Renderer) {
    const gl = this.gl;
    let any = false;
    for (const b of this.transB) if (b.count > 0) any = true;
    if (!any) return;
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.depthMask(false);
    gl.enable(gl.CULL_FACE);
    this.prog.use();
    this.prog.f1("uShell", 0);
    this.flush(this.transB);
    gl.depthMask(true);
    gl.disable(gl.BLEND);
    gl.bindVertexArray(null);
    void r;
  }
}
