/** Итоговые характеристики персонажа: класс + уровень + пассивки дерева + предметы + баффы. */
import { CLASSES } from "./classes";
import { levelScale, manaScale } from "./progression";
import type { ClassId, Element } from "./types";
import { ELEMENTS } from "./types";
import type { Delivery, KeystoneId, Passive, StatKey } from "./skills/types";
import type { Item } from "./items";

export interface Stats {
  maxHp: number;
  maxMp: number;
  hpRegen: number;
  mpRegen: number;
  power: number;
  armor: number;
  resist: number;
  crit: number;
  critDmg: number;
  haste: number;
  moveSpeed: number;
  lifesteal: number;
  dodge: number;
  thorns: number;
  summonPct: number;
  healPct: number;
  areaPct: number;
  durationPct: number;
  elementPct: Record<Element, number>;
  deliveryPct: Partial<Record<Delivery, number>>;
  onKill: { heal: number; mana: number; haste: number; explode: number };
  keystones: Map<KeystoneId, number>;
  /** Общий множитель урона (повторные ключевые таланты и т.п.). */
  damageMul: number;
  xpBonus: number;
  fishBonus: number;
  level: number;
}

export interface StatInput {
  classId: ClassId;
  level: number;
  passives: Passive[];
  keystones: Map<KeystoneId, number>;
  items: Item[];
  buffs?: { stat: StatKey; pct: number }[];
}

/**
 * Восстановление игроков. Зелий в игре нет: здоровье и мана копятся сами.
 * В бою понемногу, а через несколько секунд без боя кот мурлычет и быстро приходит в себя.
 * Доли — от максимума в секунду, к ним добавляется восстановление из характеристик.
 */
export const REGEN = {
  /** Сколько секунд без боя до отдыха и за сколько он набирает силу. */
  restDelay: 3,
  restRamp: 1.5,
  hpCombat: 0.005,
  mpCombat: 0.04,
  hpRest: 0.1,
  mpRest: 0.12,
  /** В бою чем меньше здоровья, тем упорнее кот держится: у самого края восстановление втрое сильнее. */
  grit: 2,
  /** Множители восстановления из характеристик: в бою и на отдыхе. */
  statHp: [0.5, 2.5],
  statMp: [1, 2],
};

/** Насколько кот отдыхает: 0 — в бою, 1 — полный отдых. */
export function restFactor(sinceCombat: number): number {
  const t = (sinceCombat - REGEN.restDelay) / REGEN.restRamp;
  return t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t);
}

/** Восстановление здоровья и маны в секунду: rest — степень отдыха, hpFrac — доля здоровья. */
export function regenPerSec(st: Pick<Stats, "hpRegen" | "mpRegen">, maxHp: number, maxMp: number, rest: number, hpFrac = 1): { hp: number; mp: number } {
  const mix = (a: number, b: number) => a + (b - a) * rest;
  const grit = 1 + REGEN.grit * (1 - Math.max(0, Math.min(1, hpFrac)));
  return {
    hp: st.hpRegen * mix(REGEN.statHp[0], REGEN.statHp[1]) + maxHp * mix(REGEN.hpCombat * grit, REGEN.hpRest),
    mp: st.mpRegen * mix(REGEN.statMp[0], REGEN.statMp[1]) + maxMp * mix(REGEN.mpCombat, REGEN.mpRest),
  };
}

export function emptyElementMap(): Record<Element, number> {
  const m = {} as Record<Element, number>;
  for (const e of ELEMENTS) m[e] = 0;
  return m;
}

export function computeStats(inp: StatInput): Stats {
  const cls = CLASSES[inp.classId];
  const L = inp.level;
  const ls = levelScale(L);
  const ms = manaScale(L);
  const b = cls.base;
  const pct: Partial<Record<StatKey, number>> = {};
  const add: Partial<Record<StatKey, number>> = {};
  const elementPct = emptyElementMap();
  const deliveryPct: Partial<Record<Delivery, number>> = {};
  const onKill = { heal: 0, mana: 0, haste: 0, explode: 0 };
  let xpBonus = 0,
    fishBonus = 0;
  const addP = (p: Passive) => {
    switch (p.p) {
      case "stat":
        if (p.pct !== undefined) pct[p.stat] = (pct[p.stat] ?? 0) + p.pct;
        if (p.add !== undefined) add[p.stat] = (add[p.stat] ?? 0) + p.add;
        break;
      case "element":
        elementPct[p.el] += p.pct;
        break;
      case "delivery":
        deliveryPct[p.d] = (deliveryPct[p.d] ?? 0) + p.pct;
        break;
      case "onKill":
        onKill[p.what] += p.amount;
        break;
    }
  };
  for (const p of inp.passives) addP(p);
  // Предметы
  let flatPower = 0,
    flatArmor = 0,
    flatHp = 0,
    flatMp = 0;
  for (const it of inp.items) {
    if (!it.gear) continue;
    flatPower += it.gear.power ?? 0;
    flatArmor += it.gear.armor ?? 0;
    flatHp += it.gear.hp ?? 0;
    flatMp += it.gear.mp ?? 0;
    for (const a of it.gear.affixes) {
      if (a.kind === "stat") {
        if (a.pct) pct[a.stat!] = (pct[a.stat!] ?? 0) + a.value;
        else add[a.stat!] = (add[a.stat!] ?? 0) + a.value;
      } else if (a.kind === "element") elementPct[a.el!] += a.value;
      else if (a.kind === "delivery") deliveryPct[a.delivery!] = (deliveryPct[a.delivery!] ?? 0) + a.value;
      else if (a.kind === "xp") xpBonus += a.value;
      else if (a.kind === "fish") fishBonus += a.value;
    }
  }
  for (const bf of inp.buffs ?? []) pct[bf.stat] = (pct[bf.stat] ?? 0) + bf.pct;
  const P = (k: StatKey) => pct[k] ?? 0;
  const A = (k: StatKey) => add[k] ?? 0;
  const ks = inp.keystones;
  let maxHp = (b.hp * ls + flatHp) * (1 + P("maxHp"));
  if (ks.has("feline")) maxHp *= 0.85;
  const maxMp = (b.mp * ms + flatMp) * (1 + P("maxMp"));
  const power = (b.power * ls + flatPower) * (1 + P("power"));
  let armor = (b.armor * ls + flatArmor) * (1 + P("armor"));
  if (ks.has("frozenHeart")) armor *= 1.3;
  let moveSpeed = b.moveSpeed * (1 + A("moveSpeed") + P("moveSpeed"));
  if (ks.has("sprinter")) moveSpeed *= 1.3;
  let dodge = b.dodge + A("dodge");
  if (ks.has("feline")) dodge += 0.25;
  let dupes = 0;
  for (const v of ks.values()) dupes += v - 1;
  return {
    maxHp,
    maxMp,
    hpRegen: b.hpRegen * ls * (1 + P("hpRegen")) + A("hpRegen") * ls,
    mpRegen: b.mpRegen * ms * (1 + P("mpRegen")) + A("mpRegen") * ms,
    power,
    armor,
    resist: Math.min(0.75, b.resist + A("resist")),
    crit: Math.min(0.9, b.crit + A("crit")),
    critDmg: b.critDmg + A("critDmg"),
    haste: A("haste") + P("haste"),
    moveSpeed: Math.min(moveSpeed, 14),
    lifesteal: A("lifesteal") + (ks.has("vampirism") ? 0.08 : 0),
    dodge: Math.min(0.6, dodge),
    thorns: A("thorns"),
    summonPct: A("summonPct") + P("summonPct"),
    healPct: A("healPct") + P("healPct"),
    areaPct: A("areaPct") + P("areaPct"),
    durationPct: A("durationPct") + P("durationPct"),
    elementPct,
    deliveryPct,
    onKill,
    keystones: ks,
    damageMul: 1 + dupes * 0.1,
    xpBonus,
    fishBonus,
    level: L,
  };
}
