/** Сохранения персонажей в localStorage (+ экспорт/импорт в файл). */
import { makeAutoObservable } from "mobx";
import type { CharacterData } from "../game/character";

const INDEX = "kotoverse.saves.index.v1";
const PREFIX = "kotoverse.save.v1.";

export interface SaveMeta {
  id: string;
  name: string;
  classId: string;
  level: number;
  mode: CharacterData["mode"];
  updatedAt: number;
  playTime: number;
  fur: number;
  pattern: string;
}

export class SaveStore {
  list: SaveMeta[] = [];
  error: string | null = null;

  constructor() {
    makeAutoObservable(this);
    this.refresh();
  }

  refresh() {
    try {
      const raw = localStorage.getItem(INDEX);
      this.list = raw ? (JSON.parse(raw) as SaveMeta[]) : [];
      this.list.sort((a, b) => b.updatedAt - a.updatedAt);
    } catch {
      this.list = [];
    }
  }

  load(id: string): CharacterData | null {
    try {
      const raw = localStorage.getItem(PREFIX + id);
      return raw ? (JSON.parse(raw) as CharacterData) : null;
    } catch {
      return null;
    }
  }

  save(data: CharacterData): boolean {
    try {
      data.updatedAt = Date.now();
      localStorage.setItem(PREFIX + data.id, JSON.stringify(data));
      const meta: SaveMeta = {
        id: data.id,
        name: data.name,
        classId: data.classId,
        level: data.level,
        mode: data.mode,
        updatedAt: data.updatedAt,
        playTime: data.stats.playTime,
        fur: data.look.fur,
        pattern: data.look.pattern,
      };
      const idx = this.list.filter((m) => m.id !== data.id);
      idx.unshift(meta);
      this.list = idx;
      localStorage.setItem(INDEX, JSON.stringify(idx));
      this.error = null;
      return true;
    } catch (e) {
      this.error = String(e);
      return false;
    }
  }

  remove(id: string) {
    try {
      localStorage.removeItem(PREFIX + id);
    } catch {
      /* ignore */
    }
    this.list = this.list.filter((m) => m.id !== id);
    try {
      localStorage.setItem(INDEX, JSON.stringify(this.list));
    } catch {
      /* ignore */
    }
  }

  exportJson(id: string): string | null {
    const d = this.load(id);
    return d ? JSON.stringify(d) : null;
  }

  importJson(json: string): CharacterData | null {
    try {
      const d = JSON.parse(json) as CharacterData;
      if (!d || d.v !== 1 || !d.classId || !d.id) return null;
      this.save(d);
      return d;
    } catch {
      return null;
    }
  }
}
