/** Корень приложения: хранилища, 3D-фон меню и переключение экранов. */
import { observer } from "mobx-react-lite";
import { useEffect, useRef, useState } from "react";
import { tr } from "../core/i18n";
import { audio } from "../audio/audio";
import { RootStore, StoreContext, useStore } from "./stores";
import { MenuBackdrop } from "./menu-backdrop";
import { About, MainMenu } from "./menu/MainMenu";
import { NewGame } from "./menu/NewGame";
import { LoadGame } from "./menu/LoadGame";
import { SettingsScreen } from "./menu/Settings";
import { AnswerRelay, CoopScreen } from "./panels/Coop";
import { GameScreen } from "./game/GameScreen";
import { ConfirmPopup, LorePopup } from "./panels/GameMenu";
import { ErrorBoundary } from "./ErrorBoundary";

const MenuLayer = observer(() => {
  const s = useStore();
  const ref = useRef<HTMLCanvasElement>(null);
  const [backdrop, setBackdrop] = useState<MenuBackdrop | null>(null);
  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    let b: MenuBackdrop | null = null;
    try {
      b = new MenuBackdrop(c, s.settings.quality);
      b.start();
      setBackdrop(b);
    } catch (e) {
      console.warn("3D-фон меню недоступен:", e);
    }
    audio.setMood("menu");
    // Потеря контекста (телефон свернул вкладку): пересоздаём фон после восстановления
    const lost = (e: Event) => e.preventDefault();
    const restored = () => s.restartSession();
    c.addEventListener("webglcontextlost", lost);
    c.addEventListener("webglcontextrestored", restored);
    return () => {
      c.removeEventListener("webglcontextlost", lost);
      c.removeEventListener("webglcontextrestored", restored);
      b?.destroy();
      setBackdrop(null);
    };
  }, [s]);
  const scr = s.ui.screen;
  return (
    <>
      <canvas ref={ref} className="game menu-bg" />
      {scr === "menu" && <MainMenu />}
      {scr === "newgame" && <NewGame backdrop={backdrop} />}
      {scr === "load" && <LoadGame />}
      {scr === "settings" && <SettingsScreen />}
      {scr === "about" && <About />}
      {scr === "coop" && <CoopScreen />}
    </>
  );
});

// iOS принимает включение звука только из «настоящего» жеста (touchend/click)
const unlock = () => audio.unlock();

const Screens = observer(() => {
  const s = useStore();
  const inGame = s.ui.screen === "game" && s.char !== null;
  return (
    <div className="app-root" onPointerDown={unlock} onTouchEnd={unlock} onClick={unlock} lang={s.settings.lang}>
      {s.relayAnswer ? <AnswerRelay code={s.relayAnswer} /> : inGame ? <GameScreen key={`${s.char!.data.id}:${s.sessionNonce}`} /> : <MenuLayer key={s.sessionNonce} />}
      <ConfirmPopup />
      <LorePopup />
      <noscript>{tr({ ru: "Нужен JavaScript", en: "JavaScript is required" })}</noscript>
    </div>
  );
});

export function App() {
  const [root] = useState(() => {
    const r = new RootStore();
    // Ссылка-приглашение в кооператив: #join=<код>
    const h = location.hash;
    if (h.startsWith("#join=")) {
      r.joinCode = h.slice(6);
      history.replaceState(null, "", location.pathname + location.search);
      r.ui.go("coop");
    } else if (h.startsWith("#answer=")) {
      r.relayAnswer = h.slice(8);
      history.replaceState(null, "", location.pathname + location.search);
    }
    (window as unknown as { __root: RootStore }).__root = r;
    return r;
  });
  return (
    <StoreContext.Provider value={root}>
      <ErrorBoundary onReset={() => root.quitToMenu()}>
        <Screens />
      </ErrorBoundary>
    </StoreContext.Provider>
  );
}
