/**
 * Процедурный звук на WebAudio: мяуканье (формантный синтез), шипение, мурчание, удары,
 * заклинания, взрывы, музыка-генератор по настроению биома. Никаких аудиофайлов.
 */
type Mood = "calm" | "bright" | "mystic" | "dark" | "epic" | "cold" | "hot" | "dungeon" | "menu";

const SCALES: Record<Mood, number[]> = {
  calm: [0, 2, 4, 7, 9],
  bright: [0, 2, 4, 7, 9],
  mystic: [0, 3, 5, 7, 10],
  dark: [0, 1, 3, 7, 8],
  epic: [0, 3, 5, 7, 10],
  cold: [0, 2, 3, 7, 9],
  hot: [0, 1, 4, 5, 7],
  dungeon: [0, 1, 3, 6, 7],
  menu: [0, 2, 4, 7, 9],
};
const ROOT: Record<Mood, number> = { calm: 57, bright: 60, mystic: 55, dark: 50, epic: 52, cold: 59, hot: 53, dungeon: 48, menu: 60 };
const TEMPO: Record<Mood, number> = { calm: 84, bright: 100, mystic: 76, dark: 70, epic: 108, cold: 72, hot: 96, dungeon: 64, menu: 88 };

const mtof = (m: number) => 440 * Math.pow(2, (m - 69) / 12);

export class AudioEngine {
  ctx: AudioContext | null = null;
  private master!: GainNode;
  private sfxBus!: GainNode;
  private musicBus!: GainNode;
  private noiseBuf!: AudioBuffer;
  private comp!: DynamicsCompressorNode;
  sfxVolume = 0.8;
  musicVolume = 0.45;
  muted = false;
  private mood: Mood = "menu";
  private combat = 0;
  private nextNote = 0;
  private step = 0;
  private musicTimer: number | null = null;
  private listenerX = 0;
  private listenerZ = 0;
  private recent = new Map<string, number>();

  /** Вызывать из обработчика жеста пользователя (требование мобильных браузеров). */
  unlock() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") void this.ctx.resume();
      return;
    }
    const AC = window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.comp = ctx.createDynamicsCompressor();
    this.comp.threshold.value = -14;
    this.comp.ratio.value = 4;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 1;
    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = this.sfxVolume;
    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = this.musicVolume * 0.5;
    this.sfxBus.connect(this.comp);
    this.musicBus.connect(this.comp);
    this.comp.connect(this.master);
    this.master.connect(ctx.destination);
    const len = ctx.sampleRate * 1.5;
    this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    this.startMusic();
  }

  setVolumes(sfx: number, music: number, muted: boolean) {
    this.sfxVolume = sfx;
    this.musicVolume = music;
    this.muted = muted;
    if (!this.ctx) return;
    this.sfxBus.gain.value = sfx;
    this.musicBus.gain.value = music * 0.5;
    this.master.gain.value = muted ? 0 : 1;
  }

  setListener(x: number, z: number) {
    this.listenerX = x;
    this.listenerZ = z;
  }

  setMood(m: Mood) {
    this.mood = m;
  }

  setCombat(c: number) {
    this.combat = c;
  }

  // ─────────────── базовые кирпичики ───────────────

  private out(x?: number, z?: number, vol = 1): GainNode | null {
    const ctx = this.ctx;
    if (!ctx) return null;
    const g = ctx.createGain();
    let v = vol;
    let pan = 0;
    if (x !== undefined && z !== undefined) {
      const dx = x - this.listenerX,
        dz = z - this.listenerZ;
      const d = Math.hypot(dx, dz);
      v *= Math.max(0, 1 - d / 45);
      pan = Math.max(-0.8, Math.min(0.8, dx / 18));
      if (v < 0.02) return null;
    }
    g.gain.value = v;
    if (ctx.createStereoPanner) {
      const p = ctx.createStereoPanner();
      p.pan.value = pan;
      g.connect(p);
      p.connect(this.sfxBus);
    } else g.connect(this.sfxBus);
    return g;
  }

  private noise(dur: number): AudioBufferSourceNode {
    const src = this.ctx!.createBufferSource();
    src.buffer = this.noiseBuf;
    src.loop = true;
    src.loopStart = Math.random() * 0.5;
    return src;
  }

  private env(g: GainNode, t: number, a: number, peak: number, d: number, sustain = 0) {
    const p = g.gain;
    p.setValueAtTime(0.0001, t);
    p.exponentialRampToValueAtTime(Math.max(peak, 0.0002), t + a);
    p.exponentialRampToValueAtTime(Math.max(sustain, 0.0001), t + a + d);
  }

  // ─────────────── звуки ───────────────

  /** Мяу! size — размер кошки (чем больше, тем ниже), kind — оттенок. */
  meow(x?: number, z?: number, size = 1, kind: "happy" | "angry" | "sad" | "question" = "happy", vol = 0.5) {
    const ctx = this.ctx;
    const o = this.out(x, z, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime;
    const dur = (0.35 + Math.random() * 0.25) * (kind === "sad" ? 1.4 : 1);
    const base = (620 + Math.random() * 180) / Math.pow(size, 0.8);
    const osc = ctx.createOscillator();
    osc.type = "sawtooth";
    const f = osc.frequency;
    f.setValueAtTime(base * 0.8, t);
    if (kind === "question") {
      f.linearRampToValueAtTime(base * 1.1, t + dur * 0.4);
      f.linearRampToValueAtTime(base * 1.5, t + dur);
    } else if (kind === "sad") {
      f.linearRampToValueAtTime(base * 1.2, t + dur * 0.3);
      f.linearRampToValueAtTime(base * 0.6, t + dur);
    } else {
      f.linearRampToValueAtTime(base * 1.35, t + dur * 0.35);
      f.linearRampToValueAtTime(base * (kind === "angry" ? 0.55 : 0.75), t + dur);
    }
    const vib = ctx.createOscillator();
    vib.frequency.value = 6;
    const vg = ctx.createGain();
    vg.gain.value = base * 0.02;
    vib.connect(vg);
    vg.connect(f);
    // Форманты: «м» → «я» → «у»
    const f1 = ctx.createBiquadFilter();
    f1.type = "bandpass";
    f1.Q.value = 6;
    f1.frequency.setValueAtTime(400, t);
    f1.frequency.linearRampToValueAtTime(850, t + dur * 0.3);
    f1.frequency.linearRampToValueAtTime(520, t + dur);
    const f2 = ctx.createBiquadFilter();
    f2.type = "bandpass";
    f2.Q.value = 8;
    f2.frequency.setValueAtTime(1200, t);
    f2.frequency.linearRampToValueAtTime(2000, t + dur * 0.3);
    f2.frequency.linearRampToValueAtTime(900, t + dur);
    const g = ctx.createGain();
    this.env(g, t, 0.04, 1, dur, 0.0001);
    osc.connect(f1);
    osc.connect(f2);
    f1.connect(g);
    f2.connect(g);
    g.connect(o);
    osc.start(t);
    vib.start(t);
    osc.stop(t + dur + 0.1);
    vib.stop(t + dur + 0.1);
  }

  hiss(x?: number, z?: number, vol = 0.4) {
    const ctx = this.ctx;
    const o = this.out(x, z, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime;
    const n = this.noise(0.6);
    const hp = ctx.createBiquadFilter();
    hp.type = "highpass";
    hp.frequency.value = 2800;
    const g = ctx.createGain();
    this.env(g, t, 0.02, 0.8, 0.5);
    n.connect(hp);
    hp.connect(g);
    g.connect(o);
    n.start(t);
    n.stop(t + 0.6);
  }

  purr(dur = 1.5, vol = 0.35) {
    const ctx = this.ctx;
    const o = this.out(undefined, undefined, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = "sawtooth";
    osc.frequency.value = 55;
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = 300;
    const am = ctx.createGain();
    am.gain.value = 0;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 24;
    const lg = ctx.createGain();
    lg.gain.value = 0.5;
    lfo.connect(lg);
    lg.connect(am.gain);
    const g = ctx.createGain();
    this.env(g, t, 0.2, 0.7, dur, 0.0001);
    osc.connect(lp);
    lp.connect(am);
    am.connect(g);
    g.connect(o);
    osc.start(t);
    lfo.start(t);
    osc.stop(t + dur + 0.3);
    lfo.stop(t + dur + 0.3);
  }

  private swoosh(x: number | undefined, z: number | undefined, f0: number, f1: number, dur: number, vol: number) {
    const ctx = this.ctx;
    const o = this.out(x, z, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime;
    const n = this.noise(dur);
    const bp = ctx.createBiquadFilter();
    bp.type = "bandpass";
    bp.Q.value = 2.5;
    bp.frequency.setValueAtTime(f0, t);
    bp.frequency.exponentialRampToValueAtTime(f1, t + dur);
    const g = ctx.createGain();
    this.env(g, t, 0.01, 1, dur);
    n.connect(bp);
    bp.connect(g);
    g.connect(o);
    n.start(t);
    n.stop(t + dur + 0.05);
  }

  private tone(x: number | undefined, z: number | undefined, type: OscillatorType, f0: number, f1: number, dur: number, vol: number, delay = 0) {
    const ctx = this.ctx;
    const o = this.out(x, z, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
    const g = ctx.createGain();
    this.env(g, t, 0.01, 1, dur);
    osc.connect(g);
    g.connect(o);
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  private boom(x?: number, z?: number, vol = 0.8, size = 1) {
    const ctx = this.ctx;
    const o = this.out(x, z, vol);
    if (!ctx || !o) return;
    const t = ctx.currentTime;
    this.tone(x, z, "sine", 90 / size, 30, 0.5, vol * 0.9);
    const n = this.noise(0.6);
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.setValueAtTime(1800, t);
    lp.frequency.exponentialRampToValueAtTime(200, t + 0.5);
    const g = ctx.createGain();
    this.env(g, t, 0.005, 0.9, 0.55);
    n.connect(lp);
    lp.connect(g);
    g.connect(o);
    n.start(t);
    n.stop(t + 0.7);
  }

  private chime(x: number | undefined, z: number | undefined, notes: number[], vol = 0.25, gap = 0.07, type: OscillatorType = "triangle") {
    notes.forEach((m, i) => this.tone(x, z, type, mtof(m), mtof(m) * 0.995, 0.35, vol, i * gap));
  }

  /** Универсальная точка входа по имени события. */
  play(name: string, x?: number, z?: number, vol = 1, pitch = 1) {
    if (!this.ctx) return;
    // Ограничиваем частоту одинаковых звуков
    const now = this.ctx.currentTime;
    const last = this.recent.get(name) ?? 0;
    if (now - last < 0.045) return;
    this.recent.set(name, now);
    switch (name) {
      case "cast_strike":
        this.swoosh(x, z, 3200 * pitch, 700, 0.14, 0.35 * vol);
        break;
      case "cast_projectile":
      case "cast_boomerang":
        this.swoosh(x, z, 1800 * pitch, 3200, 0.16, 0.22 * vol);
        this.tone(x, z, "sine", 700 * pitch, 1200 * pitch, 0.12, 0.08 * vol);
        break;
      case "cast_nova":
      case "cast_cone":
        this.swoosh(x, z, 600, 2400, 0.3, 0.35 * vol);
        this.tone(x, z, "triangle", 220 * pitch, 110, 0.3, 0.2 * vol);
        break;
      case "cast_chain":
      case "zap":
        this.tone(x, z, "square", 900 * pitch, 180, 0.18, 0.12 * vol);
        this.swoosh(x, z, 5000, 2000, 0.12, 0.2 * vol);
        break;
      case "cast_heal":
        this.chime(x, z, [72, 76, 79, 84], 0.12 * vol);
        break;
      case "cast_buff":
      case "cast_barrier":
        this.chime(x, z, [67, 71, 74], 0.14 * vol, 0.05, "sine");
        break;
      case "cast_summon":
        this.meow(x, z, 0.6, "happy", 0.3 * vol);
        this.chime(x, z, [60, 67, 72], 0.1 * vol);
        break;
      case "cast_dash":
      case "cast_leap":
      case "cast_blink":
        this.swoosh(x, z, 900, 4000, 0.2, 0.3 * vol);
        break;
      case "cast_blast":
      case "cast_rain":
      case "cast_vortex":
      case "cast_mark":
      case "cast_wall":
      case "cast_totem":
      case "cast_trap":
      case "cast_aura":
      case "cast_orbit":
      case "cast_beam":
      case "cast_eruption":
        this.chime(x, z, [64 + Math.floor(Math.random() * 5), 71, 76], 0.08 * vol, 0.04, "sine");
        this.swoosh(x, z, 1200, 2600, 0.25, 0.15 * vol);
        break;
      case "boom":
        this.boom(x, z, 0.55 * vol);
        break;
      case "rumble":
        this.boom(x, z, 0.4 * vol, 1.6);
        break;
      case "land":
        this.tone(x, z, "sine", 120, 45, 0.25, 0.45 * vol);
        break;
      case "trap":
        this.tone(x, z, "square", 400, 120, 0.12, 0.2 * vol);
        this.boom(x, z, 0.4 * vol);
        break;
      case "hit":
        this.tone(x, z, "sine", 160 * pitch, 60, 0.12, 0.35 * vol);
        this.swoosh(x, z, 2000, 500, 0.06, 0.25 * vol);
        break;
      case "hurt":
        this.tone(undefined, undefined, "sine", 130, 50, 0.18, 0.45 * vol);
        this.meow(undefined, undefined, 1, "angry", 0.25 * vol);
        break;
      case "death":
        this.meow(x, z, pitch > 0 ? 1 / pitch : 1, "sad", 0.3 * vol);
        this.swoosh(x, z, 900, 300, 0.4, 0.15 * vol);
        break;
      case "bossDeath":
        this.boom(x, z, 0.9 * vol, 1.8);
        this.meow(x, z, 2.2, "sad", 0.6 * vol);
        break;
      case "playerDeath":
        this.meow(undefined, undefined, 1, "sad", 0.6);
        this.chime(undefined, undefined, [60, 56, 53], 0.2, 0.25, "sine");
        break;
      case "bossRoar": {
        const ctx = this.ctx;
        const o = this.out(x, z, 0.7 * vol);
        if (!o) break;
        const t = ctx.currentTime;
        const osc = ctx.createOscillator();
        osc.type = "sawtooth";
        osc.frequency.setValueAtTime(110, t);
        osc.frequency.exponentialRampToValueAtTime(55, t + 1.1);
        const lp = ctx.createBiquadFilter();
        lp.type = "lowpass";
        lp.frequency.value = 700;
        const g = ctx.createGain();
        this.env(g, t, 0.08, 1, 1.1);
        osc.connect(lp);
        lp.connect(g);
        g.connect(o);
        osc.start(t);
        osc.stop(t + 1.3);
        this.hiss(x, z, 0.3 * vol);
        break;
      }
      case "levelup":
        this.chime(undefined, undefined, [60, 64, 67, 72, 76, 79, 84], 0.18, 0.07);
        this.purr(1.2, 0.2);
        break;
      case "quest":
        this.chime(undefined, undefined, [67, 72, 76, 79], 0.2, 0.1);
        break;
      case "pickup":
        this.tone(undefined, undefined, "square", 988, 988, 0.06, 0.08);
        this.tone(undefined, undefined, "square", 1319, 1319, 0.09, 0.08, 0.06);
        break;
      case "fish":
        this.tone(undefined, undefined, "triangle", 1568, 1760, 0.08, 0.1);
        break;
      case "click":
        this.tone(undefined, undefined, "triangle", 1200, 900, 0.04, 0.08);
        break;
      case "open":
        this.swoosh(undefined, undefined, 400, 1600, 0.2, 0.2);
        break;
      case "portal":
        this.chime(x, z, [60, 63, 67, 70, 74], 0.12, 0.06, "sine");
        this.swoosh(x, z, 300, 3000, 0.6, 0.2);
        break;
      case "meow":
        this.meow(x, z, pitch > 0 ? 1 / pitch : 1, "happy", 0.5 * vol);
        break;
      case "hiss":
        this.hiss(x, z, 0.4 * vol);
        break;
      case "dodge":
        this.swoosh(x, z, 2500, 5000, 0.08, 0.12 * vol);
        break;
      default:
        break;
    }
  }

  // ─────────────── музыка ───────────────

  private startMusic() {
    if (this.musicTimer !== null) return;
    this.nextNote = this.ctx!.currentTime + 0.2;
    this.musicTimer = window.setInterval(() => this.scheduleMusic(), 120);
  }

  stopMusic() {
    if (this.musicTimer !== null) window.clearInterval(this.musicTimer);
    this.musicTimer = null;
  }

  private note(t: number, midi: number, dur: number, vol: number, type: OscillatorType, cutoff = 2400) {
    const ctx = this.ctx!;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = mtof(midi);
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = cutoff;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(lp);
    lp.connect(g);
    g.connect(this.musicBus);
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  private scheduleMusic() {
    const ctx = this.ctx;
    if (!ctx || this.musicVolume <= 0.001) return;
    const mood = this.mood;
    const scale = SCALES[mood];
    const root = ROOT[mood];
    const tempo = TEMPO[mood] * (1 + this.combat * 0.25);
    const beat = 60 / tempo / 2;
    while (this.nextNote < ctx.currentTime + 0.5) {
      const t = this.nextNote;
      const s = this.step;
      const bar = Math.floor(s / 8) % 4;
      const chordRoots = [0, 3, 4, 2];
      const cr = scale[chordRoots[bar] % scale.length];
      // Бас
      if (s % 4 === 0) this.note(t, root - 24 + cr, beat * 3.6, 0.07, "triangle", 600);
      // Пэд
      if (s % 8 === 0) {
        for (const k of [0, 2, 4]) this.note(t, root - 12 + scale[(chordRoots[bar] + k) % scale.length] + (k === 4 ? 12 : 0), beat * 7.6, 0.022, "sine", 1200);
      }
      // Мелодия (генеративная)
      const r = Math.sin(s * 12.9898 + bar * 78.233) * 43758.5453;
      const rnd = r - Math.floor(r);
      if (rnd < (mood === "calm" || mood === "mystic" ? 0.45 : 0.6)) {
        const deg = Math.floor(rnd * 10) % scale.length;
        const oct = rnd > 0.3 ? 12 : 0;
        this.note(t, root + scale[deg] + oct, beat * (rnd < 0.2 ? 2 : 1.2), 0.035, mood === "dark" || mood === "dungeon" ? "sine" : "triangle", 3000);
      }
      // Лёгкая перкуссия в бою
      if (this.combat > 0.3 && s % 2 === 0) {
        const n = ctx.createBufferSource();
        n.buffer = this.noiseBuf;
        const hp = ctx.createBiquadFilter();
        hp.type = "highpass";
        hp.frequency.value = s % 4 === 0 ? 200 : 6000;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(s % 4 === 0 ? 0.08 : 0.02, t + 0.005);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.09);
        n.connect(hp);
        hp.connect(g);
        g.connect(this.musicBus);
        n.start(t);
        n.stop(t + 0.1);
      }
      this.nextNote += beat;
      this.step++;
    }
  }
}

export const audio = new AudioEngine();

// Свернули вкладку — выключаем звук и музыку (экономия батареи на телефоне)
if (typeof document !== "undefined") {
  document.addEventListener("visibilitychange", () => {
    const ctx = audio.ctx;
    if (!ctx) return;
    if (document.hidden) void ctx.suspend().catch(() => undefined);
    else void ctx.resume().catch(() => undefined);
  });
}
