interface Floater {
  x: number;
  y: number;
  z: number;
  text: string;
  color: number;
  size: number;
  t: number;
  life: number;
  vy: number;
  vx: number;
}

interface InteractTarget extends InteractView {
  x: number;
  z: number;
  run: () => void;
}

/** Мост для кооператива (реализуется сетевым модулем). */
export interface NetBridge {
  role: "host" | "guest";
  readonly partnerName: string;
  readonly connected: boolean;
  partner(): Entity | null;
  onFrame(s: GameSession, dt: number): void;
  onEvents(s: GameSession, events: GameEvent[]): void;
  onLocalCast(s: GameSession, skill: SkillDef, aimX: number, aimZ: number, targetId: number): void;
  onEnterDungeon?(s: GameSession, poi: Poi, floor: number): void;
  onExitDungeon?(s: GameSession): void;
  onMeow?(s: GameSession): void;
  /** Гость просит хоста о переходе (подземелье, выход, лестница). */
  request?(k: "dungeon" | "exit" | "stairs", poiId?: string): void;
  close(): void;
}

/** Гость кооператива играет в мире хоста. */
export interface WorldOverride {
  seed: number;
  mode: ModeConfig;
  x: number;
  z: number;
  dungeon: { poiId: string; floor: number } | null;
  dungeonReturn: { x: number; z: number } | null;
}

/** То, что принадлежит миру персонажа и не должно меняться, пока он гостит у друга. */
type WorldBound = Pick<CharacterData, "quests" | "discovered" | "cleared" | "pos" | "story">;

export class GameSession {
  readonly gen: WorldGen;
  readonly terrain: TerrainCache;
  readonly world: GameWorld;
  // GPU-объекты пересоздаются при восстановлении потерянного WebGL-контекста
  renderer: Renderer;
  cats: CatRenderer;
  particles: ParticleSystem;
  text: TextRenderer;
  fx: FxSystem;
  ambient: AmbientFx;
  private nearBuildings: Building[] = [];
  private treeCats = new TreeCats();
  private treeCatList: CatInstance[] = [];
  dungeonR: DungeonRenderer;
  readonly input = new Input();
  readonly quests: QuestSystem;
  player!: Entity;
  dungeon: Dungeon | null = null;
  dungeonReturn: { x: number; z: number } | null = null;
  loot: LootDrop[] = [];
  floaters: Floater[] = [];
  camYaw = 0.6;
  camPitch = 0.72;
  camDist = 13;
  targetId = -1;
  hoverTarget = -1;
  net: NetBridge | null = null;
  running = false;
  private raf = 0;
  private last = 0;
  private hudT = 0;
  private saveT = 0;
  private visitT = 0;
  private deadT = 0;
  /** Отдых вне боя: кот мурлычет и быстро восстанавливается. */
  private resting = false;
  private restT = 0;
  private purrAt = -100;
  private catInst = new Map<number, CatInstance>();
  private interactTarget: InteractTarget | null = null;
  private aim: { x: number; z: number } | null = null;
  private lastRegion = "";
  private lastTown = "";
  private noManaT = 0;
  private fpsAcc = 0;
  private fpsN = 0;
  private shrineCd = new Map<string, number>();
  private kittens = new Map<string, CatInstance>();
  private loaded = false;
  private disposers: (() => void)[] = [];
  private lootId = 1;
  private shake = 0;
  combatT = 0;
  private dynScaleT = 0;
  private slowT = 0;
  private climbHinted = false;
  private noDyn = typeof location !== "undefined" && location.search.includes("nodyn");
  private playAcc = 0;
  private hinted = false;
  /** Гость кооператива: сохранённое состояние родного мира персонажа. */
  private guestStash: WorldBound | null = null;

  constructor(
    readonly canvas: HTMLCanvasElement,
    readonly char: CharacterStore,
    readonly hud: HudState,
    readonly ui: UiStore,
    readonly settings: SettingsStore,
    readonly saves: SaveStore,
    override?: WorldOverride,
  ) {
    const d = char.data;
    if (override) {
      // Гостим в мире хоста: прогресс персонажа общий, а задания/открытия родного мира не трогаем
      this.guestStash = { quests: d.quests, discovered: d.discovered, cleared: d.cleared, pos: d.pos, story: d.story };
      runInAction(() => {
        d.quests = { active: {}, done: [], tracked: null };
        d.discovered = [];
        d.cleared = [];
        d.story = { ...d.story };
        d.pos = { x: override.x, z: override.z, dungeon: override.dungeon };
      });
    }
    this.gen = override ? new WorldGen(override.seed, override.mode) : new WorldGen(d.seed, d.mode);
    this.terrain = new TerrainCache(this.gen);
    this.world = new GameWorld(this.gen, this.terrain, override ? override.mode : d.mode);
    if (override) this.world.authority = false;
    this.renderer = new Renderer(canvas);
    this.renderer.setWorld(this.terrain);
    this.renderer.setQuality(settings.quality);
    this.cats = new CatRenderer(this.renderer.gl);
    this.particles = new ParticleSystem(this.renderer.gl, this.renderer.quality.particles);
    this.text = new TextRenderer(this.renderer.gl);
    this.fx = new FxSystem(this.particles);
    this.ambient = new AmbientFx(this.particles);
    this.dungeonR = new DungeonRenderer(this.renderer.gl);
    this.renderer.passes.push(this.dungeonR, this.cats, this.particles, this.text);
    this.quests = new QuestSystem(this.gen, char, hud);
    this.renderer.env.dayLength = settings.dayLength * 60;
    // Позиция игрока
    let x = d.pos.x,
      z = d.pos.z;
    if (!isFinite(x) || !isFinite(z)) {
      const r = this.gen.regionAt(this.gen.start.x, this.gen.start.z);
      x = r.town ? r.town.x + 3 : this.gen.start.x;
      z = r.town ? r.town.z + 6 : this.gen.start.z;
    }
    this.player = this.world.addPlayer({ classId: d.classId, name: { ru: d.name, en: d.name }, look: char.gearLook, level: d.level, stats: char.stats, peer: "local", x, z });
    this.quests.ensureStory();
    // Реакция на изменения характеристик/внешности
    this.disposers.push(
      reaction(
        () => this.char.stats,
        (st) => this.world.applyStats(this.player, st),
      ),
      reaction(
        () => this.char.gearLook,
        (lk) => {
          this.player.look = lk;
        },
      ),
      reaction(
        () => this.settings.quality,
        (q) => {
          this.renderer.setQuality(q);
          this.particles.setMax(this.renderer.quality.particles);
          this.fx.quality = q === "low" ? 0.5 : q === "medium" ? 0.8 : 1;
          this.ambient.quality = this.fx.quality;
        },
      ),
      reaction(
        () => [this.settings.sfx, this.settings.music, this.settings.muted] as const,
        ([s, m, mu]) => audio.setVolumes(s, m, mu),
        { fireImmediately: true },
      ),
    );
    this.fx.quality = settings.quality === "low" ? 0.5 : settings.quality === "medium" ? 0.8 : 1;
    this.ambient.quality = this.fx.quality;
    this.world.difficulty = settings.difficultyMul;
    if (d.pos.dungeon) {
      const poi = this.findPoi(d.pos.dungeon.poiId);
      if (poi) {
        this.dungeonReturn = override?.dungeonReturn ?? { x: poi.x + 6, z: poi.z + 6 };
        this.enterDungeon(poi, d.pos.dungeon.floor, true);
      }
    }
    const isMobile = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent) || matchMedia("(pointer: coarse)").matches;
    if (isMobile) {
      this.camDist = 11.5;
      this.camPitch = 0.8;
    }
  }

  // ───────────────────────── жизненный цикл ─────────────────────────

  start() {
    this.input.attach(this.canvas);
    this.running = true;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  /** Приостановить цикл кадров (без освобождения ресурсов). */
  pause() {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  resume() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  /**
   * WebGL-контекст восстановлен после потери: пересоздаём всё, что жило на GPU.
   * Мир, персонаж и кооператив остаются как были.
   */
  rebuildGpu() {
    const old = this.renderer;
    const r = new Renderer(this.canvas);
    r.env.dayLength = this.settings.dayLength * 60;
    r.env.timeOfDay = old.env.timeOfDay;
    for (const k of ["tx", "ty", "tz", "yaw", "pitch", "distance"] as const) r.camera[k] = old.camera[k];
    this.renderer = r;
    this.cats = new CatRenderer(r.gl);
    this.particles = new ParticleSystem(r.gl, QUALITY[this.settings.quality].particles);
    this.text = new TextRenderer(r.gl);
    this.fx = new FxSystem(this.particles);
    this.fx.quality = this.settings.quality === "low" ? 0.5 : this.settings.quality === "medium" ? 0.8 : 1;
    this.ambient = new AmbientFx(this.particles);
    this.ambient.quality = this.fx.quality;
    this.dungeonR = new DungeonRenderer(r.gl);
    r.passes.push(this.dungeonR, this.cats, this.particles, this.text);
    this.catInst.clear();
    this.kittens.clear();
    if (this.dungeon) {
      this.dungeonR.setDungeon(this.dungeon);
      r.env.dungeon = true;
      r.showWater = false;
      r.showSky = false;
      r.setWorld(null);
    } else {
      r.setWorld(this.terrain);
      this.loaded = false;
    }
    r.setQuality(this.settings.quality);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
    this.input.detach();
    this.saveNow();
    for (const d of this.disposers) d();
    this.net?.close();
    this.net = null;
    const stash = this.guestStash;
    if (stash) {
      runInAction(() => Object.assign(this.char.data, stash));
      this.guestStash = null;
    }
    audio.setMood("menu");
    this.renderer.dispose();
  }

  /** Кооперативный гость? */
  get isGuest() {
    return this.guestStash !== null;
  }

  findPoi(id: string): Poi | null {
    const reg = this.gen.regionById(id.split(":")[0]);
    return reg?.pois.find((p) => p.id === id) ?? null;
  }

  saveNow() {
    const d = this.char.data;
    if (this.guestStash) {
      // Сохраняем прогресс персонажа, но не позицию/задания в чужом мире
      this.saves.save({ ...d, ...this.guestStash } as CharacterData);
      return;
    }
    if (this.dungeon) {
      d.pos = { x: this.dungeonReturn?.x ?? this.player.x, z: this.dungeonReturn?.z ?? this.player.z, dungeon: null };
    } else d.pos = { x: this.player.x, z: this.player.z, dungeon: null };
    this.saves.save(d);
  }

  private frame = (now: number) => {
    if (!this.running) return;
    this.raf = requestAnimationFrame(this.frame);
    const rawDt = (now - this.last) / 1000;
    this.last = now;
    const dt = clamp(rawDt, 0, 0.05);
    try {
      this.step(dt, rawDt);
    } catch (e) {
      console.error(e);
    }
  };

  private step(dt: number, rawDt: number) {
    const r = this.renderer;
    const w = this.world;
    // Загрузка мира вокруг игрока
    if (!this.loaded) {
      r.camera.tx = this.player.x;
      r.camera.tz = this.player.z;
      r.camera.ty = this.player.y;
      if (!this.dungeon) r.updateWorld(30);
      const pending = this.dungeon ? 0 : r.loadingPending;
      runInAction(() => (this.hud.loading = pending > 0 ? clamp(1 - pending / 200, 0, 0.99) : 1));
      if (pending > 40) {
        r.render(0.016, (x, z) => w.groundAt(x, z));
        return;
      }
      this.loaded = true;
      runInAction(() => (this.hud.loading = 1));
      audio.play("meow");
      this.firstHints();
    }
    this.playAcc += dt;
    if (this.playAcc > 1) {
      this.char.data.stats.playTime += this.playAcc;
      this.playAcc = 0;
    }
    this.input.blocked = this.ui.modalOpen;
    this.input.cameraKeys(dt);
    this.handleActions();
    this.controlPlayer(dt);
    w.update(dt);
    if (this.net) this.net.onFrame(this, dt);
    const events = w.events;
    w.events = [];
    this.processEvents(events);
    if (this.net) this.net.onEvents(this, events);
    this.updateLoot(dt);
    this.updateCamera(dt);
    this.updateEnvironment(dt);
    if (!this.dungeon) r.updateWorld(this.settings.quality === "low" ? 3 : 5);
    this.buildScene(dt);
    r.render(dt, (x, z) => w.groundAt(x, z));
    this.hudT -= dt;
    if (this.hudT <= 0) {
      this.hudT = 0.1;
      this.syncHud();
    }
    this.hud.tick(dt);
    this.saveT += dt;
    if (this.saveT > 20) {
      this.saveT = 0;
      this.saveNow();
    }
    // Динамическое разрешение (?nodyn — выключить, для скриншотов)
    if (this.noDyn) return;
    this.fpsAcc += rawDt;
    this.fpsN++;
    this.dynScaleT += rawDt;
    if (this.dynScaleT > 2) {
      const fps = this.fpsN / this.fpsAcc;
      if (fps < 40 && r.dynScale > 0.6) r.dynScale -= 0.08;
      else if (fps > 56 && r.dynScale < 1) r.dynScale += 0.04;
      // Разрешение уже минимальное, а кадров всё равно мало — снимаем эффекты по одному
      if (fps < 28 && r.dynScale <= 0.61) {
        this.slowT += this.dynScaleT;
        if (this.slowT > 6) {
          this.slowT = 0;
          if (r.degrade()) console.info(`[perf] low FPS (${fps.toFixed(0)}), effects reduced, step ${r.degradeStep}`);
        }
      } else this.slowT = 0;
      this.dynScaleT = 0;
    }
  }

  /** Подсказки новичку: первый навык и куда идти. */
  private firstHints() {
    if (this.hinted) return;
    this.hinted = true;
    const d = this.char.data;
    const hasActive = d.learned.some((id) => this.char.tree.get(id)?.kind === "active");
    if (!hasActive && d.skillPoints > 0) {
      const touch = this.input.isTouch || matchMedia("(pointer: coarse)").matches;
      setTimeout(
        () =>
          this.hud.toast(
            touch
              ? { ru: "Нажмите ☰ у миникарты → «Навыки» или «+1» на портрете и выберите первый навык!", en: "Tap ☰ by the minimap → Skills, or +1 on the portrait, and pick your first skill!" }
              : { ru: "Откройте дерево навыков [K] и выберите первый навык!", en: "Open the skill tree [K] and pick your first skill!" },
            0xffd24a,
            "✨",
          ),
        1500,
      );
    }
  }

  // ───────────────────────── ввод и управление ─────────────────────────

  private handleActions() {
    for (const a of this.input.takeActions()) {
      switch (a) {
        case "inventory":
        case "skills":
        case "map":
        case "quests":
        case "character":
          this.ui.open(a);
          audio.play("click");
          break;
        case "menu":
          if (this.ui.confirm) this.ui.confirm = null;
          else if (this.ui.lore) this.ui.lore = null;
          else if (this.ui.panel) this.ui.close();
          else this.ui.open("menu");
          break;
        case "interact":
          if (!this.ui.modalOpen) this.doInteract();
          break;
        case "meow":
          this.meow();
          break;
        default:
          if (a.startsWith("skill") && !this.ui.modalOpen) this.castSlot(parseInt(a.slice(5)), null, null);
      }
    }
    for (const c of this.input.takeCasts()) if (!this.ui.modalOpen) this.castSlot(c.slot, c.dx, c.dz);
  }

  meow() {
    const p = this.player;
    p.action = "meow";
    p.actionT = 0;
    p.actionDur = 0.7;
    audio.play("meow", p.x, p.z, 1, 1 / p.look.size);
    this.fx.handle({ k: "cast", x: p.x, y: p.y + 1.2, z: p.z, v: { color: 0xffd24a, color2: 0xffffff, shape: "note", size: 1, trail: false, glow: 1, style: 0 } });
    this.net?.onMeow?.(this);
  }

  /** Отдых вне боя: кот мурлычет, вокруг поднимаются сердечки, полоски на HUD мерцают. */
  private restCue(dt: number) {
    const p = this.player;
    const hurtHp = p.hp < p.maxHp - 0.5;
    const on = restFactor(this.world.time - p.lastCombat) > 0.5 && (hurtHp || p.mp < p.maxMp - 0.5);
    // Мурлыканье — не после каждой стычки, а когда кот правда потрёпан
    if (on && !this.resting && (p.hp < p.maxHp * 0.85 || p.mp < p.maxMp * 0.6) && this.world.time - this.purrAt > 12) {
      this.purrAt = this.world.time;
      audio.purr(1.6, 0.16);
      this.floater(p.x, p.y + 1.9 * p.look.size, p.z, tr({ ru: "мрр…", en: "purr…" }), 0xffc8e0, 16);
    }
    this.resting = on;
    if (!on) return;
    this.restT -= dt;
    if (this.restT > 0) return;
    this.restT = 0.3;
    const a = Math.random() * Math.PI * 2;
    this.particles.emit({ x: p.x + Math.cos(a) * 0.45, y: p.y + 0.4 + Math.random() * 0.6, z: p.z + Math.sin(a) * 0.45, vy: 0.9, life: 1.1, size: 0.16, size1: 0.05, color: hurtHp ? 0x7ee081 : 0x6ac0ff, color1: 0xffffff, shape: hurtHp ? "heart" : "bubble", drag: 0.5 });
  }

  private moveWorldFromInput(): [number, number] {
    const mv = this.input.moveVector();
    const yaw = this.camYaw;
    const fx = -Math.sin(yaw),
      fz = -Math.cos(yaw);
    const rx = Math.cos(yaw),
      rz = -Math.sin(yaw);
    return [rx * mv.x + fx * mv.y, rz * mv.x + fz * mv.y];
  }

  /** Автоприцел: ближайший враг впереди в радиусе. */
  autoTarget(range: number): Entity | null {
    const p = this.player;
    const cur = this.targetId >= 0 ? this.world.entities.get(this.targetId) : null;
    if (cur && cur.alive && isHostile(cur, p) && dist(cur.x, cur.z, p.x, p.z) <= range + 2) return cur;
    let best: Entity | null = null;
    let bs = Infinity;
    const fx = Math.sin(p.yaw),
      fz = Math.cos(p.yaw);
    for (const e of this.world.entities.values()) {
      if (!e.alive || !isHostile(e, p)) continue;
      const dx = e.x - p.x,
        dz = e.z - p.z;
      const d = Math.hypot(dx, dz);
      if (d > range) continue;
      const facing = (dx * fx + dz * fz) / Math.max(d, 0.01);
      const score = d * (1.6 - facing * 0.6) + (e.enemy?.boss ? -3 : 0);
      if (score < bs) {
        bs = score;
        best = e;
      }
    }
    return best;
  }

  private skillRange(s: SkillDef): number {
    const p = s.params;
    switch (s.delivery) {
      case "strike":
      case "cone":
        return Math.max(p.radius, 3) + 5;
      case "nova":
      case "aura":
      case "orbit":
      case "buff":
      case "heal":
      case "barrier":
      case "summon":
        return 12;
      case "dash":
      case "leap":
      case "blink":
        return p.range + 2;
      default:
        return Math.max(p.range, 8);
    }
  }

  castSlot(slot: number, dx: number | null, dz: number | null) {
    const id = this.char.data.slots[slot];
    if (!id) return;
    const skill = this.char.skills.get(id);
    if (!skill) return;
    this.castSkill(skill, dx, dz);
  }

  castSkill(skill: SkillDef, dx: number | null, dz: number | null) {
    const p = this.player;
    if (!p.alive) return;
    let ax: number, az: number;
    let tid = -1;
    const range = this.skillRange(skill);
    if (dx !== null && dz !== null) {
      ax = p.x + dx;
      az = p.z + dz;
      const t = this.world.nearestHostileTo(ax, az, p.faction, 3);
      if (t) tid = t.id;
    } else if (this.aim && !this.input.isTouch && this.input.mouseInside) {
      ax = this.aim.x;
      az = this.aim.z;
      tid = this.hoverTarget;
    } else {
      const t = this.settings.autoAim ? this.autoTarget(range) : null;
      if (t) {
        ax = t.x;
        az = t.z;
        tid = t.id;
        this.targetId = t.id;
      } else {
        ax = p.x + Math.sin(p.yaw) * Math.min(6, range);
        az = p.z + Math.cos(p.yaw) * Math.min(6, range);
      }
    }
    if (skill.target === "self") {
      if (skill.delivery !== "nova" && skill.delivery !== "aura" && skill.delivery !== "orbit") {
        ax = ax ?? p.x;
        az = az ?? p.z;
      }
    }
    const res = this.world.tryCast(p, skill, ax, az, tid);
    if (res === "ok") {
      if (!skill.basic) this.fx.handle({ k: "cast", x: p.x, y: p.y, z: p.z, v: skill.visual });
      this.net?.onLocalCast(this, skill, ax, az, tid);
    } else if (res === "mana" && this.noManaT <= 0) {
      this.noManaT = 1.5;
      this.hud.toast({ ru: "Не хватает маны", en: "Not enough mana" }, 0x5aa8ff);
    }
  }

  private basicCast(skill: SkillDef, ax: number, az: number, tid: number) {
    if (this.world.tryCast(this.player, skill, ax, az, tid) === "ok") this.net?.onLocalCast(this, skill, ax, az, tid);
  }

  private controlPlayer(dt: number) {
    const p = this.player;
    this.noManaT -= dt;
    // Смерть и воскрешение
    if (!p.alive) {
      p.moveX = p.moveZ = 0;
      this.resting = false;
      this.deadT += dt;
      if (this.deadT > 5) this.respawn();
      return;
    }
    this.deadT = 0;
    this.restCue(dt);
    const [mx, mz] = this.moveWorldFromInput();
    p.moveX = mx;
    p.moveZ = mz;
    // Прицел мышью
    this.aim = null;
    this.hoverTarget = -1;
    if (!this.input.isTouch && this.input.mouseInside) {
      const g = this.renderer.camera.pickGround(this.input.mouseX, this.input.mouseY, (x, z) => this.world.groundAt(x, z));
      if (g) {
        this.aim = { x: g.x, z: g.z };
        const t = this.world.nearestHostileTo(g.x, g.z, p.faction, 2.2);
        if (t) {
          this.hoverTarget = t.id;
          this.aim = { x: t.x, z: t.z };
        }
      }
    }
    // Базовая атака
    const basic = this.char.basicSkill;
    const wantAttack = (this.input.lmb && !this.ui.modalOpen) || this.input.attackHeld || this.input.touchAttack;
    if (wantAttack && !this.ui.modalOpen) {
      if (this.aim && this.input.lmb) {
        if (this.hoverTarget >= 0) this.targetId = this.hoverTarget;
        this.basicCast(basic, this.aim.x, this.aim.z, this.hoverTarget);
      } else {
        const t = this.autoTarget(basic.delivery === "strike" ? 9 : basic.params.range);
        if (t) {
          this.targetId = t.id;
          const d = dist(p.x, p.z, t.x, t.z);
          const reach = basic.delivery === "strike" ? basic.params.radius + t.radius * 0.7 : basic.params.range;
          if (d > reach && mx === 0 && mz === 0) {
            p.moveX = (t.x - p.x) / d;
            p.moveZ = (t.z - p.z) / d;
          } else this.basicCast(basic, t.x, t.z, t.id);
        } else this.basicCast(basic, p.x + Math.sin(p.yaw) * 3, p.z + Math.cos(p.yaw) * 3, -1);
      }
    }
    // Разворот
    if (!p.cast || p.cast.released) {
      if (p.moveX !== 0 || p.moveZ !== 0) p.yaw = dampAngle(p.yaw, Math.atan2(p.moveX, p.moveZ), 14, dt);
    }
    const tgt = this.targetId >= 0 ? this.world.entities.get(this.targetId) : null;
    if (!tgt || !tgt.alive || dist(tgt.x, tgt.z, p.x, p.z) > 30) this.targetId = -1;
    // Взаимодействие
    this.findInteract();
  }

  private respawn() {
    const p = this.player;
    const d = this.char.data;
    if (this.dungeon && this.net?.connected) {
      // В кооперативе очнёмся у входа в подземелье, чтобы не разлучаться
      const dg = this.dungeon;
      this.world.dropClimb(p);
      p.x = dg.start.x;
      p.z = dg.start.z;
      p.alive = true;
      p.state = "alive";
      p.hp = p.maxHp * 0.6;
      p.mp = p.maxMp;
      p.invuln = 3;
      p.statuses.length = 0;
      d.stats.deaths++;
      this.char.touch();
      this.hud.toast({ ru: "Вы очнулись у входа в подземелье", en: "You wake up at the dungeon entrance" }, 0xffb454, "💫");
      this.world.emit({ t: "respawn", id: p.id });
      return;
    }
    if (this.dungeon) this.exitDungeon(true);
    let x = this.gen.start.x,
      z = this.gen.start.z;
    // Ближайший открытый город
    let best = Infinity;
    for (const tid of d.discovered) {
      const reg = this.gen.regionById(tid.split(":")[0]);
      const t = reg?.town;
      if (!t) continue;
      const dd = dist(t.x, t.z, p.x, p.z);
      if (dd < best) {
        best = dd;
        x = t.x + 3;
        z = t.z + 5;
      }
    }
    if (best === Infinity) {
      const reg = this.gen.regionAt(this.gen.start.x, this.gen.start.z);
      if (reg.town) {
        x = reg.town.x + 3;
        z = reg.town.z + 5;
      }
    }
    this.world.dropClimb(p);
    p.x = x;
    p.z = z;
    p.alive = true;
    p.state = "alive";
    p.hp = p.maxHp;
    p.mp = p.maxMp;
    p.invuln = 3;
    p.statuses.length = 0;
    const lost = Math.floor(d.fish * 0.1);
    d.fish -= lost;
    d.stats.deaths++;
    this.char.touch();
    this.loaded = false;
    this.renderer.camera.tx = x;
    this.renderer.camera.tz = z;
    this.hud.toast({ ru: `Вы очнулись в городе. Потеряно рыбок: ${lost}`, en: `You wake up in town. Fish lost: ${lost}` }, 0xffb454, "🐟");
    this.world.emit({ t: "respawn", id: p.id });
  }

  // ───────────────────────── взаимодействия ─────────────────────────

  /** Залезть по кнопке: «вперёд» на экране — вверх по стволу (или текущий ввод, если он есть). */
  private climbFromCamera(tree: ClimbAnchor) {
    const [mx, mz] = this.moveWorldFromInput();
    if (mx || mz) this.world.startClimb(this.player, tree, mx, mz);
    else this.world.startClimb(this.player, tree, -Math.sin(this.camYaw), -Math.cos(this.camYaw));
  }

  private findInteract() {
    const p = this.player;
    let best: InteractTarget | null = null;
    let bd = Infinity;
    // На дереве единственное действие — спрыгнуть
    if (p.climb) {
      const c = p.climb;
      this.interactTarget =
        c.phase === "leap"
          ? null
          : {
              kind: "climb",
              label: c.phase === "perch" ? { ru: "Спрыгнуть", en: "Jump down" } : { ru: "Спрыгнуть с дерева", en: "Jump off" },
              id: "climb-off",
              x: p.x,
              z: p.z,
              run: () => {
                const cam = this.renderer.camera;
                // Прыжок «от камеры», если не задано направление
                const [mx, mz] = this.moveWorldFromInput();
                if (mx || mz) this.world.leapFromTree(p, mx, mz);
                else this.world.leapFromTree(p, p.x - cam.ex, p.z - cam.ez);
              },
            };
      return;
    }
    const consider = (t: InteractTarget, r: number) => {
      const d = dist(p.x, p.z, t.x, t.z);
      if (d < r && d < bd) {
        bd = d;
        best = t;
      }
    };
    for (const e of this.world.entities.values()) {
      if (e.kind !== "npc" || !e.npc) continue;
      if (Math.abs(e.x - p.x) > 4 || Math.abs(e.z - p.z) > 4) continue;
      const npc = e;
      consider({ kind: "npc", label: { ru: `Поговорить: ${npc.name.ru}`, en: `Talk: ${npc.name.en}` }, id: String(e.id), x: e.x, z: e.z, run: () => this.talkTo(npc) }, 3.2);
    }
    for (const n of this.quests.gatherNodes()) {
      if (Math.abs(n.x - p.x) > 3 || Math.abs(n.z - p.z) > 3) continue;
      const node = n;
      consider({ kind: "gather", label: { ru: "Собрать", en: "Gather" }, id: `${n.questId}:${n.idx}`, x: n.x, z: n.z, run: () => this.gather(node) }, 2.4);
    }
    for (const k of this.quests.rescueTargets()) {
      const kk = k;
      consider({ kind: "rescue", label: { ru: `Позвать: ${k.name.ru}`, en: `Call ${k.name.en}` }, id: k.questId, x: k.x, z: k.z, run: () => this.rescueKitten(kk.questId, kk.x, kk.z) }, 3);
    }
    if (this.dungeon) {
      const d = this.dungeon;
      const guest = this.net?.role === "guest";
      const next = () => (guest ? this.askHost("stairs") : this.nextFloor());
      const leave = () => (guest ? this.askHost("exit") : this.exitDungeon(false));
      if (d.stairs) consider({ kind: "stairs", label: { ru: "Спуститься ниже", en: "Go deeper" }, id: "stairs", x: d.stairs.x, z: d.stairs.z, run: next }, 3);
      if (d.exitPortal) consider({ kind: "exit", label: { ru: "Выйти из подземелья", en: "Leave the dungeon" }, id: "exit", x: d.exitPortal.x, z: d.exitPortal.z, run: leave }, 3.2);
      consider({ kind: "exit", label: { ru: "Выход наружу", en: "Exit" }, id: "exit0", x: d.start.x, z: d.start.z - TILE * 0.8, run: leave }, 1.6);
      d.chests.forEach((c, i) => {
        if (!c.opened) consider({ kind: "chest", label: { ru: "Открыть сундук", en: "Open chest" }, id: `dc${i}`, x: c.x, z: c.z, run: () => this.openDungeonChest(i) }, 2.6);
      });
    } else {
      const reg = this.gen.regionAt(p.x, p.z);
      const town = reg.town;
      if (town && dist(p.x, p.z, town.x, town.z) < 6)
        consider({ kind: "waystone", label: { ru: "Путевой камень", en: "Waystone" }, id: town.id, x: town.x, z: town.z, run: () => this.useWaystone(town.id) }, 3.5);
      for (const poi of reg.pois) {
        if (Math.abs(poi.x - p.x) > 12 || Math.abs(poi.z - p.z) > 12) continue;
        const pp = poi;
        switch (poi.kind) {
          case "dungeon":
            consider({ kind: "dungeon", label: { ru: `Войти: ${poi.name.ru} (ур. ${poi.level})`, en: `Enter: ${poi.name.en} (Lv ${poi.level})` }, id: poi.id, x: poi.x, z: poi.z, run: () => (this.net?.role === "guest" ? this.askHost("dungeon", pp.id) : this.askEnterDungeon(pp)) }, 7);
            break;
          case "treasure":
          case "camp":
            if (!this.char.data.cleared.includes(poi.id + ":chest")) {
              const b = poi.buildings.find((b) => b.kind === "chest");
              if (b) consider({ kind: "chest", label: { ru: "Открыть сундук", en: "Open chest" }, id: poi.id, x: b.x, z: b.z, run: () => this.openChest(pp) }, 2.6);
            }
            break;
          case "shrine":
            consider({ kind: "shrine", label: { ru: "Помолиться у святилища", en: "Pray at the shrine" }, id: poi.id, x: poi.x, z: poi.z, run: () => this.useShrine(pp) }, 3.2);
            break;
          case "obelisk":
            consider({ kind: "obelisk", label: { ru: "Прочитать камень", en: "Read the stone" }, id: poi.id, x: poi.x, z: poi.z, run: () => this.readObelisk(pp) }, 3.2);
            break;
          case "waystone":
            consider({ kind: "waystone", label: { ru: "Путевой камень", en: "Waystone" }, id: poi.id, x: poi.x, z: poi.z, run: () => this.useWaystone(poi.id) }, 3.2);
            break;
        }
      }
    }
    // Деревья и когтеточки: кот умеет лазить
    if (!this.dungeon && p.alive && !p.swimming) {
      const tree = this.world.findClimbable(p.x, p.z, 1.5);
      if (tree) {
        const base = { x: tree.x, z: tree.z };
        const label: Txt = tree.building ? { ru: "Залезть на когтеточку", en: "Climb the cat tree" } : { ru: "Залезть на дерево", en: "Climb the tree" };
        const d = Math.max(0.1, dist(p.x, p.z, base.x, base.z) - 0.9);
        if (d < bd) {
          bd = d;
          best = { kind: "climb", label, id: `climb:${Math.round(tree.x * 10)}:${Math.round(tree.z * 10)}`, x: base.x, z: base.z, run: () => this.climbFromCamera(tree) };
        }
        if (!this.climbHinted && this.loaded) {
          this.climbHinted = true;
          const touch = this.input.isTouch || matchMedia("(pointer: coarse)").matches;
          this.hud.toast(
            touch
              ? { ru: "Коты лазят по деревьям! Нажмите 👆 или упритесь в ствол", en: "Cats climb trees! Tap 👆 or push into the trunk" }
              : { ru: "Коты лазят по деревьям! Нажмите [E] или упритесь в ствол", en: "Cats climb trees! Press [E] or push into the trunk" },
            0x9ad86a,
            "🌳",
          );
        }
      }
    }
    this.interactTarget = best;
  }

  /** Гость: попросить хоста о переходе. */
  private askHost(k: "dungeon" | "exit" | "stairs", poiId?: string) {
    this.net?.request?.(k, poiId);
    this.hud.toast({ ru: `Запрос отправлен: ${this.net?.partnerName ?? "хост"} должен подтвердить`, en: `Request sent: ${this.net?.partnerName ?? "the host"} must confirm` }, 0x8fd0ff, "🤝");
  }

  doInteract() {
    const t = this.interactTarget;
    if (!t) return;
    audio.unlock();
    t.run();
  }

  talkTo(npc: Entity) {
    if (!npc.npc) return;
    this.quests.onTalk(npc.npc.npcId);
    audio.play("meow", npc.x, npc.z, 0.8, 1 / npc.look.size);
    npc.action = "wave";
    npc.actionT = 0;
    npc.actionDur = 1.2;
    npc.state = "alive";
    const greetings: Txt[] = [
      { ru: "Мур-мяу! Чем могу помочь?", en: "Mrr-meow! How can I help?" },
      { ru: "Привет, путник. Хорошая сегодня погода для сна на солнышке.", en: "Hello, traveler. Great weather for a sunbeam nap." },
      { ru: "О! Новое лицо. Точнее, новая морда!", en: "Oh! A new face. Or rather, a new muzzle!" },
      { ru: "Не видел мою рыбку? Нет? Ну ладно…", en: "Have you seen my fish? No? Oh well…" },
      { ru: "Мр-р. Осторожнее за стенами города.", en: "Mrr. Be careful beyond the town walls." },
    ];
    const g = greetings[hashInts(npc.id, Math.floor(this.world.time / 30)) % greetings.length];
    this.ui.openDialog({ npcEntityId: npc.id, npcId: npc.npc.npcId, townId: npc.npc.townId, name: npc.name, role: npc.npc.role, greeting: g, questId: null });
  }

  private gather(n: GatherNode) {
    this.quests.gather(n);
    this.player.action = "bite";
    this.player.actionT = 0;
    this.player.actionDur = 0.5;
    this.fx.handle({ k: "loot", x: n.x, y: this.world.groundAt(n.x, n.z) + 0.5, z: n.z, color: n.color });
    audio.play("pickup");
  }

  private rescueKitten(questId: string, x: number, z: number) {
    this.quests.rescue(questId);
    this.fx.handle({ k: "levelup", x, y: this.world.groundAt(x, z), z, color: 0xff9ac8 });
    audio.play("meow", x, z, 1, 1.6);
    this.hud.toast({ ru: "Котёнок найден! Возвращайтесь к квестодателю.", en: "Kitten found! Return to the quest giver." }, 0xff9ac8, "🐱");
  }

  private useWaystone(id: string) {
    const d = this.char.data;
    const townId = id.includes(":t") ? id : id;
    if (!d.discovered.includes(townId)) {
      d.discovered.push(townId);
      this.char.touch();
      this.hud.toast({ ru: "Путевой камень открыт!", en: "Waystone discovered!" }, 0x8fd0ff, "✨");
      this.fx.handle({ k: "portal", x: this.player.x, y: this.player.y, z: this.player.z, color: 0x8fd0ff });
      audio.play("portal", this.player.x, this.player.z);
    }
    this.ui.open("travel");
  }

  /** Быстрое перемещение к открытому путевому камню. */
  travelTo(id: string) {
    let x: number | null = null,
      z: number | null = null;
    const reg = this.gen.regionById(id.split(":")[0]);
    if (!reg) return;
    if (reg.town && reg.town.id === id) {
      x = reg.town.x + 3;
      z = reg.town.z + 4;
    } else {
      const poi = reg.pois.find((p) => p.id === id);
      if (poi) {
        x = poi.x + 3;
        z = poi.z + 3;
      }
    }
    if (x === null || z === null) return;
    if (this.dungeon && this.net?.role === "guest") {
      // Гость не может уйти из общего подземелья в одиночку
      this.hud.toast({ ru: "Сначала выйдите из подземелья вместе с хостом", en: "Leave the dungeon together with the host first" }, 0xffb454, "🤝");
      return;
    }
    if (this.dungeon) this.exitDungeon(true);
    this.fx.handle({ k: "portal", x: this.player.x, y: this.player.y, z: this.player.z, color: 0x8fd0ff });
    this.world.dropClimb(this.player);
    this.player.x = x;
    this.player.z = z;
    this.player.y = this.world.groundAt(x, z);
    this.loaded = false;
    // В кооперативе мир общий: хост сам уберёт далёкие сущности и досоздаст новые
    if (!this.net?.connected) this.world.clearNonPlayers();
    this.loot.length = 0;
    this.ui.close();
    audio.play("portal");
    this.saveNow();
  }

  private openChest(poi: Poi) {
    const d = this.char.data;
    d.cleared.push(poi.id + ":chest");
    this.char.touch();
    const rng = new Rng(hashStr(poi.id + d.id));
    const b = poi.buildings.find((b) => b.kind === "chest")!;
    this.dropLoot(b.x, b.z, poi.level, rng, 1.5, 2 + (poi.kind === "treasure" ? 1 : 0), 6);
    audio.play("open");
    this.fx.handle({ k: "loot", x: b.x, y: b.y + 0.8, z: b.z, color: 0xffd24a });
  }

  private openDungeonChest(i: number) {
    const d = this.dungeon!;
    const c = d.chests[i];
    c.opened = true;
    d.version++;
    const rng = new Rng(hashInts(d.poi.seed, d.floor, i, Date.now() & 0xffff));
    this.dropLoot(c.x, c.z, d.level, rng, 1.5 + c.rarityBoost, 2 + c.rarityBoost, 10);
    audio.play("open");
    this.fx.handle({ k: "loot", x: c.x, y: 1, z: c.z, color: 0xffd24a });
  }

  private useShrine(poi: Poi) {
    const cd = this.shrineCd.get(poi.id) ?? 0;
    if (this.world.time < cd) {
      this.hud.toast({ ru: "Святилище ещё не восстановило силы", en: "The shrine is still recharging" }, 0xa0a0a8);
      return;
    }
    this.shrineCd.set(poi.id, this.world.time + 180);
    const rng = new Rng(poi.seed);
    const buffs: { stat: "power" | "haste" | "moveSpeed" | "armor" | "crit"; name: Txt }[] = [
      { stat: "power", name: { ru: "Сила льва", en: "Lion's Might" } },
      { stat: "haste", name: { ru: "Кошачья мята", en: "Catnip Rush" } },
      { stat: "moveSpeed", name: { ru: "Лёгкие лапы", en: "Light Paws" } },
      { stat: "armor", name: { ru: "Толстая шкура", en: "Thick Hide" } },
      { stat: "crit", name: { ru: "Зоркий глаз", en: "Keen Eye" } },
    ];
    const b = rng.pick(buffs);
    this.world.addStatus(this.player, { kind: "buff", stat: b.stat, t: 90, dur: 90, value: b.stat === "crit" ? 0.15 : 0.3, key: "shrine" });
    this.hud.toast({ ru: `Благословение: ${b.name.ru} (90 с)`, en: `Blessing: ${b.name.en} (90s)` }, 0xffd27a, "✨");
    this.fx.handle({ k: "buff", x: this.player.x, y: this.player.y, z: this.player.z, v: { color: 0xffd27a, color2: 0xffffff, shape: "star", size: 1, trail: false, glow: 1, style: 0 } });
    audio.play("cast_buff");
  }

  private readObelisk(poi: Poi) {
    const d = this.char.data;
    const key = poi.id + ":read";
    const first = !d.cleared.includes(key);
    const rng = new Rng(poi.seed);
    const lore: Txt[] = [
      { ru: "«Когда-то все коты мира мурлыкали в унисон. Этот звук и был солнцем.»", en: "“Once, all the cats of the world purred in unison. That sound was the sun.”" },
      { ru: "«Первый Кот сошёл с Луны по лунной дорожке и лёг спать на тёплом камне. Так появился этот камень.»", en: "“The First Cat descended from the Moon along its silver path and slept on a warm stone. This is that stone.”" },
      { ru: "«Девять жизней — не выдумка. Но каждая следующая стоит всё дороже.»", en: "“Nine lives are no myth. But each one costs more than the last.”" },
      { ru: "«Не доверяй пылесосам. Они — слуги Бездны.»", en: "“Never trust vacuum cleaners. They serve the Abyss.”" },
      { ru: "«Коробка, в которую ты не можешь поместиться, — это ещё не повод сдаваться.»", en: "“A box you cannot fit into is no reason to give up.”" },
      { ru: "«Колокольчики звенели на небе, пока их не украл тот, у кого нет дна.»", en: "“The bells rang in the sky until the one without a bottom stole them.”" },
      { ru: "«Рыба в реке — к удаче. Рыба на столе — к ещё большей удаче.»", en: "“A fish in the river brings luck. A fish on the table brings even more.”" },
      { ru: "«Смотри на красную точку. Нет, не на неё. Она — иллюзия.»", en: "“Look at the red dot. No, not that one. It is an illusion.”" },
    ];
    this.ui.lore = { title: poi.name, text: rng.pick(lore) };
    if (first) {
      d.cleared.push(key);
      const xp = Math.round(killXp(poi.level, d.level, 6));
      this.char.gainXp(xp);
      this.hud.toast({ ru: `Мудрость предков: +${fmtNum(xp)} опыта`, en: `Ancestral wisdom: +${fmtNum(xp)} XP` }, 0xc08aff, "📜");
    }
  }

  // ───────────────────────── подземелья ─────────────────────────

  askEnterDungeon(poi: Poi) {
    this.ui.ask({
      text: { ru: `Войти в подземелье «${poi.name.ru}»? Рекомендуемый уровень: ${poi.level}. Этажей: ${poi.floors}.`, en: `Enter the dungeon "${poi.name.en}"? Recommended level: ${poi.level}. Floors: ${poi.floors}.` },
      ok: () => {
        this.dungeonReturn = { x: poi.x + Math.sin(0.5) * 7, z: poi.z + Math.cos(0.5) * 7 };
        this.enterDungeon(poi, 0);
      },
      okLabel: { ru: "Войти", en: "Enter" },
    });
  }

  enterDungeon(poi: Poi, floor: number, silent = false) {
    const d = new Dungeon(poi, floor, poi.floors ?? 1);
    this.dungeon = d;
    this.world.clearNonPlayers();
    this.world.map = d;
    this.loot.length = 0;
    for (const p of this.world.players()) {
      p.x = d.start.x + (p === this.player ? 0 : 1.5);
      p.z = d.start.z;
      p.y = 0;
      p.motion = null;
      this.world.dropClimb(p);
    }
    if (this.world.authority) d.populate(this.world, this.char.data.level);
    this.dungeonR.setDungeon(d);
    const r = this.renderer;
    r.env.dungeon = true;
    r.showWater = false;
    r.showSky = false;
    r.terrain && (r.terrain.viewRadius = 0);
    this.renderer.setWorld(null);
    this.renderer.setQuality(this.settings.quality);
    this.fx.clear();
    this.char.data.pos.dungeon = { poiId: poi.id, floor };
    this.loaded = true;
    this.camPitch = Math.max(this.camPitch, 0.95);
    if (!silent) {
      this.hud.toast({ ru: `${poi.name.ru} — этаж ${floor + 1}/${poi.floors}`, en: `${poi.name.en} — floor ${floor + 1}/${poi.floors}` }, 0xc08aff, "🕳️");
      audio.play("portal");
    }
    audio.setMood("dungeon");
    this.net?.onEnterDungeon?.(this, poi, floor);
  }

  nextFloor() {
    const d = this.dungeon;
    if (!d) return;
    this.enterDungeon(d.poi, d.floor + 1);
  }

  exitDungeon(silent: boolean) {
    const d = this.dungeon;
    if (!d) return;
    this.dungeon = null;
    this.dungeonR.setDungeon(null);
    this.world.clearNonPlayers();
    this.world.map = this.world.overworld;
    this.renderer.setWorld(this.terrain);
    this.renderer.setQuality(this.settings.quality);
    const r = this.renderer;
    r.env.dungeon = false;
    r.showWater = true;
    r.showSky = true;
    const ret = this.dungeonReturn ?? { x: d.poi.x + 6, z: d.poi.z + 6 };
    for (const p of this.world.players()) {
      p.x = ret.x + (p === this.player ? 0 : 1.5);
      p.z = ret.z;
      p.y = this.world.groundAt(p.x, p.z);
    }
    this.char.data.pos.dungeon = null;
    this.loot.length = 0;
    this.fx.clear();
    this.loaded = false;
    this.camPitch = Math.min(this.camPitch, 0.85);
    if (!silent) audio.play("portal");
    this.net?.onExitDungeon?.(this);
    this.saveNow();
  }

  // ───────────────────────── события симуляции ─────────────────────────

  private isMine(id: number): boolean {
    if (id === this.player.id) return true;
    const e = this.world.entities.get(id);
    return !!(e?.minion && e.minion.ownerId === this.player.id);
  }

  processEvents(events: GameEvent[]) {
    const p = this.player;
    for (const ev of events) {
      switch (ev.t) {
        case "fx":
          this.fx.handle(ev.fx);
          break;
        case "sound":
          audio.play(ev.s, ev.x, ev.z, ev.vol ?? 1, ev.pitch ?? 1);
          break;
        case "damage": {
          if (ev.id === p.id) {
            this.floater(ev.x, ev.y, ev.z, `-${fmtNum(ev.amount)}`, 0xff5a5a, ev.dot ? 16 : 22);
            if (!ev.dot) {
              audio.play("hurt");
              this.shake = Math.min(0.4, this.shake + 0.15);
            }
          } else if (this.isMine(ev.by)) {
            if (this.settings.damageNumbers) this.floater(ev.x, ev.y, ev.z, ev.crit ? `${fmtNum(ev.amount)}!` : fmtNum(ev.amount), ev.crit ? 0xffb03a : ev.dot ? 0xd8c8a8 : 0xffffff, ev.crit ? 30 : ev.dot ? 15 : 21);
            if (!ev.dot) audio.play("hit", ev.x, ev.z, 0.6);
          }
          if (ev.id === p.id || this.isMine(ev.by)) this.combatT = 4;
          break;
        }
        case "heal":
          if (ev.id === p.id && !ev.silent && ev.amount > p.maxHp * 0.02) this.floater(ev.x, ev.y, ev.z, `+${fmtNum(ev.amount)}`, 0x7ee081, 20);
          break;
        case "dodge":
          if (ev.id === p.id || this.world.entities.get(ev.id)?.kind === "enemy") this.floater(ev.x, ev.y, ev.z, tr({ ru: "Уклон!", en: "Dodge!" }), 0xa8c8e8, 18);
          audio.play("dodge", ev.x, ev.z);
          break;
        case "text":
          this.floater(ev.x, ev.y, ev.z, tr(ev.text), ev.color, 24);
          break;
        case "death":
          this.fx.handle({ k: "death", x: ev.x, y: this.world.groundAt(ev.x, ev.z), z: ev.z });
          if (ev.kind === "enemy") this.onEnemyDeath(ev);
          if (ev.id === this.targetId) this.targetId = -1;
          break;
        case "playerDeath":
          if (ev.id === p.id) {
            this.hud.toast({ ru: "Вы потеряли сознание…", en: "You passed out…" }, 0xff5a5a, "💫");
          }
          break;
        default:
          break;
      }
    }
  }

  private floater(x: number, y: number, z: number, text: string, color: number, size: number) {
    if (this.floaters.length > 60) this.floaters.shift();
    this.floaters.push({ x, y, z, text, color, size, t: 0, life: 1.1, vy: 1.6, vx: (Math.random() - 0.5) * 0.8 });
  }

  private onEnemyDeath(ev: Extract<GameEvent, { t: "death" }>) {
    const p = this.player;
    const d = this.char.data;
    if (!p.alive && dist(p.x, p.z, ev.x, ev.z) > 60) return;
    if (dist(p.x, p.z, ev.x, ev.z) > 60) return;
    const rng = new Rng(hashInts(ev.id, Math.floor(this.world.time * 10)));
    const mul = (ev.elite ? 4 : 1) * (ev.boss ? 25 : 1) * (ev.role === "kitten" ? 0.3 : 1);
    const xp = Math.round(killXp(ev.level, d.level, mul) * (1 + this.char.stats.xpBonus));
    const before = d.level;
    const ups = this.char.gainXp(xp);
    this.floater(ev.x, this.world.groundAt(ev.x, ev.z) + 2.2, ev.z, `+${fmtNum(xp)} XP`, 0xc08aff, 16);
    if (ups > 0) this.onLevelUp(before, d.level);
    d.stats.kills++;
    // Добыча
    const luck = (ev.elite ? 1 : 0) + (ev.boss ? 3 : 0);
    const fishChance = ev.boss ? 1 : ev.elite ? 0.9 : 0.55;
    if (rng.chance(fishChance)) {
      const fish = Math.max(1, Math.round((1.5 + ev.level * 0.4) * Math.pow(priceScale(ev.level), 0.85) * (ev.elite ? 4 : 1) * (ev.boss ? 15 : 1) * (1 + this.char.stats.fishBonus) * rng.range(0.7, 1.3)));
      this.spawnDrop(ev.x, ev.z, null, fish, rng);
    }
    const itemChance = ev.boss ? 1 : ev.elite ? 0.6 : 0.085;
    const nItems = ev.boss ? rng.int(2, 3) : 1;
    for (let i = 0; i < nItems; i++) if (rng.chance(itemChance)) this.spawnDrop(ev.x, ev.z, makeGear(rng, ev.level, rollRarity(rng, luck, ev.level), d.classId), 0, rng);
    if (ev.boss && rng.chance(0.25)) this.spawnDrop(ev.x, ev.z, makeTome(ev.level), 0, rng);
    // Квесты
    const res = this.quests.onKill(ev.family, ev.x, ev.z, !!ev.elite, !!ev.boss, ev.poiId, rng);
    if (res.collected) this.floater(ev.x, this.world.groundAt(ev.x, ev.z) + 2.6, ev.z, `+1 ${tr(res.collected)}`, 0xffd24a, 16);
    // Подземелье
    if (ev.boss && this.dungeon && (ev.id === this.dungeon.bossId || (!this.world.authority && ev.poiId === this.dungeon.poi.id))) {
      this.dungeon.onBossDeath();
      this.quests.onDungeonBoss(this.dungeon.poi.id);
      if (!d.cleared.includes(this.dungeon.poi.id)) d.cleared.push(this.dungeon.poi.id);
      d.stats.dungeons++;
      d.stats.bosses++;
      this.hud.toast({ ru: "Подземелье зачищено! Открылся выход.", en: "Dungeon cleared! An exit has opened." }, 0xffd24a, "🏆");
      audio.play("quest");
    } else if (ev.boss || ev.elite) d.stats.bosses += ev.boss ? 1 : 0;
    this.char.touch();
  }

  private onLevelUp(from: number, to: number) {
    const p = this.player;
    this.world.applyStats(p, this.char.stats, 1);
    p.mp = p.maxMp;
    this.fx.handle({ k: "levelup", x: p.x, y: p.y, z: p.z });
    audio.play("levelup");
    const gained = to - from;
    this.hud.toast({ ru: `Новый уровень: ${to}! Доступно очков навыков: ${this.char.data.skillPoints}`, en: `Level up: ${to}! Skill points available: ${this.char.data.skillPoints}` }, 0xffd24a, gained > 1 ? `⭐×${gained}` : "⭐");
    runInAction(() => (this.hud.levelUpFlash = 1));
    if (this.char.data.mode.world === "continent" && this.char.data.mode.levels === "infinite") this.world.levelFloor = to;
    this.saveNow();
  }

  private spawnDrop(x: number, z: number, item: Item | null, fish: number, rng: Rng) {
    const a = rng.next() * Math.PI * 2;
    const r = 0.6 + rng.next() * 1.2;
    const dx = x + Math.cos(a) * r,
      dz = z + Math.sin(a) * r;
    this.loot.push({ id: this.lootId++, x: dx, y: this.world.groundAt(dx, dz), z: dz, item, fish, owner: "local", t: 0 });
    this.fx.handle({ k: "loot", x: dx, y: this.world.groundAt(dx, dz) + 0.3, z: dz, color: item ? RARITY_COLORS[item.rarity] : 0xffd24a });
  }

  private dropLoot(x: number, z: number, level: number, rng: Rng, luck: number, items: number, fishMul: number) {
    for (let i = 0; i < items; i++) this.spawnDrop(x, z, makeGear(rng, level, rollRarity(rng, luck, level), this.char.data.classId), 0, rng);
    this.spawnDrop(x, z, null, Math.round((3 + level) * priceScale(level) * fishMul * 0.3), rng);
  }

  private updateLoot(dt: number) {
    const p = this.player;
    for (const l of this.loot) {
      l.t += dt;
      if (!p.alive) continue;
      const d = dist(p.x, p.z, l.x, l.z);
      if (d < 1.7) {
        if (l.item) {
          if (!this.char.addItem(l.item)) {
            if (l.t % 3 < dt) this.hud.toast({ ru: "Инвентарь полон!", en: "Inventory full!" }, 0xff8a8a);
            continue;
          }
          this.hud.toast(l.item.name, RARITY_COLORS[l.item.rarity], l.item.icon);
          audio.play("pickup");
        } else if (l.fish > 0) {
          this.char.addFish(l.fish);
          this.floater(l.x, l.y + 1, l.z, `+${fmtNum(l.fish)} 🐟`, 0xffd24a, 18);
          audio.play("fish");
        }
        l.t = 1e9;
      } else if (d < 4.5 && !l.item) {
        // Рыбки подтягиваются к игроку
        l.x = lerp(l.x, p.x, dt * 4);
        l.z = lerp(l.z, p.z, dt * 4);
        l.y = this.world.groundAt(l.x, l.z);
      }
    }
    this.loot = this.loot.filter((l) => l.t < 180);
  }

  // ───────────────────────── камера и окружение ─────────────────────────

  private updateCamera(dt: number) {
    const cam = this.renderer.camera;
    const c = this.input.takeCamera();
    this.camYaw += c.yaw;
    this.camPitch = clamp(this.camPitch + c.pitch, 0.35, 1.35);
    this.camDist = clamp(this.camDist + c.zoom, 6, 30);
    const p = this.player;
    cam.tx = damp(cam.tx, p.x, 12, dt);
    cam.tz = damp(cam.tz, p.z, 12, dt);
    cam.ty = damp(cam.ty, p.y + 0.9 * p.look.size, 10, dt);
    cam.yaw = this.camYaw;
    cam.pitch = this.dungeon ? Math.max(this.camPitch, 0.95) : this.camPitch;
    cam.distance = this.dungeon ? Math.min(this.camDist, 16) : this.camDist;
    if (this.shake > 0 && this.settings.cameraShake) {
      this.shake = Math.max(0, this.shake - dt);
      cam.tx += (Math.random() - 0.5) * this.shake * 0.5;
      cam.tz += (Math.random() - 0.5) * this.shake * 0.5;
    }
    audio.setListener(p.x, p.z);
    // Деревья и дома между камерой и котом становятся «прозрачными»
    const f = this.renderer.focus ?? (this.renderer.focus = { x: 0, y: 0, z: 0, r: 0 });
    f.x = p.x;
    f.y = p.y + 0.7 * p.look.size;
    f.z = p.z;
    f.r = this.dungeon ? 0 : 1.6;
  }

  private updateEnvironment(dt: number) {
    this.combatT = Math.max(0, this.combatT - dt);
    audio.setCombat(this.combatT > 0 ? 1 : 0);
    const p = this.player;
    this.visitT -= dt;
    if (this.visitT <= 0) {
      this.visitT = 0.5;
      this.quests.onVisit(p.x, p.z);
    }
    if (this.dungeon) {
      this.renderer.playerLight = { x: p.x, y: p.y + 2.2, z: p.z, r: 22 };
      return;
    }
    this.renderer.playerLight = { x: p.x, y: p.y + 2.5, z: p.z, r: 14 };
    const reg = this.gen.regionAt(p.x, p.z);
    const biomeId = this.gen.biomeIdAt(p.x, p.z);
    const biome = BIOMES[biomeId];
    this.renderer.env.setBiomeFog(biome.fog);
    this.renderer.env.setBiomeAtmosphere(BIOME_ATMOSPHERE[biomeId] ?? BIOME_ATMOSPHERE.meadow);
    const cam = this.renderer.camera;
    this.ambient.update(dt, biomeId, cam.tx, cam.ty, cam.tz, this.renderer.env);
    const pcx = Math.floor(p.x / CHUNK),
      pcz = Math.floor(p.z / CHUNK);
    const near = this.nearBuildings;
    near.length = 0;
    for (let dz = -1; dz <= 1; dz++)
      for (let dx = -1; dx <= 1; dx++) {
        if (!this.terrain.hasContent(pcx + dx, pcz + dz)) continue;
        for (const b of this.terrain.content(pcx + dx, pcz + dz).buildings) near.push(b);
      }
    this.ambient.chimneys(dt, near, p.x, p.z, this.renderer.env);
    this.renderer.waterColor = biome.water;
    this.renderer.lava = biomeId === "volcanic";
    audio.setMood(biome.mood);
    if (reg.id !== this.lastRegion) {
      this.lastRegion = reg.id;
      this.hud.toast({ ru: `${reg.name.ru} · ур. ${reg.level}`, en: `${reg.name.en} · Lv ${reg.level}` }, 0xe8e2d8, "🗺️");
    }
    const town = reg.town;
    const inTown = town && dist(p.x, p.z, town.x, town.z) < town.radius + 10;
    if (inTown && town.id !== this.lastTown) {
      this.lastTown = town.id;
      this.hud.toast({ ru: `Добро пожаловать в ${town.name.ru}!`, en: `Welcome to ${town.name.en}!` }, 0xffd27a, "🏠");
      if (!this.char.data.discovered.includes(town.id)) {
        this.char.data.discovered.push(town.id);
        this.char.touch();
      }
    } else if (!inTown && this.lastTown && town?.id !== this.lastTown) this.lastTown = "";
  }

  // ───────────────────────── сцена ─────────────────────────

  private buildScene(dt: number) {
    const r = this.renderer;
    const cam = r.camera;
    const w = this.world;
    const p = this.player;
    this.cats.begin(cam.ox, cam.oz, dt);
    this.text.begin(cam.ox, cam.oz);
    this.text.scale = this.settings.hudScale;
    this.particles.setOrigin(cam.ox, cam.oz);
    const shadows = (r.shadows.length = 0, r.shadows);
    const lights: PointLight[] = (r.lights.length = 0, r.lights);
    const decals: Decal[] = (r.decals.length = 0, r.decals);
    const ex = cam.ex,
      ez = cam.ez;
    const seen = new Set<number>();
    for (const e of w.entities.values()) {
      const dCam = Math.hypot(e.x - ex, e.z - ez);
      if (dCam > 85) continue;
      if (!cam.sphereVisible(e.x, e.y + 0.6 * e.look.size, e.z, 1.6 * e.look.size)) {
        if (e.alive) shadows.push({ x: e.x, y: e.y, z: e.z, r: 0.75 * e.look.size });
        continue;
      }
      let ci = this.catInst.get(e.id);
      if (!ci) {
        ci = makeCatInstance(e.id, e.look);
        this.catInst.set(e.id, ci);
      }
      seen.add(e.id);
      ci.look = e.look;
      ci.x = e.x;
      ci.y = e.y;
      ci.z = e.z;
      ci.yaw = e.yaw;
      ci.speed = e.speed;
      ci.action = e.action;
      ci.actionT = e.actionT;
      ci.state = e.alive ? e.state : "dead";
      ci.stateT = e.alive ? e.stateT : e.deadT;
      ci.flash = e.flash;
      ci.lookX = e.lookX;
      ci.lookZ = e.lookZ;
      ci.alpha = e.alive ? 1 : clamp(1 - (e.deadT - 2.2) / 1.5, 0, 1);
      if (e.invuln > 0 && e.kind === "player" && e.invuln > 1) ci.alpha *= 0.6 + 0.4 * Math.sin(w.time * 20);
      // Оттенки от статусов
      ci.tintAmt = 0;
      for (const s of e.statuses) {
        if (s.kind === "freeze") {
          ci.tint = 0x9ae8ff;
          ci.tintAmt = 0.65;
        } else if (s.kind === "dot" && ci.tintAmt < 0.2) {
          ci.tint = s.el === "poison" ? 0x8aff5a : s.el === "fire" ? 0xff7a2a : 0xff4a5a;
          ci.tintAmt = 0.18;
        } else if (s.kind === "charm") {
          ci.tint = 0xff9ac8;
          ci.tintAmt = 0.35;
        } else if (s.kind === "slow" && ci.tintAmt < 0.1) {
          ci.tint = 0x8ab8ff;
          ci.tintAmt = 0.12;
        }
      }
      this.cats.add(ci, dt, dCam);
      if (e.alive || e.deadT < 3) shadows.push({ x: e.x, y: e.y, z: e.z, r: 0.75 * e.look.size });
      this.entityOverlay(e, dCam);
    }
    for (const id of this.catInst.keys()) if (!seen.has(id) && !w.entities.has(id)) this.catInst.delete(id);
    // Котята для квестов спасения
    for (const k of this.quests.rescueTargets()) {
      let ci = this.kittens.get(k.questId);
      if (!ci) {
        const look = villagerLook(new Rng(hashStr(k.questId)));
        look.size = 0.55;
        look.headSize = 1.25;
        ci = makeCatInstance(900000 + (hashStr(k.questId) % 90000), look);
        ci.state = "sit";
        this.kittens.set(k.questId, ci);
      }
      ci.x = k.x;
      ci.z = k.z;
      ci.y = w.groundAt(k.x, k.z);
      ci.lookX = p.x;
      ci.lookZ = p.z;
      if (Math.random() < dt * 0.3) {
        ci.action = "meow";
        ci.actionT = 0;
        audio.play("meow", k.x, k.z, 0.7, 1.7);
      }
      if (ci.action) {
        ci.actionT += dt / 0.8;
        if (ci.actionT >= 1) ci.action = null;
      }
      const dc = Math.hypot(k.x - ex, k.z - ez);
      if (dc < 70) {
        this.cats.add(ci, dt, dc);
        shadows.push({ x: k.x, y: ci.y, z: k.z, r: 0.45 });
        if (dc < 30) this.text.text({ x: k.x, y: ci.y + 1.2, z: k.z, text: "?", color: 0xff9ac8, size: 30, alpha: 1 });
      }
    }
    // Коты на деревьях и когтеточках (только картинка)
    if (!this.dungeon) {
      const tc = this.treeCatList;
      tc.length = 0;
      this.treeCats.update(dt, w.time, this.terrain, cam.tx, cam.tz, tc);
      for (const ci of tc) {
        const dc = Math.hypot(ci.x - ex, ci.z - ez);
        if (dc > 75 || !cam.sphereVisible(ci.x, ci.y + 0.5, ci.z, 1.3)) continue;
        this.cats.add(ci, dt, dc);
        if (ci.y - w.groundAt(ci.x, ci.z) < 0.6) shadows.push({ x: ci.x, y: ci.y, z: ci.z, r: 0.55 * ci.look.size });
        if (ci.state === "perch" && dc < 14 && Math.random() < dt * 0.04) audio.play("meow", ci.x, ci.z, 0.5, 1.2 + Math.random() * 0.3);
      }
    }
    // Узлы сбора
    for (const n of this.quests.gatherNodes()) {
      if (Math.abs(n.x - p.x) > 60 || Math.abs(n.z - p.z) > 60) continue;
      const gy = w.groundAt(n.x, n.z);
      this.particles.immediateOne({ x: n.x, y: gy + 0.6 + Math.sin(w.time * 3 + n.idx) * 0.15, z: n.z, life: 1, size: 0.55, color: n.color, shape: "star", rot: w.time * 2 + n.idx });
      this.particles.immediateOne({ x: n.x, y: gy + 0.6, z: n.z, life: 1, size: 0.9, color: n.color, alpha: 0.4 });
      decals.push({ x: n.x, y: gy, z: n.z, r: 0.8, color: n.color, mode: 0, progress: 1, alpha: 0.8 });
    }
    // Добыча на земле
    for (const l of this.loot) {
      const color = l.item ? RARITY_COLORS[l.item.rarity] : 0xffd24a;
      const bob = Math.sin(w.time * 3 + l.id) * 0.1;
      this.particles.immediateOne({ x: l.x, y: l.y + 0.45 + bob, z: l.z, life: 1, size: l.item ? 0.45 : 0.4, color, shape: l.item ? (l.item.kind === "tome" ? "rune" : "diamond") : "fish", rot: w.time * 1.5 + l.id });
      if (l.item && l.item.rarity >= 2) this.particles.immediateOne({ x: l.x, y: l.y + 1.6, z: l.z, life: 1, size: 0.35, color, stretch: 6, vy: 3, alpha: 0.5 });
      decals.push({ x: l.x, y: l.y, z: l.z, r: 0.6, color, mode: 1, progress: 1, alpha: 0.7 });
    }
    // Цель и прицел
    const tgt = this.targetId >= 0 ? w.entities.get(this.targetId) : null;
    if (tgt && tgt.alive) decals.push({ x: tgt.x, y: tgt.y, z: tgt.z, r: 0.95 * tgt.look.size, color: 0xff5a4a, mode: 3, progress: 1, alpha: 1 });
    if (this.aim && !this.input.isTouch && this.input.mouseInside && !this.ui.modalOpen) decals.push({ x: this.aim.x, y: w.groundAt(this.aim.x, this.aim.z), z: this.aim.z, r: 0.45, color: 0xffffff, mode: 0, progress: 1, alpha: 0.6 });
    if (this.dragAim) {
      const d = this.dragAim;
      decals.push({ x: p.x + d.dx, y: w.groundAt(p.x + d.dx, p.z + d.dz), z: p.z + d.dz, r: d.r, color: 0x8fd0ff, mode: 2, progress: 0.5, alpha: 1 });
    }
    // Свет: фонари и костры ночью, факелы в подземелье
    this.addStaticLights(lights);
    // Точки интереса: подсветка входов в подземелья и путевых камней
    this.poiOverlays(decals);
    // Эффекты
    this.fx.frame(dt, w.projectiles, w.areas, w.entities.values(), w.time, decals, lights);
    // Всплывающие числа
    for (const f of this.floaters) {
      f.t += dt;
      f.y += f.vy * dt;
      f.x += f.vx * dt;
      f.vy *= 1 - dt * 1.5;
      const a = clamp(1 - (f.t - f.life * 0.6) / (f.life * 0.4), 0, 1);
      const pop = f.t < 0.12 ? 1 + (0.12 - f.t) * 4 : 1;
      this.text.text({ x: f.x, y: f.y, z: f.z, text: f.text, color: f.color, size: f.size * pop, alpha: a });
    }
    this.floaters = this.floaters.filter((f) => f.t < f.life);
  }

  dragAim: { dx: number; dz: number; r: number } | null = null;

  private entityOverlay(e: Entity, dCam: number) {
    const top = e.y + (1.35 + 0.25 * e.look.headSize) * e.look.size + (e.look.hat !== "none" ? 0.25 * e.look.size : 0);
    if (e.kind === "npc" && e.npc && dCam < 22) {
      const mk = this.quests.marker(e.npc.npcId, e.npc.townId);
      if (mk) this.text.text({ x: e.x, y: top + 0.6 + Math.sin(this.world.time * 3) * 0.08, z: e.z, text: mk.icon, color: mk.color, size: 40, alpha: 1 });
      if (dCam < 16) {
        const roleName = NPC_ROLE_NAMES[e.npc.role];
        this.text.text({ x: e.x, y: top + 0.15, z: e.z, text: tr(e.name), color: 0xfff6ea, size: 15, alpha: 0.95 });
        if (roleName) this.text.text({ x: e.x, y: top + 0.15, z: e.z, text: `‹${tr(roleName)}›`, color: 0xffd27a, size: 12, alpha: 0.9, oy: -14 });
      }
      return;
    }
    if (!e.alive) return;
    if (e.kind === "enemy") {
      const special = !!(e.enemy?.elite || e.enemy?.boss);
      const show = special || e.hp < e.maxHp || e.id === this.targetId || e.id === this.hoverTarget;
      if (!show || dCam > 45) return;
      const frac = e.hp / e.maxHp;
      const bw = special ? 70 : 48;
      this.text.bar(e.x, top + 0.1, e.z, bw, special ? 7 : 5, frac, e.faction === 1 ? (e.enemy?.boss ? 0xff3a5a : 0xff5a5a) : 0x7ee081, 1);
      if (special || e.id === this.targetId || e.id === this.hoverTarget) {
        const lv = e.level;
        this.text.text({ x: e.x, y: top + 0.1, z: e.z, text: `${tr(e.enemy?.named ?? e.name)} · ${lv}`, color: e.enemy?.boss ? 0xff9a5a : e.enemy?.elite ? 0xffc85a : 0xffe0d0, size: special ? 15 : 13, alpha: 1, oy: 14 });
      }
    } else if (e.kind === "player" && e !== this.player) {
      this.text.bar(e.x, top + 0.1, e.z, 50, 5, e.hp / e.maxHp, 0x7ee081, 1);
      this.text.text({ x: e.x, y: top + 0.1, z: e.z, text: tr(e.name), color: 0x9ae8ff, size: 15, alpha: 1, oy: 14 });
    } else if (e.kind === "minion" && e.hp < e.maxHp) {
      this.text.bar(e.x, top, e.z, 30, 4, e.hp / e.maxHp, 0x7ec0e0, 0.9);
    }
  }

  private addStaticLights(lights: PointLight[]) {
    const p = this.player;
    const env = this.renderer.env;
    if (this.dungeon) {
      const d = this.dungeon;
      const near = d.torches.map((t) => ({ t, d: (t.x - p.x) ** 2 + (t.z - p.z) ** 2 })).sort((a, b) => a.d - b.d);
      for (let i = 0; i < Math.min(5, near.length); i++) {
        const t = near[i].t;
        const flick = 0.85 + Math.sin(this.world.time * 9 + i * 3) * 0.08 + Math.sin(this.world.time * 23 + i) * 0.05;
        lights.push({ x: t.x - t.wx * 0.2, y: 2.0, z: t.z - t.wz * 0.2, radius: 9, color: d.style.torch, intensity: 1.2 * flick });
        if (Math.random() < 0.3) this.particles.emit({ x: t.x - t.wx * 0.12, y: 2.05, z: t.z - t.wz * 0.12, vy: 1, life: 0.4, size: 0.18, size1: 0.02, color: d.style.torch, shape: "flame" });
      }
      if (d.exitPortal) lights.push({ x: d.exitPortal.x, y: 1.7, z: d.exitPortal.z, radius: 8, color: 0x8fd0ff, intensity: 1.2 });
      if (d.stairs) lights.push({ x: d.stairs.x, y: 0.5, z: d.stairs.z, radius: 6, color: d.style.accent, intensity: 1 });
      return;
    }
    const ccx = Math.floor(p.x / CHUNK),
      ccz = Math.floor(p.z / CHUNK);
    for (let dz = -1; dz <= 1; dz++)
      for (let dx = -1; dx <= 1; dx++) {
        if (!this.terrain.hasContent(ccx + dx, ccz + dz)) continue;
        const c = this.terrain.content(ccx + dx, ccz + dz);
        for (const b of c.buildings) {
          if (b.kind === "campfire") {
            lights.push({ x: b.x, y: b.y + 1, z: b.z, radius: 9, color: 0xff9a4a, intensity: 1.3 + Math.sin(this.world.time * 8) * 0.1 });
            if (Math.random() < 0.4) this.particles.emit({ x: b.x + (Math.random() - 0.5) * 0.4, y: b.y + 0.3, z: b.z + (Math.random() - 0.5) * 0.4, vy: 2, life: 0.6, size: 0.35, size1: 0.05, color: 0xffd24a, color1: 0xff4a1a, shape: "flame" });
          } else if (b.kind === "lamp" && env.night > 0.25) {
            lights.push({ x: b.x, y: b.y + 2.5, z: b.z, radius: 8, color: 0xffd27a, intensity: env.night });
          } else if ((b.kind === "waystone" || b.kind === "shrine") && env.night > 0.2) {
            lights.push({ x: b.x, y: b.y + 2, z: b.z, radius: 7, color: b.color, intensity: env.night * 0.8 });
          }
        }
      }
  }

  private poiOverlays(decals: Decal[]) {
    if (this.dungeon) {
      const d = this.dungeon;
      if (d.stairs) {
        decals.push({ x: d.stairs.x, y: 0, z: d.stairs.z, r: 1.6, color: d.style.accent, mode: 3, progress: 1, alpha: 1 });
        if (Math.random() < 0.3) this.particles.emit({ x: d.stairs.x + (Math.random() - 0.5) * 2, y: -0.5, z: d.stairs.z + (Math.random() - 0.5) * 2, vy: 1.5, life: 1, size: 0.2, color: d.style.accent, shape: "star" });
      }
      if (d.exitPortal && Math.random() < 0.5) this.fx.handle({ k: "portal", x: d.exitPortal.x, y: 0.3, z: d.exitPortal.z, color: 0x8fd0ff });
      const ex = d.start.x,
        ez = d.start.z - TILE * 0.8;
      decals.push({ x: ex, y: 0, z: ez, r: 1.0, color: 0x8fd0ff, mode: 0, progress: 1, alpha: 0.8 });
      return;
    }
    const p = this.player;
    const reg = this.gen.regionAt(p.x, p.z);
    for (const poi of reg.pois) {
      if (Math.abs(poi.x - p.x) > 40 || Math.abs(poi.z - p.z) > 40) continue;
      if (poi.kind === "dungeon") {
        decals.push({ x: poi.x, y: poi.h, z: poi.z, r: 6.5, color: 0xc08aff, mode: 0, progress: 1, alpha: 0.5 });
        const dd = dist(p.x, p.z, poi.x, poi.z);
        if (dd < 25) this.text.text({ x: poi.x, y: poi.h + 7, z: poi.z, text: `${tr(poi.name)} · ${poi.level}`, color: 0xd8b0ff, size: 15, alpha: clamp(1 - (dd - 15) / 10, 0, 1) });
      }
    }
    const town = reg.town;
    if (town && dist(p.x, p.z, town.x, town.z) < 40) {
      decals.push({ x: town.x, y: town.h, z: town.z, r: 2.2, color: 0x8fd0ff, mode: 0, progress: 1, alpha: 0.8 });
    }
  }

  // ───────────────────────── HUD ─────────────────────────

  private syncHud() {
    const p = this.player;
    const h = this.hud;
    const d = this.char.data;
    const skills = this.char.skills;
    runInAction(() => {
      h.hp = p.hp;
      h.maxHp = p.maxHp;
      h.mp = p.mp;
      h.maxMp = p.maxMp;
      h.shield = p.shield;
      h.level = d.level;
      h.xp = d.xp;
      h.xpNeeded = this.char.xpNeeded;
      h.fish = d.fish;
      h.resting = this.resting;
      h.skillPoints = d.skillPoints;
      h.dead = !p.alive;
      h.respawnIn = Math.max(0, 5 - this.deadT);
      h.fps = Math.round(this.fpsN / Math.max(0.001, this.fpsAcc));
      this.fpsAcc = 0;
      this.fpsN = 0;
      h.playerX = p.x;
      h.playerZ = p.z;
      h.playerYaw = p.yaw;
      h.camYaw = this.camYaw;
      h.timeOfDay = this.renderer.env.timeOfDay;
      const basic = this.char.basicSkill;
      h.basicCd = Math.max(0, p.cds.get(basic.id) ?? 0);
      const cost = (s: SkillDef) => s.params.cost * (1 + 0.045 * (d.level - 1));
      h.slots = d.slots.map((id) => {
        const s = id ? skills.get(id) : undefined;
        const node = id ? this.char.tree.get(id) : undefined;
        return {
          id: id,
          cd: s ? Math.max(0, p.cds.get(s.id) ?? 0) : 0,
          cdTotal: s ? s.params.cooldown : 1,
          noMana: s ? p.mp < cost(s) && !this.char.stats.keystones.has("bloodPact") : false,
          color: s ? s.visual.color : 0x444444,
          glyph: node?.glyph ?? "",
          name: s ? s.name : null,
        };
      });
      const t = this.targetId >= 0 ? this.world.entities.get(this.targetId) : null;
      h.target = t && t.alive && t.kind === "enemy" ? { name: t.enemy?.named ?? t.name, level: t.level, hp: t.hp, maxHp: t.maxHp, elite: !!t.enemy?.elite, boss: !!t.enemy?.boss } : null;
      let boss: Entity | null = null;
      for (const e of this.world.entities.values()) {
        if (e.alive && e.enemy?.boss && e.ai && e.ai.target >= 0 && dist(e.x, e.z, p.x, p.z) < 40) boss = e;
      }
      h.boss = boss ? { name: boss.enemy?.named ?? boss.name, level: boss.level, hp: boss.hp, maxHp: boss.maxHp, elite: false, boss: true } : null;
      const it = this.interactTarget;
      h.interact = it ? { kind: it.kind, label: it.label, id: it.id } : null;
      if (this.dungeon) {
        h.inDungeon = true;
        h.dungeonName = this.dungeon.poi.name;
        h.dungeonFloor = this.dungeon.floor + 1;
        h.dungeonFloors = this.dungeon.floors;
        let left = 0;
        for (const e of this.world.entities.values()) if (e.alive && e.kind === "enemy") left++;
        h.enemiesLeft = left;
        h.regionName = this.dungeon.poi.name;
        h.regionLevel = this.dungeon.level;
      } else {
        h.inDungeon = false;
        const reg = this.gen.regionAt(p.x, p.z);
        h.regionName = reg.name;
        h.regionLevel = reg.level;
        h.townName = reg.town && dist(p.x, p.z, reg.town.x, reg.town.z) < reg.town.radius + 10 ? reg.town.name : null;
      }
      const tt = this.quests.trackedTarget();
      if (tt && !this.dungeon) {
        const ang = Math.atan2(tt.x - p.x, tt.z - p.z);
        h.compass = { angle: wrapAngle(ang - (this.camYaw + Math.PI)), dist: dist(p.x, p.z, tt.x, tt.z), label: tt.label };
      } else h.compass = null;
      h.levelUpFlash = Math.max(0, h.levelUpFlash - 0.1);
      const mate = this.net?.connected ? this.net.partner() : null;
      h.coop = mate ? { name: this.net!.partnerName, hp: mate.alive ? mate.hp : 0, maxHp: mate.maxHp, level: mate.level } : null;
    });
  }
}

export const NPC_ROLE_NAMES: Record<string, Txt | null> = {
  questgiver: null,
  merchant: { ru: "Торговец", en: "Merchant" },
  smith: { ru: "Кузнец", en: "Smith" },
  innkeeper: { ru: "Трактирщик", en: "Innkeeper" },
  trainer: { ru: "Наставник", en: "Trainer" },
  villager: null,
  guard: { ru: "Стражник", en: "Guard" },
  elder: { ru: "Старейшина", en: "Elder" },
};

export { levelScale, CLASSES };
