import { useEffect, useRef } from "react";
import { Renderer } from "../engine/renderer";
import { WorldGen } from "../game/world/worldgen";
import { TerrainCache } from "../game/world/terrain-cache";
import { CLASS_IDS, MODE_PRESETS } from "../game/types";
import { CatRenderer } from "../engine/cats";
import { CAT_ACTIONS, makeCatInstance, type CatInstance } from "../engine/cat-types";
import { classLook, villagerLook, type FurPattern } from "../game/cats/look";
import { Rng } from "../core/rng";
import { BIOME_ATMOSPHERE } from "../engine/environment";

/** Тестовый просмотрщик мира и котов (?viewer=1&cats=1&walk=1…) — для скриншотов и отладки. */
export function Viewer() {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current!;
    const r = new Renderer(canvas);
    const params = new URLSearchParams(location.search);
    const mode = params.get("mode") === "endless" ? "endless" : "campaign";
    const gen = new WorldGen(Number(params.get("seed") ?? 12345), MODE_PRESETS[mode]);
    const cache = new TerrainCache(gen);
    r.setWorld(cache);
    r.setQuality((params.get("q") as "low" | "medium" | "high") ?? "medium");
    const tod = params.get("tod");
    if (tod) r.env.timeOfDay = Number(tod);
    if (params.get("shadows") === "0") r.shadowMap = null;
    const atmo = params.get("atmo");
    if (atmo && BIOME_ATMOSPHERE[atmo]) r.env.setBiomeAtmosphere(BIOME_ATMOSPHERE[atmo]);
    if (params.get("clouds")) r.env.cloudCover = Number(params.get("clouds"));
    const town = gen.regionAt(gen.start.x, gen.start.z).town;
    const cam = r.camera;
    cam.tx = params.get("x") ? Number(params.get("x")) : town ? town.x + Number(params.get("dx") ?? 0) : gen.start.x;
    cam.tz = params.get("z") ? Number(params.get("z")) : town ? town.z + Number(params.get("dz") ?? 0) : gen.start.z;
    cam.distance = Number(params.get("dist") ?? 30);
    cam.pitch = Number(params.get("pitch") ?? 0.6);
    cam.yaw = Number(params.get("yaw") ?? 0.6);
    const catsR = new CatRenderer(r.gl);
    r.passes.push(catsR);
    const cats: CatInstance[] = [];
    if (params.get("cats")) {
      const rng = new Rng(5);
      const pats: FurPattern[] = ["tabby", "tuxedo", "calico", "siamese", "tiger", "ghost", "mecha", "lava", "crystal", "void", "skeleton", "golden", "spots", "tortie", "bicolor"];
      CLASS_IDS.forEach((c, i) => {
        const ci = makeCatInstance(i + 1, classLook(c));
        ci.x = cam.tx - 6 + i * 2;
        ci.z = cam.tz + 3;
        ci.yaw = 0.2;
        cats.push(ci);
      });
      pats.forEach((p, i) => {
        const look = villagerLook(rng);
        look.pattern = p;
        if (p === "tiger") { look.fur = 0xe8883a; look.fur2 = 0x1a1a1a; look.size = 1.4; }
        if (p === "ghost") { look.fur = 0xcfe8ff; look.fur2 = 0x8ab8ff; look.alpha = 0.7; }
        if (p === "mecha") { look.fur = 0x8a929c; look.fur2 = 0x4af0ff; }
        if (p === "lava") { look.fur = 0x2a2220; look.fur2 = 0xff6a1a; }
        if (p === "crystal") { look.fur = 0x9ae8ff; look.fur2 = 0xd08aff; }
        if (p === "void") { look.fur = 0x1a1030; look.fur2 = 0xd08aff; look.glow = 0xd08aff; }
        if (p === "skeleton") { look.fur = 0xe8e0d0; look.fur2 = 0x2a2a2a; look.glow = 0xff3a3a; }
        if (p === "golden") { look.fur = 0xf2c84a; look.fur2 = 0xf2c84a; look.mane = 0xd89a3a; }
        const ci = makeCatInstance(100 + i, look);
        ci.x = cam.tx - 14 + i * 2;
        ci.z = cam.tz - 1;
        ci.yaw = 0.3;
        cats.push(ci);
      });
    }
    let last = performance.now();
    let raf = 0;
    let t = 0;
    const loop = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      t += dt;
      cam.ty = cache.heightAt(cam.tx, cam.tz) + 1;
      if (params.get("spin")) cam.yaw += dt * 0.1;
      r.updateWorld(8);
      catsR.begin(cam.ox, cam.oz, dt);
      r.shadows.length = 0;
      cats.forEach((c, i) => {
        c.y = cache.heightAt(c.x, c.z);
        const phase = (t * 0.5 + i * 0.37) % 1;
        if (params.get("walk") && i % 3 === 0) { c.speed = 2.5; }
        else if (params.get("walk") && i % 3 === 1) { c.speed = 6; }
        if (params.get("act")) { c.action = CAT_ACTIONS[i % CAT_ACTIONS.length]; c.actionT = phase; }
        if (params.get("sit") && i % 4 === 3) c.state = "sit";
        catsR.add(c, dt, Math.hypot(c.x - cam.ex, c.z - cam.ez));
        r.shadows.push({ x: c.x, y: c.y, z: c.z, r: 0.7 * c.look.size });
      });
      // Как в игре: деревья и дома между камерой и центром кадра растворяются
      r.focus = { x: cam.tx, y: cam.ty, z: cam.tz, r: 3.5 };
      r.render(dt, (x, z) => cache.heightAt(x, z));
      (window as any).__stats = { ...r.stats, pending: r.loadingPending, cats: catsR.count };
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);
  return <canvas ref={ref} className="game" />;
}
