/** GLSL: сэмплеры массивов и таблица параметров. */
export const MATERIAL_GLSL = /* glsl */ `
uniform highp sampler2DArray uMatAlbedo;
uniform highp sampler2DArray uMatNormal;
const vec4 MAT_INFO[${MAT_COUNT}] = vec4[${MAT_COUNT}](${INFO.map((i) => `vec4(${(1 / i[0]).toFixed(5)}, ${i[1].toFixed(3)}, ${i[2].toFixed(3)}, ${i[3].toFixed(1)})`).join(", ")});
struct MatS { vec3 alb; float h; vec2 n; float ao; float spec; };
MatS matFetch(float layer, vec2 uv, vec2 dx, vec2 dy) {
  vec4 a = textureGrad(uMatAlbedo, vec3(uv, layer), dx, dy);
  vec4 b = textureGrad(uMatNormal, vec3(uv, layer), dx, dy);
  MatS s;
  s.alb = a.rgb * 2.0;
  s.h = a.a;
  s.n = b.xy * 2.0 - 1.0;
  s.ao = b.z;
  s.spec = b.w;
  return s;
}
`;

