const BAKE_LIB = /* glsl */ `
float hp(vec2 i, vec2 per) {
  i = mod(i, per);
  vec3 p3 = fract(vec3(i.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
vec2 hp2(vec2 i, vec2 per) {
  i = mod(i, per);
  vec3 p3 = fract(vec3(i.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}
// Периодический шум: p в клетках, per — период в клетках
float pn(vec2 p, vec2 per) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hp(i, per), hp(i + vec2(1.0, 0.0), per), u.x), mix(hp(i + vec2(0.0, 1.0), per), hp(i + vec2(1.0, 1.0), per), u.x), u.y);
}
float pfbm(vec2 uv, vec2 per, int oct) {
  float s = 0.0, n = 0.0, a = 0.5;
  vec2 p = uv * per;
  for (int i = 0; i < 6; i++) {
    if (i >= oct) break;
    s += a * pn(p, per);
    n += a;
    p *= 2.0;
    per *= 2.0;
    a *= 0.5;
  }
  return s / n;
}
// Периодические ячейки: x — F1, y — F2, z — хеш ячейки; cp — ближайшая точка (в клетках)
vec3 pvor(vec2 p, vec2 per, out vec2 cp) {
  vec2 n = floor(p);
  vec2 f = fract(p);
  float d1 = 8.0, d2 = 8.0, id = 0.0;
  cp = vec2(0.0);
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 o = hp2(n + g, per) * 0.8 + 0.1;
      vec2 r = g + o - f;
      float d = dot(r, r);
      if (d < d1) { d2 = d1; d1 = d; id = hp(n + g + 3.7, per); cp = n + g + o; }
      else if (d < d2) d2 = d;
    }
  return vec3(sqrt(d1), sqrt(d2), id);
}
float segD(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
mat2 rot2(float a) { float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }
`;

/** Материалы: alb — множитель/2, h — высота, s — блеск. */
const BAKE_MATS = /* glsl */ `
struct M { vec3 alb; float h; float s; };

M mGrass(vec2 uv) {
  M m;
  float base = pfbm(uv, vec2(5.0), 4);
  float bl = 0.0, bh = 0.0;
  for (int L = 0; L < 3; L++) {
    float per = L == 0 ? 22.0 : L == 1 ? 34.0 : 51.0;
    vec2 p = uv * per;
    vec2 n = floor(p);
    for (int j = -1; j <= 1; j++)
      for (int i = -1; i <= 1; i++) {
        vec2 c = n + vec2(float(i), float(j));
        vec2 r = hp2(c + float(L) * 17.0, vec2(per));
        vec2 o = c + r;
        float ang = hp(c + 5.3 + float(L) * 3.0, vec2(per)) * 6.2831;
        vec2 dir = vec2(cos(ang), sin(ang));
        float len = 0.8 + 0.7 * r.x;
        float t = clamp(dot(p - o, dir) / len, 0.0, 1.0);
        float d = segD(p, o, o + dir * len);
        float w = mix(0.16, 0.03, t);
        float blade = smoothstep(w, w * 0.35, d);
        float lift = float(L) * 0.12 + t * 0.5;
        if (blade * (0.4 + lift) > bh) { bh = blade * (0.4 + lift); bl = blade * (0.35 + 0.65 * t); }
      }
  }
  vec3 c = vec3(0.44) * (0.88 + 0.24 * base);
  float hue = hp(floor(uv * 9.0), vec2(9.0));
  vec3 tip = mix(vec3(0.52, 0.55, 0.45), vec3(0.56, 0.54, 0.41), hue);
  c = mix(c, tip, bl * 0.8);
  // Клевер и мелкие цветочки
  vec2 cp;
  vec3 v = pvor(uv * 7.0, vec2(7.0), cp);
  if (v.z > 0.9 && v.x < 0.12) { c = mix(c, vec3(0.95, 0.9, 0.8), smoothstep(0.12, 0.07, v.x)); bh = max(bh, 0.9); }
  m.alb = c;
  m.h = base * 0.3 + bh * 0.7;
  m.s = 0.2 + bl * 0.4;
  return m;
}

M mSand(vec2 uv) {
  M m;
  float w = pfbm(uv, vec2(4.0), 3);
  float r = fract(dot(uv, vec2(6.0, 3.0)) + w * 1.3);
  float rip = smoothstep(0.0, 0.8, r) * smoothstep(1.0, 0.86, r);
  float g = hp(floor(uv * 256.0), vec2(256.0));
  float g2 = hp(floor(uv * 128.0) + 7.0, vec2(128.0));
  m.alb = vec3(0.5) * (0.9 + 0.1 * rip + 0.1 * (g - 0.5)) + vec3(0.03, 0.015, -0.02) * (g2 - 0.5);
  m.h = rip * 0.65 + g * 0.08 + w * 0.25;
  m.s = step(0.975, g) * 1.0 + 0.1;
  return m;
}

M mSnow(vec2 uv) {
  M m;
  float b = pfbm(uv, vec2(4.0), 5);
  float g = hp(floor(uv * 256.0), vec2(256.0));
  m.alb = mix(vec3(0.45, 0.47, 0.52), vec3(0.52, 0.52, 0.51), smoothstep(0.3, 0.7, b));
  m.h = b;
  m.s = step(0.965, g) + 0.15;
  return m;
}

M mDirt(vec2 uv) {
  M m;
  float b = pfbm(uv, vec2(6.0), 4);
  vec2 cp;
  vec3 v = pvor(uv * 13.0, vec2(13.0), cp);
  float peb = smoothstep(0.34, 0.24, v.x) * step(0.5, v.z);
  float fine = hp(floor(uv * 180.0), vec2(180.0));
  vec3 c = vec3(0.47) * (0.82 + 0.34 * b) + (fine - 0.5) * 0.05;
  c = mix(c, vec3(0.58, 0.57, 0.56) * (0.85 + 0.3 * v.z), peb);
  m.alb = c;
  m.h = b * 0.45 + peb * (0.45 + 0.35 * (1.0 - v.x / 0.34));
  m.s = peb * 0.3 + 0.05;
  return m;
}

// Брусчатка с мозаикой-лапкой: камни, чей центр попал в отпечаток, — терракотовые
M mCobble(vec2 uv) {
  M m;
  const float N = 16.0;
  vec2 cp;
  vec3 v = pvor(uv * N, vec2(N), cp);
  float e = v.y - v.x;
  float stone = smoothstep(0.03, 0.13, e);
  float dome = sqrt(clamp(e * 2.5, 0.0, 1.0));
  vec2 q = mod(cp, N) / N;
  vec2 pc = q - vec2(0.5, 0.42);
  bool paw = dot(pc / vec2(0.17, 0.135), pc / vec2(0.17, 0.135)) < 1.0;
  paw = paw || length(q - vec2(0.29, 0.62)) < 0.075 || length(q - vec2(0.42, 0.71)) < 0.078;
  paw = paw || length(q - vec2(0.58, 0.71)) < 0.078 || length(q - vec2(0.71, 0.62)) < 0.075;
  float tone = 0.86 + 0.28 * v.z;
  vec3 c = vec3(0.5) * tone;
  if (paw) c = vec3(0.66, 0.45, 0.38) * (0.9 + 0.2 * v.z);
  c *= 0.88 + 0.16 * pfbm(uv, vec2(24.0), 3);
  c = mix(vec3(0.22, 0.21, 0.2), c, stone);
  m.alb = c;
  m.h = stone * (0.3 + 0.7 * dome);
  m.s = stone * 0.35;
  return m;
}

M mRock(vec2 uv) {
  M m;
  float warp = pfbm(uv, vec2(3.0), 3);
  float sy = uv.y * 6.0 + warp * 0.9;
  float strata = fract(sy);
  float band = smoothstep(0.0, 0.1, strata) * smoothstep(1.0, 0.72, strata);
  vec2 cp;
  vec3 v = pvor(uv * 5.0, vec2(5.0), cp);
  float crack = 1.0 - smoothstep(0.0, 0.07, v.y - v.x);
  float n = pfbm(uv, vec2(10.0), 4);
  float tone = hp(vec2(mod(floor(sy), 6.0), 1.0), vec2(6.0, 4.0));
  vec3 c = vec3(0.5) * (0.78 + 0.34 * n) * (0.88 + 0.22 * tone);
  c *= 1.0 - crack * 0.5;
  float lich = smoothstep(0.66, 0.74, pfbm(uv + 0.37, vec2(7.0), 3));
  c = mix(c, vec3(0.6, 0.62, 0.42), lich * 0.45);
  m.alb = c;
  m.h = clamp(band * 0.4 + n * 0.45 - crack * 0.4 + 0.25, 0.0, 1.0);
  m.s = 0.15;
  return m;
}

M mAsh(vec2 uv) {
  M m;
  vec2 cp;
  vec3 v = pvor(uv * 6.0, vec2(6.0), cp);
  float crack = 1.0 - smoothstep(0.0, 0.09, v.y - v.x);
  float n = pfbm(uv, vec2(14.0), 4);
  vec3 c = vec3(0.5) * (0.72 + 0.4 * n) * (0.9 + 0.2 * v.z);
  c = mix(c, vec3(0.62, 0.22, 0.08), crack);
  m.alb = c;
  m.h = (1.0 - crack) * (0.45 + 0.55 * n);
  m.s = (1.0 - crack) * n * 0.6;
  return m;
}

M mMoss(vec2 uv) {
  M m;
  float b = pfbm(uv, vec2(5.0), 4);
  float moss = smoothstep(0.44, 0.58, b);
  float fine = pfbm(uv, vec2(40.0), 2);
  vec3 mud = vec3(0.4, 0.37, 0.33) * (0.9 + 0.2 * fine);
  vec3 ms = vec3(0.5, 0.58, 0.4) * (0.78 + 0.44 * fine);
  m.alb = mix(mud, ms, moss);
  m.h = moss * (0.45 + 0.55 * fine) + (1.0 - moss) * b * 0.25;
  m.s = (1.0 - moss) * 0.9 + 0.05;
  return m;
}

M mLitter(vec2 uv) {
  M m;
  float b = pfbm(uv, vec2(6.0), 3);
  vec3 c = vec3(0.4) * (0.85 + 0.3 * b);
  float h = b * 0.25;
  for (int L = 0; L < 3; L++) {
    float per = L == 0 ? 11.0 : L == 1 ? 17.0 : 26.0;
    vec2 p = uv * per;
    vec2 n = floor(p);
    for (int j = -1; j <= 1; j++)
      for (int i = -1; i <= 1; i++) {
        vec2 cc = n + vec2(float(i), float(j));
        vec2 r = hp2(cc + float(L) * 9.0, vec2(per));
        if (r.y > 0.8) continue;
        vec2 d = rot2(hp(cc + 2.7 + float(L), vec2(per)) * 6.2831) * (p - cc - r);
        float leaf = length(d * vec2(1.0, 2.3));
        float s = smoothstep(0.42, 0.37, leaf);
        if (s <= 0.0) continue;
        float hue = hp(cc + 11.0 + float(L), vec2(per));
        vec3 lc = hue < 0.3 ? vec3(0.66, 0.42, 0.26) : hue < 0.6 ? vec3(0.72, 0.56, 0.28) : hue < 0.85 ? vec3(0.52, 0.44, 0.3) : vec3(0.58, 0.6, 0.36);
        lc *= 1.0 - smoothstep(0.03, 0.0, abs(d.y)) * 0.3;
        lc *= 0.85 + 0.3 * smoothstep(0.42, 0.1, leaf);
        c = mix(c, lc, s);
        h = max(h, (0.35 + float(L) * 0.2) * s + 0.1 * (1.0 - leaf));
      }
  }
  m.alb = c;
  m.h = h;
  m.s = 0.1;
  return m;
}

M mDryEarth(vec2 uv) {
  M m;
  vec2 cp;
  vec3 v = pvor(uv * 8.0, vec2(8.0), cp);
  float e = v.y - v.x;
  float crack = 1.0 - smoothstep(0.02, 0.08, e);
  float n = pfbm(uv, vec2(20.0), 3);
  vec3 c = vec3(0.52) * (0.88 + 0.2 * n) * (0.94 + 0.12 * v.z);
  c = mix(c, vec3(0.26), crack);
  m.alb = c;
  m.h = (1.0 - crack) * (0.55 + 0.25 * smoothstep(0.35, 0.05, e) + 0.2 * n);
  m.s = 0.05;
  return m;
}

M mCandy(vec2 uv) {
  M m;
  float b = pfbm(uv, vec2(3.0), 4);
  float sw = sin(b * 9.0 + uv.x * 6.2831 * 2.0) * 0.5 + 0.5;
  vec3 c = vec3(0.52) * (0.92 + 0.12 * sw);
  float h = b * 0.5 + sw * 0.2;
  const float P = 24.0;
  vec2 p = uv * P;
  vec2 n = floor(p);
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 cc = n + vec2(float(i), float(j));
      vec2 r = hp2(cc, vec2(P));
      if (r.x > 0.6) continue;
      vec2 o = cc + r;
      float ang = hp(cc + 4.0, vec2(P)) * 6.2831;
      vec2 dir = vec2(cos(ang), sin(ang));
      float d = segD(p, o - dir * 0.22, o + dir * 0.22);
      float s = smoothstep(0.13, 0.08, d);
      if (s <= 0.0) continue;
      float hue = hp(cc + 9.0, vec2(P));
      vec3 sc = hue < 0.2 ? vec3(0.95, 0.3, 0.45) : hue < 0.4 ? vec3(0.3, 0.6, 1.0) : hue < 0.6 ? vec3(1.0, 0.9, 0.3) : hue < 0.8 ? vec3(0.5, 0.95, 0.5) : vec3(1.0);
      c = mix(c, sc, s);
      h = max(h, 0.75 * s + 0.2);
    }
  m.alb = c;
  m.h = h;
  m.s = 0.6;
  return m;
}

M mPlanks(vec2 uv) {
  M m;
  const float ROWS = 5.0;
  float y = uv.y * ROWS;
  float row = floor(y);
  float fy = fract(y);
  float off = hp(vec2(row, 3.0), vec2(ROWS, 7.0));
  float x = uv.x * 2.0 + off;
  float plank = floor(x);
  float fx = fract(x);
  float id = hp(vec2(mod(plank, 2.0), row), vec2(2.0, ROWS));
  float gap = smoothstep(0.0, 0.05, fy) * smoothstep(1.0, 0.95, fy) * smoothstep(0.0, 0.015, fx) * smoothstep(1.0, 0.985, fx);
  float g = pn(vec2(uv.x * 3.0, uv.y * 90.0 + id * 13.0), vec2(3.0, 90.0));
  float g2 = pn(vec2(uv.x * 12.0, uv.y * 160.0), vec2(12.0, 160.0));
  float rings = sin(g * 14.0 + fy * 3.0 + id * 20.0) * 0.5 + 0.5;
  float grain = 0.8 + 0.12 * g + 0.08 * g2 + 0.07 * rings;
  vec3 c = vec3(0.5) * (0.8 + 0.3 * id) * grain;
  // Сучки
  vec2 kp = vec2(fx - 0.3 - 0.4 * id, (fy - 0.5) * 0.4);
  float knot = smoothstep(0.08, 0.02, length(kp * vec2(1.0, 2.5)));
  c *= 1.0 - knot * 0.35;
  // Гвоздики на концах досок
  float nail = smoothstep(0.035, 0.02, length(vec2((fx - 0.05) * 2.0, fy - 0.5) * vec2(1.0, 1.2)));
  nail = max(nail, smoothstep(0.035, 0.02, length(vec2((fx - 0.95) * 2.0, fy - 0.5) * vec2(1.0, 1.2))));
  c = mix(c, vec3(0.3, 0.3, 0.32), nail);
  c *= mix(0.4, 1.0, gap);
  m.alb = c;
  m.h = gap * (0.62 + 0.18 * g + 0.1 * g2) - knot * 0.1 + nail * 0.1;
  m.s = 0.12 + nail * 0.8;
  return m;
}

// Черепица «рыбья чешуя»: полукруглые пластинки, нижний край каждого ряда лежит поверх следующего
M mScales(vec2 uv) {
  M m;
  const float COLS = 6.0, ROWS = 8.0;
  vec2 p = vec2(uv.x * COLS, uv.y * ROWS);
  float R = 0.62;
  float best = 1e3;
  vec2 bc = vec2(0.0);
  float bj = 0.0;
  bool found = false;
  for (int k = 0; k < 3; k++) {
    float j = floor(p.y) - 1.0 + float(k);
    float sh = mod(j, 2.0) * 0.5;
    float i = floor(p.x - sh);
    for (int t = 0; t < 2; t++) {
      vec2 c = vec2(i + float(t) + 0.5 + sh, j);
      float d = length((p - c) * vec2(1.0, 0.9));
      if (d < R && !found) {
        found = true;
        best = d;
        bc = c;
        bj = j;
      }
    }
  }
  float tone = hp(vec2(mod(bc.x - 0.5 - mod(bj, 2.0) * 0.5, COLS), mod(bj, ROWS)), vec2(COLS, ROWS));
  float rim = smoothstep(R * 0.8, R, best);
  vec3 c = vec3(0.5) * (0.84 + 0.3 * tone) * (1.02 - rim * 0.3);
  c *= 0.94 + 0.12 * pfbm(uv, vec2(16.0), 3);
  // Блик-прожилка по центру пластинки
  c += vec3(0.03) * smoothstep(0.2, 0.0, abs(p.x - bc.x)) * (1.0 - rim);
  m.alb = c;
  m.h = found ? 0.25 + 0.75 * smoothstep(0.0, R * 0.92, best) * (1.0 - smoothstep(R * 0.93, R, best)) : 0.0;
  m.s = 0.5 * (1.0 - rim);
  return m;
}

M bricksAt(vec2 uv, float rows, float cols) {
  M m;
  vec2 p = vec2(uv.x * cols, uv.y * rows);
  float row = floor(p.y);
  p.x += mod(row, 2.0) * 0.5;
  vec2 cell = floor(p);
  vec2 f = fract(p);
  float asp = rows / cols * 2.0;
  float ex = min(f.x, 1.0 - f.x) * 2.0 / asp * 2.0;
  float ey = min(f.y, 1.0 - f.y);
  float chip = pn(uv * vec2(cols, rows) * 5.0, vec2(cols, rows) * 5.0) * 0.06;
  float e = min(ex, ey) - chip;
  float brick = smoothstep(0.03, 0.09, e);
  float id = hp(vec2(mod(cell.x, cols), mod(cell.y, rows)), vec2(cols, rows));
  float n = pfbm(uv, vec2(18.0), 3);
  vec3 c = vec3(0.5) * (0.8 + 0.34 * id) * (0.88 + 0.22 * n);
  c = mix(vec3(0.34, 0.33, 0.31), c, brick);
  m.alb = c;
  m.h = brick * (0.65 + 0.35 * n);
  m.s = 0.08;
  return m;
}

M mBricks(vec2 uv) { return bricksAt(uv, 8.0, 4.0); }

M mPlaster(vec2 uv) {
  M m;
  float n = pfbm(uv, vec2(5.0), 5);
  float tr = pn(vec2(uv.x * 4.0, uv.y * 18.0), vec2(4.0, 18.0));
  vec3 c = vec3(0.52) * (0.93 + 0.08 * n + 0.04 * tr);
  float h = n * 0.35 + tr * 0.1 + 0.4;
  // Отвалившаяся штукатурка открывает кирпич
  float pn2 = pfbm(uv + 0.5, vec2(3.0), 4);
  float patchK = smoothstep(0.64, 0.66, pn2);
  float edge = smoothstep(0.6, 0.64, pn2) * (1.0 - patchK);
  if (patchK > 0.0) {
    M b = bricksAt(uv, 10.0, 5.0);
    c = mix(c, b.alb * vec3(1.08, 0.86, 0.74), patchK);
    h = mix(h, b.h * 0.3, patchK);
  }
  c *= 1.0 - edge * 0.15;
  m.alb = c;
  m.h = h;
  m.s = 0.05;
  return m;
}

M mBark(vec2 uv) {
  M m;
  float r = pfbm(uv, vec2(8.0, 2.0), 4);
  float ridges = abs(sin((uv.x * 10.0 + r * 1.6) * 3.14159265));
  float cr = pn(vec2(uv.x * 30.0, uv.y * 4.0), vec2(30.0, 4.0));
  float crack = smoothstep(0.18, 0.02, ridges) * (0.6 + 0.4 * cr);
  vec3 c = vec3(0.5) * (0.7 + 0.45 * ridges) * (0.9 + 0.2 * r);
  c *= 1.0 - crack * 0.5;
  float mossy = smoothstep(0.6, 0.72, pfbm(uv + 0.3, vec2(4.0, 2.0), 3)) * smoothstep(0.3, 0.9, ridges);
  c = mix(c, vec3(0.5, 0.62, 0.38), mossy * 0.5);
  m.alb = c;
  m.h = ridges * 0.7 + r * 0.3 - crack * 0.3;
  m.s = 0.05;
  return m;
}

M mLeaves(vec2 uv) {
  M m;
  // Тёмная глубина кроны между листьями
  float deep = pfbm(uv, vec2(4.0), 3);
  vec3 c = vec3(0.24) * (0.8 + 0.4 * deep);
  float h = deep * 0.2;
  for (int L = 0; L < 4; L++) {
    float per = L == 0 ? 8.0 : L == 1 ? 11.0 : L == 2 ? 15.0 : 20.0;
    vec2 p = uv * per;
    vec2 n = floor(p);
    for (int j = -1; j <= 1; j++)
      for (int i = -1; i <= 1; i++) {
        vec2 cc = n + vec2(float(i), float(j));
        vec2 r = hp2(cc + float(L) * 5.0, vec2(per));
        // Лист заострён с обоих концов: ширина — парабола вдоль длины
        vec2 d = rot2(hp(cc + 1.3 + float(L), vec2(per)) * 6.2831) * (p - cc - r);
        float len = 0.62;
        float x = d.x / len;
        float wdt = 0.26 * (1.0 - x * x);
        float inside = step(abs(x), 1.0) * smoothstep(wdt, wdt - 0.05, abs(d.y));
        if (inside <= 0.0) continue;
        float tone = hp(cc + 7.0 + float(L), vec2(per));
        vec3 lc = vec3(0.5) * (0.8 + 0.35 * tone) * (0.75 + 0.12 * float(L));
        lc *= vec3(1.0 + 0.1 * (tone - 0.5), 1.0, 1.0 - 0.12 * tone);
        // Прожилка и светлая середина
        lc *= 1.0 - smoothstep(0.02, 0.0, abs(d.y)) * 0.25 * step(abs(x), 0.85);
        lc *= 0.85 + 0.25 * (1.0 - abs(d.y) / max(wdt, 1e-3));
        c = mix(c, lc, inside);
        h = max(h, (0.3 + float(L) * 0.18) * inside + 0.12 * (1.0 - abs(x)));
      }
  }
  m.alb = c;
  m.h = h;
  m.s = 0.45;
  return m;
}

M mFabric(vec2 uv) {
  M m;
  const float T = 48.0;
  vec2 p = uv * T;
  float ck = mod(floor(p.x) + floor(p.y), 2.0);
  float th = ck > 0.5 ? 0.5 + 0.5 * cos(fract(p.y) * 6.2831) : 0.5 + 0.5 * cos(fract(p.x) * 6.2831);
  float n = pfbm(uv, vec2(6.0), 3);
  m.alb = vec3(0.5) * (0.88 + 0.12 * th) * (0.95 + 0.1 * n);
  m.h = 0.3 + 0.5 * (1.0 - th) + n * 0.2;
  m.s = 0.08;
  return m;
}

M mThatch(vec2 uv) {
  M m;
  const float ROWS = 5.0;
  float y = uv.y * ROWS;
  float fy = fract(y);
  float s1 = pn(vec2(uv.x * 90.0, uv.y * 5.0), vec2(90.0, 5.0));
  float s2 = pn(vec2(uv.x * 170.0, uv.y * 9.0 + 3.0), vec2(170.0, 9.0));
  float straw = s1 * 0.6 + s2 * 0.4;
  float shade = smoothstep(0.0, 0.25, fy);
  m.alb = vec3(0.5) * (0.7 + 0.4 * straw) * (0.6 + 0.4 * shade);
  m.h = straw * 0.5 + shade * 0.5;
  m.s = 0.08;
  return m;
}

M mMetal(vec2 uv) {
  M m;
  float br = pn(vec2(uv.x * 2.0, uv.y * 220.0), vec2(2.0, 220.0));
  vec2 f = fract(uv * 2.0);
  float seam = smoothstep(0.0, 0.02, min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)));
  vec2 rv = abs(f - 0.5);
  float rivet = smoothstep(0.035, 0.02, length(rv - vec2(0.42, 0.42)));
  m.alb = vec3(0.5) * (0.85 + 0.15 * br) * mix(0.55, 1.0, seam) + rivet * 0.08;
  m.h = seam * 0.5 + rivet * 0.4 + br * 0.05;
  m.s = 0.9 * seam;
  return m;
}

M mCrystal(vec2 uv) {
  M m;
  vec2 cp;
  vec3 v = pvor(uv * 5.0, vec2(5.0), cp);
  float edge = 1.0 - smoothstep(0.0, 0.05, v.y - v.x);
  float facet = 0.8 + 0.4 * v.z;
  float spark = step(0.985, hp(floor(uv * 128.0), vec2(128.0)));
  m.alb = vec3(0.5) * facet + edge * 0.15 + spark * 0.3;
  m.h = 0.5 + 0.4 * (v.z - 0.5) - edge * 0.3 + (1.0 - v.x) * 0.2;
  m.s = 0.8 + spark;
  return m;
}

M material(int L, vec2 uv) {
  if (L == 0) return mGrass(uv);
  if (L == 1) return mSand(uv);
  if (L == 2) return mSnow(uv);
  if (L == 3) return mDirt(uv);
  if (L == 4) return mCobble(uv);
  if (L == 5) return mRock(uv);
  if (L == 6) return mAsh(uv);
  if (L == 7) return mMoss(uv);
  if (L == 8) return mLitter(uv);
  if (L == 9) return mDryEarth(uv);
  if (L == 10) return mCandy(uv);
  if (L == 11) return mPlanks(uv);
  if (L == 12) return mScales(uv);
  if (L == 13) return mPlaster(uv);
  if (L == 14) return mBricks(uv);
  if (L == 15) return mBark(uv);
  if (L == 16) return mLeaves(uv);
  if (L == 17) return mFabric(uv);
  if (L == 18) return mThatch(uv);
  if (L == 19) return mMetal(uv);
  return mCrystal(uv);
}
`;

/** Проход 1: альбедо+высота в массив A и блеск в альфу массива B. */
const BAKE_FS = /* glsl */ `${HEADER}
${UTIL_GLSL}
${BAKE_LIB}
${BAKE_MATS}
in vec2 vUv;
uniform int uLayer;
layout(location = 0) out vec4 outA;
layout(location = 1) out vec4 outB;
void main() {
  M m = material(uLayer, vUv);
  outA = vec4(clamp(m.alb, 0.0, 1.0), clamp(m.h, 0.0, 1.0));
  outB = vec4(0.5, 0.5, 1.0, clamp(m.s, 0.0, 1.0));
}
`;

/** Проход 2: нормали и полости (AO) из высоты. */
const NORMAL_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform highp sampler2DArray uSrc;
uniform int uLayer;
uniform float uBump;
layout(location = 0) out vec4 outB;
float H(ivec2 p, int size) {
  p = (p + ivec2(size)) % size;
  return texelFetch(uSrc, ivec3(p, uLayer), 0).a;
}
void main() {
  int size = textureSize(uSrc, 0).x;
  ivec2 p = ivec2(gl_FragCoord.xy);
  float hl = H(p + ivec2(-1, 0), size), hr = H(p + ivec2(1, 0), size);
  float hd = H(p + ivec2(0, -1), size), hu = H(p + ivec2(0, 1), size);
  float k = uBump * float(size) / 256.0;
  vec3 n = normalize(vec3((hl - hr) * k * 4.0, (hd - hu) * k * 4.0, 1.0));
  float h = H(p, size);
  float avg = 0.0;
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 0.785398;
    ivec2 o = ivec2(round(vec2(cos(a), sin(a)) * float(size) / 64.0));
    avg += H(p + o, size);
  }
  avg /= 8.0;
  float ao = clamp(1.0 - (avg - h) * 1.6, 0.35, 1.0);
  outB = vec4(n.xy * 0.5 + 0.5, ao, 0.0);
}
`;

/** Рельефность на этапе запекания (перепад высот → наклон нормали). */
const BUMP: number[] = [1.0, 0.8, 0.6, 1.2, 1.6, 1.8, 1.4, 1.1, 1.3, 1.4, 1.0, 1.1, 1.6, 0.8, 1.4, 1.8, 1.5, 0.9, 1.3, 0.8, 1.2];

export class MaterialLibrary {
  readonly albedo: WebGLTexture;
  readonly normal: WebGLTexture;
  readonly size: number;

  constructor(
    readonly gl: GL,
    size: number,
  ) {
    this.size = size;
    const levels = Math.floor(Math.log2(size)) + 1;
    const mk = () => {
      const t = gl.createTexture()!;
      gl.bindTexture(gl.TEXTURE_2D_ARRAY, t);
      gl.texStorage3D(gl.TEXTURE_2D_ARRAY, levels, gl.RGBA8, size, size, MAT_COUNT);
      gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_S, gl.REPEAT);
      gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_T, gl.REPEAT);
      gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
      gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      const an = gl.getExtension("EXT_texture_filter_anisotropic");
      if (an) gl.texParameterf(gl.TEXTURE_2D_ARRAY, an.TEXTURE_MAX_ANISOTROPY_EXT, Math.min(8, gl.getParameter(an.MAX_TEXTURE_MAX_ANISOTROPY_EXT) as number));
      return t;
    };
    this.albedo = mk();
    this.normal = mk();
    this.bake();
    this.bind();
  }

  private bake() {
    const gl = this.gl;
    const bakeProg = new Program(gl, FULLSCREEN_VS, BAKE_FS, "material-bake");
    const normProg = new Program(gl, FULLSCREEN_VS, NORMAL_FS, "material-normal");
    const vao = gl.createVertexArray()!;
    const fbo = gl.createFramebuffer()!;
    gl.bindVertexArray(vao);
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.viewport(0, 0, this.size, this.size);
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.BLEND);
    gl.disable(gl.CULL_FACE);
    for (let L = 0; L < MAT_COUNT; L++) {
      gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, this.albedo, 0, L);
      gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT1, this.normal, 0, L);
      gl.drawBuffers([gl.COLOR_ATTACHMENT0, gl.COLOR_ATTACHMENT1]);
      bakeProg.use();
      bakeProg.i1("uLayer", L);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      // Нормали: пишем только RGB массива B (альфа — блеск из первого прохода)
      gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT1, null, 0, 0);
      gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, this.normal, 0, L);
      gl.drawBuffers([gl.COLOR_ATTACHMENT0]);
      gl.colorMask(true, true, true, false);
      normProg.use();
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.albedo);
      normProg.i1("uSrc", 0);
      normProg.i1("uLayer", L);
      normProg.f1("uBump", BUMP[L] ?? 1);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      gl.colorMask(true, true, true, true);
      gl.bindTexture(gl.TEXTURE_2D_ARRAY, null);
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.deleteFramebuffer(fbo);
    gl.bindVertexArray(null);
    gl.deleteVertexArray(vao);
    gl.deleteProgram(bakeProg.program);
    gl.deleteProgram(normProg.program);
    for (const t of [this.albedo, this.normal]) {
      gl.bindTexture(gl.TEXTURE_2D_ARRAY, t);
      gl.generateMipmap(gl.TEXTURE_2D_ARRAY);
    }
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, null);
  }

  /** Привязать массивы к постоянным слотам. */
  bind() {
    const gl = this.gl;
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.matAlbedo);
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.albedo);
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.matNormal);
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, this.normal);
    gl.activeTexture(gl.TEXTURE0);
  }

  dispose() {
    this.gl.deleteTexture(this.albedo);
    this.gl.deleteTexture(this.normal);
  }
}
