/** Кривые опыта и масштабирование по уровню (работает и для бесконечных уровней). */
import { LEVEL_CAP, type ModeConfig } from "./types";

/** Множитель силы/здоровья от уровня: экспонента 6% за уровень. */
export function levelScale(level: number): number {
  return Math.pow(1.06, Math.min(Math.max(level, 1), 11500) - 1);
}

/** Мягкое масштабирование маны и стоимостей. */
export function manaScale(level: number): number {
  return 1 + 0.045 * (Math.max(level, 1) - 1);
}

export function xpToNext(level: number): number {
  const base = 80 * Math.pow(level, 1.55);
  return Math.round(level > 100 ? base * Math.pow(1.012, level - 100) : base);
}

export function killXp(enemyLevel: number, playerLevel: number, mult = 1): number {
  const base = 10 + enemyLevel * 3.6 + Math.pow(enemyLevel, 1.25) * 0.8;
  const diff = enemyLevel - playerLevel;
  let k = 1;
  if (diff < -8) k = 0.1;
  else if (diff < -4) k = 0.5;
  else if (diff > 0) k = 1 + Math.min(0.5, diff * 0.08);
  const extra = playerLevel > 100 ? Math.pow(1.012, playerLevel - 100) : 1;
  return Math.max(1, Math.round(base * k * mult * extra));
}

export function questXp(level: number, mult = 1): number {
  return Math.round(xpToNext(Math.max(1, level)) * 0.45 * mult);
}

export function skillPointsForLevel(level: number): number {
  return level <= 1 ? 1 : 2;
}

export function levelCap(mode: ModeConfig): number {
  return mode.levels === "capped" ? LEVEL_CAP : Infinity;
}

/** Цена в рыбках. */
export function priceScale(level: number): number {
  return Math.pow(1.045, Math.min(level, 15000) - 1);
}
