import { observer } from "mobx-react-lite";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn } from "../common";
import { CLASSES } from "../../game/classes";
import { modeLabel, type ClassId } from "../../game/types";
import { CharacterStore } from "../../game/character";

export const MainMenu = observer(() => {
  const s = useStore();
  const last = s.saves.list[0];
  const cont = () => {
    if (!last) return;
    const d = s.saves.load(last.id);
    if (!d) return;
    s.play(new CharacterStore(d));
  };
  return (
    <div className="menu-screen">
      <div className="menu-title">{tr({ ru: "Котоверсум", en: "Catverse" })}</div>
      <div className="menu-sub">{tr({ ru: "3D RPG, где всё — кошки 🐾", en: "A 3D RPG where everything is cats 🐾" })}</div>
      <div className="menu-buttons">
        {last && (
          <Btn kind="primary" onClick={cont}>
            ▶ {tr({ ru: "Продолжить", en: "Continue" })}: {last.name} · {tr(CLASSES[last.classId as ClassId].name)} {last.level}
            <div style={{ fontSize: 12, fontWeight: 700, opacity: 0.8 }}>{tr(modeLabel(last.mode))}</div>
          </Btn>
        )}
        <Btn kind={last ? "normal" : "primary"} onClick={() => s.ui.go("newgame")}>
          ✨ {tr({ ru: "Новая игра", en: "New game" })}
        </Btn>
        {s.saves.list.length > 0 && <Btn onClick={() => s.ui.go("load")}>📂 {tr({ ru: "Сохранения", en: "Saved games" })}</Btn>}
        <Btn onClick={() => s.ui.go("coop")}>🤝 {tr({ ru: "Кооператив (WebRTC)", en: "Co-op (WebRTC)" })}</Btn>
        <Btn onClick={() => s.ui.go("settings")}>⚙️ {tr({ ru: "Настройки", en: "Settings" })}</Btn>
        <div className="row" style={{ justifyContent: "center" }}>
          <Btn kind="ghost" small onClick={() => s.settings.set("lang", s.settings.lang === "ru" ? "en" : "ru")}>
            🌐 {s.settings.lang === "ru" ? "English" : "Русский"}
          </Btn>
          <Btn kind="ghost" small onClick={() => s.ui.go("about")}>
            ❓ {tr({ ru: "Как играть", en: "How to play" })}
          </Btn>
        </div>
      </div>
    </div>
  );
});

