/**
 * Градиентный шум без таблиц перестановок: градиенты берутся из хеша целочисленной
 * координаты, поэтому шум бесконечен по площади и одинаков на всех устройствах.
 */
import { hash2 } from "./rng";

const GX = new Float32Array(16);
const GY = new Float32Array(16);
for (let i = 0; i < 16; i++) {
  const a = (i / 16) * Math.PI * 2 + 0.3;
  GX[i] = Math.cos(a);
  GY[i] = Math.sin(a);
}

const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);

/** 2D градиентный шум, результат примерно в [-1, 1]. */
export function noise2(x: number, y: number, seed: number): number {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = x - ix;
  const fy = y - iy;
  const h00 = hash2(ix, iy, seed) & 15;
  const h10 = hash2(ix + 1, iy, seed) & 15;
  const h01 = hash2(ix, iy + 1, seed) & 15;
  const h11 = hash2(ix + 1, iy + 1, seed) & 15;
  const n00 = GX[h00] * fx + GY[h00] * fy;
  const n10 = GX[h10] * (fx - 1) + GY[h10] * fy;
  const n01 = GX[h01] * fx + GY[h01] * (fy - 1);
  const n11 = GX[h11] * (fx - 1) + GY[h11] * (fy - 1);
  const u = fade(fx);
  const v = fade(fy);
  const a = n00 + (n10 - n00) * u;
  const b = n01 + (n11 - n01) * u;
  return (a + (b - a) * v) * 1.414;
}

/** Фрактальный шум (fBm), результат примерно в [-1, 1]. */
export function fbm2(x: number, y: number, seed: number, octaves = 4, lacunarity = 2, gain = 0.5): number {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  let f = 1;
  for (let i = 0; i < octaves; i++) {
    sum += noise2(x * f, y * f, seed + i * 1013) * amp;
    norm += amp;
    amp *= gain;
    f *= lacunarity;
  }
  return sum / norm;
}

/** «Хребтовый» шум для гор: результат в [0, 1]. */
export function ridged2(x: number, y: number, seed: number, octaves = 4, lacunarity = 2, gain = 0.5): number {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  let f = 1;
  let prev = 1;
  for (let i = 0; i < octaves; i++) {
    let n = 1 - Math.abs(noise2(x * f, y * f, seed + i * 7919));
    n *= n;
    sum += n * amp * prev;
    prev = n;
    norm += amp;
    amp *= gain;
    f *= lacunarity;
  }
  return sum / norm;
}

/** Клеточный шум (Ворони): расстояние до ближайшей точки и id клетки. */
export function voronoi2(x: number, y: number, seed: number): { d: number; id: number; cx: number; cy: number } {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  let best = 1e9;
  let bestId = 0;
  let bcx = 0,
    bcy = 0;
  for (let j = -1; j <= 1; j++) {
    for (let i = -1; i <= 1; i++) {
      const cx = ix + i;
      const cy = iy + j;
      const h = hash2(cx, cy, seed);
      const px = cx + (h & 0xffff) / 65536;
      const py = cy + (h >>> 16) / 65536;
      const d = (px - x) * (px - x) + (py - y) * (py - y);
      if (d < best) {
        best = d;
        bestId = h;
        bcx = px;
        bcy = py;
      }
    }
  }
  return { d: Math.sqrt(best), id: bestId, cx: bcx, cy: bcy };
}
