import { observer } from "mobx-react-lite";
import { useState, Fragment } from "react";
import { tr } from "../../core/i18n";
import { fmtNum, fmtPct, fmtTime } from "../../core/format";
import { useStore } from "../stores";
import { Btn, ItemCard, ItemIcon, Panel } from "../common";
import { SLOTS, SLOT_NAMES, gearScore, type Item } from "../../game/items";
import { CLASSES } from "../../game/classes";
import { ELEMENTS } from "../../game/types";
import { regenPerSec } from "../../game/stats";
import { ELEMENT_NAMES, KEYSTONES } from "../../game/skills/vocab";
import { audio } from "../../audio/audio";

export const CharacterStats = observer(() => {
  const s = useStore();
  const c = s.char!;
  const st = c.stats;
  const d = c.data;
  // Зелий нет: показываем, сколько кот восстанавливает в бою и на отдыхе
  const inFight = regenPerSec(st, st.maxHp, st.maxMp, 0);
  const atRest = regenPerSec(st, st.maxHp, st.maxMp, 1);
  const resting = tr({ ru: "вне боя", en: "resting" });
  const rows: [string, string][] = [
    [tr({ ru: "Уровень", en: "Level" }), `${d.level}${c.cap < Infinity ? ` / ${c.cap}` : ""}`],
    [tr({ ru: "Опыт", en: "XP" }), `${fmtNum(d.xp)} / ${fmtNum(c.xpNeeded)}`],
    [tr({ ru: "Здоровье", en: "Health" }), fmtNum(st.maxHp)],
    [tr({ ru: "Мана", en: "Mana" }), fmtNum(st.maxMp)],
    [tr({ ru: "Сила", en: "Power" }), fmtNum(st.power)],
    [tr({ ru: "Броня", en: "Armor" }), fmtNum(st.armor)],
    [tr({ ru: "Сопротивление", en: "Resistance" }), fmtPct(st.resist)],
    [tr({ ru: "Шанс крита", en: "Crit chance" }), fmtPct(st.crit)],
    [tr({ ru: "Урон крита", en: "Crit damage" }), `×${st.critDmg.toFixed(2)}`],
    [tr({ ru: "Скорость навыков", en: "Haste" }), `+${fmtPct(st.haste)}`],
    [tr({ ru: "Скорость бега", en: "Move speed" }), st.moveSpeed.toFixed(1)],
    [tr({ ru: "Уклонение", en: "Dodge" }), fmtPct(st.dodge)],
    [tr({ ru: "Вампиризм", en: "Lifesteal" }), fmtPct(st.lifesteal)],
    [tr({ ru: "Восст. здоровья/с", en: "HP regen/s" }), `${fmtNum(inFight.hp)} · ${fmtNum(atRest.hp)} ${resting}`],
    [tr({ ru: "Восст. маны/с", en: "MP regen/s" }), `${fmtNum(inFight.mp)} · ${fmtNum(atRest.mp)} ${resting}`],
  ];
  for (const e of ELEMENTS) if (st.elementPct[e] > 0) rows.push([`${tr(ELEMENT_NAMES[e])}`, `+${fmtPct(st.elementPct[e])}`]);
  if (st.summonPct) rows.push([tr({ ru: "Сила призванных", en: "Summon power" }), `+${fmtPct(st.summonPct)}`]);
  if (st.healPct) rows.push([tr({ ru: "Сила лечения", en: "Healing" }), `+${fmtPct(st.healPct)}`]);
  return (
    <div className="col">
      <div className="stat-list">
        {rows.map(([k, v]) => (
          <Fragment key={k}>
            <div className="muted">{k}</div>
            <div>{v}</div>
          </Fragment>
        ))}
      </div>
      {st.keystones.size > 0 && (
        <div>
          <div className="label" style={{ marginTop: 8 }}>
            {tr({ ru: "Ключевые таланты", en: "Keystones" })}
          </div>
          {[...st.keystones.keys()].map((k) => (
            <div key={k} style={{ fontSize: 14, marginBottom: 4 }}>
              ⭐ <b>{tr(KEYSTONES[k].name)}</b> — <span className="muted">{tr(KEYSTONES[k].desc)}</span>
            </div>
          ))}
        </div>
      )}
      <div className="muted" style={{ fontSize: 13 }}>
        {tr({ ru: "Убито врагов", en: "Kills" })}: {d.stats.kills} · {tr({ ru: "Заданий", en: "Quests" })}: {d.stats.quests} · {tr({ ru: "Подземелий", en: "Dungeons" })}: {d.stats.dungeons} · {tr({ ru: "Обмороков", en: "Faints" })}: {d.stats.deaths} · {tr({ ru: "Время", en: "Time" })}: {fmtTime(d.stats.playTime)}
      </div>
    </div>
  );
});

export const InventoryPanel = observer(({ tab: initial = "inv" }: { tab?: "inv" | "stats" }) => {
  const s = useStore();
  const c = s.char!;
  void c.rev;
  const [tab, setTab] = useState<"inv" | "stats">(initial);
  const [sel, setSel] = useState<string | null>(null);
  const d = c.data;
  const findItem = (id: string | null): { item: Item; equipped: boolean } | null => {
    if (!id) return null;
    for (const sl of SLOTS) if (d.equipment[sl]?.id === id) return { item: d.equipment[sl]!, equipped: true };
    const it = d.inventory.find((x) => x?.id === id);
    return it ? { item: it, equipped: false } : null;
  };
  const cur = findItem(sel);
  const atMerchant = s.ui.dialog && (s.ui.dialog.role === "merchant" || s.ui.dialog.role === "smith");
  const sell = (it: Item) => {
    c.removeItem(it.id);
    c.addFish(Math.max(1, Math.round((it.value * (it.stack ?? 1)) / 3)));
    audio.play("fish");
    setSel(null);
  };
  const useItem = (it: Item) => {
    if (it.kind === "tome") {
      c.removeItem(it.id);
      if ((it.stack ?? 1) > 1) c.addItem({ ...it, stack: (it.stack ?? 1) - 1 });
      d.skillPoints += 1;
      c.touch();
      s.hud.toast({ ru: "+1 очко навыков!", en: "+1 skill point!" }, 0x7ee081, "📖");
      audio.play("levelup");
      setSel(null);
    }
  };
  const sortInv = () => {
    const items = d.inventory.filter(Boolean) as Item[];
    items.sort((a, b) => (a.kind === b.kind ? b.rarity - a.rarity || gearScore(b) - gearScore(a) : a.kind.localeCompare(b.kind)));
    d.inventory = [...items, ...new Array(d.inventory.length - items.length).fill(null)];
    c.touch();
  };
  const sellJunk = () => {
    let total = 0;
    for (const it of [...d.inventory]) if (it && it.kind === "gear" && it.rarity <= 1) {
      c.removeItem(it.id);
      total += Math.max(1, Math.round(it.value / 3));
    }
    if (total) {
      c.addFish(total);
      audio.play("fish");
      s.hud.toast({ ru: `Продано хлама на ${total} 🐟`, en: `Sold junk for ${total} 🐟` }, 0xffd24a);
    }
  };
  return (
    <Panel title={{ ru: `${d.name} · ${CLASSES[d.classId].name.ru}`, en: `${d.name} · ${CLASSES[d.classId].name.en}` }} onClose={() => s.ui.close()} wide>
      <div className="tabs">
        <button className={`tab${tab === "inv" ? " on" : ""}`} onClick={() => setTab("inv")}>
          🎒 {tr({ ru: "Снаряжение", en: "Gear" })}
        </button>
        <button className={`tab${tab === "stats" ? " on" : ""}`} onClick={() => setTab("stats")}>
          📊 {tr({ ru: "Характеристики", en: "Stats" })}
        </button>
        <div className="spacer" />
        <div style={{ fontWeight: 900 }}>🐟 {fmtNum(d.fish)}</div>
      </div>
      {tab === "stats" ? (
        <CharacterStats />
      ) : (
        <div className="inv-layout">
          <div className="col">
            <div className="equip-grid">
              {SLOTS.map((sl) => (
                <div key={sl} className="equip-slot">
                  <ItemIcon item={d.equipment[sl]} size={56} selected={sel !== null && sel === d.equipment[sl]?.id} onClick={() => d.equipment[sl] && setSel(d.equipment[sl]!.id)} />
                  {tr(SLOT_NAMES[sl])}
                </div>
              ))}
            </div>
            <div className="row">
              <span className="muted">
                {tr({ ru: "Очки навыков", en: "Skill points" })}: {d.skillPoints}
              </span>
            </div>
            {cur && (
              <ItemCard item={cur.item} compare={!cur.equipped && cur.item.gear ? d.equipment[cur.item.gear.slot] : null}>
                <div className="row" style={{ marginTop: 10 }}>
                  {cur.item.gear &&
                    (cur.equipped ? (
                      <Btn small onClick={() => c.unequip(cur.item.gear!.slot)}>
                        {tr({ ru: "Снять", en: "Unequip" })}
                      </Btn>
                    ) : (
                      <Btn small kind="primary" onClick={() => c.equip(cur.item.id)}>
                        {tr({ ru: "Надеть", en: "Equip" })}
                      </Btn>
                    ))}
                  {cur.item.kind === "tome" && (
                    <Btn small kind="primary" onClick={() => useItem(cur.item)}>
                      {tr({ ru: "Прочитать", en: "Read" })}
                    </Btn>
                  )}
                  {!cur.equipped && cur.item.kind !== "quest" && (
                    <Btn small kind={atMerchant ? "primary" : "ghost"} onClick={() => sell(cur.item)}>
                      {atMerchant ? tr({ ru: "Продать", en: "Sell" }) : tr({ ru: "Продать (издалека)", en: "Sell (remote)" })}
                    </Btn>
                  )}
                </div>
              </ItemCard>
            )}
          </div>
          <div className="col">
            <div className="row">
              <Btn small kind="ghost" onClick={sortInv}>
                ↕ {tr({ ru: "Сортировать", en: "Sort" })}
              </Btn>
              <Btn small kind="ghost" onClick={sellJunk}>
                🐟 {tr({ ru: "Продать хлам", en: "Sell junk" })}
              </Btn>
            </div>
            <div className="inv-grid">
              {d.inventory.map((it, i) => (
                <ItemIcon key={it?.id ?? `e${i}`} item={it} size={52} selected={!!it && it.id === sel} onClick={() => it && setSel(it.id)} />
              ))}
            </div>
          </div>
        </div>
      )}
    </Panel>
  );
});
