/** Предохранитель: ошибка отрисовки не стирает всё приложение, а предлагает вернуться в меню. */
import { Component, type ReactNode } from "react";
import { tr } from "../core/i18n";

interface Props {
  children: ReactNode;
  onReset: () => void;
}

export class ErrorBoundary extends Component<Props, { error: Error | null }> {
  override state: { error: Error | null } = { error: null };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  override componentDidCatch(error: Error) {
    console.error(error);
  }

  override render() {
    const e = this.state.error;
    if (!e) return this.props.children;
    return (
      <div className="menu-screen">
        <div className="menu-card" style={{ maxWidth: 520 }}>
          <h2>😿 {tr({ ru: "Что-то пошло не так", en: "Something went wrong" })}</h2>
          <div className="muted" style={{ fontSize: 13, wordBreak: "break-word" }}>
            {String(e.message ?? e).slice(0, 300)}
          </div>
          <div className="muted" style={{ fontSize: 14, margin: "8px 0 12px" }}>
            {tr({ ru: "Прогресс сохранён. Можно вернуться в меню или перезагрузить страницу.", en: "Your progress is saved. You can return to the menu or reload the page." })}
          </div>
          <div className="row">
            <button
              className="btn btn-primary"
              onClick={() => {
                this.props.onReset();
                this.setState({ error: null });
              }}
            >
              🏠 {tr({ ru: "В меню", en: "Main menu" })}
            </button>
            <button className="btn btn-normal" onClick={() => location.reload()}>
              ↻ {tr({ ru: "Перезагрузить", en: "Reload" })}
            </button>
          </div>
        </div>
      </div>
    );
  }
}
