export function classLook(cls: ClassId, overrides: Partial<CatLook> = {}): CatLook {
  return { ...BASE_LOOK, ...CLASS_LOOKS[cls], ...overrides };
}

/** Случайный горожанин. */
export function villagerLook(rng: Rng): CatLook {
  const patterns: FurPattern[] = ["solid", "tabby", "spots", "tuxedo", "calico", "siamese", "tortie", "bicolor"];
  const pattern = rng.pick(patterns);
  let fur = rng.pick(FUR_COLORS);
  let fur2 = 0xf8f4ee;
  if (pattern === "calico") {
    fur = 0xf8f4ee;
    fur2 = 0xe08a3a;
  } else if (pattern === "tortie") {
    fur = 0x3a2a24;
    fur2 = 0xd07a3a;
  } else if (pattern === "siamese") {
    fur = 0xf2e6d2;
    fur2 = 0x4a3428;
  } else if (pattern === "tabby" || pattern === "spots") fur2 = darken(fur, 0.45);
  const hats: HatKind[] = ["none", "none", "none", "none", "straw", "chef", "bandana", "feather", "pirate"];
  return {
    ...BASE_LOOK,
    fur,
    fur2,
    pattern,
    eyes: rng.pick(EYE_COLORS),
    size: rng.range(0.85, 1.1),
    bulk: rng.range(0.85, 1.35),
    legLen: rng.range(0.9, 1.1),
    earSize: rng.range(0.85, 1.15),
    tailLen: rng.range(0.75, 1.2),
    tailFluff: rng.range(0.8, 1.5),
    headSize: rng.range(0.95, 1.1),
    hat: rng.pick(hats),
    hatColor: rng.pick([0xc0503a, 0x3a6aa0, 0x4a8a4a, 0xd8b050, 0xf0f0f0, 0x8a4ab0]),
    weapon: "none",
    collar: rng.chance(0.7) ? rng.pick([0xd23a3a, 0x3a7ad2, 0x3ad27a, 0xd2a03a, 0xa03ad2]) : undefined,
    bell: rng.chance(0.5),
  };
}

export function darken(hex: number, k: number): number {
  const r = ((hex >> 16) & 255) * (1 - k);
  const g = ((hex >> 8) & 255) * (1 - k);
  const b = (hex & 255) * (1 - k);
  return (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b);
}

export function lighten(hex: number, k: number): number {
  const r = ((hex >> 16) & 255) + (255 - ((hex >> 16) & 255)) * k;
  const g = ((hex >> 8) & 255) + (255 - ((hex >> 8) & 255)) * k;
  const b = (hex & 255) + (255 - (hex & 255)) * k;
  return (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b);
}
