/** 0 — игроки и союзники, 1 — враги, 2 — нейтральные. */
export type Faction = 0 | 1 | 2;

/** Конфигурация режима: каждый аспект можно сделать бесконечным независимо. */
export interface ModeConfig {
  /** continent — огромный конечный материк; infinite — бесконечно генерируемый мир. */
  world: "continent" | "infinite";
  /** classic — фиксированное дерево из ~300 навыков на класс; infinite — бесконечно растущее дерево. */
  skills: "classic" | "infinite";
  /** capped — максимум 100 уровней; infinite — без ограничения. */
  levels: "capped" | "infinite";
}

export const MODE_PRESETS: Record<"campaign" | "endless", ModeConfig> = {
  campaign: { world: "continent", skills: "classic", levels: "capped" },
  endless: { world: "infinite", skills: "infinite", levels: "infinite" },
};

export const LEVEL_CAP = 100;

export function modeLabel(m: ModeConfig): Txt {
  if (m.world === "continent" && m.skills === "classic" && m.levels === "capped")
    return { ru: "Кампания", en: "Campaign" };
  if (m.world === "infinite" && m.skills === "infinite" && m.levels === "infinite")
    return { ru: "Бесконечность", en: "Endless" };
  const parts: Txt[] = [];
  parts.push(m.world === "continent" ? { ru: "Материк", en: "Continent" } : { ru: "∞ мир", en: "∞ world" });
  parts.push(m.skills === "classic" ? { ru: "300 навыков", en: "300 skills" } : { ru: "∞ навыки", en: "∞ skills" });
  parts.push(m.levels === "capped" ? { ru: "100 ур.", en: "Lv 100" } : { ru: "∞ уровни", en: "∞ levels" });
  return { ru: parts.map((p) => p.ru).join(" · "), en: parts.map((p) => p.en).join(" · ") };
}

export interface Pos2 {
  x: number;
  z: number;
}
