import { observer } from "mobx-react-lite";
import { useRef } from "react";
import { tr } from "../../core/i18n";
import { fmtTime } from "../../core/format";
import { useStore } from "../stores";
import { Btn } from "../common";
import { CLASSES } from "../../game/classes";
import { modeLabel, type ClassId } from "../../game/types";
import { CharacterStore } from "../../game/character";
import { hex } from "../icons";

export const LoadGame = observer(() => {
  const s = useStore();
  const fileRef = useRef<HTMLInputElement>(null);
  const play = (id: string) => {
    const d = s.saves.load(id);
    if (!d) return;
    s.play(new CharacterStore(d));
  };
  const exp = (id: string, name: string) => {
    const json = s.saves.exportJson(id);
    if (!json) return;
    const blob = new Blob([json], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `kotoverse-${name}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  };
  const imp = async (f: File) => {
    const text = await f.text();
    const d = s.saves.importJson(text);
    if (!d) alert(tr({ ru: "Не удалось импортировать сохранение", en: "Could not import save" }));
  };
  return (
    <div className="menu-screen" style={{ justifyContent: "flex-start" }}>
      <div className="menu-card" style={{ maxWidth: 720 }}>
        <h2>{tr({ ru: "Сохранения", en: "Saved games" })}</h2>
        {s.saves.list.length === 0 && <div className="muted">{tr({ ru: "Пока пусто.", en: "Nothing here yet." })}</div>}
        {s.saves.list.map((m) => (
          <div className="save-row" key={m.id}>
            <div style={{ width: 40, height: 40, borderRadius: "50%", background: hex(m.fur), border: "3px solid #fff" }} />
            <div style={{ flex: 1, minWidth: 160 }}>
              <div style={{ fontWeight: 900 }}>
                {m.name} · {tr(CLASSES[m.classId as ClassId].name)} {m.level}
              </div>
              <div className="muted" style={{ fontSize: 12 }}>
                {tr(modeLabel(m.mode))} · {fmtTime(m.playTime)} · {new Date(m.updatedAt).toLocaleString()}
              </div>
            </div>
            <Btn small kind="primary" onClick={() => play(m.id)}>
              ▶
            </Btn>
            <Btn small kind="ghost" onClick={() => exp(m.id, m.name)}>
              ⬇
            </Btn>
            <Btn
              small
              kind="danger"
              onClick={() =>
                s.ui.ask({
                  text: { ru: `Удалить «${m.name}» навсегда?`, en: `Delete “${m.name}” forever?` },
                  ok: () => s.saves.remove(m.id),
                  okLabel: { ru: "Удалить", en: "Delete" },
                })
              }
            >
              🗑
            </Btn>
          </div>
        ))}
        <div className="row" style={{ marginTop: 12 }}>
          <Btn onClick={() => s.ui.go("menu")}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
          <div className="spacer" />
          <Btn onClick={() => fileRef.current?.click()}>⬆ {tr({ ru: "Импорт", en: "Import" })}</Btn>
          <input ref={fileRef} type="file" accept="application/json" style={{ display: "none" }} onChange={(e) => e.target.files?.[0] && imp(e.target.files[0])} />
        </div>
      </div>
    </div>
  );
});
