/**
 * Генератор деревьев навыков.
 *
 * Дерево = корень класса → 3 школы. Каждая ветка — сегмент из 2–4 узлов, после которого
 * она разветвляется на 2–3 направления:
 *  - «специализация» — углубляет текущий навык (новые модификаторы, эффекты, механики);
 *  - «новый навык» — открывает новую способность школы (другой способ доставки/стихия);
 *  - «мастерство» — пассивные бонусы и в конце ключевой талант (keystone).
 *
 * Кампания: дерево строится в ширину до ~300 узлов на класс (детерминированно).
 * Бесконечный режим: те же правила, но дети генерируются лениво по мере изучения — без конца.
 */
import { clamp } from "../../core/math";
import { hashStr, Rng } from "../../core/rng";
import type { Txt } from "../../core/i18n";
import { CLASSES, type School } from "../classes";
import type { ClassId, Element } from "../types";
import { BASE_PARAMS, DELIVERY_INFO, ELEMENT_INFO } from "./palette";
import type {
  BuffSpec,
  Delivery,
  KeystoneId,
  OnHit,
  Passive,
  SkillDef,
  SkillMod,
  SkillNode,
  SkillParams,
  StatKey,
  SummonKind,
} from "./types";
import {
  DELIVERY_NAMES,
  DELIVERY_NOUNS,
  DOT_NAMES,
  ELEMENT_ADJ,
  ELEMENT_AFFINITY,
  GROUND_NAMES,
  HIT_NAMES,
  KEYSTONES,
  MOD_NAMES,
  roman,
  STAT_NAMES,
  TIER_PREFIX,
} from "./vocab";

type Direction = "new" | "spec" | "mastery";

interface SegSpec {
  path: string;
  school: number;
  parentNodeId: string;
  depthStart: number;
  segDepth: number;
  direction: Direction;
  skillId: string | null;
  element: Element;
  theme: string;
}

export const CAMPAIGN_NODES = 300;

const SPEC_THEMES = ["power", "multi", "area", "element", "control", "utility", "special"];

const ALL_KEYSTONES: KeystoneId[] = Object.keys(KEYSTONES) as KeystoneId[];

export class SkillTree {
  readonly nodes = new Map<string, SkillNode>();
  readonly root: SkillNode;
  private pending = new Map<string, SegSpec[]>();
  private usedNames = new Set<string>();
  private usedKeystones = new Set<KeystoneId>();
  /** Уникальные модификаторы, уже выданные навыку (чтобы не повторялись). */
  private skillMods = new Map<string, Set<string>>();
  private levelK = 1.11;
  maxDepth = 0;

  constructor(
    readonly classId: ClassId,
    readonly infinite: boolean,
  ) {
    const cls = CLASSES[classId];
    this.root = {
      id: `${classId}:root`,
      classId,
      parent: null,
      children: null,
      depth: 0,
      school: -1,
      kind: "root",
      reqLevel: 1,
      name: { ru: "Кошачья натура", en: "Feline Nature" },
      passives: [
        { p: "stat", stat: "maxHp", pct: 0.05 },
        { p: "stat", stat: "moveSpeed", add: 0.03 },
      ],
      color: cls.color,
      glyph: "paw",
      segDepth: 0,
    };
    this.nodes.set(this.root.id, this.root);
    const starts: SegSpec[] = cls.schools.map((s, i) => ({
      path: String(i),
      school: i,
      parentNodeId: this.root.id,
      depthStart: 1,
      segDepth: 0,
      direction: "new" as Direction,
      skillId: null,
      element: s.signature.element,
      theme: "power",
    }));
    this.pending.set(this.root.id, starts);
    if (!infinite) this.buildCampaign();
    else this.expand(this.root.id);
  }

  /** Строит всё дерево кампании в ширину до ~300 узлов. */
  private buildCampaign() {
    const queue: string[] = [this.root.id];
    while (queue.length && this.nodes.size < CAMPAIGN_NODES) {
      const id = queue.shift()!;
      const specs = this.pending.get(id);
      if (!specs) continue;
      this.pending.delete(id);
      const node = this.nodes.get(id)!;
      node.children = [];
      // Узел получает сразу все свои ветви (иначе две цепочки сливаются в одну длинную без развилки)
      for (const spec of specs) {
        const created = this.genSegment(spec);
        node.children.push(created[0].id);
        queue.push(created[created.length - 1].id);
      }
    }
    // Оставшиеся ветки — листья
    for (const id of this.pending.keys()) {
      const n = this.nodes.get(id);
      if (n && n.children === null) n.children = [];
    }
    this.pending.clear();
    for (const n of this.nodes.values()) if (n.children === null) n.children = [];
    // Пересчитываем уровни так, чтобы самые глубокие узлы требовали ~100-й уровень
    this.maxDepth = 0;
    for (const n of this.nodes.values()) this.maxDepth = Math.max(this.maxDepth, n.depth);
    this.levelK = 97 / Math.pow(Math.max(2, this.maxDepth - 1), 1.6);
    for (const n of this.nodes.values()) n.reqLevel = this.reqLevel(n.depth);
  }

  reqLevel(depth: number): number {
    if (depth <= 1) return 1;
    const lv = 1 + Math.round(this.levelK * Math.pow(depth - 1, 1.6));
    return this.infinite ? lv : clamp(lv, 1, 100);
  }

  /** Сгенерировать детей узла (для бесконечного дерева). */
  expand(id: string): SkillNode[] {
    const node = this.nodes.get(id);
    if (!node) return [];
    if (node.children !== null) return node.children.map((c) => this.nodes.get(c)!).filter(Boolean);
    const specs = this.pending.get(id);
    if (!specs) {
      node.children = [];
      return [];
    }
    this.pending.delete(id);
    node.children = [];
    for (const spec of specs) {
      const created = this.genSegment(spec);
      node.children.push(created[0].id);
    }
    return node.children.map((c) => this.nodes.get(c)!);
  }

  get(id: string): SkillNode | undefined {
    return this.nodes.get(id);
  }

  childrenOf(id: string): SkillNode[] {
    return this.expand(id);
  }

  // ───────────────────── генерация сегмента ─────────────────────

  private genSegment(spec: SegSpec): SkillNode[] {
    const rng = new Rng(hashStr(`${this.classId}|${this.infinite ? "inf" : "cmp"}|${spec.path}`));
    const cls = CLASSES[this.classId];
    const school = cls.schools[spec.school];
    const len = spec.segDepth === 0 ? 3 : rng.int(2, 4);
    const created: SkillNode[] = [];
    let parentId = spec.parentNodeId;
    let skillId = spec.skillId;
    const t = spec.segDepth;
    for (let i = 0; i < len; i++) {
      const id = `${this.classId}:${spec.path}:${i}`;
      const depth = spec.depthStart + i;
      let node: SkillNode;
      const base = {
        id,
        classId: this.classId,
        parent: parentId,
        children: null as string[] | null,
        depth,
        school: spec.school,
        reqLevel: this.reqLevel(depth),
        segDepth: t,
      };
      if (spec.direction === "new" && i === 0) {
        const skill = this.makeNewSkill(rng, id, school, spec, t);
        node = { ...base, kind: "active", name: skill.name, skill, color: skill.visual.color, glyph: DELIVERY_INFO[skill.delivery].glyph };
        skillId = id;
      } else if (spec.direction === "mastery" || !skillId) {
        const last = i === len - 1;
        if (last && rng.chance(0.75)) {
          const ks = this.pickKeystone(rng, school);
          const kd = KEYSTONES[ks];
          node = { ...base, kind: "keystone", name: kd.name, keystone: ks, color: 0xffd24a, glyph: "star" };
        } else {
          const p = this.makePassive(rng, school, t, spec.element);
          node = { ...base, kind: "passive", name: p.name, passives: p.passives, color: school.color, glyph: p.glyph };
        }
      } else {
        const target = this.nodes.get(skillId)!;
        if (rng.chance(0.14) && i > 0) {
          const p = this.makePassive(rng, school, t, target.skill!.element);
          node = { ...base, kind: "passive", name: p.name, passives: p.passives, color: school.color, glyph: p.glyph };
        } else {
          let used = this.skillMods.get(skillId);
          if (!used) this.skillMods.set(skillId, (used = new Set()));
          const up = this.makeUpgrade(rng, target.skill!, spec.theme, t, used);
          node = { ...base, kind: "upgrade", name: up.name, target: skillId, mods: up.mods, color: target.skill!.visual.color, glyph: up.glyph };
        }
      }
      this.nodes.set(id, node);
      const parent = this.nodes.get(parentId)!;
      if (i > 0) parent.children = [id];
      created.push(node);
      parentId = id;
    }
    // Дети: 2–3 направления
    const last = created[created.length - 1];
    const nChildren = spec.direction === "mastery" ? 2 : rng.int(2, 3);
    const specs: SegSpec[] = [];
    const dirs: Direction[] = [];
    if (skillId && spec.direction !== "mastery") dirs.push("spec");
    while (dirs.length < nChildren) dirs.push(rng.chance(0.62) ? "new" : "mastery");
    // Не больше одной ветки мастерства
    let mastery = 0;
    for (let k = 0; k < dirs.length; k++) {
      if (dirs[k] === "mastery" && ++mastery > 1) dirs[k] = "new";
    }
    dirs.forEach((dir, k) => {
      const el = rng.chance(0.75) ? school.elements[0] : rng.pick(school.elements);
      specs.push({
        path: `${spec.path}.${k}`,
        school: spec.school,
        parentNodeId: last.id,
        depthStart: last.depth + 1,
        segDepth: t + 1,
        direction: dir,
        skillId: dir === "spec" ? skillId : null,
        element: dir === "spec" && skillId ? this.nodes.get(skillId)!.skill!.element : el,
        theme: rng.pick(SPEC_THEMES),
      });
    });
    this.pending.set(last.id, specs);
    return created;
  }

  private pickKeystone(rng: Rng, school: School): KeystoneId {
    const prefer = school.keystones.filter((k) => !this.usedKeystones.has(k));
    let ks: KeystoneId;
    if (prefer.length) ks = rng.pick(prefer);
    else {
      const rest = ALL_KEYSTONES.filter((k) => !this.usedKeystones.has(k));
      ks = rest.length ? rng.pick(rest) : rng.pick(school.keystones);
    }
    if (!this.infinite) this.usedKeystones.add(ks);
    return ks;
  }

  private uniqueName(base: Txt, rng: Rng, alt: () => Txt): Txt {
    let n = base;
    for (let i = 0; i < 6 && this.usedNames.has(n.ru); i++) n = alt();
    if (this.usedNames.has(n.ru)) {
      let k = 2;
      while (this.usedNames.has(`${n.ru} ${roman(k)}`)) k++;
      n = { ru: `${n.ru} ${roman(k)}`, en: `${n.en} ${roman(k)}` };
    }
    this.usedNames.add(n.ru);
    void rng;
    return n;
  }

  private skillName(rng: Rng, el: Element, d: Delivery, t: number): Txt {
    const a = rng.pick(ELEMENT_ADJ[el]);
    const n = rng.pick(DELIVERY_NOUNS[d]);
    const tp = TIER_PREFIX[Math.min(TIER_PREFIX.length - 1, Math.floor(t / 2))];
    let ru = `${a[n.g]} ${n.ru.charAt(0).toLowerCase()}${n.ru.slice(1)}`;
    if (tp.ru) {
      const g = n.g;
      const pre = tp.ru.trim();
      // Согласуем префикс по роду: Великий/Великая/Великое/Великие
      const fix = (w: string) =>
        g === "f" ? w.replace(/ий$/, "ая").replace(/ый$/, "ая") : g === "n" ? w.replace(/ий$/, "ое").replace(/ый$/, "ое") : g === "p" ? w.replace(/ий$/, "ие").replace(/ый$/, "ые") : w;
      ru = `${fix(pre)} ${ru.charAt(0).toLowerCase()}${ru.slice(1)}`;
    }
    const en = `${tp.en}${a.en} ${n.en}`;
    return { ru, en };
  }

  private makeNewSkill(rng: Rng, id: string, school: School, spec: SegSpec, t: number): SkillDef {
    const sig = t === 0 ? school.signature : null;
    let delivery: Delivery;
    let element: Element;
    if (sig) {
      delivery = sig.delivery;
      element = sig.element;
    } else {
      // избегаем повторения доставки родительского навыка
      const parentSkill = this.nearestSkill(spec.parentNodeId);
      const opts = school.deliveries.filter((d) => !parentSkill || d !== parentSkill.delivery);
      delivery = rng.pick(opts.length ? opts : school.deliveries);
      element = spec.element;
    }
    const info = DELIVERY_INFO[delivery];
    const params: SkillParams = { ...BASE_PARAMS, ...info.params };
    const tierMul = 1 + 0.14 * t;
    params.power *= tierMul * rng.range(0.92, 1.1);
    if (params.radius) params.radius *= rng.range(0.9, 1.15) * (1 + 0.03 * t);
    if (delivery === "projectile" && !sig) params.count = rng.chance(0.3) ? rng.int(2, 3) : 1;
    if (params.count > 1 && delivery === "projectile") params.spread = 0.18 * params.count;
    params.cooldown *= rng.range(0.9, 1.1);
    params.cost *= 1 + 0.05 * t;
    const onHit: OnHit[] = [];
    const eh = ELEMENT_INFO[element].defaultHit(t);
    if (eh && (sig || rng.chance(0.65)) && !["buff", "heal", "barrier", "blink"].includes(delivery)) onHit.push(eh);
    let homing = false;
    let name = sig ? sig.name : this.skillName(rng, element, delivery, t);
    if (!sig) name = this.uniqueName(name, rng, () => this.skillName(rng, element, delivery, t));
    else this.usedNames.add(name.ru);
    // Настройки «подписи»
    if (sig?.tweak) {
      const tw = sig.tweak;
      if (tw.count) params.count = tw.count;
      if (tw.pierce) params.pierce = tw.pierce;
      if (tw.spread) params.spread = tw.spread;
      if (tw.radius) params.radius = tw.radius;
      if (tw.power) params.power *= tw.power;
      if (tw.explode) onHit.push({ k: "explode", radius: tw.explode, power: 0.6 });
      if (tw.stun) onHit.push({ k: "stun", dur: tw.stun });
      if (tw.freeze) onHit.push({ k: "freeze", dur: tw.freeze });
      if (tw.bleed) onHit.push({ k: "dot", el: "physical", dps: tw.bleed, dur: 3 });
      if (tw.poison) onHit.push({ k: "dot", el: "poison", dps: tw.poison, dur: 4 });
      if (tw.homing) homing = true;
    }
    const ei = ELEMENT_INFO[element];
    const shape = rng.pick(ei.shapes);
    const summonKind: SummonKind | undefined =
      delivery === "summon"
        ? (sig?.summon ?? school.summon ?? (element === "shadow" ? "ghost" : element === "nature" ? "beast" : element === "holy" ? "spirit" : "elemental"))
        : undefined;
    const buff: BuffSpec[] | undefined =
      delivery === "buff"
        ? [
            { stat: rng.pick([...(school.passives.filter((s) => s !== "summonPct" && s !== "healPct") as StatKey[]), "power", "haste"] as StatKey[]), pct: 0.2 + 0.04 * t },
            { stat: rng.pick(["haste", "moveSpeed", "armor", "crit", "power"] as StatKey[]), pct: 0.15 + 0.03 * t },
          ]
        : undefined;
    return {
      id,
      name,
      delivery,
      element,
      params,
      onHit,
      homing,
      returning: delivery === "boomerang",
      echo: null,
      ground: null,
      anim: sig ? sig.anim : rng.pick(info.anims),
      visual: {
        color: ei.color,
        color2: rng.chance(0.3) ? school.color : ei.color2,
        shape,
        size: rng.range(0.85, 1.25) * (1 + 0.05 * t),
        trail: rng.chance(0.7),
        glow: rng.range(0.6, 1.2),
        style: rng.int(0, 7),
      },
      tier: t,
      summon: summonKind ? { kind: summonKind, ranged: rng.chance(0.4) || summonKind === "spirit" || summonKind === "elemental" } : undefined,
      buff,
      melee: info.melee,
      target: info.target,
    };
  }

  private nearestSkill(nodeId: string): SkillDef | null {
    let n = this.nodes.get(nodeId);
    while (n) {
      if (n.skill) return n.skill;
      if (n.target) return this.nodes.get(n.target)?.skill ?? null;
      n = n.parent ? this.nodes.get(n.parent) : undefined;
    }
    return null;
  }

  private makeUpgrade(rng: Rng, skill: SkillDef, theme: string, t: number, used: Set<string>): { mods: SkillMod[]; name: Txt; glyph: string } {
    const allowed = DELIVERY_INFO[skill.delivery].mods;
    const cands: { mod: SkillMod; name: Txt; glyph: string; key: string }[] = [];
    const REPEATABLE = new Set(["power", "radius", "count", "pierce", "bounce", "cooldown", "cost", "duration", "speed", "range", "crit", "knock", "spread"]);
    const add = (key: string, mod: SkillMod, name: Txt, glyph: string) => {
      const base = key.split(":")[0];
      if (!allowed.includes(base) && base !== "onHit") return;
      if (base === "onHit" && !allowed.includes("onHit")) return;
      if (!REPEATABLE.has(key) && used.has(key)) return;
      if (used.has(`last:${key}`)) return;
      cands.push({ mod, name, glyph, key });
    };
    const nm = (k: keyof typeof MOD_NAMES) => rng.pick(MOD_NAMES[k]!);
    const el = skill.element;
    const themes: Record<string, () => void> = {
      power: () => {
        add("power", { m: "power", pct: 0.18 + 0.05 * t }, nm("power"), "up");
        add("crit", { m: "crit", pct: 0.08 + 0.02 * t }, nm("crit"), "crit");
        add("onHit:execute", { m: "onHit", hit: { k: "execute", pct: Math.min(0.3, 0.1 + 0.01 * t) } }, HIT_NAMES.execute, "skull");
      },
      multi: () => {
        add("count", { m: "count", add: t >= 5 ? 2 : 1 }, nm("count"), "multi");
        add("pierce", { m: "pierce", add: 1 + Math.floor(t / 3) }, nm("pierce"), "arrow");
        add("bounce", { m: "bounce", add: 1 + Math.floor(t / 4) }, nm("bounce"), "bounce");
        add("echo", { m: "echo", delay: 0.55, pct: 0.35 + 0.05 * t }, nm("echo"), "echo");
        add("spread", { m: "spread", pct: 0.3 }, nm("spread"), "cone");
      },
      area: () => {
        add("radius", { m: "radius", pct: 0.18 + 0.04 * t }, nm("radius"), "area");
        add("ground", { m: "ground", dps: 0.2 + 0.04 * t, dur: 3 + t * 0.2, radius: 2.4 }, GROUND_NAMES[el], "ground");
        add("duration", { m: "duration", pct: 0.25 + 0.05 * t }, nm("duration"), "clock");
      },
      element: () => {
        add("onHit:dot", { m: "onHit", hit: { k: "dot", el, dps: 0.16 + 0.04 * t, dur: 3.5 } }, DOT_NAMES[el], "drop");
        add("onHit:vulnerable", { m: "onHit", hit: { k: "vulnerable", pct: 0.12 + 0.02 * t, dur: 4 } }, HIT_NAMES.vulnerable, "down");
        add("onHit:weaken", { m: "onHit", hit: { k: "weaken", pct: 0.15 + 0.02 * t, dur: 4 } }, HIT_NAMES.weaken, "down");
        add("onHit:lifesteal", { m: "onHit", hit: { k: "lifesteal", pct: 0.05 + 0.01 * t } }, HIT_NAMES.lifesteal, "heart");
      },
      control: () => {
        add("onHit:slow", { m: "onHit", hit: { k: "slow", pct: Math.min(0.6, 0.25 + 0.03 * t), dur: 2.5 } }, HIT_NAMES.slow, "snow");
        add("onHit:stun", { m: "onHit", hit: { k: "stun", dur: Math.min(2, 0.6 + 0.1 * t) } }, HIT_NAMES.stun, "star");
        add("onHit:freeze", { m: "onHit", hit: { k: "freeze", dur: Math.min(2.2, 0.8 + 0.1 * t) } }, HIT_NAMES.freeze, "snow");
        add("knock", { m: "knock", add: 2.5 }, nm("knock"), "push");
        add("onHit:pull", { m: "onHit", hit: { k: "pull", force: 4 } }, HIT_NAMES.pull, "pull");
        add("onHit:fear", { m: "onHit", hit: { k: "fear", dur: 1.6 } }, HIT_NAMES.fear, "skull");
      },
      utility: () => {
        add("cooldown", { m: "cooldown", pct: -(0.1 + 0.02 * t) }, nm("cooldown"), "clock");
        add("cost", { m: "cost", pct: -(0.12 + 0.02 * t) }, nm("cost"), "drop");
        add("speed", { m: "speed", pct: 0.25 + 0.05 * t }, nm("speed"), "dash");
        add("range", { m: "range", pct: 0.25 }, nm("range"), "arrow");
        add("duration", { m: "duration", pct: 0.25 + 0.05 * t }, nm("duration"), "clock");
      },
      special: () => {
        add("homing", { m: "homing" }, nm("homing"), "target");
        add("returning", { m: "returning" }, nm("returning"), "bounce");
        add("onHit:split", { m: "onHit", hit: { k: "split", count: 2 } }, HIT_NAMES.split, "multi");
        add("onHit:explode", { m: "onHit", hit: { k: "explode", radius: 2.4, power: 0.45 + 0.08 * t } }, HIT_NAMES.explode, "burst");
        add("onHit:chain", { m: "onHit", hit: { k: "chain", count: 2 } }, HIT_NAMES.chain, "chain");
        add("onHit:charm", { m: "onHit", hit: { k: "charm", dur: 3 } }, HIT_NAMES.charm, "heart");
        add("onHit:manaLeech", { m: "onHit", hit: { k: "manaLeech", pct: 0.05 } }, HIT_NAMES.manaLeech, "drop");
      },
    };
    const order = [theme, ...SPEC_THEMES.filter((x) => x !== theme)];
    for (const th of order) {
      themes[th]();
      if (cands.length >= 2) break;
    }
    if (!cands.length) {
      // универсальный фолбэк: мощь
      cands.push({ mod: { m: "power", pct: 0.2 + 0.05 * t }, name: nm("power"), glyph: "up", key: `power:${used.size}` });
    }
    const pick = rng.pick(cands);
    for (const k of [...used]) if (k.startsWith("last:")) used.delete(k);
    used.add(pick.key);
    used.add(`last:${pick.key}`);
    const mods: SkillMod[] = [pick.mod];
    // Изредка — второе, слабое свойство
    if (rng.chance(0.25) && pick.mod.m !== "power") mods.push({ m: "power", pct: 0.06 + 0.02 * t });
    const name: Txt = { ru: `${skill.name.ru}: ${pick.name.ru}`, en: `${skill.name.en}: ${pick.name.en}` };
    return { mods, name, glyph: pick.glyph };
  }

  private makePassive(rng: Rng, school: School, t: number, el: Element): { passives: Passive[]; name: Txt; glyph: string } {
    const roll = rng.next();
    if (roll < 0.22) {
      const pct = 0.08 + 0.025 * t;
      return { passives: [{ p: "element", el, pct }], name: this.numbered(ELEMENT_AFFINITY[el]), glyph: "elem" };
    }
    if (roll < 0.32) {
      const d = rng.pick(school.deliveries);
      return {
        passives: [{ p: "delivery", d, pct: 0.1 + 0.025 * t }],
        name: this.numbered({ ru: `Мастерство: ${DELIVERY_NAMES[d].ru.toLowerCase()}`, en: `${DELIVERY_NAMES[d].en} Mastery` }),
        glyph: DELIVERY_INFO[d].glyph,
      };
    }
    if (roll < 0.38) {
      const what = rng.pick(["heal", "mana", "haste", "explode"] as const);
      const names = {
        heal: { ru: "Трофей охотника", en: "Hunter's Trophy" },
        mana: { ru: "Вдохновение", en: "Inspiration" },
        haste: { ru: "Азарт погони", en: "Thrill of the Chase" },
        explode: { ru: "Злой рок", en: "Doom" },
      };
      return { passives: [{ p: "onKill", what, amount: what === "explode" ? 0.3 + 0.05 * t : 0.02 + 0.005 * t }], name: this.numbered(names[what]), glyph: "skull" };
    }
    const stat = rng.pick(school.passives);
    const p = statPassive(stat, t);
    const flavor = rng.pick(STAT_NAMES[stat].flavor);
    return { passives: [p], name: this.numbered(flavor), glyph: "up" };
  }

  private numbered(n: Txt): Txt {
    if (!this.usedNames.has(n.ru)) {
      this.usedNames.add(n.ru);
      return n;
    }
    let k = 2;
    while (this.usedNames.has(`${n.ru} ${roman(k)}`)) k++;
    const r = { ru: `${n.ru} ${roman(k)}`, en: `${n.en} ${roman(k)}` };
    this.usedNames.add(r.ru);
    return r;
  }

  // ───────────────────── запросы ─────────────────────

  all(): SkillNode[] {
    return [...this.nodes.values()];
  }

  canLearn(id: string, learned: ReadonlySet<string>, level: number): boolean {
    const n = this.nodes.get(id);
    if (!n || learned.has(id) || n.kind === "root") return false;
    if (n.parent && !learned.has(n.parent)) return false;
    return level >= n.reqLevel;
  }
}

export function statPassive(stat: StatKey, t: number): Passive {
  switch (stat) {
    case "maxHp":
      return { p: "stat", stat, pct: 0.06 + 0.012 * t };
    case "maxMp":
      return { p: "stat", stat, pct: 0.08 + 0.012 * t };
    case "hpRegen":
    case "mpRegen":
      return { p: "stat", stat, pct: 0.25 + 0.05 * t };
    case "power":
      return { p: "stat", stat, pct: 0.05 + 0.012 * t };
    case "armor":
      return { p: "stat", stat, pct: 0.1 + 0.02 * t };
    case "resist":
      return { p: "stat", stat, add: 0.03 + 0.004 * t };
    case "crit":
      return { p: "stat", stat, add: 0.02 + 0.003 * t };
    case "critDmg":
      return { p: "stat", stat, add: 0.1 + 0.02 * t };
    case "haste":
      return { p: "stat", stat, add: 0.04 + 0.006 * t };
    case "moveSpeed":
      return { p: "stat", stat, add: 0.04 + 0.004 * t };
    case "lifesteal":
      return { p: "stat", stat, add: 0.015 + 0.003 * t };
    case "dodge":
      return { p: "stat", stat, add: 0.02 + 0.003 * t };
    case "thorns":
      return { p: "stat", stat, add: 0.1 + 0.02 * t };
    default:
      return { p: "stat", stat, add: 0.08 + 0.02 * t };
  }
}

const TREE_CACHE = new Map<string, SkillTree>();

export function getTree(classId: ClassId, infinite: boolean): SkillTree {
  const k = `${classId}|${infinite}`;
  let t = TREE_CACHE.get(k);
  if (!t) {
    t = new SkillTree(classId, infinite);
    TREE_CACHE.set(k, t);
  }
  return t;
}
