export const TAU = Math.PI * 2;
export const DEG = Math.PI / 180;

export const clamp = (v: number, lo: number, hi: number) => (v < lo ? lo : v > hi ? hi : v);
export const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
export const invLerp = (a: number, b: number, v: number) => (a === b ? 0 : (v - a) / (b - a));
export const remap = (a: number, b: number, c: number, d: number, v: number) => lerp(c, d, invLerp(a, b, v));
export const smoothstep = (e0: number, e1: number, x: number) => {
  const t = clamp01((x - e0) / (e1 - e0));
  return t * t * (3 - 2 * t);
};
export const fract = (x: number) => x - Math.floor(x);
export const sign = (x: number) => (x < 0 ? -1 : 1);

/** Нормализует угол в диапазон [-PI, PI]. */
export function wrapAngle(a: number): number {
  a = (a + Math.PI) % TAU;
  if (a < 0) a += TAU;
  return a - Math.PI;
}
export const angleDiff = (from: number, to: number) => wrapAngle(to - from);
export const lerpAngle = (a: number, b: number, t: number) => a + angleDiff(a, b) * t;

/** Кадронезависимое экспоненциальное сглаживание. */
export const damp = (a: number, b: number, lambda: number, dt: number) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const dampAngle = (a: number, b: number, lambda: number, dt: number) =>
  lerpAngle(a, b, 1 - Math.exp(-lambda * dt));

export const dist2 = (ax: number, az: number, bx: number, bz: number) => {
  const dx = bx - ax,
    dz = bz - az;
  return dx * dx + dz * dz;
};
export const dist = (ax: number, az: number, bx: number, bz: number) => Math.sqrt(dist2(ax, az, bx, bz));
export const len2 = (x: number, z: number) => Math.sqrt(x * x + z * z);

/** Угол (yaw) направления (dx, dz) в нашей системе: yaw=0 смотрит в +Z. */
export const yawOf = (dx: number, dz: number) => Math.atan2(dx, dz);
export const dirX = (yaw: number) => Math.sin(yaw);
export const dirZ = (yaw: number) => Math.cos(yaw);

/** Расстояние от точки до отрезка (2D) и параметр t проекции. */
export function distToSegment(px: number, pz: number, ax: number, az: number, bx: number, bz: number): number {
  const abx = bx - ax,
    abz = bz - az;
  const l2 = abx * abx + abz * abz;
  let t = l2 > 0 ? ((px - ax) * abx + (pz - az) * abz) / l2 : 0;
  t = clamp01(t);
  const cx = ax + abx * t,
    cz = az + abz * t;
  return Math.sqrt((px - cx) * (px - cx) + (pz - cz) * (pz - cz));
}

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

export function hexToRgb(hex: number): [number, number, number] {
  return [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
}
export function rgbToHex(r: number, g: number, b: number): number {
  return (Math.round(clamp01(r) * 255) << 16) | (Math.round(clamp01(g) * 255) << 8) | Math.round(clamp01(b) * 255);
}
export function cssColor(hex: number, alpha = 1): string {
  const [r, g, b] = hexToRgb(hex);
  return alpha >= 1
    ? `rgb(${Math.round(r * 255)},${Math.round(g * 255)},${Math.round(b * 255)})`
    : `rgba(${Math.round(r * 255)},${Math.round(g * 255)},${Math.round(b * 255)},${alpha})`;
}
export function mixRgb(a: [number, number, number], b: [number, number, number], t: number): [number, number, number] {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}
/** HSV → RGB, всё в [0,1]. */
export function hsv(h: number, s: number, v: number): [number, number, number] {
  h = fract(h) * 6;
  const i = Math.floor(h);
  const f = h - i;
  const p = v * (1 - s),
    q = v * (1 - s * f),
    t = v * (1 - s * (1 - f));
  switch (i) {
    case 0:
      return [v, t, p];
    case 1:
      return [q, v, p];
    case 2:
      return [p, v, t];
    case 3:
      return [p, q, v];
    case 4:
      return [t, p, v];
    default:
      return [v, p, q];
  }
}
