import { observer } from "mobx-react-lite";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn, Panel } from "../common";
import { SettingsForm } from "../menu/Settings";
import { modeLabel } from "../../game/types";
import { fmtNum } from "../../core/format";
import { CLASSES } from "../../game/classes";
import { Glyph } from "../icons";
import { QuestTracker } from "../game/Hud";

export const GameMenuPanel = observer(({ onQuit }: { onQuit: () => void }) => {
  const s = useStore();
  const c = s.char!;
  const h = s.hud;
  const place = h.inDungeon
    ? `🕳️ ${tr(h.dungeonName!)} · ${tr({ ru: "этаж", en: "floor" })} ${h.dungeonFloor}/${h.dungeonFloors} · ${tr({ ru: "врагов", en: "foes" })}: ${h.enemiesLeft}`
    : `${tr(h.townName ?? h.regionName)} · ${tr({ ru: "ур.", en: "Lv" })} ${h.regionLevel}`;
  // Окна, которые раньше висели кнопками на экране
  const tiles: { glyph: string; label: string; key: string; open: Parameters<typeof s.ui.open>[0]; dot?: boolean }[] = [
    { glyph: "bag", label: tr({ ru: "Сумка", en: "Bag" }), key: "I", open: "inventory" },
    { glyph: "cat", label: tr({ ru: "Кот", en: "Cat" }), key: "C", open: "character" },
    { glyph: "tree", label: tr({ ru: "Навыки", en: "Skills" }), key: "K", open: "skills", dot: h.skillPoints > 0 },
    { glyph: "scroll", label: tr({ ru: "Задания", en: "Quests" }), key: "J", open: "quests" },
    { glyph: "map", label: tr({ ru: "Карта", en: "Map" }), key: "M", open: "map" },
  ];
  return (
    <Panel title={{ ru: "Меню", en: "Menu" }} onClose={() => s.ui.close()}>
      <div className="col">
        <div className="menu-status">
          <b>
            {c.data.name} · {tr(CLASSES[c.data.classId].name)}
          </b>
          <span>
            {place} · 🐟 {fmtNum(h.fish)}
          </span>
        </div>
        <div className="menu-tiles">
          {tiles.map((t) => (
            <button key={t.open} className="menu-tile" onClick={() => s.ui.open(t.open)} title={t.key}>
              <Glyph name={t.glyph} size={24} />
              <span>{t.label}</span>
              {t.dot && <i className="dot">+{h.skillPoints}</i>}
            </button>
          ))}
        </div>
        <QuestTracker />
        <div className="muted" style={{ fontSize: 13 }}>
          {tr(modeLabel(c.data.mode))} · seed {c.data.seed}
        </div>
        <Btn kind="primary" onClick={() => s.ui.close()}>
          ▶ {tr({ ru: "Продолжить", en: "Resume" })}
        </Btn>
        <Btn
          onClick={() => {
            s.session?.saveNow();
            s.hud.toast({ ru: "Игра сохранена", en: "Game saved" }, 0x7ee081, "💾");
            s.ui.close();
          }}
        >
          💾 {tr({ ru: "Сохранить", en: "Save" })}
        </Btn>
        <Btn onClick={() => s.ui.open("coop")}>🤝 {tr({ ru: "Кооператив", en: "Co-op" })}</Btn>
        <Btn onClick={() => s.ui.open("settings")}>⚙️ {tr({ ru: "Настройки", en: "Settings" })}</Btn>
        <Btn onClick={() => s.ui.open("help")}>❓ {tr({ ru: "Управление", en: "Controls" })}</Btn>
        <Btn kind="danger" onClick={onQuit}>
          🚪 {tr({ ru: "Выйти в главное меню", en: "Quit to main menu" })}
        </Btn>
      </div>
    </Panel>
  );
});

export const SettingsPanel = observer(() => {
  const s = useStore();
  return (
    <Panel title={{ ru: "Настройки", en: "Settings" }} onClose={() => s.ui.close()}>
      <SettingsForm />
    </Panel>
  );
});

export const HelpPanel = observer(() => {
  const s = useStore();
  return (
    <Panel title={{ ru: "Управление", en: "Controls" }} onClose={() => s.ui.close()}>
      <div className="col" style={{ fontSize: 15, lineHeight: 1.5 }}>
        <div>
          <b>📱</b>{" "}
          {tr({
            ru: "Левая половина экрана — стик. Большая кнопка — атака (удерживайте). Кнопки навыков: нажмите — автоприцел, потяните — ручной прицел. Свайп справа — поворот камеры, два пальца — масштаб. Сумка, навыки, задания и карта — в меню ☰ у миникарты.",
            en: "Left half of the screen — stick. Big button — attack (hold). Skill buttons: tap to auto-aim, drag to aim. Swipe on the right to rotate the camera, pinch to zoom. Bag, skills, quests and map are in the ☰ menu by the minimap.",
          })}
        </div>
        <div>
          <b>🖥️</b>{" "}
          {tr({
            ru: "WASD — ходить, ЛКМ — атака, 1–6 — навыки, E — действие, Q/R или ПКМ — камера, колесо — масштаб, I/K/J/M/C — окна, V — мяу!",
            en: "WASD to move, LMB attack, 1–6 skills, E interact, Q/R or RMB camera, wheel zoom, I/K/J/M/C windows, V — meow!",
          })}
        </div>
      </div>
    </Panel>
  );
});

export const LorePopup = observer(() => {
  const s = useStore();
  const l = s.ui.lore;
  if (!l) return null;
  return (
    <div className="confirm" onPointerDown={(e) => e.target === e.currentTarget && (s.ui.lore = null)}>
      <div className="confirm-box">
        <h3 style={{ marginTop: 0 }}>📜 {tr(l.title)}</h3>
        <div className="dialog-bubble" style={{ fontStyle: "italic" }}>
          {tr(l.text)}
        </div>
        <div className="row" style={{ marginTop: 12, justifyContent: "flex-end" }}>
          <Btn onClick={() => (s.ui.lore = null)}>OK</Btn>
        </div>
      </div>
    </div>
  );
});

export const ConfirmPopup = observer(() => {
  const s = useStore();
  const c = s.ui.confirm;
  if (!c) return null;
  return (
    <div className="confirm">
      <div className="confirm-box">
        <div style={{ fontSize: 16, lineHeight: 1.4 }}>{tr(c.text)}</div>
        <div className="row" style={{ marginTop: 14, justifyContent: "flex-end" }}>
          <Btn kind="ghost" onClick={() => (s.ui.confirm = null)}>
            {tr({ ru: "Отмена", en: "Cancel" })}
          </Btn>
          <Btn
            kind="primary"
            onClick={() => {
              const ok = c.ok;
              s.ui.confirm = null;
              ok();
            }}
          >
            {c.okLabel ? tr(c.okLabel) : "OK"}
          </Btn>
        </div>
      </div>
    </div>
  );
});
