/**
 * Обёртка над RTCPeerConnection: два согласованных канала данных —
 * надёжный упорядоченный (события) и быстрый ненадёжный (снимки состояния).
 */
import { decodeSignal, encodeSignal, slimSdp, type SignalPayload } from "./signal";

export type PeerState = "new" | "gathering" | "waiting" | "connecting" | "open" | "closed";

const STUN = [{ urls: ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302"] }];

export class Peer {
  readonly pc: RTCPeerConnection;
  private reliable: RTCDataChannel;
  private fast: RTCDataChannel;
  state: PeerState = "new";
  onOpen: (() => void) | null = null;
  onClose: ((reason: string) => void) | null = null;
  onMessage: ((msg: unknown) => void) | null = null;
  private opened = 0;
  private closed = false;
  private discT: ReturnType<typeof setTimeout> | null = null;
  bytesIn = 0;
  bytesOut = 0;

  constructor(useStun: boolean) {
    this.pc = new RTCPeerConnection({ iceServers: useStun ? STUN : [] });
    this.reliable = this.pc.createDataChannel("rel", { negotiated: true, id: 0, ordered: true });
    this.fast = this.pc.createDataChannel("fast", { negotiated: true, id: 1, ordered: false, maxRetransmits: 0 });
    for (const ch of [this.reliable, this.fast]) {
      ch.onopen = () => {
        this.opened++;
        if (this.opened === 2) {
          this.state = "open";
          this.onOpen?.();
        }
      };
      ch.onclose = () => this.shutdown("channel");
      ch.onmessage = (ev) => {
        if (typeof ev.data !== "string") return;
        this.bytesIn += ev.data.length;
        let msg: unknown;
        try {
          msg = JSON.parse(ev.data);
        } catch {
          return;
        }
        this.onMessage?.(msg);
      };
    }
    this.pc.onconnectionstatechange = () => {
      const st = this.pc.connectionState;
      if (st === "failed" || st === "closed") this.shutdown(st);
      else if (st === "disconnected") {
        // Может восстановиться само — ждём немного
        if (this.discT) clearTimeout(this.discT);
        this.discT = setTimeout(() => {
          if (this.pc.connectionState === "disconnected") this.shutdown("disconnected");
        }, 8000);
      } else if (st === "connected" && this.discT) {
        clearTimeout(this.discT);
        this.discT = null;
      }
    };
  }

  private waitIce(timeoutMs: number): Promise<void> {
    const pc = this.pc;
    return new Promise((resolve) => {
      if (pc.iceGatheringState === "complete") return resolve();
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        clearTimeout(t);
        pc.removeEventListener("icegatheringstatechange", check);
        pc.removeEventListener("icecandidate", onCand);
        resolve();
      };
      const check = () => {
        if (pc.iceGatheringState === "complete") finish();
      };
      const onCand = (e: RTCPeerConnectionIceEvent) => {
        if (!e.candidate) finish();
      };
      const t = setTimeout(finish, timeoutMs);
      pc.addEventListener("icegatheringstatechange", check);
      pc.addEventListener("icecandidate", onCand);
    });
  }

  /** Хост: создать код приглашения. */
  async createOffer(meta: Omit<SignalPayload, "sdp">): Promise<string> {
    this.state = "gathering";
    const offer = await this.pc.createOffer();
    await this.pc.setLocalDescription(offer);
    await this.waitIce(6000);
    this.state = "waiting";
    return encodeSignal("offer", { ...meta, sdp: slimSdp(this.pc.localDescription!.sdp) });
  }

  /** Гость: принять приглашение и создать код ответа. */
  async acceptOffer(payload: SignalPayload, meta: Omit<SignalPayload, "sdp">): Promise<string> {
    this.state = "gathering";
    await this.pc.setRemoteDescription({ type: "offer", sdp: payload.sdp });
    const answer = await this.pc.createAnswer();
    await this.pc.setLocalDescription(answer);
    await this.waitIce(6000);
    this.state = "connecting";
    return encodeSignal("answer", { ...meta, sdp: slimSdp(this.pc.localDescription!.sdp) });
  }

  /** Хост: применить код ответа гостя. */
  async acceptAnswer(code: string): Promise<SignalPayload> {
    const { kind, payload } = await decodeSignal(code);
    if (kind !== "answer") throw new Error("not-answer");
    this.state = "connecting";
    await this.pc.setRemoteDescription({ type: "answer", sdp: payload.sdp });
    return payload;
  }

  get isOpen() {
    return this.state === "open";
  }

  send(msg: unknown, reliable = true) {
    const ch = reliable ? this.reliable : this.fast;
    if (ch.readyState !== "open") return;
    // Ненадёжный канал: не копим очередь, если сеть не успевает
    if (!reliable && ch.bufferedAmount > 64 * 1024) return;
    const s = JSON.stringify(msg);
    this.bytesOut += s.length;
    try {
      ch.send(s);
    } catch {
      /* канал закрывается */
    }
  }

  private shutdown(reason: string) {
    if (this.closed) return;
    this.closed = true;
    this.state = "closed";
    if (this.discT) clearTimeout(this.discT);
    try {
      this.reliable.close();
      this.fast.close();
      this.pc.close();
    } catch {
      /* ignore */
    }
    this.onClose?.(reason);
  }

  close() {
    this.shutdown("local");
  }
}
