/** Персонаж игрока: сохраняемые данные + MobX-стор с вычисляемыми характеристиками и навыками. */
import { computed, makeObservable, observable, action } from "mobx";
import type { Txt } from "../core/i18n";
import { classLook, type CatLook } from "./cats/look";
import { CLASSES } from "./classes";
import { makeGear, SLOTS, type Item, type ItemSlot } from "./items";
import { levelCap, priceScale, skillPointsForLevel, xpToNext } from "./progression";
import { getTree, type SkillTree } from "./skills/generator";
import { applyMods, summarizeLearned, type LearnedSummary } from "./skills/resolve";
import type { SkillDef, SkillMod } from "./skills/types";
import { computeStats, type Stats } from "./stats";
import type { ClassId, ModeConfig } from "./types";
import { enemySkill } from "./sim/enemies";
import { Rng } from "../core/rng";

export const INVENTORY_SIZE = 48;
export const SKILL_SLOTS = 6;

export interface QuestProgress {
  /** id квеста → прогресс по целям */
  active: Record<string, number[]>;
  done: string[];
  tracked: string | null;
}

export interface DungeonRef {
  poiId: string;
  floor: number;
}

export interface CharacterData {
  v: 1;
  id: string;
  name: string;
  classId: ClassId;
  look: CatLook;
  mode: ModeConfig;
  seed: number;
  level: number;
  xp: number;
  skillPoints: number;
  learned: string[];
  slots: (string | null)[];
  inventory: (Item | null)[];
  equipment: Partial<Record<ItemSlot, Item>>;
  fish: number;
  quests: QuestProgress;
  discovered: string[];
  cleared: string[];
  pos: { x: number; z: number; dungeon: DungeonRef | null };
  story: { chapter: number; step: number };
  stats: { kills: number; deaths: number; playTime: number; bosses: number; dungeons: number; quests: number; maxLevel: number };
  createdAt: number;
  updatedAt: number;
}

export function newCharacter(o: { name: string; classId: ClassId; look?: Partial<CatLook>; mode: ModeConfig; seed: number }): CharacterData {
  const tree = getTree(o.classId, o.mode.skills === "infinite");
  const rng = new Rng(o.seed ^ 0x51ab);
  const inventory: (Item | null)[] = new Array(INVENTORY_SIZE).fill(null);
  const weapon = makeGear(rng, 1, 1, o.classId, "weapon");
  const collar = makeGear(rng, 1, 0, o.classId, "collar");
  return {
    v: 1,
    id: `c${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`,
    name: o.name,
    classId: o.classId,
    look: classLook(o.classId, o.look ?? {}),
    mode: o.mode,
    seed: o.seed,
    level: 1,
    xp: 0,
    skillPoints: skillPointsForLevel(1),
    learned: [tree.root.id],
    slots: new Array(SKILL_SLOTS).fill(null),
    inventory,
    equipment: { weapon, collar },
    fish: 20,
    quests: { active: {}, done: [], tracked: null },
    discovered: [],
    cleared: [],
    pos: { x: NaN, z: NaN, dungeon: null },
    story: { chapter: 0, step: 0 },
    stats: { kills: 0, deaths: 0, playTime: 0, bosses: 0, dungeons: 0, quests: 0, maxLevel: 1 },
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };
}

/**
 * Старые сохранения. Зелий в игре больше нет (здоровье и мана восстанавливаются сами),
 * поэтому оставшиеся зелья выкупаются рыбками по цене лавки.
 */
export function migrateCharacter(d: CharacterData): CharacterData {
  const old = (d as CharacterData & { potions?: { hp?: number; mp?: number } }).potions;
  if (old) {
    const n = Math.max(0, Math.floor(Number(old.hp) || 0)) + Math.max(0, Math.floor(Number(old.mp) || 0));
    d.fish += n * Math.max(2, Math.round(6 * priceScale(d.level)));
    delete (d as { potions?: unknown }).potions;
  }
  return d;
}

export class CharacterStore {
  data: CharacterData;
  /** Счётчик изменений для перерасчёта (избегаем глубокого наблюдения за огромными объектами). */
  rev = 0;
  buffs: { stat: import("./skills/types").StatKey; pct: number }[] = [];

  constructor(data: CharacterData) {
    this.data = migrateCharacter(data);
    makeObservable(this, {
      data: observable,
      rev: observable,
      tree: computed,
      summary: computed,
      stats: computed,
      skills: computed,
      basicSkill: computed,
      gearLook: computed,
      xpNeeded: computed,
      learnedSet: computed,
      touch: action,
      gainXp: action,
      learn: action,
      unlearnAll: action,
      setSlot: action,
      addItem: action,
      removeItem: action,
      equip: action,
      unequip: action,
      addFish: action,
    });
  }

  touch() {
    this.rev++;
    this.data.updatedAt = Date.now();
  }

  get tree(): SkillTree {
    return getTree(this.data.classId, this.data.mode.skills === "infinite");
  }

  get learnedSet(): Set<string> {
    void this.rev;
    return new Set(this.data.learned);
  }

  get summary(): LearnedSummary {
    void this.rev;
    return summarizeLearned(this.tree, this.data.learned);
  }

  get equippedItems(): Item[] {
    const out: Item[] = [];
    for (const s of SLOTS) {
      const it = this.data.equipment[s];
      if (it) out.push(it);
    }
    return out;
  }

  get stats(): Stats {
    void this.rev;
    const sum = this.summary;
    return computeStats({
      classId: this.data.classId,
      level: this.data.level,
      passives: sum.passives,
      keystones: sum.keystones,
      items: this.equippedItems,
    });
  }

  /** Все изученные активные навыки с применёнными улучшениями и легендарками. */
  get skills(): Map<string, SkillDef> {
    void this.rev;
    const sum = this.summary;
    const itemMods = new Map<string, SkillMod[]>();
    for (const it of this.equippedItems) {
      const lg = it.gear?.legendary;
      if (lg?.delivery && lg.mods) itemMods.set(lg.delivery, [...(itemMods.get(lg.delivery) ?? []), ...lg.mods]);
    }
    const out = new Map<string, SkillDef>();
    for (const n of sum.actives) {
      const base = n.skill!;
      const mods = [...(sum.modsBySkill.get(n.id) ?? []), ...(itemMods.get(base.delivery) ?? [])];
      if (base.delivery === "dash" && itemMods.get("dash")) mods.push(...[]);
      out.set(n.id, applyMods(base, mods));
    }
    return out;
  }

  get basicSkill(): SkillDef {
    const cls = CLASSES[this.data.classId];
    const b = cls.basic;
    const w = this.data.equipment.weapon;
    const color = w?.gear?.look?.weaponColor;
    const s = enemySkill(`basic:${cls.id}`, b.delivery, b.element, b.anim, { power: b.power, cooldown: b.cooldown, radius: b.radius ?? 2.3, range: b.range ?? 18, speed: b.speed ?? 20, castTime: 0.2, spread: 1.7, cost: 0 }, [], { basic: true });
    s.name = b.name;
    if (color && b.delivery === "projectile") s.visual = { ...s.visual, color };
    return s;
  }

  /** Внешность с учётом надетых предметов. */
  get gearLook(): CatLook {
    void this.rev;
    const L = { ...this.data.look };
    for (const it of this.equippedItems) {
      const lk = it.gear?.look;
      if (!lk) continue;
      if (lk.hat) {
        L.hat = lk.hat;
        L.hatColor = lk.hatColor ?? L.hatColor;
      }
      if (lk.weapon) {
        L.weapon = lk.weapon;
        L.weaponColor = lk.weaponColor ?? L.weaponColor;
      }
      if (lk.collar !== undefined) L.collar = lk.collar;
    }
    return L;
  }

  get xpNeeded(): number {
    return xpToNext(this.data.level);
  }

  get cap(): number {
    return levelCap(this.data.mode);
  }

  /** Возвращает количество полученных уровней. */
  gainXp(amount: number): number {
    const d = this.data;
    if (d.level >= this.cap) return 0;
    d.xp += amount;
    let ups = 0;
    while (d.xp >= xpToNext(d.level) && d.level < this.cap) {
      d.xp -= xpToNext(d.level);
      d.level++;
      d.skillPoints += skillPointsForLevel(d.level);
      ups++;
    }
    if (d.level >= this.cap) d.xp = 0;
    d.stats.maxLevel = Math.max(d.stats.maxLevel, d.level);
    this.touch();
    return ups;
  }

  canLearn(id: string): boolean {
    return this.data.skillPoints > 0 && this.tree.canLearn(id, this.learnedSet, this.data.level);
  }

  learn(id: string): boolean {
    if (!this.canLearn(id)) return false;
    this.data.learned.push(id);
    this.data.skillPoints--;
    const n = this.tree.get(id);
    // Новый активный навык — сразу в свободный слот
    if (n?.kind === "active") {
      const free = this.data.slots.indexOf(null);
      if (free >= 0) this.data.slots[free] = id;
    }
    if (this.data.mode.skills === "infinite") this.tree.expand(id);
    this.touch();
    return true;
  }

  unlearnAll() {
    const refund = this.data.learned.length - 1;
    this.data.learned = [this.tree.root.id];
    this.data.skillPoints += refund;
    this.data.slots = new Array(SKILL_SLOTS).fill(null);
    this.touch();
  }

  setSlot(i: number, id: string | null) {
    const s = this.data.slots;
    const prev = s.indexOf(id);
    if (id && prev >= 0) s[prev] = s[i];
    s[i] = id;
    this.touch();
  }

  addItem(it: Item): boolean {
    const inv = this.data.inventory;
    if (it.stack) {
      const same = inv.find((x) => x && x.kind === it.kind && x.name.ru === it.name.ru && x.questId === it.questId);
      if (same) {
        same.stack = (same.stack ?? 1) + (it.stack ?? 1);
        this.touch();
        return true;
      }
    }
    const free = inv.indexOf(null);
    if (free < 0) return false;
    inv[free] = it;
    this.touch();
    return true;
  }

  removeItem(id: string): Item | null {
    const inv = this.data.inventory;
    const i = inv.findIndex((x) => x?.id === id);
    if (i < 0) return null;
    const it = inv[i];
    inv[i] = null;
    this.touch();
    return it;
  }

  equip(id: string) {
    const it = this.removeItem(id);
    if (!it?.gear) {
      if (it) this.addItem(it);
      return;
    }
    const slot = it.gear.slot;
    const prev = this.data.equipment[slot];
    this.data.equipment[slot] = it;
    if (prev) this.addItem(prev);
    this.touch();
  }

  unequip(slot: ItemSlot) {
    const it = this.data.equipment[slot];
    if (!it) return;
    if (this.data.inventory.indexOf(null) < 0) return;
    delete this.data.equipment[slot];
    this.addItem(it);
    this.touch();
  }

  addFish(n: number) {
    this.data.fish += Math.round(n);
    this.touch();
  }

  get title(): Txt {
    const c = CLASSES[this.data.classId];
    return { ru: `${c.name.ru} · ${this.data.level} ур.`, en: `${c.name.en} · Lv ${this.data.level}` };
  }
}
