/** Состояние квестов игрока: принятие, прогресс, маркеры, сдача и награды. */
import { Rng, hashStr } from "../../core/rng";
import { dist } from "../../core/math";
import type { Txt } from "../../core/i18n";
import type { CharacterStore } from "../character";
import type { HudState } from "../hud";
import { makeGear, makeTome } from "../items";
import type { WorldGen } from "../world/worldgen";
import { objectiveNeeded, questsForTown } from "./gen";
import { storyChapter, storyQuest } from "./story";
import type { Objective, QuestDef } from "./types";

export interface GatherNode {
  questId: string;
  idx: number;
  x: number;
  z: number;
  color: number;
  icon: string;
}

export interface RewardResult {
  xp: number;
  fish: number;
  items: string[];
  skillPoints: number;
}

export class QuestSystem {
  private gathered = new Set<string>();
  private rescued = new Set<string>();

  constructor(
    private gen: WorldGen,
    private char: CharacterStore,
    private hud: HudState,
  ) {}

  private get q() {
    return this.char.data.quests;
  }

  get(id: string): QuestDef | null {
    if (id.startsWith("story:")) {
      const [, k, s] = id.split(":");
      return storyQuest(this.gen, parseInt(k), parseInt(s));
    }
    const m = /^(r-?\d+_-?\d+):t:q\d+$/.exec(id);
    if (!m) return null;
    const region = this.gen.regionById(m[1]);
    if (!region?.town) return null;
    return questsForTown(this.gen, region.town, region).find((q) => q.id === id) ?? null;
  }

  /** Текущий квест сюжета (всегда активен). */
  ensureStory() {
    const st = this.char.data.story;
    const id = `story:${st.chapter}:${st.step}`;
    if (!this.q.active[id] && !this.q.done.includes(id)) {
      const def = this.get(id);
      if (def) {
        this.q.active[id] = def.objectives.map(() => 0);
        if (!this.q.tracked) this.q.tracked = id;
        this.char.touch();
      }
    }
  }

  activeIds(): string[] {
    return Object.keys(this.q.active);
  }

  isDone(id: string) {
    return this.q.done.includes(id);
  }

  isActive(id: string) {
    return id in this.q.active;
  }

  isComplete(id: string): boolean {
    const def = this.get(id);
    const pr = this.q.active[id];
    if (!def || !pr) return false;
    return def.objectives.every((o, i) => pr[i] >= objectiveNeeded(o));
  }

  progress(id: string): number[] {
    return this.q.active[id] ?? [];
  }

  /** Квесты, которые может дать NPC (новые) и которые можно ему сдать. */
  forNpc(npcId: string, townId: string): { offer: QuestDef[]; turnIn: QuestDef[]; inProgress: QuestDef[] } {
    const region = this.gen.regionById(townId.split(":")[0]);
    const offer: QuestDef[] = [];
    const turnIn: QuestDef[] = [];
    const inProgress: QuestDef[] = [];
    if (region?.town) {
      for (const q of questsForTown(this.gen, region.town, region)) {
        if (q.giverNpcId !== npcId) continue;
        if (this.isDone(q.id)) continue;
        if (this.isActive(q.id)) {
          if (this.isComplete(q.id) && !q.turnInNpcId) turnIn.push(q);
          else inProgress.push(q);
          continue;
        }
        if (q.requires && !this.isDone(q.requires)) continue;
        offer.push(q);
      }
    }
    // Доставки и сюжет, сдаваемые этому NPC
    for (const id of this.activeIds()) {
      const q = this.get(id);
      if (!q) continue;
      if (q.turnInNpcId === npcId && this.isComplete(id)) turnIn.push(q);
      if (q.kind === "story") {
        const talkIdx = q.objectives.findIndex((o) => o.k === "talk" && o.npcId === npcId);
        if (talkIdx >= 0) turnIn.push(q);
      }
    }
    return { offer, turnIn, inProgress };
  }

  marker(npcId: string, townId: string): { icon: string; color: number } | null {
    const f = this.forNpc(npcId, townId);
    if (f.turnIn.length) return { icon: "?", color: 0xffd24a };
    if (f.offer.length) return { icon: "!", color: 0xffd24a };
    if (f.inProgress.length) return { icon: "?", color: 0xa0a0a8 };
    return null;
  }

  accept(id: string) {
    const def = this.get(id);
    if (!def || this.isActive(id) || this.isDone(id)) return;
    this.q.active[id] = def.objectives.map(() => 0);
    this.q.tracked = id;
    this.hud.toast({ ru: `Новое задание: ${def.title.ru}`, en: `New quest: ${def.title.en}` }, 0xffd24a, "📜");
    this.char.touch();
  }

  abandon(id: string) {
    if (id.startsWith("story:")) return;
    delete this.q.active[id];
    if (this.q.tracked === id) this.q.tracked = this.activeIds()[0] ?? null;
    this.char.touch();
  }

  private bump(id: string, idx: number, n = 1) {
    const pr = this.q.active[id];
    if (!pr) return;
    const def = this.get(id);
    if (!def) return;
    const need = objectiveNeeded(def.objectives[idx]);
    if (pr[idx] >= need) return;
    pr[idx] = Math.min(need, pr[idx] + n);
    const o = def.objectives[idx];
    if (o.k === "kill" || o.k === "collect" || o.k === "gather") {
      this.hud.toast({ ru: `${o.label.ru}: ${pr[idx]}/${need}`, en: `${o.label.en}: ${pr[idx]}/${need}` }, 0xe8e2d8);
    }
    if (this.isComplete(id)) {
      this.hud.toast({ ru: `Задание выполнено: ${def.title.ru}`, en: `Quest complete: ${def.title.en}` }, 0x7ee081, "✅");
    }
    this.char.touch();
  }

  /** Сдать квест (или засчитать разговор в сюжете). Возвращает награду, если квест завершён. */
  turnIn(id: string, npcId: string): RewardResult | null {
    const def = this.get(id);
    if (!def) return null;
    // Сюжетный разговор засчитывается при разговоре
    if (def.kind === "story") {
      const idx = def.objectives.findIndex((o) => o.k === "talk" && o.npcId === npcId);
      if (idx >= 0) this.q.active[id][idx] = 1;
    }
    if (!this.isComplete(id)) return null;
    delete this.q.active[id];
    this.q.done.push(id);
    const res = this.giveReward(def);
    this.char.data.stats.quests++;
    if (def.kind === "story") {
      const st = this.char.data.story;
      if (st.step >= 2) {
        st.chapter++;
        st.step = 0;
      } else st.step++;
      this.ensureStory();
      const next = `story:${st.chapter}:${st.step}`;
      this.q.tracked = next;
    } else if (this.q.tracked === id) this.q.tracked = `story:${this.char.data.story.chapter}:${this.char.data.story.step}`;
    this.char.touch();
    return res;
  }

  private giveReward(def: QuestDef): RewardResult {
    const r = def.reward;
    const d = this.char.data;
    const rng = new Rng(hashStr(def.id + d.id));
    const items: string[] = [];
    const xp = Math.round(r.xp * (1 + this.char.stats.xpBonus));
    this.char.gainXp(xp);
    this.char.addFish(r.fish);
    if (r.item) {
      const it = makeGear(rng, Math.max(def.level, 1), r.item.rarity as 0, d.classId);
      if (this.char.addItem(it)) items.push(it.name.ru);
    }
    if (r.tome) {
      const t = makeTome(def.level);
      if (this.char.addItem(t)) items.push(t.name.ru);
    }
    if (r.skillPoints) d.skillPoints += r.skillPoints;
    return { xp, fish: r.fish, items, skillPoints: r.skillPoints };
  }

  // ───────────── события игры ─────────────

  onKill(family: string | undefined, x: number, z: number, elite: boolean, boss: boolean, poiId: string | undefined, rng: Rng): { collected?: Txt } {
    let collected: Txt | undefined;
    for (const id of this.activeIds()) {
      const def = this.get(id);
      if (!def) continue;
      def.objectives.forEach((o, i) => {
        if (o.k === "kill") {
          if (o.family && o.family !== family) return;
          if (o.area && dist(x, z, o.area.x, o.area.z) > o.area.r) return;
          this.bump(id, i);
        } else if (o.k === "collect") {
          if (o.family && o.family !== family) return;
          if (o.area && dist(x, z, o.area.x, o.area.z) > o.area.r) return;
          if (rng.chance(o.chance)) {
            this.bump(id, i);
            collected = o.item;
          }
        } else if (o.k === "elite" && elite && poiId === o.poiId) this.bump(id, i);
        else if (o.k === "dungeon" && boss && poiId === o.poiId) this.bump(id, i);
      });
    }
    return { collected };
  }

  onDungeonBoss(poiId: string) {
    for (const id of this.activeIds()) {
      const def = this.get(id);
      def?.objectives.forEach((o, i) => {
        if (o.k === "dungeon" && o.poiId === poiId) this.bump(id, i);
      });
    }
  }

  onTalk(npcId: string) {
    for (const id of this.activeIds()) {
      const def = this.get(id);
      if (!def || def.kind === "story") continue;
      def.objectives.forEach((o, i) => {
        if (o.k === "talk" && o.npcId === npcId) this.bump(id, i);
      });
    }
  }

  /** Периодическая проверка «посетить место». */
  onVisit(x: number, z: number) {
    for (const id of this.activeIds()) {
      const def = this.get(id);
      def?.objectives.forEach((o, i) => {
        if (o.k === "visit" && dist(x, z, o.area.x, o.area.z) < o.area.r) this.bump(id, i);
      });
    }
  }

  gatherNodes(): GatherNode[] {
    const out: GatherNode[] = [];
    for (const id of this.activeIds()) {
      const def = this.get(id);
      if (!def) continue;
      def.objectives.forEach((o: Objective, i) => {
        if (o.k !== "gather") return;
        if ((this.q.active[id][i] ?? 0) >= o.count) return;
        const rng = new Rng(hashStr(id + ":g"));
        for (let k = 0; k < o.count + 3; k++) {
          const key = `${id}:${k}`;
          if (this.gathered.has(key)) continue;
          const a = rng.next() * Math.PI * 2;
          const r = Math.sqrt(rng.next()) * o.area.r;
          out.push({ questId: id, idx: k, x: o.area.x + Math.cos(a) * r, z: o.area.z + Math.sin(a) * r, color: o.color, icon: o.icon });
        }
      });
    }
    return out;
  }

  gather(node: GatherNode) {
    const key = `${node.questId}:${node.idx}`;
    if (this.gathered.has(key)) return;
    this.gathered.add(key);
    const def = this.get(node.questId);
    const i = def?.objectives.findIndex((o) => o.k === "gather") ?? -1;
    if (i >= 0) this.bump(node.questId, i);
  }

  /** Потерявшиеся котята для активных квестов спасения. */
  rescueTargets(): { questId: string; x: number; z: number; name: Txt }[] {
    const out: { questId: string; x: number; z: number; name: Txt }[] = [];
    for (const id of this.activeIds()) {
      const def = this.get(id);
      def?.objectives.forEach((o, i) => {
        if (o.k === "rescue" && (this.q.active[id][i] ?? 0) < 1 && !this.rescued.has(id)) out.push({ questId: id, x: o.at.x, z: o.at.z, name: o.kittenName });
      });
    }
    return out;
  }

  rescue(questId: string) {
    this.rescued.add(questId);
    const def = this.get(questId);
    const i = def?.objectives.findIndex((o) => o.k === "rescue") ?? -1;
    if (i >= 0) this.bump(questId, i);
  }

  /** Цель для компаса: ближайшая незавершённая цель отслеживаемого квеста. */
  trackedTarget(): { x: number; z: number; label: Txt } | null {
    const id = this.q.tracked;
    if (!id) return null;
    const def = this.get(id);
    const pr = this.q.active[id];
    if (!def || !pr) return null;
    if (this.isComplete(id)) {
      // вернуться к квестодателю
      const region = this.gen.regionById(def.townId.split(":")[0]);
      const town = region?.town;
      if (def.turnInNpcId) {
        const o = def.objectives.find((o) => o.k === "talk");
        if (o && o.k === "talk") return { x: o.at.x, z: o.at.z, label: o.label };
      }
      if (town) return { x: town.x, z: town.z, label: { ru: `Сдать: ${def.title.ru}`, en: `Turn in: ${def.title.en}` } };
      return null;
    }
    for (let i = 0; i < def.objectives.length; i++) {
      const o = def.objectives[i];
      if (pr[i] >= objectiveNeeded(o)) continue;
      switch (o.k) {
        case "kill":
        case "collect":
          if (o.area) return { x: o.area.x, z: o.area.z, label: o.label };
          break;
        case "gather":
        case "visit":
          return { x: o.area.x, z: o.area.z, label: o.label };
        case "talk":
        case "dungeon":
        case "elite":
        case "rescue":
          return { x: o.at.x, z: o.at.z, label: o.label };
      }
    }
    return null;
  }

  storyChapterInfo() {
    return storyChapter(this.gen, this.char.data.story.chapter);
  }
}
