/**
 * Коды приглашения и ответа для ручного обмена SDP (без сигнального сервера).
 * SDP + метаданные → JSON → deflate-raw → base64url. Код можно отправить в любом мессенджере.
 */

export type SignalKind = "offer" | "answer";

export interface SignalPayload {
  sdp: string;
  /** Имя игрока, отправившего код. */
  name: string;
  /** Для приглашения: краткие сведения о мире хоста. */
  host?: { level: number; classId: string; mode: { world: string; skills: string; levels: string }; seed: number };
  v: number;
}

export const PROTOCOL_VERSION = 3;
const PREFIX: Record<SignalKind, string> = { offer: "MO", answer: "MA" };

function toB64Url(bytes: Uint8Array): string {
  let s = "";
  const CH = 0x8000;
  for (let i = 0; i < bytes.length; i += CH) s += String.fromCharCode(...bytes.subarray(i, i + CH));
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function fromB64Url(str: string): Uint8Array {
  const b = str.replace(/-/g, "+").replace(/_/g, "/");
  const pad = b.length % 4 ? "=".repeat(4 - (b.length % 4)) : "";
  const bin = atob(b + pad);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const body = new Blob([bytes as Uint8Array<ArrayBuffer>]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(body).arrayBuffer());
}

/** Убираем из SDP то, что не нужно для канала данных (делает код короче). */
export function slimSdp(sdp: string): string {
  return sdp
    .split(/\r?\n/)
    .filter((l) => l && !(l.startsWith("a=candidate") && / tcp /i.test(l)))
    .join("\r\n")
    .concat("\r\n");
}

export async function encodeSignal(kind: SignalKind, payload: SignalPayload): Promise<string> {
  const bytes: Uint8Array = new TextEncoder().encode(JSON.stringify(payload));
  let packed: Uint8Array = bytes;
  let flag = "r";
  if (typeof CompressionStream !== "undefined") {
    try {
      packed = await pipe(bytes, new CompressionStream("deflate-raw"));
      flag = "z";
    } catch {
      packed = bytes;
      flag = "r";
    }
  }
  return PREFIX[kind] + flag + toB64Url(packed);
}

/** Достаёт код из текста: принимает как сам код, так и ссылку-приглашение. */
export function extractCode(text: string): string {
  const t = text.trim();
  const m = t.match(/[#?&](?:join|answer)=([A-Za-z0-9_-]+)/);
  if (m) return m[1];
  const m2 = t.match(/M[OA][zr][A-Za-z0-9_-]{20,}/);
  if (m2) return m2[0];
  return t.replace(/\s+/g, "");
}

export async function decodeSignal(text: string): Promise<{ kind: SignalKind; payload: SignalPayload }> {
  const code = extractCode(text);
  const kind: SignalKind | null = code.startsWith(PREFIX.offer) ? "offer" : code.startsWith(PREFIX.answer) ? "answer" : null;
  if (!kind) throw new Error("bad-code");
  const flag = code[2];
  const body = fromB64Url(code.slice(3));
  let bytes: Uint8Array = body;
  if (flag === "z") {
    if (typeof DecompressionStream === "undefined") throw new Error("no-decompress");
    bytes = await pipe(body, new DecompressionStream("deflate-raw"));
  }
  const payload = JSON.parse(new TextDecoder().decode(bytes)) as SignalPayload;
  if (!payload || typeof payload.sdp !== "string") throw new Error("bad-code");
  return { kind, payload };
}

export function inviteLink(code: string): string {
  const base = `${location.origin}${location.pathname}`;
  return `${base}#join=${code}`;
}

/** Ссылка-ответ: открывается на устройстве хоста и передаёт код во вкладку с игрой. */
export function answerLink(code: string): string {
  const base = `${location.origin}${location.pathname}`;
  return `${base}#answer=${code}`;
}

/** Канал между вкладками одного браузера (ответ по ссылке → вкладка хоста). */
export const RELAY_CHANNEL = "kotoverse-coop";
