/** Состояние HUD (MobX), обновляется сессией ~10 раз в секунду. */
import { makeAutoObservable } from "mobx";
import type { Txt } from "../core/i18n";

export interface SlotView {
  id: string | null;
  cd: number;
  cdTotal: number;
  noMana: boolean;
  color: number;
  glyph: string;
  name: Txt | null;
}

export interface TargetView {
  name: Txt;
  level: number;
  hp: number;
  maxHp: number;
  elite: boolean;
  boss: boolean;
}

export interface InteractView {
  kind: "npc" | "loot" | "dungeon" | "waystone" | "chest" | "shrine" | "obelisk" | "exit" | "gather" | "stairs" | "rescue" | "climb";
  label: Txt;
  id: string;
}

export interface Toast {
  id: number;
  text: Txt;
  color: number;
  t: number;
  icon?: string;
}

export class HudState {
  hp = 1;
  maxHp = 1;
  mp = 1;
  maxMp = 1;
  shield = 0;
  xp = 0;
  xpNeeded = 1;
  level = 1;
  fish = 0;
  /** Кот отдыхает вне боя и быстро восстанавливается. */
  resting = false;
  basicCd = 0;
  slots: SlotView[] = [];
  target: TargetView | null = null;
  boss: TargetView | null = null;
  interact: InteractView | null = null;
  regionName: Txt = { ru: "", en: "" };
  regionLevel = 1;
  townName: Txt | null = null;
  dead = false;
  respawnIn = 0;
  fps = 0;
  toasts: Toast[] = [];
  loading = 1;
  inDungeon = false;
  dungeonName: Txt | null = null;
  dungeonFloor = 0;
  dungeonFloors = 0;
  enemiesLeft = 0;
  compass: { angle: number; dist: number; label: Txt } | null = null;
  timeOfDay = 0.3;
  playerX = 0;
  playerZ = 0;
  playerYaw = 0;
  camYaw = 0;
  levelUpFlash = 0;
  skillPoints = 0;
  coop: { name: string; hp: number; maxHp: number; level: number } | null = null;
  private toastId = 1;

  constructor() {
    makeAutoObservable(this);
  }

  toast(text: Txt, color = 0xffffff, icon?: string) {
    this.toasts.push({ id: this.toastId++, text, color, t: 4, icon });
    if (this.toasts.length > 5) this.toasts.shift();
  }

  tick(dt: number) {
    if (!this.toasts.length) return;
    let expired = false;
    for (const t of this.toasts) {
      t.t -= dt;
      if (t.t <= 0) expired = true;
    }
    if (expired) this.toasts = this.toasts.filter((t) => t.t > 0);
  }
}
