/**
 * Общие куски GLSL: блок кадровых юниформов, цвет, шум, небо (для тумана и отражений),
 * освещение с картой теней, туман, декали.
 *
 * Освещение считается в линейном пространстве (цвета из hex переводятся sRGB → linear),
 * кадр рисуется в HDR-буфер, а тональная кривая и гамма применяются в пост-обработке.
 */

export const MAX_LIGHTS = 8;
export const MAX_SHADOWS = 24;
export const MAX_DECALS = 16;

/** Раскладка std140 блока Frame (в float-ах). */
export const FRAME = {
  viewProj: 0,
  view: 16,
  camPos: 32, // xyz, w = time
  sunDir: 36, // направление света (солнце или луна), w = интенсивность
  sunColor: 40, // rgb (linear), w = ambient
  skyColor: 44, // rgb зенит, w = подземелье (1/0)
  horizon: 48, // rgb горизонт/туман, w = начало тумана
  ground: 52, // rgb отражённый от земли, w = конец тумана
  originMod: 56, // xy = origin mod 1024, z = ночь, w = качество
  playerLight: 60, // xyz, w = радиус
  lights: 64, // 8 × vec4 pos+radius
  lightColors: 96, // 8 × vec4 rgb+intensity
  shadows: 128, // 24 × vec4 xyz + radius (пятна-тени)
  counts: 224, // x огни, y пятна, z декали, w = карта теней включена
  decals: 228, // 16 × vec4 xyz + radius
  decalColors: 292, // 16 × vec4 rgb + mode
  decalParams: 356, // 16 × vec4 (progress, alpha, inner, _)
  focus: 420, // xyz — точка, которую нельзя загораживать (игрок), w — радиус (0 — выкл.)
  shadowMat: 424, // mat4: мир → [0..1] карты теней
  shadowParams: 440, // x = размер текселя в мире, y = сила, z = 1/разрешение, w = число выборок
  sunTrue: 444, // xyz настоящее направление на солнце, w = видимость луны
  moonDir: 448, // xyz направление на луну, w = сияние (0..1)
  wind: 452, // xy направление ветра, z сила, w облачность
  fogParams: 456, // x плотность тумана в низинах, y спад с высотой, z рассеяние солнца, w сырость
  misc: 460, // x = уровень воды, y = снег, zw резерв
  size: 464,
} as const;

export const FRAME_GLSL = /* glsl */ `
layout(std140) uniform Frame {
  mat4 uViewProj;
  mat4 uView;
  vec4 uCamPos;
  vec4 uSunDir;
  vec4 uSunColor;
  vec4 uSkyColor;
  vec4 uHorizon;
  vec4 uGround;
  vec4 uOriginMod;
  vec4 uPlayerLight;
  vec4 uLights[${MAX_LIGHTS}];
  vec4 uLightColors[${MAX_LIGHTS}];
  vec4 uShadows[${MAX_SHADOWS}];
  vec4 uCounts;
  vec4 uDecals[${MAX_DECALS}];
  vec4 uDecalColors[${MAX_DECALS}];
  vec4 uDecalParams[${MAX_DECALS}];
  vec4 uFocus;
  mat4 uShadowMat;
  vec4 uShadowParams;
  vec4 uSunTrue;
  vec4 uMoonDir;
  vec4 uWind;
  vec4 uFogParams;
  vec4 uMisc;
};
`;

export const HEADER = `#version 300 es
precision highp float;
precision highp int;
precision highp sampler2DArray;
precision highp sampler2DShadow;
`;

/** Цвет и шум — можно подключать и в вершинные, и во фрагментные шейдеры. */
export const UTIL_GLSL = /* glsl */ `
vec3 toLinear(vec3 c) { return c * c * (c * 0.2 + 0.8); }
float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float hash13(vec3 p3) {
  p3 = fract(p3 * 0.1031);
  p3 += dot(p3, p3.zyx + 31.32);
  return fract((p3.x + p3.y) * p3.z);
}
vec3 hash33(vec3 p3) {
  p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yxz + 33.33);
  return fract((p3.xxy + p3.yxx) * p3.zyx);
}
vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), u.x),
             mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm3(vec2 p) {
  return vnoise(p) * 0.55 + vnoise(p * 2.03 + 17.1) * 0.28 + vnoise(p * 4.07 + 31.7) * 0.17;
}
// Ячеистый шум: x — расстояние до ближайшей точки, y — до второй, z — хеш ячейки
vec3 voronoi(vec2 p) {
  vec2 n = floor(p);
  vec2 f = fract(p);
  float d1 = 8.0, d2 = 8.0, id = 0.0;
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 o = hash22(n + g);
      vec2 r = g + o - f;
      float d = dot(r, r);
      if (d < d1) { d2 = d1; d1 = d; id = hash12(n + g + 3.7); }
      else if (d < d2) d2 = d;
    }
  return vec3(sqrt(d1), sqrt(d2), id);
}
`;

/**
 * Небо без диска солнца и облаков: общий градиент для неба, тумана и отражений в воде.
 * uSunTrue — настоящее положение солнца (ниже горизонта ночью), даёт зори.
 */
export const SKY_GLSL = /* glsl */ `
vec3 skyGradient(vec3 dir) {
  float h = dir.y;
  vec3 zen = uSkyColor.rgb;
  vec3 hor = uHorizon.rgb;
  vec3 col = mix(hor, zen, pow(clamp(h, 0.0, 1.0), 0.42));
  if (h < 0.0) col = mix(hor, uGround.rgb * 0.5 + hor * 0.5, clamp(-h * 3.0, 0.0, 1.0));
  vec3 sd = normalize(uSunTrue.xyz);
  float mu = max(dot(dir, sd), 0.0);
  float up = clamp(sd.y * 4.0 + 0.45, 0.0, 1.0);
  // Тёплое свечение вокруг солнца (сильнее у горизонта — зори)
  float low = 1.0 - clamp(abs(sd.y) * 3.2, 0.0, 1.0);
  vec3 glow = mix(vec3(1.0, 0.58, 0.28), vec3(1.0, 0.36, 0.12), low);
  glow = mix(vec3(1.0, 0.92, 0.78), glow, clamp(low * 1.4, 0.0, 1.0));
  col += glow * (pow(mu, 6.0) * (0.25 + 0.55 * low) + pow(mu, 48.0) * 0.9) * up;
  // Полоса зари вдоль горизонта со стороны солнца
  float band = exp(-abs(h) * 9.0) * low * up;
  float side = 0.35 + 0.65 * pow(max(dot(normalize(dir.xz + 1e-4), normalize(sd.xz + 1e-4)), 0.0), 2.0);
  col += vec3(1.0, 0.42, 0.2) * band * side * 0.7;
  return col;
}
`;

/** Только для фрагментных шейдеров. */
export const FOCUS_GLSL = /* glsl */ `
// Окно видимости: объекты между камерой и игроком растворяются сеткой Байера.
const float BAYER4[16] = float[16](0.0, 8.0, 2.0, 10.0, 12.0, 4.0, 14.0, 6.0, 3.0, 11.0, 1.0, 9.0, 15.0, 7.0, 13.0, 5.0);
bool focusCutout(vec3 wpos) {
  if (uFocus.w <= 0.0) return false;
  vec3 a = uFocus.xyz;
  vec3 ab = uCamPos.xyz - a;
  vec3 ap = wpos - a;
  float t = dot(ap, ab) / max(dot(ab, ab), 1e-4);
  if (t < 0.03 || t > 0.98) return false;
  float d = length(ap - ab * t);
  float r = uFocus.w * (0.55 + t * 1.6);
  if (d > r) return false;
  float k = 1.0 - smoothstep(r * 0.45, r, d);
  ivec2 q = ivec2(mod(gl_FragCoord.xy, 4.0));
  float th = (BAYER4[q.x + q.y * 4] + 0.5) / 16.0;
  return th < k * 0.82;
}
`;

/** Освещение (фрагментные шейдеры). Требует UTIL_GLSL и SKY_GLSL. */
export const LIGHTING_GLSL = /* glsl */ `
uniform highp sampler2DShadow uShadowMap;

// Мягкая тень от солнца: смещение по нормали + аппаратный PCF в 4 или 9 выборках
float sunShadow(vec3 wpos, vec3 N) {
  if (uCounts.w < 0.5) return 1.0;
  float ndl = dot(N, uSunDir.xyz);
  vec3 p = wpos + N * uShadowParams.x * (1.2 + 1.8 * (1.0 - abs(ndl))) + uSunDir.xyz * uShadowParams.x * 0.6;
  vec3 s = (uShadowMat * vec4(p, 1.0)).xyz;
  if (s.x < 0.0 || s.y < 0.0 || s.x > 1.0 || s.y > 1.0 || s.z > 1.0) return 1.0;
  float t = uShadowParams.z;
  float sh;
  if (uShadowParams.w < 2.0) {
    sh = texture(uShadowMap, s);
  } else if (uShadowParams.w > 5.0) {
    sh = 0.0;
    for (int j = -1; j <= 1; j++)
      for (int i = -1; i <= 1; i++) sh += texture(uShadowMap, vec3(s.xy + vec2(float(i), float(j)) * t * 1.25, s.z));
    sh /= 9.0;
  } else {
    sh = texture(uShadowMap, vec3(s.xy + vec2(-0.6, -0.6) * t, s.z));
    sh += texture(uShadowMap, vec3(s.xy + vec2(0.6, -0.6) * t, s.z));
    sh += texture(uShadowMap, vec3(s.xy + vec2(-0.6, 0.6) * t, s.z));
    sh += texture(uShadowMap, vec3(s.xy + vec2(0.6, 0.6) * t, s.z));
    sh *= 0.25;
  }
  vec2 e = abs(s.xy - 0.5) * 2.0;
  float fade = smoothstep(0.82, 1.0, max(e.x, e.y));
  return mix(1.0, mix(sh, 1.0, fade), uShadowParams.y);
}

vec3 pointLights(vec3 N, vec3 wpos) {
  vec3 acc = vec3(0.0);
  int n = int(uCounts.x);
  for (int i = 0; i < ${MAX_LIGHTS}; i++) {
    if (i >= n) break;
    vec3 d = uLights[i].xyz - wpos;
    float dist = length(d);
    float att = clamp(1.0 - dist / uLights[i].w, 0.0, 1.0);
    att *= att;
    float nd = max(dot(N, d / max(dist, 0.001)), 0.0) * 0.75 + 0.25;
    acc += uLightColors[i].rgb * uLightColors[i].w * att * nd;
  }
  // Фонарь игрока: работает ночью и в подземельях.
  if (uPlayerLight.w > 0.0) {
    vec3 d = uPlayerLight.xyz - wpos;
    float dist = length(d);
    float att = clamp(1.0 - dist / uPlayerLight.w, 0.0, 1.0);
    float strength = max(uOriginMod.z, uSkyColor.w) * 0.75;
    acc += vec3(1.0, 0.72, 0.42) * att * att * strength * (max(dot(N, d / max(dist, 0.001)), 0.0) * 0.6 + 0.4);
  }
  return acc;
}

float blobShadows(vec3 wpos) {
  float s = 1.0;
  int n = int(uCounts.y);
  for (int i = 0; i < ${MAX_SHADOWS}; i++) {
    if (i >= n) break;
    vec4 c = uShadows[i];
    vec2 d = wpos.xz - c.xz;
    float dd = dot(d, d);
    float r = c.w;
    if (dd > r * r) continue;
    float k = 1.0 - smoothstep(r * 0.15, r, sqrt(dd));
    float hk = 1.0 - clamp(abs(wpos.y - c.y) / 2.5, 0.0, 1.0);
    s *= 1.0 - 0.55 * k * hk;
  }
  return s;
}

vec3 ambientLight(vec3 N) {
  vec3 skyAmb = mix(uHorizon.rgb, uSkyColor.rgb, 0.55);
  vec3 grd = uGround.rgb;
  return mix(grd, skyAmb, N.y * 0.5 + 0.5) * uSunColor.w;
}

/**
 * Стилизованное освещение: мягкий терминатор, небо/земля, тень, огни, блик.
 * spec: сила блика (0 — матово), gloss: острота.
 */
vec3 shadeFull(vec3 albedo, vec3 N, vec3 V, vec3 wpos, float emissive, float ao, float spec, float gloss, float shadow) {
  float ndl = dot(N, uSunDir.xyz);
  float diff = clamp((ndl + 0.22) / 1.22, 0.0, 1.0);
  diff = diff * diff * (3.0 - 2.0 * diff);
  vec3 sun = uSunColor.rgb * uSunDir.w * diff * shadow;
  vec3 light = ambientLight(N) * ao + sun;
  light += pointLights(N, wpos);
  vec3 col = albedo * light;
  if (spec > 0.0) {
    vec3 H = normalize(uSunDir.xyz + V);
    float s = pow(max(dot(N, H), 0.0), gloss) * (gloss + 2.0) / 8.0;
    col += uSunColor.rgb * uSunDir.w * s * spec * shadow * step(0.0, ndl);
  }
  return col + albedo * emissive * 3.2;
}

vec3 shade(vec3 albedo, vec3 N, vec3 wpos, float emissive, float ao) {
  return shadeFull(albedo, N, normalize(uCamPos.xyz - wpos), wpos, emissive, ao, 0.0, 16.0, sunShadow(wpos, N));
}

vec3 fogColor(vec3 dir) {
  if (uSkyColor.w > 0.5) return uHorizon.rgb;
  vec3 d = dir;
  d.y = max(d.y, 0.02);
  return skyGradient(normalize(d));
}

vec3 fog(vec3 col, vec3 wpos) {
  vec3 dv = wpos - uCamPos.xyz;
  float dist = length(dv);
  vec3 dir = dv / max(dist, 1e-3);
  float f = smoothstep(uHorizon.w, uGround.w, dist);
  f = f * f * (3.0 - 2.0 * f);
  // Туман в низинах: тем плотнее, чем ниже точка
  if (uSkyColor.w < 0.5) {
    float hf = uFogParams.x * exp(-max(wpos.y + 2.0, 0.0) * uFogParams.y) * (1.0 - exp(-dist * 0.018));
    f = max(f, clamp(hf, 0.0, 0.85));
  }
  return mix(col, fogColor(dir), f);
}

// Декали на земле: 0 — кольцо, 1 — мягкий круг, 2 — телеграф атаки (заполняется), 3 — метка цели
vec3 applyDecals(vec3 col, vec3 wpos) {
  int n = int(uCounts.z);
  for (int i = 0; i < ${MAX_DECALS}; i++) {
    if (i >= n) break;
    vec4 d = uDecals[i];
    vec2 dv = wpos.xz - d.xz;
    float r = d.w;
    float dist = length(dv);
    if (dist > r + 0.3) continue;
    if (abs(wpos.y - d.y) > 4.0) continue;
    vec4 c = uDecalColors[i];
    vec4 pr = uDecalParams[i];
    float a = 0.0;
    int mode = int(c.w + 0.5);
    if (mode == 0) {
      a = (1.0 - smoothstep(0.0, 0.12, abs(dist - r * 0.92))) * 0.9;
    } else if (mode == 1) {
      a = (1.0 - smoothstep(r * 0.55, r, dist)) * 0.5;
    } else if (mode == 2) {
      float edge = 1.0 - smoothstep(0.0, 0.14, abs(dist - r * 0.96));
      float fill = step(dist, r * pr.x) * 0.35 + (1.0 - smoothstep(r * 0.7, r, dist)) * 0.12;
      a = max(edge * 0.95, fill);
    } else {
      float ang = atan(dv.y, dv.x);
      float dash = step(0.0, sin(ang * 6.0 + uCamPos.w * 3.0));
      a = (1.0 - smoothstep(0.0, 0.1, abs(dist - r))) * (0.5 + 0.5 * dash);
    }
    a *= pr.y;
    col = mix(col, c.rgb * (mode == 1 ? 1.2 : 2.2), clamp(a, 0.0, 1.0));
  }
  return col;
}
`;

/** Полноэкранный треугольник (без вершинных буферов). */
export const FULLSCREEN_VS = `${HEADER}
out vec2 vUv;
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  vUv = p;
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
`;

/** Пустой фрагментный шейдер для прохода глубины (карта теней). */
export const DEPTH_FS = `${HEADER}
void main() {}
`;
