/**
 * Пост-обработка: сцена рисуется в HDR-буфер (RGBA16F, если есть EXT_color_buffer_float) с MSAA,
 * затем блум двойным фильтром (Bjørge, ARM) и финальный проход: тональная кривая, цветокоррекция,
 * виньетка, гамма и дизеринг. На слабом качестве вместо MSAA — FXAA в том же проходе.
 */
import { FULLSCREEN_VS, HEADER } from "./shaders/common";
import { type GL, Program } from "./gl";

export interface PostOptions {
  msaa: boolean;
  bloom: boolean;
  bloomLevels: number;
  fxaa: boolean;
}

/** Цветокоррекция кадра (меняется со временем суток и биомом). */
export interface Grade {
  exposure: number;
  bloom: number;
  saturation: number;
  contrast: number;
  vignette: number;
  /** Оттенок теней и светов (split toning), rgb 0..1 вокруг 0.5 — нейтрально. */
  shadowTint: [number, number, number];
  lightTint: [number, number, number];
}

const PREFILTER_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
uniform vec2 uThreshold; // x — порог, y — мягкое колено
out vec4 outColor;
vec3 pick(vec2 uv) {
  vec3 c = texture(uSrc, uv).rgb;
  float br = max(c.r, max(c.g, c.b));
  float soft = clamp(br - uThreshold.x + uThreshold.y, 0.0, 2.0 * uThreshold.y);
  soft = soft * soft / (4.0 * uThreshold.y + 1e-4);
  float w = max(soft, br - uThreshold.x) / max(br, 1e-4);
  // Вес Кариса гасит одиночные яркие пиксели (мерцание блума)
  return c * w / (1.0 + br * 0.25);
}
void main() {
  vec2 o = uTexel;
  vec3 c = pick(vUv + vec2(-o.x, -o.y)) + pick(vUv + vec2(o.x, -o.y)) + pick(vUv + vec2(-o.x, o.y)) + pick(vUv + vec2(o.x, o.y));
  outColor = vec4(c * 0.25, 1.0);
}
`;

const DOWN_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
out vec4 outColor;
void main() {
  vec2 o = uTexel * 0.5;
  vec3 c = texture(uSrc, vUv).rgb * 4.0;
  c += texture(uSrc, vUv - o).rgb;
  c += texture(uSrc, vUv + o).rgb;
  c += texture(uSrc, vUv + vec2(o.x, -o.y)).rgb;
  c += texture(uSrc, vUv + vec2(-o.x, o.y)).rgb;
  outColor = vec4(c / 8.0, 1.0);
}
`;

const UP_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec2 uTexel;
uniform float uWeight;
out vec4 outColor;
void main() {
  vec2 o = uTexel * 0.5;
  vec3 c = texture(uSrc, vUv + vec2(-o.x * 2.0, 0.0)).rgb;
  c += texture(uSrc, vUv + vec2(-o.x, o.y)).rgb * 2.0;
  c += texture(uSrc, vUv + vec2(0.0, o.y * 2.0)).rgb;
  c += texture(uSrc, vUv + vec2(o.x, o.y)).rgb * 2.0;
  c += texture(uSrc, vUv + vec2(o.x * 2.0, 0.0)).rgb;
  c += texture(uSrc, vUv + vec2(o.x, -o.y)).rgb * 2.0;
  c += texture(uSrc, vUv + vec2(0.0, -o.y * 2.0)).rgb;
  c += texture(uSrc, vUv + vec2(-o.x, -o.y)).rgb * 2.0;
  outColor = vec4(c / 12.0 * uWeight, 1.0);
}
`;

/** Лучи от солнца: радиальное размытие ярких пятен (неба у солнца) к экранной позиции солнца. */
const SHAFTS_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform sampler2D uSrc;
uniform vec3 uSun; // xy — солнце на экране (0..1), z — сила
out vec4 outColor;
void main() {
  const int N = 28;
  vec2 d = (uSun.xy - vUv) * (0.9 / float(N));
  vec2 uv = vUv;
  float decay = 1.0;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < N; i++) {
    uv += d;
    vec2 cuv = clamp(uv, vec2(0.001), vec2(0.999));
    acc += texture(uSrc, cuv).rgb * decay;
    decay *= 0.955;
  }
  // Ослабление у края экрана и вдали от солнца
  float falloff = exp(-length((vUv - uSun.xy) * vec2(1.6, 1.0)) * 1.4);
  outColor = vec4(acc / float(N) * uSun.z * falloff, 1.0);
}
`;

const COMPOSITE_FS = /* glsl */ `${HEADER}
in vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uBloom;
uniform sampler2D uShafts;
uniform float uShaftsOn;
uniform vec2 uTexel;
uniform vec4 uGrade0; // x экспозиция, y блум, z насыщенность, w контраст
uniform vec4 uGrade1; // x виньетка, y FXAA, z время, w есть блум
uniform vec3 uShadowTint;
uniform vec3 uLightTint;
out vec4 outColor;

float lumaOf(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float lumaT(vec3 c) { c = c / (1.0 + c); return lumaOf(c); }

vec3 fxaa(vec2 uv) {
  vec2 px = uTexel;
  vec3 nw = texture(uScene, uv + vec2(-1.0, -1.0) * px).rgb;
  vec3 ne = texture(uScene, uv + vec2(1.0, -1.0) * px).rgb;
  vec3 sw = texture(uScene, uv + vec2(-1.0, 1.0) * px).rgb;
  vec3 se = texture(uScene, uv + vec2(1.0, 1.0) * px).rgb;
  vec3 m = texture(uScene, uv).rgb;
  float lNW = lumaT(nw), lNE = lumaT(ne), lSW = lumaT(sw), lSE = lumaT(se), lM = lumaT(m);
  float lMin = min(lM, min(min(lNW, lNE), min(lSW, lSE)));
  float lMax = max(lM, max(max(lNW, lNE), max(lSW, lSE)));
  if (lMax - lMin < max(0.03, lMax * 0.12)) return m;
  vec2 dir = vec2(-((lNW + lNE) - (lSW + lSE)), (lNW + lSW) - (lNE + lSE));
  float red = max((lNW + lNE + lSW + lSE) * 0.03125, 1.0 / 128.0);
  float rcp = 1.0 / (min(abs(dir.x), abs(dir.y)) + red);
  dir = clamp(dir * rcp, vec2(-8.0), vec2(8.0)) * px;
  vec3 a = 0.5 * (texture(uScene, uv + dir * (1.0 / 3.0 - 0.5)).rgb + texture(uScene, uv + dir * (2.0 / 3.0 - 0.5)).rgb);
  vec3 b = a * 0.5 + 0.25 * (texture(uScene, uv - dir * 0.5).rgb + texture(uScene, uv + dir * 0.5).rgb);
  float lB = lumaT(b);
  return (lB < lMin || lB > lMax) ? a : b;
}

// Нейтральная кривая Khronos PBR Neutral: сохраняет цвета в средних тонах, мягко сжимает света
vec3 tonemap(vec3 c) {
  float x = min(c.r, min(c.g, c.b));
  float off = x < 0.08 ? x - 6.25 * x * x : 0.04;
  c -= off;
  float peak = max(c.r, max(c.g, c.b));
  const float start = 0.76;
  if (peak < start) return c;
  const float d = 1.0 - start;
  float np = 1.0 - d * d / (peak + d - start);
  c *= np / peak;
  float g = 1.0 - 1.0 / (0.15 * (peak - np) + 1.0);
  return mix(c, vec3(np), g);
}

float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }

void main() {
  vec3 col = uGrade1.y > 0.5 ? fxaa(vUv) : texture(uScene, vUv).rgb;
  if (uGrade1.w > 0.5) col += texture(uBloom, vUv).rgb * uGrade0.y;
  if (uShaftsOn > 0.5) col += texture(uShafts, vUv).rgb;
  col *= uGrade0.x;
  col = tonemap(max(col, vec3(0.0)));
  // Гамма
  col = pow(clamp(col, 0.0, 1.0), vec3(1.0 / 2.2));
  // Насыщенность и мягкая S-кривая контраста
  float l = lumaOf(col);
  col = mix(vec3(l), col, uGrade0.z);
  col = clamp(col, 0.0, 1.0);
  col = mix(col, col * col * (3.0 - 2.0 * col), uGrade0.w);
  // Раздельное тонирование теней и светов
  float lw = smoothstep(0.0, 1.0, lumaOf(col));
  col += (uShadowTint - 0.5) * (1.0 - lw) * 0.35 + (uLightTint - 0.5) * lw * 0.3;
  // Виньетка
  vec2 q = vUv - 0.5;
  float v = 1.0 - dot(q, q) * uGrade1.x * 1.6;
  col *= clamp(v, 0.0, 1.0);
  // Дизеринг против полос в градиентах неба
  col += (ign(gl_FragCoord.xy + uGrade1.z * 17.0) - 0.5) / 255.0;
  outColor = vec4(col, 1.0);
}
`;

interface Level {
  tex: WebGLTexture;
  fbo: WebGLFramebuffer;
  w: number;
  h: number;
}

export class PostFX {
  /** Буфер сцены хранит HDR (иначе RGBA8 со срезанными светами). */
  readonly hdr: boolean;
  readonly maxSamples: number;
  private colorFormat: number;
  private progPrefilter: Program;
  private progDown: Program;
  private progUp: Program;
  private progComposite: Program;
  private progShafts: Program;
  private shafts: Level | null = null;
  /** Солнце на экране для лучей: x, y (0..1) и сила (0 — выкл.). */
  sun: [number, number, number] = [0.5, 0.5, 0];
  private vao: WebGLVertexArrayObject;
  // Буферы сцены
  private msaaFbo: WebGLFramebuffer | null = null;
  private msaaColor: WebGLRenderbuffer | null = null;
  private msaaDepth: WebGLRenderbuffer | null = null;
  private sceneFbo: WebGLFramebuffer | null = null;
  private sceneTex: WebGLTexture | null = null;
  private sceneDepth: WebGLRenderbuffer | null = null;
  private levels: Level[] = [];
  private w = 0;
  private h = 0;
  private samples = 0;
  private opts: PostOptions = { msaa: true, bloom: true, bloomLevels: 5, fxaa: false };
  grade: Grade = {
    exposure: 1,
    bloom: 0.08,
    saturation: 1.08,
    contrast: 0.18,
    vignette: 0.3,
    shadowTint: [0.46, 0.48, 0.56],
    lightTint: [0.54, 0.52, 0.47],
  };
  time = 0;

  constructor(readonly gl: GL) {
    const float = !!(gl.getExtension("EXT_color_buffer_float") || gl.getExtension("EXT_color_buffer_half_float"));
    gl.getExtension("OES_texture_float_linear");
    this.colorFormat = float ? gl.RGBA16F : gl.RGBA8;
    this.hdr = float && this.checkFormat(gl.RGBA16F);
    if (!this.hdr) this.colorFormat = gl.RGBA8;
    let max = gl.getParameter(gl.MAX_SAMPLES) as number;
    try {
      const s = gl.getInternalformatParameter(gl.RENDERBUFFER, this.colorFormat, gl.SAMPLES) as Int32Array | null;
      if (s && s.length) max = Math.min(max, Math.max(...Array.from(s)));
    } catch {
      /* старые драйверы */
    }
    this.maxSamples = max || 0;
    this.progPrefilter = new Program(gl, FULLSCREEN_VS, PREFILTER_FS, "bloom-prefilter");
    this.progDown = new Program(gl, FULLSCREEN_VS, DOWN_FS, "bloom-down");
    this.progUp = new Program(gl, FULLSCREEN_VS, UP_FS, "bloom-up");
    this.progComposite = new Program(gl, FULLSCREEN_VS, COMPOSITE_FS, "composite");
    this.progShafts = new Program(gl, FULLSCREEN_VS, SHAFTS_FS, "shafts");
    for (const p of [this.progPrefilter, this.progDown, this.progUp, this.progShafts]) {
      p.use();
      p.i1("uSrc", 0);
    }
    this.progComposite.use();
    this.progComposite.i1("uScene", 0);
    this.progComposite.i1("uBloom", 1);
    this.progComposite.i1("uShafts", 2);
    this.vao = gl.createVertexArray()!;
  }

  /** Можно ли рисовать в текстуру такого формата (некоторые мобильные драйверы врут про расширения). */
  private checkFormat(fmt: number): boolean {
    const gl = this.gl;
    const t = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texStorage2D(gl.TEXTURE_2D, 1, fmt, 4, 4);
    const f = gl.createFramebuffer()!;
    gl.bindFramebuffer(gl.FRAMEBUFFER, f);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, t, 0);
    const ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.deleteFramebuffer(f);
    gl.deleteTexture(t);
    return ok;
  }

  setOptions(o: PostOptions) {
    const msaaChanged = o.msaa !== this.opts.msaa;
    const levelsChanged = o.bloomLevels !== this.opts.bloomLevels || o.bloom !== this.opts.bloom;
    this.opts = { ...o };
    if (msaaChanged || levelsChanged) this.w = this.h = 0; // пересоздать при следующем кадре
  }

  get options(): PostOptions {
    return this.opts;
  }

  private makeTex(w: number, h: number, fmt: number): WebGLTexture {
    const gl = this.gl;
    const t = gl.createTexture()!;
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texStorage2D(gl.TEXTURE_2D, 1, fmt, w, h);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return t;
  }

  private release() {
    const gl = this.gl;
    if (this.msaaFbo) gl.deleteFramebuffer(this.msaaFbo);
    if (this.msaaColor) gl.deleteRenderbuffer(this.msaaColor);
    if (this.msaaDepth) gl.deleteRenderbuffer(this.msaaDepth);
    if (this.sceneFbo) gl.deleteFramebuffer(this.sceneFbo);
    if (this.sceneTex) gl.deleteTexture(this.sceneTex);
    if (this.sceneDepth) gl.deleteRenderbuffer(this.sceneDepth);
    for (const l of this.levels) {
      gl.deleteFramebuffer(l.fbo);
      gl.deleteTexture(l.tex);
    }
    this.levels = [];
    if (this.shafts) {
      gl.deleteFramebuffer(this.shafts.fbo);
      gl.deleteTexture(this.shafts.tex);
      this.shafts = null;
    }
    this.msaaFbo = this.msaaColor = this.msaaDepth = this.sceneFbo = this.sceneTex = this.sceneDepth = null;
  }

  private allocate(w: number, h: number) {
    const gl = this.gl;
    this.release();
    this.w = w;
    this.h = h;
    this.samples = this.opts.msaa ? Math.min(4, this.maxSamples) : 0;
    if (this.samples < 2) this.samples = 0;
    this.sceneTex = this.makeTex(w, h, this.colorFormat);
    this.sceneFbo = gl.createFramebuffer()!;
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.sceneFbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.sceneTex, 0);
    if (this.samples) {
      this.msaaColor = gl.createRenderbuffer()!;
      gl.bindRenderbuffer(gl.RENDERBUFFER, this.msaaColor);
      gl.renderbufferStorageMultisample(gl.RENDERBUFFER, this.samples, this.colorFormat, w, h);
      this.msaaDepth = gl.createRenderbuffer()!;
      gl.bindRenderbuffer(gl.RENDERBUFFER, this.msaaDepth);
      gl.renderbufferStorageMultisample(gl.RENDERBUFFER, this.samples, gl.DEPTH_COMPONENT24, w, h);
      this.msaaFbo = gl.createFramebuffer()!;
      gl.bindFramebuffer(gl.FRAMEBUFFER, this.msaaFbo);
      gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, this.msaaColor);
      gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, this.msaaDepth);
      if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE) {
        // MSAA не поддержан для этого формата — рисуем без него
        gl.deleteFramebuffer(this.msaaFbo);
        gl.deleteRenderbuffer(this.msaaColor);
        gl.deleteRenderbuffer(this.msaaDepth);
        this.msaaFbo = this.msaaColor = this.msaaDepth = null;
        this.samples = 0;
      }
    }
    if (!this.samples) {
      this.sceneDepth = gl.createRenderbuffer()!;
      gl.bindRenderbuffer(gl.RENDERBUFFER, this.sceneDepth);
      gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT24, w, h);
      gl.bindFramebuffer(gl.FRAMEBUFFER, this.sceneFbo);
      gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, this.sceneDepth);
    }
    if (this.opts.bloom) {
      let lw = w,
        lh = h;
      for (let i = 0; i < this.opts.bloomLevels; i++) {
        lw = Math.max(1, lw >> 1);
        lh = Math.max(1, lh >> 1);
        if (i > 0 && (lw < 4 || lh < 4)) break;
        const tex = this.makeTex(lw, lh, this.colorFormat);
        const fbo = gl.createFramebuffer()!;
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
        this.levels.push({ tex, fbo, w: lw, h: lh });
      }
      if (this.levels.length > 1) {
        const l1 = this.levels[1];
        const tex = this.makeTex(l1.w, l1.h, this.colorFormat);
        const fbo = gl.createFramebuffer()!;
        gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
        this.shafts = { tex, fbo, w: l1.w, h: l1.h };
      }
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.bindRenderbuffer(gl.RENDERBUFFER, null);
  }

  get msaaSamples(): number {
    return this.samples;
  }

  /** Начать кадр: привязать буфер сцены. */
  begin(w: number, h: number) {
    if (w !== this.w || h !== this.h) this.allocate(w, h);
    const gl = this.gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, this.samples ? this.msaaFbo : this.sceneFbo);
    gl.viewport(0, 0, w, h);
  }

  private fullscreen() {
    this.gl.drawArrays(this.gl.TRIANGLES, 0, 3);
  }

  /** Закончить кадр: разрешить MSAA, посчитать блум и вывести на экран. */
  end() {
    const gl = this.gl;
    const w = this.w,
      h = this.h;
    if (this.samples && this.msaaFbo) {
      gl.bindFramebuffer(gl.READ_FRAMEBUFFER, this.msaaFbo);
      gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, this.sceneFbo);
      gl.blitFramebuffer(0, 0, w, h, 0, 0, w, h, gl.COLOR_BUFFER_BIT, gl.NEAREST);
      gl.invalidateFramebuffer(gl.READ_FRAMEBUFFER, [gl.COLOR_ATTACHMENT0, gl.DEPTH_ATTACHMENT]);
      gl.bindFramebuffer(gl.READ_FRAMEBUFFER, null);
      gl.bindFramebuffer(gl.DRAW_FRAMEBUFFER, null);
    } else {
      gl.bindFramebuffer(gl.FRAMEBUFFER, this.sceneFbo);
      gl.invalidateFramebuffer(gl.FRAMEBUFFER, [gl.DEPTH_ATTACHMENT]);
    }
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.CULL_FACE);
    gl.disable(gl.BLEND);
    gl.depthMask(false);
    gl.bindVertexArray(this.vao);
    const L = this.levels;
    const g = this.grade;
    if (L.length) {
      // Порог: в HDR — выше белого, в LDR — почти белое
      this.progPrefilter.use();
      this.progPrefilter.f2("uTexel", 1 / w, 1 / h);
      this.progPrefilter.f2("uThreshold", this.hdr ? 1.05 : 0.82, this.hdr ? 0.55 : 0.2);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, this.sceneTex);
      gl.bindFramebuffer(gl.FRAMEBUFFER, L[0].fbo);
      gl.viewport(0, 0, L[0].w, L[0].h);
      this.fullscreen();
      this.progDown.use();
      for (let i = 1; i < L.length; i++) {
        gl.bindTexture(gl.TEXTURE_2D, L[i - 1].tex);
        this.progDown.f2("uTexel", 1 / L[i - 1].w, 1 / L[i - 1].h);
        gl.bindFramebuffer(gl.FRAMEBUFFER, L[i].fbo);
        gl.viewport(0, 0, L[i].w, L[i].h);
        this.fullscreen();
      }
      this.progUp.use();
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.ONE, gl.ONE);
      for (let i = L.length - 1; i > 0; i--) {
        gl.bindTexture(gl.TEXTURE_2D, L[i].tex);
        this.progUp.f2("uTexel", 1 / L[i].w, 1 / L[i].h);
        this.progUp.f1("uWeight", 0.85);
        gl.bindFramebuffer(gl.FRAMEBUFFER, L[i - 1].fbo);
        gl.viewport(0, 0, L[i - 1].w, L[i - 1].h);
        this.fullscreen();
      }
      gl.disable(gl.BLEND);
    }
    // Лучи: по второму уровню блума (там яркое небо у солнца и силуэты перед ним)
    const shaftsOn = !!this.shafts && this.sun[2] > 0.01 && L.length > 1;
    if (shaftsOn && this.shafts) {
      this.progShafts.use();
      this.progShafts.f3("uSun", this.sun[0], this.sun[1], this.sun[2]);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, L[1].tex);
      gl.bindFramebuffer(gl.FRAMEBUFFER, this.shafts.fbo);
      gl.viewport(0, 0, this.shafts.w, this.shafts.h);
      this.fullscreen();
    }
    // Итог на экран
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, w, h);
    const p = this.progComposite;
    p.use();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.sceneTex);
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, L.length ? L[0].tex : this.sceneTex);
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_2D, shaftsOn && this.shafts ? this.shafts.tex : this.sceneTex);
    gl.activeTexture(gl.TEXTURE0);
    p.f1("uShaftsOn", shaftsOn ? 1 : 0);
    p.f2("uTexel", 1 / w, 1 / h);
    p.f4("uGrade0", g.exposure, g.bloom, g.saturation, g.contrast);
    p.f4("uGrade1", g.vignette, this.opts.fxaa ? 1 : 0, this.time % 64, L.length ? 1 : 0);
    p.f3("uShadowTint", g.shadowTint[0], g.shadowTint[1], g.shadowTint[2]);
    p.f3("uLightTint", g.lightTint[0], g.lightTint[1], g.lightTint[2]);
    this.fullscreen();
    gl.bindVertexArray(null);
    gl.depthMask(true);
    gl.enable(gl.DEPTH_TEST);
  }

  dispose() {
    this.release();
  }
}
