import { createRoot } from "react-dom/client";
import { configure } from "mobx";
import { App } from "./ui/App";
import { Viewer } from "./ui/Viewer";

declare const __PROD__: boolean | undefined;
const IS_PROD = typeof __PROD__ !== "undefined" && __PROD__;

// Игровой цикл меняет состояние каждый кадр — строгий режим действий MobX тут только мешает
configure({ enforceActions: "never" });

// PWA: манифест и иконка для «Добавить на главный экран»
for (const [rel, href] of [
  ["manifest", "manifest.webmanifest"],
  ["apple-touch-icon", "icon-192.png"],
] as const) {
  const l = document.createElement("link");
  l.rel = rel;
  l.href = href;
  document.head.appendChild(l);
}
// Офлайн-кэш только в продакшене (в dev мешал бы горячей перезагрузке)
if (IS_PROD && "serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("sw.js").catch(() => undefined);
  });
}

const params = new URLSearchParams(location.search);
const root = createRoot(document.getElementById("root")!);
root.render(params.has("viewer") ? <Viewer /> : <App />);
