import { createContext, useContext } from "react";
import { makeAutoObservable } from "mobx";
import { SettingsStore } from "../stores/settings";
import { SaveStore } from "../stores/saves";
import { UiStore } from "../stores/ui";
import { HudState } from "../game/hud";
import type { CharacterStore } from "../game/character";
import type { GameSession, WorldOverride } from "../game/session";
import { CoopLink } from "../net/coop";

export class RootStore {
  settings = new SettingsStore();
  saves = new SaveStore();
  ui = new UiStore();
  hud = new HudState();
  coop = new CoopLink();
  char: CharacterStore | null = null;
  session: GameSession | null = null;
  /** Гость кооператива: мир хоста, в который входим. */
  worldOverride: WorldOverride | null = null;
  /** Кооператив, подготовленный в меню (гость), подключается при создании сессии. */
  pendingNet: CoopLink | null = null;
  /** Код приглашения из ссылки (#join=…). */
  joinCode: string | null = null;
  /** Вкладка открыта по ссылке-ответу (#answer=…): только передаём код хосту. */
  relayAnswer: string | null = null;
  /** Счётчик перезапусков игрового экрана (например, после потери WebGL-контекста). */
  sessionNonce = 0;

  constructor() {
    makeAutoObservable(this, { session: false, pendingNet: false, worldOverride: false });
  }

  setChar(c: CharacterStore | null) {
    this.char = c;
  }

  takePendingNet(): CoopLink | null {
    const p = this.pendingNet;
    this.pendingNet = null;
    return p;
  }

  /** Войти в игру персонажем (в своём мире или в мире хоста). */
  play(c: CharacterStore, override: WorldOverride | null = null, net: CoopLink | null = null) {
    this.worldOverride = override;
    this.pendingNet = net;
    this.hud = new HudState();
    this.char = c;
    this.ui.go("game");
  }

  /** Пересоздать игровую сессию (новый холст и контекст WebGL). Кооператив при этом завершается. */
  restartSession() {
    // Гость, потерявший связь, продолжает в своём собственном мире
    this.worldOverride = null;
    this.pendingNet = null;
    this.sessionNonce++;
  }

  quitToMenu() {
    if (this.coop.status !== "idle") this.coop.reset();
    this.ui.close();
    this.ui.go("menu");
    this.char = null;
    this.worldOverride = null;
    this.pendingNet = null;
    this.saves.refresh();
  }
}

export const StoreContext = createContext<RootStore>(null as unknown as RootStore);
export const useStore = () => useContext(StoreContext);
