/** Игровой экран: холст, игровая сессия, HUD, управление и панели. */
import { observer } from "mobx-react-lite";
import { useEffect, useRef, useState } from "react";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn } from "../common";
import { GameSession } from "../../game/session";
import { Hud } from "./Hud";
import { ActionCluster, DeadOverlay, InteractButton, LoadingOverlay, SkillBar, TouchLayer } from "./Controls";
import { InventoryPanel } from "../panels/Inventory";
import { SkillTreePanel } from "../panels/SkillTree";
import { QuestsPanel } from "../panels/Quests";
import { DialogPanel, TravelPanel } from "../panels/Dialog";
import { WorldMapPanel } from "../panels/WorldMap";
import { GameMenuPanel, HelpPanel, SettingsPanel } from "../panels/GameMenu";
import { CoopPanel } from "../panels/Coop";

/** Сенсорный режим: грубый указатель при старте + переключение по типу последнего касания/мыши. */
function useTouchMode(): boolean {
  const [touch, setTouch] = useState(() => {
    try {
      return matchMedia("(pointer: coarse)").matches || /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
    } catch {
      return false;
    }
  });
  useEffect(() => {
    const on = (e: PointerEvent) => {
      if (e.pointerType === "touch") setTouch(true);
      else if (e.pointerType === "mouse") setTouch(false);
    };
    window.addEventListener("pointerdown", on, true);
    return () => window.removeEventListener("pointerdown", on, true);
  }, []);
  return touch;
}

const Panels = observer(({ onQuit }: { onQuit: () => void }) => {
  const s = useStore();
  switch (s.ui.panel) {
    case "inventory":
      return <InventoryPanel key="inv" tab="inv" />;
    case "character":
      return <InventoryPanel key="stats" tab="stats" />;
    case "skills":
      return <SkillTreePanel />;
    case "quests":
      return <QuestsPanel />;
    case "map":
      return <WorldMapPanel />;
    case "dialog":
    case "shop":
      return <DialogPanel />;
    case "travel":
      return <TravelPanel />;
    case "menu":
      return <GameMenuPanel onQuit={onQuit} />;
    case "settings":
      return <SettingsPanel />;
    case "help":
      return <HelpPanel />;
    case "coop":
      return <CoopPanel />;
    default:
      return null;
  }
});

export const GameScreen = observer(() => {
  const s = useStore();
  const ref = useRef<HTMLCanvasElement>(null);
  const [ready, setReady] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lost, setLost] = useState(false);
  const touch = useTouchMode();

  useEffect(() => {
    const canvas = ref.current;
    const char = s.char;
    if (!canvas || !char) return;
    // Кооператив, подготовленный заранее (гость подключился из меню). Если связь уже
    // оборвалась, мир хоста без сети не имеет смысла — играем в своём мире.
    const pending = s.takePendingNet();
    const override = pending?.guest ? s.worldOverride : null;
    if (!override && s.worldOverride) {
      s.worldOverride = null;
      s.hud.toast({ ru: "Связь с хостом потеряна — вы в своём мире", en: "Lost connection to the host — you are in your own world" }, 0xffb454, "🔌");
    }
    let sess: GameSession;
    try {
      sess = new GameSession(canvas, char, s.hud, s.ui, s.settings, s.saves, override ?? undefined);
    } catch (e) {
      console.error(e);
      setError(e instanceof Error ? e.message : String(e));
      return;
    }
    s.session = sess;
    if (override && pending) pending.attach(sess);
    sess.start();
    setReady(true);
    const save = () => {
      if (document.visibilityState === "hidden") sess.saveNow();
    };
    const unload = () => sess.saveNow();
    // Потеря WebGL-контекста (свёрнутое приложение, нехватка памяти): сохраняемся и ждём восстановления
    const onLost = (e: Event) => {
      e.preventDefault();
      sess.saveNow();
      sess.pause();
      setLost(true);
    };
    const onRestored = () => {
      try {
        sess.rebuildGpu();
        sess.resume();
        setLost(false);
      } catch (err) {
        console.error(err);
        s.restartSession();
      }
    };
    canvas.addEventListener("webglcontextlost", onLost);
    canvas.addEventListener("webglcontextrestored", onRestored);
    document.addEventListener("visibilitychange", save);
    window.addEventListener("pagehide", unload);
    return () => {
      canvas.removeEventListener("webglcontextlost", onLost);
      canvas.removeEventListener("webglcontextrestored", onRestored);
      document.removeEventListener("visibilitychange", save);
      window.removeEventListener("pagehide", unload);
      sess.stop();
      if (s.session === sess) s.session = null;
      setReady(false);
    };
  }, [s, s.char]);

  const quit = () => {
    s.ui.ask({
      text: { ru: "Выйти в главное меню? Прогресс будет сохранён.", en: "Quit to the main menu? Progress will be saved." },
      okLabel: { ru: "Выйти", en: "Quit" },
      ok: () => s.quitToMenu(),
    });
  };

  if (error) {
    return (
      <div className="menu-screen">
        <div className="menu-card" style={{ maxWidth: 520 }}>
          <h2>😿 {tr({ ru: "Не удалось запустить игру", en: "Could not start the game" })}</h2>
          <div className="muted" style={{ marginBottom: 12 }}>
            {error}
            <br />
            {tr({ ru: "Нужен браузер с поддержкой WebGL 2.", en: "A browser with WebGL 2 support is required." })}
          </div>
          <Btn onClick={() => s.quitToMenu()}>← {tr({ ru: "В меню", en: "Menu" })}</Btn>
        </div>
      </div>
    );
  }

  return (
    <>
      <canvas ref={ref} className="game" />
      {ready && (
        <>
          {touch && <TouchLayer />}
          <Hud />
          {touch ? <ActionCluster /> : <SkillBar />}
          <InteractButton />
          <DeadOverlay />
          <Panels onQuit={quit} />
        </>
      )}
      <LoadingOverlay />
      {lost && (
        <div className="loading">
          <div>
            <div className="paw">🐾</div>
            <div style={{ fontWeight: 900, fontSize: 18, margin: "8px 0 12px" }}>{tr({ ru: "Восстанавливаем графику…", en: "Restoring graphics…" })}</div>
            <Btn kind="primary" onClick={() => s.restartSession()}>
              ↻ {tr({ ru: "Перезапустить", en: "Restart" })}
            </Btn>
          </div>
        </div>
      )}
    </>
  );
});
