/** Рендер ландшафта: чанки с LOD, юбки против щелей, генерация с бюджетом времени. */
import { hexToRgb, smoothstep, lerp, clamp01 } from "../core/math";
import { noise2 } from "../core/noise";
import { BIOMES, BIOME_IDS, type BiomeId, PROP_COLLIDER } from "../game/world/biomes";
import { CHUNK, type TerrainSample } from "../game/world/worldgen";
import { GRID, type TerrainCache } from "../game/world/terrain-cache";
import type { Camera } from "./camera";
import { ATTR, type GL, type Program, setupAttribs, staticBuffer, VERTEX_STRIDE } from "./gl";
import { MAT, MAT_COUNT } from "./materials";

/** Материал земли, берега и склонов по биому. */
const GROUND_MAT: Record<BiomeId, number> = {
  meadow: MAT.grass,
  forest: MAT.litter,
  birch: MAT.grass,
  sakura: MAT.grass,
  autumn: MAT.litter,
  jungle: MAT.moss,
  savanna: MAT.grass,
  desert: MAT.sand,
  swamp: MAT.moss,
  taiga: MAT.litter,
  snow: MAT.snow,
  mountain: MAT.grass,
  beach: MAT.sand,
  volcanic: MAT.ash,
  crystal: MAT.crystal,
  shadow: MAT.ash,
  void: MAT.ash,
  candy: MAT.candy,
};
const SHORE_MAT: Partial<Record<BiomeId, number>> = { swamp: MAT.moss, volcanic: MAT.ash, shadow: MAT.ash, void: MAT.ash, snow: MAT.snow, candy: MAT.candy };
const SLOPE_MAT: Partial<Record<BiomeId, number>> = { candy: MAT.candy, volcanic: MAT.ash, desert: MAT.dryEarth, savanna: MAT.dryEarth };

interface BiomeColors {
  ground: number[];
  groundAlt: number[];
  slope: number[];
  shore: number[];
}
const BCOL: Record<string, BiomeColors> = {};
for (const id of BIOME_IDS) {
  const b = BIOMES[id];
  BCOL[id] = { ground: hexToRgb(b.ground), groundAlt: hexToRgb(b.groundAlt), slope: hexToRgb(b.slope), shore: hexToRgb(b.shore) };
}
const ROAD = hexToRgb(0x9c7b52);
const ROAD_SNOW = hexToRgb(0xb3aba3);
const PLAZA = hexToRgb(0xb8a88c);
const PLAZA2 = hexToRgb(0xa39478);
const DIRT = hexToRgb(0x8a7456);
const SNOW = hexToRgb(0xf4f8fc);
const ASH = hexToRgb(0x3a3432);

const LOD_CELLS = [32, 16, 8, 4];

interface TerrainChunk {
  cx: number;
  cz: number;
  lod: number;
  vao: WebGLVertexArrayObject;
  vbo: WebGLBuffer;
  minY: number;
  maxY: number;
  /** Палитра материалов чанка и материал склонов. */
  mats: [number, number, number, number];
  slope: number;
}

const ckey = (cx: number, cz: number) => (cx + 1048576) * 2097152 + (cz + 1048576);

export class TerrainRenderer {
  private chunks = new Map<number, TerrainChunk>();
  private ibos: { buffer: WebGLBuffer; count: number }[] = [];
  viewRadius = 10;
  detail = true;
  /** Сколько чанков ещё ждут построения (для экрана загрузки). */
  pending = 0;
  private sample: TerrainSample = { h: 0, biomeA: "meadow", biomeB: "meadow", w: 0, road: 0, town: 0, poi: 0, plaza: 0 };
  private mw = new Float32Array(MAT_COUNT);
  private visible: TerrainChunk[] = [];

  constructor(
    readonly gl: GL,
    readonly cache: TerrainCache,
  ) {
    for (let lod = 0; lod < LOD_CELLS.length; lod++) this.ibos.push(this.buildIndices(LOD_CELLS[lod]));
  }

  private buildIndices(cells: number) {
    const N = cells + 1;
    const idx: number[] = [];
    for (let j = 0; j < cells; j++)
      for (let i = 0; i < cells; i++) {
        const a = j * N + i;
        const b = a + 1;
        const c = a + N;
        const d = c + 1;
        if ((i + j) % 2 === 0) idx.push(a, c, b, b, c, d);
        else idx.push(a, c, d, a, d, b);
      }
    const base = N * N;
    const edge = (e: number, k: number) => {
      // индекс вершины сетки на ребре e в позиции k
      switch (e) {
        case 0:
          return k; // j=0
        case 1:
          return (N - 1) * N + k; // j=N-1
        case 2:
          return k * N; // i=0
        default:
          return k * N + N - 1; // i=N-1
      }
    };
    for (let e = 0; e < 4; e++) {
      for (let k = 0; k < N - 1; k++) {
        const g0 = edge(e, k),
          g1 = edge(e, k + 1);
        const s0 = base + e * N + k,
          s1 = s0 + 1;
        idx.push(g0, g1, s1, g0, s1, s0);
      }
    }
    const gl = this.gl;
    const buffer = staticBuffer(gl, gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx));
    return { buffer, count: idx.length };
  }

  private lodFor(dist: number): number {
    if (dist <= 2) return 0;
    if (dist <= 5) return 1;
    if (dist <= 9) return 2;
    return 3;
  }

  /** Обновить набор чанков вокруг камеры. Возвращает число построенных за кадр. */
  update(cam: Camera, budgetMs: number): number {
    const ccx = Math.floor(cam.tx / CHUNK);
    const ccz = Math.floor(cam.tz / CHUNK);
    const R = this.viewRadius;
    const todo: { cx: number; cz: number; lod: number; d: number }[] = [];
    for (let dz = -R; dz <= R; dz++) {
      for (let dx = -R; dx <= R; dx++) {
        if (dx * dx + dz * dz > (R + 0.5) * (R + 0.5)) continue;
        const d = Math.max(Math.abs(dx), Math.abs(dz));
        const lod = this.lodFor(d);
        const c = this.chunks.get(ckey(ccx + dx, ccz + dz));
        if (!c || c.lod !== lod) todo.push({ cx: ccx + dx, cz: ccz + dz, lod, d: dx * dx + dz * dz + (c ? 4 : 0) });
      }
    }
    todo.sort((a, b) => a.d - b.d);
    this.pending = todo.length;
    const t0 = performance.now();
    let built = 0;
    for (const t of todo) {
      if (built > 0 && performance.now() - t0 > budgetMs) break;
      this.buildChunk(t.cx, t.cz, t.lod);
      built++;
      this.pending--;
    }
    // Удаляем далёкие чанки
    const RR = (R + 2) * (R + 2);
    for (const [k, c] of this.chunks) {
      const dx = c.cx - ccx,
        dz = c.cz - ccz;
      if (dx * dx + dz * dz > RR) {
        this.disposeChunk(c);
        this.chunks.delete(k);
      }
    }
    return built;
  }

  private disposeChunk(c: TerrainChunk) {
    this.gl.deleteVertexArray(c.vao);
    this.gl.deleteBuffer(c.vbo);
  }

  clear() {
    for (const c of this.chunks.values()) this.disposeChunk(c);
    this.chunks.clear();
  }

  private buildChunk(cx: number, cz: number, lod: number) {
    const gl = this.gl;
    const cells = LOD_CELLS[lod];
    const N = cells + 1;
    const step = CHUNK / cells;
    const x0 = cx * CHUNK;
    const z0 = cz * CHUNK;
    const gen = this.cache.gen;
    // Высоты с каймой в 1 отсчёт для нормалей
    const M = N + 2;
    const hb = new Float32Array(M * M);
    const vb: number[] = new Array(N * N * 3); // biome a index, b index, w
    const extra = new Float32Array(N * N * 4); // road, town, poi, plaza
    const biomeIdx = (b: BiomeId) => BIOME_IDS.indexOf(b);
    let samples = lod === 0 ? this.cache.chunkSamples(cx, cz) : null;
    const s = this.sample;
    for (let j = -1; j <= N; j++) {
      for (let i = -1; i <= N; i++) {
        const inner = i >= 0 && j >= 0 && i < N && j < N;
        const x = x0 + i * step;
        const z = z0 + j * step;
        let h: number;
        if (inner) {
          const vi = j * N + i;
          if (samples) {
            const si = j * step * GRID + i * step;
            h = samples.h[si];
            vb[vi * 3] = biomeIdx(samples.biomeA[si]);
            vb[vi * 3 + 1] = biomeIdx(samples.biomeB[si]);
            vb[vi * 3 + 2] = samples.w[si];
            extra[vi * 4] = samples.road[si];
            extra[vi * 4 + 1] = samples.town[si];
            extra[vi * 4 + 2] = samples.poi[si];
            extra[vi * 4 + 3] = samples.plaza[si];
          } else {
            gen.sample(x, z, s);
            h = s.h;
            vb[vi * 3] = biomeIdx(s.biomeA);
            vb[vi * 3 + 1] = biomeIdx(s.biomeB);
            vb[vi * 3 + 2] = s.w;
            extra[vi * 4] = s.road;
            extra[vi * 4 + 1] = s.town;
            extra[vi * 4 + 2] = s.poi;
            extra[vi * 4 + 3] = s.plaza;
          }
        } else {
          h = gen.height(x, z);
        }
        hb[(j + 1) * M + (i + 1)] = h;
      }
    }
    // AO от деревьев и камней (только для ближних LOD)
    const ao = new Float32Array(N * N).fill(1);
    if (lod <= 1) {
      const content = this.cache.content(cx, cz);
      for (const p of content.props) {
        const cr = PROP_COLLIDER[p.kind];
        if (cr <= 0) continue;
        const rad = 1.2 + cr * p.scale * 2.2;
        const li = (p.x - x0) / step,
          lj = (p.z - z0) / step;
        const ri = Math.ceil(rad / step);
        for (let j = Math.max(0, Math.floor(lj - ri)); j <= Math.min(N - 1, Math.ceil(lj + ri)); j++)
          for (let i = Math.max(0, Math.floor(li - ri)); i <= Math.min(N - 1, Math.ceil(li + ri)); i++) {
            const dx = x0 + i * step - p.x,
              dz = z0 + j * step - p.z;
            const d = Math.sqrt(dx * dx + dz * dz);
            if (d < rad) ao[j * N + i] *= 0.55 + 0.45 * smoothstep(0, rad, d);
          }
      }
      for (const b of content.buildings) {
        const rad = b.collider * b.scale * 1.6 + 1;
        if (rad < 1.5) continue;
        const li = (b.x - x0) / step,
          lj = (b.z - z0) / step;
        const ri = Math.ceil(rad / step);
        for (let j = Math.max(0, Math.floor(lj - ri)); j <= Math.min(N - 1, Math.ceil(lj + ri)); j++)
          for (let i = Math.max(0, Math.floor(li - ri)); i <= Math.min(N - 1, Math.ceil(li + ri)); i++) {
            const dx = x0 + i * step - b.x,
              dz = z0 + j * step - b.z;
            const d = Math.sqrt(dx * dx + dz * dz);
            if (d < rad) ao[j * N + i] *= 0.6 + 0.4 * smoothstep(rad * 0.5, rad, d);
          }
      }
    }

    const vcount = N * N + 4 * N;
    const buf = new ArrayBuffer(vcount * VERTEX_STRIDE);
    const f = new Float32Array(buf);
    const i8 = new Int8Array(buf);
    const u8 = new Uint8Array(buf);
    let minY = Infinity,
      maxY = -Infinity;
    const col = [0, 0, 0];
    const writeVertex = (vi: number, lx: number, y: number, lz: number, nx: number, ny: number, nz: number, r: number, g: number, b: number, a: number) => {
      const o = vi * VERTEX_STRIDE;
      f[o / 4] = lx;
      f[o / 4 + 1] = y;
      f[o / 4 + 2] = lz;
      i8[o + 12] = Math.round(nx * 127);
      i8[o + 13] = Math.round(ny * 127);
      i8[o + 14] = Math.round(nz * 127);
      i8[o + 15] = 0;
      u8[o + 16] = Math.round(clamp01(r) * 255);
      u8[o + 17] = Math.round(clamp01(g) * 255);
      u8[o + 18] = Math.round(clamp01(b) * 255);
      u8[o + 19] = 255;
      u8[o + 20] = Math.round(clamp01(a) * 255);
      u8[o + 21] = 0;
      u8[o + 22] = 0;
      u8[o + 23] = 0;
    };
    const normals = new Float32Array(N * N * 3);
    const mw = this.mw;
    const vmw = new Float32Array(N * N * MAT_COUNT);
    const total = new Float32Array(MAT_COUNT);
    for (let j = 0; j < N; j++) {
      for (let i = 0; i < N; i++) {
        const vi = j * N + i;
        const h = hb[(j + 1) * M + (i + 1)];
        const hl = hb[(j + 1) * M + i],
          hr = hb[(j + 1) * M + i + 2];
        const hd = hb[j * M + i + 1],
          hu = hb[(j + 2) * M + i + 1];
        let nx = hl - hr,
          ny = 2 * step,
          nz = hd - hu;
        const l = Math.hypot(nx, ny, nz);
        nx /= l;
        ny /= l;
        nz /= l;
        normals[vi * 3] = nx;
        normals[vi * 3 + 1] = ny;
        normals[vi * 3 + 2] = nz;
        const x = x0 + i * step,
          z = z0 + j * step;
        this.terrainColor(
          BIOME_IDS[vb[vi * 3]],
          BIOME_IDS[vb[vi * 3 + 1]],
          vb[vi * 3 + 2],
          h,
          ny,
          x,
          z,
          extra[vi * 4],
          extra[vi * 4 + 1],
          extra[vi * 4 + 2],
          extra[vi * 4 + 3],
          col,
          mw,
        );
        for (let m = 0; m < MAT_COUNT; m++) {
          vmw[vi * MAT_COUNT + m] = mw[m];
          total[m] += mw[m];
        }
        writeVertex(vi, i * step, h, j * step, nx, ny, nz, col[0], col[1], col[2], ao[vi]);
        if (h < minY) minY = h;
        if (h > maxY) maxY = h;
      }
    }
    // Палитра чанка: четыре самых весомых материала
    const order = Array.from({ length: MAT_COUNT }, (_, m) => m).sort((a, b) => total[b] - total[a]);
    const mats: [number, number, number, number] = [order[0], order[1], order[2], order[3]];
    for (let k = 1; k < 4; k++) if (total[mats[k]] <= 0) mats[k] = mats[0];
    for (let vi = 0; vi < N * N; vi++) {
      const o = vi * VERTEX_STRIDE;
      let w0 = total[mats[0]] > 0 ? vmw[vi * MAT_COUNT + mats[0]] : 0;
      const w1 = mats[1] !== mats[0] ? vmw[vi * MAT_COUNT + mats[1]] : 0;
      const w2 = mats[2] !== mats[0] ? vmw[vi * MAT_COUNT + mats[2]] : 0;
      const w3 = mats[3] !== mats[0] ? vmw[vi * MAT_COUNT + mats[3]] : 0;
      let sum = w0 + w1 + w2 + w3;
      if (sum < 1e-3) {
        w0 = 1;
        sum = 1;
      }
      u8[o + 19] = Math.round((w0 / sum) * 255);
      u8[o + 22] = Math.round((w1 / sum) * 255);
      u8[o + 23] = Math.round((w2 / sum) * 255);
      i8[o + 15] = Math.round((w3 / sum) * 127);
    }
    // Склоны: по биому центра чанка
    const cb = BIOME_IDS[vb[(Math.floor(N / 2) * N + Math.floor(N / 2)) * 3]];
    const slope = SLOPE_MAT[cb] ?? MAT.rock;
    // Юбки
    const skirt = 1.5 + step * 1.2;
    const edgeIdx = (e: number, k: number) => (e === 0 ? k : e === 1 ? (N - 1) * N + k : e === 2 ? k * N : k * N + N - 1);
    for (let e = 0; e < 4; e++) {
      for (let k = 0; k < N; k++) {
        const gi = edgeIdx(e, k);
        const o = gi * VERTEX_STRIDE;
        const vi = N * N + e * N + k;
        const oo = vi * VERTEX_STRIDE;
        u8.copyWithin(oo, o, o + VERTEX_STRIDE);
        f[oo / 4 + 1] = f[o / 4 + 1] - skirt;
      }
    }
    minY -= skirt;

    const vao = gl.createVertexArray()!;
    gl.bindVertexArray(vao);
    const vbo = staticBuffer(gl, gl.ARRAY_BUFFER, u8);
    setupAttribs(gl, vbo, [
      { loc: ATTR.pos, size: 3, type: gl.FLOAT, stride: VERTEX_STRIDE, offset: 0 },
      { loc: ATTR.normal, size: 4, type: gl.BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 12 },
      { loc: ATTR.color, size: 4, type: gl.UNSIGNED_BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 16 },
      { loc: ATTR.misc, size: 4, type: gl.UNSIGNED_BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 20 },
    ]);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.ibos[lod].buffer);
    gl.bindVertexArray(null);

    const k = ckey(cx, cz);
    const old = this.chunks.get(k);
    if (old) this.disposeChunk(old);
    this.chunks.set(k, { cx, cz, lod, vao, vbo, minY, maxY, mats, slope });
  }

  private terrainColor(
    ba: BiomeId,
    bb: BiomeId,
    w: number,
    h: number,
    ny: number,
    x: number,
    z: number,
    road: number,
    town: number,
    poi: number,
    plaza: number,
    out: number[],
    mw: Float32Array,
  ) {
    const A = BCOL[ba],
      B = BCOL[bb];
    // Доли материалов идут тем же порядком, что и цвет: земля → шапки → берег → дорога → площадь
    mw.fill(0);
    mw[GROUND_MAT[ba]] += 1 - w;
    mw[GROUND_MAT[bb]] += w;
    const over = (m: number, k: number) => {
      if (k <= 0) return;
      for (let i = 0; i < MAT_COUNT; i++) mw[i] *= 1 - k;
      mw[m] += k;
    };
    const n = noise2(x / 23, z / 23, 991) * 0.5 + 0.5;
    const n2 = noise2(x / 7, z / 7, 313) * 0.5 + 0.5;
    const t = clamp01(n * 1.2 - 0.1);
    let r = lerp(lerp(A.ground[0], A.groundAlt[0], t), lerp(B.ground[0], B.groundAlt[0], t), w);
    let g = lerp(lerp(A.ground[1], A.groundAlt[1], t), lerp(B.ground[1], B.groundAlt[1], t), w);
    let b = lerp(lerp(A.ground[2], A.groundAlt[2], t), lerp(B.ground[2], B.groundAlt[2], t), w);
    const v = 0.94 + n2 * 0.12;
    r *= v;
    g *= v;
    b *= v;
    // Склоны
    const steep = smoothstep(0.86, 0.62, ny);
    if (steep > 0) {
      r = lerp(r, lerp(A.slope[0], B.slope[0], w), steep);
      g = lerp(g, lerp(A.slope[1], B.slope[1], w), steep);
      b = lerp(b, lerp(A.slope[2], B.slope[2], w), steep);
    }
    // Снежные шапки
    const volcanic = ba === "volcanic" || bb === "volcanic" || ba === "void";
    const cap = smoothstep(46, 62, h + n * 6);
    if (cap > 0) {
      over(volcanic ? MAT.ash : MAT.snow, cap * (1 - steep * 0.5));
      const c = volcanic ? ASH : SNOW;
      r = lerp(r, c[0], cap * (1 - steep * 0.5));
      g = lerp(g, c[1], cap * (1 - steep * 0.5));
      b = lerp(b, c[2], cap * (1 - steep * 0.5));
    }
    // Берег и дно
    const shore = smoothstep(1.7, 0.3, h + n2 * 0.6);
    if (shore > 0) {
      over(SHORE_MAT[w < 0.5 ? ba : bb] ?? MAT.sand, shore);
      r = lerp(r, lerp(A.shore[0], B.shore[0], w), shore);
      g = lerp(g, lerp(A.shore[1], B.shore[1], w), shore);
      b = lerp(b, lerp(A.shore[2], B.shore[2], w), shore);
    }
    if (h < 0) {
      const d = smoothstep(0, -6, h);
      r *= 1 - d * 0.45;
      g *= 1 - d * 0.35;
      b *= 1 - d * 0.25;
    }
    // Дорога
    if (road > 0) {
      const cold = ba === "snow" || ba === "taiga";
      const rc = cold ? ROAD_SNOW : ROAD;
      const k = road * (0.8 + 0.2 * n2);
      over(cold ? MAT.snow : MAT.dirt, k);
      r = lerp(r, rc[0], k);
      g = lerp(g, rc[1], k);
      b = lerp(b, rc[2], k);
    }
    // Город: утоптанная трава и мощёная площадь в центре
    if (town > 0) {
      const k = smoothstep(0.3, 1, town) * 0.22;
      over(MAT.dirt, k * 0.8);
      r = lerp(r, DIRT[0], k);
      g = lerp(g, DIRT[1], k);
      b = lerp(b, DIRT[2], k);
    }
    if (plaza > 0) {
      over(MAT.cobble, smoothstep(0, 0.6, plaza));
      const cob = n2 > 0.5 ? PLAZA : PLAZA2;
      r = lerp(r, cob[0], plaza);
      g = lerp(g, cob[1], plaza);
      b = lerp(b, cob[2], plaza);
    }
    if (poi > 0) {
      const k = smoothstep(0.2, 0.9, poi) * 0.75;
      over(MAT.dirt, k);
      r = lerp(r, DIRT[0], k);
      g = lerp(g, DIRT[1], k);
      b = lerp(b, DIRT[2], k);
    }
    out[0] = r;
    out[1] = g;
    out[2] = b;
  }

  draw(cam: Camera, prog: Program) {
    const gl = this.gl;
    prog.use();
    prog.f1("uDetail", this.detail ? 1 : 0);
    const vis = this.visible;
    vis.length = 0;
    for (const c of this.chunks.values()) {
      const x0 = c.cx * CHUNK - cam.ox;
      const z0 = c.cz * CHUNK - cam.oz;
      if (!cam.boxVisible(x0, c.minY, z0, x0 + CHUNK, c.maxY, z0 + CHUNK)) continue;
      vis.push(c);
    }
    const tx = cam.tx,
      tz = cam.tz;
    vis.sort((a, b) => {
      const da = (a.cx * CHUNK + 16 - tx) ** 2 + (a.cz * CHUNK + 16 - tz) ** 2;
      const db = (b.cx * CHUNK + 16 - tx) ** 2 + (b.cz * CHUNK + 16 - tz) ** 2;
      return da - db;
    });
    const loc = prog.loc("uOffset");
    const locM = prog.loc("uMats");
    const locS = prog.loc("uSlopeMat");
    for (const c of vis) {
      gl.uniform3f(loc, c.cx * CHUNK - cam.ox, 0, c.cz * CHUNK - cam.oz);
      gl.uniform4f(locM, c.mats[0], c.mats[1], c.mats[2], c.mats[3]);
      gl.uniform1f(locS, c.slope);
      gl.bindVertexArray(c.vao);
      gl.drawElements(gl.TRIANGLES, this.ibos[c.lod].count, gl.UNSIGNED_SHORT, 0);
    }
    gl.bindVertexArray(null);
    return vis.length;
  }

  /** Чанки в квадрате карты теней (мировые координаты центра и радиус). */
  drawShadow(cam: Camera, prog: Program, sx: number, sz: number, sr: number) {
    const gl = this.gl;
    prog.use();
    const loc = prog.loc("uOffset");
    for (const c of this.chunks.values()) {
      const x0 = c.cx * CHUNK,
        z0 = c.cz * CHUNK;
      if (x0 > sx + sr || x0 + CHUNK < sx - sr || z0 > sz + sr || z0 + CHUNK < sz - sr) continue;
      gl.uniform3f(loc, x0 - cam.ox, 0, z0 - cam.oz);
      gl.bindVertexArray(c.vao);
      gl.drawElements(gl.TRIANGLES, this.ibos[c.lod].count, gl.UNSIGNED_SHORT, 0);
    }
    gl.bindVertexArray(null);
  }

  get chunkCount() {
    return this.chunks.size;
  }
}
