/**
 * Трава: пучки по три изогнутые травинки вокруг камеры. Инстансы строятся по сетке высот чанка
 * (там, где биом травянистый, нет дорог, площадей, воды и построек), перемешиваются — поэтому
 * для дальних чанков достаточно нарисовать первые N. Ветер гнёт травинки, игрок их приминает,
 * у границы радиуса они плавно уходят в землю.
 */
import { clamp01, hexToRgb, lerp } from "../core/math";
import { noise2 } from "../core/noise";
import { BIOMES, type BiomeId, PROP_COLLIDER } from "../game/world/biomes";
import { CHUNK } from "../game/world/worldgen";
import { GRID, type TerrainCache } from "../game/world/terrain-cache";
import type { Camera } from "./camera";
import { ATTR, type GL, Program, setupAttribs, staticBuffer } from "./gl";
import { FRAME_GLSL, HEADER, LIGHTING_GLSL, SKY_GLSL, UTIL_GLSL } from "./shaders/common";

/** Густота (пучков на м² при полном качестве) и высота травы по биомам. */
const GRASS: Partial<Record<BiomeId, [number, number]>> = {
  meadow: [1.0, 0.75],
  forest: [0.55, 0.7],
  birch: [0.9, 0.7],
  sakura: [0.85, 0.65],
  autumn: [0.6, 0.7],
  jungle: [1.0, 1.15],
  savanna: [0.85, 1.05],
  swamp: [0.7, 0.95],
  taiga: [0.4, 0.55],
  mountain: [0.5, 0.5],
  beach: [0.12, 0.8],
  shadow: [0.35, 0.6],
};

const INST = 8;

const GRASS_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
layout(location=0) in vec4 aBlade;   // xyz — вершина пучка высотой 1, w — доля высоты t
layout(location=1) in vec4 aFacing;  // xz — куда смотрит травинка
layout(location=4) in vec4 iPos;     // xyz в чанке, w — поворот
layout(location=5) in vec4 iCol;     // x — высота, yzw — цвет
uniform vec3 uOffset;
uniform vec2 uFade;                  // x — радиус, где трава исчезает, y — ширина перехода
out vec3 vWorld;
out vec3 vColor;
out vec3 vNormal;
out float vT;
void main() {
  vec3 base = iPos.xyz + uOffset;
  float dcam = length(base.xz - uCamPos.xz);
  float fade = clamp((uFade.x - dcam) / uFade.y, 0.0, 1.0);
  float hgt = iCol.x * fade;
  float c = cos(iPos.w), s = sin(iPos.w);
  vec3 p = aBlade.xyz;
  p = vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
  float t = aBlade.w;
  vec3 wp = base + vec3(p.x * (0.6 + 0.4 * iCol.x), p.y * hgt, p.z * (0.6 + 0.4 * iCol.x));
  // Ветер: волны по полю + дрожь травинок
  float time = uCamPos.w;
  vec2 wd = normalize(uWind.xy + 1e-4);
  vec2 wpos = base.xz + uOriginMod.xy;
  float wave = sin(dot(wpos, wd) * 0.35 - time * 1.9) * 0.5 + 0.5;
  float gust = vnoise(wpos * 0.08 - wd * time * 0.6);
  float bend = (0.12 + 0.35 * wave * gust * (0.6 + uWind.z)) * t * t * hgt;
  wp.xz += wd * bend + vec2(sin(time * 3.1 + wpos.x * 1.7), cos(time * 2.7 + wpos.y * 1.9)) * 0.03 * t * hgt;
  // Игрок приминает траву
  if (uFocus.w > 0.0) {
    vec2 d = base.xz - uFocus.xz;
    float dist = length(d);
    float k = (1.0 - smoothstep(0.3, 1.4, dist)) * step(abs(base.y - uFocus.y), 2.0);
    wp.xz += normalize(d + 1e-4) * k * 0.55 * t * hgt;
    wp.y -= k * 0.45 * t * hgt;
  }
  vec3 fn = vec3(c * aFacing.x + s * aFacing.z, 0.0, -s * aFacing.x + c * aFacing.z);
  vNormal = normalize(mix(fn, vec3(0.0, 1.0, 0.0), 0.65));
  vWorld = wp;
  vColor = toLinear(iCol.yzw);
  vT = t;
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

const GRASS_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
${LIGHTING_GLSL}
in vec3 vWorld;
in vec3 vColor;
in vec3 vNormal;
in float vT;
out vec4 outColor;
void main() {
  vec3 N = normalize(vNormal);
  vec3 V = normalize(uCamPos.xyz - vWorld);
  // У корня темнее (тень соседних травинок), к кончику светлее и желтее
  vec3 albedo = vColor * mix(0.55, 1.2, vT);
  albedo = mix(albedo, albedo * vec3(1.12, 1.08, 0.78), vT * vT * 0.5);
  float shadow = sunShadow(vWorld, vec3(0.0, 1.0, 0.0));
  vec3 col = shadeFull(albedo, N, V, vWorld, 0.0, mix(0.45, 1.0, vT), 0.25 * vT, 20.0, shadow);
  // Просвечивание против солнца
  float back = pow(max(dot(-V, uSunDir.xyz), 0.0), 3.0);
  col += albedo * uSunColor.rgb * uSunDir.w * back * vT * shadow * 0.9;
  col = fog(col, vWorld);
  outColor = vec4(col, 1.0);
}
`;

interface GrassChunk {
  cx: number;
  cz: number;
  vao: WebGLVertexArrayObject;
  buf: WebGLBuffer;
  count: number;
  minY: number;
  maxY: number;
}

const ckey = (cx: number, cz: number) => (cx + 1048576) * 2097152 + (cz + 1048576);

/** Хеш для раскладки травы (детерминированно по координатам). */
function h2(x: number, z: number, s: number) {
  let h = (x * 374761393 + z * 668265263 + s * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

export class GrassRenderer {
  readonly prog: Program;
  private chunks = new Map<number, GrassChunk>();
  private bladeVbo: WebGLBuffer;
  private bladeIbo: WebGLBuffer;
  private bladeCount: number;
  /** Радиус в чанках и густота (0..1). */
  radius = 1;
  density = 0.7;
  drawn = 0;

  constructor(
    readonly gl: GL,
    readonly cache: TerrainCache,
  ) {
    this.prog = new Program(gl, GRASS_VS, GRASS_FS, "grass");
    // Пучок из трёх травинок: у каждой 5 вершин (3 треугольника), слегка отклонены наружу
    const v: number[] = [];
    const idx: number[] = [];
    for (let i = 0; i < 3; i++) {
      const a = i * 2.1 + 0.3;
      const ca = Math.cos(a),
        sa = Math.sin(a);
      const lean = 0.16 + i * 0.06;
      const w = 0.07;
      const base = v.length / 8;
      const pt = (side: number, t: number) => {
        const width = w * (1 - t * 0.8) * side;
        const x = -sa * width + ca * lean * t * t + ca * 0.05;
        const z = ca * width + sa * lean * t * t + sa * 0.05;
        v.push(x, t, z, t, ca, 0, sa, 0);
      };
      pt(-1, 0);
      pt(1, 0);
      pt(-1, 0.5);
      pt(1, 0.5);
      pt(0, 1);
      idx.push(base, base + 1, base + 2, base + 2, base + 1, base + 3, base + 2, base + 3, base + 4);
    }
    this.bladeCount = idx.length;
    this.bladeVbo = staticBuffer(gl, gl.ARRAY_BUFFER, new Float32Array(v));
    this.bladeIbo = staticBuffer(gl, gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx));
  }

  private build(cx: number, cz: number): GrassChunk | null {
    const gl = this.gl;
    const s = this.cache.chunkSamples(cx, cz);
    const content = this.cache.content(cx, cz);
    const x0 = cx * CHUNK,
      z0 = cz * CHUNK;
    const out: number[] = [];
    let minY = Infinity,
      maxY = -Infinity;
    const obst: number[] = [];
    for (const b of content.buildings) if (b.collider > 0 || b.kind === "laundry") obst.push(b.x, b.z, Math.max(1, b.collider * b.scale + 0.6));
    for (const p of content.props) {
      const r = PROP_COLLIDER[p.kind] ?? 0;
      if (r > 0) obst.push(p.x, p.z, r * p.scale + 0.2);
    }
    const col = [0, 0, 0];
    for (let j = 0; j < CHUNK; j++)
      for (let i = 0; i < CHUNK; i++) {
        const si = j * GRID + i;
        const ba = s.biomeA[si],
          bb = s.biomeB[si];
        const w = s.w[si];
        const ga = GRASS[ba],
          gb = GRASS[bb];
        const dens = lerp(ga ? ga[0] : 0, gb ? gb[0] : 0, w);
        if (dens <= 0.02) continue;
        const hgt = lerp(ga ? ga[1] : 0.5, gb ? gb[1] : 0.5, w);
        const h00 = s.h[si],
          h10 = s.h[si + 1],
          h01 = s.h[si + GRID],
          h11 = s.h[si + GRID + 1];
        const slope = Math.max(Math.abs(h10 - h00), Math.abs(h01 - h00), Math.abs(h11 - h00));
        const block = Math.max(s.road[si], s.plaza[si] * 3, s.poi[si] * 0.8, s.town[si] * 0.35);
        const k = dens * (1 - clamp01(block * 1.6)) * (1 - clamp01((slope - 0.45) * 3));
        if (k <= 0.02 || h00 < 0.45) continue;
        const n = Math.floor(k * 3.2 + h2(cx * 64 + i, cz * 64 + j, 3));
        for (let q = 0; q < n; q++) {
          const fx = h2(x0 + i, z0 + j, 11 + q),
            fz = h2(x0 + i, z0 + j, 29 + q);
          const lx = i + fx,
            lz = j + fz;
          const wx = x0 + lx,
            wz = z0 + lz;
          let blocked = false;
          for (let o = 0; o < obst.length; o += 3) {
            const dx = wx - obst[o],
              dz = wz - obst[o + 1];
            if (dx * dx + dz * dz < obst[o + 2] * obst[o + 2]) {
              blocked = true;
              break;
            }
          }
          if (blocked) continue;
          const y = lerp(lerp(h00, h10, fx), lerp(h01, h11, fx), fz);
          if (y < 0.45) continue;
          // Цвет — как у земли под травой (тот же шум, что в ландшафте), с разбросом
          const A = BIOMES[ba],
            B = BIOMES[bb];
          const nn = noise2(wx / 23, wz / 23, 991) * 0.5 + 0.5;
          const t = clamp01(nn * 1.2 - 0.1);
          const ag = hexToRgb(A.ground),
            aa = hexToRgb(A.groundAlt),
            bg = hexToRgb(B.ground),
            bA = hexToRgb(B.groundAlt);
          const vr = (0.94 + (noise2(wx / 7, wz / 7, 313) * 0.5 + 0.5) * 0.12) * (0.9 + h2(wx * 3, wz * 3, 5) * 0.2);
          for (let c3 = 0; c3 < 3; c3++) col[c3] = lerp(lerp(ag[c3], aa[c3], t), lerp(bg[c3], bA[c3], t), w) * vr;
          const hh = hgt * (0.55 + h2(wx * 7, wz * 7, 9) * 0.75) * (0.6 + 0.4 * k);
          out.push(lx, y, lz, h2(wx, wz, 13) * 6.283, hh, col[0], col[1], col[2]);
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    const count = out.length / INST;
    if (count === 0) return { cx, cz, vao: gl.createVertexArray()!, buf: gl.createBuffer()!, count: 0, minY: 0, maxY: 0 };
    // Перемешиваем, чтобы первые N инстансов были равномерной выборкой
    const data = new Float32Array(out);
    for (let a = count - 1; a > 0; a--) {
      const b = Math.floor(h2(cx * 131 + a, cz * 71, 41) * (a + 1));
      for (let f = 0; f < INST; f++) {
        const tmp = data[a * INST + f];
        data[a * INST + f] = data[b * INST + f];
        data[b * INST + f] = tmp;
      }
    }
    const vao = gl.createVertexArray()!;
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.bladeIbo);
    setupAttribs(gl, this.bladeVbo, [
      { loc: ATTR.pos, size: 4, type: gl.FLOAT, stride: 32, offset: 0 },
      { loc: ATTR.normal, size: 4, type: gl.FLOAT, stride: 32, offset: 16 },
    ]);
    const buf = staticBuffer(gl, gl.ARRAY_BUFFER, data);
    setupAttribs(gl, buf, [
      { loc: ATTR.i0, size: 4, type: gl.FLOAT, stride: INST * 4, offset: 0, divisor: 1 },
      { loc: ATTR.i1, size: 4, type: gl.FLOAT, stride: INST * 4, offset: 16, divisor: 1 },
    ]);
    gl.bindVertexArray(null);
    return { cx, cz, vao, buf, count, minY, maxY: maxY + 1.5 };
  }

  private dispose(c: GrassChunk) {
    this.gl.deleteVertexArray(c.vao);
    this.gl.deleteBuffer(c.buf);
  }

  clear() {
    for (const c of this.chunks.values()) this.dispose(c);
    this.chunks.clear();
  }

  /** Построить недостающие чанки (не больше одного за кадр) и убрать дальние. */
  update(cam: Camera) {
    if (this.radius <= 0) {
      if (this.chunks.size) this.clear();
      return;
    }
    const ccx = Math.floor(cam.tx / CHUNK),
      ccz = Math.floor(cam.tz / CHUNK);
    const R = this.radius;
    let built = false;
    for (let d = 0; d <= R && !built; d++)
      for (let dz = -d; dz <= d && !built; dz++)
        for (let dx = -d; dx <= d && !built; dx++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) !== d) continue;
          const k = ckey(ccx + dx, ccz + dz);
          if (this.chunks.has(k)) continue;
          const c = this.build(ccx + dx, ccz + dz);
          if (c) this.chunks.set(k, c);
          built = true;
        }
    for (const [k, c] of this.chunks)
      if (Math.abs(c.cx - ccx) > R + 1 || Math.abs(c.cz - ccz) > R + 1) {
        this.dispose(c);
        this.chunks.delete(k);
      }
  }

  draw(cam: Camera) {
    if (this.radius <= 0 || this.chunks.size === 0) return;
    const gl = this.gl;
    const p = this.prog;
    p.use();
    const fadeR = (this.radius + 0.35) * CHUNK;
    p.f2("uFade", fadeR, 10);
    const loc = p.loc("uOffset");
    let drawn = 0;
    for (const c of this.chunks.values()) {
      if (c.count === 0) continue;
      const x0 = c.cx * CHUNK - cam.ox,
        z0 = c.cz * CHUNK - cam.oz;
      if (!cam.boxVisible(x0, c.minY, z0, x0 + CHUNK, c.maxY, z0 + CHUNK)) continue;
      // Дальние чанки — реже
      const mx = c.cx * CHUNK + CHUNK / 2 - cam.tx,
        mz = c.cz * CHUNK + CHUNK / 2 - cam.tz;
      const dist = Math.hypot(mx, mz);
      const k = this.density * (dist < CHUNK ? 1 : Math.max(0.35, 1 - (dist - CHUNK) / (fadeR * 1.4)));
      const n = Math.floor(c.count * k);
      if (n <= 0) continue;
      gl.uniform3f(loc, x0, 0, z0);
      gl.bindVertexArray(c.vao);
      gl.drawElementsInstanced(gl.TRIANGLES, this.bladeCount, gl.UNSIGNED_SHORT, 0, n);
      drawn += n;
    }
    gl.bindVertexArray(null);
    this.drawn = drawn;
  }
}
