export function Glyph({ name, size = 24, color = "currentColor", stroke = 2, style }: { name: string; size?: number; color?: string; stroke?: number; style?: CSSProperties }) {
  const d = P[name] ?? P.star;
  const filled = ["burst", "star", "heart", "shield", "mark", "crit", "elem", "drop", "up", "down", "boomerang", "cone", "fish"].includes(name);
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" style={style} aria-hidden="true">
      <path d={d} fill={filled ? color : "none"} fillOpacity={filled ? 0.9 : 0} stroke={color} strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function hex(c: number, a = 1): string {
  const r = (c >> 16) & 255,
    g = (c >> 8) & 255,
    b = c & 255;
  return a >= 1 ? `rgb(${r},${g},${b})` : `rgba(${r},${g},${b},${a})`;
}
