/**
 * Главный рендерер. Кадр: карта теней → HDR-сцена с MSAA (ландшафт, пропы, сущности, небо, вода, эффекты)
 * → блум и тональная кривая → текст поверх готового кадра.
 */
import { FRAME, MAX_DECALS, MAX_LIGHTS, MAX_SHADOWS, DEPTH_FS } from "./shaders/common";
import { PROP_FS, PROP_VS, SKY_FS, SKY_VS, TERRAIN_FS, TERRAIN_VS, WATER_FS, WATER_VS } from "./shaders/world";
import { Camera } from "./camera";
import { Environment } from "./environment";
import { FRAME_UBO_BINDING, type GL, Program, setupAttribs, staticBuffer, ATTR, TEX_UNIT } from "./gl";
import { TerrainRenderer } from "./terrain";
import { PropRenderer } from "./props";
import { PostFX } from "./post";
import { ShadowMap } from "./shadows";
import { HeightField, HF_SPAN } from "./heightfield";
import { MaterialLibrary } from "./materials";
import { GrassRenderer } from "./grass";
import type { TerrainCache } from "../game/world/terrain-cache";
import { hexToRgb } from "../core/math";

export type QualityLevel = "low" | "medium" | "high";

export interface QualityPreset {
  renderScale: number;
  viewRadius: number;
  propRadius: number;
  decorRadius: number;
  buildingRadius: number;
  detail: boolean;
  maxShadows: number;
  maxLights: number;
  particles: number;
  /** Размер карты теней (0 — без теней, только пятна). */
  shadowSize: number;
  /** Полуразмер области теней, м. */
  shadowRadius: number;
  /** Выборок PCF: 4 или 9. */
  shadowTaps: number;
  /** Размер процедурных текстур материалов. */
  texSize: number;
  /** Трава: радиус в чанках (0 — нет) и густота. */
  grassRadius: number;
  grassDensity: number;
  msaa: boolean;
  fxaa: boolean;
  bloomLevels: number;
}

export const QUALITY: Record<QualityLevel, QualityPreset> = {
  low: {
    renderScale: 0.7,
    viewRadius: 7,
    propRadius: 3,
    decorRadius: 1,
    buildingRadius: 5,
    detail: true,
    maxShadows: 8,
    maxLights: 3,
    particles: 900,
    shadowSize: 1024,
    shadowRadius: 30,
    shadowTaps: 1,
    texSize: 256,
    grassRadius: 1,
    grassDensity: 0.4,
    msaa: false,
    fxaa: true,
    bloomLevels: 4,
  },
  medium: {
    renderScale: 0.9,
    viewRadius: 10,
    propRadius: 4,
    decorRadius: 2,
    buildingRadius: 7,
    detail: true,
    maxShadows: 16,
    maxLights: 6,
    particles: 2200,
    shadowSize: 1024,
    shadowRadius: 38,
    shadowTaps: 4,
    texSize: 256,
    grassRadius: 1,
    grassDensity: 0.75,
    msaa: true,
    fxaa: false,
    bloomLevels: 5,
  },
  high: {
    renderScale: 1.0,
    viewRadius: 14,
    propRadius: 6,
    decorRadius: 3,
    buildingRadius: 10,
    detail: true,
    maxShadows: 24,
    maxLights: 8,
    particles: 4000,
    shadowSize: 2048,
    shadowRadius: 56,
    shadowTaps: 9,
    texSize: 512,
    grassRadius: 2,
    grassDensity: 1,
    msaa: true,
    fxaa: false,
    bloomLevels: 6,
  },
};

export interface PointLight {
  x: number;
  y: number;
  z: number;
  radius: number;
  color: number;
  intensity: number;
}

/** Декаль на земле (кольцо/телеграф/метка). mode: 0 кольцо, 1 круг, 2 телеграф, 3 цель */
export interface Decal {
  x: number;
  y: number;
  z: number;
  r: number;
  color: number;
  mode: number;
  progress: number;
  alpha: number;
}

export interface BlobShadow {
  x: number;
  y: number;
  z: number;
  r: number;
}

/** Дополнительный проход рендера (кошки, частицы, подземелья, текст...). */
export interface RenderPass {
  /** Отбросить тень в карту теней (глубина). */
  shadow?(r: Renderer): void;
  opaque?(r: Renderer): void;
  transparent?(r: Renderer): void;
  /** Поверх готового кадра (после тональной кривой), в sRGB. */
  overlay?(r: Renderer): void;
}

/** sRGB → линейное (то же приближение, что в шейдерах). */
const lin = (c: number) => c * c * (c * 0.2 + 0.8);

export class Renderer {
  readonly gl: GL;
  readonly camera = new Camera();
  readonly env = new Environment();
  readonly progTerrain: Program;
  readonly progProp: Program;
  readonly progSky: Program;
  readonly progWater: Program;
  /** Программы прохода глубины (карта теней). */
  readonly progTerrainDepth: Program;
  readonly progPropDepth: Program;
  readonly post: PostFX;
  readonly heightField: HeightField;
  shadowMap: ShadowMap | null = null;
  materials: MaterialLibrary | null = null;
  terrain: TerrainRenderer | null = null;
  props: PropRenderer | null = null;
  grass: GrassRenderer | null = null;
  quality: QualityPreset = QUALITY.medium;
  qualityLevel: QualityLevel = "medium";
  private ubo: WebGLBuffer;
  private shadowUbo: WebGLBuffer;
  private frame = new Float32Array(FRAME.size);
  private shadowFrame = new Float32Array(FRAME.size);
  private emptyVao: WebGLVertexArrayObject;
  private waterVao: WebGLVertexArrayObject;
  private waterCount: number;
  private dummyShadow: WebGLTexture;
  time = 0;
  lights: PointLight[] = [];
  shadows: BlobShadow[] = [];
  decals: Decal[] = [];
  playerLight: { x: number; y: number; z: number; r: number } | null = null;
  /** Точка, которую не должны загораживать деревья и дома (обычно игрок). */
  focus: { x: number; y: number; z: number; r: number } | null = null;
  waterColor = 0x3a8fd0;
  lava = false;
  showWater = true;
  showSky = true;
  passes: RenderPass[] = [];
  /** Сейчас идёт проход в карту теней (для RenderPass.shadow). */
  shadowPassActive = false;
  /** Динамическое разрешение. */
  dynScale = 1;
  width = 1;
  height = 1;
  stats = { chunks: 0, props: 0, frameMs: 0 };

  constructor(readonly canvas: HTMLCanvasElement) {
    const gl = canvas.getContext("webgl2", {
      antialias: false,
      alpha: false,
      depth: false,
      stencil: false,
      powerPreference: "high-performance",
      preserveDrawingBuffer: false,
    });
    if (!gl) throw new Error("WebGL2 не поддерживается этим браузером");
    this.gl = gl;
    const aniso = gl.getExtension("EXT_texture_filter_anisotropic");
    void aniso;
    this.progTerrain = new Program(gl, TERRAIN_VS, TERRAIN_FS, "terrain");
    this.progProp = new Program(gl, PROP_VS, PROP_FS, "prop");
    this.progSky = new Program(gl, SKY_VS, SKY_FS, "sky");
    this.progWater = new Program(gl, WATER_VS, WATER_FS, "water");
    this.progTerrainDepth = new Program(gl, TERRAIN_VS, DEPTH_FS, "terrain-depth");
    this.progPropDepth = new Program(gl, PROP_VS, DEPTH_FS, "prop-depth");
    this.ubo = gl.createBuffer()!;
    gl.bindBuffer(gl.UNIFORM_BUFFER, this.ubo);
    gl.bufferData(gl.UNIFORM_BUFFER, FRAME.size * 4, gl.DYNAMIC_DRAW);
    this.shadowUbo = gl.createBuffer()!;
    gl.bindBuffer(gl.UNIFORM_BUFFER, this.shadowUbo);
    gl.bufferData(gl.UNIFORM_BUFFER, FRAME.size * 4, gl.DYNAMIC_DRAW);
    gl.bindBufferBase(gl.UNIFORM_BUFFER, FRAME_UBO_BINDING, this.ubo);
    this.emptyVao = gl.createVertexArray()!;
    this.post = new PostFX(gl);
    this.heightField = new HeightField(gl);
    // Заглушка карты теней: сэмплер должен всегда видеть глубинную текстуру со сравнением
    this.dummyShadow = gl.createTexture()!;
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.shadowMap);
    gl.bindTexture(gl.TEXTURE_2D, this.dummyShadow);
    gl.texStorage2D(gl.TEXTURE_2D, 1, gl.DEPTH_COMPONENT24, 1, 1);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_MODE, gl.COMPARE_REF_TO_TEXTURE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_COMPARE_FUNC, gl.LEQUAL);
    gl.activeTexture(gl.TEXTURE0);
    // Сетка воды: плотнее у центра (там видны волны и берег)
    const N = 48,
      S = 1100;
    const pos: number[] = [];
    const warp = (u: number) => Math.sign(u) * Math.pow(Math.abs(u), 1.8);
    for (let j = 0; j <= N; j++) for (let i = 0; i <= N; i++) pos.push(warp((i / N) * 2 - 1) * S * 0.5, 0, warp((j / N) * 2 - 1) * S * 0.5);
    const idx: number[] = [];
    for (let j = 0; j < N; j++)
      for (let i = 0; i < N; i++) {
        const a = j * (N + 1) + i;
        idx.push(a, a + N + 1, a + 1, a + 1, a + N + 1, a + N + 2);
      }
    this.waterVao = gl.createVertexArray()!;
    gl.bindVertexArray(this.waterVao);
    const vb = staticBuffer(gl, gl.ARRAY_BUFFER, new Float32Array(pos));
    setupAttribs(gl, vb, [{ loc: ATTR.pos, size: 3, type: gl.FLOAT, stride: 12, offset: 0 }]);
    staticBuffer(gl, gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx));
    gl.bindVertexArray(null);
    this.waterCount = idx.length;
  }

  setQuality(level: QualityLevel) {
    this.qualityLevel = level;
    this.quality = { ...QUALITY[level] };
    this.degradeStep = 0;
    this.applyQuality();
  }

  /** Сколько ступеней эффектов уже отключено из-за низкого FPS. */
  degradeStep = 0;

  /**
   * Слабое устройство не тянет даже на минимальном разрешении: отключаем эффекты по одному
   * (мех-оболочки, трава, MSAA, блум, тени). Возвращает false, если отключать больше нечего.
   */
  degrade(): boolean {
    const q = this.quality;
    const steps: (() => boolean)[] = [
      () => (q.grassRadius > 0 ? ((q.grassRadius = 0), true) : false),
      () => (q.msaa ? ((q.msaa = false), (q.fxaa = true), true) : false),
      () => (q.bloomLevels > 3 ? ((q.bloomLevels = 3), true) : false),
      () => (q.shadowSize > 0 ? ((q.shadowSize = 0), true) : false),
      () => (q.bloomLevels > 0 ? ((q.bloomLevels = 0), true) : false),
    ];
    while (this.degradeStep < steps.length) {
      const ok = steps[this.degradeStep++]();
      if (ok) {
        this.applyQuality();
        return true;
      }
    }
    return false;
  }

  private applyQuality() {
    const q = this.quality;
    if (this.terrain) {
      this.terrain.viewRadius = q.viewRadius;
      this.terrain.detail = q.detail;
    }
    if (this.props) {
      this.props.propRadius = q.propRadius;
      this.props.decorRadius = q.decorRadius;
      this.props.buildingRadius = q.buildingRadius;
    }
    if (this.grass) {
      this.grass.radius = q.grassRadius;
      this.grass.density = q.grassDensity;
    }
    this.camera.far = (q.viewRadius + 1) * 32 * 1.05;
    this.post.setOptions({ msaa: q.msaa, fxaa: q.fxaa, bloom: q.bloomLevels > 0, bloomLevels: q.bloomLevels });
    if ((this.materials?.size ?? 0) !== q.texSize) {
      this.materials?.dispose();
      this.materials = new MaterialLibrary(this.gl, q.texSize);
    }
    if ((this.shadowMap?.size ?? 0) !== q.shadowSize) {
      this.shadowMap?.dispose();
      this.shadowMap = null;
      if (q.shadowSize > 0) {
        const sm = new ShadowMap(this.gl, q.shadowSize);
        if (sm.ok) this.shadowMap = sm;
        else sm.dispose();
      }
    }
  }

  setWorld(cache: TerrainCache | null) {
    this.terrain?.clear();
    this.props?.clear();
    this.grass?.clear();
    this.terrain = cache ? new TerrainRenderer(this.gl, cache) : null;
    this.props = cache ? new PropRenderer(this.gl, cache) : null;
    this.grass = cache ? new GrassRenderer(this.gl, cache) : null;
    this.heightField.reset();
    this.applyQuality();
  }

  /** Освободить GPU-ресурсы (контекст больше не используется). */
  dispose() {
    this.terrain?.clear();
    this.props?.clear();
    this.grass?.clear();
    this.terrain = null;
    this.props = null;
    this.grass = null;
    this.passes.length = 0;
    this.post.dispose();
    this.shadowMap?.dispose();
    this.materials?.dispose();
    this.gl.getExtension("WEBGL_lose_context")?.loseContext();
  }

  resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const scale = this.quality.renderScale * this.dynScale;
    const w = Math.max(1, Math.floor(this.canvas.clientWidth * dpr * scale));
    const h = Math.max(1, Math.floor(this.canvas.clientHeight * dpr * scale));
    if (this.canvas.width !== w || this.canvas.height !== h) {
      this.canvas.width = w;
      this.canvas.height = h;
    }
    this.width = w;
    this.height = h;
  }

  /** Обновить мир вокруг камеры (генерация чанков) с бюджетом времени. */
  updateWorld(budgetMs: number) {
    if (this.terrain) this.terrain.update(this.camera, budgetMs);
    if (this.grass && !this.env.dungeon) this.grass.update(this.camera);
  }

  get loadingPending(): number {
    return this.terrain ? this.terrain.pending : 0;
  }

  /** Центр области теней: перед камерой, чтобы покрыть видимую землю. */
  private shadowCenter(): [number, number, number] {
    const cam = this.camera;
    const r = this.quality.shadowRadius;
    let fx = cam.tx - cam.ex,
      fz = cam.tz - cam.ez;
    const l = Math.hypot(fx, fz) || 1;
    fx /= l;
    fz /= l;
    const k = r * 0.38;
    return [cam.tx + fx * k, cam.ty, cam.tz + fz * k];
  }

  private writeFrame(shadowOn: boolean) {
    const f = this.frame;
    const cam = this.camera;
    const env = this.env;
    f.set(cam.viewProj, FRAME.viewProj);
    f.set(cam.view, FRAME.view);
    f[FRAME.camPos] = cam.ex - cam.ox;
    f[FRAME.camPos + 1] = cam.ey;
    f[FRAME.camPos + 2] = cam.ez - cam.oz;
    f[FRAME.camPos + 3] = this.time;
    f.set(env.sunDir, FRAME.sunDir);
    f[FRAME.sunDir + 3] = env.sunIntensity;
    const setLin = (o: number, c: readonly number[], w: number) => {
      f[o] = lin(c[0]);
      f[o + 1] = lin(c[1]);
      f[o + 2] = lin(c[2]);
      f[o + 3] = w;
    };
    setLin(FRAME.sunColor, env.sunColor, env.ambient);
    setLin(FRAME.skyColor, env.sky, env.dungeon ? 1 : 0);
    const far = this.camera.far;
    setLin(FRAME.horizon, env.horizon, env.dungeon ? 20 : far * 0.42);
    setLin(FRAME.ground, env.ground, env.dungeon ? 62 : far * 0.96);
    f[FRAME.originMod] = ((cam.ox % 1024) + 1024) % 1024;
    f[FRAME.originMod + 1] = ((cam.oz % 1024) + 1024) % 1024;
    f[FRAME.originMod + 2] = env.night;
    f[FRAME.originMod + 3] = this.qualityLevel === "high" ? 2 : this.qualityLevel === "medium" ? 1 : 0;
    if (this.playerLight) {
      f[FRAME.playerLight] = this.playerLight.x - cam.ox;
      f[FRAME.playerLight + 1] = this.playerLight.y;
      f[FRAME.playerLight + 2] = this.playerLight.z - cam.oz;
      f[FRAME.playerLight + 3] = this.playerLight.r;
    } else f[FRAME.playerLight + 3] = 0;
    if (this.focus) {
      f[FRAME.focus] = this.focus.x - cam.ox;
      f[FRAME.focus + 1] = this.focus.y;
      f[FRAME.focus + 2] = this.focus.z - cam.oz;
      f[FRAME.focus + 3] = this.focus.r;
    } else f[FRAME.focus + 3] = 0;
    // Точечные источники: ближайшие к камере
    const maxL = Math.min(MAX_LIGHTS, this.quality.maxLights);
    const lights = this.lights;
    if (lights.length > maxL) {
      const tx = cam.tx,
        tz = cam.tz;
      lights.sort((a, b) => (a.x - tx) ** 2 + (a.z - tz) ** 2 - ((b.x - tx) ** 2 + (b.z - tz) ** 2));
    }
    const nl = Math.min(maxL, lights.length);
    for (let i = 0; i < nl; i++) {
      const l = lights[i];
      const o = FRAME.lights + i * 4;
      f[o] = l.x - cam.ox;
      f[o + 1] = l.y;
      f[o + 2] = l.z - cam.oz;
      f[o + 3] = l.radius;
      setLin(FRAME.lightColors + i * 4, hexToRgb(l.color), l.intensity * 1.6);
    }
    const maxS = Math.min(MAX_SHADOWS, this.quality.maxShadows);
    const sh = this.shadows;
    if (sh.length > maxS) {
      const tx = cam.tx,
        tz = cam.tz;
      sh.sort((a, b) => (a.x - tx) ** 2 + (a.z - tz) ** 2 - ((b.x - tx) ** 2 + (b.z - tz) ** 2));
    }
    const ns = Math.min(maxS, sh.length);
    for (let i = 0; i < ns; i++) {
      const s = sh[i];
      const o = FRAME.shadows + i * 4;
      f[o] = s.x - cam.ox;
      f[o + 1] = s.y;
      f[o + 2] = s.z - cam.oz;
      // С картой теней пятна служат лишь контактной тенью
      f[o + 3] = shadowOn ? s.r * 0.75 : s.r;
    }
    const dc = this.decals;
    if (dc.length > MAX_DECALS) {
      const tx = cam.tx,
        tz = cam.tz;
      dc.sort((a, b) => (a.mode === 3 ? -1 : 0) - (b.mode === 3 ? -1 : 0) || (a.x - tx) ** 2 + (a.z - tz) ** 2 - ((b.x - tx) ** 2 + (b.z - tz) ** 2));
    }
    const nd = Math.min(MAX_DECALS, dc.length);
    for (let i = 0; i < nd; i++) {
      const d = dc[i];
      const o = FRAME.decals + i * 4;
      f[o] = d.x - cam.ox;
      f[o + 1] = d.y;
      f[o + 2] = d.z - cam.oz;
      f[o + 3] = d.r;
      setLin(FRAME.decalColors + i * 4, hexToRgb(d.color), d.mode);
      const op = FRAME.decalParams + i * 4;
      f[op] = d.progress;
      f[op + 1] = d.alpha;
      f[op + 2] = 0;
      f[op + 3] = 0;
    }
    f[FRAME.counts] = nl;
    f[FRAME.counts + 1] = ns;
    f[FRAME.counts + 2] = nd;
    f[FRAME.counts + 3] = shadowOn ? 1 : 0;
    const sm = this.shadowMap;
    if (shadowOn && sm) {
      f.set(sm.shadowMat, FRAME.shadowMat);
      f[FRAME.shadowParams] = sm.texelWorld;
      f[FRAME.shadowParams + 1] = env.shadowStrength;
      f[FRAME.shadowParams + 2] = 1 / sm.size;
      f[FRAME.shadowParams + 3] = this.quality.shadowTaps;
    }
    f[FRAME.sunTrue] = env.sunTrue[0];
    f[FRAME.sunTrue + 1] = env.sunTrue[1];
    f[FRAME.sunTrue + 2] = env.sunTrue[2];
    f[FRAME.sunTrue + 3] = env.moonVis;
    f[FRAME.moonDir] = env.moonDir[0];
    f[FRAME.moonDir + 1] = env.moonDir[1];
    f[FRAME.moonDir + 2] = env.moonDir[2];
    f[FRAME.moonDir + 3] = env.aurora;
    f[FRAME.wind] = env.windX;
    f[FRAME.wind + 1] = env.windZ;
    f[FRAME.wind + 2] = env.windStrength;
    f[FRAME.wind + 3] = env.cloudCover;
    f[FRAME.fogParams] = env.valleyFog;
    f[FRAME.fogParams + 1] = 0.12;
    f[FRAME.fogParams + 2] = 0;
    f[FRAME.fogParams + 3] = env.wetness;
    f[FRAME.misc] = 0;
    f[FRAME.misc + 1] = env.snow;
    f[FRAME.misc + 2] = this.terrain && this.heightField.ready ? HF_SPAN * 0.42 : 0;
    f[FRAME.misc + 3] = 1 / HF_SPAN;
    const gl = this.gl;
    gl.bindBuffer(gl.UNIFORM_BUFFER, this.ubo);
    gl.bufferSubData(gl.UNIFORM_BUFFER, 0, f);
    if (shadowOn && sm) {
      const s = this.shadowFrame;
      s.set(f);
      s.set(sm.viewProj, FRAME.viewProj);
      gl.bindBuffer(gl.UNIFORM_BUFFER, this.shadowUbo);
      gl.bufferSubData(gl.UNIFORM_BUFFER, 0, s);
    }
  }

  /** Солнце на экране для лучей: сильнее у низкого солнца, гаснет за краем кадра и ночью. */
  private updateSunShafts() {
    const env = this.env;
    const sun = this.post.sun;
    sun[2] = 0;
    if (env.dungeon || !this.showSky || this.qualityLevel === "low") return;
    const d = env.sunTrue;
    if (d[1] < -0.05) return;
    const cam = this.camera;
    const m = cam.viewProj;
    // Точка далеко в сторону солнца (в пространстве рендера)
    const px = cam.ex - cam.ox + d[0] * 500,
      py = cam.ey + d[1] * 500,
      pz = cam.ez - cam.oz + d[2] * 500;
    const cx = m[0] * px + m[4] * py + m[8] * pz + m[12];
    const cy = m[1] * px + m[5] * py + m[9] * pz + m[13];
    const cw = m[3] * px + m[7] * py + m[11] * pz + m[15];
    if (cw <= 0.01) return;
    const u = (cx / cw) * 0.5 + 0.5,
      v = (cy / cw) * 0.5 + 0.5;
    const off = Math.max(Math.abs(u - 0.5), Math.abs(v - 0.5));
    const onScreen = 1 - Math.min(1, Math.max(0, (off - 0.5) / 0.35));
    const low = 1 - Math.min(1, Math.max(0, (d[1] - 0.05) / 0.5));
    const day = 1 - env.night;
    sun[0] = u;
    sun[1] = v;
    sun[2] = onScreen * day * (0.25 + 0.75 * low) * 0.55;
  }

  /** Проход глубины от солнца. */
  private renderShadows() {
    const sm = this.shadowMap!;
    const gl = this.gl;
    const cam = this.camera;
    gl.bindBufferBase(gl.UNIFORM_BUFFER, FRAME_UBO_BINDING, this.shadowUbo);
    sm.begin();
    this.shadowPassActive = true;
    gl.disable(gl.CULL_FACE);
    if (this.terrain) this.terrain.drawShadow(cam, this.progTerrainDepth, sm.cx, sm.cz, sm.radius + 4);
    if (this.props) this.props.drawShadow(this.progPropDepth);
    for (const p of this.passes) p.shadow?.(this);
    this.shadowPassActive = false;
    sm.end();
    gl.bindBufferBase(gl.UNIFORM_BUFFER, FRAME_UBO_BINDING, this.ubo);
  }

  render(dt: number, groundAt?: (x: number, z: number) => number) {
    const t0 = performance.now();
    this.time += dt;
    this.env.update(dt);
    this.resize();
    const gl = this.gl;
    const cam = this.camera;
    cam.update(this.width / this.height, groundAt);
    // Высоты для воды
    if (this.terrain && !this.env.dungeon) {
      const gen = this.terrain.cache.gen;
      this.heightField.update(cam.tx, cam.tz, (x, z) => gen.height(x, z));
    }
    // Карта теней
    const sm = this.shadowMap;
    const shadowOn = !!sm && this.env.shadowStrength > 0.02;
    let sc: [number, number, number] = [cam.tx, cam.ty, cam.tz];
    if (shadowOn && sm) {
      sc = this.shadowCenter();
      sm.update(sc[0], sc[1], sc[2], cam.ox, cam.oz, this.env.sunDir, this.quality.shadowRadius, 160);
    }
    if (this.props) this.props.collect(cam, sc[0], sc[2], shadowOn ? this.quality.shadowRadius + 6 : 0);
    this.writeFrame(shadowOn);
    // Текстуры на постоянных слотах
    this.materials?.bind();
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.heightField);
    gl.bindTexture(gl.TEXTURE_2D, this.heightField.tex);
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.shadowMap);
    gl.bindTexture(gl.TEXTURE_2D, this.dummyShadow);
    gl.activeTexture(gl.TEXTURE0);
    if (shadowOn) {
      this.renderShadows();
      gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.shadowMap);
      gl.bindTexture(gl.TEXTURE_2D, sm!.tex);
      gl.activeTexture(gl.TEXTURE0);
    }
    // Сцена в HDR
    this.post.time = this.time;
    const g = this.post.grade;
    const env = this.env;
    g.exposure = env.exposure;
    g.saturation = env.saturation;
    g.shadowTint = env.shadowTint;
    g.lightTint = env.lightTint;
    this.updateSunShafts();
    this.post.begin(this.width, this.height);
    const hz = env.horizon;
    gl.clearColor(lin(hz[0]), lin(hz[1]), lin(hz[2]), 1);
    gl.depthMask(true);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.disable(gl.BLEND);

    // Ландшафт
    gl.disable(gl.CULL_FACE);
    if (this.terrain) this.stats.chunks = this.terrain.draw(cam, this.progTerrain);
    if (this.grass && !env.dungeon) this.grass.draw(cam);
    // Пропы и постройки
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);
    if (this.props) {
      this.props.draw(this.progProp);
      this.stats.props = this.props.drawn;
    }
    for (const p of this.passes) p.opaque?.(this);
    // Небо — после непрозрачного (раннее отсечение глубины)
    if (this.showSky && !env.dungeon) {
      gl.disable(gl.CULL_FACE);
      gl.depthMask(false);
      this.progSky.use();
      this.progSky.m4("uInvViewProj", cam.invViewProj);
      this.progSky.f1("uQuality", this.qualityLevel === "low" ? 0 : 1);
      gl.bindVertexArray(this.emptyVao);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      gl.depthMask(true);
    }
    // Вода
    if (this.showWater && !env.dungeon) {
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
      gl.disable(gl.CULL_FACE);
      this.progWater.use();
      const sx = Math.round(cam.tx / 8) * 8 - cam.ox;
      const sz = Math.round(cam.tz / 8) * 8 - cam.oz;
      this.progWater.f3("uOffset", sx, 0, sz);
      const wc = hexToRgb(this.waterColor);
      this.progWater.f3("uWaterColor", wc[0], wc[1], wc[2]);
      this.progWater.f1("uLava", this.lava ? 1 : 0);
      gl.bindVertexArray(this.waterVao);
      gl.drawElements(gl.TRIANGLES, this.waterCount, gl.UNSIGNED_SHORT, 0);
      gl.disable(gl.BLEND);
    }
    for (const p of this.passes) p.transparent?.(this);
    gl.bindVertexArray(null);
    // Пост-обработка и вывод
    this.post.end();
    for (const p of this.passes) p.overlay?.(this);
    gl.bindVertexArray(null);
    this.stats.frameMs = performance.now() - t0;
  }
}
