/**
 * Высоты ландшафта вокруг камеры в текстуре R16F: по ним вода знает глубину (цвет, прозрачность, пена у берега).
 * Адресация тороидальная: тексель хранит точку мира с тем же остатком по модулю размера окна,
 * поэтому при движении камеры дописываются только новые столбцы и строки.
 */
import { type GL, TEX_UNIT } from "./gl";

export const HF_SIZE = 128;
export const HF_STEP = 2;
/** Покрытие в метрах (делит 1024 — период координат в шейдерах). */
export const HF_SPAN = HF_SIZE * HF_STEP;

export class HeightField {
  readonly tex: WebGLTexture;
  private i0 = 0;
  private j0 = 0;
  private valid = false;
  /** Строки, которые ещё нужно заполнить после полного сброса. */
  private pendingRows: number[] = [];
  private col = new Float32Array(HF_SIZE);
  private row = new Float32Array(HF_SIZE);

  constructor(readonly gl: GL) {
    this.tex = gl.createTexture()!;
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.heightField);
    gl.bindTexture(gl.TEXTURE_2D, this.tex);
    gl.texStorage2D(gl.TEXTURE_2D, 1, gl.R16F, HF_SIZE, HF_SIZE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
    const init = new Float32Array(HF_SIZE * HF_SIZE).fill(-20);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, HF_SIZE, HF_SIZE, gl.RED, gl.FLOAT, init);
    gl.activeTexture(gl.TEXTURE0);
  }

  /** Готово ли окно вокруг камеры (иначе вода считает дно глубоким). */
  get ready(): boolean {
    return this.valid && this.pendingRows.length === 0;
  }

  reset() {
    this.valid = false;
    this.pendingRows.length = 0;
  }

  private mod(v: number) {
    return ((v % HF_SIZE) + HF_SIZE) % HF_SIZE;
  }

  /** Записать столбец мира I (в пределах текущего окна по J). */
  private writeCol(I: number, height: (x: number, z: number) => number) {
    const c = this.col;
    const x = (I + 0.5) * HF_STEP;
    for (let J = this.j0; J < this.j0 + HF_SIZE; J++) c[this.mod(J)] = height(x, (J + 0.5) * HF_STEP);
    this.gl.texSubImage2D(this.gl.TEXTURE_2D, 0, this.mod(I), 0, 1, HF_SIZE, this.gl.RED, this.gl.FLOAT, c);
  }

  private writeRow(J: number, height: (x: number, z: number) => number) {
    const r = this.row;
    const z = (J + 0.5) * HF_STEP;
    for (let I = this.i0; I < this.i0 + HF_SIZE; I++) r[this.mod(I)] = height((I + 0.5) * HF_STEP, z);
    this.gl.texSubImage2D(this.gl.TEXTURE_2D, 0, 0, this.mod(J), HF_SIZE, 1, this.gl.RED, this.gl.FLOAT, r);
  }

  /** Сдвинуть окно к камере. budget — сколько строк/столбцов можно записать за кадр. */
  update(camX: number, camZ: number, height: (x: number, z: number) => number, budget = 6) {
    const gl = this.gl;
    const ti = Math.floor(camX / HF_STEP) - HF_SIZE / 2;
    const tj = Math.floor(camZ / HF_STEP) - HF_SIZE / 2;
    gl.activeTexture(gl.TEXTURE0 + TEX_UNIT.heightField);
    gl.bindTexture(gl.TEXTURE_2D, this.tex);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);
    if (!this.valid || Math.abs(ti - this.i0) >= HF_SIZE / 2 || Math.abs(tj - this.j0) >= HF_SIZE / 2) {
      this.i0 = ti;
      this.j0 = tj;
      this.valid = true;
      this.pendingRows = [];
      // Сначала строки у камеры
      for (let k = 0; k < HF_SIZE; k++) {
        const off = k % 2 === 0 ? k / 2 : -(k + 1) / 2;
        this.pendingRows.push(tj + HF_SIZE / 2 + off);
      }
    }
    let n = 0;
    while (this.pendingRows.length && n < budget * 3) {
      this.writeRow(this.pendingRows.shift()!, height);
      n++;
    }
    if (this.pendingRows.length) {
      gl.activeTexture(gl.TEXTURE0);
      return;
    }
    while (n < budget && this.i0 !== ti) {
      if (this.i0 < ti) {
        this.i0++;
        this.writeCol(this.i0 + HF_SIZE - 1, height);
      } else {
        this.i0--;
        this.writeCol(this.i0, height);
      }
      n++;
    }
    while (n < budget && this.j0 !== tj) {
      if (this.j0 < tj) {
        this.j0++;
        this.writeRow(this.j0 + HF_SIZE - 1, height);
      } else {
        this.j0--;
        this.writeRow(this.j0, height);
      }
      n++;
    }
    gl.activeTexture(gl.TEXTURE0);
  }

  dispose() {
    this.gl.deleteTexture(this.tex);
  }
}
