/** Поведение: враги (включая боссов), призванные союзники и мирные жители. */
import { dist, wrapAngle } from "../../core/math";
import type { SkillDef } from "../skills/types";
import { hasStatus, isDisabled, isHostile } from "./combat";
import type { Entity } from "./types";
import type { GameWorld } from "./world";

function setMove(e: Entity, dx: number, dz: number, k = 1) {
  const l = Math.hypot(dx, dz);
  if (l < 1e-4) {
    e.moveX = 0;
    e.moveZ = 0;
    return;
  }
  e.moveX = (dx / l) * k;
  e.moveZ = (dz / l) * k;
}

function skillInRange(w: GameWorld, e: Entity, s: SkillDef, t: Entity, d: number): boolean {
  const p = s.params;
  switch (s.delivery) {
    case "strike":
      return d <= p.radius + t.radius * 0.8;
    case "projectile":
    case "boomerang":
    case "chain":
    case "blast":
    case "rain":
    case "vortex":
    case "mark":
      return d <= p.range * 0.9;
    case "nova":
      return d <= p.radius * 0.75 + t.radius;
    case "cone":
      return d <= p.radius * 0.85;
    case "dash":
      return d > 3 && d <= p.range + 1;
    case "leap":
      return d > 4 && d <= p.range;
    case "summon":
      return d < 16;
    case "heal": {
      for (const o of w.entities.values()) if (o.alive && o.faction === e.faction && o.kind !== "npc" && o.hp < o.maxHp * 0.65 && dist(o.x, o.z, e.x, e.z) < p.radius) return true;
      return false;
    }
    case "barrier":
      return e.hp < e.maxHp * 0.75 && e.shield <= 0;
    case "buff":
      return d < 14;
    default:
      return d < 10;
  }
}

export function updateAI(w: GameWorld, e: Entity, dt: number) {
  const ai = e.ai;
  if (!ai || !e.alive) return;
  if (e.motion) return;
  if (isDisabled(e)) {
    e.moveX = e.moveZ = 0;
    return;
  }
  // Страх: бежим прочь
  if (hasStatus(e, "fear")) {
    const src = w.entities.get(ai.lastHitBy) ?? w.nearestHostile(e, 20);
    if (src) setMove(e, e.x - src.x, e.z - src.z);
    return;
  }
  if (e.kind === "npc") return npcAI(w, e, dt);
  if (e.kind === "minion") return minionAI(w, e, dt);
  combatAI(w, e, dt);
}

function combatAI(w: GameWorld, e: Entity, dt: number) {
  const ai = e.ai!;
  let target = ai.target >= 0 ? w.entities.get(ai.target) ?? null : null;
  if (target && (!target.alive || !isHostile(target, e))) {
    target = null;
    ai.target = -1;
  }
  const boss = !!e.enemy?.boss;
  if (!target) {
    const t = w.nearestHostile(e, ai.aggro);
    if (t) {
      target = t;
      ai.target = t.id;
      ai.mode = "chase";
      // Будим соседей по стае
      for (const o of w.entities.values()) {
        if (o !== e && o.alive && o.ai && o.faction === e.faction && o.ai.target < 0 && dist(o.x, o.z, e.x, e.z) < 10) {
          o.ai.target = t.id;
          o.ai.mode = "chase";
        }
      }
      if (boss) w.emit({ t: "sound", s: "bossRoar", x: e.x, z: e.z });
    }
  }
  if (e.state !== "alive" && e.state !== "swim" && target) e.state = "alive";
  if (!target) {
    // Возврат домой и безделье
    const dh = dist(e.x, e.z, ai.homeX, ai.homeZ);
    if (ai.mode === "return" || dh > ai.leash * 0.7) {
      ai.mode = dh < 2 ? "idle" : "return";
      setMove(e, ai.homeX - e.x, ai.homeZ - e.z, 1);
      if (ai.mode === "idle") e.hp = e.maxHp;
      return;
    }
    ai.t -= dt;
    if (ai.t <= 0) {
      ai.t = 3 + w.rng.next() * 5;
      if (w.rng.chance(0.5)) {
        const a = w.rng.next() * Math.PI * 2;
        ai.wx = ai.homeX + Math.cos(a) * w.rng.range(2, 7);
        ai.wz = ai.homeZ + Math.sin(a) * w.rng.range(2, 7);
        ai.mode = "wander";
        e.state = "alive";
      } else {
        ai.mode = "idle";
        if (!boss && w.rng.chance(0.3)) {
          e.state = w.rng.chance(0.5) ? "sit" : "loaf";
          e.stateT = 0;
        }
      }
    }
    if (ai.mode === "wander") {
      if (dist(e.x, e.z, ai.wx, ai.wz) < 1) {
        ai.mode = "idle";
        e.moveX = e.moveZ = 0;
      } else setMove(e, ai.wx - e.x, ai.wz - e.z, 0.4);
    } else {
      e.moveX = e.moveZ = 0;
    }
    if (e.hp < e.maxHp && w.time - e.lastCombat > 5) e.hp = Math.min(e.maxHp, e.hp + e.maxHp * 0.08 * dt);
    return;
  }
  // Поводок
  if (dist(e.x, e.z, ai.homeX, ai.homeZ) > ai.leash && !boss) {
    ai.target = -1;
    ai.mode = "return";
    return;
  }
  const d = dist(e.x, e.z, target.x, target.z);
  e.lookX = target.x;
  e.lookZ = target.z;
  // Фазы босса
  if (boss) {
    const frac = e.hp / e.maxHp;
    if (ai.phase === 0 && frac < 0.5) {
      ai.phase = 1;
      w.emit({ t: "text", text: { ru: "Ярость!", en: "Enrage!" }, x: e.x, y: e.y + 3, z: e.z, color: 0xff5a3a });
      w.emit({ t: "sound", s: "bossRoar", x: e.x, z: e.z });
      e.dmg *= 1.25;
    }
    if (ai.phase === 1 && frac < 0.2) {
      ai.phase = 2;
      e.dmg *= 1.2;
      e.baseSpeed *= 1.2;
    }
  }
  // Выбор умения
  if (!e.cast) {
    const skills = ai.skills;
    for (let i = skills.length - 1; i >= 0; i--) {
      const s = skills[i];
      if ((e.cds.get(s.id) ?? 0) > 0) continue;
      if (!skillInRange(w, e, s, target, d)) continue;
      const res = w.tryCast(e, s, target.x, target.z, target.id);
      if (res === "ok") {
        if (boss && ai.phase > 0) e.cds.set(s.id, (e.cds.get(s.id) ?? 0) * 0.7);
        break;
      }
    }
  }
  // Движение
  const keep = ai.keepDist;
  const melee = ai.skills[0];
  const reach = melee && melee.delivery === "strike" ? melee.params.radius * 0.75 + target.radius : 2;
  if (e.enemy?.role === "bomber") {
    setMove(e, target.x - e.x, target.z - e.z);
  } else if (keep > 0) {
    if (d < keep - 2.5) setMove(e, e.x - target.x, e.z - target.z, 0.9);
    else if (d > keep + 2) setMove(e, target.x - e.x, target.z - e.z);
    else {
      // стрейф
      const side = Math.sin(w.time * 0.7 + e.id) > 0 ? 1 : -1;
      setMove(e, -(target.z - e.z) * side, (target.x - e.x) * side, 0.45);
    }
  } else if (d > reach) {
    const dir = w.pathDir(e, target.x, target.z);
    setMove(e, dir[0], dir[1]);
  } else {
    e.moveX = e.moveZ = 0;
  }
  if (!e.cast && e.moveX === 0 && e.moveZ === 0) {
    const want = Math.atan2(target.x - e.x, target.z - e.z);
    e.yaw += wrapAngle(want - e.yaw) * Math.min(1, dt * 8);
  }
}

function minionAI(w: GameWorld, e: Entity, dt: number) {
  const ai = e.ai!;
  const owner = e.minion ? w.entities.get(e.minion.ownerId) : null;
  if (!owner || !owner.alive) {
    e.moveX = e.moveZ = 0;
    return;
  }
  let target = ai.target >= 0 ? w.entities.get(ai.target) ?? null : null;
  if (target && (!target.alive || !isHostile(target, e) || dist(target.x, target.z, owner.x, owner.z) > 18)) {
    target = null;
    ai.target = -1;
  }
  if (!target) {
    const t = w.nearestHostileTo(owner.x, owner.z, e.faction, 13);
    if (t) {
      target = t;
      ai.target = t.id;
    }
  }
  const dOwner = dist(e.x, e.z, owner.x, owner.z);
  if (!target || dOwner > 16) {
    if (dOwner > 3.5) setMove(e, owner.x - e.x + Math.sin(e.id) * 2, owner.z - e.z + Math.cos(e.id) * 2, dOwner > 8 ? 1.3 : 1);
    else e.moveX = e.moveZ = 0;
    if (dOwner > 30) {
      e.x = owner.x + Math.sin(e.id) * 2;
      e.z = owner.z + Math.cos(e.id) * 2;
    }
    return;
  }
  const d = dist(e.x, e.z, target.x, target.z);
  const s = e.minion!.skill;
  const range = s.delivery === "strike" ? s.params.radius + target.radius * 0.7 : s.params.range * 0.8;
  e.lookX = target.x;
  e.lookZ = target.z;
  if (d <= range) {
    e.moveX = e.moveZ = 0;
    if (!e.cast) w.tryCast(e, s, target.x, target.z, target.id);
  } else {
    const dir = w.pathDir(e, target.x, target.z);
    setMove(e, dir[0], dir[1]);
  }
}

function npcAI(w: GameWorld, e: Entity, dt: number) {
  const ai = e.ai!;
  ai.t -= dt;
  const pl = w.nearestPlayer(e.x, e.z, 7);
  if (pl) {
    e.lookX = pl.x;
    e.lookZ = pl.z;
  } else {
    e.lookX = undefined;
    e.lookZ = undefined;
  }
  const role = e.npc?.role;
  if (role === "questgiver" || role === "merchant" || role === "smith" || role === "innkeeper" || role === "trainer" || role === "elder") {
    // Стоят на месте, иногда садятся
    e.moveX = e.moveZ = 0;
    if (ai.t <= 0) {
      ai.t = 6 + w.rng.next() * 10;
      e.state = pl ? "alive" : w.rng.chance(0.5) ? "sit" : "alive";
    }
    if (pl && e.state !== "alive") e.state = "alive";
    return;
  }
  if (ai.t <= 0) {
    ai.t = 4 + w.rng.next() * 8;
    const r = w.rng.next();
    if (role === "guard" || r < 0.5) {
      const a = w.rng.next() * Math.PI * 2;
      const rad = role === "guard" ? 10 : 6;
      ai.wx = ai.homeX + Math.cos(a) * rad;
      ai.wz = ai.homeZ + Math.sin(a) * rad;
      ai.mode = "wander";
      e.state = "alive";
    } else {
      ai.mode = "idle";
      e.state = r < 0.7 ? "sit" : r < 0.9 ? "loaf" : "sleep";
      e.stateT = 0;
    }
  }
  if (ai.mode === "wander") {
    if (dist(e.x, e.z, ai.wx, ai.wz) < 0.8) {
      ai.mode = "idle";
      e.moveX = e.moveZ = 0;
    } else setMove(e, ai.wx - e.x, ai.wz - e.z, 0.35);
  } else e.moveX = e.moveZ = 0;
}
