export function townName(rng: Rng): Txt {
  const r = rng.pick(TOWN_ROOTS);
  const s = rng.pick(TOWN_SUFFIX);
  let ru = r.ru + s.ru;
  let en = r.en + s.en;
  if (rng.chance(0.18)) {
    const p = rng.pick(TOWN_PREFIX);
    ru = `${p[s.g]} ${ru}`;
    en = `${p.en} ${en}`;
  }
  return { ru, en };
}

