export function dungeonName(rng: Rng, theme: string): Txt {
  const base = rng.pick(DUNGEON_NOUN[theme] ?? DUNGEON_NOUN.cave);
  const g = rng.pick(GENITIVES);
  return rng.chance(0.5) ? base : { ru: `${base.ru} ${g.ru}`, en: `${base.en} of ${g.en}` };
}
