/**
 * Состояние кооператива для интерфейса: создание приглашения (хост),
 * присоединение по коду (гость), статус соединения.
 */
import { makeAutoObservable, runInAction } from "mobx";
import type { Txt } from "../core/i18n";
import type { CharacterStore } from "../game/character";
import type { GameSession } from "../game/session";
import { Peer } from "./peer";
import { answerLink, decodeSignal, inviteLink, PROTOCOL_VERSION, RELAY_CHANNEL, type SignalPayload } from "./signal";
import { HostBridge } from "./host";
import { GuestBridge } from "./guest";
import { packStats, type HostMsg, type WelcomeMsg } from "./protocol";

export type CoopStatus = "idle" | "preparing" | "invite" | "answer" | "connecting" | "connected" | "closed" | "error";

const ERRORS: Record<string, Txt> = {
  "bad-code": { ru: "Код не распознан. Скопируйте его целиком.", en: "The code was not recognized. Copy it completely." },
  "not-answer": { ru: "Это код приглашения, а нужен код ответа друга.", en: "That's an invite code — paste your friend's answer code." },
  "not-offer": { ru: "Это код ответа, а нужен код приглашения.", en: "That's an answer code — paste the invite code." },
  "no-decompress": { ru: "Браузер не поддерживает распаковку кода.", en: "This browser cannot unpack the code." },
  "no-webrtc": { ru: "Браузер не поддерживает WebRTC.", en: "This browser does not support WebRTC." },
  timeout: { ru: "Не удалось соединиться. Проверьте коды или включите STUN.", en: "Could not connect. Check the codes or enable STUN." },
  version: { ru: "У вас разные версии игры — обновите страницу.", en: "Game versions differ — reload the page." },
};

/** Приветствие хоста: проверяем форму, прежде чем строить по нему мир. */
function validWelcome(w: WelcomeMsg): boolean {
  const okNum = (v: unknown) => typeof v === "number" && Number.isFinite(v);
  const m = w.mode as unknown as Record<string, unknown> | undefined;
  return (
    okNum(w.seed) &&
    okNum(w.you) &&
    okNum(w.ep) &&
    !!m &&
    (m.world === "continent" || m.world === "infinite") &&
    (m.skills === "classic" || m.skills === "infinite") &&
    (m.levels === "capped" || m.levels === "infinite") &&
    !!w.pos &&
    okNum(w.pos.x) &&
    okNum(w.pos.z) &&
    !!w.host &&
    typeof w.hostName === "string" &&
    (w.dungeon === null || (typeof w.dungeon === "object" && typeof w.dungeon.poiId === "string" && okNum(w.dungeon.floor)))
  );
}

function errText(e: unknown): Txt {
  const k = e instanceof Error ? e.message : String(e);
  return ERRORS[k] ?? { ru: `Ошибка: ${k}`, en: `Error: ${k}` };
}

export class CoopLink {
  role: "host" | "guest" | null = null;
  status: CoopStatus = "idle";
  /** Наш код для отправки другу (приглашение или ответ). */
  code = "";
  link = "";
  error: Txt | null = null;
  partnerName = "";
  /** Гость: сведения о мире хоста из приглашения. */
  invite: SignalPayload | null = null;
  peer: Peer | null = null;
  host: HostBridge | null = null;
  guest: GuestBridge | null = null;
  welcome: WelcomeMsg | null = null;
  private connectT: ReturnType<typeof setTimeout> | null = null;
  private relay: BroadcastChannel | null = null;
  /** Гость: вызывается, когда хост прислал приветствие и можно входить в мир. */
  onWelcome: ((w: WelcomeMsg) => void) | null = null;

  constructor() {
    makeAutoObservable(this, { peer: false, host: false, guest: false, welcome: false, onWelcome: false });
  }

  /** Хост: ждём ответ, открытый по ссылке в другой вкладке этого же браузера. */
  private listenRelay() {
    this.stopRelay();
    if (typeof BroadcastChannel === "undefined") return;
    const ch = new BroadcastChannel(RELAY_CHANNEL);
    ch.onmessage = (ev) => {
      const m = ev.data as { t?: string; code?: string };
      if (m?.t === "answer" && typeof m.code === "string" && this.status === "invite") {
        ch.postMessage({ t: "ack" });
        void this.applyAnswer(m.code);
      }
    };
    this.relay = ch;
  }

  private stopRelay() {
    this.relay?.close();
    this.relay = null;
  }

  get active() {
    return this.status === "connected";
  }

  private fail(e: unknown) {
    this.status = "error";
    this.error = errText(e);
    this.peer?.close();
    this.peer = null;
  }

  private armTimeout() {
    if (this.connectT) clearTimeout(this.connectT);
    this.connectT = setTimeout(() => {
      runInAction(() => {
        if (this.status === "connecting") this.fail(new Error("timeout"));
      });
    }, 30000);
  }

  // ───────────── хост ─────────────

  async startHost(s: GameSession, useStun: boolean) {
    this.reset();
    this.role = "host";
    this.status = "preparing";
    try {
      if (typeof RTCPeerConnection === "undefined") throw new Error("no-webrtc");
      const peer = new Peer(useStun);
      this.peer = peer;
      const host = new HostBridge(peer, {
        onPartner: (name) =>
          runInAction(() => {
            this.partnerName = name;
            this.status = "connected";
            if (this.connectT) clearTimeout(this.connectT);
          }),
        onClosed: () => runInAction(() => this.onClosed()),
      });
      this.host = host;
      host.attach(s);
      const d = s.char.data;
      const code = await peer.createOffer({ v: PROTOCOL_VERSION, name: d.name, host: { level: d.level, classId: d.classId, mode: s.gen.mode, seed: s.gen.seed } });
      if (this.peer !== peer) return; // пока готовили код, приглашение отменили
      runInAction(() => {
        this.code = code;
        this.link = inviteLink(code);
        this.status = "invite";
      });
      this.listenRelay();
    } catch (e) {
      // Ошибка устаревшей попытки (её уже отменили) не должна ломать новую
      runInAction(() => {
        if (this.status === "preparing") this.fail(e);
      });
    }
  }

  async applyAnswer(text: string) {
    const peer = this.peer;
    if (!peer || this.role !== "host") return;
    try {
      const p = await peer.acceptAnswer(text);
      if (this.peer !== peer) return;
      this.stopRelay();
      runInAction(() => {
        this.partnerName = p.name;
        this.status = "connecting";
        this.error = null;
      });
      this.armTimeout();
    } catch (e) {
      if (this.peer !== peer) return;
      runInAction(() => {
        this.error = errText(e);
      });
    }
  }

  // ───────────── гость ─────────────

  async readInvite(text: string): Promise<boolean> {
    try {
      const { kind, payload } = await decodeSignal(text);
      if (kind !== "offer") throw new Error("not-offer");
      if (payload.v !== PROTOCOL_VERSION) throw new Error("version");
      runInAction(() => {
        this.invite = payload;
        this.error = null;
      });
      return true;
    } catch (e) {
      runInAction(() => {
        this.invite = null;
        this.error = errText(e);
      });
      return false;
    }
  }

  async startGuest(char: CharacterStore, useStun: boolean) {
    const inv = this.invite;
    if (!inv) return;
    this.role = "guest";
    this.status = "preparing";
    this.error = null;
    try {
      if (typeof RTCPeerConnection === "undefined") throw new Error("no-webrtc");
      const peer = new Peer(useStun);
      this.peer = peer;
      this.partnerName = inv.name;
      peer.onOpen = () => {
        runInAction(() => (this.status = "connecting"));
        const d = char.data;
        peer.send({ t: "hello", v: PROTOCOL_VERSION, name: d.name, classId: d.classId, look: char.gearLook, level: d.level, stats: packStats(char.stats) });
      };
      peer.onClose = () => runInAction(() => this.onClosed());
      // До приветствия слушаем только его
      peer.onMessage = (m) => {
        const msg = m as HostMsg;
        if (msg && msg.t === "welcome") {
          if (!validWelcome(msg) || this.welcome) return;
          runInAction(() => {
            this.welcome = msg;
            this.guest = new GuestBridge(peer, msg, {
              onPartner: () => undefined,
              onClosed: () => runInAction(() => this.onClosed()),
            });
            this.status = "connected";
            if (this.connectT) clearTimeout(this.connectT);
          });
          this.onWelcome?.(msg);
        } else if (msg && msg.t === "toast") {
          runInAction(() => (this.error = msg.text));
        }
      };
      const code = await peer.acceptOffer(inv, { v: PROTOCOL_VERSION, name: char.data.name });
      if (this.peer !== peer) return;
      runInAction(() => {
        this.code = code;
        this.link = answerLink(code);
        this.status = "answer";
      });
    } catch (e) {
      // Ошибка устаревшей попытки (её уже отменили) не должна ломать новую
      runInAction(() => {
        if (this.status === "preparing") this.fail(e);
      });
    }
  }

  /** Гость: подключить мост к созданной сессии. */
  attach(s: GameSession) {
    if (this.guest) this.guest.attach(s);
  }

  private onClosed() {
    this.stopRelay();
    if (this.connectT) clearTimeout(this.connectT);
    if (this.status === "error") return;
    this.status = "closed";
    this.host = null;
    this.guest = null;
    this.peer = null;
  }

  reset() {
    this.close();
    this.role = null;
    this.status = "idle";
    this.code = "";
    this.link = "";
    this.error = null;
    this.partnerName = "";
    this.invite = null;
    this.welcome = null;
  }

  close() {
    if (this.connectT) clearTimeout(this.connectT);
    this.stopRelay();
    this.host?.close();
    this.guest?.close();
    this.peer?.close();
    this.host = null;
    this.guest = null;
    this.peer = null;
    if (this.status !== "idle") this.status = "closed";
  }
}
