/** Применение улучшений к навыку и сбор пассивок персонажа. */
import type { Element } from "../types";
import type { KeystoneId, OnHit, Passive, SkillDef, SkillMod, SkillNode } from "./types";
import type { SkillTree } from "./generator";

export function cloneSkill(s: SkillDef): SkillDef {
  return {
    ...s,
    params: { ...s.params },
    onHit: s.onHit.map((h) => ({ ...h })) as OnHit[],
    echo: s.echo ? { ...s.echo } : null,
    ground: s.ground ? { ...s.ground } : null,
    visual: { ...s.visual },
    buff: s.buff?.map((b) => ({ ...b })),
    summon: s.summon ? { ...s.summon } : undefined,
  };
}

function mergeHit(list: OnHit[], h: OnHit) {
  const same = list.find((x) => x.k === h.k && (x.k !== "dot" || (x as { el: Element }).el === (h as { el: Element }).el));
  if (!same) {
    list.push({ ...h } as OnHit);
    return;
  }
  switch (h.k) {
    case "dot":
      (same as typeof h).dps += h.dps;
      (same as typeof h).dur = Math.max((same as typeof h).dur, h.dur);
      break;
    case "slow":
      (same as typeof h).pct = Math.min(0.75, Math.max((same as typeof h).pct, h.pct) + 0.05);
      break;
    case "stun":
    case "freeze":
    case "fear":
    case "charm":
      (same as typeof h).dur = Math.max((same as typeof h).dur, h.dur) + 0.2;
      break;
    case "explode":
      (same as typeof h).power += h.power;
      (same as typeof h).radius = Math.max((same as typeof h).radius, h.radius);
      break;
    case "split":
    case "chain":
      (same as typeof h).count += h.count;
      break;
    case "lifesteal":
    case "manaLeech":
    case "execute":
      (same as typeof h).pct += h.pct;
      break;
    case "weaken":
    case "vulnerable":
    case "blind":
      (same as typeof h).pct += h.pct * 0.7;
      break;
    case "knockback":
    case "pull":
      (same as typeof h).force += h.force;
      break;
  }
}

/** Навык с учётом всех модификаторов. */
export function applyMods(def: SkillDef, mods: SkillMod[]): SkillDef {
  const s = cloneSkill(def);
  const p = s.params;
  let powerPct = 0,
    radiusPct = 0,
    cdPct = 0,
    costPct = 0,
    durPct = 0,
    speedPct = 0,
    rangePct = 0,
    spreadPct = 0;
  for (const m of mods) {
    switch (m.m) {
      case "power":
        powerPct += m.pct;
        break;
      case "radius":
        radiusPct += m.pct;
        break;
      case "count":
        p.count += m.add;
        break;
      case "pierce":
        p.pierce += m.add;
        break;
      case "bounce":
        p.bounce += m.add;
        break;
      case "cooldown":
        cdPct += m.pct;
        break;
      case "cost":
        costPct += m.pct;
        break;
      case "duration":
        durPct += m.pct;
        break;
      case "speed":
        speedPct += m.pct;
        break;
      case "range":
        rangePct += m.pct;
        break;
      case "crit":
        p.crit += m.pct;
        break;
      case "spread":
        spreadPct += m.pct;
        break;
      case "knock":
        p.knock += m.add;
        break;
      case "onHit":
        mergeHit(s.onHit, m.hit);
        break;
      case "homing":
        s.homing = true;
        break;
      case "returning":
        s.returning = true;
        break;
      case "echo":
        s.echo = s.echo ? { delay: s.echo.delay, pct: s.echo.pct + m.pct } : { ...m };
        break;
      case "element":
        s.element = m.el;
        break;
      case "ground":
        s.ground = s.ground ? { dps: s.ground.dps + m.dps, dur: Math.max(s.ground.dur, m.dur), radius: Math.max(s.ground.radius, m.radius) } : { ...m };
        break;
    }
  }
  p.power *= 1 + powerPct;
  p.radius *= 1 + radiusPct;
  p.cooldown *= Math.max(0.3, 1 + cdPct);
  p.cost *= Math.max(0.2, 1 + costPct);
  p.duration *= 1 + durPct;
  p.speed *= 1 + speedPct;
  p.range *= 1 + rangePct;
  p.spread *= 1 + spreadPct;
  if (s.delivery === "projectile" && p.count > 1 && p.spread < 0.12 * p.count) p.spread = 0.12 * p.count;
  return s;
}

export interface LearnedSummary {
  actives: SkillNode[];
  passives: Passive[];
  keystones: Map<KeystoneId, number>;
  modsBySkill: Map<string, SkillMod[]>;
}

export function summarizeLearned(tree: SkillTree, learned: Iterable<string>): LearnedSummary {
  const actives: SkillNode[] = [];
  const passives: Passive[] = [];
  const keystones = new Map<KeystoneId, number>();
  const modsBySkill = new Map<string, SkillMod[]>();
  for (const id of learned) {
    const n = tree.get(id);
    if (!n) continue;
    switch (n.kind) {
      case "active":
        actives.push(n);
        break;
      case "upgrade": {
        const list = modsBySkill.get(n.target!) ?? [];
        list.push(...(n.mods ?? []));
        modsBySkill.set(n.target!, list);
        break;
      }
      case "passive":
      case "root":
        passives.push(...(n.passives ?? []));
        break;
      case "keystone":
        keystones.set(n.keystone!, (keystones.get(n.keystone!) ?? 0) + 1);
        break;
    }
  }
  return { actives, passives, keystones, modsBySkill };
}
