export interface PropRule {
  kind: PropKind;
  weight: number;
  /** Разброс масштаба. */
  scale: [number, number];
  /** Оттенки листвы/материала (случайный выбор). */
  tints?: number[];
}

export interface Biome {
  id: BiomeId;
  name: Txt;
  /** Цвет травы/почвы на равнине и на высоте, цвет склонов. */
  ground: number;
  groundAlt: number;
  slope: number;
  /** Цвет у воды (песок/грязь). */
  shore: number;
  /** Множитель рельефа и смещение высоты. */
  relief: number;
  lift: number;
  /** Плотность пропов (0..1) и правила. */
  density: number;
  props: PropRule[];
  /** Оттенок тумана/неба. */
  fog: number;
  /** Цвет воды. */
  water: number;
  /** Семейства врагов, обитающих здесь. */
  families: string[];
  /** Настроение музыки. */
  mood: "calm" | "bright" | "mystic" | "dark" | "epic" | "cold" | "hot";
}

