/** Рендер подземелья: пол и стены одним мешем, декор и сундуки — вторым (перестраивается при изменениях). */
import { hexToRgb, lerp } from "../core/math";
import { hash2, toUnit } from "../core/rng";
import { Dungeon, TILE, Tile } from "../game/dungeon/dungeon";
import { boxGeo, coneGeo, cylinderGeo, icoGeo, MeshBuilder, sphereGeo, torusGeo, xf } from "./geometry";
import { ATTR, GpuMesh, type GL, VERTEX_STRIDE, type PackedGeometry } from "./gl";
import { MAT } from "./materials";
import type { DungeonTheme } from "../game/world/worldgen";
import type { Renderer, RenderPass } from "./renderer";

const WALL_H = 2.8;

/** Материалы пола и стен по стилю подземелья. */
const THEME_MATS: Record<DungeonTheme, [number, number]> = {
  box: [MAT.planks, MAT.thatch],
  cave: [MAT.dirt, MAT.rock],
  crypt: [MAT.cobble, MAT.bricks],
  pyramid: [MAT.bricks, MAT.bricks],
  ice: [MAT.crystal, MAT.crystal],
  forge: [MAT.ash, MAT.bricks],
  crystal: [MAT.crystal, MAT.rock],
  factory: [MAT.metal, MAT.metal],
  rift: [MAT.ash, MAT.crystal],
};

export class DungeonRenderer implements RenderPass {
  private base: GpuMesh | null = null;
  private deco: GpuMesh | null = null;
  private builtVersion = -1;
  dungeon: Dungeon | null = null;

  constructor(readonly gl: GL) {}

  setDungeon(d: Dungeon | null) {
    this.base?.dispose();
    this.deco?.dispose();
    this.base = this.deco = null;
    this.dungeon = d;
    this.builtVersion = -1;
    if (d) this.base = new GpuMesh(this.gl, this.buildBase(d));
  }

  private buildBase(d: Dungeon): PackedGeometry {
    const pos: number[] = [];
    const nrm: number[] = [];
    const col: number[] = [];
    const misc: number[] = [];
    const idx: number[] = [];
    const st = d.style;
    const f1 = hexToRgb(st.floor),
      f2 = hexToRgb(st.floor2),
      wc = hexToRgb(st.wall),
      wt = hexToRgb(st.wallTop);
    const quad = (p: number[][], n: number[], c: number[][], ao: number[], em = 0) => {
      const b = pos.length / 3;
      for (let i = 0; i < 4; i++) {
        pos.push(p[i][0], p[i][1], p[i][2]);
        nrm.push(n[0], n[1], n[2]);
        col.push(c[i][0], c[i][1], c[i][2]);
        misc.push(ao[i], em);
      }
      idx.push(b, b + 1, b + 2, b, b + 2, b + 3);
    };
    const W = d.W,
      H = d.H;
    const wallAdj = (tx: number, ty: number) => {
      let n = 0;
      for (const [dx, dy] of [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ])
        if (d.at(tx + dx, ty + dy) === Tile.Wall) n++;
      return n;
    };
    for (let ty = 0; ty < H; ty++)
      for (let tx = 0; tx < W; tx++) {
        const t = d.at(tx, ty);
        const x0 = tx * TILE,
          z0 = ty * TILE;
        if (t !== Tile.Wall) {
          const k = toUnit(hash2(tx, ty, 77));
          const checker = (tx + ty) % 2 === 0 ? 0 : 1;
          const c = [lerp(f1[0], f2[0], checker * 0.6 + k * 0.4), lerp(f1[1], f2[1], checker * 0.6 + k * 0.4), lerp(f1[2], f2[2], checker * 0.6 + k * 0.4)];
          const aoEdge = wallAdj(tx, ty) > 0 ? 0.7 : 1;
          const cs = [c, c, c, c];
          if (t === Tile.Stairs) {
            // Лестница вниз: тёмная яма со ступенями
            for (let s = 0; s < 4; s++) {
              const y = -0.35 * (s + 1);
              const zs = z0 + (s / 4) * TILE,
                ze = z0 + ((s + 1) / 4) * TILE;
              const sc = [c[0] * (0.7 - s * 0.12), c[1] * (0.7 - s * 0.12), c[2] * (0.7 - s * 0.12)];
              quad([[x0, y, zs], [x0, y, ze], [x0 + TILE, y, ze], [x0 + TILE, y, zs]], [0, 1, 0], [sc, sc, sc, sc], [1, 1, 1, 1]);
            }
            continue;
          }
          quad([[x0, 0, z0], [x0, 0, z0 + TILE], [x0 + TILE, 0, z0 + TILE], [x0 + TILE, 0, z0]], [0, 1, 0], cs, [aoEdge, aoEdge, aoEdge, aoEdge]);
          continue;
        }
        // Стена, если рядом есть пол
        let near = false;
        for (let dy = -1; dy <= 1 && !near; dy++) for (let dx = -1; dx <= 1; dx++) if (d.at(tx + dx, ty + dy) !== Tile.Wall) near = true;
        if (!near) continue;
        const h = WALL_H * (0.9 + toUnit(hash2(tx, ty, 5)) * 0.2);
        const tc = [wt[0] * 0.9, wt[1] * 0.9, wt[2] * 0.9];
        quad([[x0, h, z0], [x0, h, z0 + TILE], [x0 + TILE, h, z0 + TILE], [x0 + TILE, h, z0]], [0, 1, 0], [tc, tc, tc, tc], [1, 1, 1, 1]);
        const bot = [wc[0] * 0.55, wc[1] * 0.55, wc[2] * 0.55];
        const topc = wc;
        const sides: [number, number, number[][], number[]][] = [
          [1, 0, [[x0 + TILE, 0, z0], [x0 + TILE, h, z0], [x0 + TILE, h, z0 + TILE], [x0 + TILE, 0, z0 + TILE]], [1, 0, 0]],
          [-1, 0, [[x0, 0, z0 + TILE], [x0, h, z0 + TILE], [x0, h, z0], [x0, 0, z0]], [-1, 0, 0]],
          [0, 1, [[x0 + TILE, 0, z0 + TILE], [x0 + TILE, h, z0 + TILE], [x0, h, z0 + TILE], [x0, 0, z0 + TILE]], [0, 0, 1]],
          [0, -1, [[x0, 0, z0], [x0, h, z0], [x0 + TILE, h, z0], [x0 + TILE, 0, z0]], [0, 0, -1]],
        ];
        for (const [dx, dy, pts, n] of sides) {
          if (d.at(tx + dx, ty + dy) === Tile.Wall) continue;
          const brick = toUnit(hash2(tx * 3 + dx, ty * 3 + dy, 11)) * 0.12;
          const tcc = [topc[0] * (0.95 - brick), topc[1] * (0.95 - brick), topc[2] * (0.95 - brick)];
          quad(pts, n, [bot, tcc, tcc, bot], [0.7, 1, 1, 0.7]);
        }
      }
    // Упаковка
    const nv = pos.length / 3;
    const buf = new ArrayBuffer(nv * VERTEX_STRIDE);
    const f = new Float32Array(buf),
      i8 = new Int8Array(buf),
      u8 = new Uint8Array(buf);
    for (let i = 0; i < nv; i++) {
      const o = i * VERTEX_STRIDE;
      f[o / 4] = pos[i * 3];
      f[o / 4 + 1] = pos[i * 3 + 1];
      f[o / 4 + 2] = pos[i * 3 + 2];
      i8[o + 12] = Math.round(nrm[i * 3] * 127);
      i8[o + 13] = Math.round(nrm[i * 3 + 1] * 127);
      i8[o + 14] = Math.round(nrm[i * 3 + 2] * 127);
      u8[o + 16] = Math.round(col[i * 3] * 255);
      u8[o + 17] = Math.round(col[i * 3 + 1] * 255);
      u8[o + 18] = Math.round(col[i * 3 + 2] * 255);
      u8[o + 19] = 255;
      u8[o + 20] = Math.round(misc[i * 2] * 255);
      u8[o + 21] = Math.round(misc[i * 2 + 1] * 255);
    }
    return { vertexData: buf, vertexCount: nv, indices: nv > 65535 ? new Uint32Array(idx) : new Uint16Array(idx) };
  }

  private buildDeco(d: Dungeon): PackedGeometry {
    const b = new MeshBuilder();
    const st = d.style;
    const BOX = boxGeo(),
      CYL = cylinderGeo(8, 1, 1),
      CONE = coneGeo(6),
      ICO = icoGeo(1),
      SPH = sphereGeo(8, 6),
      TOR = torusGeo(1, 0.15, 14, 5);
    for (const dc of d.decor) {
      const s = dc.s;
      switch (dc.kind) {
        case "pillar":
          b.add(CYL, xf(dc.x, 0, dc.z, 0.45 * s, WALL_H * 1.05, 0.45 * s), st.wallTop, { flat: true, mat: MAT.bricks });
          b.add(BOX, xf(dc.x, 0.15, dc.z, 1.1 * s, 0.3, 1.1 * s), st.wall, { flat: true, mat: MAT.rock });
          break;
        case "crate":
          b.add(BOX, xf(dc.x, 0.45 * s, dc.z, 0.9 * s, 0.9 * s, 0.9 * s, 0, s * 2), 0xa0703a, { flat: true, mat: MAT.planks });
          break;
        case "barrel":
          b.add(CYL, xf(dc.x, 0, dc.z, 0.42 * s, 1.0 * s, 0.42 * s), 0x8a5a2a, { flat: true, mat: MAT.planks });
          break;
        case "bones":
          for (let i = 0; i < 3; i++) b.add(CYL, xf(dc.x + i * 0.2 - 0.2, 0.06, dc.z, 0.04, 0.7, 0.04, 0, i * 1.3, Math.PI / 2), 0xe8e0d0, {});
          b.add(SPH, xf(dc.x + 0.3, 0.14, dc.z + 0.2, 0.16, 0.13, 0.16), 0xe8e0d0, {});
          break;
        case "crystal":
          for (let i = 0; i < 3; i++) b.add(CONE, xf(dc.x + (i - 1) * 0.3, 0, dc.z + ((i * 7) % 3) * 0.2 - 0.2, 0.25 * s, (1.2 + i * 0.4) * s, 0.25 * s, (i - 1) * 0.2), st.accent, { flat: true, emissive: 0.8, mat: MAT.crystal });
          break;
        case "rubble":
          b.add(ICO, xf(dc.x, 0.2, dc.z, 0.5 * s, 0.35 * s, 0.45 * s), st.wall, { flat: true, jitter: 0.4, mat: MAT.rock });
          break;
      }
    }
    for (const t of d.torches) {
      b.add(CYL, xf(t.x, 1.3, t.z, 0.06, 0.6, 0.06, t.wz * 0.4, 0, -t.wx * 0.4), 0x4a3a2a, {});
      b.add(SPH, xf(t.x - t.wx * 0.12, 1.95, t.z - t.wz * 0.12, 0.16, 0.24, 0.16), st.torch, { emissive: 1 });
    }
    for (const c of d.chests) {
      if (c.opened) continue;
      b.add(BOX, xf(c.x, 0.35, c.z, 1.1, 0.7, 0.8), 0x8a5a2a, { flat: true, mat: MAT.planks });
      b.add(cylinderGeo(10, 0.4, 0.4), xf(c.x - 0.55, 0.7, c.z, 1, 1.1, 1, 0, 0, -Math.PI / 2), 0x9a6a32, { flat: true, mat: MAT.planks });
      b.add(BOX, xf(c.x, 0.6, c.z + 0.41, 0.2, 0.22, 0.06), 0xffe066, { emissive: 0.6 });
      for (const sx of [-0.38, 0.38]) b.add(BOX, xf(c.x + sx, 0.6, c.z, 0.1, 0.82, 0.84), 0xf2c84a, { mat: MAT.metal });
    }
    if (d.stairs) b.add(TOR, xf(d.stairs.x, 0.08, d.stairs.z, 1.3, 1.3, 1.3), st.accent, { emissive: 1 });
    if (d.exitPortal) {
      b.add(TOR, xf(d.exitPortal.x, 1.7, d.exitPortal.z, 1.4, 1.4, 1.4, Math.PI / 2), 0x8fd0ff, { emissive: 1 });
      b.add(cylinderGeo(18, 1.35, 1.35), xf(d.exitPortal.x, 1.7, d.exitPortal.z - 0.05, 1, 0.1, 1, Math.PI / 2), 0x2a4a8a, { emissive: 0.6 });
    }
    return b.pack();
  }

  private ensureDeco(d: Dungeon) {
    if (this.builtVersion !== d.version) {
      this.deco?.dispose();
      this.deco = new GpuMesh(this.gl, this.buildDeco(d));
      this.builtVersion = d.version;
    }
  }

  /** Декор рисуется программой пропов как один «инстанс» в начале координат подземелья. */
  private decoInstance(r: Renderer) {
    const gl = this.gl;
    gl.vertexAttrib4f(ATTR.i0, -r.camera.ox, 0, -r.camera.oz, 0);
    gl.vertexAttrib4f(ATTR.i1, 1, 1, 1, 1);
  }

  shadow(r: Renderer) {
    const d = this.dungeon;
    if (!d || !this.base) return;
    this.ensureDeco(d);
    const gl = this.gl;
    const cam = r.camera;
    r.progTerrainDepth.use();
    r.progTerrainDepth.f3("uOffset", -cam.ox, 0, -cam.oz);
    gl.disable(gl.CULL_FACE);
    this.base.draw();
    if (this.deco) {
      r.progPropDepth.use();
      this.decoInstance(r);
      this.deco.draw();
    }
    gl.bindVertexArray(null);
  }

  opaque(r: Renderer) {
    const d = this.dungeon;
    if (!d || !this.base) return;
    this.ensureDeco(d);
    const gl = this.gl;
    const cam = r.camera;
    const [floorMat, wallMat] = THEME_MATS[d.theme] ?? [MAT.rock, MAT.rock];
    r.progTerrain.use();
    r.progTerrain.f1("uDetail", 1);
    r.progTerrain.f3("uOffset", -cam.ox, 0, -cam.oz);
    r.progTerrain.f4("uMats", floorMat, floorMat, floorMat, floorMat);
    r.progTerrain.f1("uSlopeMat", wallMat);
    gl.disable(gl.CULL_FACE);
    this.base.draw();
    if (this.deco) {
      r.progProp.use();
      this.decoInstance(r);
      this.deco.draw();
    }
    gl.enable(gl.CULL_FACE);
    gl.bindVertexArray(null);
  }
}
