/**
 * Локализация: русский (по умолчанию) и английский.
 * Генераторы контента возвращают пары {ru, en}; язык выбирается только при показе,
 * поэтому смена языка мгновенно перерисовывает весь интерфейс (MobX).
 */
import { observable, runInAction } from "mobx";

export type Lang = "ru" | "en";
export interface Txt {
  ru: string;
  en: string;
}

const langBox = observable.box<Lang>("ru");

export function getLang(): Lang {
  return langBox.get();
}
export function setLang(l: Lang) {
  runInAction(() => langBox.set(l));
}

export const txt = (ru: string, en: string): Txt => ({ ru, en });

/** Перевести пару строк на текущий язык (реактивно). */
export function tr(t: Txt | string | undefined | null): string {
  if (t == null) return "";
  if (typeof t === "string") return t;
  return t[langBox.get()] ?? t.ru;
}

/** Подстановка {name} в шаблон. */
export function fmt(template: string, vars: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? String(vars[k]) : `{${k}}`));
}

/** Перевести и подставить. */
export function trf(t: Txt, vars: Record<string, string | number>): Txt {
  return { ru: fmt(t.ru, vars), en: fmt(t.en, vars) };
}

/** Склеить несколько пар. */
export function join(parts: (Txt | string)[], sep: Txt | string = " "): Txt {
  const s = typeof sep === "string" ? { ru: sep, en: sep } : sep;
  const ru = parts.map((p) => (typeof p === "string" ? p : p.ru)).join(s.ru);
  const en = parts.map((p) => (typeof p === "string" ? p : p.en)).join(s.en);
  return { ru, en };
}

/** Русское склонение числительных: 1 рыбка, 2 рыбки, 5 рыбок. */
export function pluralRu(n: number, one: string, few: string, many: string): string {
  const a = Math.abs(n) % 100;
  const b = a % 10;
  if (a > 10 && a < 20) return many;
  if (b > 1 && b < 5) return few;
  if (b === 1) return one;
  return many;
}

/** Грамматический род для согласования прилагательных. */
export type Gender = "m" | "f" | "n" | "p";

/** Прилагательное в 4 формах (м/ж/ср/мн) + английская форма. */
export interface Adj {
  m: string;
  f: string;
  n: string;
  p: string;
  en: string;
}
/** Существительное с родом. */
export interface Noun {
  ru: string;
  g: Gender;
  en: string;
}

export function adjNoun(a: Adj, n: Noun): Txt {
  return { ru: `${a[n.g]} ${n.ru}`, en: `${a.en} ${n.en}` };
}

/**
 * Упрощённое построение прилагательного из основы: "Огненн" → ый/ая/ое/ые.
 * type: "hard" (-ый), "soft" (-ий, синий), "stress" (-ой, золотой), "gk" (г/к/х: -ий/-ая)
 */
export function adj(stem: string, en: string, type: "hard" | "soft" | "stress" | "gk" = "hard"): Adj {
  switch (type) {
    case "soft":
      return { m: stem + "ий", f: stem + "яя", n: stem + "ее", p: stem + "ие", en };
    case "stress":
      return { m: stem + "ой", f: stem + "ая", n: stem + "ое", p: stem + "ые", en };
    case "gk":
      return { m: stem + "ий", f: stem + "ая", n: stem + "ое", p: stem + "ие", en };
    default:
      return { m: stem + "ый", f: stem + "ая", n: stem + "ое", p: stem + "ые", en };
  }
}
export const noun = (ru: string, g: Gender, en: string): Noun => ({ ru, g, en });
