/**
 * Проверка данных от напарника. Кооператив дружеский, но кривое или злонамеренное
 * сообщение не должно ронять или вешать игру: только конечные числа в разумных
 * пределах, короткие строки, ограниченные массивы, без «__proto__».
 */
import type { Txt } from "../core/i18n";
import { BASE_LOOK, classLook, type CatLook } from "../game/cats/look";
import type { MirrorInfo } from "../game/sim/world";
import type { GameEvent } from "../game/sim/types";
import { DELIVERIES, type SkillDef } from "../game/skills/types";
import type { Stats } from "../game/stats";
import { CLASS_IDS, ELEMENTS, type ClassId, type Element } from "../game/types";
import type { WireStats } from "./protocol";

const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

/** Глубокая очистка JSON: конечные числа, короткие строки, массивы до 64, глубина до 6. */
export function cleanJson(v: unknown, depth = 0): unknown {
  if (depth > 6) return undefined;
  if (typeof v === "number") return Number.isFinite(v) ? Math.max(-1e12, Math.min(1e12, v)) : 0;
  if (typeof v === "string") return v.slice(0, 200);
  if (typeof v === "boolean" || v === null) return v;
  if (Array.isArray(v)) return v.slice(0, 64).map((x) => cleanJson(x, depth + 1));
  if (typeof v === "object") {
    const out: Record<string, unknown> = {};
    let n = 0;
    for (const k of Object.keys(v as object)) {
      if (FORBIDDEN.has(k) || ++n > 48) continue;
      out[k] = cleanJson((v as Record<string, unknown>)[k], depth + 1);
    }
    return out;
  }
  return undefined;
}

export const fin = (v: unknown, lo: number, hi: number, def: number): number => (typeof v === "number" && Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : def);
export const str = (v: unknown, max: number, def = ""): string => (typeof v === "string" ? v.slice(0, max) : def);
export const txt = (v: unknown, max = 80): Txt => {
  const o = (v && typeof v === "object" ? v : {}) as Record<string, unknown>;
  return { ru: str(o.ru, max, "?"), en: str(o.en, max, "?") };
};
const obj = (v: unknown): Record<string, unknown> | null => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : null);

const DELIV = new Set<string>(DELIVERIES);
const ELEM = new Set<string>(ELEMENTS);
const CLASSES = new Set<string>(CLASS_IDS);

/** Навык от напарника: пределы с запасом (самые «раскачанные» навыки бесконечного дерева в них укладываются). */
export function sanitizeSkill(raw: unknown): SkillDef | null {
  const s = obj(cleanJson(raw)) as unknown as SkillDef | null;
  if (!s || typeof s.id !== "string" || !DELIV.has(s.delivery) || !ELEM.has(s.element)) return null;
  const p = obj(s.params);
  if (!p || !obj(s.visual)) return null;
  s.params = {
    power: fin(p.power, 0, 1000, 1),
    radius: fin(p.radius, 0, 120, 2),
    range: fin(p.range, 0, 120, 8),
    count: Math.round(fin(p.count, 0, 64, 1)),
    speed: fin(p.speed, 1, 200, 20),
    duration: fin(p.duration, 0, 600, 3),
    tick: fin(p.tick, 0.05, 10, 0.5),
    pierce: Math.round(fin(p.pierce, 0, 200, 0)),
    bounce: Math.round(fin(p.bounce, 0, 50, 0)),
    spread: fin(p.spread, 0, 20, 0.5),
    cooldown: fin(p.cooldown, 0, 600, 1),
    cost: fin(p.cost, 0, 1e9, 0),
    castTime: fin(p.castTime, 0, 5, 0.2),
    knock: fin(p.knock, 0, 50, 0),
    crit: fin(p.crit, 0, 10, 0),
  };
  s.onHit = (Array.isArray(s.onHit) ? s.onHit : [])
    .slice(0, 12)
    .map((h) => obj(h))
    .filter((h): h is Record<string, unknown> => !!h && typeof h.k === "string")
    .map((h) => {
      const o: Record<string, unknown> = { ...h };
      for (const k of Object.keys(o)) {
        if (typeof o[k] !== "number") continue;
        const v = o[k] as number;
        o[k] = k === "count" ? Math.round(fin(v, 0, 12, 1)) : k === "radius" ? fin(v, 0, 30, 2) : k === "dur" ? fin(v, 0, 30, 1) : fin(v, -100, 1000, 0);
      }
      return o;
    }) as unknown as SkillDef["onHit"];
  const e = obj(s.echo);
  s.echo = e ? { delay: fin(e.delay, 0.05, 5, 0.4), pct: fin(e.pct, 0, 2, 0.5) } : null;
  const g = obj(s.ground);
  s.ground = g ? { dps: fin(g.dps, 0, 1e6, 0), dur: fin(g.dur, 0, 60, 3), radius: fin(g.radius, 0, 30, 2) } : null;
  if (s.buff !== undefined) s.buff = Array.isArray(s.buff) ? s.buff.slice(0, 6) : undefined;
  s.homing = !!s.homing;
  s.returning = !!s.returning;
  s.melee = !!s.melee;
  if (typeof s.anim !== "string") s.anim = "swipe";
  if (!s.name || typeof s.name !== "object") s.name = { ru: "?", en: "?" };
  return s;
}

/** Типы полей внешности (в том числе необязательных). */
const LOOK_TYPES: Record<string, "num" | "scale" | "str" | "bool" | "alpha"> = {
  fur: "num",
  fur2: "num",
  pattern: "str",
  eyes: "num",
  size: "scale",
  bulk: "scale",
  legLen: "scale",
  earSize: "scale",
  tailLen: "scale",
  tailFluff: "scale",
  headSize: "scale",
  mane: "num",
  tufts: "bool",
  hat: "str",
  hatColor: "num",
  weapon: "str",
  weaponColor: "num",
  offhand: "str",
  collar: "num",
  bell: "bool",
  glow: "num",
  alpha: "alpha",
  cape: "num",
  hairless: "bool",
};

/** Внешность: берём за основу корректную и переносим только поля известных типов. */
export function sanitizeLook(raw: unknown, classId: ClassId | null): CatLook {
  const base: CatLook = classId ? classLook(classId) : { ...BASE_LOOK };
  const src = obj(cleanJson(raw));
  if (!src) return base;
  const out = { ...base } as unknown as Record<string, unknown>;
  for (const [k, kind] of Object.entries(LOOK_TYPES)) {
    const v = src[k];
    if (v === undefined) continue;
    if (kind === "scale" && typeof v === "number") out[k] = fin(v, 0.3, 3, 1);
    else if (kind === "alpha" && typeof v === "number") out[k] = fin(v, 0.2, 1, 1);
    else if (kind === "num" && typeof v === "number") out[k] = Math.round(fin(v, 0, 0xffffff, 0));
    else if (kind === "str" && typeof v === "string") out[k] = v.slice(0, 24);
    else if (kind === "bool" && typeof v === "boolean") out[k] = v;
  }
  return out as unknown as CatLook;
}

export function sanitizeClass(v: unknown): ClassId {
  return typeof v === "string" && CLASSES.has(v) ? (v as ClassId) : "warrior";
}

/** Характеристики: все числа конечные и неотрицательные. */
export function sanitizeStats(raw: unknown): WireStats | null {
  const s = obj(cleanJson(raw));
  if (!s) return null;
  const num = (v: unknown, def = 0) => fin(v, 0, 1e15, def);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(s)) {
    if (typeof v === "number") out[k] = num(v);
    else if (k === "keystones") out[k] = Array.isArray(v) ? v.filter((e) => Array.isArray(e) && typeof e[0] === "string" && typeof e[1] === "number").slice(0, 32) : [];
    else if (obj(v)) out[k] = Object.fromEntries(Object.entries(obj(v)!).map(([kk, vv]) => [kk, num(vv)]));
  }
  out.maxHp = num(out.maxHp, 100) || 100;
  out.maxMp = num(out.maxMp, 50);
  out.level = Math.max(1, Math.round(num(out.level, 1)));
  if (!Array.isArray(out.keystones)) out.keystones = [];
  for (const k of ["elementPct", "deliveryPct", "onKill"]) if (!obj(out[k])) out[k] = {};
  return out as unknown as WireStats;
}

export function statsOk(st: Stats): boolean {
  return Number.isFinite(st.maxHp) && st.maxHp > 0 && Number.isFinite(st.moveSpeed);
}

/** Сущность хоста для зеркала у гостя. */
export function sanitizeMirror(raw: unknown): MirrorInfo | null {
  const m = obj(cleanJson(raw));
  if (!m || typeof m.id !== "number" || !["player", "enemy", "npc", "minion"].includes(m.kind as string)) return null;
  const e = obj(m.enemy);
  const n = obj(m.npc);
  const classId = typeof m.classId === "string" && CLASSES.has(m.classId) ? (m.classId as ClassId) : null;
  return {
    id: m.id,
    kind: m.kind as MirrorInfo["kind"],
    name: txt(m.name, 60),
    look: sanitizeLook(m.look, classId),
    x: fin(m.x, -1e7, 1e7, 0),
    z: fin(m.z, -1e7, 1e7, 0),
    yaw: fin(m.yaw, -100, 100, 0),
    level: Math.round(fin(m.level, 1, 1e6, 1)),
    hp: fin(m.hp, 0, 1e15, 1),
    maxHp: fin(m.maxHp, 1, 1e15, 1),
    alive: !!m.alive,
    radius: fin(m.radius, 0.1, 5, 0.55),
    faction: Math.round(fin(m.faction, 0, 3, 1)),
    classId,
    enemy: e ? { family: str(e.family, 32, "alley"), role: str(e.role, 24, "brute"), elite: !!e.elite, boss: !!e.boss, poiId: typeof e.poiId === "string" ? e.poiId.slice(0, 64) : undefined, named: e.named ? txt(e.named, 60) : undefined } : undefined,
    npc: n ? { role: str(n.role, 24, "villager"), npcId: str(n.npcId, 64), townId: str(n.townId, 64) } : undefined,
    minionOwner: typeof m.minionOwner === "number" ? m.minionOwner : undefined,
  };
}

/** События хоста: только нужные типы с конечными числами. */
export function sanitizeEvents(raw: unknown): GameEvent[] {
  if (!Array.isArray(raw)) return [];
  const out: GameEvent[] = [];
  for (const r of raw.slice(0, 400)) {
    const e = obj(cleanJson(r));
    if (!e) continue;
    const x = fin(e.x, -1e7, 1e7, 0),
      y = fin(e.y, -1e4, 1e4, 0),
      z = fin(e.z, -1e7, 1e7, 0);
    switch (e.t) {
      case "damage":
        out.push({ t: "damage", id: fin(e.id, -1, 1e12, -1), by: fin(e.by, -1, 1e12, -1), x, y, z, amount: fin(e.amount, 0, 1e15, 0), crit: !!e.crit, el: (ELEM.has(e.el as string) ? e.el : "physical") as Element, toPlayer: !!e.toPlayer, dot: !!e.dot });
        break;
      case "heal":
        out.push({ t: "heal", id: fin(e.id, -1, 1e12, -1), x, y, z, amount: fin(e.amount, 0, 1e15, 0), by: fin(e.by, -1, 1e12, -1), silent: !!e.silent });
        break;
      case "dodge":
        out.push({ t: "dodge", id: fin(e.id, -1, 1e12, -1), x, y, z });
        break;
      case "text":
        out.push({ t: "text", text: txt(e.text, 60), x, y, z, color: Math.round(fin(e.color, 0, 0xffffff, 0xffffff)) });
        break;
      case "death":
        out.push({
          t: "death",
          id: fin(e.id, -1, 1e12, -1),
          x,
          z,
          kind: (["enemy", "npc", "minion", "player"].includes(e.kind as string) ? e.kind : "enemy") as "enemy",
          killerId: fin(e.killerId, -1, 1e12, -1),
          level: Math.round(fin(e.level, 1, 1e6, 1)),
          family: typeof e.family === "string" ? e.family.slice(0, 32) : undefined,
          role: typeof e.role === "string" ? e.role.slice(0, 24) : undefined,
          boss: !!e.boss,
          elite: !!e.elite,
          poiId: typeof e.poiId === "string" ? e.poiId.slice(0, 64) : undefined,
        });
        break;
      default:
        break;
    }
  }
  return out;
}
