import type { CatLook } from "../game/cats/look";

/** Анимации действий (у каждого навыка — своя). */
export type CatAction =
  | "swipe"
  | "doubleSwipe"
  | "pounce"
  | "bite"
  | "spin"
  | "slam"
  | "raise"
  | "point"
  | "throw"
  | "roar"
  | "tailWhip"
  | "backflip"
  | "channel"
  | "stomp"
  | "dash"
  | "summon"
  | "pray"
  | "hiss"
  | "hit"
  | "jump"
  | "meow"
  | "wave"
  | "shoot"
  | "stab";

export const CAT_ACTIONS: CatAction[] = [
  "swipe",
  "doubleSwipe",
  "pounce",
  "bite",
  "spin",
  "slam",
  "raise",
  "point",
  "throw",
  "roar",
  "tailWhip",
  "backflip",
  "channel",
  "stomp",
  "dash",
  "summon",
  "pray",
  "hiss",
  "shoot",
  "stab",
];

export type CatState = "alive" | "dead" | "sit" | "loaf" | "sleep" | "swim" | "climb" | "perch";

/** Что нужно отрисовать для одной кошки в этом кадре. */
export interface CatInstance {
  id: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
  look: CatLook;
  speed: number;
  action: CatAction | null;
  actionT: number;
  state: CatState;
  stateT: number;
  flash: number;
  tint: number;
  tintAmt: number;
  alpha: number;
  scale: number;
  lookX?: number;
  lookZ?: number;
}

export function makeCatInstance(id: number, look: CatLook): CatInstance {
  return {
    id,
    x: 0,
    y: 0,
    z: 0,
    yaw: 0,
    look,
    speed: 0,
    action: null,
    actionT: 0,
    state: "alive",
    stateT: 0,
    flash: 0,
    tint: 0xffffff,
    tintAmt: 0,
    alpha: 1,
    scale: 1,
  };
}
