/** Состояние интерфейса: экраны, панели, диалоги. */
import { makeAutoObservable } from "mobx";
import type { Txt } from "../core/i18n";

export type Screen = "menu" | "newgame" | "load" | "settings" | "coop" | "game" | "about";
export type Panel = null | "inventory" | "skills" | "map" | "quests" | "character" | "menu" | "dialog" | "shop" | "travel" | "settings" | "coop" | "help";

export interface DialogState {
  npcEntityId: number;
  npcId: string;
  townId: string;
  name: Txt;
  role: string;
  greeting: Txt;
  /** Выбранный квест для просмотра. */
  questId: string | null;
}

export interface ConfirmState {
  text: Txt;
  ok: () => void;
  okLabel?: Txt;
}

export class UiStore {
  screen: Screen = "menu";
  panel: Panel = null;
  dialog: DialogState | null = null;
  confirm: ConfirmState | null = null;
  selectedSkill: string | null = null;
  selectedItem: string | null = null;
  lore: { title: Txt; text: Txt } | null = null;
  loadingText: Txt | null = null;
  toastMessage: Txt | null = null;

  constructor() {
    makeAutoObservable(this);
  }

  go(s: Screen) {
    this.screen = s;
    this.panel = null;
  }

  open(p: Panel) {
    this.panel = this.panel === p ? null : p;
    if (p !== "dialog") this.dialog = this.panel === "dialog" ? this.dialog : null;
  }

  close() {
    this.panel = null;
    this.dialog = null;
  }

  openDialog(d: DialogState) {
    this.dialog = d;
    this.panel = "dialog";
  }

  ask(c: ConfirmState) {
    this.confirm = c;
  }

  get modalOpen() {
    return this.panel !== null || this.confirm !== null || this.lore !== null;
  }
}
