import { observer } from "mobx-react-lite";
import { useEffect, useRef, useState } from "react";
import { tr } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn, Panel } from "../common";
import { BIOMES } from "../../game/world/biomes";
import { REGION, type WorldGen } from "../../game/world/worldgen";

interface MapImage {
  key: string;
  canvas: HTMLCanvasElement;
  x0: number;
  z0: number;
  size: number;
  res: number;
  done: boolean;
  row: number;
}

let cached: MapImage | null = null;

function ensureImage(gen: WorldGen, px: number, pz: number): MapImage {
  const infinite = gen.infinite;
  const size = infinite ? 9000 : 16400;
  const x0 = infinite ? Math.round(px / 1000) * 1000 - size / 2 : -size / 2;
  const z0 = infinite ? Math.round(pz / 1000) * 1000 - size / 2 : -size / 2;
  const key = `${gen.seed}|${infinite}|${x0}|${z0}`;
  if (cached && cached.key === key) return cached;
  const res = 220;
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = res;
  cached = { key, canvas, x0, z0, size, res, done: false, row: 0 };
  return cached;
}

/** Постепенно дорисовываем карту (чтобы не подвешивать кадр). */
function progress(img: MapImage, gen: WorldGen, budgetMs: number) {
  if (img.done) return;
  const ctx = img.canvas.getContext("2d")!;
  const t0 = performance.now();
  const step = img.size / img.res;
  while (img.row < img.res && performance.now() - t0 < budgetMs) {
    const j = img.row++;
    const data = ctx.createImageData(img.res, 1);
    for (let i = 0; i < img.res; i++) {
      const x = img.x0 + (i + 0.5) * step,
        z = img.z0 + (j + 0.5) * step;
      const h = gen.rawHeight(x, z);
      let c: number;
      if (h < 0) {
        const b = BIOMES[gen.biomeIdAt(x, z)];
        c = h < -12 ? 0x1f4a78 : b.water;
      } else {
        const b = BIOMES[gen.biomeIdAt(x, z)];
        c = h < 1.2 ? b.shore : h > 45 ? 0xeef2f6 : b.ground;
      }
      const shade = h > 0 ? Math.max(0.7, Math.min(1.15, 0.85 + h / 120)) : 1;
      data.data[i * 4] = Math.min(255, ((c >> 16) & 255) * shade);
      data.data[i * 4 + 1] = Math.min(255, ((c >> 8) & 255) * shade);
      data.data[i * 4 + 2] = Math.min(255, (c & 255) * shade);
      data.data[i * 4 + 3] = 255;
    }
    ctx.putImageData(data, 0, j);
  }
  if (img.row >= img.res) img.done = true;
}

export const WorldMapPanel = observer(() => {
  const s = useStore();
  const sess = s.session!;
  const c = s.char!;
  const ref = useRef<HTMLCanvasElement>(null);
  const [view, setView] = useState({ cx: sess.player.x, cz: sess.player.z, k: sess.gen.infinite ? 0.12 : 0.05 });
  const [selTown, setSelTown] = useState<{ id: string; name: { ru: string; en: string }; x: number; z: number; level: number; discovered: boolean } | null>(null);
  const ptrs = useRef(new Map<number, { x: number; y: number }>());
  const pinch = useRef<number | null>(null);
  const moved = useRef(0);
  const viewRef = useRef(view);
  viewRef.current = view;
  useEffect(() => {
    const canvas = ref.current!;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;
    const img = ensureImage(sess.gen, sess.player.x, sess.player.z);
    const draw = () => {
      raf = requestAnimationFrame(draw);
      progress(img, sess.gen, 10);
      const W = (canvas.width = canvas.clientWidth * devicePixelRatio);
      const H = (canvas.height = canvas.clientHeight * devicePixelRatio);
      const v = viewRef.current;
      const k = v.k * devicePixelRatio;
      const toS = (x: number, z: number) => [W / 2 + (x - v.cx) * k, H / 2 + (z - v.cz) * k];
      ctx.fillStyle = "#16304e";
      ctx.fillRect(0, 0, W, H);
      const [ix, iz] = toS(img.x0, img.z0);
      ctx.imageSmoothingEnabled = true;
      ctx.drawImage(img.canvas, ix, iz, img.size * k, img.size * k);
      // Регионы и города
      const rMin = Math.floor((v.cx - W / 2 / k) / REGION),
        rMax = Math.floor((v.cx + W / 2 / k) / REGION);
      const zMin = Math.floor((v.cz - H / 2 / k) / REGION),
        zMax = Math.floor((v.cz + H / 2 / k) / REGION);
      const disc = new Set(c.data.discovered);
      const showAll = (rMax - rMin) * (zMax - zMin) < 900;
      if (showAll) {
        for (let rz = zMin; rz <= zMax; rz++)
          for (let rx = rMin; rx <= rMax; rx++) {
            const reg = sess.gen.region(rx, rz);
            const t = reg.town;
            if (!t) continue;
            const [sx, sz] = toS(t.x, t.z);
            const known = disc.has(t.id);
            ctx.beginPath();
            ctx.arc(sx, sz, known ? 6 * devicePixelRatio : 3.5 * devicePixelRatio, 0, Math.PI * 2);
            ctx.fillStyle = known ? "#ffd27a" : "rgba(255,240,220,0.55)";
            ctx.fill();
            ctx.strokeStyle = "#2a1a0a";
            ctx.lineWidth = 1.5;
            ctx.stroke();
            if (k > 0.12 || known) {
              ctx.font = `${Math.round(11 * devicePixelRatio)}px sans-serif`;
              ctx.fillStyle = "#fff";
              ctx.textAlign = "center";
              ctx.strokeStyle = "rgba(0,0,0,0.6)";
              ctx.lineWidth = 3;
              const label = `${tr(t.name)} · ${reg.level}`;
              ctx.strokeText(label, sx, sz - 9 * devicePixelRatio);
              ctx.fillText(label, sx, sz - 9 * devicePixelRatio);
            }
            if (k > 0.1)
              for (const poi of reg.pois) {
                if (poi.kind !== "dungeon") continue;
                const [px, pz] = toS(poi.x, poi.z);
                ctx.fillStyle = c.data.cleared.includes(poi.id) ? "#7ee081" : "#c08aff";
                ctx.fillRect(px - 3 * devicePixelRatio, pz - 3 * devicePixelRatio, 6 * devicePixelRatio, 6 * devicePixelRatio);
              }
          }
      }
      // Сюжет и отслеживаемое задание
      const star = (x: number, z: number, color: string) => {
        const [sx, sz] = toS(x, z);
        ctx.font = `${Math.round(22 * devicePixelRatio)}px sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillStyle = color;
        ctx.strokeStyle = "#000";
        ctx.lineWidth = 3;
        ctx.strokeText("★", sx, sz);
        ctx.fillText("★", sx, sz);
      };
      const ch = sess.quests.storyChapterInfo();
      if (ch) star(ch.town.x, ch.town.z, "#ff9ac8");
      const tt = sess.quests.trackedTarget();
      if (tt) star(tt.x, tt.z, "#ffd24a");
      // Игрок
      const p = sess.player;
      const [px, pz] = toS(p.x, p.z);
      ctx.save();
      ctx.translate(px, pz);
      ctx.rotate(-p.yaw + Math.PI);
      ctx.beginPath();
      ctx.moveTo(0, -10 * devicePixelRatio);
      ctx.lineTo(7 * devicePixelRatio, 8 * devicePixelRatio);
      ctx.lineTo(-7 * devicePixelRatio, 8 * devicePixelRatio);
      ctx.closePath();
      ctx.fillStyle = "#fff";
      ctx.fill();
      ctx.strokeStyle = "#e8703a";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
      if (!img.done) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, H - 22 * devicePixelRatio, W, 22 * devicePixelRatio);
        ctx.fillStyle = "#fff";
        ctx.font = `${Math.round(12 * devicePixelRatio)}px sans-serif`;
        ctx.textAlign = "left";
        ctx.fillText(`${tr({ ru: "Рисуем карту", en: "Drawing map" })} ${Math.round((img.row / img.res) * 100)}%`, 8, H - 7 * devicePixelRatio);
      }
    };
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, [sess, c]);
  const pickTown = (clientX: number, clientY: number) => {
    const canvas = ref.current!;
    const r = canvas.getBoundingClientRect();
    const v = viewRef.current;
    const wx = v.cx + (clientX - r.left - r.width / 2) / v.k;
    const wz = v.cz + (clientY - r.top - r.height / 2) / v.k;
    const reg = sess.gen.regionAt(wx, wz);
    const t = reg.town;
    if (t && Math.hypot(t.x - wx, t.z - wz) < 14 / v.k + 20) setSelTown({ id: t.id, name: t.name, x: t.x, z: t.z, level: reg.level, discovered: c.data.discovered.includes(t.id) });
    else setSelTown(null);
  };
  return (
    <Panel title={{ ru: "Карта мира", en: "World map" }} onClose={() => s.ui.close()} wide>
      <div style={{ display: "flex", flexDirection: "column", height: "100%", gap: 8, minHeight: 360 }}>
        <div style={{ flex: 1, minHeight: 300, position: "relative" }}>
          <canvas
            ref={ref}
            className="map-canvas"
            onPointerDown={(e) => {
              (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
              ptrs.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
              moved.current = 0;
            }}
            onPointerMove={(e) => {
              const p = ptrs.current.get(e.pointerId);
              if (!p) return;
              if (ptrs.current.size >= 2) {
                const pts = [...ptrs.current.entries()].map(([id, v]) => (id === e.pointerId ? { x: e.clientX, y: e.clientY } : v));
                const d = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
                if (pinch.current) setView((v) => ({ ...v, k: Math.min(2, Math.max(0.01, (v.k * d) / pinch.current!)) }));
                pinch.current = d;
                moved.current += 10;
              } else {
                const dx = e.clientX - p.x,
                  dy = e.clientY - p.y;
                moved.current += Math.abs(dx) + Math.abs(dy);
                setView((v) => ({ ...v, cx: v.cx - dx / v.k, cz: v.cz - dy / v.k }));
              }
              p.x = e.clientX;
              p.y = e.clientY;
            }}
            onPointerUp={(e) => {
              ptrs.current.delete(e.pointerId);
              if (ptrs.current.size < 2) pinch.current = null;
              if (moved.current < 6) pickTown(e.clientX, e.clientY);
            }}
            onWheel={(e) => setView((v) => ({ ...v, k: Math.min(2, Math.max(0.01, v.k * Math.exp(-e.deltaY * 0.0015))) }))}
          />
        </div>
        <div className="row">
          <Btn small kind="ghost" onClick={() => setView((v) => ({ ...v, k: Math.min(2, v.k * 1.4) }))}>
            ＋
          </Btn>
          <Btn small kind="ghost" onClick={() => setView((v) => ({ ...v, k: Math.max(0.01, v.k / 1.4) }))}>
            －
          </Btn>
          <Btn small kind="ghost" onClick={() => setView((v) => ({ ...v, cx: sess.player.x, cz: sess.player.z }))}>
            ◎ {tr({ ru: "Я", en: "Me" })}
          </Btn>
          <span className="muted" style={{ fontSize: 12 }}>
            ★ {tr({ ru: "жёлтая — задание, розовая — сюжет", en: "yellow — quest, pink — story" })}
          </span>
          <div className="spacer" />
          {selTown && (
            <>
              <b>
                {tr(selTown.name)} · {selTown.level}
              </b>
              {selTown.discovered ? (
                <Btn small kind="primary" disabled={sess.combatT > 0} onClick={() => sess.travelTo(selTown.id)}>
                  ✨ {tr({ ru: "Перенестись", en: "Travel" })}
                </Btn>
              ) : (
                <span className="muted" style={{ fontSize: 12 }}>
                  {tr({ ru: "не открыт", en: "undiscovered" })}
                </span>
              )}
            </>
          )}
        </div>
      </div>
    </Panel>
  );
});
