/** Хост кооператива: принимает гостя, рассылает снимки мира и события, исполняет его навыки. */
import { dist } from "../core/math";
import type { Txt } from "../core/i18n";
import { audio } from "../audio/audio";
import type { GameSession, NetBridge } from "../game/session";
import type { Entity, GameEvent, Status } from "../game/sim/types";
import type { Poi } from "../game/world/worldgen";
import type { Peer } from "./peer";
import { PROTOCOL_VERSION } from "./signal";
import { mirrorOf, r2, STATES, unpackStats, type GuestMsg, type HostMsg, type WireStatus } from "./protocol";
import { fin, sanitizeClass, sanitizeLook, sanitizeSkill, sanitizeStats, statsOk, str } from "./sanitize";

/** Радиус, в котором гость видит сущности хоста. */
const VIEW = 80;
/** Если гость молчит дольше (загрузка, свёрнутая вкладка) — он неуязвим и не цель для врагов. */
const STALE_MS = 1000;
const CC_KINDS = new Set<Status["kind"]>(["stun", "freeze", "slow", "blind", "weaken", "vulnerable"]);

export interface BridgeHooks {
  onPartner(name: string): void;
  onClosed(reason: string): void;
}

export class HostBridge implements NetBridge {
  readonly role = "host" as const;
  remote: Entity | null = null;
  partnerName = "";
  private inbox: GuestMsg[] = [];
  private lastState: Extract<GuestMsg, { t: "st" }> | null = null;
  private lastStAt = 0;
  private staleGuard = false;
  private known = new Set<number>();
  private sentStatuses = new WeakSet<Status>();
  private snapT = 0;
  private evOut: GameEvent[] = [];
  private session: GameSession | null = null;
  private closed = false;
  /** Номер перехода между картами: устаревшие снимки гостя отбрасываются. */
  private epoch = 0;

  constructor(
    private peer: Peer,
    private hooks: BridgeHooks,
  ) {
    peer.onMessage = (m) => {
      const msg = m as GuestMsg;
      if (!msg || typeof msg !== "object" || typeof msg.t !== "string") return;
      if (msg.t === "st") {
        if (msg.ep === this.epoch) this.lastState = msg;
      } else if (this.inbox.length < 2000) this.inbox.push(msg);
    };
    peer.onClose = (reason) => this.handleClose(reason);
  }

  get connected() {
    return !!this.remote && this.peer.isOpen;
  }

  partner(): Entity | null {
    return this.remote;
  }

  attach(s: GameSession) {
    this.session = s;
    s.net = this;
  }

  private send(m: HostMsg, reliable = true) {
    this.peer.send(m, reliable);
  }

  onFrame(s: GameSession, dt: number) {
    if (this.inbox.length) {
      const msgs = this.inbox;
      this.inbox = [];
      for (const m of msgs) this.handle(s, m);
    }
    const r = this.remote;
    if (!r) return;
    const st = this.lastState;
    if (st) {
      this.lastState = null;
      this.applyState(s, r, st);
    }
    // Гость не отвечает — не даём врагам бить его «вслепую»
    const stale = performance.now() - this.lastStAt > STALE_MS;
    if (stale) {
      r.invuln = Math.max(r.invuln, 6);
      this.staleGuard = true;
    } else if (this.staleGuard) {
      this.staleGuard = false;
      r.invuln = 0;
    }
    // Контроль (оглушение, замедление…) от врагов — гостю
    for (const status of r.statuses) {
      if (!CC_KINDS.has(status.kind) || this.sentStatuses.has(status)) continue;
      this.sentStatuses.add(status);
      this.send({ t: "status", s: { kind: status.kind as WireStatus["kind"], t: status.t, dur: status.dur, value: status.value } });
    }
    this.snapT -= dt;
    if (this.snapT <= 0) {
      this.snapT = 1 / 12;
      this.sendSnapshot(s);
    }
    if (this.evOut.length) {
      this.send({ t: "ev", e: this.evOut });
      this.evOut = [];
    }
  }

  private applyState(s: GameSession, r: Entity, st: Extract<GuestMsg, { t: "st" }>) {
    const x = fin(st.x, -1e7, 1e7, NaN),
      z = fin(st.z, -1e7, 1e7, NaN);
    if (!Number.isFinite(x) || !Number.isFinite(z)) return;
    this.lastStAt = performance.now();
    if (dist(r.x, r.z, x, z) > 25) {
      r.x = x;
      r.z = z;
    }
    r.net = { tx: x, tz: z, tyaw: fin(st.yaw, -100, 100, r.yaw), th: fin(st.h, 0, 15, 0), h: r.net?.h };
    r.hp = Math.min(r.maxHp, fin(st.hp, 0, 1e15, r.hp));
    r.mp = fin(st.mp, 0, 1e15, r.mp);
    r.shield = fin(st.sh, 0, 1e15, 0);
    const state = STATES[Math.round(fin(st.s, 0, STATES.length - 1, 0))] ?? "alive";
    if (!st.alive && r.alive) {
      r.alive = false;
      r.hp = 0;
      r.state = "dead";
      r.stateT = 0;
      r.deadT = 0;
      r.cast = null;
      r.statuses.length = 0;
      for (const e of s.world.entities.values()) if (e.minion && e.minion.ownerId === r.id && e.alive) e.minion.expires = 0;
    } else if (st.alive && !r.alive) {
      r.alive = true;
      r.state = "alive";
      r.deadT = 0;
      r.invuln = 2;
    }
    if (r.alive) {
      r.swimming = state === "swim";
      if (state !== "dead") r.state = state;
    }
  }

  private near(e: { x: number; z: number }, r: number) {
    const g = this.remote!;
    return Math.abs(e.x - g.x) < r && Math.abs(e.z - g.z) < r;
  }

  private sendSnapshot(s: GameSession) {
    const g = this.remote!;
    const spawn = [];
    const flat: number[] = [];
    const seen = new Set<number>();
    for (const e of s.world.entities.values()) {
      if (e === g) continue;
      if (e !== s.player && !this.near(e, VIEW)) continue;
      seen.add(e.id);
      if (!this.known.has(e.id)) {
        this.known.add(e.id);
        spawn.push(mirrorOf(e));
      }
      const si = Math.max(0, STATES.indexOf(e.alive ? e.state : "dead"));
      const h = e.climb || e.state === "climb" || e.state === "perch" ? r2(Math.max(0, e.y - s.world.groundAt(e.x, e.z))) : 0;
      flat.push(e.id, r2(e.x), r2(e.z), r2(e.yaw), Math.round(e.hp), Math.round(e.maxHp), (e.alive ? 1 : 0) | (si << 1), h);
    }
    const gone: number[] = [];
    for (const id of this.known) if (!seen.has(id)) gone.push(id);
    for (const id of gone) this.known.delete(id);
    if (gone.length) this.send({ t: "gone", ids: gone });
    if (spawn.length) this.send({ t: "spawn", e: spawn });
    this.send({ t: "snap", tod: Math.round(s.renderer.env.timeOfDay * 10000) / 10000, e: flat }, false);
  }

  onEvents(s: GameSession, events: GameEvent[]) {
    const g = this.remote;
    if (!g) return;
    for (const ev of events) {
      switch (ev.t) {
        case "cast": {
          if (ev.casterId === g.id) break;
          const c = s.world.entities.get(ev.casterId);
          if (!c || (c !== s.player && !this.near(c, VIEW))) break;
          this.send({ t: "cast", c: ev.casterId, s: ev.skill, ax: r2(ev.aimX), az: r2(ev.aimZ), tid: ev.targetId });
          break;
        }
        case "damage":
        case "dodge":
        case "text":
          if (this.near(ev, VIEW)) this.evOut.push(ev);
          break;
        case "heal":
          // Лечение гостя от других (хоста, его тотемов, похищения жизни) — гостю; своё он считает сам
          if (ev.id === g.id && ev.by !== g.id) this.evOut.push(ev);
          break;
        case "death":
          if (ev.kind !== "player" && this.near(ev, VIEW)) this.evOut.push(ev);
          break;
        default:
          break;
      }
    }
  }

  onLocalCast() {
    /* Касты хоста уходят гостю через события "cast". */
  }

  private transition() {
    this.epoch++;
    this.lastState = null;
    this.lastStAt = 0;
    this.known = new Set(this.session ? [this.session.player.id] : []);
  }

  onEnterDungeon(s: GameSession, poi: Poi, floor: number) {
    this.transition();
    if (this.remote) {
      this.remote.net = { tx: this.remote.x, tz: this.remote.z, tyaw: this.remote.yaw };
      this.send({ t: "dungeon", poiId: poi.id, floor, ret: s.dungeonReturn, ep: this.epoch });
    }
  }

  onExitDungeon() {
    this.transition();
    if (this.remote) {
      this.remote.net = { tx: this.remote.x, tz: this.remote.z, tyaw: this.remote.yaw };
      this.send({ t: "exitDungeon", x: this.remote.x, z: this.remote.z, ep: this.epoch });
    }
  }

  onMeow(s: GameSession) {
    this.send({ t: "emote", id: s.player.id, k: "meow" });
  }

  private handle(s: GameSession, m: GuestMsg) {
    switch (m.t) {
      case "hello": {
        if (m.v !== PROTOCOL_VERSION) {
          this.send({ t: "toast", text: { ru: "Разные версии игры — обновите страницу", en: "Game versions differ — reload the page" } });
          this.close();
          return;
        }
        const wire = sanitizeStats(m.stats);
        if (!wire) return;
        const stats = unpackStats(wire);
        if (!statsOk(stats)) return;
        const classId = sanitizeClass(m.classId);
        const name = str(m.name, 24, "Котик").trim() || "Котик";
        if (this.remote) s.world.entities.delete(this.remote.id);
        const p = s.player;
        const x = p.x + 1.6,
          z = p.z + 0.6;
        const e = s.world.addPlayer({ classId, name: { ru: name, en: name }, look: sanitizeLook(m.look, classId), level: Math.round(fin(m.level, 1, 1e6, 1)), stats, peer: "remote", x, z });
        e.net = { tx: x, tz: z, tyaw: 0 };
        this.remote = e;
        this.partnerName = name;
        this.known = new Set([p.id]);
        this.lastStAt = 0;
        const d = s.dungeon;
        this.send({
          t: "welcome",
          v: PROTOCOL_VERSION,
          seed: s.gen.seed,
          mode: s.gen.mode,
          you: e.id,
          host: mirrorOf(p),
          hostName: s.char.data.name,
          pos: { x, z },
          dungeon: d ? { poiId: d.poi.id, floor: d.floor } : null,
          dungeonReturn: s.dungeonReturn,
          tod: s.renderer.env.timeOfDay,
          ep: this.epoch,
        });
        s.hud.toast({ ru: `${name} присоединяется к игре!`, en: `${name} joined the game!` }, 0x7ee081, "🤝");
        audio.play("meow", x, z);
        this.hooks.onPartner(name);
        break;
      }
      case "stats": {
        const r = this.remote;
        const wire = sanitizeStats(m.stats);
        if (!r || !wire) break;
        const stats = unpackStats(wire);
        if (!statsOk(stats)) break;
        const hpFrac = r.maxHp > 0 ? r.hp / r.maxHp : 1;
        s.world.applyStats(r, stats, hpFrac);
        r.look = sanitizeLook(m.look, r.classId);
        r.level = Math.round(fin(m.level, 1, 1e6, r.level));
        break;
      }
      case "cast": {
        const r = this.remote;
        if (!r || !r.alive) break;
        const skill = sanitizeSkill(m.s);
        if (!skill) break;
        // Точка прицела — в разумных пределах от кота
        let ax = fin(m.ax, -1e7, 1e7, r.x),
          az = fin(m.az, -1e7, 1e7, r.z);
        const d = dist(r.x, r.z, ax, az);
        const maxD = skill.params.range + skill.params.radius + 10;
        if (d > maxD) {
          ax = r.x + ((ax - r.x) / d) * maxD;
          az = r.z + ((az - r.z) / d) * maxD;
        }
        const tid = typeof m.tid === "number" && s.world.entities.has(m.tid) ? m.tid : -1;
        r.mp = r.maxMp;
        s.world.tryCast(r, skill, ax, az, tid, true);
        break;
      }
      case "req":
        if (m.k === "dungeon" || m.k === "exit" || m.k === "stairs") this.handleRequest(s, m.k, typeof m.poiId === "string" ? m.poiId.slice(0, 64) : undefined);
        break;
      case "emote": {
        const r = this.remote;
        if (!r) break;
        r.action = "meow";
        r.actionT = 0;
        r.actionDur = 0.7;
        audio.play("meow", r.x, r.z, 1, 1 / r.look.size);
        s.fx.handle({ k: "cast", x: r.x, y: r.y + 1.2, z: r.z, v: { color: 0xffd24a, color2: 0xffffff, shape: "note", size: 1, trail: false, glow: 1, style: 0 } });
        break;
      }
      case "bye":
        this.handleClose("bye");
        break;
    }
  }

  private handleRequest(s: GameSession, k: "dungeon" | "exit" | "stairs", poiId?: string) {
    const who = this.partnerName;
    if (s.ui.confirm) return;
    if (k === "dungeon" && poiId) {
      const poi = s.findPoi(poiId);
      if (!poi || poi.kind !== "dungeon" || s.dungeon) return;
      s.ui.ask({
        text: { ru: `${who} зовёт вас в подземелье «${poi.name.ru}» (ур. ${poi.level}). Идём?`, en: `${who} invites you into the dungeon "${poi.name.en}" (Lv ${poi.level}). Go?` },
        okLabel: { ru: "Войти вместе", en: "Enter together" },
        ok: () => {
          s.dungeonReturn = { x: poi.x + Math.sin(0.5) * 7, z: poi.z + Math.cos(0.5) * 7 };
          s.enterDungeon(poi, 0);
        },
      });
    } else if (k === "exit" && s.dungeon) {
      s.ui.ask({ text: { ru: `${who} хочет выйти из подземелья.`, en: `${who} wants to leave the dungeon.` }, okLabel: { ru: "Выйти", en: "Leave" }, ok: () => s.exitDungeon(false) });
    } else if (k === "stairs" && s.dungeon?.stairs) {
      s.ui.ask({ text: { ru: `${who} хочет спуститься ниже.`, en: `${who} wants to go deeper.` }, okLabel: { ru: "Спуститься", en: "Go deeper" }, ok: () => s.nextFloor() });
    }
    audio.play("click");
  }

  toast(text: Txt) {
    this.send({ t: "toast", text });
  }

  private handleClose(reason: string) {
    if (this.closed) return;
    this.closed = true;
    const s = this.session;
    if (s) {
      const r = this.remote;
      if (r) {
        s.world.entities.delete(r.id);
        for (const e of s.world.entities.values()) if (e.minion && e.minion.ownerId === r.id) e.minion.expires = 0;
        s.hud.toast({ ru: `${this.partnerName || "Напарник"} отключился`, en: `${this.partnerName || "Partner"} disconnected` }, 0xffb454, "🔌");
      }
      if (s.net === this) s.net = null;
    }
    this.remote = null;
    this.hooks.onClosed(reason);
  }

  close() {
    if (this.closed) return;
    this.send({ t: "bye" });
    const peer = this.peer;
    setTimeout(() => peer.close(), 150);
    this.handleClose("local");
  }
}
