import { FRAME_GLSL, HEADER, UTIL_GLSL } from "./common";

/**
 * Частицы: билборды с процедурными формами (SDF) — лапки, рыбки, пламя, снежинки, молнии...
 * Инстанс: pos+size, color, (shape, rot, flags, stretch), vel+age.
 * flags: 1 — лежит на земле, 2 — растягивается по скорости.
 */
export const PARTICLE_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
layout(location=0) in vec2 aCorner;
layout(location=4) in vec4 iPosSize;
layout(location=5) in vec4 iColor;
layout(location=6) in vec4 iShape;
layout(location=7) in vec4 iVel;
out vec2 vUv;
out vec4 vColor;
flat out float vShape;
out float vAge;
void main() {
  vec3 right = vec3(uView[0][0], uView[1][0], uView[2][0]);
  vec3 up = vec3(uView[0][1], uView[1][1], uView[2][1]);
  float size = iPosSize.w;
  float rot = iShape.y;
  int flags = int(iShape.z + 0.5);
  vec2 c = aCorner;
  vec3 wp;
  if ((flags & 1) != 0) {
    // На земле
    float cr = cos(rot), sr = sin(rot);
    vec2 rc = vec2(c.x * cr - c.y * sr, c.x * sr + c.y * cr);
    wp = iPosSize.xyz + vec3(rc.x, 0.0, rc.y) * size;
  } else if ((flags & 2) != 0 && length(iVel.xyz) > 0.01) {
    // Растяжение по скорости (искры, капли)
    vec3 v = iVel.xyz;
    vec3 vv = normalize(v - dot(v, normalize(uCamPos.xyz - iPosSize.xyz)) * normalize(uCamPos.xyz - iPosSize.xyz) + vec3(1e-4));
    vec3 side = normalize(cross(vv, normalize(uCamPos.xyz - iPosSize.xyz)));
    float st = 1.0 + iShape.w * min(length(v) * 0.12, 3.0);
    wp = iPosSize.xyz + side * c.x * size * 0.5 + vv * c.y * size * st;
  } else {
    float cr = cos(rot), sr = sin(rot);
    vec2 rc = vec2(c.x * cr - c.y * sr, c.x * sr + c.y * cr);
    wp = iPosSize.xyz + (right * rc.x + up * rc.y) * size;
  }
  vUv = c;
  vColor = vec4(toLinear(iColor.rgb), iColor.a);
  vShape = iShape.x;
  vAge = iVel.w;
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

export const PARTICLE_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
in vec2 vUv;
in vec4 vColor;
flat in float vShape;
in float vAge;
uniform float uAdditive;
out vec4 outColor;

float sdCircle(vec2 p, float r) { return length(p) - r; }
float sdBox(vec2 p, vec2 b) { vec2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
float sdStar(vec2 p, float r, float rf) {
  const vec2 k1 = vec2(0.809016994375, -0.587785252292);
  const vec2 k2 = vec2(-k1.x, k1.y);
  p.x = abs(p.x);
  p -= 2.0 * max(dot(k1, p), 0.0) * k1;
  p -= 2.0 * max(dot(k2, p), 0.0) * k2;
  p.x = abs(p.x);
  p.y -= r;
  vec2 ba = rf * vec2(-k1.y, k1.x) - vec2(0, 1);
  float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
  return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
}
float sdHeart(vec2 p) {
  p.x = abs(p.x);
  p.y += 0.5;
  if (p.y + p.x > 1.0) return sqrt(dot(p - vec2(0.25, 0.75), p - vec2(0.25, 0.75))) - sqrt(2.0) / 4.0;
  return sqrt(min(dot(p - vec2(0.0, 1.0), p - vec2(0.0, 1.0)), dot(p - 0.5 * max(p.x + p.y, 0.0), p - 0.5 * max(p.x + p.y, 0.0)))) * sign(p.x - p.y);
}
float sdSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
float hash(float n) { return fract(sin(n) * 43758.5453); }

void main() {
  vec2 p = vUv;
  int shape = int(vShape + 0.5);
  // Непрозрачные частицы слегка следуют освещению сцены
  float lightK = 0.55 + 0.45 * (uSunColor.w + uSunDir.w * 0.6);
  float d = 1.0;
  float glow = 0.0;
  if (shape == 0) { // мягкий кружок
    float r = length(p);
    float a = 1.0 - smoothstep(0.0, 1.0, r);
    outColor = vec4(vColor.rgb, vColor.a * a * a);
    outColor.rgb *= uAdditive > 0.5 ? 2.4 * outColor.a : lightK;
    if (outColor.a < 0.003) discard;
    return;
  } else if (shape == 1) { d = abs(sdCircle(p, 0.8)) - 0.1; }
  else if (shape == 2) { d = sdStar(p, 0.9, 0.45); }
  else if (shape == 3) { d = sdBox(vec2(p.x * 3.5, p.y), vec2(0.15, 0.85)) ; d = length(vec2(p.x * 4.0, p.y)) - 0.9; }
  else if (shape == 4) { // пламя-капля
    vec2 q = p; q.y += 0.2;
    float r = length(q) - 0.55;
    float tip = sdSeg(q, vec2(0.0), vec2(0.0, 0.95)) - 0.55 * (1.0 - clamp(q.y / 0.95, 0.0, 1.0));
    d = min(r, tip);
  } else if (shape == 5) { // снежинка
    float a = atan(p.y, p.x);
    float r = length(p);
    float arm = abs(sin(a * 3.0));
    d = min(abs(r * arm) - 0.07, r - 0.85);
    d = max(d, r - 0.9);
    d = min(d, r - 0.18);
  } else if (shape == 6) { // лапка!
    d = sdCircle(p - vec2(0.0, -0.25), 0.42);
    d = min(d, sdCircle(p - vec2(-0.52, 0.28), 0.18));
    d = min(d, sdCircle(p - vec2(-0.2, 0.55), 0.19));
    d = min(d, sdCircle(p - vec2(0.2, 0.55), 0.19));
    d = min(d, sdCircle(p - vec2(0.52, 0.28), 0.18));
  } else if (shape == 7) { // рыбка
    vec2 q = p; q.x += 0.15;
    d = length(q * vec2(0.9, 1.7)) - 0.6;
    vec2 t = p - vec2(0.62, 0.0);
    d = min(d, max(abs(t.y) - (t.x) * 0.9, abs(t.x) - 0.28));
  } else if (shape == 8) { // черепок
    d = sdCircle(p - vec2(0.0, 0.15), 0.62);
    d = min(d, sdBox(p - vec2(0.0, -0.45), vec2(0.35, 0.25)));
    d = max(d, -sdCircle(p - vec2(-0.25, 0.15), 0.17));
    d = max(d, -sdCircle(p - vec2(0.25, 0.15), 0.17));
  } else if (shape == 9) { // лист
    vec2 q = vec2(p.x * 1.8, p.y);
    d = max(length(q - vec2(0.55, 0.0)) - 0.75, length(q + vec2(0.55, 0.0)) - 0.75);
  } else if (shape == 10) { d = sdHeart(p * 1.1) ; }
  else if (shape == 11) { d = max(sdCircle(p, 0.85), -sdCircle(p - vec2(0.35, 0.2), 0.72)); }
  else if (shape == 12) { d = abs(p.x) + abs(p.y) * 0.75 - 0.8; }
  else if (shape == 13) { // пузырь
    d = abs(sdCircle(p, 0.75)) - 0.08;
    glow = 1.0 - smoothstep(0.0, 0.15, length(p - vec2(-0.3, 0.3)));
  } else if (shape == 14) { d = min(sdBox(p, vec2(0.18, 0.85)), sdBox(p - vec2(0.0, 0.25), vec2(0.6, 0.17))); }
  else if (shape == 15) { // молния
    d = sdSeg(p, vec2(-0.2, 0.9), vec2(0.15, 0.1));
    d = min(d, sdSeg(p, vec2(0.15, 0.1), vec2(-0.15, 0.0)));
    d = min(d, sdSeg(p, vec2(-0.15, 0.0), vec2(0.25, -0.9)));
    d -= 0.1;
  } else if (shape == 16) { // руна
    d = abs(sdCircle(p, 0.75)) - 0.07;
    d = min(d, sdSeg(p, vec2(0.0, -0.6), vec2(0.0, 0.6)) - 0.07);
    d = min(d, sdSeg(p, vec2(-0.45, 0.2), vec2(0.45, -0.2)) - 0.07);
  } else if (shape == 17) { // следы когтей
    for (int i = 0; i < 3; i++) {
      float o = float(i - 1) * 0.38;
      vec2 q = p - vec2(o, 0.0);
      q.x += q.y * q.y * 0.25;
      d = min(d, sdSeg(q, vec2(0.0, -0.8), vec2(0.0, 0.8)) - 0.07 * (1.0 - abs(q.y)));
    }
  } else if (shape == 18) { // нота
    d = sdCircle(p - vec2(-0.2, -0.45), 0.3);
    d = min(d, sdBox(p - vec2(0.06, 0.1), vec2(0.07, 0.6)));
    d = min(d, sdSeg(p, vec2(0.06, 0.7), vec2(0.45, 0.45)) - 0.08);
  } else if (shape == 19) { // перо
    vec2 q = vec2(p.x * 2.5, p.y);
    d = length(q) - 0.85;
    d = min(d, sdSeg(p, vec2(0.0, -0.95), vec2(0.0, 0.8)) - 0.04);
  } else if (shape == 20) { // клубок
    float r = length(p);
    d = r - 0.8;
    float lines = abs(sin((p.x + p.y * 0.6) * 12.0));
    glow = (1.0 - lines) * 0.35 * step(r, 0.8);
  } else if (shape == 21) { // дым
    float r = length(p);
    float n = sin(atan(p.y, p.x) * 5.0 + vAge * 6.0) * 0.08;
    float a = 1.0 - smoothstep(0.3, 0.95 + n, r);
    outColor = vec4(vColor.rgb, vColor.a * a);
    outColor.rgb *= uAdditive > 0.5 ? 2.4 * outColor.a : lightK;
    if (outColor.a < 0.003) discard;
    return;
  }
  float edge = 1.0 - smoothstep(-0.02, 0.06, d);
  float halo = (1.0 - smoothstep(0.0, 0.45, d)) * 0.35;
  float a = max(edge, uAdditive > 0.5 ? halo : 0.0);
  vec3 col = mix(vColor.rgb, vec3(1.0), edge * 0.18 + glow);
  outColor = vec4(col, vColor.a * a);
  outColor.rgb *= uAdditive > 0.5 ? 2.4 * outColor.a : lightK;
  if (outColor.a < 0.003) discard;
}
`;
