import { FRAME_GLSL, HEADER, LIGHTING_GLSL, SKY_GLSL, UTIL_GLSL } from "./common";

/**
 * Кошки собираются из инстансов примитивов (сфера, цилиндр, конус, куб, тор).
 * Окрас (полоски, пятна, «смокинг», сиамский и т.д.) рисуется процедурно во фрагментном шейдере
 * по локальным координатам примитива и типу части тела.
 */
export const CAT_VS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
layout(location=0) in vec3 aPos;
layout(location=1) in vec4 aNormal;
layout(location=4) in vec4 iRow0;
layout(location=5) in vec4 iRow1;
layout(location=6) in vec4 iRow2;
layout(location=7) in vec4 iColA;
layout(location=8) in vec4 iColB;
layout(location=9) in vec4 iParams;
uniform float uShell;
out vec3 vWorld;
out vec3 vNormal;
out vec3 vLocal;
out vec3 vFlow;
flat out float vScale;
flat out vec4 vColA;
flat out vec4 vColB;
flat out vec4 vParams;
void main() {
  vec4 p = vec4(aPos, 1.0);
  vec3 wp = vec3(dot(iRow0, p), dot(iRow1, p), dot(iRow2, p));
  vec3 c0 = vec3(iRow0.x, iRow1.x, iRow2.x);
  vec3 c1 = vec3(iRow0.y, iRow1.y, iRow2.y);
  vec3 c2 = vec3(iRow0.z, iRow1.z, iRow2.z);
  mat3 cof = mat3(cross(c1, c2), cross(c2, c0), cross(c0, c1));
  vNormal = normalize(cof * aNormal.xyz);
  // Направление шерсти: вдоль тела и головы — по локальной Z, у лап и хвоста — по Y
  int part = int(iColA.w + 0.5);
  vFlow = normalize((part == 0 || part == 1 || part == 16 || part == 9) ? c2 : c1);
  vScale = (length(c0) + length(c1) + length(c2)) / 3.0;
  if (uShell > 0.0) {
    int pat = int(iColB.w + 0.5);
    bool furry = (part <= 6 || part == 9 || part == 14 || part == 16) && pat != 9 && pat != 10 && pat != 12 && pat != 13 && pat != 14;
    vec3 origin = vec3(iRow0.w, iRow1.w, iRow2.w);
    if (!furry || length(origin - uCamPos.xyz) > 16.0 || iParams.z < 0.99) {
      gl_Position = vec4(0.0, 0.0, -2.0, 1.0);
      return;
    }
    wp += vNormal * uShell * (part == 4 ? 0.5 : 1.0);
  }
  vWorld = wp;
  vLocal = aPos;
  vColA = vec4(toLinear(iColA.rgb), iColA.w);
  vColB = vec4(toLinear(iColB.rgb), iColB.w);
  vParams = iParams;
  gl_Position = uViewProj * vec4(wp, 1.0);
}
`;

export const CAT_FS = /* glsl */ `${HEADER}
${FRAME_GLSL}
${UTIL_GLSL}
${SKY_GLSL}
${LIGHTING_GLSL}
in vec3 vWorld;
in vec3 vNormal;
in vec3 vLocal;
in vec3 vFlow;
flat in float vScale;
flat in vec4 vColA;
flat in vec4 vColB;
flat in vec4 vParams;
uniform float uShell;
uniform float uShellK;
out vec4 outColor;

float h31(vec3 p) {
  p = fract(p * 0.3183099 + 0.1);
  p *= 17.0;
  return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}
float vn3(vec3 x) {
  vec3 i = floor(x);
  vec3 f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(h31(i), h31(i + vec3(1,0,0)), f.x), mix(h31(i + vec3(0,1,0)), h31(i + vec3(1,1,0)), f.x), f.y),
             mix(mix(h31(i + vec3(0,0,1)), h31(i + vec3(1,0,1)), f.x), mix(h31(i + vec3(0,1,1)), h31(i + vec3(1,1,1)), f.x), f.y), f.z);
}

// Цвета в линейном пространстве
const vec3 PINK = vec3(0.89, 0.36, 0.43);
const vec3 WHITE = vec3(0.93, 0.89, 0.83);

// Части: 0 тело, 1 голова, 2 бедро/плечо, 3 голень, 4 лапа, 5 хвост, 6 ухо, 7 глаз, 8 нос,
// 9 морда, 10 усы, 11 аксессуар, 12 металл, 13 свечение, 14 грива, 16 грудь/таз, 17 дерево
vec3 furColor(int pat, int part, vec3 p, vec3 A, vec3 B, float seed, inout float em, inout float al, inout float spec) {
  vec3 c = A;
  bool leg = part == 2 || part == 3;
  bool bodyish = part == 0 || part == 16;
  if (pat == 1) { // полосатый табби
    float s = -1.0;
    if (bodyish) s = sin(p.z * 9.0 + sin(p.y * 5.0 + seed) * 1.3 + seed);
    else if (part == 1) s = p.y > 0.3 && p.z > -0.2 ? sin(p.x * 17.0) : -1.0;
    else if (leg) s = sin(p.y * 13.0 + seed);
    else if (part == 5) s = fract(seed * 3.71) > 0.5 ? 1.0 : -1.0;
    c = mix(A, B, smoothstep(0.25, 0.65, s) * 0.85);
    if (bodyish && p.y < -0.5) c = mix(c, A * 1.5 + 0.012, 0.6);
    if (part == 9) c = mix(A, WHITE, 0.55);
  } else if (pat == 2) { // пятнистый (бенгал/леопард)
    vec3 q = p * 3.2 + seed;
    vec3 cell = floor(q);
    vec3 fr = fract(q) - 0.5;
    float r = h31(cell);
    float spot = r > 0.45 ? smoothstep(0.34, 0.22, length(fr + (h31(cell + 7.0) - 0.5) * 0.3)) : 0.0;
    if (part == 1 || part == 9 || part == 4) spot *= 0.5;
    c = mix(A, B, spot * 0.9);
    if (bodyish && p.y < -0.45) c = mix(c, WHITE, 0.4);
    if (part == 9) c = mix(c, WHITE, 0.5);
  } else if (pat == 3) { // «смокинг»
    bool white = part == 4 || part == 9
      || (bodyish && (p.y < -0.35 || (part == 16 && p.z > 0.4 && p.y < 0.3)))
      || (part == 1 && p.y < -0.15 && p.z > 0.2)
      || (part == 3 && p.y < 0.45);
    c = white ? B : A;
  } else if (pat == 4) { // трёхцветная (калико)
    float n = vn3(p * 2.3 + seed * 13.0);
    c = A;
    if (n > 0.6) c = B;
    else if (n < 0.33) c = vec3(0.022, 0.018, 0.016);
    if (part == 4 || part == 9) c = A;
  } else if (pat == 5) { // сиамский окрас-пойнт
    float k = 0.0;
    if (part == 6 || part == 4 || part == 5) k = 1.0;
    else if (part == 3) k = 0.85;
    else if (part == 2) k = smoothstep(0.6, -0.4, p.y) * 0.6;
    else if (part == 9) k = 0.9;
    else if (part == 1) k = smoothstep(0.1, 0.9, p.z) * smoothstep(0.5, -0.2, p.y) * 0.9;
    c = mix(A, B, k);
  } else if (pat == 6) { // черепаховый
    float n = vn3(p * 4.0 + seed * 7.0) * 0.7 + vn3(p * 9.0) * 0.3;
    c = mix(A, B, smoothstep(0.45, 0.62, n));
  } else if (pat == 7) { // двухцветный
    bool low = (bodyish && p.y < -0.05) || (part == 1 && p.y < -0.25) || part == 3 || part == 4 || part == 9;
    c = low ? B : A;
  } else if (pat == 8) { // тигр
    float s = -1.0;
    if (bodyish) s = sin(p.z * 11.0 + sin(p.y * 6.0 + seed) * 2.0 + p.y * 3.0);
    else if (part == 1) s = p.y > 0.1 ? sin(p.x * 14.0 + p.y * 4.0) : -1.0;
    else if (leg) s = sin(p.y * 12.0 + seed);
    else if (part == 5) s = fract(seed * 3.71) > 0.5 ? 1.0 : -1.0;
    c = mix(A, B, smoothstep(0.35, 0.55, s));
    if ((bodyish && p.y < -0.5) || part == 9) c = mix(c, WHITE, 0.7);
  } else if (pat == 9) { // призрак
    c = mix(A, B, 0.5 + 0.5 * sin(p.y * 6.0 + uCamPos.w * 2.0 + seed));
    al *= 0.55;
    em += 0.45;
  } else if (pat == 10) { // механокот
    vec3 g = abs(fract(p * 2.5) - 0.5);
    float line = 1.0 - smoothstep(0.02, 0.05, min(min(g.x, g.y), g.z));
    c = mix(A, A * 0.45, line);
    float seam = step(0.46, g.x) * step(0.4, h31(floor(p * 2.5) + seed));
    c = mix(c, B, seam);
    em += seam * 1.2;
    spec = 1.0;
  } else if (pat == 11) { // лава
    vec3 q = p * 2.8 + seed;
    float n = vn3(q) + vn3(q * 2.1) * 0.5;
    float crack = 1.0 - smoothstep(0.03, 0.1, abs(n - 0.75));
    c = mix(A, B, crack);
    em += crack * (1.2 + 0.4 * sin(uCamPos.w * 3.0 + seed));
  } else if (pat == 12) { // кристалл
    float n = vn3(p * 5.0 + seed);
    c = mix(A, B, n * 0.6);
    em += 0.25 + step(0.93, h31(floor(p * 9.0) + floor(uCamPos.w * 2.0))) * 1.5;
    spec = 1.0;
  } else if (pat == 13) { // пустота
    c = A;
    float star = step(0.985, h31(floor(p * 14.0 + seed)));
    c += star * B * (0.6 + 0.4 * sin(uCamPos.w * 4.0 + seed * 10.0));
    em += star * 1.5;
  } else if (pat == 14) { // скелет
    c = A;
    if (bodyish) c = mix(A, A * 0.25, step(0.55, sin(p.z * 16.0)) * step(-0.6, p.y));
  } else if (pat == 15) { // золотой
    c = mix(A, A * 1.3, vn3(p * 3.0));
    spec = 1.0;
  }
  // Детали, общие для всех окрасов
  if (part == 6 && p.z > 0.15 && p.y < 0.8 && pat < 9) c = mix(c, PINK, 0.85);
  if (part == 4 && p.y < -0.45 && pat < 9) c = mix(c, PINK, 0.8);
  if (part == 9 && pat == 0) c = mix(A, WHITE, 0.45);
  return c;
}

void main() {
  int part = int(vColA.w + 0.5);
  int pat = int(vColB.w + 0.5);
  vec3 A = vColA.rgb;
  vec3 B = vColB.rgb;
  float seed = vParams.x;
  float em = vParams.y;
  float al = vParams.z;
  float flash = vParams.w;
  float spec = 0.0;
  vec3 p = vLocal;
  vec3 N = normalize(vNormal);
  if (!gl_FrontFacing) N = -N;
  vec3 V = normalize(uCamPos.xyz - vWorld);
  vec3 albedo;
  if (part == 7) {
    // Глаз: радужка с вертикальным зрачком и бликом
    float iris = smoothstep(0.1, 0.3, p.z);
    float pupilW = mix(0.16, 0.42, uOriginMod.z);
    float pupil = (1.0 - smoothstep(pupilW, pupilW + 0.06, abs(p.x))) * smoothstep(0.55, 0.7, p.z) * (1.0 - smoothstep(0.75, 0.95, abs(p.y)));
    albedo = mix(vec3(0.006), A, iris);
    albedo = mix(albedo, vec3(0.001), pupil);
    float hl = 1.0 - smoothstep(0.1, 0.16, length(p.xy - vec2(0.32, 0.36)));
    albedo = mix(albedo, vec3(1.0), hl * step(0.5, p.z));
    em += iris * (1.0 - pupil) * 0.35;
    spec = 1.0;
  } else if (part == 8) {
    albedo = A;
  } else if (part == 10) {
    albedo = A;
    em += 0.2;
  } else if (part == 11) {
    albedo = A;
  } else if (part == 12) {
    albedo = A;
    spec = 1.0;
  } else if (part == 13) {
    albedo = A;
    em += 1.0;
  } else if (part == 17) {
    albedo = A * (0.85 + 0.15 * sin(p.y * 30.0 + sin(p.x * 10.0) * 2.0));
  } else if (part == 14) {
    albedo = A * (0.8 + 0.3 * vn3(p * 6.0 + seed));
  } else {
    albedo = furColor(pat, part, p, A, B, seed, em, al, spec);
    // Шерстинки: мелкий шум, вытянутый вдоль направления шерсти
    vec3 fp = p * vScale;
    float strands = vn3(fp * vec3(55.0, 55.0, 14.0) + seed) * 0.6 + vn3(fp * 110.0 + seed * 3.0) * 0.4;
    albedo *= 0.9 + 0.2 * strands;
  }
  bool furPart = part <= 6 || part == 9 || part == 14 || part == 16;
  // Оболочки пушистой кромки: шерстинки редеют к внешнему слою (alpha-to-coverage)
  if (uShell > 0.0) {
    vec3 fp = p * vScale * 95.0 + seed;
    float n = vn3(fp) * 0.55 + vn3(fp * 2.3) * 0.45;
    float keep = smoothstep(uShellK - 0.08, uShellK + 0.08, n);
    if (keep < 0.02) discard;
    al = keep;
  }
  float shadow = sunShadow(vWorld, N);
  vec3 col = shadeFull(albedo, N, V, vWorld, em, 1.0, 0.0, 16.0, shadow);
  float ndv = max(dot(N, V), 0.0);
  float rim = pow(1.0 - ndv, 2.5);
  if (furPart && pat < 9) {
    // Анизотропный блеск шерсти (Каджия — Кей) и тёплое свечение кромки против солнца
    vec3 T = normalize(vFlow - N * dot(vFlow, N));
    vec3 H = normalize(uSunDir.xyz + V);
    float th = dot(T, H);
    float sheen = pow(sqrt(max(1.0 - th * th, 0.0)), 60.0);
    col += albedo * uSunColor.rgb * uSunDir.w * sheen * 0.35 * shadow;
    float back = pow(max(dot(-V, uSunDir.xyz), 0.0), 2.0);
    col += (albedo * 0.6 + 0.4) * uSunColor.rgb * uSunDir.w * rim * rim * back * 1.4 * shadow;
    col += rim * mix(uHorizon.rgb, uSkyColor.rgb, 0.4) * 0.35 * (0.5 + uSunColor.w * 0.5);
  } else {
    col += rim * (uSkyColor.rgb * 0.25 + uSunColor.rgb * 0.15) * (0.6 + uSunColor.w * 0.4);
  }
  if (spec > 0.0) {
    vec3 H = normalize(uSunDir.xyz + V);
    col += uSunColor.rgb * pow(max(dot(N, H), 0.0), 48.0) * 1.4 * spec * uSunDir.w * shadow;
  }
  col = mix(col, vec3(1.6, 1.5, 1.4), flash);
  col = fog(col, vWorld);
  outColor = vec4(col, al);
}
`;
