import { observer } from "mobx-react-lite";
import { useEffect, useRef } from "react";
import { useStore } from "../stores";
import { BIOMES } from "../../game/world/biomes";
import { hex } from "../icons";
import { Tile, TILE } from "../../game/dungeon/dungeon";

const SIZE = 150;
const RANGE = 70;

export const Minimap = observer(() => {
  const s = useStore();
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current!;
    const ctx = canvas.getContext("2d")!;
    const bg = document.createElement("canvas");
    bg.width = bg.height = 48;
    const bctx = bg.getContext("2d")!;
    let lastX = NaN,
      lastZ = NaN,
      lastDungeon: unknown = null;
    const draw = () => {
      const sess = s.session;
      if (!sess) return;
      const p = sess.player;
      const d = sess.dungeon;
      // Фон (перерисовываем при заметном перемещении)
      if (Math.abs(p.x - lastX) > 6 || Math.abs(p.z - lastZ) > 6 || d !== lastDungeon) {
        lastX = p.x;
        lastZ = p.z;
        lastDungeon = d;
        const img = bctx.createImageData(48, 48);
        for (let j = 0; j < 48; j++)
          for (let i = 0; i < 48; i++) {
            const wx = p.x + ((i + 0.5) / 48 - 0.5) * RANGE * 2;
            const wz = p.z + ((j + 0.5) / 48 - 0.5) * RANGE * 2;
            let c: number;
            if (d) {
              const t = d.at(Math.floor(wx / TILE), Math.floor(wz / TILE));
              c = t === Tile.Wall ? 0x141018 : t === Tile.Stairs ? d.style.accent : d.style.floor;
            } else {
              const h = sess.terrain.heightAt(wx, wz);
              const b = BIOMES[sess.gen.biomeIdAt(wx, wz)];
              c = h < -0.5 ? b.water : h < 1 ? b.shore : b.ground;
              if (h > 40) c = 0xdde6ee;
            }
            const o = (j * 48 + i) * 4;
            const shade = d ? 1 : 1;
            img.data[o] = ((c >> 16) & 255) * shade;
            img.data[o + 1] = ((c >> 8) & 255) * shade;
            img.data[o + 2] = (c & 255) * shade;
            img.data[o + 3] = 255;
          }
        bctx.putImageData(img, 0, 0);
      }
      const W = canvas.width;
      ctx.save();
      ctx.clearRect(0, 0, W, W);
      ctx.translate(W / 2, W / 2);
      // «Вперёд» камеры — вверху: взгляд камеры (-sin yaw, -cos yaw) после поворота на yaw смотрит вверх,
      // а её «вправо» (cos yaw, -sin yaw) — вправо, как и управление
      const rot = sess.camYaw;
      ctx.rotate(rot);
      const scale = W / (RANGE * 2);
      const offX = (lastX - p.x) * scale,
        offZ = (lastZ - p.z) * scale;
      ctx.imageSmoothingEnabled = true;
      ctx.drawImage(bg, -W / 2 + offX, -W / 2 + offZ, W, W);
      const dot = (x: number, z: number, r: number, color: string, stroke = false) => {
        const px = (x - p.x) * scale,
          pz = (z - p.z) * scale;
        if (px * px + pz * pz > (W / 2) ** 2) return;
        ctx.beginPath();
        ctx.arc(px, pz, r, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
        if (stroke) {
          ctx.strokeStyle = "#fff";
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }
      };
      if (!d) {
        const reg = sess.gen.regionAt(p.x, p.z);
        if (reg.town) dot(reg.town.x, reg.town.z, 6, "#ffd27a", true);
        for (const poi of reg.pois) dot(poi.x, poi.z, poi.kind === "dungeon" ? 5 : 3, poi.kind === "dungeon" ? "#c08aff" : poi.kind === "camp" ? "#ff8a5a" : "#9ad0ff", poi.kind === "dungeon");
      } else {
        if (d.stairs) dot(d.stairs.x, d.stairs.z, 5, hex(d.style.accent), true);
        if (d.exitPortal) dot(d.exitPortal.x, d.exitPortal.z, 5, "#8fd0ff", true);
      }
      for (const e of sess.world.entities.values()) {
        if (!e.alive || e === p) continue;
        if (e.kind === "enemy") dot(e.x, e.z, e.enemy?.boss ? 5 : e.enemy?.elite ? 3.5 : 2.2, e.enemy?.boss ? "#ff3a5a" : "#ff6a5a");
        else if (e.kind === "npc") {
          const mk = e.npc ? sess.quests.marker(e.npc.npcId, e.npc.townId) : null;
          dot(e.x, e.z, mk ? 4 : 2.2, mk ? "#ffd24a" : "#e8e2d8", !!mk);
        } else if (e.kind === "player") dot(e.x, e.z, 4, "#5ad0ff", true);
        else if (e.kind === "minion") dot(e.x, e.z, 2, "#7ee081");
      }
      const tt = sess.quests.trackedTarget();
      if (tt && !d) {
        const px = (tt.x - p.x) * scale,
          pz = (tt.z - p.z) * scale;
        const l = Math.hypot(px, pz);
        const k = l > W / 2 - 8 ? (W / 2 - 8) / l : 1;
        ctx.fillStyle = "#ffd24a";
        ctx.font = "bold 16px sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.save();
        ctx.translate(px * k, pz * k);
        ctx.rotate(-rot);
        ctx.fillText("★", 0, 0);
        ctx.restore();
      }
      // Игрок
      ctx.rotate(-rot);
      ctx.rotate(-(p.yaw - sess.camYaw) + Math.PI);
      ctx.beginPath();
      ctx.moveTo(0, -8);
      ctx.lineTo(5.5, 6);
      ctx.lineTo(0, 3);
      ctx.lineTo(-5.5, 6);
      ctx.closePath();
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.strokeStyle = "#2a1a3a";
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.restore();
    };
    const id = window.setInterval(draw, 120);
    return () => window.clearInterval(id);
  }, [s]);
  return <canvas ref={ref} className="minimap" width={SIZE} height={SIZE} onClick={() => s.ui.open("map")} />;
});
