import { observer } from "mobx-react-lite";
import { tr } from "../../core/i18n";
import { fmtNum } from "../../core/format";
import { useStore } from "../stores";
import { Bar, click } from "../common";
import { Glyph, hex } from "../icons";
import { Minimap } from "./Minimap";
import { CLASSES } from "../../game/classes";
import { objectiveCountText, objectiveNeeded } from "../../game/quests/gen";

/** Отслеживаемое задание: теперь живёт в меню, на экране от него только звёздочка на миникарте. */
export const QuestTracker = observer(() => {
  const s = useStore();
  const sess = s.session;
  const char = s.char;
  if (!sess || !char) return null;
  void char.rev;
  const id = char.data.quests.tracked;
  if (!id) return null;
  const q = sess.quests.get(id);
  if (!q) return null;
  const pr = sess.quests.progress(id);
  const complete = sess.quests.isComplete(id);
  return (
    <div className="quest-tracker" onClick={() => s.ui.open("quests")}>
      <b>{tr(q.title)}</b>
      {complete ? (
        <div className="good">✓ {tr({ ru: "Сдать задание", en: "Turn in" })}</div>
      ) : (
        q.objectives.map((o, i) => (
          <div key={i} style={{ opacity: pr[i] >= objectiveNeeded(o) ? 0.5 : 1 }}>
            • {tr(o.label)} {objectiveCountText(o, pr[i] ?? 0)}
          </div>
        ))
      )}
      {s.hud.compass && (
        <div className="row" style={{ marginTop: 4, gap: 6 }}>
          <div className="compass" style={{ transform: `rotate(${-s.hud.compass.angle}rad)` }}>
            <Glyph name="up" size={18} color="#ffd24a" />
          </div>
          <span>{Math.round(s.hud.compass.dist)} {tr({ ru: "м", en: "m" })}</span>
        </div>
      )}
    </div>
  );
});

export const Hud = observer(() => {
  const s = useStore();
  const h = s.hud;
  const char = s.char;
  if (!char) return null;
  const cls = CLASSES[char.data.classId];
  const ui = s.ui;
  return (
    <div className={`hud${h.coop ? " coop-on" : ""}`} style={{ ["--hud-scale" as string]: s.settings.hudScale }}>
      <div className="hud-player">
        <div className="hud-portrait" style={{ background: `radial-gradient(circle at 40% 35%, ${hex(char.data.look.fur)}, ${hex(cls.color)})` }} onClick={click(() => ui.open("character"))}>
          <Glyph name="cat" size={30} color="#fff" />
          <div className="hud-level">{h.level}</div>
          {h.skillPoints > 0 && (
            <div
              className="hud-sp"
              onClick={(e) => {
                e.stopPropagation();
                ui.open("skills");
              }}
            >
              +{h.skillPoints}
            </div>
          )}
        </div>
        <div className="hud-bars">
          <Bar value={h.hp} max={h.maxHp} color="linear-gradient(90deg,#ff4a6a,#ff8a6a)" label={`${fmtNum(h.hp)} / ${fmtNum(h.maxHp)}`} height={16} secondary={h.shield} secondaryColor="#bfe8ff" glow={h.resting} />
          <Bar value={h.mp} max={h.maxMp} color="linear-gradient(90deg,#3a7aff,#6ac0ff)" label={`${fmtNum(h.mp)}`} height={11} glow={h.resting} />
          {h.coop && (
            <div style={{ marginTop: 4 }}>
              <div className="hud-name" style={{ color: "#9ae8ff" }}>
                🤝 {h.coop.name} · {h.coop.level}
              </div>
              <Bar value={h.coop.hp} max={h.coop.maxHp} color="#7ee081" height={8} />
            </div>
          )}
        </div>
      </div>
      <div className="hud-top-center">
        {h.boss && (
          <div className="hud-boss">
            <div className="hud-boss-name">
              👑 {tr(h.boss.name)} · {h.boss.level}
            </div>
            <Bar value={h.boss.hp} max={h.boss.maxHp} color="linear-gradient(90deg,#c0203a,#ff5a3a)" height={12} label={`${Math.ceil((h.boss.hp / h.boss.maxHp) * 100)}%`} />
          </div>
        )}
        {!h.boss && h.target && (
          <div className="hud-target">
            <div style={{ color: h.target.elite ? "#ffc85a" : "#ffe0d0" }}>
              {tr(h.target.name)} · {h.target.level}
            </div>
            <Bar value={h.target.hp} max={h.target.maxHp} color="#ff5a5a" height={7} />
          </div>
        )}
      </div>
      {/* Справа сверху — только миникарта и кнопка меню; всё остальное (сумка, навыки, задания, карта) — в меню */}
      <div className="hud-right">
        <Minimap />
        <div className="hud-btn hud-menu-btn" onClick={click(() => ui.open("menu"))} title="Esc">
          <Glyph name="menu" size={20} />
          {h.skillPoints > 0 && <div className="dot" />}
        </div>
      </div>
      <div className="toasts">
        {h.toasts.map((t) => (
          <div className="toast" key={t.id} style={{ borderColor: hex(t.color), opacity: Math.min(1, t.t) }}>
            {t.icon ? `${t.icon} ` : ""}
            {tr(t.text)}
          </div>
        ))}
      </div>
      <div className="hud-xp">
        <div style={{ width: `${(h.xp / Math.max(1, h.xpNeeded)) * 100}%` }} />
      </div>
      {s.settings.showFps && (
        <div className="fps">
          {h.fps} FPS · {h.playerX.toFixed(0)}, {h.playerZ.toFixed(0)}
        </div>
      )}
    </div>
  );
});
