/** Тонкие обёртки над WebGL2: программы, буферы, VAO. Никаких сторонних библиотек. */

export type GL = WebGL2RenderingContext;

export const FRAME_UBO_BINDING = 0;

/**
 * Постоянные текстурные слоты: сэмплеры с этими именами получают свой слот при создании программы,
 * а рендерер держит нужные текстуры привязанными весь кадр.
 */
export const TEX_UNIT = {
  matAlbedo: 4,
  matNormal: 5,
  heightField: 6,
  shadowMap: 7,
} as const;

const SAMPLER_UNITS: Record<string, number> = {
  uMatAlbedo: TEX_UNIT.matAlbedo,
  uMatNormal: TEX_UNIT.matNormal,
  uHeightField: TEX_UNIT.heightField,
  uShadowMap: TEX_UNIT.shadowMap,
};

export class Program {
  readonly program: WebGLProgram;
  private uniforms = new Map<string, WebGLUniformLocation | null>();

  constructor(
    readonly gl: GL,
    vs: string,
    fs: string,
    readonly name = "program",
  ) {
    const v = compile(gl, gl.VERTEX_SHADER, vs, name);
    const f = compile(gl, gl.FRAGMENT_SHADER, fs, name);
    const p = gl.createProgram()!;
    gl.attachShader(p, v);
    gl.attachShader(p, f);
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
      const log = gl.getProgramInfoLog(p);
      throw new Error(`Link error in ${name}: ${log}`);
    }
    gl.deleteShader(v);
    gl.deleteShader(f);
    this.program = p;
    const idx = gl.getUniformBlockIndex(p, "Frame");
    if (idx !== gl.INVALID_INDEX) gl.uniformBlockBinding(p, idx, FRAME_UBO_BINDING);
    gl.useProgram(p);
    for (const [name, unit] of Object.entries(SAMPLER_UNITS)) {
      const l = gl.getUniformLocation(p, name);
      if (l) gl.uniform1i(l, unit);
    }
  }

  use() {
    this.gl.useProgram(this.program);
    return this;
  }

  loc(name: string): WebGLUniformLocation | null {
    let l = this.uniforms.get(name);
    if (l === undefined) {
      l = this.gl.getUniformLocation(this.program, name);
      this.uniforms.set(name, l);
    }
    return l;
  }

  f1(name: string, v: number) {
    this.gl.uniform1f(this.loc(name), v);
  }
  f2(name: string, a: number, b: number) {
    this.gl.uniform2f(this.loc(name), a, b);
  }
  f3(name: string, a: number, b: number, c: number) {
    this.gl.uniform3f(this.loc(name), a, b, c);
  }
  f4(name: string, a: number, b: number, c: number, d: number) {
    this.gl.uniform4f(this.loc(name), a, b, c, d);
  }
  i1(name: string, v: number) {
    this.gl.uniform1i(this.loc(name), v);
  }
  m4(name: string, m: Float32Array) {
    this.gl.uniformMatrix4fv(this.loc(name), false, m);
  }
  v4a(name: string, arr: Float32Array) {
    this.gl.uniform4fv(this.loc(name), arr);
  }
}

function compile(gl: GL, type: number, src: string, name: string): WebGLShader {
  const s = gl.createShader(type)!;
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(s) ?? "";
    const lines = src.split("\n").map((l, i) => `${String(i + 1).padStart(4)}: ${l}`);
    // Показываем контекст ошибки
    const m = /ERROR: \d+:(\d+)/.exec(log);
    const ln = m ? parseInt(m[1]) : 0;
    const ctx = ln ? lines.slice(Math.max(0, ln - 4), ln + 3).join("\n") : "";
    throw new Error(`Shader compile error in ${name} (${type === gl.VERTEX_SHADER ? "VS" : "FS"}):\n${log}\n${ctx}`);
  }
  return s;
}

/** Статический буфер. */
export function staticBuffer(gl: GL, target: number, data: ArrayBufferView): WebGLBuffer {
  const b = gl.createBuffer()!;
  gl.bindBuffer(target, b);
  gl.bufferData(target, data, gl.STATIC_DRAW);
  return b;
}

/** Растущий динамический буфер для инстансов и частиц. */
export class DynamicBuffer {
  readonly buffer: WebGLBuffer;
  private capacity = 0;

  constructor(
    readonly gl: GL,
    readonly target: number = gl.ARRAY_BUFFER,
  ) {
    this.buffer = gl.createBuffer()!;
  }

  upload(data: Float32Array | Uint8Array | Uint16Array, length: number = data.length) {
    const gl = this.gl;
    const bytes = length * data.BYTES_PER_ELEMENT;
    gl.bindBuffer(this.target, this.buffer);
    if (bytes > this.capacity) {
      this.capacity = Math.max(bytes, Math.ceil(this.capacity * 1.5));
      gl.bufferData(this.target, this.capacity, gl.DYNAMIC_DRAW);
    }
    gl.bufferSubData(this.target, 0, data, 0, length);
  }
}

/** Описание вершинного атрибута. */
export interface AttribSpec {
  loc: number;
  size: number;
  type: number;
  normalized?: boolean;
  stride: number;
  offset: number;
  divisor?: number;
}

export function setupAttribs(gl: GL, buffer: WebGLBuffer, specs: AttribSpec[]) {
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  for (const s of specs) {
    gl.enableVertexAttribArray(s.loc);
    if ((s.type === gl.INT || s.type === gl.UNSIGNED_INT) && !s.normalized) {
      gl.vertexAttribIPointer(s.loc, s.size, s.type, s.stride, s.offset);
    } else {
      gl.vertexAttribPointer(s.loc, s.size, s.type, !!s.normalized, s.stride, s.offset);
    }
    gl.vertexAttribDivisor(s.loc, s.divisor ?? 0);
  }
}

/** Расположение атрибутов (одинаковое во всех шейдерах мешей). */
export const ATTR = {
  pos: 0,
  normal: 1,
  color: 2,
  misc: 3,
  i0: 4,
  i1: 5,
  i2: 6,
  i3: 7,
  i4: 8,
  i5: 9,
  i6: 10,
} as const;

/**
 * Упакованная статическая геометрия: position f32x3, normal i8x4, color u8x4, misc u8x4 (24 байта).
 * misc: x — сила покачивания на ветру, y — эмиссия, z — маска тонирования, w — материал + 1 (0 — без текстуры).
 * У ландшафта иначе: color.a, misc.zw и normal.w — веса четырёх материалов палитры чанка.
 */
export interface PackedGeometry {
  vertexData: ArrayBuffer;
  vertexCount: number;
  indices: Uint16Array | Uint32Array;
}

export const VERTEX_STRIDE = 24;

export class GpuMesh {
  readonly vao: WebGLVertexArrayObject;
  readonly vbo: WebGLBuffer;
  readonly ibo: WebGLBuffer;
  readonly indexCount: number;
  readonly indexType: number;

  constructor(
    readonly gl: GL,
    geo: PackedGeometry,
    instanceSetup?: (gl: GL) => void,
  ) {
    this.vao = gl.createVertexArray()!;
    gl.bindVertexArray(this.vao);
    this.vbo = staticBuffer(gl, gl.ARRAY_BUFFER, new Uint8Array(geo.vertexData));
    setupAttribs(gl, this.vbo, [
      { loc: ATTR.pos, size: 3, type: gl.FLOAT, stride: VERTEX_STRIDE, offset: 0 },
      { loc: ATTR.normal, size: 4, type: gl.BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 12 },
      { loc: ATTR.color, size: 4, type: gl.UNSIGNED_BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 16 },
      { loc: ATTR.misc, size: 4, type: gl.UNSIGNED_BYTE, normalized: true, stride: VERTEX_STRIDE, offset: 20 },
    ]);
    this.ibo = staticBuffer(gl, gl.ELEMENT_ARRAY_BUFFER, geo.indices);
    this.indexCount = geo.indices.length;
    this.indexType = geo.indices instanceof Uint32Array ? gl.UNSIGNED_INT : gl.UNSIGNED_SHORT;
    if (instanceSetup) instanceSetup(gl);
    gl.bindVertexArray(null);
  }

  draw() {
    const gl = this.gl;
    gl.bindVertexArray(this.vao);
    gl.drawElements(gl.TRIANGLES, this.indexCount, this.indexType, 0);
  }

  drawInstanced(count: number) {
    if (count <= 0) return;
    const gl = this.gl;
    gl.bindVertexArray(this.vao);
    gl.drawElementsInstanced(gl.TRIANGLES, this.indexCount, this.indexType, 0, count);
  }

  dispose() {
    const gl = this.gl;
    gl.deleteVertexArray(this.vao);
    gl.deleteBuffer(this.vbo);
    gl.deleteBuffer(this.ibo);
  }
}
