/**
 * Смена дня и ночи: цвета неба и тумана, солнце и луна, погода и цветокоррекция кадра.
 * Цвета ключей заданы в sRGB (как в палитрах художников), в линейное пространство их переводит рендерер.
 */
import { clamp01, hexToRgb, lerp, smoothstep } from "../core/math";

type RGB = [number, number, number];

interface Key {
  t: number;
  sky: RGB;
  horizon: RGB;
  ground: RGB;
  sun: RGB;
  sunI: number;
  amb: number;
  /** Экспозиция кадра. */
  exp: number;
  /** Тонирование теней и светов (0.5 — нейтрально). */
  shT: RGB;
  liT: RGB;
}

const K = (t: number, sky: number, horizon: number, ground: number, sun: number, sunI: number, amb: number, exp: number, shT: number, liT: number): Key => ({
  t,
  sky: hexToRgb(sky),
  horizon: hexToRgb(horizon),
  ground: hexToRgb(ground),
  sun: hexToRgb(sun),
  sunI,
  amb,
  exp,
  shT: hexToRgb(shT),
  liT: hexToRgb(liT),
});

// t: 0 — полночь, 0.25 — рассвет, 0.5 — полдень, 0.75 — закат
const KEYS: Key[] = [
  K(0.0, 0x0b1336, 0x1f2d5c, 0x10131d, 0x9fb4ff, 0.34, 0.5, 1.5, 0x6a7ab0, 0x8088a8),
  K(0.19, 0x1a2758, 0x3a3f70, 0x161822, 0xa8b0ff, 0.3, 0.52, 1.45, 0x6a74aa, 0x8888a8),
  K(0.245, 0x5a70c0, 0xffa877, 0x3a3434, 0xffa060, 0.75, 0.55, 1.2, 0x7070a0, 0x9c8070),
  K(0.31, 0x4f92e8, 0xd4e8ff, 0x4f5a3e, 0xffe8c8, 1.05, 0.62, 1.05, 0x767ea0, 0x8a8278),
  K(0.5, 0x3d86e6, 0xc8e4ff, 0x56633f, 0xfff4e4, 1.2, 0.66, 1.0, 0x7a80a0, 0x868078),
  K(0.69, 0x4884dc, 0xd4e4fa, 0x56633f, 0xffe4c0, 1.05, 0.62, 1.05, 0x7a7ea0, 0x8a8074),
  K(0.755, 0x5a4ea0, 0xff8a58, 0x3a3030, 0xff8248, 0.8, 0.52, 1.18, 0x6e6aa6, 0xa07c68),
  K(0.81, 0x1d2355, 0x423668, 0x1a1a24, 0xa8a8ff, 0.3, 0.5, 1.45, 0x6a70aa, 0x8888a8),
  K(1.0, 0x0b1336, 0x1f2d5c, 0x10131d, 0x9fb4ff, 0.34, 0.5, 1.5, 0x6a7ab0, 0x8088a8),
];

/** Атмосфера биомов: облачность, северное сияние, туман в низинах, снег. */
export interface Atmosphere {
  clouds: number;
  aurora: number;
  valleyFog: number;
  snow: number;
}
const A = (clouds: number, aurora: number, valleyFog: number, snow = 0): Atmosphere => ({ clouds, aurora, valleyFog, snow });
export const BIOME_ATMOSPHERE: Record<string, Atmosphere> = {
  meadow: A(0.42, 0, 0.3),
  forest: A(0.5, 0, 0.55),
  birch: A(0.45, 0, 0.4),
  sakura: A(0.35, 0.1, 0.35),
  autumn: A(0.55, 0, 0.5),
  jungle: A(0.6, 0, 0.65),
  savanna: A(0.25, 0, 0.1),
  desert: A(0.12, 0, 0.03),
  swamp: A(0.7, 0, 0.95),
  taiga: A(0.55, 0.7, 0.55, 0.45),
  snow: A(0.6, 1, 0.35, 1),
  mountain: A(0.55, 0.3, 0.4, 0.3),
  beach: A(0.3, 0, 0.12),
  volcanic: A(0.72, 0, 0.35),
  crystal: A(0.3, 0.6, 0.3),
  shadow: A(0.75, 0.2, 0.85),
  void: A(0.2, 0.8, 0.5),
  candy: A(0.5, 0.2, 0.2),
};

const norm = (v: RGB): RGB => {
  const l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
};

export class Environment {
  /** 0 — полночь, 0.25 — рассвет, 0.5 — полдень, 0.75 — закат. */
  timeOfDay = 0.36;
  dayLength = 20 * 60;
  dungeon = false;
  biomeFog: RGB = [0.75, 0.88, 1.0];
  private targetFog: RGB = [0.75, 0.88, 1.0];

  /** Направление основного света (солнце днём, луна ночью). */
  sunDir: RGB = [0.3, 0.8, 0.4];
  sunColor: RGB = [1, 1, 1];
  sunIntensity = 1;
  ambient = 0.7;
  /** Настоящее направление на солнце (ночью под горизонтом) и на луну. */
  sunTrue: RGB = [0.3, 0.8, 0.4];
  moonDir: RGB = [-0.3, 0.6, -0.4];
  /** 0..1: насколько видна луна. */
  moonVis = 0;
  /** Сила теней: падает, когда свет переходит от солнца к луне. */
  shadowStrength = 1;
  sky: RGB = [0.3, 0.5, 0.9];
  horizon: RGB = [0.8, 0.9, 1];
  ground: RGB = [0.3, 0.3, 0.25];
  night = 0;
  // Погода и атмосфера
  cloudCover = 0.45;
  private targetCloud = 0.45;
  windX = 0.8;
  windZ = 0.35;
  windStrength = 0.6;
  /** Северное сияние (0..1), задаётся биомом. */
  aurora = 0;
  private targetAurora = 0;
  /** Туман в низинах (утром сильнее). */
  valleyFog = 0.3;
  private biomeValley = 0.3;
  wetness = 0;
  snow = 0;
  private targetSnow = 0;
  // Цветокоррекция
  exposure = 1;
  shadowTint: RGB = [0.46, 0.48, 0.56];
  lightTint: RGB = [0.54, 0.52, 0.47];
  saturation = 1.1;

  setBiomeFog(hex: number) {
    this.targetFog = hexToRgb(hex);
  }

  /** Атмосфера биома: облачность, сияние, туман в низинах, снег. */
  setBiomeAtmosphere(o: Atmosphere) {
    this.targetCloud = o.clouds;
    this.targetAurora = o.aurora;
    this.biomeValley = o.valleyFog;
    this.targetSnow = o.snow;
  }

  update(dt: number) {
    if (!this.dungeon) this.timeOfDay = (this.timeOfDay + dt / this.dayLength) % 1;
    const k = 1 - Math.exp(-dt * 0.8);
    for (let i = 0; i < 3; i++) this.biomeFog[i] = lerp(this.biomeFog[i], this.targetFog[i], k);
    const ks = 1 - Math.exp(-dt * 0.25);
    this.cloudCover = lerp(this.cloudCover, this.targetCloud, ks);
    this.aurora = lerp(this.aurora, this.targetAurora, ks);
    this.snow = lerp(this.snow, this.targetSnow, ks);
    if (this.dungeon) {
      this.sunDir = norm([0.35, 0.9, 0.25]);
      this.sunTrue = this.sunDir;
      this.sunColor = [0.62, 0.56, 0.74];
      this.sunIntensity = 0.3;
      this.ambient = 0.62;
      this.sky = [0.03, 0.03, 0.05];
      this.horizon = [0.05, 0.04, 0.07];
      this.ground = [0.16, 0.13, 0.18];
      this.night = 1;
      this.moonVis = 0;
      this.shadowStrength = 0.6;
      this.exposure = 1.6;
      this.shadowTint = [0.44, 0.44, 0.58];
      this.lightTint = [0.58, 0.52, 0.44];
      this.saturation = 1.08;
      return;
    }
    const t = this.timeOfDay;
    let a = KEYS[0],
      b = KEYS[1];
    for (let i = 0; i < KEYS.length - 1; i++) {
      if (t >= KEYS[i].t && t <= KEYS[i + 1].t) {
        a = KEYS[i];
        b = KEYS[i + 1];
        break;
      }
    }
    const f = smoothstep(0, 1, clamp01((t - a.t) / (b.t - a.t)));
    const mix = (x: RGB, y: RGB): RGB => [lerp(x[0], y[0], f), lerp(x[1], y[1], f), lerp(x[2], y[2], f)];
    this.sky = mix(a.sky, b.sky);
    this.horizon = mix(a.horizon, b.horizon);
    this.ground = mix(a.ground, b.ground);
    this.sunColor = mix(a.sun, b.sun);
    this.sunIntensity = lerp(a.sunI, b.sunI, f);
    this.ambient = lerp(a.amb, b.amb, f);
    this.exposure = lerp(a.exp, b.exp, f);
    this.shadowTint = mix(a.shT, b.shT);
    this.lightTint = mix(a.liT, b.liT);
    // Солнце идёт по наклонной дуге, луна — напротив и чуть в стороне
    const ang = (t - 0.25) * Math.PI * 2;
    const sun = norm([Math.cos(ang) * 0.78, Math.sin(ang), 0.38]);
    this.sunTrue = sun;
    const moon = norm([-Math.cos(ang) * 0.62 + 0.12, -Math.sin(ang) * 0.9 + 0.08, -0.45]);
    this.moonDir = moon;
    const day = smoothstep(-0.1, 0.12, sun[1]);
    this.night = 1 - day;
    this.moonVis = smoothstep(-0.05, 0.12, moon[1]) * (1 - smoothstep(0.0, 0.25, sun[1]));
    // Основной свет: солнце, пока оно заметно над горизонтом, иначе луна.
    // Переключение прячем: интенсивность и тени проседают около момента смены.
    const sunUp = sun[1] > 0.04;
    const dir: RGB = sunUp ? sun : moon[1] > 0.1 ? moon : norm([moon[0], 0.1 + Math.max(0, moon[1]), moon[2]]);
    const edge = Math.abs(sun[1] - 0.04);
    const fade = smoothstep(0.0, 0.1, edge);
    this.sunDir = dir;
    this.sunIntensity *= 0.35 + 0.65 * fade;
    // Низкое солнце — длинные тени, но не бесконечные
    if (this.sunDir[1] < 0.18) this.sunDir = norm([this.sunDir[0], 0.18, this.sunDir[2]]);
    this.shadowStrength = fade * (sunUp ? 0.9 : 0.6);
    // Туман с оттенком биома (днём сильнее)
    const bf = 0.5 * day;
    this.horizon = [lerp(this.horizon[0], this.biomeFog[0], bf), lerp(this.horizon[1], this.biomeFog[1], bf), lerp(this.horizon[2], this.biomeFog[2], bf)];
    // Утренний туман в низинах
    const morning = Math.exp(-(((t - 0.27) / 0.06) ** 2));
    this.valleyFog = this.biomeValley * (0.35 + 0.65 * morning) + 0.15 * this.night;
    this.wetness = morning * 0.5;
    this.saturation = 1.12 - this.night * 0.12;
    // Ветер медленно меняет направление
    const wa = t * 11.0;
    this.windX = Math.cos(wa) * 0.9 + 0.3;
    this.windZ = Math.sin(wa * 0.7) * 0.6 + 0.2;
    this.windStrength = 0.5 + 0.3 * Math.sin(t * 40.0) * Math.sin(t * 17.0);
  }
}
