/** Кооператив по WebRTC: приглашение (хост, в игре) и присоединение (гость, из меню). */
import { observer } from "mobx-react-lite";
import { useEffect, useMemo, useRef, useState } from "react";
import { tr, type Txt } from "../../core/i18n";
import { useStore } from "../stores";
import { Btn, Panel } from "../common";
import { hex } from "../icons";
import { CLASSES } from "../../game/classes";
import { CLASS_IDS, modeLabel, type ClassId, type ModeConfig } from "../../game/types";
import { CharacterStore, newCharacter } from "../../game/character";
import { catName } from "../../game/world/names";
import { Rng } from "../../core/rng";
import { encodeQr, qrPath } from "../../core/qr";
import { RELAY_CHANNEL } from "../../net/signal";

const CLASS_ICONS = ["⚔️", "🔮", "🏹", "🗡️", "✨", "💀", "🌿"];

async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand("copy");
      ta.remove();
      return ok;
    } catch {
      return false;
    }
  }
}

/** QR-код ссылки: второй телефон сканирует его камерой. */
const QrView = ({ text }: { text: string }) => {
  const qr = useMemo(() => {
    try {
      return encodeQr(text, "L");
    } catch {
      return null;
    }
  }, [text]);
  if (!qr) return null;
  const n = qr.size + 8;
  return (
    <svg className="qr" viewBox={`0 0 ${n} ${n}`} shapeRendering="crispEdges" role="img" aria-label="QR">
      <rect width={n} height={n} fill="#fff" />
      <path d={qrPath(qr)} fill="#120c1e" />
    </svg>
  );
};

const CodeBox = ({ code, link, hint }: { code: string; link?: string; hint: Txt }) => {
  const [copied, setCopied] = useState<string | null>(null);
  const [qr, setQr] = useState(true);
  const copy = async (what: string, text: string) => {
    if (await copyText(text)) {
      setCopied(what);
      setTimeout(() => setCopied(null), 1600);
    }
  };
  const canShare = typeof navigator !== "undefined" && typeof navigator.share === "function";
  return (
    <div className="code-box">
      <div className="muted" style={{ fontSize: 13, marginBottom: 6 }}>
        {tr(hint)}
      </div>
      {link && qr && (
        <div className="qr-wrap">
          <QrView text={link} />
          <div className="muted" style={{ fontSize: 12 }}>
            {tr({ ru: "Отсканируйте камерой второго телефона", en: "Scan with the other phone's camera" })}
          </div>
        </div>
      )}
      <textarea readOnly value={code} onFocus={(e) => e.currentTarget.select()} rows={3} />
      <div className="row" style={{ marginTop: 8 }}>
        <Btn small kind="primary" onClick={() => copy("code", code)}>
          📋 {copied === "code" ? tr({ ru: "Скопировано!", en: "Copied!" }) : tr({ ru: "Копировать код", en: "Copy code" })}
        </Btn>
        {link && (
          <Btn small onClick={() => copy("link", link)}>
            🔗 {copied === "link" ? tr({ ru: "Скопировано!", en: "Copied!" }) : tr({ ru: "Копировать ссылку", en: "Copy link" })}
          </Btn>
        )}
        {link && (
          <Btn small kind="ghost" onClick={() => setQr(!qr)}>
            ▦ {qr ? tr({ ru: "Скрыть QR", en: "Hide QR" }) : "QR"}
          </Btn>
        )}
        {canShare && (
          <Btn small onClick={() => void navigator.share({ title: tr({ ru: "Котоверсум — кооператив", en: "Catverse — co-op" }), text: link ?? code, url: link }).catch(() => undefined)}>
            📤 {tr({ ru: "Поделиться", en: "Share" })}
          </Btn>
        )}
      </div>
    </div>
  );
};

const Spinner = ({ text }: { text: Txt }) => (
  <div className="row" style={{ gap: 10, padding: "10px 0" }}>
    <span className="paw-spin">🐾</span>
    <span>{tr(text)}</span>
  </div>
);

const ErrorLine = observer(() => {
  const s = useStore();
  const e = s.coop.error;
  if (!e) return null;
  return <div className="coop-error">⚠️ {tr(e)}</div>;
});

/** Панель в игре. */
export const CoopPanel = observer(() => {
  const s = useStore();
  const c = s.coop;
  const sess = s.session;
  const [answer, setAnswer] = useState("");
  const guest = sess?.isGuest;
  const net = sess?.net;
  return (
    <Panel title={{ ru: "Кооператив", en: "Co-op" }} onClose={() => s.ui.close()}>
      <div className="col coop">
        {guest ? (
          <>
            <div>
              🤝 {tr({ ru: "Вы в гостях в мире", en: "You are visiting the world of" })} <b>{net?.partnerName ?? c.partnerName}</b>.
            </div>
            <div className="muted" style={{ fontSize: 14 }}>
              {tr({
                ru: "Опыт, уровни, добыча и рыбки остаются у вашего кота. Задания и открытые места в этом мире не сохраняются. Вход в подземелья подтверждает хост.",
                en: "XP, levels, loot and fish stay with your cat. Quests and discoveries in this world are not saved. The host confirms dungeon entry.",
              })}
            </div>
            {!net && <div className="coop-error">{tr({ ru: "Соединение закрыто — вы играете в одиночку.", en: "Connection closed — you are playing solo." })}</div>}
            {net && (
              <Btn kind="danger" onClick={() => c.close()}>
                🔌 {tr({ ru: "Отключиться", en: "Disconnect" })}
              </Btn>
            )}
          </>
        ) : c.status === "connected" && net ? (
          <>
            <div style={{ fontSize: 17 }}>
              🤝 {tr({ ru: "Вы играете вместе с", en: "Playing together with" })} <b>{net.partnerName}</b>!
            </div>
            <div className="muted" style={{ fontSize: 14 }}>
              {tr({
                ru: "Враги становятся крепче, но опыт идёт обоим. Добыча у каждого своя. Друг появится рядом с вами; в подземелья вы входите вместе.",
                en: "Enemies get tougher, but both of you gain XP. Each player gets their own loot. Your friend appears next to you; you enter dungeons together.",
              })}
            </div>
            <Btn kind="danger" onClick={() => c.close()}>
              🔌 {tr({ ru: "Завершить кооператив", en: "End co-op" })}
            </Btn>
          </>
        ) : c.status === "preparing" ? (
          <Spinner text={{ ru: "Готовим приглашение…", en: "Preparing the invite…" }} />
        ) : c.status === "invite" || (c.status === "connecting" && c.role === "host") ? (
          <>
            <div className="step">
              <b>1.</b> {tr({ ru: "Отправьте другу код или ссылку (мессенджер, почта…)", en: "Send your friend the code or link (messenger, e-mail…)" })}
            </div>
            <CodeBox code={c.code} link={c.link} hint={{ ru: "Друг открывает ссылку или вставляет код: «Кооператив» → «Присоединиться».", en: "Your friend opens the link or pastes the code: “Co-op” → “Join”." }} />
            <div className="step">
              <b>2.</b> {tr({ ru: "Вставьте код ответа, который пришлёт друг:", en: "Paste the answer code your friend sends back:" })}
            </div>
            <textarea className="code-input" rows={3} value={answer} onChange={(e) => setAnswer(e.target.value)} placeholder="MAz…" />
            <ErrorLine />
            {c.status === "connecting" ? (
              <Spinner text={{ ru: "Соединяемся…", en: "Connecting…" }} />
            ) : (
              <div className="row">
                <Btn kind="primary" disabled={answer.trim().length < 20} onClick={() => void c.applyAnswer(answer)}>
                  🤝 {tr({ ru: "Подключить друга", en: "Connect friend" })}
                </Btn>
                <Btn kind="ghost" onClick={() => c.reset()}>
                  {tr({ ru: "Отмена", en: "Cancel" })}
                </Btn>
              </div>
            )}
          </>
        ) : (
          <>
            <div>
              {tr({
                ru: "Играйте вдвоём напрямую через WebRTC — без серверов. Вы — хост: друг появится в вашем мире.",
                en: "Play together directly over WebRTC — no servers. You are the host: your friend will appear in your world.",
              })}
            </div>
            <div className="muted" style={{ fontSize: 14 }}>
              {tr({
                ru: "Обмен кодами вручную: вы отправляете приглашение, друг возвращает код ответа. Для игры через интернет включите STUN в настройках (по умолчанию включён).",
                en: "Codes are exchanged manually: you send an invite, your friend returns an answer code. To play over the internet keep STUN enabled in settings (on by default).",
              })}
            </div>
            {c.status === "closed" && <div className="muted">🔌 {tr({ ru: "Соединение закрыто.", en: "Connection closed." })}</div>}
            <ErrorLine />
            <Btn kind="primary" onClick={() => sess && void c.startHost(sess, s.settings.useStun)}>
              ✉️ {tr({ ru: "Создать приглашение", en: "Create invite" })}
            </Btn>
          </>
        )}
      </div>
    </Panel>
  );
});

/** Экран меню: присоединиться к другу. */
export const CoopScreen = observer(() => {
  const s = useStore();
  const c = s.coop;
  const [code, setCode] = useState(s.joinCode ?? "");
  const [charId, setCharId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [cls, setCls] = useState<ClassId>("warrior");
  const [name, setName] = useState(() => tr(catName(new Rng(Date.now()), 0)));
  const chosen = useRef<CharacterStore | null>(null);
  const inv = c.invite;

  useEffect(() => {
    // Ссылка-приглашение: сразу разбираем код
    if (s.joinCode) {
      void c.readInvite(s.joinCode);
      s.joinCode = null;
    }
  }, [s, c]);

  useEffect(() => {
    c.onWelcome = (w) => {
      const ch = chosen.current;
      if (!ch) return;
      s.play(ch, { seed: w.seed, mode: w.mode, x: w.pos.x, z: w.pos.z, dungeon: w.dungeon, dungeonReturn: w.dungeonReturn }, c);
    };
    return () => {
      c.onWelcome = null;
    };
  }, [s, c]);

  const back = () => {
    c.reset();
    s.ui.go("menu");
  };

  const join = (id: string) => {
    const d = s.saves.load(id);
    if (!d) return;
    const ch = new CharacterStore(d);
    chosen.current = ch;
    setCharId(id);
    void c.startGuest(ch, s.settings.useStun);
  };

  const createAndJoin = () => {
    if (!inv?.host) return;
    const mode = { world: inv.host.mode.world, skills: inv.host.mode.skills, levels: inv.host.mode.levels } as ModeConfig;
    const data = newCharacter({ name: name.trim() || "Мурзик", classId: cls, mode, seed: Math.floor(Math.random() * 1e9) });
    s.saves.save(data);
    join(data.id);
  };

  const stage = c.role === "guest" ? c.status : "pick";

  return (
    <div className="menu-screen" style={{ justifyContent: "flex-start" }}>
      <div className="menu-card coop" style={{ maxWidth: 680 }}>
        <h2>🤝 {tr({ ru: "Кооператив", en: "Co-op" })}</h2>
        {stage === "pick" && !inv && (
          <>
            <div className="muted" style={{ fontSize: 14, marginBottom: 10 }}>
              {tr({
                ru: "Хотите позвать друга? Начните или продолжите игру и откройте «Меню → Кооператив». Хотите присоединиться? Вставьте код приглашения от друга:",
                en: "Want to invite a friend? Start or continue a game and open “Menu → Co-op”. Want to join? Paste your friend's invite code:",
              })}
            </div>
            <textarea className="code-input" rows={4} value={code} onChange={(e) => setCode(e.target.value)} placeholder={tr({ ru: "Код или ссылка-приглашение (MOz…)", en: "Invite code or link (MOz…)" })} />
            <ErrorLine />
            <div className="row" style={{ marginTop: 10 }}>
              <Btn onClick={back}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
              <div className="spacer" />
              <Btn kind="primary" disabled={code.trim().length < 20} onClick={() => void c.readInvite(code)}>
                {tr({ ru: "Далее", en: "Next" })} →
              </Btn>
            </div>
          </>
        )}
        {stage === "pick" && inv && (
          <>
            <div className="coop-host">
              <b>{inv.name}</b> {tr({ ru: "приглашает вас в свой мир", en: "invites you to their world" })}
              {inv.host && (
                <div className="muted" style={{ fontSize: 13 }}>
                  {tr(CLASSES[inv.host.classId as ClassId]?.name ?? { ru: "?", en: "?" })} · {tr({ ru: "ур.", en: "Lv" })} {inv.host.level} · {tr(modeLabel(inv.host.mode as ModeConfig))}
                </div>
              )}
            </div>
            <div className="label" style={{ marginTop: 12 }}>
              {tr({ ru: "Выберите котика", en: "Choose your cat" })}
            </div>
            {!creating && (
              <div className="col" style={{ gap: 6 }}>
                {s.saves.list.map((m) => (
                  <div key={m.id} className="save-row" onClick={() => join(m.id)}>
                    <div className="save-dot" style={{ background: hex(m.fur) }} />
                    <div style={{ flex: 1 }}>
                      <b>{m.name}</b> · {tr(CLASSES[m.classId as ClassId]?.name ?? { ru: "?", en: "?" })} {m.level}
                      {inv.host && Math.abs(m.level - inv.host.level) > 8 && (
                        <span className="muted" style={{ fontSize: 12 }}>
                          {" "}
                          ⚠️ {tr({ ru: "большая разница уровней", en: "big level gap" })}
                        </span>
                      )}
                    </div>
                    <span>→</span>
                  </div>
                ))}
                <Btn onClick={() => setCreating(true)}>✨ {tr({ ru: "Новый котик", en: "New cat" })}</Btn>
              </div>
            )}
            {creating && (
              <>
                <div className="class-grid">
                  {CLASS_IDS.map((id, i) => (
                    <div key={id} className={`class-card${cls === id ? " sel" : ""}`} onClick={() => setCls(id)} style={{ borderColor: cls === id ? hex(CLASSES[id].color) : undefined }}>
                      <div style={{ fontSize: 24 }}>{CLASS_ICONS[i]}</div>
                      <div className="cname">{tr(CLASSES[id].name)}</div>
                    </div>
                  ))}
                </div>
                <div className="row" style={{ marginTop: 10, flexWrap: "nowrap" }}>
                  <input type="text" value={name} maxLength={20} onChange={(e) => setName(e.target.value)} />
                  <Btn kind="primary" onClick={createAndJoin}>
                    🐾 {tr({ ru: "Создать и войти", en: "Create & join" })}
                  </Btn>
                </div>
              </>
            )}
            <ErrorLine />
            <div className="row" style={{ marginTop: 12 }}>
              <Btn onClick={() => (creating ? setCreating(false) : c.reset())}>← {tr({ ru: "Назад", en: "Back" })}</Btn>
            </div>
          </>
        )}
        {stage === "preparing" && <Spinner text={{ ru: "Готовим ответ…", en: "Preparing the answer…" }} />}
        {stage === "answer" && (
          <>
            <CodeBox code={c.code} link={c.link} hint={{ ru: "Отправьте другу код или ссылку ответа (или покажите QR). Игра начнётся сама, как только он его применит.", en: "Send your friend the answer code or link (or show the QR). The game starts automatically once they apply it." }} />
            <Spinner text={{ ru: `Ждём, пока ${c.partnerName} вставит код…`, en: `Waiting for ${c.partnerName} to paste the code…` }} />
          </>
        )}
        {stage === "connecting" && <Spinner text={{ ru: "Соединяемся с другом…", en: "Connecting to your friend…" }} />}
        {stage === "connected" && <Spinner text={{ ru: "Входим в мир друга…", en: "Entering your friend's world…" }} />}
        {(stage === "error" || stage === "closed") && (
          <>
            <ErrorLine />
            {stage === "closed" && <div className="muted">🔌 {tr({ ru: "Соединение закрыто.", en: "Connection closed." })}</div>}
          </>
        )}
        {stage !== "pick" && (
          <div className="row" style={{ marginTop: 12 }}>
            <Btn onClick={back}>← {tr({ ru: "В меню", en: "Menu" })}</Btn>
            {(stage === "error" || stage === "closed") && <Btn onClick={() => c.reset()}>↻ {tr({ ru: "Заново", en: "Retry" })}</Btn>}
          </div>
        )}
        {charId === null ? null : null}
      </div>
    </div>
  );
});

/** Вкладка, открытая по ссылке-ответу: передаём код во вкладку хоста этого же браузера. */
export const AnswerRelay = observer(({ code }: { code: string }) => {
  const s = useStore();
  const [state, setState] = useState<"sending" | "done" | "nohost">("sending");
  useEffect(() => {
    if (typeof BroadcastChannel === "undefined") {
      setState("nohost");
      return;
    }
    const ch = new BroadcastChannel(RELAY_CHANNEL);
    let acked = false;
    ch.onmessage = (ev) => {
      if ((ev.data as { t?: string })?.t === "ack") {
        acked = true;
        setState("done");
      }
    };
    ch.postMessage({ t: "answer", code });
    const t = setTimeout(() => {
      if (!acked) setState("nohost");
    }, 2500);
    return () => {
      clearTimeout(t);
      ch.close();
    };
  }, [code]);
  return (
    <div className="menu-screen relay">
      <div className="menu-card coop" style={{ maxWidth: 560 }}>
        <h2>🤝 {tr({ ru: "Ответ друга", en: "Friend's answer" })}</h2>
        {state === "sending" && <Spinner text={{ ru: "Передаём ответ во вкладку с игрой…", en: "Passing the answer to the game tab…" }} />}
        {state === "done" && (
          <div style={{ fontSize: 16, lineHeight: 1.5 }}>
            ✅ {tr({ ru: "Готово! Ответ передан в игру — вернитесь во вкладку с игрой, друг появится рядом с вами. Эту вкладку можно закрыть.", en: "Done! The answer was passed to the game — switch back to the game tab, your friend will appear next to you. You can close this tab." })}
          </div>
        )}
        {state === "nohost" && (
          <>
            <div className="muted" style={{ fontSize: 14, marginBottom: 8 }}>
              {tr({
                ru: "Не нашли вкладку с приглашением в этом браузере. Скопируйте код и вставьте его в игре: «Меню → Кооператив → код ответа».",
                en: "No tab with an open invite was found in this browser. Copy the code and paste it in the game: “Menu → Co-op → answer code”.",
              })}
            </div>
            <CodeBox code={code} hint={{ ru: "Код ответа друга", en: "Your friend's answer code" }} />
          </>
        )}
        <div className="row" style={{ marginTop: 12 }}>
          <Btn onClick={() => (s.relayAnswer = null)}>🏠 {tr({ ru: "Главное меню", en: "Main menu" })}</Btn>
        </div>
      </div>
    </div>
  );
});
