export function familyFor(id: string): Family {
  return FAMILIES[id] ?? FAMILIES.alley;
}

export function enemyName(fam: Family, role: Role, elite: boolean): Txt {
  const n = ROLES[role].noun;
  const base: Txt = { ru: `${fam.adj[n.g]} ${n.ru}`, en: `${fam.adj.en} ${n.en}` };
  if (!elite) return base;
  const pre: Adj = adj("Матёр", "Grizzled");
  return { ru: `${pre[n.g]} ${base.ru.charAt(0).toLowerCase()}${base.ru.slice(1)}`, en: `${pre.en} ${base.en}` };
}

export function enemyLook(rng: Rng, fam: Family, role: Role, elite: boolean, boss: boolean): CatLook {
  const base: CatLook = { ...BASE_LOOK, collar: undefined, bell: false, ...fam.look(rng) };
  base.size = fam.size * ROLES[role].size * rng.range(0.93, 1.07) * (elite ? 1.3 : 1) * (boss ? 1.9 : 1);
  if (role === "kitten") base.headSize = 1.2;
  if (role === "tank" && base.hat === "none") {
    base.hat = "helmet";
    base.hatColor = 0x8a8a90;
  }
  if (role === "caster" && base.weapon === "none") {
    base.weapon = "staff";
    base.weaponColor = ELEMENT_INFO[fam.element].color;
  }
  if (role === "support" && base.weapon === "none") {
    base.weapon = "tome";
    base.weaponColor = 0xfff0a0;
  }
  if (role === "summoner") base.bulk = (base.bulk ?? 1) * 1.2;
  if (elite && base.glow === undefined) base.glow = 0xff5a3a;
  if (boss) {
    base.hat = base.hat === "none" ? "crown" : base.hat;
    base.hatColor = base.hat === "crown" ? 0xf2c84a : base.hatColor;
    base.glow = base.glow ?? 0xff3a3a;
  }
  if (base.fur2 === undefined) base.fur2 = darken(base.fur, 0.5);
  return base;
}

/** Навык врага на базе общего DSL. */
export function enemySkill(id: string, delivery: Delivery, element: Element, anim: CatAction, over: Partial<SkillParams> = {}, onHit: OnHit[] = [], extra: Partial<SkillDef> = {}): SkillDef {
  const info = DELIVERY_INFO[delivery];
  const params: SkillParams = { ...BASE_PARAMS, ...info.params, ...over };
  const ei = ELEMENT_INFO[element];
  return {
    id,
    name: { ru: "", en: "" },
    delivery,
    element,
    params,
    onHit,
    homing: false,
    returning: false,
    echo: null,
    ground: null,
    anim,
    visual: { color: ei.color, color2: ei.color2, shape: ei.shapes[0], size: 1, trail: true, glow: 0.8, style: 0 },
    tier: 0,
    melee: info.melee,
    target: info.target,
    ...extra,
  };
}

/** Набор способностей врага по роли и стихии. */
export function roleSkills(role: Role, fam: Family, elite: boolean, rng: Rng): SkillDef[] {
  const el = fam.element;
  const el2 = fam.element2 ?? el;
  const eh = ELEMENT_INFO[el].defaultHit(0);
  const hits = eh && el !== "physical" ? [eh] : [];
  const out: SkillDef[] = [];
  switch (role) {
    case "brute":
      out.push(enemySkill("e:strike", "strike", el, rng.pick(["swipe", "bite"] as CatAction[]), { power: 1.0, cooldown: 1.5, radius: 2.3, spread: 1.6, castTime: 0.45 }, hits));
      if (elite) out.push(enemySkill("e:slam", "nova", el2, "stomp", { power: 1.5, radius: 4.5, cooldown: 7, castTime: 0.8 }, [{ k: "knockback", force: 5 }]));
      break;
    case "skirmisher":
      out.push(enemySkill("e:strike", "strike", el, "swipe", { power: 0.8, cooldown: 1.1, radius: 2.1, spread: 1.4, castTime: 0.3 }, hits));
      out.push(enemySkill("e:dash", "dash", el, "dash", { power: 1.0, range: 8, cooldown: 6, castTime: 0.5 }));
      break;
    case "ranged":
      out.push(
        enemySkill("e:shot", "projectile", el2 === "physical" ? el : el2, "throw", { power: 0.85, cooldown: 1.9, speed: 13, range: 16, castTime: 0.45 }, hits, {
          visual: { color: el === "physical" ? 0xb8a890 : ELEMENT_INFO[el].color, color2: 0x7a6a5a, shape: el === "physical" ? "yarn" : ELEMENT_INFO[el].shapes[0], size: 1, trail: true, glow: 0.5, style: 1 },
        }),
      );
      if (elite) out.push(enemySkill("e:volley", "projectile", el, "throw", { power: 0.6, count: 3, spread: 0.6, cooldown: 6, speed: 12, range: 16, castTime: 0.6 }, hits));
      break;
    case "caster": {
      const d = rng.pick(["blast", "chain", "cone"] as Delivery[]);
      out.push(enemySkill("e:bolt", "projectile", el, "point", { power: 0.8, cooldown: 2.2, speed: 12, range: 16, castTime: 0.5 }, hits));
      out.push(enemySkill("e:spell", d, el, d === "cone" ? "roar" : "raise", { power: d === "blast" ? 1.5 : 1.1, cooldown: 6, castTime: 0.9, duration: 1.0, radius: d === "cone" ? 6 : d === "blast" ? 3 : 7, count: 2 }, hits));
      break;
    }
    case "support":
      out.push(enemySkill("e:bolt", "projectile", el, "point", { power: 0.6, cooldown: 2.4, speed: 12, range: 15, castTime: 0.5 }, hits));
      out.push(enemySkill("e:heal", "heal", "holy", "pray", { power: 1.2, cooldown: 7, radius: 9, castTime: 0.8 }));
      break;
    case "summoner":
      out.push(enemySkill("e:strike", "strike", el, "swipe", { power: 0.7, cooldown: 1.6, radius: 2.1, castTime: 0.4 }));
      out.push(enemySkill("e:kittens", "summon", el, "meow", { power: 0.4, count: 2, duration: 30, cooldown: 14, castTime: 0.9 }, [], { summon: { kind: "kitten", ranged: false } }));
      break;
    case "bomber":
      out.push(enemySkill("e:boom", "nova", el === "physical" ? "fire" : el, "hiss", { power: 2.0, radius: 3.5, cooldown: 99, castTime: 0.7 }, [{ k: "knockback", force: 6 }]));
      break;
    case "tank":
      out.push(enemySkill("e:strike", "strike", el, "swipe", { power: 0.9, cooldown: 1.7, radius: 2.4, castTime: 0.5 }));
      out.push(enemySkill("e:bash", "dash", "physical", "dash", { power: 0.9, range: 6, cooldown: 8, castTime: 0.6 }, [{ k: "stun", dur: 0.9 }]));
      out.push(enemySkill("e:guard", "barrier", el, "raise", { power: 1.2, duration: 5, cooldown: 12, castTime: 0.5 }));
      break;
    case "kitten":
      out.push(enemySkill("e:nibble", "strike", el, "bite", { power: 0.6, cooldown: 1.0, radius: 1.7, castTime: 0.25 }));
      break;
  }
  return out;
}

/** Способности босса: 4–6 умений, часть открывается во второй фазе. */
export function bossSkills(fam: Family, rng: Rng): SkillDef[] {
  const el = fam.element;
  const el2 = fam.element2 ?? el;
  const eh = ELEMENT_INFO[el].defaultHit(2);
  const hits = eh ? [eh] : [];
  const list: SkillDef[] = [
    enemySkill("b:strike", "strike", el, "swipe", { power: 1.1, cooldown: 1.6, radius: 3.4, spread: 2.2, castTime: 0.55 }, hits),
    enemySkill("b:nova", "nova", el2, "stomp", { power: 1.4, radius: 6.5, cooldown: 9, castTime: 1.1 }, [{ k: "knockback", force: 6 }]),
    enemySkill("b:blast", "blast", el, "raise", { power: 1.8, radius: 3.6, count: 3, duration: 1.2, cooldown: 8, castTime: 0.8, range: 20 }, hits),
  ];
  const extra = rng.shuffle([
    enemySkill("b:rain", "rain", el, "summon", { power: 0.9, count: 14, radius: 8, duration: 3.5, cooldown: 14, castTime: 1.0, range: 20 }, hits),
    enemySkill("b:cone", "cone", el, "roar", { power: 1.5, radius: 9, spread: 1.0, cooldown: 10, castTime: 1.0 }, hits),
    enemySkill("b:leap", "leap", el2, "pounce", { power: 1.6, radius: 4.5, range: 14, cooldown: 11, castTime: 0.7 }, [{ k: "stun", dur: 0.8 }]),
    enemySkill("b:adds", "summon", el, "meow", { power: 0.5, count: 3, duration: 40, cooldown: 20, castTime: 1.0 }, [], { summon: { kind: "kitten", ranged: false } }),
    enemySkill("b:vortex", "vortex", el, "spin", { power: 0.4, radius: 7, duration: 3, cooldown: 16, castTime: 1.0, range: 18 }, [{ k: "pull", force: 3 }]),
    enemySkill("b:volley", "projectile", el, "throw", { power: 0.8, count: 7, spread: 1.6, speed: 12, range: 20, cooldown: 7, castTime: 0.7 }, hits),
  ]);
  list.push(...extra.slice(0, 3));
  return list;
}
