/** Название семейства во множественном числе (для текста квестов). */
function famPlural(famId: string): Txt {
  const f = familyFor(famId);
  return { ru: `${f.adj.p.toLowerCase()} коты`, en: `${f.adj.en} cats` };
}
function famGenPl(famId: string): Txt {
  const f = familyFor(famId);
  // родительный падеж мн.ч.: «дворовых котов»
  const p = f.adj.p.toLowerCase().replace(/ые$/, "ых").replace(/ие$/, "их").replace(/ьи$/, "ьих");
  return { ru: `${p} котов`, en: `${f.adj.en} cats` };
}

