function fill(t: T3, vars: Record<string, Txt | string | number>): Txt {
  const f = (s: string, lang: "ru" | "en") =>
    s.replace(/\{(\w+)\}/g, (_, k) => {
      const v = vars[k];
      if (v === undefined) return k;
      if (typeof v === "string" || typeof v === "number") return String(v);
      return v[lang];
    });
  return { ru: f(t[0], "ru"), en: f(t[1], "en") };
}

function cap(t: Txt): Txt {
  return { ru: t.ru.charAt(0).toUpperCase() + t.ru.slice(1), en: t.en.charAt(0).toUpperCase() + t.en.slice(1) };
}

function poiPlace(p: Poi): Txt {
  switch (p.kind) {
    case "camp":
      return { ru: "лагеря в округе", en: "the camp in the area" };
    case "dungeon":
      return { ru: `входа в «${p.name.ru}»`, en: `the entrance to "${p.name.en}"` };
    case "shrine":
      return { ru: "старого святилища", en: "the old shrine" };
    case "obelisk":
      return { ru: "камня памяти", en: "the memory stone" };
    case "treasure":
      return { ru: "древних колонн", en: "the ancient pillars" };
    case "nest":
      return { ru: "мрачного логова", en: "the grim lair" };
    case "waystone":
      return { ru: "путевого камня", en: "the waystone" };
  }
}

