const REWARD_MUL: Record<Exclude<QuestKind, "story">, number> = {
  hunt: 1,
  collect: 1,
  gather: 0.8,
  deliver: 0.7,
  explore: 0.6,
  dungeon: 2.6,
  elite: 1.8,
  rescue: 1.2,
};

const townCache = new Map<string, QuestDef[]>();

export function questsForTown(gen: WorldGen, town: Town, region: Region): QuestDef[] {
  const key = `${gen.seed}|${town.id}`;
  const cached = townCache.get(key);
  if (cached) return cached;
  const rng = new Rng(hashStr(`quests|${gen.seed}|${town.id}`));
  const givers = town.npcs.filter((n) => n.role === "questgiver" || n.role === "elder");
  const level = region.level;
  const biome = BIOMES[region.biome];
  const fams = biome.families;
  const pois = region.pois;
  const out: QuestDef[] = [];
  let qi = 0;
  const neighborTowns: Town[] = [];
  for (const [dx, dz] of [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ]) {
    const r = gen.region(region.rx + dx, region.rz + dz);
    if (r.town) neighborTowns.push(r.town);
  }
  const kindsPool: Exclude<QuestKind, "story">[] = ["hunt", "collect", "gather", "explore", "hunt", "rescue", "collect", "gather"];
  if (neighborTowns.length) kindsPool.push("deliver", "deliver");
  if (pois.some((p) => p.kind === "dungeon")) kindsPool.push("dungeon", "dungeon");
  if (pois.some((p) => p.kind === "nest")) kindsPool.push("elite");
  const used = new Set<string>();
  for (const giver of givers) {
    const n = giver.role === "elder" ? 3 : 2;
    let prevId: string | null = null;
    for (let k = 0; k < n; k++) {
      let q: QuestDef | null = null;
      for (let attempt = 0; attempt < 6 && !q; attempt++) {
        const kind: Exclude<QuestKind, "story"> = giver.role === "elder" && k === n - 1 && attempt < 3 && pois.some((p) => p.kind === "dungeon") ? "dungeon" : rng.pick(kindsPool);
        const id = `${town.id}:q${qi}`;
        const cand = makeQuest(gen, rng.fork(id + ":" + attempt), id, kind, giver.id, town, region, level, fams, pois, neighborTowns);
        if (!cand) continue;
        const o = cand.objectives[0];
        const tkey = o.k === "dungeon" || o.k === "elite" ? `${o.k}:${o.poiId}` : o.k === "talk" ? `talk:${o.npcId}` : o.k === "rescue" ? `rescue:${o.poiId}` : `${cand.kind}:${cand.intro.ru}`;
        if (used.has(tkey)) continue;
        used.add(tkey);
        q = cand;
      }
      if (!q) continue;
      qi++;
      if (giver.role === "elder") {
        q.requires = prevId;
        q.chain = { step: k + 1, total: n };
        prevId = q.id;
        if (k === n - 1) {
          q.reward.skillPoints += 1;
          q.reward.item = { rarity: 3 };
        }
      }
      out.push(q);
    }
  }
  townCache.set(key, out);
  if (townCache.size > 300) townCache.delete(townCache.keys().next().value!);
  return out;
}

function makeQuest(
  gen: WorldGen,
  rng: Rng,
  id: string,
  kind: Exclude<QuestKind, "story">,
  giverId: string,
  town: Town,
  region: Region,
  level: number,
  fams: string[],
  pois: Poi[],
  neighbors: Town[],
): QuestDef | null {
  const fam = rng.pick(fams);
  const camp = pois.find((p) => p.kind === "camp");
  const anyPoi = pois.length ? rng.pick(pois) : null;
  const townArea = { x: town.x, z: town.z, r: 160 };
  let objectives: Objective[] = [];
  let vars: Record<string, Txt | string | number> = {};
  let turnIn: string | null = null;
  const count = rng.int(5, 10);
  const place = (p: Poi | null | undefined): Txt => (p ? poiPlace(p) : { ru: "окраин города", en: "the town outskirts" });
  switch (kind) {
    case "hunt": {
      const where = camp ?? anyPoi;
      const area = where ? { x: where.x, z: where.z, r: 60 } : townArea;
      objectives = [{ k: "kill", family: fam, count, area, label: { ru: `Победить: ${famPlural(fam).ru}`, en: `Defeat: ${famPlural(fam).en}` } }];
      vars = { enemies: famPlural(fam), Enemies: cap(famPlural(fam)), count, place: place(where) };
      break;
    }
    case "collect": {
      const it = rng.pick(COLLECT_ITEMS);
      const where = camp ?? anyPoi;
      objectives = [
        {
          k: "collect",
          item: it.name,
          icon: it.icon,
          count: Math.max(4, count - 2),
          family: fam,
          chance: 0.55,
          area: where ? { x: where.x, z: where.z, r: 90 } : townArea,
          label: { ru: `Добыть: ${it.name.ru}`, en: `Collect: ${it.name.en}` },
        },
      ];
      vars = { item: it.name, count: Math.max(4, count - 2), enemiesGen: famGenPl(fam), enemies: famPlural(fam), Enemies: cap(famPlural(fam)) };
      break;
    }
    case "gather": {
      const g = GATHER_BY_BIOME[region.biome] ?? GATHER_BY_BIOME.meadow;
      const where = anyPoi ?? null;
      const a = rng.next() * Math.PI * 2;
      const area = where ? { x: where.x + Math.cos(a) * 25, z: where.z + Math.sin(a) * 25, r: 18 } : { x: town.x + Math.cos(a) * 90, z: town.z + Math.sin(a) * 90, r: 18 };
      objectives = [{ k: "gather", item: g.name, icon: g.icon, count, area, label: { ru: `Собрать: ${g.name.ru}`, en: `Gather: ${g.name.en}` }, color: g.color }];
      vars = { item: g.name, count, place: place(where) };
      break;
    }
    case "deliver": {
      const t2 = rng.pick(neighbors);
      const npc = t2.npcs.find((n) => n.role === "villager" || n.role === "questgiver") ?? t2.npcs[0];
      objectives = [{ k: "talk", npcId: npc.id, townId: t2.id, at: { x: t2.x, z: t2.z, r: t2.radius }, label: { ru: `Доставить: ${npc.name.ru} (${t2.name.ru})`, en: `Deliver to ${npc.name.en} (${t2.name.en})` } }];
      vars = { npc: npc.name, town: t2.name };
      turnIn = npc.id;
      break;
    }
    case "explore": {
      const p = pois.find((x) => x.kind === "obelisk" || x.kind === "shrine" || x.kind === "waystone") ?? anyPoi;
      if (!p) return null;
      objectives = [{ k: "visit", area: { x: p.x, z: p.z, r: 10 }, label: { ru: `Разведать: ${poiName(p).ru}`, en: `Scout ${poiName(p).en}` } }];
      vars = { place: poiPlace(p) };
      break;
    }
    case "dungeon": {
      const d = pois.filter((p) => p.kind === "dungeon");
      if (!d.length) return null;
      const p = rng.pick(d);
      objectives = [{ k: "dungeon", poiId: p.id, at: { x: p.x, z: p.z, r: 8 }, label: { ru: `Одолеть: ${p.bossName!.ru}`, en: `Defeat ${p.bossName!.en}` } }];
      vars = { dungeon: p.name, boss: p.bossName! };
      break;
    }
    case "elite": {
      const p = pois.find((x) => x.kind === "nest");
      if (!p) return null;
      objectives = [{ k: "elite", poiId: p.id, at: { x: p.x, z: p.z, r: 12 }, label: { ru: `Одолеть: ${p.bossName!.ru}`, en: `Defeat ${p.bossName!.en}` } }];
      vars = { boss: p.bossName!, place: poiPlace(p) };
      break;
    }
    case "rescue": {
      const p = anyPoi;
      if (!p) return null;
      const kn = catName(rng, 0);
      const a = rng.next() * Math.PI * 2;
      objectives = [{ k: "rescue", poiId: p.id, at: { x: p.x + Math.cos(a) * 14, z: p.z + Math.sin(a) * 14, r: 4 }, kittenName: kn, label: { ru: `Найти котёнка: ${kn.ru}`, en: `Find the kitten ${kn.en}` } }];
      vars = { kitten: kn, place: poiPlace(p) };
      break;
    }
  }
  const mul = REWARD_MUL[kind];
  const title = fill(rng.pick(TITLE[kind]), {});
  const intro = fill(rng.pick(INTRO[kind]), vars);
  const done = fill(rng.pick(DONE_LINES), {});
  return {
    id,
    kind,
    giverNpcId: giverId,
    townId: town.id,
    title,
    intro,
    done,
    level,
    objectives,
    reward: {
      xp: questXp(level, mul),
      fish: Math.round(14 * priceScale(level) * mul),
      item: rng.chance(kind === "dungeon" || kind === "elite" ? 1 : 0.35) ? { rarity: kind === "dungeon" ? 3 : kind === "elite" ? 2 : 1 } : null,
      skillPoints: kind === "dungeon" ? 1 : 0,
      tome: kind === "dungeon" && rng.chance(0.25),
    },
    requires: null,
    chain: null,
    turnInNpcId: turnIn,
  };
}

export function objectiveCountText(o: Objective, progress: number): string {
  switch (o.k) {
    case "kill":
    case "collect":
    case "gather":
      return `${Math.min(progress, o.count)}/${o.count}`;
    default:
      return progress > 0 ? "✓" : "";
  }
}

export function objectiveNeeded(o: Objective): number {
  return o.k === "kill" || o.k === "collect" || o.k === "gather" ? o.count : 1;
}

export { pluralRu, ROLES };
