import { observer } from "mobx-react-lite";
import { tr } from "../../core/i18n";
import { fmtNum } from "../../core/format";
import { useStore } from "../stores";
import { Btn, Panel } from "../common";
import { objectiveCountText, objectiveNeeded } from "../../game/quests/gen";
import type { QuestDef } from "../../game/quests/types";

export const QuestView = observer(({ q, showIntro = true }: { q: QuestDef; showIntro?: boolean }) => {
  const s = useStore();
  const sess = s.session!;
  const pr = sess.quests.progress(q.id);
  const active = sess.quests.isActive(q.id);
  return (
    <div>
      {showIntro && <div className="dialog-bubble" style={{ marginBottom: 6 }}>{tr(q.intro)}</div>}
      {q.objectives.map((o, i) => {
        const done = active && (pr[i] ?? 0) >= objectiveNeeded(o);
        return (
          <div key={i} className={`obj${done ? " done" : ""}`}>
            <span>{done ? "✓" : "•"}</span>
            <span>
              {tr(o.label)} {active ? objectiveCountText(o, pr[i] ?? 0) : ""}
            </span>
          </div>
        );
      })}
      <div className="reward">
        🎁 {fmtNum(q.reward.xp)} XP · 🐟 {fmtNum(q.reward.fish)}
        {q.reward.item ? ` · ${tr({ ru: "предмет", en: "item" })}` : ""}
        {q.reward.skillPoints ? ` · +${q.reward.skillPoints} ${tr({ ru: "очк. навыков", en: "skill pts" })}` : ""}
        {q.reward.tome ? ` · 📖` : ""}
      </div>
    </div>
  );
});

export const QuestsPanel = observer(() => {
  const s = useStore();
  const sess = s.session!;
  const c = s.char!;
  void c.rev;
  const ids = sess.quests.activeIds();
  const qs = ids.map((id) => sess.quests.get(id)).filter(Boolean) as QuestDef[];
  qs.sort((a, b) => (a.kind === "story" ? -1 : b.kind === "story" ? 1 : 0));
  const tracked = c.data.quests.tracked;
  return (
    <Panel title={{ ru: `Задания (${qs.length})`, en: `Quests (${qs.length})` }} onClose={() => s.ui.close()}>
      <div className="muted" style={{ fontSize: 13, marginBottom: 8 }}>
        {tr({ ru: `Выполнено заданий: ${c.data.quests.done.length}. Задания дают старейшины и жители городов (значок «!»).`, en: `Quests completed: ${c.data.quests.done.length}. Elders and townsfolk give quests (the “!” marker).` })}
      </div>
      {qs.map((q) => (
        <div key={q.id} className={`quest${tracked === q.id ? " tracked" : ""}`}>
          <div className="row">
            <h4>
              {q.kind === "story" ? "👑 " : ""}
              {tr(q.title)} <span className="muted">· {q.level}</span>
            </h4>
            <div className="spacer" />
            {sess.quests.isComplete(q.id) && <span className="good">✓ {tr({ ru: "Сдать", en: "Turn in" })}</span>}
          </div>
          <QuestView q={q} />
          <div className="row" style={{ marginTop: 8 }}>
            {tracked !== q.id && (
              <Btn small onClick={() => {
                c.data.quests.tracked = q.id;
                c.touch();
              }}>
                📍 {tr({ ru: "Отслеживать", en: "Track" })}
              </Btn>
            )}
            {q.kind !== "story" && (
              <Btn small kind="ghost" onClick={() => sess.quests.abandon(q.id)}>
                {tr({ ru: "Отказаться", en: "Abandon" })}
              </Btn>
            )}
          </div>
        </div>
      ))}
    </Panel>
  );
});
